import { ChangeDetectionStrategy, Component, TemplateRef, computed, inject, input, output, signal, viewChild } from '@angular/core';
import { FormsModule } from '@angular/forms';
import {
  IconArrowBackUp, IconArrowLeft, IconArrowRight, IconChecklist, IconChevronDown, IconChevronUp,
  IconCircleCheck, IconCircleMinus, IconExternalLink, IconFileImport, IconFilter, IconHelpCircle, IconHistory, IconKeyboard,
  IconPaperclip, IconScissors, IconSend, IconSignature, IconTool, IconWriting, TablerIconComponent,
} from '@tabler/icons-angular';
import {
  HrmAlert, HrmButton, HrmCollapse, HrmCollapsePanel, HrmDescItem, HrmDescriptions, HrmGrid,
  HrmGridColumn, HrmInput, HrmMessageService, HrmPopover, HrmSelect, HrmStatusCell, HrmTag, HrmTextarea,
} from 'hrm-ui';
import { InsLayerBadge, InsSectionLabel, InsVarianceCell } from '../_shared';
import { InsShellStore, insKy } from '../_data/_core';
import {
  INS_KENHNOP_LABEL, INS_LO_KETQUA_LABEL, INS_LO_LABEL, INS_LO_TONE, INS_NHOM_THUTUC,
  InsKenhNop, InsKetQuaCQ, InsLo, InsLoItem, InsLoTrangThai, InsM03Store, InsPhanLoaiLoi, InsPhanLoaiTrangThai,
} from '../_data/_m03-data';
import {
  INS_DOCHACCHAN_LABEL, INS_PHANLOAI_LOI_LABEL, INS_PHANLOAI_LOI_TONE,
  INS_PHANLOAI_TRANGTHAI_LABEL, INS_PHANLOAI_TRANGTHAI_TONE, ItemRow, KENHNOP_OPTIONS, KETQUA_OPTIONS,
  KqRow, LYDO_TUCHOI_OPTIONS, M03_ITEM_COLS, M03_ITEM_MIN_WIDTH, M03_KETQUA_COLS,
  M03_KETQUA_MIN_WIDTH, buildItemRow, buildKqRow,
} from './_m03-columns';
import { InsM03LoPanel } from './m03-lo-panel';
import { InsM03RunZone } from './m03-b34';

/** VM 1 dòng bị TỪ CHỐI cho chặng ⑤ (phân loại) + ⑥ (xử lý trả về). Thuần — dựng từ item + deXuatPhanLoaiLoi
 *  (pure store getter). `duong` = đường xử lý theo NHÃN ĐÃ XÁC NHẬN (F2): chưa phân loại / nội bộ / giải trình. */
interface RejectVM {
  id: string; ten: string; sub: string; lyDo: string;
  deNhan: InsPhanLoaiLoi; doChacChanLabel: string; giaiThich: string;
  danNguon: { truong: string; minhKhai: string; coQuanGhi: string; khop: boolean }[];
  confirmedNhan: InsPhanLoaiLoi | undefined;
  activeNhan: InsPhanLoaiLoi; activeNhanLabel: string; activeTone: string;
  trangThai: InsPhanLoaiTrangThai; ttLabel: string; ttTone: string;
  chips: { nhan: InsPhanLoaiLoi; label: string; tone: string; active: boolean; goiY: boolean }[];
  duong: 'chua' | 'noi-bo' | 'giai-trinh' | 'ky-thuat';
  vaoLoSua: boolean; mocNopGoc: string;
}

/** ═════════ M03 · SC-B2 — LÔ & TỜ KHAI trong MỘT CARD GỌN (`ins-m03-lo-detail`) ═════════
 *  Re-packaging chặng ②③④ của SC-B2 thành 1 card compact: dải 6 bước inline (①Soát ②Dựng tờ khai
 *  ③Duyệt & Ký ④Nộp ⑤Import ⑥Xử lý trả về) + mỗi bước MỘT dòng tóm tắt + nút inline + expand tùy chọn.
 *  Gọi ĐÚNG store method của b2/b34 — chỉ đổi layout. Dưới card: hrm-collapse "Chi tiết lô nâng cao".
 *
 *  PHASE 2 (doc SC-B2 §9/§10/§13) đắp lên chặng ⑤⑥:
 *   • F1 phân loại lỗi thuộc về ai (nội bộ/cơ quan/kỹ thuật) — hệ ĐỀ XUẤT mock deterministic, người XÁC NHẬN;
 *     kèm dẫn nguồn "mình khai ↔ cơ quan ghi" (✓/⚠) · độ chắc chắn · [Vì sao?] popover. Đổi nhãn → emit
 *     reason {mode:'doi-nhan-loi'} (host mở modal lý do, ghi vết).
 *   • F2 chặng ⑥ rẽ theo nhãn: cơ quan/kỹ thuật → giải trình & gửi lại tại chỗ (giữ mốc nộp gốc, không tính
 *     trễ); nội bộ → 3 đường ra cũ (Sửa & chạy lại / Trả về M02 / Loại trừ).
 *   • F3 vòng 5 trạng thái dòng kết quả (mới bóc tách → đã phân loại → đang xử lý → chờ phản hồi → đã đóng).
 *   • F4 chặng ⑤ Import thay auto-fetch: [Chọn tệp phản hồi] (bóc tách demo) + [Nhập tay (văn bản giấy)].
 *  ⚠️ Điểm treo doc §17 (ngưỡng độ chắc chắn · định dạng tệp) → MOCK deterministic, gắn nhãn "đề xuất mô
 *     phỏng — người xác nhận", KHÔNG cứng hóa.
 *
 *  NAMING CONTRACT (frozen): input `loId` · output `reason` ({mode,id} → host mở reason-prompt: trả lại lô /
 *  chấp nhận cảnh báo / loại trừ dòng kết quả / ĐỔI NHÃN LỖI 'doi-nhan-loi') · output `openD02` (emit loId →
 *  host mở D02-TS viewer) · output `back` (về workspace) · output `gotoM04` (sang Theo dõi đóng).
 *  ⚠️ Zoneless + OnPush + standalone: mọi binding qua computed(); tiền/ngày = chuỗi seed; nhãn/tone = const
 *  map; KHÔNG Date.now()/Math.random() trong template/getter (mutation chỉ trong click handler qua store). */
@Component({
  selector: 'ins-m03-lo-detail',
  imports: [
    FormsModule, TablerIconComponent,
    HrmAlert, HrmButton, HrmCollapse, HrmCollapsePanel, HrmDescriptions, HrmGrid, HrmInput, HrmPopover,
    HrmSelect, HrmStatusCell, HrmTag, HrmTextarea,
    InsLayerBadge, InsSectionLabel, InsVarianceCell, InsM03LoPanel, InsM03RunZone,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (lo(); as lo) {
      <div class="ld__card">
        <!-- ═════ Header lô ═════ -->
        <div class="ld__head">
          <hrm-button size="sm" (click)="back.emit()"><tabler-icon [icon]="icBack" [size]="15" /> Danh sách lô</hrm-button>
          <span class="ld__ma">LÔ {{ lo.maLo }}</span>
          <span class="ld__ky">· {{ kyLabel() }}</span>
          <hrm-status-cell [status]="$any(loTone())" [label]="loTrangThai()" variant="badge" />
          @if (loKetQua()) { <hrm-tag color="orange" size="sm" variant="lighter">{{ loKetQua() }}</hrm-tag> }
          @if (lo.maLoGoc) { <hrm-tag color="purple" size="sm" variant="lighter">Lô sửa · gốc {{ lo.maLoGoc }} · lần nộp {{ lo.soLanNop }}</hrm-tag> }
          @if (lo.trangThai === 'bi-tra-lai' && lo.lyDoTraLai) { <span class="ld__block">Bị trả lại: {{ lo.lyDoTraLai }}</span> }
          <span class="ld__gap"></span>
          @if (d02Opened()) {
            <span class="ld__a07" [title]="a07Hint">A-07 · D02-LT chờ QĐ 366/QĐ-BHXH · tin cậy Thấp</span>
          }
          <span class="ld__cnt">{{ items().length }} item · lần nộp {{ lo.soLanNop }}</span>
        </div>

        <!-- ═════ Dải 6 bước inline (done ✓ · current đậm · upcoming mờ) ═════ -->
        <div class="ld__strip" role="list">
          @for (s of steps(); track s.n; let last = $last) {
            <span class="ld__pill" [attr.data-state]="s.state" role="listitem">
              <span class="ld__pill-idx">@if (s.state === 'done') { ✓ } @else { {{ s.n }} }</span>
              <span class="ld__pill-tx">{{ s.label }}</span>
            </span>
            @if (!last) { <span class="ld__arrow" aria-hidden="true">──▶</span> }
          }
        </div>

        <!-- ═════ ① Soát trước nộp — pre-check từng item ═════ -->
        <div class="ld__step">
          <span class="ld__step-idx" [attr.data-state]="steps()[0].state">①</span>
          <div class="ld__step-body">
            <div class="ld__row">
              <span class="ld__sum">
                <b class="ld__ok">✓ {{ soDat() }} đạt</b> ·
                <b class="ld__warn">⚠ {{ soCanhBao() }} cảnh báo</b> ·
                <b class="ld__err">✗ {{ soLoi() }} lỗi</b>
                @if (soChua()) { · <span class="ld__muted">{{ soChua() }} chưa chạy</span> }
              </span>
              <span class="ld__acts">
                <hrm-button size="sm" [disabled]="locked()" (click)="chayPreCheck()">
                  <tabler-icon [icon]="icCheck" [size]="14" /> Chạy pre-check</hrm-button>
                @if (warnPending().length) {
                  <hrm-button size="sm" (click)="chapNhan(warnPending()[0].maItem)">Chấp nhận cảnh báo ({{ warnPending().length }})</hrm-button>
                }
                <hrm-button size="sm" [disabled]="locked() || soLoi() === 0" (click)="tachLoi()">
                  <tabler-icon [icon]="icCut" [size]="14" /> Tách dòng lỗi</hrm-button>
                <button type="button" class="ld__link" (click)="showItems.set(!showItems())">
                  <tabler-icon [icon]="showItems() ? icUp : icDown" [size]="13" /> {{ showItems() ? 'Ẩn' : 'Xem' }} {{ items().length }} item</button>
                @if (soLoi() > 0) {
                  <button type="button" class="ld__link ld__link--err" (click)="xemDongLoi()">
                    <tabler-icon [icon]="icFilter" [size]="13" /> Xem {{ soLoi() }} dòng lỗi</button>
                }
              </span>
            </div>
            @if (trinhReason(); as r) { <p class="ld__block">{{ r }}</p> }
            @if (onlyLoi()) { <p class="ld__hint">Đang lọc <b>chỉ dòng Lỗi</b> · <button type="button" class="ld__link" (click)="onlyLoi.set(false)">bỏ lọc</button></p> }
            @if (showItems()) {
              <div class="ld__gridwrap">
                <hrm-grid [columns]="itemCols()" [data]="itemRows()" rowKey="id" density="compact"
                  [minWidth]="itemMinWidth" [pageSize]="6" [showPagination]="itemRows().length > 6" />
              </div>
            }
          </div>
        </div>

        <!-- ═════ ② Dựng tờ khai — mở bản D02-TS đúng mẫu (600 / 600a / 600b) ═════ -->
        <div class="ld__step">
          <span class="ld__step-idx" [attr.data-state]="steps()[1].state">②</span>
          <div class="ld__step-body">
            <div class="ld__row">
              <span class="ld__sum">Tờ khai D02-TS theo nhóm thủ tục:</span>
              <span class="ld__acts">
                @for (t of thuTucCodes(); track t) {
                  <hrm-button size="sm" (click)="xemToKhai()">{{ t }} <tabler-icon [icon]="icOpen" [size]="13" /> Xem tờ khai</hrm-button>
                }
                @if (!thuTucCodes().length) { <span class="ld__muted">Chưa có item kê khai trong lô.</span> }
              </span>
            </div>
            <p class="ld__hint">Bản D02-TS là nội dung sẽ ký & nộp — người duyệt xem trước khi ký (mở bản đúng mẫu).</p>

            <!-- Xem trước tác động lô (§6 · chỉ đọc) — quỹ lương cũ→mới→chênh theo TỪNG QUỸ, nhãn "Dự kiến nội bộ" -->
            @if (tacDong(); as t) {
              <div class="ld__tac">
                <div class="ld__tac-head">
                  <ins-section-label text="Xem trước tác động lô (chỉ đọc)" tone="muted" />
                  <ins-layer-badge layer="du-kien" />
                  <span class="ld__muted">Bộ quy tắc {{ t.ruleVersion }} · {{ t.nguon }} — không ghi vào số liệu chính thức.</span>
                </div>
                <div class="ld__funds">
                  <div class="ld__funds-head"><span>Quỹ</span><span>Quỹ lương cũ → mới · chênh lệch</span></div>
                  @for (q of tacDongRows(); track q.quy) {
                    <div class="ld__fund">
                      <span class="ld__fund-name">{{ q.quy }}</span>
                      <ins-variance-cell [expected]="q.cu" [actual]="q.moi" [diff]="q.chenh" [tone]="q.tone" layer="du-kien" />
                    </div>
                  }
                </div>
                @if (t.ghiChuCD) { <p class="ld__hint">{{ t.ghiChuCD }} — dòng CD hiển thị nhưng KHÔNG cộng vào tổng.</p> }
                @for (k of t.khongTinhDuoc; track k) { <p class="ld__warn-line">{{ k }}</p> }
              </div>
            }
          </div>
        </div>

        <!-- ═════ ③ Duyệt & Ký số — maker–checker; nội dung ký = bản đóng băng ═════ -->
        <div class="ld__step">
          <span class="ld__step-idx" [attr.data-state]="steps()[2].state">③</span>
          <div class="ld__step-body">
            <div class="ld__row">
              <span class="ld__sum">{{ signSummary() }}</span>
              <span class="ld__acts">
                <hrm-button size="sm" variant="primary" [disabled]="!!trinhReason()" (click)="trinhDuyet()">Trình duyệt</hrm-button>
                <hrm-button size="sm" [disabled]="!!duyetReason()" (click)="duyet()">
                  <tabler-icon [icon]="icApprove" [size]="14" /> Phê duyệt</hrm-button>
                <hrm-button size="sm" variant="primary" [disabled]="!!kyReason()" (click)="ky()">
                  <tabler-icon [icon]="icSign" [size]="14" /> Ký số</hrm-button>
                <hrm-button size="sm" [danger]="true" [disabled]="!traLaiDuoc()" (click)="traLai()">
                  <tabler-icon [icon]="icReturn" [size]="14" /> Trả lại</hrm-button>
              </span>
            </div>
            <!-- 7 điểm dừng: hiện lý do bị chặn (không khóa câm) -->
            @if (duyetReason(); as r) { <p class="ld__block"><b>Duyệt:</b> {{ r }}</p> }
            @if (kyReason(); as r) { <p class="ld__block"><b>Ký số:</b> {{ r }}</p> }
            @if (lo.trangThai === 'da-ky') {
              <hrm-alert type="warning" message="Sửa nội dung/tham số sau khi ký làm MẤT HIỆU LỰC chữ ký"
                description="Nội dung ký là bản đóng băng — mọi thay đổi ghi nhật ký, lô phải ký lại trước khi nộp." />
            }
          </div>
        </div>

        <!-- ═════ ④ Nộp → bằng chứng bất biến ═════ -->
        <div class="ld__step">
          <span class="ld__step-idx" [attr.data-state]="steps()[3].state">④</span>
          <div class="ld__step-body">
            <div class="ld__row">
              <span class="ld__sum">Kênh nộp:
                @if (canEditParams()) {
                  <hrm-select class="ld__sel" [ngModel]="lo.kenhNop" (ngModelChange)="setKenh($event)"
                    [options]="kenhOptions" size="sm" [allowClear]="false" [showSearch]="false" />
                } @else { <b>{{ kenhLabel() }}</b> }
              </span>
              <span class="ld__acts">
                <hrm-button size="sm" variant="primary" [disabled]="!!nopReason()" (click)="nop()">
                  <tabler-icon [icon]="icSend" [size]="14" /> Nộp</hrm-button>
                @if (bangChung()) {
                  <button type="button" class="ld__link" (click)="showEvidence.set(!showEvidence())">
                    <tabler-icon [icon]="showEvidence() ? icUp : icDown" [size]="13" /> Bằng chứng giao dịch</button>
                }
              </span>
            </div>
            @if (nopReason(); as r) { <p class="ld__block"><b>Nộp:</b> {{ r }}</p> }

            <!-- Bằng chứng giao dịch bất biến — 6 dữ kiện (expand) -->
            @if (showEvidence() && bangChung()) {
              <div class="ld__evi">
                <div class="ld__evi-head"><ins-layer-badge layer="da-giao-dich" />
                  <span class="ld__muted">6 dữ kiện bất biến — không ghi đè; idempotent mã lô + lần nộp.</span></div>
                <hrm-descriptions [items]="bangChungItems()" [column]="2" size="small" [bordered]="true" />
              </div>
            }
          </div>
        </div>

        <!-- ═════ ⑤ Import kết quả — bóc tách tệp / nhập tay + F1 phân loại lỗi ═════ -->
        <div class="ld__step">
          <span class="ld__step-idx" [attr.data-state]="steps()[4].state">⑤</span>
          <div class="ld__step-body">
            <div class="ld__row">
              <span class="ld__sum">Nhập kết quả cơ quan BHXH (bóc tách từ tệp phản hồi / văn bản giấy):</span>
              <span class="ld__acts">
                @if (chuaCoKetQua()) {
                  <hrm-button size="sm" variant="primary" [disabled]="locked()" (click)="importKetQua()">
                    <tabler-icon [icon]="icImport" [size]="14" /> Chọn tệp phản hồi</hrm-button>
                  <hrm-button size="sm" [disabled]="locked()" (click)="showManual.set(!showManual())">
                    <tabler-icon [icon]="icManual" [size]="14" /> Nhập tay (văn bản giấy)</hrm-button>
                }
                @if (soChapNhan() || soTuChoi()) {
                  <button type="button" class="ld__link" (click)="showResult.set(!showResult())">
                    <tabler-icon [icon]="showResult() ? icUp : icDown" [size]="13" /> {{ showResult() ? 'Ẩn' : 'Xem' }} lưới kết quả</button>
                }
              </span>
            </div>
            @if (chuaCoKetQua()) {
              <p class="ld__hint">Bóc tách kết quả từng item từ tệp phản hồi cổng — hoặc nhập tay khi nhận văn bản giấy (bắt buộc số văn bản + ngày). <i>Định dạng tệp import đang chờ chốt (doc §17) — bản mô phỏng.</i></p>
            }

            <!-- Nhập tay (văn bản giấy) — form nhỏ: item · số VB · ngày · kết quả (+ lý do khi từ chối) -->
            @if (showManual() && chuaCoKetQua()) {
              <div class="ld__manual">
                <div class="ld__manual-grid">
                  <label class="ld__f">
                    <span class="ld__flabel">Item chưa có kết quả</span>
                    <hrm-select [ngModel]="mItem()" (ngModelChange)="mItem.set($any($event))" [options]="nhapTayCandidates()"
                      size="sm" placeholder="Chọn item" [allowClear]="false" [showSearch]="false" />
                  </label>
                  <label class="ld__f">
                    <span class="ld__flabel">Số văn bản *</span>
                    <hrm-input [ngModel]="mSoVB()" (ngModelChange)="mSoVB.set($any($event))" placeholder="VD 1234/TB-BHXH" />
                  </label>
                  <label class="ld__f">
                    <span class="ld__flabel">Ngày văn bản *</span>
                    <hrm-input [ngModel]="mNgay()" (ngModelChange)="mNgay.set($any($event))" placeholder="dd/mm/yyyy" />
                  </label>
                  <label class="ld__f">
                    <span class="ld__flabel">Kết quả</span>
                    <hrm-select [ngModel]="mKq()" (ngModelChange)="mKq.set($any($event))" [options]="kqOptions"
                      size="sm" [allowClear]="false" [showSearch]="false" />
                  </label>
                  @if (mKq() === 'tu-choi') {
                    <label class="ld__f ld__f-wide">
                      <span class="ld__flabel">Lý do (danh mục) *</span>
                      <hrm-select [ngModel]="mLyDo()" (ngModelChange)="mLyDo.set($any($event))" [options]="lyDoOptions"
                        size="sm" placeholder="Chọn lý do từ chối" [allowClear]="false" [showSearch]="false" />
                    </label>
                  }
                </div>
                <div class="ld__manual-acts">
                  <hrm-button size="sm" variant="primary" (click)="submitNhapTay()">Ghi kết quả (nhập tay)</hrm-button>
                  <span class="ld__muted">Nhập tay BẮT BUỘC số văn bản + ngày (giữ vết văn bản giấy).</span>
                </div>
              </div>
            }

            <!-- Tổng kết + lưới kết quả -->
            @if (soChapNhan() || soTuChoi()) {
              <div class="ld__row ld__kq">
                <span class="ld__sum">KẾT QUẢ:
                  <b class="ld__ok">{{ soChapNhan() }} chấp nhận</b> ·
                  <b class="ld__err">{{ soTuChoi() }} từ chối</b> <span class="ld__muted">(lý do danh mục)</span></span>
              </div>
            }
            @if (showResult()) {
              <div class="ld__gridwrap">
                <hrm-grid [columns]="kqCols()" [data]="kqRows()" rowKey="id" density="compact"
                  [minWidth]="kqMinWidth" [pageSize]="6" [showPagination]="kqRows().length > 6" />
              </div>
            }

            <!-- F1 — Phân loại lỗi thuộc về ai (đề xuất mô phỏng, người xác nhận) -->
            @if (rejectVMs().length) {
              <div class="ld__cls-wrap">
                <ins-section-label text="Phân loại lỗi thuộc về ai — hệ đề xuất, người xác nhận" tone="attention" [count]="rejectVMs().length" />
                <p class="ld__sim"><tabler-icon [icon]="icWhy" [size]="13" /> Đề xuất mô phỏng — người xác nhận. Ngưỡng độ chắc chắn & định dạng tệp đang chờ chốt (doc §17).</p>
                @for (v of rejectVMs(); track v.id) {
                  <div class="ld__cls">
                    <div class="ld__cls-head">
                      <div class="ld__stack"><span class="ld__strong">{{ v.ten }}</span><span class="ld__muted">{{ v.sub }} · {{ v.lyDo }}</span></div>
                      <span class="ld__gap"></span>
                      <hrm-status-cell [status]="$any(v.ttTone)" [label]="v.ttLabel" variant="badge" />
                    </div>
                    <div class="ld__chips">
                      @for (c of v.chips; track c.nhan) {
                        <button type="button" class="ld__chip" [attr.data-tone]="c.tone" [attr.data-active]="c.active" [attr.data-goiy]="c.goiY" [disabled]="locked()" (click)="onChonNhan(v.id, c.nhan)">
                          <span class="ld__chip-dot"></span>{{ c.label }}@if (c.goiY) { <span class="ld__chip-hint">· đề xuất</span> }
                        </button>
                      }
                      <span class="ld__dcc">Độ chắc chắn: <b>{{ v.doChacChanLabel }}</b></span>
                      <button type="button" class="ld__link" hrmPopover [hrmPopoverContent]="v.giaiThich"
                        hrmPopoverTitle="Vì sao đề xuất nhãn này?" hrmPopoverPlacement="top" hrmPopoverTrigger="click">
                        <tabler-icon [icon]="icWhy" [size]="13" /> Vì sao?</button>
                    </div>
                    @if (v.danNguon.length) {
                      <div class="ld__gridwrap">
                        <hrm-grid [columns]="danNguonCols()" [data]="$any(v.danNguon)" rowKey="truong"
                          density="compact" [bordered]="true" [showPagination]="false"
                          [reorderable]="false" [customizable]="false" [resizable]="false" [minWidth]="dnMinWidth" />
                      </div>
                    }
                  </div>
                }
              </div>
            }
          </div>
        </div>

        <!-- ═════ ⑥ Xử lý trả về — rẽ theo nhãn đã xác nhận (F2) ═════ -->
        <div class="ld__step">
          <span class="ld__step-idx" [attr.data-state]="steps()[5].state">⑥</span>
          <div class="ld__step-body">
            @if (rejectVMs().length) {
              <ins-section-label text="Xử lý hồ sơ trả về — rẽ theo nhãn đã xác nhận" tone="critical" [count]="rejectVMs().length" />
              @for (v of rejectVMs(); track v.id) {
                <div class="ld__rcard">
                  <div class="ld__cls-head">
                    <div class="ld__stack"><span class="ld__strong">{{ v.ten }}</span><span class="ld__muted">{{ v.sub }} · {{ v.lyDo }}</span></div>
                    <span class="ld__gap"></span>
                    <hrm-tag [color]="$any(insToNzColor(v.activeTone))" size="sm" variant="lighter">{{ v.activeNhanLabel }}</hrm-tag>
                    <hrm-status-cell [status]="$any(v.ttTone)" [label]="v.ttLabel" variant="badge" />
                  </div>
                  @switch (v.duong) {
                    @case ('chua') {
                      <p class="ld__hint">Chưa phân loại — xác nhận nhãn ở chặng ⑤ trước khi chọn đường xử lý.</p>
                    }
                    @case ('noi-bo') {
                      @if (v.vaoLoSua) { <span class="ld__muted">Đã đưa vào lô sửa — đi lại đủ B2+B3.</span> }
                      @else {
                        <span class="ld__acts">
                          <hrm-button size="sm" [disabled]="!!loSuaReason()" (click)="taoLoSua()">
                            <tabler-icon [icon]="icFix" [size]="14" /> Sửa & chạy lại</hrm-button>
                          <hrm-button size="sm" [disabled]="locked()" (click)="traVe02()"><tabler-icon [icon]="icReturn" [size]="14" /> Trả về M02</hrm-button>
                          <hrm-button size="sm" [danger]="true" [disabled]="locked()" (click)="loaiTru(v.id)"><tabler-icon [icon]="icExclude" [size]="14" /> Loại trừ</hrm-button>
                        </span>
                      }
                    }
                    @case ('giai-trinh') {
                      @switch (v.trangThai) {
                        @case ('cho-phan-hoi') {
                          <p class="ld__giaitrinh-sent"><tabler-icon [icon]="icSend" [size]="13" /> Đã giải trình & gửi lại · <b>giữ mốc nộp gốc {{ v.mocNopGoc }}</b> · không tính trễ · chờ phản hồi cơ quan.</p>
                        }
                        @case ('dang-xu-ly') {
                          <div class="ld__giaitrinh">
                            <hrm-textarea [ngModel]="gtOf(v.id)" (ngModelChange)="setGt(v.id, $any($event))"
                              placeholder="Nội dung giải trình gửi cơ quan (căn cứ dẫn nguồn mình khai ↔ cơ quan ghi)…" [minRows]="2" />
                            <div class="ld__gt-acts">
                              <hrm-button size="sm" [disabled]="locked()" (click)="toggleDinhKem(v.id)">
                                <tabler-icon [icon]="icAttach" [size]="14" /> Đính kèm bằng chứng@if (dinhKemOf(v.id)) { <span class="ld__ok"> ✓</span> }</hrm-button>
                              <span class="ld__keepmoc">Giữ mốc nộp gốc · không tính trễ</span>
                              <span class="ld__gap"></span>
                              <hrm-button size="sm" variant="primary" [disabled]="locked()" (click)="guiLai(v.id)">
                                <tabler-icon [icon]="icSend" [size]="14" /> Gửi lại</hrm-button>
                            </div>
                          </div>
                        }
                        @default {
                          <div class="ld__gt-start">
                            <span class="ld__muted">{{ v.activeNhanLabel }} → giải trình & gửi lại tại chỗ (giữ mốc nộp gốc, không tính trễ).</span>
                            <hrm-button size="sm" [disabled]="locked()" (click)="batDau(v.id)"><tabler-icon [icon]="icWrite" [size]="14" /> Soạn giải trình</hrm-button>
                          </div>
                        }
                      }
                    }
                    @case ('ky-thuat') {
                      @switch (v.trangThai) {
                        @case ('cho-phan-hoi') {
                          <p class="ld__giaitrinh-sent"><tabler-icon [icon]="icSend" [size]="13" /> Đã ký lại / sửa định dạng & nộp lại · <b>giữ mốc nộp gốc {{ v.mocNopGoc }}</b> · không tính trễ · chờ phản hồi cơ quan.</p>
                        }
                        @case ('dang-xu-ly') {
                          <div class="ld__giaitrinh">
                            <span class="ld__muted">Lỗi kỹ thuật (chữ ký / định dạng tệp / cổng) — ký lại hoặc sửa định dạng tệp rồi nộp lại, giữ mốc nộp gốc.</span>
                            <div class="ld__gt-acts">
                              <hrm-button size="sm" [disabled]="locked()" (click)="kyThuatBuoc('Ký lại chữ ký')"><tabler-icon [icon]="icSign" [size]="14" /> Ký lại</hrm-button>
                              <hrm-button size="sm" [disabled]="locked()" (click)="kyThuatBuoc('Sửa định dạng tệp')"><tabler-icon [icon]="icFix" [size]="14" /> Sửa định dạng tệp</hrm-button>
                              <span class="ld__keepmoc">Giữ mốc nộp gốc · không tính trễ</span>
                              <span class="ld__gap"></span>
                              <hrm-button size="sm" variant="primary" [disabled]="locked()" (click)="nopLaiKyThuat(v.id)"><tabler-icon [icon]="icSend" [size]="14" /> Nộp lại</hrm-button>
                            </div>
                          </div>
                        }
                        @default {
                          <div class="ld__gt-start">
                            <span class="ld__muted">{{ v.activeNhanLabel }} → ký lại / sửa định dạng tệp rồi nộp lại (giữ mốc nộp gốc, không tính trễ).</span>
                            <hrm-button size="sm" [disabled]="locked()" (click)="batDau(v.id)"><tabler-icon [icon]="icFix" [size]="14" /> Bắt đầu xử lý kỹ thuật</hrm-button>
                          </div>
                        }
                      }
                    }
                  }
                </div>
              }
              @if (loSuaReason(); as r) { <p class="ld__block">{{ r }}</p> }
            } @else {
              <p class="ld__muted">Chưa có hồ sơ trả về — vòng xử lý mở khi cơ quan từ chối dòng nào đó.</p>
            }

            @if (daNop()) {
              <div class="ld__m04">
                <hrm-button size="sm" variant="primary" (click)="gotoM04.emit()">
                  <tabler-icon [icon]="icM04" [size]="15" /> Chuyển sang Theo dõi đóng (M04)</hrm-button>
                <span class="ld__muted">Đối soát C12-TS · lãi chậm đóng — ngoài màn Kê khai.</span>
              </div>
            }
          </div>
        </div>
      </div>

      <!-- ═════ Dưới card — hai panel collapse: chi tiết lô nâng cao · kết quả xử lý lô (chạy nền) ═════ -->
      <hrm-collapse class="ld__adv">
        <hrm-collapse-panel [active]="true" header="Chi tiết lô nâng cao (định danh · item · hồi tố · tạm dừng HT-TT)">
          <ins-m03-lo-panel [loId]="lo.maLo" (reason)="reason.emit($event)" />
        </hrm-collapse-panel>
        <hrm-collapse-panel header="Kết quả xử lý lô — lần chạy nền + dòng lỗi (rời màn quay lại vẫn xem)">
          <ins-m03-run-zone (reason)="reason.emit($event)" />
        </hrm-collapse-panel>
      </hrm-collapse>
    } @else {
      <p class="ld__muted">Không tìm thấy lô — quay lại workspace để chọn lô khác.</p>
    }

    <!-- ═════ Cell templates lưới ITEM (chặng ①) ═════ -->
    <ng-template #itTen let-row>
      <div class="ld__stack"><span class="ld__strong">{{ $any(row).ten }}</span><span class="ld__muted">{{ $any(row).sub }}</span></div>
    </ng-template>
    <ng-template #itSuKien let-row>
      <div class="ld__stack"><span>{{ $any(row).suKien }}</span><span class="ld__muted">{{ $any(row).nguon }}</span></div>
    </ng-template>
    <ng-template #itPa let-row>
      @if ($any(row).paText) { <span>{{ $any(row).paText }}</span> } @else { <span class="ld__warn">Thiếu mã phương án</span> }
    </ng-template>
    <ng-template #itLuong let-row>
      @if ($any(row).thieuLuong) { <span class="ld__warn">không tính được</span> } @else { <span class="ld__num">{{ $any(row).luong }}</span> }
    </ng-template>
    <ng-template #itPre let-row>
      <div class="ld__stack">
        <hrm-status-cell [status]="$any(row).preTone" [label]="$any(row).preLabel" variant="badge" />
        @if ($any(row).daChapNhanCanhBao) { <span class="ld__ok" [title]="$any(row).chapNhanBoi">đã chấp nhận (override)</span> }
      </div>
    </ng-template>
    <ng-template #itViPham let-row>
      @if ($any(row).viPham.length) {
        <div class="ld__stack">@for (v of $any(row).viPham; track v) { <span class="ld__vipham">{{ v }}</span> }</div>
      } @else { <span class="ld__muted">—</span> }
    </ng-template>
    <ng-template #itTrangThai let-row>
      <hrm-status-cell [status]="$any(row).trangThaiTone" [label]="$any(row).trangThaiLabel" variant="badge" />
    </ng-template>
    <ng-template #itAct let-row>
      @if ($any(row).canChapNhan) { <hrm-button size="sm" [disabled]="locked()" (click)="chapNhan($any(row).id)">Chấp nhận cảnh báo</hrm-button> }
    </ng-template>

    <!-- ═════ Cell templates lưới KẾT QUẢ (chặng ⑤) — chỉ đọc ═════ -->
    <ng-template #kqTen let-row>
      <div class="ld__stack"><span class="ld__strong">{{ $any(row).ten }}</span><span class="ld__muted">{{ $any(row).sub }}</span></div>
    </ng-template>
    <ng-template #kqSuKien let-row>
      <span>{{ $any(row).suKien }}</span>
    </ng-template>
    <ng-template #kqNop let-row>
      @if ($any(row).nopLabel === 'chưa nộp') { <span class="ld__muted">chưa nộp</span> } @else { <span>{{ $any(row).nopLabel }}</span> }
    </ng-template>
    <ng-template #kqKetQua let-row>
      <div class="ld__stack">
        <hrm-status-cell [status]="$any(row).kqTone" [label]="$any(row).kqLabel" variant="badge" />
        @if ($any(row).vaoLoSua) { <span class="ld__muted">→ đã đưa vào lô sửa</span> }
      </div>
    </ng-template>
    <ng-template #kqLyDo let-row>
      @if ($any(row).lyDo) { <span class="ld__vipham">{{ $any(row).lyDo }}</span> } @else { <span class="ld__muted">—</span> }
    </ng-template>
    <ng-template #kqPhienBan let-row>
      <span class="ld__muted">{{ $any(row).phienBan }}</span>
      @if ($any(row).coLichSu) {
        · <button type="button" class="ld__link" (click)="xemBanCu($any(row).id)"><tabler-icon [icon]="icHistory" [size]="12" /> Xem bản cũ</button>
      }
    </ng-template>

    <!-- ═════ Cell cờ đối chiếu bảng dẫn nguồn "mình khai ↔ cơ quan ghi" (C1 · hrm-grid) ═════ -->
    <ng-template #dnFlag let-d>
      <span class="ld__dn-flag">@if ($any(d).khop) { <span class="ld__ok">✓ khớp</span> } @else { <span class="ld__warn">⚠ lệch</span> }</span>
    </ng-template>
  `,
  host: { class: 'ins-m03-lo-detail' },
  styles: [`
    :host { display: flex; flex-direction: column; gap: var(--space-3); }
    tabler-icon { display: inline-flex; align-items: center; flex: none; }

    .ld__card { display: flex; flex-direction: column; gap: var(--space-2-5); padding: var(--space-3) var(--space-3-5);
      border: 1px solid var(--border-sub); border-radius: var(--radius-lg); background: var(--bg-surface); }

    /* header */
    .ld__head { display: flex; align-items: center; gap: var(--space-2); flex-wrap: wrap; }
    :host ::ng-deep .ld__head .ant-tag { margin: 0; }
    .ld__ma { font-family: var(--font-mono, monospace); font-size: var(--fs-13); font-weight: 700; color: var(--text-strong); }
    .ld__ky { font-size: var(--fs-13); color: var(--text-sub); }
    .ld__gap { flex: 1; }
    .ld__cnt { font-size: var(--fs-12); color: var(--text-sub); white-space: nowrap; }
    .ld__a07 { font-size: var(--fs-11); font-weight: 500; color: var(--warning-text); background: var(--warning-bg);
      border: 1px dashed var(--warning-base, var(--warning-text)); border-radius: var(--radius-full); padding: var(--space-0-5) var(--space-2-5); cursor: help; white-space: nowrap; }

    /* dải 6 bước inline */
    .ld__strip { display: flex; align-items: center; gap: var(--space-1-5); flex-wrap: wrap; padding: var(--space-1) 0 var(--space-1-5);
      border-bottom: 1px solid var(--border-soft); }
    .ld__pill { display: inline-flex; align-items: center; gap: var(--space-1-5); padding: var(--space-1) var(--space-2-5); border-radius: var(--radius-full);
      border: 1px solid var(--border-soft); background: var(--bg-surface); }
    .ld__pill-idx { display: grid; place-items: center; width: 18px; height: 18px; border-radius: var(--radius-full);
      font-size: var(--fs-11); font-weight: 700; border: 1.5px solid var(--border-input); color: var(--text-sub); }
    .ld__pill-tx { font-size: var(--fs-12); font-weight: 600; color: var(--text-sub); }
    .ld__pill[data-state='current'] { border-color: var(--primary-base); }
    .ld__pill[data-state='current'] .ld__pill-idx { border-color: var(--primary-base); color: var(--primary-base); }
    .ld__pill[data-state='current'] .ld__pill-tx { color: var(--text-strong); }
    .ld__pill[data-state='done'] .ld__pill-idx { border-color: var(--success-base); color: var(--success-text); background: var(--success-bg); }
    .ld__pill[data-state='done'] .ld__pill-tx { color: var(--text-body); }
    .ld__arrow { color: var(--text-soft); font-size: var(--fs-12); }

    /* mỗi bước = 1 dòng tóm tắt + nút inline + expand */
    .ld__step { display: flex; gap: var(--space-2-5); padding-top: var(--space-2); border-top: 1px solid var(--border-soft); }
    .ld__step:first-of-type { border-top: 0; padding-top: var(--space-0-5); }
    .ld__step-idx { flex: none; width: 22px; height: 22px; display: grid; place-items: center; margin-top: var(--space-0-5);
      border-radius: var(--radius-full); font-size: var(--fs-12); font-weight: 700; border: 1.5px solid var(--border-input); color: var(--text-sub); }
    .ld__step-idx[data-state='current'] { border-color: var(--primary-base); color: var(--primary-base); }
    .ld__step-idx[data-state='done'] { border-color: var(--success-base); color: var(--success-text); background: var(--success-bg); }
    .ld__step-body { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: var(--space-1-5); }
    .ld__row { display: flex; align-items: center; gap: var(--space-2-5); flex-wrap: wrap; justify-content: space-between; }
    .ld__kq { padding-top: var(--space-0-5); }
    .ld__sum { font-size: var(--fs-13); color: var(--text-body); display: inline-flex; align-items: center; gap: var(--space-1-5); flex-wrap: wrap; }
    .ld__acts { display: flex; align-items: center; gap: var(--space-1-5); flex-wrap: wrap; }
    .ld__sel { display: inline-block; width: 150px; }

    .ld__ok { color: var(--success-text); font-weight: 600; }
    .ld__warn { color: var(--warning-text); font-weight: 600; }
    .ld__err { color: var(--error-text); font-weight: 600; }
    .ld__num { font-variant-numeric: tabular-nums; font-weight: 600; color: var(--text-strong); }
    .ld__muted { font-size: var(--fs-12); color: var(--text-sub); }
    .ld__strong { color: var(--text-strong); font-weight: 500; }
    .ld__hint { margin: 0; font-size: var(--fs-11); color: var(--text-soft); }

    /* ② Xem trước tác động lô (chỉ đọc) */
    .ld__tac { display: flex; flex-direction: column; gap: var(--space-2); padding-top: var(--space-1); }
    .ld__tac-head { display: flex; align-items: center; gap: var(--space-2); flex-wrap: wrap; }
    .ld__funds { display: flex; flex-direction: column; border: 1px solid var(--border-soft); border-radius: var(--radius-md); overflow: hidden; }
    .ld__funds-head { display: grid; grid-template-columns: 200px 1fr; gap: var(--space-3); padding: var(--space-1-5) var(--space-3);
      background: var(--bg-surface-subtle); font-size: var(--fs-12); font-weight: 600; color: var(--text-sub); }
    .ld__fund { display: grid; grid-template-columns: 200px 1fr; gap: var(--space-3); align-items: center; padding: var(--space-1-5) var(--space-3); border-top: 1px solid var(--border-soft); }
    .ld__fund-name { font-size: var(--fs-13); color: var(--text-body); font-weight: 500; }
    .ld__warn-line { margin: 0; font-size: var(--fs-12); color: var(--warning-text); font-weight: 500; }
    .ld__block { margin: 0; font-size: var(--fs-12); color: var(--error-text); }
    .ld__link { display: inline-flex; align-items: center; gap: var(--space-1); border: 0; background: none; padding: 0; cursor: pointer;
      font: inherit; font-size: var(--fs-12); font-weight: 600; color: var(--primary-base); }
    .ld__link:hover { text-decoration: underline; }
    .ld__link--err { color: var(--error-text); }
    .ld__gridwrap { overflow-x: auto; }
    .ld__vipham { font-size: var(--fs-12); color: var(--text-body); }
    .ld__stack { display: flex; flex-direction: column; gap: var(--space-0-5); min-width: 0; align-items: flex-start; }

    .ld__evi { display: flex; flex-direction: column; gap: var(--space-1-5); padding: var(--space-2) var(--space-2-5); border: 1px solid var(--border-soft); border-radius: var(--radius-md); }
    .ld__evi-head { display: flex; align-items: center; gap: var(--space-2); flex-wrap: wrap; }

    /* ⑤ nhập tay — form nhỏ */
    .ld__manual { display: flex; flex-direction: column; gap: var(--space-2); padding: var(--space-2-5) var(--space-3);
      border: 1px solid var(--border-soft); border-radius: var(--radius-md); background: var(--bg-surface-subtle); }
    .ld__manual-grid { display: flex; flex-wrap: wrap; gap: var(--space-2-5); }
    .ld__f { display: flex; flex-direction: column; gap: var(--space-1); min-width: 150px; flex: 1 1 150px; }
    .ld__f-wide { flex: 1 1 260px; }
    .ld__flabel { font-size: var(--fs-11); font-weight: 600; color: var(--text-sub); }
    .ld__manual-acts { display: flex; align-items: center; gap: var(--space-2); flex-wrap: wrap; }

    /* ⑤ F1 — phân loại lỗi */
    .ld__cls-wrap { display: flex; flex-direction: column; gap: var(--space-2); padding-top: var(--space-1-5); }
    .ld__sim { margin: 0; display: inline-flex; align-items: center; gap: var(--space-1); font-size: var(--fs-11); font-style: italic;
      color: var(--warning-text); }
    .ld__cls { display: flex; flex-direction: column; gap: var(--space-2); padding: var(--space-2) var(--space-2-5);
      border: 1px solid var(--border-soft); border-radius: var(--radius-md); background: var(--bg-surface); }
    .ld__cls-head { display: flex; align-items: center; gap: var(--space-2); flex-wrap: wrap; }
    .ld__chips { display: flex; align-items: center; gap: var(--space-2); flex-wrap: wrap; }
    .ld__chip { display: inline-flex; align-items: center; gap: var(--space-1-5); padding: var(--space-1) var(--space-3); cursor: pointer; font: inherit;
      font-size: var(--fs-12); font-weight: 600; color: var(--text-sub); background: var(--bg-surface);
      border: 1px solid var(--border-input); border-radius: var(--radius-full); }
    .ld__chip:hover { border-color: var(--primary-base); }
    .ld__chip-dot { width: 8px; height: 8px; border-radius: var(--radius-full); background: var(--text-soft); flex: none; }
    .ld__chip[data-tone='warning'] .ld__chip-dot { background: var(--warning-base); }
    .ld__chip[data-tone='info'] .ld__chip-dot { background: var(--info-base); }
    .ld__chip[data-tone='processing'] .ld__chip-dot { background: var(--primary-base); }
    .ld__chip[data-active='true'] { color: var(--text-on-primary); background: var(--primary-base); border-color: var(--primary-base); }
    .ld__chip[data-active='true'] .ld__chip-dot { background: var(--text-on-primary); }
    /* Chip đề xuất (chưa chốt): viền nét đứt primary — phân biệt với chip đã chốt (filled). */
    .ld__chip[data-goiy='true'] { border-style: dashed; border-color: var(--primary-base); color: var(--primary-base); }
    .ld__chip-hint { font-weight: 500; opacity: 0.85; }
    .ld__dcc { font-size: var(--fs-12); color: var(--text-sub); }
    /* Bảng dẫn nguồn "mình khai ↔ cơ quan ghi" (C1) = hrm-grid compact; cell cờ ✓/⚠ dùng token qua .ld__ok/.ld__warn. */
    .ld__dn-flag { white-space: nowrap; }

    /* ⑥ xử lý trả về */
    .ld__rcard { display: flex; flex-direction: column; gap: var(--space-1-5); padding: var(--space-2) var(--space-2-5);
      border: 1px solid var(--border-soft); border-radius: var(--radius-md); background: var(--bg-surface-subtle); }
    .ld__giaitrinh { display: flex; flex-direction: column; gap: var(--space-1-5); }
    .ld__gt-acts { display: flex; align-items: center; gap: var(--space-2); flex-wrap: wrap; }
    .ld__gt-start { display: flex; align-items: center; gap: var(--space-2); flex-wrap: wrap; }
    .ld__keepmoc { font-size: var(--fs-11); font-weight: 600; color: var(--success-text); background: var(--success-bg);
      border-radius: var(--radius-full); padding: var(--space-0-5) var(--space-2-5); }
    .ld__giaitrinh-sent { margin: 0; display: inline-flex; align-items: center; gap: var(--space-1-5); font-size: var(--fs-12); color: var(--info-text); }

    .ld__m04 { display: flex; align-items: center; gap: var(--space-2); flex-wrap: wrap; padding-top: var(--space-1-5); border-top: 1px solid var(--border-soft); }
    .ld__adv { display: block; }
    :host ::ng-deep .ld__adv ins-m03-run-zone { display: block; margin-top: var(--space-2); }
  `],
})
export class InsM03LoDetail {
  protected readonly store = inject(InsM03Store);
  private readonly shell = inject(InsShellStore);
  private readonly msg = inject(HrmMessageService);

  /** Host sở hữu lô đang mở → truyền xuống. */
  readonly loId = input.required<string>();
  /** Hành động BẮT BUỘC LÝ DO → host mở reason-prompt (trả lại lô / chấp nhận cảnh báo / loại trừ kết quả /
   *  ĐỔI NHÃN LỖI 'doi-nhan-loi' — F1). Với 'doi-nhan-loi', id = `${itemId}|${nhanMoi}` (host tách). */
  readonly reason = output<{ mode: string; id: string }>();
  /** "Xem tờ khai" → host mở ins-m03-d02-viewer với loId. */
  readonly openD02 = output<string>();
  /** Quay lại workspace lập tờ khai. */
  readonly back = output<void>();
  /** Sau khi nộp → sang Theo dõi đóng (M04). */
  readonly gotoM04 = output<void>();

  protected readonly icBack = IconArrowLeft;
  protected readonly icCheck = IconChecklist;
  protected readonly icCut = IconScissors;
  protected readonly icFilter = IconFilter;
  protected readonly icHistory = IconHistory;
  protected readonly icOpen = IconExternalLink;
  protected readonly icApprove = IconCircleCheck;
  protected readonly icSign = IconSignature;
  protected readonly icReturn = IconArrowBackUp;
  protected readonly icSend = IconSend;
  protected readonly icFix = IconTool;
  protected readonly icExclude = IconCircleMinus;
  protected readonly icM04 = IconArrowRight;
  protected readonly icDown = IconChevronDown;
  protected readonly icUp = IconChevronUp;
  protected readonly icImport = IconFileImport;
  protected readonly icManual = IconKeyboard;
  protected readonly icWhy = IconHelpCircle;
  protected readonly icAttach = IconPaperclip;
  protected readonly icWrite = IconWriting;
  protected readonly kenhOptions = KENHNOP_OPTIONS;
  protected readonly kqOptions = KETQUA_OPTIONS;
  protected readonly lyDoOptions = LYDO_TUCHOI_OPTIONS;
  protected readonly itemMinWidth = M03_ITEM_MIN_WIDTH;
  protected readonly kqMinWidth = M03_KETQUA_MIN_WIDTH;
  /** Bảng dẫn nguồn (C1) — giữ ngưỡng cuộn ngang cũ (min-width 360px trước khi chuyển sang hrm-grid). */
  protected readonly dnMinWidth = '360px';
  protected readonly a07Hint =
    'Sơ đồ cột khối kê khai D02-LT chờ đối chiếu nguyên văn phụ lục QĐ 366/QĐ-BHXH — bản tham chiếu.';

  /* Expand toggles + A-07 (bật khi mở D02 viewer). */
  readonly showItems = signal(false);
  readonly showEvidence = signal(false);
  readonly showResult = signal(false);
  readonly showManual = signal(false);
  readonly d02Opened = signal(false);

  /* ── Form nhập tay (văn bản giấy) ── */
  readonly mItem = signal('');
  readonly mSoVB = signal('');
  readonly mNgay = signal('');
  readonly mKq = signal<InsKetQuaCQ>('chap-nhan');
  readonly mLyDo = signal('');

  /* ── Giải trình (F2) — model + đính kèm mock theo id item ── */
  readonly giaiTrinhText = signal<Record<string, string>>({});
  readonly dinhKem = signal<Record<string, boolean>>({});
  protected gtOf(id: string): string { return this.giaiTrinhText()[id] ?? ''; }
  protected setGt(id: string, v: string): void { this.giaiTrinhText.update((m) => ({ ...m, [id]: v })); }
  protected dinhKemOf(id: string): boolean { return !!this.dinhKem()[id]; }

  /* ── VM lô ── */
  protected readonly lo = computed<InsLo | null>(() => this.store.lo(this.loId()) ?? null);
  protected readonly locked = computed(() => this.store.kyLocked());
  protected readonly items = computed<InsLoItem[]>(() => this.store.itemsOfLo(this.loId()));
  protected readonly kyLabel = computed(() => { const l = this.lo(); return l ? (insKy(l.ky)?.label ?? l.ky) : ''; });
  protected readonly loTrangThai = computed(() => { const l = this.lo(); return l ? INS_LO_LABEL[l.trangThai] : ''; });
  protected readonly loTone = computed(() => { const l = this.lo(); return l ? INS_LO_TONE[l.trangThai] : 'neutral'; });
  protected readonly loKetQua = computed(() => { const l = this.lo(); return l?.ketQuaTongHop ? INS_LO_KETQUA_LABEL[l.ketQuaTongHop] : ''; });

  /* ── ① pre-check counts ── */
  protected readonly soDat = computed(() => this.items().filter((i) => i.ketQuaPreCheck === 'dat').length);
  protected readonly soCanhBao = computed(() => this.items().filter((i) => i.ketQuaPreCheck === 'canh-bao').length);
  protected readonly soLoi = computed(() => this.items().filter((i) => i.ketQuaPreCheck === 'loi').length);
  protected readonly soChua = computed(() => this.items().filter((i) => i.ketQuaPreCheck === null).length);
  protected readonly warnPending = computed(() => this.items().filter((i) => i.ketQuaPreCheck === 'canh-bao' && !i.canhBaoChapNhan));
  /** Lọc nhanh chỉ dòng Lỗi (§5 "Xem N dòng lỗi") — bật qua xemDongLoi(). */
  readonly onlyLoi = signal(false);
  protected readonly itemRows = computed<ItemRow[]>(() =>
    (this.onlyLoi() ? this.items().filter((i) => i.ketQuaPreCheck === 'loi') : this.items()).map(buildItemRow));

  /* ── ② mã thủ tục có trong lô (600 / 600a / 600b) ── */
  protected readonly thuTucCodes = computed<string[]>(() => {
    const set = new Set<string>();
    for (const it of this.items()) {
      const nhom = this.store.nhomCuaItem(it);
      const ma = INS_NHOM_THUTUC[nhom];
      if (ma !== '—') set.add(ma);
    }
    return [...set].sort();
  });

  /* ── ② Xem trước tác động lô (§6 · chỉ đọc — quỹ cũ→mới→chênh; null khi lô không đủ điều kiện) ── */
  protected readonly tacDong = computed(() => this.store.tacDong(this.loId()));
  protected readonly tacDongRows = computed<{ quy: string; cu: string; moi: string; chenh: string; tone: 'up' | 'down' | 'zero' }[]>(() => {
    const t = this.tacDong();
    return t ? t.quy.map((q) => ({ ...q, tone: toneCuaChenh(q.chenh) })) : [];
  });

  /* ── ③ điểm dừng (disabled-có-lý-do) + tóm tắt chữ ký ── */
  protected readonly trinhReason = computed(() => this.store.trinhDuyetReason(this.loId()));
  protected readonly duyetReason = computed(() => this.store.duyetReason(this.loId()));
  protected readonly kyReason = computed(() => this.store.kyReason(this.loId()));
  protected readonly traLaiDuoc = computed(() => {
    const t = this.lo()?.trangThai;
    return !this.locked() && (t === 'cho-duyet' || t === 'da-duyet');
  });
  protected readonly signSummary = computed(() => {
    const l = this.lo();
    if (!l) return '';
    if (l.chuKyHieuLuc === false) return 'Chữ ký MẤT HIỆU LỰC (đã sửa sau ký) — cần ký lại.';
    if (l.nguoiKy) return `Đã ký — ${l.nguoiKy} · ${l.thoiDiemKy} · bản đóng băng ${l.noiDungDongBang ?? ''}`;
    return 'Nội dung ký = bản đóng băng; sửa sau ký → phải ký lại.';
  });

  /* ── ④ tham số kênh + nộp + bằng chứng ── */
  protected readonly canEditParams = computed(() => {
    const l = this.lo();
    if (!l || this.locked()) return false;
    return LO_CHUA_NOP.has(l.trangThai);
  });
  protected readonly kenhLabel = computed(() => { const l = this.lo(); return l ? INS_KENHNOP_LABEL[l.kenhNop] : ''; });
  protected readonly nopReason = computed(() => this.store.nopReason(this.loId()));
  protected readonly daNop = computed(() => {
    const t = this.lo()?.trangThai;
    return t === 'da-nop' || t === 'co-ket-qua' || t === 'dang-gui';
  });
  protected readonly chuaCoKetQua = computed(() => {
    const t = this.lo()?.trangThai;
    return t === 'da-nop' || t === 'dang-gui';
  });
  protected readonly bangChung = computed(() => {
    const l = this.lo();
    return l && l.bangChung.length ? l.bangChung[l.bangChung.length - 1] : null;
  });
  protected readonly bangChungItems = computed<HrmDescItem[]>(() => {
    const bc = this.bangChung();
    if (!bc) return [];
    return [
      { label: 'Mã giao dịch', value: bc.maGD },
      { label: 'Thời điểm', value: bc.thoiDiem },
      { label: 'Payload', value: bc.payload },
      { label: 'Phiên bản biểu mẫu', value: bc.phienBanBM },
      { label: 'Chữ ký', value: bc.chuKy },
      { label: 'Phản hồi cơ quan', value: bc.phanHoi },
    ];
  });

  /* ── ⑤ kết quả ── */
  protected readonly soChapNhan = computed(() => this.items().filter((i) => i.ketQuaCQ === 'chap-nhan').length);
  protected readonly soTuChoi = computed(() => this.items().filter((i) => i.ketQuaCQ === 'tu-choi').length);
  protected readonly kqRows = computed<KqRow[]>(() => this.items().map(buildKqRow));
  protected readonly loSuaReason = computed(() => this.store.taoLoSuaReason(this.loId()));
  /** Ứng viên nhập tay: item đã nộp nhưng chưa có kết quả cơ quan. */
  protected readonly nhapTayCandidates = computed(() =>
    this.items().filter((i) => i.coDaNop && i.ketQuaCQ === null).map((i) => {
      const r = buildKqRow(i);
      return { value: i.maItem, label: `${r.ten} · ${i.maItem}` };
    }));

  /* ── ⑤/⑥ F1/F2/F3 — dòng bị từ chối: đề xuất phân loại + vòng xử lý ── */
  protected readonly rejectVMs = computed<RejectVM[]>(() =>
    this.items()
      .filter((i) => i.ketQuaCQ === 'tu-choi' && (i.trangThai === 'bi-tu-choi' || i.trangThai === 'vao-lo-sua'))
      .map((it) => this.buildRejectVM(it)));
  /** True khi còn dòng từ chối CHƯA đóng (điều khiển chặng hiện hành ⑤/⑥). */
  protected readonly rejectedOpen = computed(() => this.rejectVMs().some((v) => v.trangThai !== 'da-dong'));

  private buildRejectVM(it: InsLoItem): RejectVM {
    const r = buildKqRow(it);
    const de = this.store.deXuatPhanLoaiLoi(it.maItem);
    const deNhan: InsPhanLoaiLoi = de?.nhan ?? 'co-quan';
    const confirmedNhan = it.phanLoaiLoi;
    const activeNhan = confirmedNhan ?? deNhan;
    const tt: InsPhanLoaiTrangThai = it.phanLoaiTrangThai ?? 'moi-boc-tach';
    const order: InsPhanLoaiLoi[] = ['noi-bo', 'co-quan', 'ky-thuat'];
    const chips = order.map((n) => ({
      nhan: n, label: INS_PHANLOAI_LOI_LABEL[n], tone: INS_PHANLOAI_LOI_TONE[n],
      active: n === confirmedNhan, goiY: !confirmedNhan && n === deNhan,
    }));
    const duong: RejectVM['duong'] = !confirmedNhan ? 'chua'
      : confirmedNhan === 'noi-bo' ? 'noi-bo' : confirmedNhan === 'co-quan' ? 'giai-trinh' : 'ky-thuat';
    return {
      id: it.maItem, ten: r.ten, sub: r.sub, lyDo: r.lyDo,
      deNhan, doChacChanLabel: de ? INS_DOCHACCHAN_LABEL[de.doChacChan] : '—',
      giaiThich: de?.giaiThich ?? '', danNguon: de?.danNguon ?? [],
      confirmedNhan, activeNhan, activeNhanLabel: INS_PHANLOAI_LOI_LABEL[activeNhan],
      activeTone: INS_PHANLOAI_LOI_TONE[activeNhan],
      trangThai: tt, ttLabel: INS_PHANLOAI_TRANGTHAI_LABEL[tt], ttTone: INS_PHANLOAI_TRANGTHAI_TONE[tt],
      chips, duong, vaoLoSua: it.trangThai === 'vao-lo-sua', mocNopGoc: it.mocNopGoc ?? it.ngayNop ?? '—',
    };
  }

  /** Nhãn tone → màu tag ng-zorro preset (dùng cho hrm-tag ⑥). */
  protected insToNzColor(tone: string): string {
    return tone === 'warning' ? 'warning' : tone === 'processing' ? 'processing' : tone === 'info' ? 'blue' : 'default';
  }

  /* ── dải 6 bước (done ✓ · current · upcoming) ── */
  protected readonly steps = computed(() => {
    const t = this.lo()?.trangThai ?? 'nhap';
    const cur = currentStep(t, this.rejectedOpen());
    const state = (idx: number): 'done' | 'current' | 'upcoming' =>
      cur >= 7 ? 'done' : idx < cur ? 'done' : idx === cur ? 'current' : 'upcoming';
    return [
      { n: 1, label: 'Soát', state: state(1) },
      { n: 2, label: 'Dựng tờ khai', state: state(2) },
      { n: 3, label: 'Duyệt & Ký', state: state(3) },
      { n: 4, label: 'Nộp', state: state(4) },
      { n: 5, label: 'Import', state: state(5) },
      { n: 6, label: 'Xử lý trả về', state: state(6) },
    ];
  });

  /* ── cột lưới (gắn cell TemplateRef theo key) ── */
  private readonly itTenTpl = viewChild.required<TemplateRef<unknown>>('itTen');
  private readonly itSuKienTpl = viewChild.required<TemplateRef<unknown>>('itSuKien');
  private readonly itPaTpl = viewChild.required<TemplateRef<unknown>>('itPa');
  private readonly itLuongTpl = viewChild.required<TemplateRef<unknown>>('itLuong');
  private readonly itPreTpl = viewChild.required<TemplateRef<unknown>>('itPre');
  private readonly itViPhamTpl = viewChild.required<TemplateRef<unknown>>('itViPham');
  private readonly itTrangThaiTpl = viewChild.required<TemplateRef<unknown>>('itTrangThai');
  private readonly itActTpl = viewChild.required<TemplateRef<unknown>>('itAct');
  protected readonly itemCols = computed<HrmGridColumn[]>(() => {
    const tpl: Record<string, TemplateRef<unknown> | undefined> = {
      ten: this.itTenTpl(), suKien: this.itSuKienTpl(), phuongAn: this.itPaTpl(), luong: this.itLuongTpl(),
      preCheck: this.itPreTpl(), viPham: this.itViPhamTpl(), trangThai: this.itTrangThaiTpl(), act: this.itActTpl(),
    };
    return M03_ITEM_COLS.map((d) => ({ ...d, cell: tpl[d.key] as HrmGridColumn['cell'] }));
  });

  private readonly kqTenTpl = viewChild.required<TemplateRef<unknown>>('kqTen');
  private readonly kqSuKienTpl = viewChild.required<TemplateRef<unknown>>('kqSuKien');
  private readonly kqNopTpl = viewChild.required<TemplateRef<unknown>>('kqNop');
  private readonly kqKetQuaTpl = viewChild.required<TemplateRef<unknown>>('kqKetQua');
  private readonly kqLyDoTpl = viewChild.required<TemplateRef<unknown>>('kqLyDo');
  private readonly kqPhienBanTpl = viewChild.required<TemplateRef<unknown>>('kqPhienBan');
  protected readonly kqCols = computed<HrmGridColumn[]>(() => {
    const tpl: Record<string, TemplateRef<unknown> | undefined> = {
      ten: this.kqTenTpl(), suKien: this.kqSuKienTpl(), nop: this.kqNopTpl(), ketQua: this.kqKetQuaTpl(),
      lyDo: this.kqLyDoTpl(), phienBan: this.kqPhienBanTpl(),
    };
    return M03_KETQUA_COLS.map((d) => ({ ...d, cell: tpl[d.key] as HrmGridColumn['cell'] }));
  });

  /* ── C1 — bảng dẫn nguồn "mình khai ↔ cơ quan ghi" (hrm-grid compact, tĩnh) ── */
  private readonly dnFlagTpl = viewChild.required<TemplateRef<unknown>>('dnFlag');
  protected readonly danNguonCols = computed<HrmGridColumn[]>(() => [
    { key: 'truong', title: 'Trường' },
    { key: 'minhKhai', title: 'Mình khai' },
    { key: 'coQuanGhi', title: 'Cơ quan ghi' },
    { key: 'khop', title: 'Đối chiếu', align: 'center', cell: this.dnFlagTpl() as HrmGridColumn['cell'] },
  ]);

  /* ═════════ hành động — gọi ĐÚNG store method của b2/b34 ═════════ */
  protected chayPreCheck(): void {
    const r = this.store.chayPreCheck(this.loId());
    r.ok
      ? this.msg.success(`Pre-check xong: ${r.dat} Đạt · ${r.canhBao} Cảnh báo · ${r.loi} Lỗi (ghi đè kết quả, giữ lịch sử).`)
      : this.msg.error(r.reason ?? 'Không chạy được pre-check.');
    this.showItems.set(true);
  }
  protected tachLoi(): void {
    const r = this.store.tachItemLoi(this.loId());
    r.done
      ? this.msg.success(`Đã tách ${r.done} dòng Lỗi khỏi lô — dòng gốc giữ nguyên, item về Sẵn sàng.`)
      : this.msg.warning('Không có dòng Lỗi để tách.');
  }
  /** §5 — lọc nhanh chỉ N dòng Lỗi (mở lưới item + bật onlyLoi). */
  protected xemDongLoi(): void { this.onlyLoi.set(true); this.showItems.set(true); }
  protected trinhDuyet(): void {
    const r = this.store.trinhDuyet(this.loId());
    r.ok ? this.msg.success(`Đã trình duyệt lô ${this.loId()} — chuyển Chờ duyệt.`) : this.msg.error(r.reason ?? 'Không trình được.');
  }
  protected duyet(): void {
    const r = this.store.duyet(this.loId());
    r.ok ? this.msg.success(`Đã duyệt lô ${this.loId()} — sẵn sàng ký số.`) : this.msg.error(r.reason ?? 'Không duyệt được.');
  }
  protected ky(): void {
    const r = this.store.ky(this.loId());
    r.ok ? this.msg.success(`Đã ký số lô ${this.loId()} — nội dung ký là bản đóng băng.`) : this.msg.error(r.reason ?? 'Không ký được.');
  }
  protected nop(): void {
    const r = this.store.nop(this.loId());
    if (!r.ok) { this.msg.error(r.reason ?? 'Không nộp được.'); return; }
    this.msg.success(`Đã nộp lô ${this.loId()} — mã GD ${r.maGD}, lưu 6 dữ kiện bằng chứng (không ghi đè).`);
    this.showEvidence.set(true);
  }
  /** ⑤ F4 — Import tệp phản hồi (demo deterministic): item đầu Bị từ chối (lý do danh mục), còn lại chấp nhận. */
  protected importKetQua(): void {
    const its = this.items();
    const rows = its.map((it, idx) => ({
      itemId: it.maItem,
      ketQua: (idx === 0 ? 'tu-choi' : 'chap-nhan') as InsKetQuaCQ,
      lyDo: idx === 0 ? 'Sai mã phương án tại kỳ lô' : undefined,
    }));
    const r = this.store.ghiKetQua(this.loId(), rows);
    r.done
      ? this.msg.success(`Đã bóc tách kết quả ${r.done}/${rows.length} item từ tệp phản hồi${r.skipped.length ? ` · ${r.skipped.length} bị chặn` : ''}.`)
      : this.msg.error(r.skipped[0]?.reason ?? 'Không bóc tách được kết quả.');
    this.showResult.set(true);
  }
  /** ⑤ F4 — Nhập tay kết quả (văn bản giấy): bắt buộc số văn bản + ngày (store guard). */
  protected submitNhapTay(): void {
    const id = this.mItem();
    if (!id) { this.msg.error('Chọn item chưa có kết quả để nhập tay.'); return; }
    const kq = this.mKq();
    const lyDo = kq === 'tu-choi' ? this.mLyDo() : undefined;
    if (kq === 'tu-choi' && !this.mLyDo()) { this.msg.error('Từ chối BẮT BUỘC lý do danh mục.'); return; }
    const r = this.store.nhapTayKetQua(id, kq, this.mSoVB(), this.mNgay(), lyDo);
    if (!r.ok) { this.msg.error(r.reason ?? 'Không nhập được kết quả.'); return; }
    this.msg.success(`Đã nhập tay kết quả (văn bản giấy) — số ${this.mSoVB()} · ${this.mNgay()}.`);
    this.showManual.set(false); this.showResult.set(true);
    this.mItem.set(''); this.mSoVB.set(''); this.mNgay.set(''); this.mKq.set('chap-nhan'); this.mLyDo.set('');
  }
  protected taoLoSua(): void {
    const r = this.store.taoLoSua(this.loId());
    if (!r.ok) { this.msg.error(r.reason ?? 'Không tạo được lô sửa.'); return; }
    r.skipped.length
      ? this.msg.warning(`Đã tạo lô sửa ${r.maLoMoi}: ${r.done} dòng vào lô · ${r.skipped.length} bỏ qua. Lô sửa đi lại đủ B2+B3.`)
      : this.msg.success(`Đã tạo lô sửa ${r.maLoMoi} với ${r.done} dòng — đi lại đủ B2+B3.`);
  }
  /** Trả về M02 — điều hướng 2 chiều (đường ra "nav", không cần lý do). */
  protected traVe02(): void {
    this.msg.success('Đẩy dòng về M02 — mở Tab Dữ liệu ngoại lệ để xử lý lại (liên kết 2 chiều).');
    this.shell.go('m02', { ky: this.store.kyId(), donVi: this.store.donViId(), filter: 'tab5:bi-tra-lai-tu-lo' });
  }

  /* ── ⑤ F1 — xác nhận / đổi nhãn phân loại lỗi ── */
  protected onChonNhan(id: string, nhan: InsPhanLoaiLoi): void {
    if (this.locked()) return;                 // kỳ khóa → chỉ đọc (không phân loại/đổi nhãn)
    const it = this.items().find((i) => i.maItem === id);
    if (!it) return;
    if (it.phanLoaiLoi === nhan) return; // đã là nhãn đó
    const de = this.store.deXuatPhanLoaiLoi(id);
    if (!it.phanLoaiLoi && de && de.nhan === nhan) {
      // chọn ĐÚNG nhãn đề xuất, chưa từng chốt → xác nhận trực tiếp (không cần lý do)
      const r = this.store.xacNhanPhanLoai(id, nhan);
      r.ok
        ? this.msg.success(`Đã xác nhận nhãn "${INS_PHANLOAI_LOI_LABEL[nhan]}" (đề xuất mô phỏng — người xác nhận).`)
        : this.msg.error(r.reason ?? 'Không xác nhận được nhãn.');
    } else {
      // đổi sang nhãn KHÁC đề xuất/đang chốt → host mở modal LÝ DO, ghi vết (BUILD-3).
      // Nhãn MỚI đi kèm qua id ghép `${itemId}|${nhan}` (giữ contract output {mode,id} nguyên) — host tách.
      this.reason.emit({ mode: 'doi-nhan-loi', id: `${id}|${nhan}` });
    }
  }

  /* ── ⑥ F2/F3 — giải trình & gửi lại (giữ mốc nộp gốc) ── */
  protected batDau(id: string): void {
    const r = this.store.batDauXuLy(id);
    r.ok ? this.msg.info('Bắt đầu xử lý — soạn giải trình gửi cơ quan.') : this.msg.error(r.reason ?? 'Không bắt đầu được.');
  }
  protected toggleDinhKem(id: string): void {
    this.dinhKem.update((m) => ({ ...m, [id]: !m[id] }));
    this.msg.info(this.dinhKemOf(id) ? 'Đã đính kèm bằng chứng (mô phỏng).' : 'Đã bỏ đính kèm.');
  }
  protected guiLai(id: string): void {
    const r = this.store.giaiTrinhGuiLai(id, this.gtOf(id));
    r.ok
      ? this.msg.success('Đã giải trình & gửi lại — giữ mốc nộp gốc, không tính trễ (chờ phản hồi).')
      : this.msg.error(r.reason ?? 'Chưa gửi được giải trình.');
  }
  /** ⑤ Lịch sử kết quả — xem bản cũ (versioned append-only; mô phỏng mở lịch sử). */
  protected xemBanCu(itemId: string): void {
    const it = this.items().find((i) => i.maItem === itemId);
    const n = it ? it.lichSuKetQua.length : 0;
    this.msg.info(`Lịch sử kết quả (${n} bản) — bản cũ luôn xem được, không ghi đè (mô phỏng).`);
  }
  /** ⑥ Lỗi kỹ thuật — ký lại / sửa định dạng tệp (mô phỏng, giữ mốc nộp gốc). */
  protected kyThuatBuoc(label: string): void { this.msg.info(`${label} (mô phỏng) — giữ mốc nộp gốc, không tính trễ.`); }
  /** ⑥ Lỗi kỹ thuật — nộp lại sau ký lại/sửa định dạng; giữ mốc nộp gốc (tái dùng giaiTrinhGuiLai). */
  protected nopLaiKyThuat(id: string): void {
    const r = this.store.giaiTrinhGuiLai(id, 'Xử lý kỹ thuật: ký lại / sửa định dạng tệp — nộp lại (giữ mốc nộp gốc).');
    r.ok
      ? this.msg.success('Đã nộp lại (kỹ thuật) — giữ mốc nộp gốc, không tính trễ (chờ phản hồi).')
      : this.msg.error(r.reason ?? 'Chưa nộp lại được.');
  }

  /* ── hành động BẮT BUỘC LÝ DO / mở viewer → emit lên host ── */
  protected traLai(): void { this.reason.emit({ mode: 'tra-lai', id: this.loId() }); }
  protected chapNhan(itemId: string): void { this.reason.emit({ mode: 'canh-bao', id: itemId }); }
  protected loaiTru(itemId: string): void { this.reason.emit({ mode: 'ketqua-loai-tru', id: itemId }); }
  protected xemToKhai(): void { this.d02Opened.set(true); this.openD02.emit(this.loId()); }

  /* ── đổi kênh nộp (sau ký → hạ Nháp + chữ ký mất hiệu lực; store lo logic) ── */
  protected setKenh(v: unknown): void {
    const l = this.lo();
    if (!l || (v as InsKenhNop) === l.kenhNop) return;
    const daKy = l.trangThai === 'da-ky' || l.trangThai === 'da-duyet';
    const r = this.store.doiThamSoLo(this.loId(), { kenhNop: v as InsKenhNop });
    if (!r.ok) { this.msg.error(r.reason ?? 'Không đổi được kênh nộp.'); return; }
    this.msg.success(`Đã đổi kênh nộp.${daKy ? ' Lô hạ về Nháp — chữ ký mất hiệu lực, cần ký lại.' : ''}`);
  }
}

/** Lô "chưa nộp" (được sửa tham số). Cục bộ — giữ card độc lập, không phụ thuộc export nội bộ store. */
const LO_CHUA_NOP = new Set<InsLoTrangThai>(['nhap', 'bi-tra-lai', 'dang-kiem-tra', 'cho-duyet', 'da-duyet', 'da-ky']);

/** Bước hiện hành (1..6; 7 = tất cả hoàn tất) suy từ trạng thái lô — thuần, deterministic (zoneless-safe).
 *  co-ket-qua: còn dòng từ chối CHƯA đóng → chặng ⑥; hết → hoàn tất. */
/** Dấu chênh → tone InsVarianceCell (down = giảm/xanh · up = tăng/đỏ · zero = không đổi).
 *  Thuần, deterministic (chuỗi format sẵn từ seed) — zoneless-safe. */
function toneCuaChenh(chenh: string): 'up' | 'down' | 'zero' {
  const c = chenh.trim();
  if (c.startsWith('-') || c.startsWith('−')) return 'down';
  if (c.startsWith('+')) return 'up';
  return /[1-9]/.test(c) ? 'up' : 'zero';
}

function currentStep(t: InsLoTrangThai, rejectedOpen: boolean): number {
  switch (t) {
    case 'nhap': case 'bi-tra-lai': case 'dang-kiem-tra': return 1;
    case 'cho-duyet': case 'da-duyet': return 3;
    case 'da-ky': return 4;
    case 'da-nop': case 'dang-gui': return 5;
    case 'co-ket-qua': return rejectedOpen ? 6 : 7;
    default: return 1;
  }
}
