import { INS_NHAN_VIEN, insDonVi, insNhanVien } from '../../_data/_core';
import { INS_CHANGE_STATE_LABEL, InsM02Store, insFormatVnd, insParseVnd } from '../../_data/_m02-data';
import { INS_QUY_LABEL, InsM04Store, M04_ITEM_LABEL, M04_QUYS } from '../../_data/_m04-data';
import { INS_CASE_NHOM_LABEL, INS_CASE_STATE_LABEL, InsCaseNhom, InsM05Store } from '../../_data/_m05-data';
import { InsM06Store } from '../../_data/_m06-data';
import { InsM07Store, M07_BIEU_MAU, M07_STATE_LABEL, m07SoDuyet } from '../../_data/_m07-data';
import { InsM08Store } from '../../_data/_m08-data';

/** Builder KẾT QUẢ báo cáo M07-B — hàm thuần đọc store (M02/M04/M05/M06/M07 → nguồn các nhóm).
 *  Kết quả LUÔN kèm DÒNG TỔNG theo đơn vị + toàn phạm vi (phạm vi hợp nhất); dòng tổng đánh dấu
 *  `tong: true` (render đậm). Số tiền đi qua `tien()` (che theo quyền — nhạy cảm che cả tệp xuất). */

export interface M07KqCol { key: string; title: string; align?: 'left' | 'right'; width?: string; }
export interface M07KetQua { cols: M07KqCol[]; rows: Record<string, unknown>[]; }

export interface M07BuildCtx {
  kyId: string;
  /** Phạm vi hợp nhất đã chọn → danh sách đơn vị trong phạm vi. */
  donViIds: string[];
  thamSo: string;
  tien: (s?: string) => string;
  m02: InsM02Store;
  m04: InsM04Store;
  m05: InsM05Store;
  m06: InsM06Store;
  m07: InsM07Store;
  /** BQA-22: nguồn bảng ánh xạ mã cũ ↔ mã mới (CHỈ ĐỌC — M08 không import M07, không vòng). */
  m08: InsM08Store;
}

const col = (key: string, title: string, align?: 'left' | 'right', width?: string): M07KqCol => ({ key, title, align, width });

/** Dòng tổng theo đơn vị + toàn phạm vi (đếm + cộng tiền nếu có). */
function tongRows(rows: Record<string, unknown>[], donViIds: string[], donViKey: string, sumKeys: string[], tien: (s?: string) => string): Record<string, unknown>[] {
  const out: Record<string, unknown>[] = [];
  const mk = (label: string, subset: Record<string, unknown>[]): Record<string, unknown> => {
    const r: Record<string, unknown> = { c1: label, tong: true };
    r['count'] = `${subset.length} dòng`;
    for (const k of sumKeys) {
      const s = subset.reduce((acc, x) => acc + insParseVnd(String(x[`${k}__raw`] ?? x[k] ?? '')), 0);
      r[k] = tien(insFormatVnd(s));
    }
    return r;
  };
  if (donViIds.length > 1) {
    for (const dv of donViIds) out.push(mk(`TỔNG — ${insDonVi(dv)?.ten ?? dv}`, rows.filter((r) => r[donViKey] === dv)));
  }
  out.push(mk('TỔNG — toàn phạm vi', rows));
  return out;
}

export function m07BuildKetQua(itemKey: string, ctx: M07BuildCtx): M07KetQua | null {
  const { donViIds, tien } = ctx;
  const inScope = (dv: string) => donViIds.includes(dv);

  switch (itemKey) {
    /* ── Biến động (nguồn M02) ── */
    case 'bd-tong-hop': {
      const list = ctx.m02.changes().filter((c) => inScope(c.donViId));
      const byState = new Map<string, { count: number; tien: number }>();
      for (const c of list) {
        const k = INS_CHANGE_STATE_LABEL[c.trangThai];
        const cur = byState.get(k) ?? { count: 0, tien: 0 };
        cur.count++; cur.tien += insParseVnd(c.chenhLechDuKien ?? '');
        byState.set(k, cur);
      }
      const rows = [...byState.entries()].map(([k, v]) => ({ c1: k, c2: String(v.count), c3: tien(insFormatVnd(v.tien, true)) }));
      rows.push({ c1: 'TỔNG — toàn phạm vi', c2: String(list.length), c3: tien(insFormatVnd(list.reduce((s, c) => s + insParseVnd(c.chenhLechDuKien ?? ''), 0), true)), tong: true } as never);
      return { cols: [col('c1', 'Trạng thái vòng đời'), col('c2', 'Số dòng', 'right'), col('c3', 'Chênh lệch dự kiến (Dự kiến nội bộ)', 'right')], rows };
    }
    case 'bd-qua-han': {
      const list = ctx.m02.changes().filter((c) => inScope(c.donViId) && c.coHan === 'qua-han');
      const rows: Record<string, unknown>[] = list.map((c) => ({
        c1: c.moTa, c2: insNhanVien(c.nhanVienId)?.name ?? '—', c3: c.ngayHanXuLy || '—', c4: insDonVi(c.donViId)?.ten ?? c.donViId, dv: c.donViId,
      }));
      return { cols: [col('c1', 'Biến động'), col('c2', 'NLĐ'), col('c3', 'Hạn xử lý'), col('c4', 'Đơn vị')], rows: [...rows, ...tongRows(rows, donViIds, 'dv', [], tien)] };
    }

    /* ── Nghĩa vụ đóng (nguồn M04 — CHỈ ĐỌC) ── */
    case 'nvd-4-quy': {
      const snap = ctx.m04.snapshots().filter((s) => s.kyId === 'k07').sort((a, b) => b.phienBan - a.phienBan)[0];
      if (!snap) return { cols: [col('c1', 'Thông báo')], rows: [{ c1: 'Chưa nhận C12-TS — không có snapshot kỳ (không số 0 giả).' }] };
      const rows = M04_QUYS.map((q) => ({
        c1: INS_QUY_LABEL[q],
        c2: tien(insFormatVnd(snap.funds[q].phaiDong)),
        c3: tien(insFormatVnd(snap.funds[q].daDong)),
        c4: tien(insFormatVnd(snap.funds[q].phaiDong - snap.funds[q].daDong)),
      }));
      rows.push({
        c1: `TỔNG (snapshot v${snap.phienBan} · ${snap.taiThoiDiem})`,
        c2: tien(insFormatVnd(M04_QUYS.reduce((s, q) => s + snap.funds[q].phaiDong, 0))),
        c3: tien(insFormatVnd(M04_QUYS.reduce((s, q) => s + snap.funds[q].daDong, 0))),
        c4: tien(insFormatVnd(M04_QUYS.reduce((s, q) => s + snap.funds[q].phaiDong - snap.funds[q].daDong, 0))),
        tong: true,
      } as never);
      return { cols: [col('c1', 'Quỹ'), col('c2', 'Phải đóng', 'right'), col('c3', 'Đã đóng', 'right'), col('c4', 'Còn thiếu', 'right')], rows };
    }
    case 'nvd-doi-soat': {
      const list = ctx.m04.items().filter((i) => i.kyId === 'k07');
      const rows = list.map((i) => ({
        c1: `${i.id} · nhánh ${i.nhanh}`, c2: i.moTa,
        c3: tien(insFormatVnd(i.giaTri, true)), c4: M04_ITEM_LABEL[i.trangThai],
      }));
      return { cols: [col('c1', 'Item', undefined, '140px'), col('c2', 'Mô tả'), col('c3', 'Chênh (C12 − expected)', 'right'), col('c4', 'Trạng thái')], rows };
    }
    case 'nvd-so-dieu-chinh': {
      const rows = ctx.m04.butToan().map((b) => ({
        c1: b.id, c2: b.loai, c3: tien(insFormatVnd(b.giaTri, true)), c4: b.trangThai,
        c5: b.refDao ? `cặp gốc–đảo: ${b.refDao}` : '—',
      }));
      return { cols: [col('c1', 'Bút toán'), col('c2', 'Loại'), col('c3', 'Giá trị', 'right'), col('c4', 'Trạng thái'), col('c5', 'Gốc–đảo')], rows };
    }

    /* ── Chi trả (nguồn M07-A) ── */
    case 'ct-3-so': {
      const list = ctx.m07.dong().filter((d) => inScope(d.donViId));
      const rows: Record<string, unknown>[] = list.map((d) => {
        const duyet = m07SoDuyet(d);
        return {
          c1: `${d.id} · ${insNhanVien(d.nhanVienId)?.name ?? ''}`,
          c2: d.soDeNghi ? tien(d.soDeNghi) : 'thiếu số đề nghị', c2__raw: d.soDeNghi,
          c3: duyet !== undefined ? tien(duyet) : 'chưa có kết quả', c3__raw: duyet ?? '',
          c4: d.soDaChi !== undefined ? tien(d.soDaChi) : '—', c4__raw: d.soDaChi ?? '',
          c5: M07_STATE_LABEL[d.trangThai], dv: d.donViId,
        };
      });
      return {
        cols: [col('c1', 'Dòng · NLĐ'), col('c2', 'Đề nghị (Dự kiến nội bộ)', 'right'), col('c3', 'Duyệt (Chính thức theo KQ cơ quan)', 'right'), col('c4', 'Đã chi (Đã thực hiện)', 'right'), col('c5', 'Trạng thái')],
        rows: [...rows, ...tongRows(rows, donViIds, 'dv', ['c2', 'c3', 'c4'], tien)],
      };
    }
    case 'ct-ton': {
      const list = ctx.m07.dong().filter((d) => inScope(d.donViId) && (d.trangThai === 'tien-da-ve' || d.trangThai === 'da-de-nghi'));
      const rows: Record<string, unknown>[] = list.map((d) => ({
        c1: `${d.id} · ${insNhanVien(d.nhanVienId)?.name ?? ''}`,
        c2: tien(m07SoDuyet(d)), c2__raw: m07SoDuyet(d) ?? '',
        c3: d.ngayTienVe ?? '—',
        c4: `${d.hanChi ?? '—'}${d.coQuaHan ? ' · QUÁ HẠN' : ''}`, dv: d.donViId,
      }));
      return { cols: [col('c1', 'Dòng · NLĐ'), col('c2', 'Số duyệt', 'right'), col('c3', 'Tiền về'), col('c4', 'Hạn chi')], rows: [...rows, ...tongRows(rows, donViIds, 'dv', ['c2'], tien)] };
    }
    case 'ct-de-nghi': {
      let list = ctx.m07.deNghi();
      if (ctx.thamSo && ctx.thamSo !== 'Tất cả') {
        const map: Record<string, string> = { 'Chờ duyệt': 'cho-duyet', 'Đã duyệt': 'da-duyet', 'Trả lại': 'tra-lai' };
        list = list.filter((d) => d.trangThai === map[ctx.thamSo]);
      }
      const rows = list.map((d) => ({
        c1: `${d.ma} · v${d.phienBan}`, c2: d.kyChi, c3: String(d.dongIds.length),
        c4: tien(d.tongTien), c5: `${d.trangThai === 'da-duyet' ? 'Đã duyệt (bất biến)' : d.trangThai === 'cho-duyet' ? 'Chờ duyệt' : d.trangThai === 'tra-lai' ? 'Trả lại' : 'Nháp'} · lập ${d.nguoiLap}`,
      }));
      return { cols: [col('c1', 'Đề nghị'), col('c2', 'Kỳ chi'), col('c3', 'Số NLĐ', 'right'), col('c4', 'Tổng tiền', 'right'), col('c5', 'Trạng thái · maker-checker')], rows };
    }

    /* ── Chế độ (nguồn M05) ── */
    case 'cd-trang-thai': {
      let list = ctx.m05.cases().filter((c) => inScope(c.donViId));
      if (ctx.thamSo && ctx.thamSo !== 'Tất cả') {
        const key = (Object.keys(INS_CASE_NHOM_LABEL) as InsCaseNhom[]).find((k) => INS_CASE_NHOM_LABEL[k] === ctx.thamSo);
        if (key) list = list.filter((c) => c.nhom === key);
      }
      const by = new Map<string, number>();
      for (const c of list) by.set(INS_CASE_STATE_LABEL[c.trangThai], (by.get(INS_CASE_STATE_LABEL[c.trangThai]) ?? 0) + 1);
      const rows = [...by.entries()].map(([k, v]) => ({ c1: k, c2: String(v) }));
      rows.push({ c1: 'TỔNG — toàn phạm vi', c2: String(list.length), tong: true } as never);
      return { cols: [col('c1', 'Trạng thái case'), col('c2', 'Số case', 'right')], rows };
    }
    case 'cd-huong-nld': {
      const list = ctx.m05.cases().filter((c) => inScope(c.donViId) && c.soTienDuKien);
      const rows: Record<string, unknown>[] = list.map((c) => ({
        c1: c.maCase, c2: insNhanVien(c.nhanVienId)?.name ?? '', c3: c.loaiCheDo,
        c4: tien(c.soTienDuKien), c4__raw: c.soTienDuKien, c5: INS_CASE_STATE_LABEL[c.trangThai], dv: c.donViId,
      }));
      return {
        cols: [col('c1', 'Case'), col('c2', 'NLĐ'), col('c3', 'Loại chế độ'), col('c4', 'Tiền dự kiến (nhạy cảm)', 'right'), col('c5', 'Trạng thái')],
        rows: [...rows, ...tongRows(rows, donViIds, 'dv', ['c4'], tien)],
      };
    }

    /* ── Hồ sơ (nguồn M06) ── */
    case 'hs-bo-ho-so': {
      const rows = ctx.m06.boHoSo().map((b) => ({
        c1: b.soHoSo, c2: b.ten, c3: `${b.loaiThuTuc} · ${b.phienBanThuTuc}`, c4: b.ngayLap,
      }));
      return { cols: [col('c1', 'Số hồ sơ'), col('c2', 'Tên'), col('c3', 'Thủ tục · phiên bản tại ngày lập'), col('c4', 'Ngày lập')], rows };
    }
    case 'hs-tai-lieu': {
      const rows = ctx.m06.taiLieu().map((t) => ({
        c1: t.ten, c2: t.loai, c3: `${t.hetHan ?? 'không thời hạn'}${t.quaHan ? ' · QUÁ HẠN' : ''}`,
        c4: t.nhayCam ? 'nhạy cảm — che theo quyền' : '—',
      }));
      return { cols: [col('c1', 'Tài liệu'), col('c2', 'Loại'), col('c3', 'Hết hạn'), col('c4', 'Nhạy cảm')], rows };
    }

    /* ── Danh sách lao động tham gia ── */
    case 'ld-tham-gia': {
      const list = INS_NHAN_VIEN.filter((e) => inScope(e.donViId));
      const rows: Record<string, unknown>[] = list.map((e) => ({
        c1: e.code, c2: e.name, c3: e.insCode, c4: e.maBHXH, c5: insDonVi(e.donViId)?.ten ?? '', dv: e.donViId,
      }));
      return { cols: [col('c1', 'Mã NV'), col('c2', 'Họ tên'), col('c3', 'Mã số BHXH'), col('c4', 'Mã ĐV BHXH'), col('c5', 'Đơn vị')], rows: [...rows, ...tongRows(rows, donViIds, 'dv', [], tien)] };
    }
    case 'ld-thieu-ma': {
      const rows = INS_NHAN_VIEN.filter((e) => inScope(e.donViId) && e.insCode === '—')
        .map((e) => ({ c1: e.code, c2: e.name, c3: e.dept, c4: 'chưa có mã số BHXH (nguồn ngoại lệ Tab 5 M02)' }));
      return { cols: [col('c1', 'Mã NV'), col('c2', 'Họ tên'), col('c3', 'Bộ phận'), col('c4', 'Ghi chú')], rows };
    }

    /* ── Tuân thủ ── */
    case 'tt-bieu-mau': {
      const rows = M07_BIEU_MAU.map((b) => ({ c1: b.label.split(' · ')[0], c2: b.label.split(' · ')[1] ?? '', c3: 'áp dụng theo ngày hiệu lực (M08)' }));
      rows.push({ c1: 'D02-LT — danh sách đề nghị', c2: 'CHƯA CÓ PHIÊN BẢN ÁP DỤNG tại kỳ 08/2026', c3: 'chờ đối chiếu nguyên văn phụ lục QĐ 366/QĐ-BHXH', tong: false } as never);
      // BQA-22 (M07-FN-13 BR-4): bảng mã cũ ↔ mã mới đọc từ InsM08Store (chỉ đọc) — kỳ cũ tra mã cũ,
      // kỳ mới tra mã mới; 2 cặp 610–612c / 613–612b GIỮ nhãn "cần xác minh".
      rows.push({ c1: 'MÃ CŨ ↔ MÃ MỚI (ánh xạ M08)', c2: 'báo cáo kỳ cũ dùng mã cũ — kỳ mới dùng mã mới', c3: 'nguồn: bảng ánh xạ mã phiếu M08 (chỉ đọc)', tong: true } as never);
      for (const a of ctx.m08.anhXa()) {
        rows.push({
          c1: `${a.maCu} ↔ ${a.maMoi}`,
          c2: `hiệu lực ${a.ngayHL}`,
          c3: `${a.ghiChu}${a.nhanXacMinh ? ' · ⚠ CẦN XÁC MINH — chưa chốt phụ lục QĐ 366' : ''}`,
        } as never);
      }
      return { cols: [col('c1', 'Mã / biểu mẫu'), col('c2', 'Phiên bản tại kỳ'), col('c3', 'Ghi chú')], rows };
    }
  }
  return null;
}
