import { ChangeDetectionStrategy, Component, TemplateRef, computed, inject, output, signal, viewChild } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { IconSearch } from '@tabler/icons-angular';
import { TablerIconComponent } from '@tabler/icons-angular';
import {
  HrmActionCell, HrmButton, HrmDetailPeek, HrmEmpty, HrmGrid, HrmGridColumn, HrmInput,
  HrmMessageService, HrmModalService, HrmPeekMode, HrmSegmented, HrmSelect, HrmStatusCell,
  HrmTag, HrmTextarea, HrmUserCell,
} from 'hrm-ui';
import { InsBulkBar, InsQueuePage, InsQueueSummary, InsQueueTab, InsSectionLabel, InsSlaChip } from '../../_shared';
import { insNhanVien } from '../../_data/_core';
import { insSlaView } from '../../_data/_m02-data';
import {
  INS_CASE_STATE_LABEL, INS_RA_STATE_LABEL, InsCase, InsCaseState, InsM05Store,
  M05BulkAction, M05_BULK_LABEL,
} from '../../_data/_m05-data';
import { M05Row, M05TabKey, M05_COLS, M05_GRID_MIN_WIDTH, M05_HAN_SEGMENTS, M05_TAB_LABEL, buildM05Row } from './_m05-columns';
import { InsM05CasePeek } from './m05-case-peek';

/** ═════════ M05-A — HÀNG ĐỢI CASE CHẾ ĐỘ (archetype Benefit Operations Queue, Phase D3) ═════════
 *  IA_LOCK m05.md: 1 lưới chia tab, P0 = ĐÚNG 4 tab `Tất cả · Ốm đau · Thai sản · Dưỡng sức`
 *  (count "12 · 3 quá hạn"); tab chỉ khác filter mặc định + cột đặc thù; chuyển tab GIỮ bộ lọc.
 *  Màn CHỈ hiển thị + chạy lô — case do M05-B sinh; `Chưa tiếp nhận` (đúng 2 lối ra) + dòng rà
 *  chênh lệch kỳ (M04-FN-15, phản hồi ngược M04) là SECTION RIÊNG (ins-section-label).
 *  Bulk 9 hành động: dry-run eligible/blocked (ins-bulk-bar) + partial {done, skipped} + retry
 *  chỉ dòng lỗi; công bố guard Tháng/Lần; XÓA = khóa quyền cao → disabled + lý do.
 *  Panel tóm tắt = hrm-detail-peek (side gọn) → "Đi sâu xử lý →" mở Màn B đúng bước. */
@Component({
  selector: 'ins-m05-queue',
  imports: [
    FormsModule, TablerIconComponent,
    HrmActionCell, HrmButton, HrmDetailPeek, HrmEmpty, HrmGrid, HrmInput, HrmSegmented, HrmSelect,
    HrmStatusCell, HrmTag, HrmTextarea, HrmUserCell,
    InsBulkBar, InsQueuePage, InsSectionLabel, InsSlaChip, InsM05CasePeek,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <ins-queue-page title="Hàng đợi case chế độ" subtitle="Case do Màn B sinh/cập nhật — màn này chỉ hiển thị + chạy lô; trạng thái chi trả đọc từ M07; danh mục từ M08."
      [tabs]="tabDefs()" [(activeTab)]="tabModel" [summary]="summaryItems()">

      <!-- Filter strip: search · trạng thái "Có sử dụng" · segmented hạn · bộ lọc Thiếu chứng từ -->
      <div qpFilters class="q5-filters">
        <hrm-input class="q5-filters__kw" [(ngModel)]="kwModel" size="sm" [prefixIcon]="icSearch" [clearable]="true"
          placeholder="Tìm NLĐ, mã case, mã tương quan…" />
        <hrm-select class="q5-filters__state" [(ngModel)]="stateModel" [options]="stateOptions()" size="sm"
          placeholder="Trạng thái (Có sử dụng)" [showSearch]="false" />
        <hrm-segmented [(ngModel)]="hanModel" [options]="hanSegs" size="sm" />
        <button type="button" class="q5-chip" [class.q5-chip--on]="store.queueThieuCT()"
          (click)="store.queueThieuCT.set(!store.queueThieuCT())"
          title="Case có ≥1 mục checklist bắt buộc thiếu — kèm hạn bổ sung (SLA M08)">
          Thiếu chứng từ ({{ store.thieuChungTuCases().length }})
        </button>
      </div>

      <!-- Lưới + panel tóm tắt -->
      <div class="q5-split">
        <div class="q5-main">
          @if (rows().length) {
            <hrm-grid [columns]="cols()" [data]="rows()" rowKey="id" [selectable]="true"
              [(selectedKeys)]="selModel" density="compact" [minWidth]="gridMinWidth()"
              [pageSize]="10" (rowClick)="onRowClick($event)" />
          } @else {
            <div class="q5-empty"><hrm-empty preset="no-results" description="Không có case nào khớp bộ lọc hiện tại." /></div>
          }

          <!-- Section riêng: Chưa tiếp nhận (đúng 2 lối ra) -->
          @if (store.chuaTiepNhan().length) {
            <section class="q5-sec">
              <ins-section-label text="Chưa tiếp nhận" tone="attention" [count]="store.chuaTiepNhan().length" />
              @for (c of store.chuaTiepNhan(); track c.maCase) {
                <div class="q5-row">
                  <span class="q5-row__mono">{{ c.maCase }}</span>
                  <span class="q5-row__main">{{ nvName(c.nhanVienId) }} · {{ c.loaiCheDo }} · nghỉ {{ c.tuNgay }} – {{ c.denNgay }}</span>
                  <span class="q5-row__muted">{{ c.lyDoChuaTiepNhan }}</span>
                  <ins-sla-chip [label]="slaOf(c).label" [tone]="slaOf(c).tone" />
                  <span class="q5-row__gap"></span>
                  <hrm-button size="sm" variant="primary" (click)="tiepNhanLai(c.maCase)">Tiếp nhận lại</hrm-button>
                  <hrm-button size="sm" [danger]="true" (click)="openDongChuaTN(c.maCase)">Đóng</hrm-button>
                </div>
              }
            </section>
          }

          <!-- Section riêng: dòng rà chênh lệch kỳ từ M04 (mã tương quan 2 chiều) -->
          @if (store.dongRaMo().length || dongRaXong().length) {
            <section class="q5-sec">
              <ins-section-label text="Chờ rà — chênh lệch kỳ từ M04" tone="critical" [count]="store.dongRaMo().length" />
              @for (r of store.dongRa(); track r.id) {
                <div class="q5-row">
                  <span class="q5-row__mono">{{ r.maTuongQuan }}</span>
                  <span class="q5-row__main">{{ r.moTa }}</span>
                  <hrm-tag size="sm" [color]="r.trangThai === 'cho-ra' ? 'orange' : r.trangThai === 'dang-ra' ? 'blue' : 'green'">{{ raLabel(r.trangThai) }}</hrm-tag>
                  <span class="q5-row__muted">{{ r.giaTri }} · kỳ {{ r.kyDong === 'k07' ? '07/2026' : r.kyDong }}</span>
                  <span class="q5-row__gap"></span>
                  @if (r.trangThai === 'cho-ra') {
                    <hrm-button size="sm" variant="primary" (click)="store.batDauRa(r.id)">Bắt đầu rà</hrm-button>
                  } @else if (r.trangThai === 'dang-ra') {
                    <hrm-button size="sm" variant="primary" (click)="daDieuChinh(r.id)">Đã điều chỉnh</hrm-button>
                    <hrm-button size="sm" (click)="openKhongThuoc(r.id)">Không thuộc chế độ</hrm-button>
                  } @else {
                    <span class="q5-row__muted">{{ r.phanHoiM04 }}</span>
                  }
                </div>
              }
            </section>
          }
        </div>

        <hrm-detail-peek [(open)]="peekOpenModel" [(peekMode)]="peekModeModel" [modes]="peekModes"
          [expandable]="false" [title]="peekTitle()" [content]="panelContent" [width]="440"
          [modeLabels]="peekLabels" switchLabel="Đổi cách hiển thị" closeLabel="Đóng" resizeLabel="Kéo đổi độ rộng" />
      </div>

      <!-- Bulk 9 hành động — dry-run theo hành động đang chọn -->
      <ins-bulk-bar qpBulk [selected]="sel().length" [eligible]="bulkPreview().eligible" [blocked]="bulkPreview().blocked">
        <hrm-select class="q5-bulk-sel" [(ngModel)]="bulkActionModel" [options]="bulkActionOptions" size="sm" [allowClear]="false" [showSearch]="false" />
        <hrm-button size="sm" variant="primary" [disabled]="bulkAction() === 'xoa'" (click)="runBulk()">{{ bulkLabel() }}</hrm-button>
        @if (bulkAction() === 'xoa') { <span class="q5-xoa-note">Xóa = khóa quyền cao — tài khoản demo không có quyền.</span> }
        @if (retryCount() > 0) {
          <hrm-button size="sm" (click)="retryBulk()">Chạy lại {{ retryCount() }} dòng lỗi</hrm-button>
        }
      </ins-bulk-bar>
    </ins-queue-page>

    <!-- ═════ Cell templates ═════ -->
    <ng-template #maCaseTpl let-row>
      <div class="q5-stack"><span class="q5-mono">{{ $any(row).maCase }}</span><span class="q5-muted">{{ $any(row).nhomLabel }}</span></div>
    </ng-template>
    <ng-template #userTpl let-row><hrm-user-cell [name]="$any(row).ten" [sub]="$any(row).sub" [avatarSize]="28" /></ng-template>
    <ng-template #loaiTpl let-row><span class="q5-strong">{{ $any(row).loaiCheDo }}</span></ng-template>
    <ng-template #tienTpl let-row>
      @if ($any(row).soTien) { <span class="q5-num">{{ $any(row).soTien }}</span> }
      @else { <span class="q5-muted">chưa có kết quả</span> }
    </ng-template>
    <ng-template #statusTpl let-row>
      <hrm-status-cell [status]="$any(row).trangThaiTone" [label]="$any(row).trangThaiLabel" variant="badge" />
    </ng-template>
    <ng-template #hanTpl let-row>
      <div class="q5-stack"><span class="q5-muted">{{ $any(row).hanNgay }}</span>
        <ins-sla-chip [label]="$any(row).slaLabel" [tone]="$any(row).slaTone" /></div>
    </ng-template>
    <ng-template #canhBaoTpl let-row>
      <div class="q5-tags">
        @if ($any(row).canhBaoChan) { <hrm-tag color="red" size="sm">{{ $any(row).canhBaoChan }} chặn</hrm-tag> }
        @if ($any(row).canhBaoWarn) { <hrm-tag color="orange" size="sm">{{ $any(row).canhBaoWarn }} cảnh báo</hrm-tag> }
        @if ($any(row).coException) { <hrm-tag color="purple" size="sm">exception mở</hrm-tag> }
        @if (!$any(row).canhBaoChan && !$any(row).canhBaoWarn && !$any(row).coException) { <span class="q5-muted">—</span> }
      </div>
    </ng-template>
    <ng-template #thieuTpl let-row>
      @if ($any(row).chungTuThieu) { <span class="q5-warn">{{ $any(row).chungTuThieu }}</span> }
      @else { <span class="q5-muted">đủ</span> }
    </ng-template>
    <ng-template #actTpl let-row>
      <hrm-action-cell [actions]="$any(row).actions" [max]="2" moreLabel="Thêm" (action)="onRowAction($any(row), $event)" />
    </ng-template>

    <!-- ═════ Panel tóm tắt case ═════ -->
    <ng-template #panelContent>
      @if (selCase(); as c) {
        <ins-m05-case-peek [c]="c" (deep)="openCase.emit($event)" />
      }
    </ng-template>

    <!-- ═════ Modal lý do dùng chung (đóng Chưa tiếp nhận / không thuộc chế độ) ═════ -->
    <ng-template #reasonTpl>
      <div class="q5-form">
        <p class="q5-muted">{{ reasonHint() }}</p>
        <hrm-textarea [(ngModel)]="reasonModel" placeholder="Nhập lý do (bắt buộc)…" [minRows]="3" [status]="reasonError() ? 'error' : ''" />
        @if (reasonError()) { <span class="q5-err">{{ reasonError() }}</span> }
      </div>
    </ng-template>

    <!-- Modal bulk có tham số (phân công / cập nhật trạng thái / công bố Tháng-Lần) -->
    <ng-template #bulkOptsTpl>
      <div class="q5-form">
        <p class="q5-muted">{{ bulkHint() }}</p>
        @if (bulkAction() === 'phan-cong') {
          <hrm-select [(ngModel)]="ownerModel" [options]="ownerOptions" placeholder="Chọn người phụ trách" [allowClear]="false" />
        } @else if (bulkAction() === 'cap-nhat') {
          <hrm-select [(ngModel)]="targetStateModel" [options]="stateOptions()" placeholder="Trạng thái đích" [allowClear]="false" [showSearch]="false" />
        } @else if (bulkAction() === 'cong-bo') {
          <hrm-segmented [(ngModel)]="congBoKieuModel" [options]="congBoSegs" size="sm" />
          <p class="q5-muted">Guard: chỉ case có kết quả <b>Đã/Không thanh toán</b> + <b>chưa công bố</b>; mail 2 mẫu; thông báo portal gom &lt;Số lượng&gt; + &lt;Nghiệp vụ&gt; + &lt;Trạng thái&gt;.</p>
        } @else if (bulkAction() === 'ket-xuat') {
          <p class="q5-muted">Kết xuất theo template (M08) — cột khớp lưới đang hiển thị.</p>
        }
      </div>
    </ng-template>
  `,
  host: { class: 'ins-m05-queue' },
  styles: [`
    :host { display: flex; flex-direction: column; flex: 1 1 auto; min-height: 0; }

    .q5-filters { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
    .q5-filters__kw { display: inline-block; width: 270px; }
    .q5-filters__state { display: inline-block; width: 210px; }
    .q5-chip {
      display: inline-flex; align-items: center; cursor: pointer; font: inherit;
      font-size: var(--fs-12); font-weight: 500; color: var(--warning-text);
      background: var(--warning-bg); border: 1px solid transparent; border-radius: var(--radius-full); padding: 2px 10px;
    }
    .q5-chip:hover { border-color: var(--warning-base, var(--warning-text)); }
    .q5-chip--on { border-color: var(--warning-base, var(--warning-text)); font-weight: 700; }

    /* peek side cần chỗ đứng khi bảng ít dòng (pattern D2 min-height) */
    .q5-split { flex: 1 1 auto; min-height: 480px; display: flex; gap: 12px; align-items: stretch; }
    .q5-main { flex: 1 1 auto; min-width: 0; overflow: auto; display: flex; flex-direction: column; gap: 14px; }
    .q5-empty { padding: 40px 0; display: flex; justify-content: center; }

    .q5-sec { display: flex; flex-direction: column; gap: 6px; }
    .q5-row {
      display: flex; align-items: center; gap: 10px; flex-wrap: wrap;
      border: 1px solid var(--border-sub); border-radius: var(--radius-md);
      background: var(--bg-surface); padding: 7px 12px; font-size: var(--fs-13);
    }
    .q5-row__mono { font-family: var(--font-mono, monospace); font-size: var(--fs-12); font-weight: 600; color: var(--text-strong); }
    .q5-row__main { color: var(--text-body); font-weight: 500; }
    .q5-row__muted { font-size: var(--fs-12); color: var(--text-sub); }
    .q5-row__gap { flex: 1; }

    .q5-stack { display: flex; flex-direction: column; gap: 2px; align-items: flex-start; min-width: 0; }
    .q5-mono { font-family: var(--font-mono, monospace); font-size: var(--fs-12); font-weight: 600; color: var(--text-strong); }
    .q5-strong { color: var(--text-strong); font-weight: 500; }
    .q5-muted { font-size: var(--fs-12); color: var(--text-sub); }
    .q5-warn { font-size: var(--fs-12); font-weight: 600; color: var(--warning-text); }
    .q5-err { font-size: var(--fs-12); color: var(--error-text); }
    .q5-num { font-weight: 600; color: var(--text-strong); font-variant-numeric: tabular-nums; }
    .q5-tags { display: flex; align-items: center; gap: 4px; flex-wrap: wrap; row-gap: 4px; }
    :host ::ng-deep .q5-tags .ant-tag { margin: 0; }

    .q5-bulk-sel { display: inline-block; width: 210px; }
    .q5-xoa-note { font-size: var(--fs-12); color: var(--text-sub); }
    .q5-form { display: flex; flex-direction: column; gap: 8px; }
    .q5-form b { color: var(--text-strong); }
  `],
})
export class InsM05Queue {
  protected readonly store = inject(InsM05Store);
  private readonly msg = inject(HrmMessageService);
  private readonly modal = inject(HrmModalService);

  protected readonly icSearch = IconSearch;
  protected readonly hanSegs = M05_HAN_SEGMENTS;

  /** Mở Màn B (đi sâu) — điều hướng nội bộ m05 qua signal, KHÔNG đổi URL. */
  readonly openCase = output<{ caseId: string; step: number }>();

  /* ── tab + filter (state sống trong store — back từ Màn B GIỮ tab/filter) ── */
  protected get tabModel(): string { return this.store.queueTab(); }
  protected set tabModel(v: string) { this.store.queueTab.set(v as M05TabKey); }
  protected get kwModel(): string { return this.store.queueKw(); }
  protected set kwModel(v: string) { this.store.queueKw.set(v ?? ''); }
  protected get stateModel(): unknown { return this.store.queueState(); }
  protected set stateModel(v: unknown) { this.store.queueState.set((v as string) || null); }
  protected get hanModel(): string | number { return this.store.queueHan(); }
  protected set hanModel(v: string | number) { this.store.queueHan.set(String(v ?? '')); }

  protected readonly tabDefs = computed<InsQueueTab[]>(() => {
    const c = this.store.tabCounts();
    return [
      { key: 'tat-ca', label: M05_TAB_LABEL['tat-ca'], count: c.tatCa.count, severityCount: c.tatCa.quaHan },
      { key: 'om-dau', label: M05_TAB_LABEL['om-dau'], count: c.omDau.count, severityCount: c.omDau.quaHan },
      { key: 'thai-san', label: M05_TAB_LABEL['thai-san'], count: c.thaiSan.count, severityCount: c.thaiSan.quaHan },
      { key: 'duong-suc', label: M05_TAB_LABEL['duong-suc'], count: c.duongSuc.count, severityCount: c.duongSuc.quaHan },
    ];
  });
  protected readonly summaryItems = computed<InsQueueSummary[]>(() => [
    { label: 'Số case', value: String(this.store.gridCases().length) },
    { label: 'Thiếu chứng từ', value: String(this.store.thieuChungTuCases().length) },
    { label: 'Chưa tiếp nhận / chờ rà', value: `${this.store.chuaTiepNhan().length} / ${this.store.dongRaMo().length}` },
    { label: 'Tổng chi dự kiến', value: this.store.tongDuKien(), layer: 'du-kien' },
  ]);
  protected readonly stateOptions = computed(() => this.store.statesInUse());

  /* ── lưới: filter chain + swap cột theo tab ── */
  private readonly filtered = computed<InsCase[]>(() => {
    let list = this.store.gridCases();
    const tab = this.store.queueTab();
    if (tab !== 'tat-ca') list = list.filter((c) => c.nhom === tab);
    const st = this.store.queueState();
    if (st) list = list.filter((c) => c.trangThai === st);
    const han = this.store.queueHan();
    if (han) list = list.filter((c) => c.coHan === han);
    if (this.store.queueThieuCT()) {
      list = list.filter((c) => c.checklist.some((k) => k.batBuoc && k.trangThai === 'thieu'));
    }
    const kw = this.store.queueKw().trim().toLowerCase();
    if (kw) {
      list = list.filter((c) => {
        const nv = insNhanVien(c.nhanVienId);
        return `${nv?.name ?? ''} ${nv?.code ?? ''} ${c.maCase} ${c.loaiCheDo} ${c.correlationId}`.toLowerCase().includes(kw);
      });
    }
    return list;
  });
  protected readonly rows = computed<M05Row[]>(() => this.filtered().map(buildM05Row));
  protected readonly gridMinWidth = computed(() => M05_GRID_MIN_WIDTH[this.store.queueTab()]);
  protected readonly dongRaXong = computed(() =>
    this.store.dongRa().filter((r) => r.trangThai === 'da-dieu-chinh' || r.trangThai === 'da-tra-loi-khong-thuoc'));

  private readonly maCaseTpl = viewChild.required<TemplateRef<unknown>>('maCaseTpl');
  private readonly userTpl = viewChild.required<TemplateRef<unknown>>('userTpl');
  private readonly loaiTpl = viewChild.required<TemplateRef<unknown>>('loaiTpl');
  private readonly tienTpl = viewChild.required<TemplateRef<unknown>>('tienTpl');
  private readonly statusTpl = viewChild.required<TemplateRef<unknown>>('statusTpl');
  private readonly hanTpl = viewChild.required<TemplateRef<unknown>>('hanTpl');
  private readonly canhBaoTpl = viewChild.required<TemplateRef<unknown>>('canhBaoTpl');
  private readonly thieuTpl = viewChild.required<TemplateRef<unknown>>('thieuTpl');
  private readonly actTpl = viewChild.required<TemplateRef<unknown>>('actTpl');

  protected readonly cols = computed<HrmGridColumn[]>(() => {
    const tpl: Record<string, TemplateRef<unknown> | undefined> = {
      maCaseCell: this.maCaseTpl(), ten: this.userTpl(), loaiCheDoCell: this.loaiTpl(),
      soTienCell: this.tienTpl(), trangThai: this.statusTpl(), hanXuLy: this.hanTpl(),
      canhBao: this.canhBaoTpl(), chungTuThieu: this.thieuTpl(), act: this.actTpl(),
    };
    return M05_COLS[this.store.queueTab()].map((d) => ({ ...d, cell: tpl[d.key] as HrmGridColumn['cell'] }));
  });

  /* ── selection + peek (đóng panel GIỮ selection/tab/filter — drawer contract) ── */
  private readonly selKeys = signal<unknown[]>([]);
  protected get selModel(): unknown[] { return this.selKeys(); }
  protected set selModel(v: unknown[]) { this.selKeys.set(v); }
  protected readonly sel = computed<string[]>(() => this.selKeys().map(String));

  protected readonly peekModes: HrmPeekMode[] = ['side', 'master'];
  protected readonly peekLabels: Partial<Record<HrmPeekMode, string>> = { side: 'Ngăn cạnh', master: 'Cạnh bảng' };
  private readonly peekOpen = signal(false);
  protected get peekOpenModel(): boolean { return this.peekOpen(); }
  protected set peekOpenModel(v: boolean) { this.peekOpen.set(v); }
  private readonly peekMode = signal<HrmPeekMode>('side');
  protected get peekModeModel(): HrmPeekMode { return this.peekMode(); }
  protected set peekModeModel(v: HrmPeekMode) { this.peekMode.set(v); }
  private readonly selId = signal<string | null>(null);
  protected readonly selCase = computed(() => {
    const id = this.selId();
    return id ? this.store.caseOf(id) ?? null : null;
  });
  protected readonly peekTitle = computed(() => {
    const c = this.selCase();
    return c ? `${c.maCase} · ${this.nvName(c.nhanVienId)}` : '';
  });

  protected onRowClick(row: Record<string, unknown>): void { this.selId.set(String(row['id'])); this.peekOpen.set(true); }
  protected onRowAction(row: M05Row, key: string): void {
    if (key === 'view') { this.selId.set(row.id); this.peekOpen.set(true); }
    else if (key === 'deep') this.openCase.emit({ caseId: row.id, step: row.buoc });
  }

  protected nvName(id: string): string { return insNhanVien(id)?.name ?? id; }
  protected slaOf(c: InsCase) { return insSlaView(c); }
  protected raLabel(s: keyof typeof INS_RA_STATE_LABEL): string { return INS_RA_STATE_LABEL[s]; }

  /* ── Chưa tiếp nhận: đúng 2 lối ra ── */
  protected tiepNhanLai(id: string): void {
    const r = this.store.tiepNhan(id);
    if (!r.ok) { this.msg.error(r.reason ?? 'Không tiếp nhận được.'); return; }
    this.msg.success(`Đã tiếp nhận lại ${id} — mở B1 với dữ liệu gốc.`);
    this.openCase.emit({ caseId: id, step: 1 });
  }

  /* ── bulk 9 hành động ── */
  protected readonly bulkActionOptions = (Object.keys(M05_BULK_LABEL) as M05BulkAction[])
    .map((a) => ({ value: a, label: `${M05_BULK_LABEL[a]}${a === 'xoa' ? ' (khóa quyền cao)' : ''}` }));
  protected readonly bulkAction = signal<M05BulkAction>('yeu-cau');
  protected get bulkActionModel(): unknown { return this.bulkAction(); }
  protected set bulkActionModel(v: unknown) { this.bulkAction.set((v as M05BulkAction) || 'yeu-cau'); }
  protected readonly bulkLabel = computed(() => M05_BULK_LABEL[this.bulkAction()]);
  protected readonly bulkPreview = computed(() => this.store.bulkPreview(this.bulkAction(), this.sel()));
  protected readonly bulkHint = computed(() =>
    `${this.store.bulkPermission(this.bulkAction())} · ${this.sel().length} case đã chọn — dòng không thỏa bị loại, phần còn lại chạy (thành công một phần + retry idempotent).`);
  protected readonly retryCount = computed(() => this.store.lastBulk()?.skipped.length ?? 0);

  protected readonly ownerOptions = [this.store.currentUser, this.store.quanLyHR, this.store.keToan].map((o) => ({ value: o, label: o }));
  private readonly owner = signal(this.store.quanLyHR);
  protected get ownerModel(): unknown { return this.owner(); }
  protected set ownerModel(v: unknown) { this.owner.set(String(v ?? '')); }
  private readonly targetState = signal<InsCaseState | null>(null);
  protected get targetStateModel(): unknown { return this.targetState(); }
  protected set targetStateModel(v: unknown) { this.targetState.set((v as InsCaseState) || null); }
  protected readonly congBoSegs = [{ label: 'Tháng', value: 'Tháng' }, { label: 'Lần', value: 'Lần' }];
  private readonly congBoKieu = signal<'Tháng' | 'Lần'>('Tháng');
  protected get congBoKieuModel(): string | number { return this.congBoKieu(); }
  protected set congBoKieuModel(v: string | number) { this.congBoKieu.set(v === 'Lần' ? 'Lần' : 'Tháng'); }

  private dlg: { close: () => void } | null = null;
  private readonly bulkOptsTplRef = viewChild<TemplateRef<unknown>>('bulkOptsTpl');

  protected runBulk(): void {
    const ids = this.sel();
    if (!ids.length) { this.msg.warning('Chưa chọn case nào.'); return; }
    const action = this.bulkAction();
    const needOpts = action === 'phan-cong' || action === 'cap-nhat' || action === 'cong-bo' || action === 'ket-xuat';
    const preview = this.bulkPreview();
    const doRun = () => {
      const r = this.store.bulkRun(action, ids, {
        owner: this.owner(), trangThai: this.targetState() ?? undefined, congBoKieu: this.congBoKieu(),
      });
      if (r.done && r.skipped.length) this.msg.warning(`${M05_BULK_LABEL[action]}: ${r.done}/${ids.length} case · ${r.skipped.length} bị loại (xem lý do trên thanh bulk / nút retry).`);
      else if (r.done) this.msg.success(`${M05_BULK_LABEL[action]}: ${r.done}/${ids.length} case — audit đầy đủ.`);
      else this.msg.error(r.skipped[0]?.reason ?? 'Không case nào đủ điều kiện.');
      this.dlg?.close();
    };
    if (needOpts) {
      this.dlg = this.modal.open({
        title: `${M05_BULK_LABEL[action]} — ${preview.eligible}/${ids.length} case đủ điều kiện`,
        content: this.bulkOptsTplRef()!, width: 480,
        footer: [
          { label: 'Hủy', onClick: () => this.dlg?.close() },
          { label: M05_BULK_LABEL[action], type: 'primary', onClick: doRun },
        ],
      });
    } else {
      this.modal.confirm({
        title: `${M05_BULK_LABEL[action]} ${preview.eligible}/${ids.length} case?`,
        content: `${this.bulkHint()}${action === 'yeu-cau' ? ' Mail theo 4 mẫu (gốc/đính kèm × hợp lệ/không) CC người yêu cầu.' : ''}`,
        okText: M05_BULK_LABEL[action], cancelText: 'Hủy',
        onOk: doRun,
      });
    }
  }

  /** Retry idempotent — CHỈ chạy lại phần lỗi của lần bulk gần nhất. */
  protected retryBulk(): void {
    const last = this.store.lastBulk();
    if (!last?.skipped.length) return;
    const ids = last.skipped.map((s) => s.id);
    const r = this.store.bulkRun(last.action, ids, { owner: this.owner(), congBoKieu: this.congBoKieu() });
    r.done
      ? this.msg.success(`Retry ${M05_BULK_LABEL[last.action]}: ${r.done}/${ids.length} chạy được — không sinh trùng.`)
      : this.msg.warning(`Retry: 0/${ids.length} — lý do chặn không đổi.`);
  }

  /* ── modal lý do (đóng Chưa tiếp nhận / trả lời không thuộc chế độ) ── */
  private readonly reasonMode = signal<'dong-chua-tn' | 'khong-thuoc'>('dong-chua-tn');
  private readonly reasonTarget = signal('');
  private readonly reasonText = signal('');
  protected get reasonModel(): string { return this.reasonText(); }
  protected set reasonModel(v: string) { this.reasonText.set(v ?? ''); if (v?.trim()) this.reasonError.set(''); }
  protected readonly reasonError = signal('');
  protected readonly reasonHint = computed(() => this.reasonMode() === 'dong-chua-tn'
    ? 'Đóng case Chưa tiếp nhận — 1 trong đúng 2 lối ra; lý do bắt buộc + để vết audit.'
    : 'Trả lời "không thuộc chế độ" — phản hồi ngược M04 theo mã tương quan 2 chiều; lý do bắt buộc.');
  private readonly reasonTplRef = viewChild<TemplateRef<unknown>>('reasonTpl');

  private openReason(mode: 'dong-chua-tn' | 'khong-thuoc', target: string, title: string): void {
    this.reasonMode.set(mode); this.reasonTarget.set(target);
    this.reasonText.set(''); this.reasonError.set('');
    this.dlg = this.modal.open({
      title, content: this.reasonTplRef()!, width: 460,
      footer: [
        { label: 'Hủy', onClick: () => this.dlg?.close() },
        { label: title, type: 'primary', danger: mode === 'dong-chua-tn', onClick: () => this.confirmReason() },
      ],
    });
  }
  protected openDongChuaTN(id: string): void { this.openReason('dong-chua-tn', id, 'Đóng case Chưa tiếp nhận'); }
  protected openKhongThuoc(raId: string): void { this.openReason('khong-thuoc', raId, 'Trả lời "không thuộc chế độ"'); }

  private confirmReason(): void {
    const lyDo = this.reasonText().trim();
    if (!lyDo) { this.reasonError.set('Lý do là bắt buộc — audit ghi lý do + người.'); return; }
    if (this.reasonMode() === 'dong-chua-tn') {
      const r = this.store.dongCase(this.reasonTarget(), 'tao-nham-trung', lyDo);
      r.ok ? this.msg.success('Đã đóng case Chưa tiếp nhận (lý do + vết audit).') : this.msg.error(r.reason ?? 'Không đóng được.');
    } else {
      const r = this.store.traLoiKhongThuoc(this.reasonTarget(), lyDo);
      r.ok ? this.msg.success('Đã trả lời "không thuộc chế độ" — phản hồi ngược M04 (audit + mã tương quan).') : this.msg.error(r.reason ?? 'Không gửi được.');
    }
    this.dlg?.close();
  }

  protected daDieuChinh(raId: string): void {
    const r = this.store.daDieuChinh(raId);
    r.ok ? this.msg.success('Đã điều chỉnh hồ sơ chế độ — phản hồi ngược M04 (audit + mã tương quan).') : this.msg.error(r.reason ?? 'Không cập nhật được.');
  }
}
