import { ChangeDetectionStrategy, Component, computed, inject, input, linkedSignal, output, signal } from '@angular/core';
import {
  TablerIconComponent,
  IconArrowLeft, IconRefresh, IconDots, IconWallet, IconPercentage,
  IconBuildingHospital, IconAlertTriangle, IconId, IconBuilding, IconBriefcase, IconCalendarEvent,
} from '@tabler/icons-angular';
import { HrmAvatar, HrmButton, HrmMessageService, HrmStatusCell, HrmTag } from 'hrm-ui';
import {
  build360, M06_TABS_360, M06_DEFAULT_TAB_360, M06_TONE_VAR, type M06Tab360,
} from './_m06-360-data';
import { M06_EMP_STATUS, M06_INS_STATUS } from '../search/_m06-search-data';
import { InsM06Tab360Bhxh } from './tabs/tab-bhxh-kcb';
import { InsM06Tab360Context } from './tabs/tab-context';
import { InsM06Tab360History, InsM06Tab360Records } from './tabs/tab-history-records';

/** ═════════ M06 · HỒ SƠ BẢO HIỂM 360° — KHUNG TRANG (Phase build) ═════════
 *  Mental model (§60,79): Current state (identity + 4 summary) → deep-link nghiệp vụ → tab body.
 *  Vào từ trang tra cứu M06-A với `initialTab` đúng ngữ cảnh; header + 4 card dùng chung 8 tab.
 *  ⚠️ ZONELESS: mọi binding deterministic (computed/const/input). Ngày & tiền = chuỗi định dạng sẵn
 *  từ data. Mọi CTA = deep-link demo (HrmMessageService.info) — không wire nav chéo module. */
@Component({
  selector: 'ins-m06-profile-360',
  imports: [
    TablerIconComponent, HrmAvatar, HrmStatusCell, HrmButton, HrmTag,
    InsM06Tab360Bhxh, InsM06Tab360Context, InsM06Tab360History, InsM06Tab360Records,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <!-- ═════ 1 · Breadcrumb ═════ -->
    <nav class="p360-crumb">
      <button type="button" class="p360-crumb__root" (click)="back.emit()" title="Về Trung tâm hồ sơ">
        <tabler-icon [icon]="icBack" [size]="15" />
        <span>Hồ sơ bảo hiểm 360°</span>
      </button>
      <span class="p360-crumb__sep">/</span>
      <span class="p360-crumb__cur">{{ identity().name }}</span>
    </nav>

    <!-- ═════ 2 · Page header ═════ -->
    <header class="p360-head">
      <div class="p360-head__title">
        <h1 class="p360-h1">Hồ sơ Bảo hiểm 360°</h1>
        <p class="p360-sub">Dữ liệu hợp nhất, lịch sử biến động và nguồn ảnh hưởng đến bảo hiểm</p>
      </div>
      <div class="p360-head__actions">
        <span class="p360-sync">
          <span class="p360-sync__dot"></span>
          Đồng bộ lúc {{ identity().lastSyncTime }} · {{ identity().lastSyncDate }}
        </span>
        <hrm-button variant="default" size="sm" (click)="onRefresh()">
          <tabler-icon [icon]="icRefresh" [size]="15" /> Làm mới dữ liệu
        </hrm-button>
      </div>
    </header>

    <!-- ═════ 3 · Identity header ═════ -->
    <section class="p360-card p360-id">
      <div class="p360-id__left">
        <hrm-avatar [text]="identity().name" [colorful]="true" [colorSeed]="identity().id" size="large" />
        <div class="p360-id__meta">
          <div class="p360-id__row1">
            <span class="p360-name">{{ identity().name }}</span>
            <hrm-status-cell [status]="empMeta().tone" [label]="empMeta().label" variant="badge" />
            <hrm-status-cell [status]="insMeta().tone" [label]="insBadgeLabel()" variant="badge" />
          </div>
          <div class="p360-id__row2">
            <span class="p360-chip"><tabler-icon [icon]="icId" [size]="14" /> {{ identity().code }}</span>
            <span class="p360-dot">·</span>
            <span class="p360-chip"><tabler-icon [icon]="icUnit" [size]="14" /> {{ identity().donViLabel }}</span>
            <span class="p360-dot">·</span>
            <span class="p360-chip"><tabler-icon [icon]="icJob" [size]="14" /> {{ identity().jobTitle }}</span>
            <span class="p360-dot">·</span>
            <span class="p360-chip"><tabler-icon [icon]="icCal" [size]="14" /> Ngày vào làm {{ identity().joinDate }}</span>
          </div>
        </div>
      </div>
      <div class="p360-id__right">
        <div class="p360-so">
          <span class="p360-so__label">Số BHXH</span>
          <span class="p360-so__val">{{ identity().soBHXH }}</span>
        </div>
        <div class="p360-create">
          <hrm-button variant="primary" size="sm" (click)="showCreateMenu.set(!showCreateMenu())">Tạo hồ sơ nghiệp vụ</hrm-button>
          @if (showCreateMenu()) {
            <div class="p360-menu">
              <div class="p360-menu__head">Tạo thủ công</div>
              <div class="p360-menu__group">Biến động tham gia</div>
              @for (it of createBienDong; track it) {
                <button type="button" class="p360-menu__item" (click)="taoThuCong(it)">{{ it }}</button>
              }
              <div class="p360-menu__group">Chế độ BHXH</div>
              @for (it of createCheDo; track it) {
                <button type="button" class="p360-menu__item" (click)="taoThuCong(it)">{{ it }}</button>
              }
            </div>
          }
        </div>
        <button type="button" class="p360-more" (click)="onMore()" title="Tùy chọn khác" aria-label="Tùy chọn khác">
          <tabler-icon [icon]="icMore" [size]="18" />
        </button>
      </div>
    </section>

    <!-- ═════ 4 · 4 summary card ═════ -->
    <section class="p360-summary">
      <!-- Card 1 — Mức lương đóng -->
      <div class="p360-card p360-sum">
        <span class="p360-sum__disc" [style.--tone]="'var(--info-base)'"><tabler-icon [icon]="icWallet" [size]="22" /></span>
        <div class="p360-sum__body">
          <span class="p360-sum__label">Mức lương đóng</span>
          <span class="p360-sum__value">{{ salaryDisplay() }}</span>
          <span class="p360-sum__sub">Hiệu lực {{ summary().salaryEffectiveFrom }}</span>
          @if (summary().salaryPrev; as prev) {
            <span class="p360-sum__up">↑ từ {{ prev }} đ</span>
          }
          @if (summary().salaryPending; as sp) {
            <span class="p360-sum__pending">
              <span class="p360-sum__pending-txt">↗ Sắp thay đổi → {{ sp.newValue }} đ từ {{ sp.effectiveDate }}</span>
              <hrm-tag color="orange" size="sm">{{ sp.statusLabel }}</hrm-tag>
            </span>
          }
        </div>
      </div>

      <!-- Card 2 — Tổng tỷ lệ đóng -->
      <div class="p360-card p360-sum">
        <span class="p360-sum__disc" [style.--tone]="'var(--data-4)'"><tabler-icon [icon]="icPercent" [size]="22" /></span>
        <div class="p360-sum__body">
          <span class="p360-sum__label">Tổng tỷ lệ đóng</span>
          <span class="p360-sum__value">{{ summary().totalRatePct }}</span>
          <span class="p360-sum__sub">NLĐ {{ summary().employeeRatePct }} · DN {{ summary().employerRatePct }}</span>
        </div>
      </div>

      <!-- Card 3 — Nơi KCB ban đầu -->
      <div class="p360-card p360-sum">
        <span class="p360-sum__disc" [style.--tone]="'var(--success-base)'"><tabler-icon [icon]="icKcb" [size]="22" /></span>
        <div class="p360-sum__body">
          <span class="p360-sum__label">Nơi KCB ban đầu</span>
          <span class="p360-sum__value p360-sum__value--sm">{{ kcbDisplay() }}</span>
          @if (summary().kcbCode) { <span class="p360-sum__sub">Mã {{ summary().kcbCode }}</span> }
        </div>
      </div>

      <!-- Card 4 — Việc cần xử lý (click → mở panel danh sách việc) -->
      <button type="button" class="p360-card p360-sum p360-sum--btn"
        [class.p360-sum--btn-on]="showTasks()" (click)="showTasks.set(!showTasks())">
        <span class="p360-sum__disc" [style.--tone]="card4ToneVar()"><tabler-icon [icon]="icTask" [size]="22" /></span>
        <div class="p360-sum__body">
          <span class="p360-sum__label">Việc cần xử lý</span>
          <span class="p360-sum__value">{{ summary().pendingTaskCount }}</span>
          <span class="p360-sum__sub">{{ summary().taskHint }}</span>
        </div>
      </button>
    </section>

    <!-- ═════ 4b · Panel việc cần xử lý (§30-31, toggle từ card 4) ═════ -->
    @if (showTasks()) {
      <section class="p360-card p360-tasks">
        <div class="p360-tasks__head">Việc cần xử lý</div>
        @if (profile().tasks.length) {
          <ul class="p360-tasks__list">
            @for (t of profile().tasks; track t.id) {
              <li class="p360-tasks__row">
                <span class="p360-tasks__dot"
                  [style.background]="t.urgent ? 'var(--error-base)' : 'var(--warning-base)'"></span>
                <span class="p360-tasks__title">{{ t.title }}</span>
                <span class="p360-tasks__due">{{ t.due }}</span>
                <button type="button" class="p360-tasks__act" (click)="onTaskAction(t.actionLabel)">{{ t.actionLabel }}</button>
              </li>
            }
          </ul>
          @if (profile().tasks.length > 5) {
            <button type="button" class="p360-tasks__all" (click)="onTaskAction('Xem tất cả')">Xem tất cả</button>
          }
        } @else {
          <div class="p360-tasks__empty">✓ Không có việc cần xử lý</div>
        }
      </section>
    }

    <!-- ═════ 5 · Tab strip ═════ -->
    <nav class="p360-tabs" role="tablist">
      @for (t of tabs; track t.key) {
        <button type="button" class="p360-tab" role="tab"
          [class.p360-tab--active]="t.key === activeTab()"
          [attr.aria-selected]="t.key === activeTab()" (click)="activeTab.set(t.key)">
          {{ t.label }}
        </button>
      }
    </nav>

    <!-- ═════ 6 · Body ═════ -->
    <div class="p360-body">
      @switch (activeTab()) {
        @case ('bhxh-kcb') { <ins-m06-360-bhxh [profile]="profile()" /> }
        @case ('hoso-nv') { <ins-m06-360-context [profile]="profile()" which="hoso-nv" /> }
        @case ('hdld') { <ins-m06-360-context [profile]="profile()" which="hdld" /> }
        @case ('luong') { <ins-m06-360-context [profile]="profile()" which="luong" /> }
        @case ('chamcong') { <ins-m06-360-context [profile]="profile()" which="chamcong" /> }
        @case ('quyetdinh') { <ins-m06-360-context [profile]="profile()" which="quyetdinh" /> }
        @case ('lich-su') { <ins-m06-360-history [profile]="profile()" /> }
        @case ('ho-so-kq') { <ins-m06-360-records [profile]="profile()" /> }
      }
    </div>
  `,
  host: { class: 'ins-m06-profile-360' },
  styles: [`
    :host { display: flex; flex-direction: column; flex: 1 1 auto; min-height: 0; padding: 0 20px; gap: 12px; }

    /* ── Card token chung ── */
    .p360-card {
      background: var(--bg-surface); border: 1px solid var(--border-sub);
      border-radius: 12px; padding: 16px;
    }

    /* ── 1 · Breadcrumb ── */
    .p360-crumb { flex: none; display: flex; align-items: center; gap: 8px; padding-top: 12px; font-size: var(--fs-12); }
    .p360-crumb__root {
      display: inline-flex; align-items: center; gap: 5px; cursor: pointer; font: inherit;
      font-size: var(--fs-12); font-weight: 500; color: var(--text-sub);
      background: none; border: 0; padding: 0;
    }
    .p360-crumb__root:hover { color: var(--primary-base); }
    .p360-crumb__sep { color: var(--text-sub); }
    .p360-crumb__cur { color: var(--text-strong); font-weight: 600; }

    /* ── 2 · Page header ── */
    .p360-head { flex: none; display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; flex-wrap: wrap; }
    .p360-head__title { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
    .p360-h1 { margin: 0; font-size: var(--fs-20, 20px); font-weight: 700; color: var(--text-strong); }
    .p360-sub { margin: 0; font-size: var(--fs-13); color: var(--text-sub); }
    .p360-head__actions { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
    .p360-sync { display: inline-flex; align-items: center; gap: 6px; font-size: var(--fs-12); color: var(--text-sub); }
    .p360-sync__dot { width: 8px; height: 8px; border-radius: 50%; background: var(--success-base); flex: none; }

    /* ── 3 · Identity ── */
    .p360-id { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; }
    .p360-id__left { display: flex; align-items: center; gap: 14px; min-width: 0; }
    .p360-id__meta { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
    .p360-id__row1 { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
    .p360-name { font-size: var(--fs-18, 18px); font-weight: 700; color: var(--text-strong); }
    .p360-id__row2 { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; font-size: var(--fs-12); color: var(--text-sub); }
    .p360-chip { display: inline-flex; align-items: center; gap: 4px; }
    .p360-dot { color: var(--border-strong, var(--text-sub)); }
    .p360-id__right { display: flex; align-items: center; gap: 12px; flex: none; }
    .p360-so { display: flex; flex-direction: column; align-items: flex-end; gap: 1px; }
    .p360-so__label { font-size: var(--fs-12); color: var(--text-sub); }
    .p360-so__val { font-family: var(--font-mono, monospace); font-size: var(--fs-14); font-weight: 700; color: var(--text-strong); }
    .p360-more {
      display: inline-flex; align-items: center; justify-content: center; width: 32px; height: 32px;
      cursor: pointer; color: var(--text-sub); background: none;
      border: 1px solid var(--border-sub); border-radius: var(--radius-md);
    }
    .p360-more:hover { color: var(--primary-base); border-color: var(--primary-base); }
    /* ── 3b · Menu tạo thủ công (§19-20) ── */
    .p360-create { position: relative; display: inline-flex; }
    .p360-menu {
      position: absolute; top: calc(100% + 6px); right: 0; z-index: 20; min-width: 190px;
      display: flex; flex-direction: column; padding: 6px;
      background: var(--bg-surface); border: 1px solid var(--border-sub); border-radius: 10px;
      box-shadow: var(--shadow-sm, 0 4px 12px rgba(0, 0, 0, .08));
    }
    .p360-menu__head { font-size: var(--fs-12); font-weight: 600; color: var(--text-strong); padding: 4px 8px 6px; }
    .p360-menu__group { font-size: var(--fs-11, 11px); font-weight: 600; text-transform: uppercase; letter-spacing: .03em; color: var(--text-sub); padding: 6px 8px 2px; }
    .p360-menu__item {
      display: flex; align-items: center; cursor: pointer; font: inherit; text-align: left;
      font-size: var(--fs-13); color: var(--text-strong); background: none; border: 0; padding: 7px 8px; border-radius: 6px;
    }
    .p360-menu__item:hover { background: color-mix(in srgb, var(--primary-base) 8%, transparent); color: var(--primary-base); }

    /* ── 4 · Summary ── */
    .p360-summary { flex: none; display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; }
    .p360-sum { display: flex; align-items: center; gap: 12px; }
    .p360-sum--btn { cursor: pointer; text-align: left; font: inherit; }
    .p360-sum--btn:hover { border-color: var(--primary-base); }
    .p360-sum__disc {
      flex: none; width: 44px; height: 44px; border-radius: 50%;
      display: inline-flex; align-items: center; justify-content: center;
      color: var(--tone); background: color-mix(in srgb, var(--tone) 14%, transparent);
    }
    .p360-sum__body { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
    .p360-sum__label { font-size: var(--fs-12); color: var(--text-sub); }
    .p360-sum__value { font-size: var(--fs-20, 20px); font-weight: 700; color: var(--text-strong); line-height: 1.2; }
    .p360-sum__value--sm { font-size: var(--fs-16); }
    .p360-sum__sub { font-size: var(--fs-12); color: var(--text-sub); }
    .p360-sum__up { font-size: var(--fs-11, 11px); font-weight: 600; color: var(--success-base); }
    /* §9,14 chip "sắp thay đổi" (mức đề xuất đang chờ) — KHÔNG ghi đè value hiện tại */
    .p360-sum__pending { display: inline-flex; align-items: center; gap: 6px; flex-wrap: wrap; margin-top: 1px; }
    .p360-sum__pending-txt { font-size: var(--fs-11, 11px); font-weight: 600; color: var(--warning-base); }
    .p360-sum--btn-on { border-color: var(--primary-base); }
    @media (max-width: 900px) { .p360-summary { grid-template-columns: repeat(2, 1fr); } }

    /* ── 4b · Panel việc cần xử lý (§30-31) ── */
    .p360-tasks { flex: none; display: flex; flex-direction: column; gap: 8px; box-shadow: var(--shadow-sm, 0 4px 12px rgba(0, 0, 0, .08)); }
    .p360-tasks__head { font-size: var(--fs-13); font-weight: 600; color: var(--text-strong); }
    .p360-tasks__list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 2px; }
    .p360-tasks__row { display: flex; align-items: center; gap: 10px; padding: 8px 6px; border-radius: 8px; }
    .p360-tasks__row:hover { background: color-mix(in srgb, var(--text-strong) 5%, transparent); }
    .p360-tasks__dot { flex: none; width: 8px; height: 8px; border-radius: 50%; }
    .p360-tasks__title { font-size: var(--fs-13); font-weight: 600; color: var(--text-strong); min-width: 0; }
    .p360-tasks__due { font-size: var(--fs-12); color: var(--text-sub); }
    .p360-tasks__act {
      margin-left: auto; flex: none; cursor: pointer; font: inherit;
      font-size: var(--fs-12); font-weight: 500; color: var(--primary-base);
      background: none; border: 1px solid var(--border-sub); border-radius: var(--radius-md, 8px); padding: 3px 10px;
    }
    .p360-tasks__act:hover { border-color: var(--primary-base); background: color-mix(in srgb, var(--primary-base) 8%, transparent); }
    .p360-tasks__all { align-self: flex-start; cursor: pointer; font: inherit; font-size: var(--fs-12); font-weight: 500; color: var(--primary-base); background: none; border: 0; padding: 2px 0; }
    .p360-tasks__empty { font-size: var(--fs-13); color: var(--text-sub); font-weight: 500; }

    /* ── 5 · Tab strip ── */
    .p360-tabs { flex: none; display: flex; gap: 2px; border-bottom: 1px solid var(--border-sub); overflow-x: auto; }
    .p360-tab {
      position: relative; display: inline-flex; align-items: center; gap: 6px; flex: none;
      border: 0; background: none; cursor: pointer; padding: 8px 12px 10px;
      font: inherit; font-size: var(--fs-13); color: var(--text-sub); white-space: nowrap;
    }
    .p360-tab:hover { color: var(--text-strong); }
    .p360-tab--active { color: var(--primary-base); font-weight: 600; }
    .p360-tab--active::after {
      content: ''; position: absolute; left: 10px; right: 10px; bottom: -1px; height: 2px;
      background: var(--primary-base); border-radius: var(--radius-full);
    }

    /* ── 6 · Body ── */
    .p360-body { flex: 1 1 auto; min-height: 0; overflow: auto; display: flex; flex-direction: column; padding: 4px 0 16px; }
  `],
})
export class InsM06Profile360 {
  private readonly msg = inject(HrmMessageService);

  /** Ngữ cảnh vào trang (từ M06-A). */
  readonly nhanVienId = input.required<string>();
  readonly initialTab = input<M06Tab360>(M06_DEFAULT_TAB_360);
  readonly back = output<void>();

  /** Tab đang mở — reset theo `initialTab` khi input đổi, user click chuyển được. */
  protected readonly activeTab = linkedSignal(() => this.initialTab());
  protected readonly tabs = M06_TABS_360;

  /** Panel bật/tắt (signal, không dùng modal service — §30-31 việc cần xử lý / §19-20 tạo thủ công). */
  protected readonly showTasks = signal(false);
  protected readonly showCreateMenu = signal(false);

  /** §19 menu tạo thủ công — 2 nhóm nghiệp vụ. */
  protected readonly createBienDong = ['Báo tăng', 'Báo giảm', 'Điều chỉnh'] as const;
  protected readonly createCheDo = ['Ốm đau', 'Thai sản', 'Dưỡng sức'] as const;

  /** Hồ sơ 360 hợp nhất (deterministic, cache theo id). */
  protected readonly profile = computed(() => build360(this.nhanVienId()));
  protected readonly identity = computed(() => this.profile().identity);
  protected readonly summary = computed(() => this.profile().summary);

  /** Trạng thái làm việc / tham gia (nhãn + tông từ bảng tra dùng chung). */
  protected readonly empMeta = computed(() => M06_EMP_STATUS[this.identity().employmentStatus]);
  protected readonly insMeta = computed(() => M06_INS_STATUS[this.identity().insuranceStatus]);
  protected readonly insBadgeLabel = computed(() =>
    this.identity().insuranceStatus === 'dang-tham-gia' ? 'Đang tham gia BHXH' : this.insMeta().label);

  /** Hiển thị mức lương / nơi KCB thân thuộc (§64) — tránh "0 đ" / "—" trơ. */
  protected readonly salaryDisplay = computed(() => {
    const s = this.summary().insuranceSalary;
    return !s || s === '0' ? 'Chưa áp dụng' : s + ' đ';
  });
  protected readonly kcbDisplay = computed(() => {
    const k = this.summary().kcbName;
    return !k || k === '—' ? 'Chưa đăng ký' : k;
  });

  /** Card "Việc cần xử lý": warning khi có việc, neutral khi rỗng (không cảnh báo thừa). */
  protected readonly card4ToneVar = computed(() =>
    'var(' + M06_TONE_VAR[this.summary().pendingTaskCount > 0 ? 'warning' : 'neutral'] + ')');

  /* ── Icons ── */
  protected readonly icBack = IconArrowLeft;
  protected readonly icRefresh = IconRefresh;
  protected readonly icMore = IconDots;
  protected readonly icWallet = IconWallet;
  protected readonly icPercent = IconPercentage;
  protected readonly icKcb = IconBuildingHospital;
  protected readonly icTask = IconAlertTriangle;
  protected readonly icId = IconId;
  protected readonly icUnit = IconBuilding;
  protected readonly icJob = IconBriefcase;
  protected readonly icCal = IconCalendarEvent;

  /* ── Deep-link demo (prototype) ── */
  protected onRefresh(): void { this.msg.info('Làm mới dữ liệu hồ sơ từ các nguồn (demo)'); }
  protected onMore(): void { this.msg.info('Tùy chọn khác cho hồ sơ (demo)'); }
  /** §30-31 hành động trên 1 việc (hoặc "Xem tất cả"). */
  protected onTaskAction(label: string): void { this.msg.info(label + ' (demo)'); }
  /** §19-20 tạo thủ công + chống trùng: "Điều chỉnh" đã có hồ sơ chờ → cảnh báo thay vì tạo trùng. */
  protected taoThuCong(item: string): void {
    this.showCreateMenu.set(false);
    if (item === 'Điều chỉnh') this.msg.warning('⚠ Đã có hồ sơ tương tự đang chờ xử lý (demo)');
    else this.msg.info('Tạo ' + item + ' thủ công (demo)');
  }
}
