export type M01Tone = 'success' | 'error' | 'warning' | 'info' | 'primary' | 'violet';
export type M01IconKey = 'up' | 'down' | 'edit' | 'alert' | 'users' | 'check' | 'clock';

/** Row1 — thẻ thống kê lớn (icon tròn tone + số lớn + 2–3 dòng phụ + link M02). */
export interface M01StatCard {
  key: string;            // filter key → M02
  ten: string;
  tone: M01Tone;
  icon: M01IconKey;
  so: string;
  sub: string[];
}
/** Mini-tile / stat-tile (số lớn màu + nhãn nhỏ). */
export interface M01Tile { nhan: string; so: string; tone: M01Tone; noi?: boolean; }
/** Lát donut + dòng legend (● tên · số · %). cvar = token màu ngữ nghĩa (khớp tone stat card + ảnh). */
export interface M01DonutSlice { name: string; value: number; pct: string; cvar: string; }
/** Hàng bảng "Tổng hợp theo loại". */
export interface M01TableRow { loai: string; tong: string; cho: string; san: string; dot: string; bold?: boolean; }
/** Bullet AI (icon tròn nhạt + câu, phần đậm tách riêng). */
export interface M01Bullet { icon: M01IconKey; tone: M01Tone; pre: string; strong: string; post: string; }
/** Mốc pipeline (icon tròn + nhãn + số). */
export interface M01PipeStep { nhan: string; so: string; tone: M01Tone; }
/** Hàng bar-list "Phân bố theo chế độ" (ptc = % số → độ rộng thanh). */
export interface M01BarRow { che: string; so: string; pct: string; ptc: number; tone: M01Tone; bold?: boolean; }
/** Dòng ký & nộp / tiền. */
export interface M01Line { icon: M01IconKey; tone: M01Tone; so: string; nhan: string; }
export interface M01MoneyRow { nhan: string; tien: string; tone?: M01Tone; }

interface M01Overview {
  title: string;
  kyLabel: string;
  kyOption: { label: string; value: string };
  chipHanChot: string;
  statCards: M01StatCard[];
  bienDongTiles: M01Tile[];
  donut: M01DonutSlice[];
  donutTotal: string;
  tongHop: M01TableRow[];
  aiBanner: { pre: string; strong: string; post: string };
  bullets: M01Bullet[];
  pipeline: M01PipeStep[];
  kyRange: string;
  cheDoTiles: M01Tile[];
  cheDoBars: M01BarRow[];
  cheDoMoney: M01MoneyRow[];
  cheDoSoHoSo: string;
  kyNop: M01Line[];
  doiSoat: M01MoneyRow[];
  doiSoatCanhBao: string;
}

