import { ChangeDetectionStrategy, Component, TemplateRef, computed, inject, output, signal, viewChild } from '@angular/core';
import { FormsModule } from '@angular/forms';
import {
  IconArrowBackUp, IconCircleMinus, IconPlayerPlay, IconRefresh, IconTool, TablerIconComponent,
} from '@tabler/icons-angular';
import {
  HrmButton, HrmGrid, HrmGridColumn, HrmMessageService, HrmSelect, HrmStatusCell,
} from 'hrm-ui';
import { InsSectionLabel } from '../_shared';
import { InsShellStore } from '../_data/_core';
import { InsM03Store } from '../_data/_m03-data';
import {
  DongLoiRow, M03_DONGLOI_COLS, M03_DONGLOI_MIN_WIDTH, M03_RUN_COLS, M03_RUN_MIN_WIDTH,
  RunRow, buildDongLoiRow, buildRunRow,
} from './_m03-columns';

/** ═════════ M03 — RUN-ZONE (Kết quả xử lý lô) ═════════
 *  InsM03RunZone 'ins-m03-run-zone' (no input) · `output reason` — HÀNH ĐỘNG BẮT BUỘC LÝ DO
 *  (loại trừ dòng lỗi) EMIT lên host; host sở hữu reason-prompt modal + selectedLoId.
 *  Bám JOB B (SC-B2 Bước③④) + `_rebuild/01-requirements/m03.md`. Column defs + row-VM import từ './_m03-columns'.
 *  ⚠️ Zoneless + OnPush + standalone: mọi collection = computed(); tiền/ngày = chuỗi seed; label/tone = const map;
 *  KHÔNG Date.now()/new Date()/Math.random() trong template/getter/computed (mutation chỉ trong click handler,
 *  qua store method). Nút bị chặn LUÔN kèm lý do (disabled-có-lý-do — không khóa câm). */

/** Yêu cầu nhập lý do BẮT BUỘC gửi lên host (host mở reason-prompt modal → gọi đúng store method). */
export interface InsM03ReasonReq {
  /** `dongloi-loai-tru` → store.dongLoiLoaiTru(id, lyDo) · `ketqua-loai-tru` → loại trừ dòng kết quả bị từ chối. */
  mode: 'dongloi-loai-tru' | 'ketqua-loai-tru';
  id: string;
}

/* ═════════════════════════ RUN-ZONE — Kết quả xử lý lô (chạy nền + dòng lỗi) ═════════════════════════
 *  Lần chạy nền = grid 5 trạng thái + đường vào a/b · "Chạy lại phần thất bại" (idempotent, không sinh trùng) ·
 *  "Chọn đợt" phân tích CHẶN CHỌN LÙI (đợt phải lớn hơn đợt đã chạy).
 *  Dòng lỗi = grid 4 trạng thái; mỗi dòng "Chờ xử lý" có 3 đường ra: Sửa tại chỗ (dongLoiSuaTaiCho) ·
 *  Trả về M02 (dongLoiTraVe02 → điều hướng 2 chiều) · Loại trừ (dongLoiLoaiTru → EMIT reason bắt buộc). */
@Component({
  selector: 'ins-m03-run-zone',
  imports: [FormsModule, TablerIconComponent, HrmButton, HrmGrid, HrmSelect, HrmStatusCell, InsSectionLabel],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <section class="rz__sec">
      <div class="rz__head">
        <ins-section-label text="Kết quả xử lý lô (chạy nền — rời màn quay lại vẫn xem)" tone="attention" [count]="runRows().length" />
        <span class="rz__gap"></span>
        <hrm-select class="rz__dot" [(ngModel)]="dotModel" [options]="dotOptions" size="sm" [allowClear]="false" [showSearch]="false" />
        <hrm-button size="sm" [disabled]="locked() || !!dotReason()" (click)="sinhBienDong()">
          <tabler-icon [icon]="icRun" [size]="15" /> Sinh biến động (nền)</hrm-button>
      </div>
      @if (dotReason(); as r) { <p class="rz__block">{{ r }}</p> }

      <hrm-grid [columns]="runCols()" [data]="runRows()" rowKey="id" density="compact" [showPagination]="false" [minWidth]="runMinWidth" />

      <ins-section-label text="Dòng lỗi (4 trạng thái · mỗi 'Chờ xử lý' có 3 đường ra)" tone="critical" [count]="dongLoiRows().length" />
      <hrm-grid [columns]="dlCols()" [data]="dongLoiRows()" rowKey="id" density="compact" [showPagination]="false" [minWidth]="dlMinWidth" />
      @if (locked()) { <p class="rz__note">Kỳ đã khóa còn dòng lỗi → chỉ còn "Trả về M02" / "Loại trừ có lý do".</p> }
      @if (!dongLoiRows().length && !runRows().length) { <p class="rz__note">Kỳ này chưa có lần chạy nền nào — bấm "Sinh biến động (nền)".</p> }
    </section>

    <!-- ── cell templates: lần chạy nền ── -->
    <ng-template #runMetaCell let-row>
      <div class="rz__stack"><span>{{ $any(row).thoiDiem }}</span><span class="rz__muted">{{ $any(row).nguoi }} · {{ $any(row).duongVao }}</span></div>
    </ng-template>
    <ng-template #runSoLieuCell let-row>
      <span class="rz__strong">{{ $any(row).soLieu }}</span>
      @if ($any(row).coThatBai) { <span class="rz__muted" [title]="$any(row).lyDoText"> · {{ $any(row).lyDoText }}</span> }
    </ng-template>
    <ng-template #runStatusCell let-row>
      <hrm-status-cell [status]="$any(row).trangThaiTone" [label]="$any(row).trangThaiLabel" variant="badge" />
    </ng-template>
    <ng-template #runActCell let-row>
      @if ($any(row).coThatBai) {
        <hrm-button size="sm" [disabled]="locked()" (click)="chayLai($any(row).id)">
          <tabler-icon [icon]="icRetry" [size]="14" /> Chạy lại phần thất bại</hrm-button>
      } @else { <span class="rz__muted">—</span> }
    </ng-template>

    <!-- ── cell templates: dòng lỗi ── -->
    <ng-template #dlUserCell let-row>
      <div class="rz__stack"><span class="rz__strong">{{ $any(row).ten }}</span><span class="rz__muted">{{ $any(row).sub }}</span></div>
    </ng-template>
    <ng-template #dlStatusCell let-row>
      <hrm-status-cell [status]="$any(row).trangThaiTone" [label]="$any(row).trangThaiLabel" variant="badge" />
    </ng-template>
    <ng-template #dlActCell let-row>
      @if ($any(row).cho) {
        <div class="rz__acts">
          <hrm-button size="sm" [disabled]="locked()" (click)="suaTaiCho($any(row).id)"><tabler-icon [icon]="icFix" [size]="14" /> Sửa tại chỗ</hrm-button>
          <hrm-button size="sm" (click)="traVe02($any(row).id)"><tabler-icon [icon]="icBack" [size]="14" /> Trả về M02</hrm-button>
          <hrm-button size="sm" [danger]="true" (click)="loaiTru($any(row).id)"><tabler-icon [icon]="icExclude" [size]="14" /> Loại trừ</hrm-button>
        </div>
      } @else { <span class="rz__muted">—</span> }
    </ng-template>
  `,
  host: { class: 'ins-m03-run-zone' },
  styles: [`
    :host { display: block; }
    .rz__sec { display: flex; flex-direction: column; gap: 8px; padding-top: 10px; border-top: 1px solid var(--border-soft); }
    .rz__head { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
    .rz__gap { flex: 1; }
    .rz__dot { display: inline-block; width: 120px; }
    .rz__stack { display: flex; flex-direction: column; gap: 1px; min-width: 0; align-items: flex-start; }
    .rz__strong { color: var(--text-strong); font-weight: 500; }
    .rz__muted { font-size: var(--fs-12); color: var(--text-sub); }
    .rz__block { margin: 0; font-size: var(--fs-12); color: var(--error-text); }
    .rz__note { margin: 0; font-size: var(--fs-12); color: var(--warning-text); }
    .rz__acts { display: flex; gap: 6px; justify-content: flex-end; flex-wrap: wrap; }
  `],
})
export class InsM03RunZone {
  protected readonly store = inject(InsM03Store);
  private readonly shell = inject(InsShellStore);
  private readonly msg = inject(HrmMessageService);

  /** Loại trừ dòng lỗi = lý do BẮT BUỘC → EMIT lên host (host mở reason-prompt modal, gọi store.dongLoiLoaiTru). */
  readonly reason = output<InsM03ReasonReq>();

  protected readonly icRun = IconPlayerPlay;
  protected readonly icRetry = IconRefresh;
  protected readonly icFix = IconTool;
  protected readonly icBack = IconArrowBackUp;
  protected readonly icExclude = IconCircleMinus;
  protected readonly runMinWidth = M03_RUN_MIN_WIDTH;
  protected readonly dlMinWidth = M03_DONGLOI_MIN_WIDTH;

  protected readonly locked = computed(() => this.store.kyLocked());
  protected readonly runRows = computed<RunRow[]>(() => this.store.lanChayOfKy().map(buildRunRow));
  protected readonly dongLoiRows = computed<DongLoiRow[]>(() => this.store.dongLoiOfKy().map(buildDongLoiRow));

  /* đợt phân tích — CHẶN CHỌN LÙI (đợt phải lớn hơn đợt đã phân tích) = disabled-có-lý-do. */
  protected readonly dotOptions = [1, 2, 3, 4, 5].map((d) => ({ value: d, label: `Đợt ${d}` }));
  private readonly dot = signal(4);
  protected get dotModel(): unknown { return this.dot(); }
  protected set dotModel(v: unknown) { this.dot.set(Number(v) || 1); }
  protected readonly dotReason = computed(() => {
    const cur = this.store.dotHienTai();
    return this.dot() <= cur ? `Đã phân tích đến đợt ${cur} — chỉ chọn đợt lớn hơn (không được chọn lùi).` : null;
  });

  protected sinhBienDong(): void {
    const r = this.store.phanTichDot(this.dot());
    r.ok
      ? this.msg.success(`Đã chạy nền đợt ${this.dot()} — dòng đã nộp KHÔNG bị xóa khi chạy lại; theo dõi tiến độ ở bảng lần chạy.`)
      : this.msg.error(r.reason ?? 'Không chạy được.');
  }
  protected chayLai(lanChayId: string): void {
    const r = this.store.chayLaiPhanThatBai(lanChayId);
    r.ok
      ? this.msg.success(`Đã chạy lại ${r.done} dòng thất bại (idempotent — chỉ phần thất bại, không sinh trùng).`)
      : this.msg.warning(r.reason ?? 'Không chạy lại được.');
  }
  protected suaTaiCho(id: string): void {
    const r = this.store.dongLoiSuaTaiCho(id);
    r.ok ? this.msg.success('Đã sửa tại chỗ — dòng chuyển "Đã sửa và đưa vào lần chạy lại".') : this.msg.error(r.reason ?? 'Không sửa được.');
  }
  protected traVe02(id: string): void {
    const r = this.store.dongLoiTraVe02(id);
    if (!r.ok) { this.msg.error(r.reason ?? 'Không trả về được.'); return; }
    this.msg.success('Đã trả dòng lỗi về M02 — mở Tab Dữ liệu ngoại lệ (liên kết 2 chiều).');
    this.shell.go('m02', { ky: this.store.kyId(), donVi: this.store.donViId(), filter: 'tab5:bi-tra-lai-tu-lo' });
  }
  /** Loại trừ dòng lỗi — EMIT reason lên host (lý do BẮT BUỘC, append-only, không xóa). */
  protected loaiTru(id: string): void { this.reason.emit({ mode: 'dongloi-loai-tru', id }); }

  private readonly runMetaTpl = viewChild.required<TemplateRef<unknown>>('runMetaCell');
  private readonly runSoLieuTpl = viewChild.required<TemplateRef<unknown>>('runSoLieuCell');
  private readonly runStatusTpl = viewChild.required<TemplateRef<unknown>>('runStatusCell');
  private readonly runActTpl = viewChild.required<TemplateRef<unknown>>('runActCell');
  private readonly dlUserTpl = viewChild.required<TemplateRef<unknown>>('dlUserCell');
  private readonly dlStatusTpl = viewChild.required<TemplateRef<unknown>>('dlStatusCell');
  private readonly dlActTpl = viewChild.required<TemplateRef<unknown>>('dlActCell');

  protected readonly runCols = computed<HrmGridColumn[]>(() => {
    const tpl: Record<string, TemplateRef<unknown> | undefined> = {
      thoiDiem: this.runMetaTpl(), soLieu: this.runSoLieuTpl(), trangThai: this.runStatusTpl(), act: this.runActTpl(),
    };
    return M03_RUN_COLS.map((d) => ({ ...d, cell: tpl[d.key] as HrmGridColumn['cell'] }));
  });
  protected readonly dlCols = computed<HrmGridColumn[]>(() => {
    const tpl: Record<string, TemplateRef<unknown> | undefined> = {
      ten: this.dlUserTpl(), trangThai: this.dlStatusTpl(), act: this.dlActTpl(),
    };
    return M03_DONGLOI_COLS.map((d) => ({ ...d, cell: tpl[d.key] as HrmGridColumn['cell'] }));
  });
}
