import { ChangeDetectionStrategy, Component, computed, inject, input, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { HrmButton, HrmGrid, HrmGridColumn, HrmInput, HrmMessageService, HrmTag } from 'hrm-ui';
import { InsM05Store } from '../../_data/_m05-data';
import { InsM06Store } from '../../_data/_m06-data';
import { InsM07Store } from '../../_data/_m07-data';

/** Nhóm "Nhật ký kiểm toán" (M07-B): lưới sự kiện đọc SỐNG từ audit các store —
 *  MỌI THAO TÁC GHI CỦA M07-A là nguồn sự kiện bắt buộc + dòng M05/M06 (import tiện).
 *  3 mục: sự kiện ghi · truy cập nhạy cảm · nhật ký xuất tệp. XUẤT NHẬT KÝ TỰ GHI NHẬT KÝ. */
@Component({
  selector: 'ins-m07-audit-tab',
  imports: [FormsModule, HrmButton, HrmGrid, HrmInput, HrmTag],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="au">
      <div class="au-head">
        <hrm-input class="au-kw" [(ngModel)]="kwModel" size="sm" [clearable]="true" placeholder="Lọc theo người / hành động / đối tượng…" />
        <hrm-tag size="sm" color="default">nguồn: InsM07Store (bắt buộc) + InsM05Store + InsM06Store (sống)</hrm-tag>
        <span class="au-gap"></span>
        <hrm-button size="sm" (click)="xuatNhatKy()">Xuất nhật ký (tự ghi nhật ký)</hrm-button>
      </div>
      <hrm-grid [columns]="cols" [data]="rows()" rowKey="key" density="compact" [pageSize]="12" [minWidth]="'980px'" />
      <p class="au-note">Append-only (bất biến #3) — before/after giữ trong cột Trước/Sau; lượt truy cập nhạy cảm (kể cả bị từ chối) đều ghi.</p>
    </div>
  `,
  host: { class: 'ins-m07-audit-tab' },
  styles: [`
    :host { display: block; }
    .au { display: flex; flex-direction: column; gap: 10px; }
    .au-head { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
    .au-kw { display: inline-block; width: 300px; }
    .au-gap { flex: 1; }
    .au-note { margin: 0; font-size: var(--fs-11); color: var(--text-soft); }
  `],
})
export class InsM07AuditTab {
  private readonly m07 = inject(InsM07Store);
  private readonly m05 = inject(InsM05Store);
  private readonly m06 = inject(InsM06Store);
  private readonly msg = inject(HrmMessageService);

  /** 'nk-su-kien' | 'nk-nhay-cam' | 'nk-xuat-tep'. */
  readonly mode = input<string>('nk-su-kien');

  private readonly kw = signal('');
  protected get kwModel(): string { return this.kw(); }
  protected set kwModel(v: string) { this.kw.set(v ?? ''); }

  protected readonly cols: HrmGridColumn[] = [
    { key: 'at', title: 'Thời điểm', width: '150px' },
    { key: 'nguoi', title: 'Người', width: '160px' },
    { key: 'hanhDong', title: 'Hành động' },
    { key: 'doiTuong', title: 'Đối tượng', width: '170px' },
    { key: 'truocSau', title: 'Trước → Sau', width: '220px' },
    { key: 'nguon', title: 'Phân hệ', width: '90px' },
  ];

  protected readonly rows = computed<Record<string, unknown>[]>(() => {
    const mode = this.mode();
    let list = this.m07.audit().map((e, i) => ({
      key: `m07-${i}`, at: e.at, nguoi: e.nguoi, hanhDong: e.hanhDong, doiTuong: e.doiTuong ?? '—',
      truocSau: e.truoc || e.sau ? `${e.truoc ?? '—'} → ${e.sau ?? '—'}` : (e.lyDo ? `lý do: ${e.lyDo}` : '—'),
      nguon: 'M07', loai: e.loai,
    }));
    if (mode === 'nk-nhay-cam') list = list.filter((e) => e.loai === 'truy-cap');
    else if (mode === 'nk-xuat-tep') list = list.filter((e) => e.loai === 'xuat');
    else {
      const m05Rows = this.m05.audit().slice(0, 5).map((e, i) => ({
        key: `m05-${i}`, at: e.at, nguoi: e.nguoi, hanhDong: e.hanhDong, doiTuong: e.caseIds.join(', ') || '—',
        truocSau: e.lyDo ? `lý do: ${e.lyDo}` : '—', nguon: 'M05', loai: 'ghi' as const,
      }));
      const m06Rows = this.m06.audit().slice(0, 5).map((e, i) => ({
        key: `m06-${i}`, at: e.at, nguoi: e.nguoi, hanhDong: e.hanhDong, doiTuong: e.nhanVienId ?? '—',
        truocSau: e.truoc || e.sau ? `${e.truoc ?? '—'} → ${e.sau ?? '—'}` : '—', nguon: 'M06', loai: 'ghi' as const,
      }));
      list = [...list, ...m05Rows, ...m06Rows];
    }
    const kw = this.kw().trim().toLowerCase();
    if (kw) list = list.filter((e) => `${e.nguoi} ${e.hanhDong} ${e.doiTuong}`.toLowerCase().includes(kw));
    return list;
  });

  /** Xuất nhật ký CŨNG là 1 sự kiện xuất (tự ghi nhật ký). */
  protected xuatNhatKy(): void {
    const id = this.m07.taoTepXuat(
      `NHAT-KY_${this.mode()}_ky08-2026.xlsx`, 'BC-TH — Tổng hợp theo kỳ', 'v2026.1 (hiệu lực 01/07/2026)',
      'Kỳ 08/2026 · nhật ký kiểm toán');
    setTimeout(() => this.m07.tepSanSang(id), 1200);
    this.msg.success(`Đang tạo tệp ${id} — thao tác xuất nhật ký đã tự ghi 1 dòng nhật ký.`);
  }
}
