import {
  ChangeDetectionStrategy, Component, TemplateRef, computed, effect, inject, output, signal, untracked, viewChild,
} from '@angular/core';
import { FormsModule } from '@angular/forms';
import {
  IconAlertTriangle, IconCopy, IconDotsVertical, IconEye, IconFileExport, IconFilter,
  IconHeartHandshake, IconHistory, IconRefresh, IconSearch, IconColumns3, TablerIconComponent,
} from '@tabler/icons-angular';
import { NzDropDownModule } from 'ng-zorro-antd/dropdown';
import { NzMenuModule } from 'ng-zorro-antd/menu';
import { NzPopoverModule } from 'ng-zorro-antd/popover';
import {
  HrmButton, HrmCheckbox, HrmCrumb, HrmDataView, HrmEmpty, HrmGridColumn, HrmInput, HrmInputNumber,
  HrmListPage, HrmMessageService, HrmSelect, HrmStatusCell, HrmUserCell,
} from 'hrm-ui';
import {
  M06SearchFilter, M06SearchRow, M06StatusMeta,
  M06_DON_VI_OPTIONS, M06_EMP_STATUS, M06_EMP_STATUS_OPTIONS, M06_INS_STATUS, M06_INS_STATUS_OPTIONS,
  M06_KCB_OPTIONS, M06_QUICK_FILTERS, M06QuickFilter, M06_SEARCH_ROWS,
  m06AdvancedCount, m06EmptyFilter, m06MatchesFilter, m06MatchesKeyword, m06MatchesQuickFilter,
  m06Money, m06QuickFilterCount,
} from './_m06-search-data';

/** Chuỗi ngày 'dd/MM/yyyy' → số yyyymmdd để SẮP XẾP (deterministic, không Date). '' → 0. */
function dmyToNum(s: string): number {
  const m = /^(\d{2})\/(\d{2})\/(\d{4})$/.exec(s ?? '');
  return m ? Number(m[3] + m[2] + m[1]) : 0;
}
/** 'HH:mm' → HHmm (deterministic). '' → 0. */
function hmToNum(s: string): number {
  const m = /^(\d{2}):(\d{2})$/.exec(s ?? '');
  return m ? Number(m[1] + m[2]) : 0;
}

/** Dòng hiển thị = M06SearchRow + khoá sắp xếp numeric + meta badge dựng sẵn (ổn định, zoneless-safe). */
interface M06DisplayRow extends M06SearchRow {
  salaryNum: number;
  movementSort: number;
  syncSort: number;
  empMeta: M06StatusMeta;
  insMeta: M06StatusMeta;
  kcbDisplay: string;
  taskTone: 'error' | 'warning' | 'muted';
}

function toDisplay(r: M06SearchRow): M06DisplayRow {
  return {
    ...r,
    salaryNum: m06Money(r.insuranceSalary),
    movementSort: dmyToNum(r.lastMovementDate),
    syncSort: dmyToNum(r.lastSyncDate) * 10000 + hmToNum(r.lastSyncTime),
    empMeta: M06_EMP_STATUS[r.employmentStatus],
    insMeta: M06_INS_STATUS[r.insuranceStatus],
    kcbDisplay: r.kcbCode ? r.kcbName : 'Chưa đăng ký',
    taskTone: r.taskPriority === 'urgent' ? 'error' : r.taskPriority === 'warn' ? 'warning' : 'muted',
  };
}

/** Toàn bộ dataset ở dạng hiển thị — dựng MỘT lần (const, không tính lại mỗi render). */
const M06_DISPLAY_ROWS: readonly M06DisplayRow[] = M06_SEARCH_ROWS.map(toDisplay);

/** ═════════ M06-A — TRA CỨU HỒ SƠ BẢO HIỂM (list-page, đứng TRƯỚC Hồ sơ 360) ═════════
 *  Kế thừa template "Chế độ xem dữ liệu" (hrm-list-page): breadcrumb · title · subtitle ·
 *  [filters] (search rộng + quick-filter chips toggle + nút Bộ lọc mở popover 4 nhóm A/B/C/D) ·
 *  [actions] (⋮ Xuất Excel · Làm mới · Tùy chỉnh cột) · hrm-data-view bảng 11 cột (ẩn dv-bar) ·
 *  phân trang (pageSize 20). CLICK CẢ DÒNG → open360.emit(id) → mở Hồ sơ Bảo hiểm 360.
 *  Search + quick-filter + advanced dùng CHUNG filtered computed (giao ∩). Zoneless: mọi giá trị
 *  deterministic (chuỗi ngày/tiền sẵn, khoá sort numeric dựng sẵn) — không random/Date.now render path. */
@Component({
  selector: 'ins-m06-search',
  imports: [
    FormsModule, TablerIconComponent, NzDropDownModule, NzMenuModule, NzPopoverModule,
    HrmButton, HrmCheckbox, HrmDataView, HrmEmpty, HrmInput, HrmInputNumber,
    HrmListPage, HrmSelect, HrmStatusCell, HrmUserCell,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <hrm-list-page class="m06-lp"
      [breadcrumb]="crumbs"
      [title]="'Tra cứu Hồ sơ bảo hiểm'"
      [subtitle]="'Tìm và xem tình trạng bảo hiểm của người lao động'"
      [total]="total()" [(pageIndex)]="pageIndexModel" [(pageSize)]="pageSizeModel"
      [showSizeChanger]="true" [panel]="true">

      <!-- Toolbar TRÁI: search rộng + quick-filter chips toggle + nút Bộ lọc (badge số điều kiện). -->
      <div filters class="m06-filters">
        <hrm-input class="m06-kw" [(ngModel)]="kwModel" size="md" [prefixIcon]="icSearch" [clearable]="true"
          placeholder="Tìm NLĐ, mã NV, số BHXH…" />

        <div class="m06-chips">
          @for (q of quickFilters; track q.key) {
            <button type="button" class="m06-chip" [class.m06-chip--on]="activeQF() === q.key"
              (click)="toggleQF(q.key)">
              {{ q.label }}@if (q.showCount) { <span class="m06-chip__n">{{ canXuLyCount }}</span> }
            </button>
          }
        </div>

        <button type="button" class="m06-fbtn" [class.m06-fbtn--on]="advancedCount() > 0"
          nz-popover nzPopoverTrigger="click" [nzPopoverContent]="filterPanel"
          nzPopoverPlacement="bottomLeft" nzPopoverOverlayClassName="m06-fpop"
          [(nzPopoverVisible)]="popOpenModel">
          <tabler-icon [icon]="icFilter" [size]="16" /> Bộ lọc
          @if (advancedCount() > 0) { <span class="m06-fbtn__badge">{{ advancedCount() }}</span> }
        </button>
      </div>

      <!-- Toolbar PHẢI: ⋮ More — Xuất Excel · Làm mới · Tùy chỉnh cột. -->
      <div actions class="m06-actions">
        <button type="button" class="m06-more" aria-label="Thêm thao tác" title="Thêm thao tác"
          [nzDropdownMenu]="moreMenu" nz-dropdown nzTrigger="click" nzPlacement="bottomRight">
          <tabler-icon [icon]="icMore" [size]="18" />
        </button>
      </div>

      <!-- Dải tóm tắt trên lưới: "N nhân viên" (+ chú thích đang lọc nếu có advanced). -->
      <div lpTabs class="m06-sum">
        <span class="m06-sum__n"><b>{{ total() }}</b> nhân viên</span>
        @if (advancedCount() > 0) {
          <button type="button" class="m06-sum__clear" (click)="clearFilter()">Đang lọc {{ advancedCount() }} điều kiện · Xóa</button>
        }
      </div>

      @if (total() === 0) {
        <div class="m06-empty">
          <hrm-empty preset="no-results" description="Không tìm thấy hồ sơ phù hợp" />
          <p class="m06-empty__hint">Thử thay đổi từ khóa hoặc bộ lọc.</p>
          <hrm-button size="sm" (click)="resetAll()">Xóa bộ lọc</hrm-button>
        </div>
      } @else {
        <hrm-data-view class="m06-dv"
          [modes]="['table']" mode="table"
          [columns]="cols()" [data]="pagedRows()" rowKey="id"
          [tableMinWidth]="'1220px'" [size]="'small'"
          (openRecord)="open360.emit($any($event).id)" />
      }

      <span pagerInfo>Hiển thị {{ from() }}-{{ to() }} trong {{ total() }} nhân viên</span>
    </hrm-list-page>

    <!-- ═════ Bộ lọc — POPOVER 4 nhóm A/B/C/D (draft → Áp dụng commit). ═════ -->
    <ng-template #filterPanel>
      <div class="m06-flt">
        <div class="m06-flt__cols">
          <!-- A · Nhân sự -->
          <section class="m06-flt__grp">
            <div class="m06-flt__h">Nhân sự</div>
            <label class="m06-flt__lbl">Đơn vị</label>
            <hrm-select [multiple]="true" [allowClear]="true" placeholder="Tất cả đơn vị" size="sm"
              [options]="donViOptions" [ngModel]="draft().donVi" (ngModelChange)="patchDraft({ donVi: $event })" />
            <div class="m06-flt__sub">Trạng thái làm việc</div>
            @for (o of empOptions; track o.value) {
              <hrm-checkbox [ngModel]="draft().employmentStatus.includes(o.value)"
                (ngModelChange)="toggleEmp(o.value, $event)">{{ o.label }}</hrm-checkbox>
            }
          </section>

          <!-- B · Bảo hiểm -->
          <section class="m06-flt__grp">
            <div class="m06-flt__h">Bảo hiểm</div>
            <div class="m06-flt__sub">Trạng thái tham gia</div>
            @for (o of insOptions; track o.value) {
              <hrm-checkbox [ngModel]="draft().insuranceStatus.includes(o.value)"
                (ngModelChange)="toggleIns(o.value, $event)">{{ o.label }}</hrm-checkbox>
            }
            <label class="m06-flt__lbl">Nơi khám chữa bệnh</label>
            <hrm-select [multiple]="true" [allowClear]="true" [showSearch]="true" placeholder="Tất cả nơi KCB" size="sm"
              [options]="kcbOptions" [ngModel]="draft().kcb" (ngModelChange)="patchDraft({ kcb: $event })" />
            <label class="m06-flt__lbl">Mức lương đóng (VNĐ)</label>
            <div class="m06-flt__range">
              <hrm-input-number size="sm" placeholder="Từ" [min]="0" [step]="1000000"
                [ngModel]="draft().salaryFrom" (ngModelChange)="patchDraft({ salaryFrom: $event ?? null })" />
              <span class="m06-flt__dash">—</span>
              <hrm-input-number size="sm" placeholder="Đến" [min]="0" [step]="1000000"
                [ngModel]="draft().salaryTo" (ngModelChange)="patchDraft({ salaryTo: $event ?? null })" />
            </div>
          </section>

          <!-- C · Công việc cần xử lý -->
          <section class="m06-flt__grp">
            <div class="m06-flt__h">Công việc cần xử lý</div>
            <hrm-checkbox [ngModel]="draft().hasPendingMovement" (ngModelChange)="patchDraft({ hasPendingMovement: $event })">Có biến động chờ</hrm-checkbox>
            <hrm-checkbox [ngModel]="draft().hasBenefitCase" (ngModelChange)="patchDraft({ hasBenefitCase: $event })">Có hồ sơ chế độ</hrm-checkbox>
            <hrm-checkbox [ngModel]="draft().hasDataException" (ngModelChange)="patchDraft({ hasDataException: $event })">Ngoại lệ dữ liệu</hrm-checkbox>
            <hrm-checkbox [ngModel]="draft().hasNearDeadline" (ngModelChange)="patchDraft({ hasNearDeadline: $event })">Sắp đến hạn</hrm-checkbox>
            <hrm-checkbox [ngModel]="draft().hasNeedSupplement" (ngModelChange)="patchDraft({ hasNeedSupplement: $event })">Cần bổ sung</hrm-checkbox>
          </section>

          <!-- D · Dữ liệu -->
          <section class="m06-flt__grp">
            <div class="m06-flt__h">Dữ liệu</div>
            <hrm-checkbox [ngModel]="draft().syncStatus.includes('synced')" (ngModelChange)="toggleSync('synced', $event)">Đã đồng bộ</hrm-checkbox>
            <hrm-checkbox [ngModel]="draft().syncStatus.includes('error')" (ngModelChange)="toggleSync('error', $event)">Chưa đồng bộ</hrm-checkbox>
          </section>
        </div>

        <div class="m06-flt__foot">
          <hrm-button variant="text" size="sm" [disabled]="draftEmpty()" (click)="clearFilter()">Xóa bộ lọc</hrm-button>
          <hrm-button variant="primary" size="sm" [disabled]="!dirty()" (click)="applyFilter()">Áp dụng</hrm-button>
        </div>
      </div>
    </ng-template>

    <!-- ⋮ More menu (toolbar phải). -->
    <nz-dropdown-menu #moreMenu="nzDropdownMenu">
      <ul nz-menu class="m06-menu">
        <li nz-menu-item (click)="onExport()"><tabler-icon [icon]="icExport" [size]="16" /> Xuất Excel</li>
        <li nz-menu-item (click)="onRefresh()"><tabler-icon [icon]="icRefresh" [size]="16" /> Làm mới</li>
        <li nz-menu-item (click)="onColumns()"><tabler-icon [icon]="icColumns" [size]="16" /> Tùy chỉnh cột</li>
      </ul>
    </nz-dropdown-menu>

    <!-- ═════ Cell templates (ngữ cảnh $implicit = M06DisplayRow) ═════ -->
    <ng-template #userCell let-r>
      <hrm-user-cell [name]="$any(r).name" [sub]="$any(r).code" [colorful]="true" [avatarSize]="30" />
    </ng-template>

    <ng-template #empCell let-r>
      <hrm-status-cell [status]="$any(r).empMeta.tone" [label]="$any(r).empMeta.label" variant="badge" [dot]="true" />
    </ng-template>

    <ng-template #insCell let-r>
      <hrm-status-cell [status]="$any(r).insMeta.tone" [label]="$any(r).insMeta.label" variant="badge" [dot]="true" />
    </ng-template>

    <ng-template #salaryCell let-r>
      <span class="m06-sal">{{ $any(r).salaryNum ? $any(r).insuranceSalary : '—' }}</span>
    </ng-template>

    <ng-template #kcbCell let-r>
      @if ($any(r).kcbCode) {
        <div class="m06-kcb">
          <span class="m06-kcb__name">{{ $any(r).kcbName }}</span>
          <span class="m06-kcb__code">{{ $any(r).kcbCode }}</span>
        </div>
      } @else {
        <span class="m06-muted">Chưa đăng ký</span>
      }
    </ng-template>

    <ng-template #taskCell let-r>
      @if ($any(r).pendingTaskCount > 0) {
        <div class="m06-task" [attr.data-tone]="$any(r).taskTone">
          <span class="m06-task__n">{{ $any(r).pendingTaskCount }}</span>
          <span class="m06-task__hint">{{ $any(r).taskHint }}</span>
        </div>
      } @else {
        <span class="m06-muted">Không có</span>
      }
    </ng-template>

    <ng-template #movementCell let-r>
      <div class="m06-mov">
        <span class="m06-mov__type">{{ $any(r).lastMovementType }}</span>
        @if ($any(r).lastMovementDate) { <span class="m06-mov__date">{{ $any(r).lastMovementDate }}</span> }
      </div>
    </ng-template>

    <ng-template #syncCell let-r>
      @if ($any(r).syncStatus === 'error') {
        <span class="m06-sync m06-sync--err"><tabler-icon [icon]="icAlert" [size]="13" /> Chưa đồng bộ</span>
      } @else {
        <div class="m06-sync">
          <span class="m06-sync__time">{{ $any(r).lastSyncTime }}</span>
          <span class="m06-sync__date">{{ $any(r).lastSyncDate }}</span>
        </div>
      }
    </ng-template>

    <!-- ⋮ per-row: Xem hồ sơ · Xem lịch sử biến động · Xem hồ sơ chế độ · Sao chép số BHXH.
         Menu scope theo dòng (nằm trong ng-template let-r). stopPropagation để không mở 360 khi bấm nút. -->
    <ng-template #actCell let-r>
      <button type="button" class="m06-rowmore" aria-label="Thao tác" title="Thao tác"
        [nzDropdownMenu]="rowMenu" nz-dropdown nzTrigger="click" nzPlacement="bottomRight"
        (click)="$event.stopPropagation()">
        <tabler-icon [icon]="icMore" [size]="16" />
      </button>
      <nz-dropdown-menu #rowMenu="nzDropdownMenu">
        <ul nz-menu class="m06-menu">
          <li nz-menu-item (click)="open360.emit($any(r).id)"><tabler-icon [icon]="icEye" [size]="16" /> Xem hồ sơ</li>
          <li nz-menu-item (click)="onRowHistory($any(r))"><tabler-icon [icon]="icHistory" [size]="16" /> Xem lịch sử biến động</li>
          <li nz-menu-item (click)="onRowBenefit($any(r))"><tabler-icon [icon]="icBenefit" [size]="16" /> Xem hồ sơ chế độ</li>
          <li nz-menu-item (click)="onCopyBhxh($any(r))"><tabler-icon [icon]="icCopy" [size]="16" /> Sao chép số BHXH</li>
        </ul>
      </nz-dropdown-menu>
    </ng-template>
  `,
  host: { class: 'ins-m06-search' },
  styles: [`
    :host { display: flex; flex-direction: column; flex: 1 1 auto; min-height: 0; }
    .m06-lp { flex: 1 1 auto; min-height: 0; }
    /* Ẩn thanh chuyển chế độ nội bộ (chỉ có mode table). */
    :host ::ng-deep hrm-data-view .dv-bar { display: none; }
    /* Lưới đơn: mỗi ô 1 dòng — hẹp thì cuộn ngang, không rớt hàng. */
    :host ::ng-deep .m06-dv .ant-table-tbody > tr { cursor: pointer; }

    /* Toolbar TRÁI. */
    .m06-filters { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; min-width: 0; }
    .m06-kw { display: inline-block; width: 300px; }
    .m06-filters ::ng-deep .ant-input-affix-wrapper {
      height: 32px; min-height: 32px; padding-top: 0; padding-bottom: 0; border-radius: var(--radius-md); }
    .m06-filters ::ng-deep .ant-input { min-height: 0; }

    /* Quick-filter chips (toggle) — active = viền + nền primary nhạt + text primary (không solid mạnh). */
    .m06-chips { display: inline-flex; align-items: center; gap: 6px; }
    .m06-chip {
      display: inline-flex; align-items: center; gap: 5px; cursor: pointer; font: inherit;
      font-size: var(--fs-13); font-weight: 500; color: var(--text-body);
      background: var(--bg-surface); border: 1px solid var(--border-sub); border-radius: var(--radius-full);
      padding: 4px 12px; height: 32px; white-space: nowrap;
    }
    .m06-chip:hover { border-color: var(--primary-base); color: var(--primary-base); }
    .m06-chip--on { color: var(--primary-base); background: var(--primary-bg-subtle); border-color: var(--primary-base); }
    .m06-chip__n {
      display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 5px;
      border-radius: var(--radius-full); background: var(--primary-base); color: var(--static-white, #fff);
      font-size: var(--fs-11); font-weight: 600; line-height: 1;
    }
    .m06-chip--on .m06-chip__n { background: var(--primary-base); }

    /* Nút Bộ lọc + badge. */
    .m06-fbtn {
      display: inline-flex; align-items: center; gap: 6px; height: 32px; padding: 0 12px; cursor: pointer;
      font: inherit; font-size: var(--fs-13); font-weight: 500; color: var(--text-body);
      background: var(--bg-surface); border: 1px solid var(--border-sub); border-radius: var(--radius-md);
    }
    .m06-fbtn:hover { border-color: var(--primary-base); color: var(--primary-base); }
    .m06-fbtn--on { border-color: var(--primary-base); color: var(--primary-base); }
    .m06-fbtn__badge {
      display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 5px; margin-left: 2px;
      border-radius: var(--radius-full); background: var(--primary-base); color: var(--static-white, #fff);
      font-size: var(--fs-11); font-weight: 600; line-height: 1;
    }

    /* Toolbar PHẢI + nút ⋮. */
    .m06-actions { display: flex; align-items: center; gap: 8px; }
    .m06-more, .m06-rowmore {
      display: inline-flex; align-items: center; justify-content: center; border: 1px solid var(--border-sub);
      background: var(--bg-surface); border-radius: var(--radius-md); cursor: pointer; color: var(--text-sub);
    }
    .m06-more { width: 34px; height: 34px; }
    .m06-rowmore { width: 28px; height: 28px; }
    .m06-more:hover, .m06-rowmore:hover { border-color: var(--primary-base); color: var(--text-strong); }

    /* Dải tóm tắt. */
    .m06-sum { display: flex; align-items: center; gap: 12px; padding: 2px 2px 10px; }
    .m06-sum__n { font-size: var(--fs-13); color: var(--text-body); }
    .m06-sum__n b { color: var(--text-strong); font-weight: 700; }
    .m06-sum__clear {
      font: inherit; font-size: var(--fs-12); color: var(--primary-base); background: none; border: 0; cursor: pointer;
    }
    .m06-sum__clear:hover { text-decoration: underline; }

    /* Empty state. */
    .m06-empty { display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 40px 0; }
    .m06-empty__hint { margin: 0; font-size: var(--fs-13); color: var(--text-sub); }

    /* Cell — Mức lương (phải, tabular). */
    .m06-sal { display: block; text-align: right; font-variant-numeric: tabular-nums; color: var(--text-strong); font-weight: 500; }
    .m06-muted { color: var(--text-soft); }

    /* Cell — Nơi KCB (tên + mã). */
    .m06-kcb { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
    .m06-kcb__name { color: var(--text-body); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    .m06-kcb__code { font-size: var(--fs-12); color: var(--text-soft); font-variant-numeric: tabular-nums; }

    /* Cell — Việc cần xử lý (số lớn + hint tone). */
    .m06-task { display: flex; align-items: baseline; gap: 6px; }
    .m06-task__n { font-size: var(--fs-15); font-weight: 700; font-variant-numeric: tabular-nums; }
    .m06-task__hint { font-size: var(--fs-12); }
    .m06-task[data-tone='error'] .m06-task__n { color: var(--error-base); }
    .m06-task[data-tone='error'] .m06-task__hint { color: var(--error-text, var(--error-base)); }
    .m06-task[data-tone='warning'] .m06-task__n { color: var(--warning-base); }
    .m06-task[data-tone='warning'] .m06-task__hint { color: var(--warning-text, var(--warning-base)); }
    .m06-task[data-tone='muted'] .m06-task__n { color: var(--text-sub); }
    .m06-task[data-tone='muted'] .m06-task__hint { color: var(--text-soft); }

    /* Cell — Biến động gần nhất. */
    .m06-mov { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
    .m06-mov__type { color: var(--text-body); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    .m06-mov__date { font-size: var(--fs-12); color: var(--text-soft); font-variant-numeric: tabular-nums; }

    /* Cell — Cập nhật gần nhất. */
    .m06-sync { display: flex; flex-direction: column; gap: 1px; }
    .m06-sync__time { color: var(--text-body); font-variant-numeric: tabular-nums; }
    .m06-sync__date { font-size: var(--fs-12); color: var(--text-soft); font-variant-numeric: tabular-nums; }
    .m06-sync--err { display: inline-flex; align-items: center; gap: 4px; color: var(--warning-text, var(--warning-base)); font-size: var(--fs-12); }

    /* Popover Bộ lọc. */
    .m06-flt { display: flex; flex-direction: column; gap: 12px; width: 540px; max-width: 88vw; }
    .m06-flt__cols { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
    .m06-flt__grp { display: flex; flex-direction: column; gap: 8px; min-width: 0; }
    .m06-flt__h {
      font-size: var(--fs-12); font-weight: 700; text-transform: uppercase; letter-spacing: .04em;
      color: var(--text-sub); padding-bottom: 4px; border-bottom: 1px solid var(--border-soft);
    }
    .m06-flt__sub, .m06-flt__lbl { font-size: var(--fs-12); font-weight: 600; color: var(--text-body); margin-top: 2px; }
    .m06-flt__range { display: flex; align-items: center; gap: 8px; }
    .m06-flt__range ::ng-deep hrm-input-number, .m06-flt__range ::ng-deep nz-input-number { flex: 1 1 0; min-width: 0; width: 100%; }
    .m06-flt__dash { color: var(--text-soft); }
    .m06-flt__foot {
      display: flex; align-items: center; justify-content: space-between; gap: 8px;
      padding-top: 10px; border-top: 1px solid var(--border-soft);
    }

    /* Menu ⋮ — chỉ set màu icon (layout do bridge lo). */
    ::ng-deep .m06-menu tabler-icon { color: var(--icon-secondary); }
  `],
})
export class InsM06Search {
  private readonly msg = inject(HrmMessageService);

  /** Mở Hồ sơ Bảo hiểm 360 cho NLĐ (nhanVienId) — click cả dòng hoặc ⋮ → Xem hồ sơ. */
  readonly open360 = output<string>();

  protected readonly icSearch = IconSearch;
  protected readonly icFilter = IconFilter;
  protected readonly icMore = IconDotsVertical;
  protected readonly icExport = IconFileExport;
  protected readonly icRefresh = IconRefresh;
  protected readonly icColumns = IconColumns3;
  protected readonly icEye = IconEye;
  protected readonly icHistory = IconHistory;
  protected readonly icBenefit = IconHeartHandshake;
  protected readonly icCopy = IconCopy;
  protected readonly icAlert = IconAlertTriangle;

  protected readonly crumbs: HrmCrumb[] = [
    { title: 'Hồ sơ bảo hiểm 360°' },
    { title: 'Tra cứu hồ sơ bảo hiểm' },
  ];

  protected readonly quickFilters = M06_QUICK_FILTERS;
  protected readonly donViOptions = M06_DON_VI_OPTIONS.map((o) => ({ label: o.label, value: o.value }));
  protected readonly empOptions = M06_EMP_STATUS_OPTIONS;
  protected readonly insOptions = M06_INS_STATUS_OPTIONS;
  protected readonly kcbOptions = M06_KCB_OPTIONS.map((o) => ({ label: `${o.name} (${o.code})`, value: o.code }));
  /** Badge "Cần xử lý · N" — số NLĐ có việc chờ xử lý trên TOÀN dataset (const, ổn định). */
  protected readonly canXuLyCount = m06QuickFilterCount('can-xu-ly');

  /* ── Search + quick-filter + advanced (dùng chung filtered ∩). ── */
  private readonly kw = signal('');
  protected get kwModel(): string { return this.kw(); }
  protected set kwModel(v: string) { this.kw.set(v ?? ''); }

  protected readonly activeQF = signal<M06QuickFilter | null>(null);
  protected toggleQF(k: M06QuickFilter): void { this.activeQF.update((cur) => (cur === k ? null : k)); }

  /** Bộ lọc ĐÃ ÁP DỤNG (commit). Search + QF + bộ này giao nhau ở filtered. */
  private readonly filter = signal<M06SearchFilter>(m06EmptyFilter());
  protected readonly advancedCount = computed(() => m06AdvancedCount(this.filter()));

  /** Bản nháp trong popover (Áp dụng mới commit sang `filter`). */
  protected readonly draft = signal<M06SearchFilter>(m06EmptyFilter());
  protected patchDraft(p: Partial<M06SearchFilter>): void { this.draft.update((d) => ({ ...d, ...p })); }
  private toggleIn<T>(arr: readonly T[], v: T, on: boolean): T[] {
    return on ? [...arr, v] : arr.filter((x) => x !== v);
  }
  protected toggleEmp(v: M06SearchFilter['employmentStatus'][number], on: boolean): void {
    this.patchDraft({ employmentStatus: this.toggleIn(this.draft().employmentStatus, v, on) });
  }
  protected toggleIns(v: M06SearchFilter['insuranceStatus'][number], on: boolean): void {
    this.patchDraft({ insuranceStatus: this.toggleIn(this.draft().insuranceStatus, v, on) });
  }
  protected toggleSync(v: M06SearchFilter['syncStatus'][number], on: boolean): void {
    this.patchDraft({ syncStatus: this.toggleIn(this.draft().syncStatus, v, on) });
  }
  /** Áp dụng bật được khi draft khác bộ đã commit. */
  protected readonly dirty = computed(() => JSON.stringify(this.draft()) !== JSON.stringify(this.filter()));
  protected readonly draftEmpty = computed(() => m06AdvancedCount(this.draft()) === 0);

  private readonly popOpen = signal(false);
  protected get popOpenModel(): boolean { return this.popOpen(); }
  protected set popOpenModel(v: boolean) {
    if (v && !this.popOpen()) this.draft.set(this.filter()); // mở → nạp lại nháp từ bộ đã commit
    this.popOpen.set(v);
  }
  protected applyFilter(): void { this.filter.set(this.draft()); this.popOpen.set(false); }
  /** Xóa bộ lọc advanced (KHÔNG đụng search/QF). */
  protected clearFilter(): void { const e = m06EmptyFilter(); this.draft.set(e); this.filter.set(e); this.popOpen.set(false); }
  /** Empty state → xóa TẤT CẢ (search + QF + advanced). */
  protected resetAll(): void {
    this.kw.set(''); this.activeQF.set(null);
    const e = m06EmptyFilter(); this.draft.set(e); this.filter.set(e);
  }

  /** Kết quả tra cứu (search ∩ QF ∩ advanced) — dạng hiển thị. */
  protected readonly filtered = computed<M06DisplayRow[]>(() => {
    const kw = this.kw();
    const qf = this.activeQF();
    const f = this.filter();
    return M06_DISPLAY_ROWS.filter(
      (r) => m06MatchesKeyword(r, kw) && m06MatchesQuickFilter(r, qf) && m06MatchesFilter(r, f),
    );
  });

  /* ── Phân trang (pageSize 20). ── */
  private readonly pageIndex = signal(1);
  protected get pageIndexModel(): number { return this.pageIndex(); }
  protected set pageIndexModel(v: number) { this.pageIndex.set(v > 0 ? v : 1); }
  private readonly pageSize = signal(20);
  protected get pageSizeModel(): number { return this.pageSize(); }
  protected set pageSizeModel(v: number) { this.pageSize.set(v > 0 ? v : 20); }

  protected readonly total = computed(() => this.filtered().length);
  private readonly pageCount = computed(() => Math.max(1, Math.ceil(this.total() / this.pageSize())));
  private readonly curPage = computed(() => Math.min(Math.max(1, this.pageIndex()), this.pageCount()));
  protected readonly pagedRows = computed<M06DisplayRow[]>(() => {
    const size = this.pageSize();
    const start = (this.curPage() - 1) * size;
    return this.filtered().slice(start, start + size);
  });
  protected readonly from = computed(() => (this.total() ? (this.curPage() - 1) * this.pageSize() + 1 : 0));
  protected readonly to = computed(() => Math.min(this.curPage() * this.pageSize(), this.total()));

  constructor() {
    // Đổi search/QF/filter → về trang 1 (đọc pageIndex qua untracked để không tự phụ thuộc).
    effect(() => {
      this.kw(); this.activeQF(); this.filter();
      untracked(() => { if (this.pageIndex() !== 1) this.pageIndex.set(1); });
    });
  }

  /* ── Cột bảng (§18) — 5 cột sortable: Tên · Mức lương · Việc cần xử lý · Biến động · Cập nhật. ── */
  private readonly userCell = viewChild.required<TemplateRef<unknown>>('userCell');
  private readonly empCell = viewChild.required<TemplateRef<unknown>>('empCell');
  private readonly insCell = viewChild.required<TemplateRef<unknown>>('insCell');
  private readonly salaryCell = viewChild.required<TemplateRef<unknown>>('salaryCell');
  private readonly kcbCell = viewChild.required<TemplateRef<unknown>>('kcbCell');
  private readonly taskCell = viewChild.required<TemplateRef<unknown>>('taskCell');
  private readonly movementCell = viewChild.required<TemplateRef<unknown>>('movementCell');
  private readonly syncCell = viewChild.required<TemplateRef<unknown>>('syncCell');
  private readonly actCell = viewChild.required<TemplateRef<unknown>>('actCell');

  protected readonly cols = computed<HrmGridColumn[]>(() => [
    { key: 'name', title: 'Nhân viên', width: '230px', sortable: true, cell: this.userCell() as HrmGridColumn['cell'] },
    { key: 'donViLabel', title: 'Đơn vị', width: '150px' },
    { key: 'employmentStatus', title: 'TT làm việc', width: '140px', cell: this.empCell() as HrmGridColumn['cell'] },
    { key: 'insuranceStatus', title: 'TT tham gia', width: '140px', cell: this.insCell() as HrmGridColumn['cell'] },
    { key: 'salaryNum', title: 'Mức lương đóng', width: '140px', align: 'right', sortable: true, cell: this.salaryCell() as HrmGridColumn['cell'] },
    { key: 'kcbCode', title: 'Nơi KCB', width: '170px', cell: this.kcbCell() as HrmGridColumn['cell'] },
    { key: 'pendingTaskCount', title: 'Việc cần xử lý', width: '150px', sortable: true, cell: this.taskCell() as HrmGridColumn['cell'] },
    { key: 'movementSort', title: 'Biến động gần nhất', width: '180px', sortable: true, cell: this.movementCell() as HrmGridColumn['cell'] },
    { key: 'syncSort', title: 'Cập nhật gần nhất', width: '150px', sortable: true, cell: this.syncCell() as HrmGridColumn['cell'] },
    { key: 'act', title: '', width: '56px', align: 'right', fixed: 'right', cell: this.actCell() as HrmGridColumn['cell'] },
  ]);

  /* ── Thao tác toolbar / per-row (demo — toast deterministic). ── */
  protected onExport(): void { this.msg.info(`Đang xuất Excel ${this.total()} nhân viên (demo).`); }
  protected onRefresh(): void { this.msg.success('Đã làm mới danh sách tra cứu.'); }
  protected onColumns(): void { this.msg.info('Tùy chỉnh cột (demo).'); }
  protected onRowHistory(r: M06DisplayRow): void { this.msg.info(`Lịch sử biến động của ${r.name} (demo).`); }
  protected onRowBenefit(r: M06DisplayRow): void { this.msg.info(`Hồ sơ chế độ của ${r.name} (demo).`); }
  protected onCopyBhxh(r: M06DisplayRow): void {
    if (!r.soBHXH || r.soBHXH === '—') { this.msg.warning(`${r.name} chưa có mã số BHXH.`); return; }
    navigator.clipboard?.writeText(r.soBHXH);
    this.msg.success(`Đã sao chép số BHXH ${r.soBHXH}.`);
  }
}
