import { ChangeDetectionStrategy, Component, computed, inject } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { IconLock } from '@tabler/icons-angular';
import { TablerIconComponent } from '@tabler/icons-angular';
import { HrmPageHeader, HrmSelect } from 'hrm-ui';
import { INS_DON_VI, InsShellStore, insKy } from '../_data/_core';
import { InsM03Store } from '../_data/_m03-data';
import { A07_D02LT_NOTE } from './_m03-columns';
import { InsM03Workspace } from './m03-workspace';

/** ═════════ M03 · HOST SLIM — KÊ KHAI BHXH THEO KỲ (workspace-only) ═════════
 *  Host chỉ giữ page-header (title + đơn vị + A-07 + locked) + <ins-m03-workspace>.
 *  "Lập tờ khai" mở MODAL trong workspace (chooser lô + Lưu nháp/Nộp hồ sơ) rồi TỰ điều hướng
 *  sang m03b ("Theo dõi hồ sơ") — nơi sống toàn bộ soát–duyệt–ký–nộp–kết-quả. Danh sách lô của kỳ,
 *  trang lô toàn màn (lo-detail), D02-TS viewer, modal Tạo lô đã dời sang m03b.
 *  Navigation contract: constructor đọc `shell.navCtx()` → set ngữ cảnh {ky, donVi} (filter 'lo:'
 *  do m03b diễn giải, không còn ở đây). A-07 (tin cậy Thấp): cột D02-LT chờ QĐ 366/QĐ-BHXH. */
@Component({
  selector: 'ins-m03-page',
  imports: [
    FormsModule, TablerIconComponent,
    HrmPageHeader, HrmSelect,
    InsM03Workspace,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <!-- ═════ PAGE HEADER (hrm-page-header) — title + actions (A-07 · đơn vị · locked) ═════ -->
    <hrm-page-header class="m03-ph" [title]="'Kê khai BHXH theo kỳ'" [subtitle]="phSubtitle()">
      <span class="m03-a07" [title]="a07Note">A-07 · Cột D02-LT chờ QĐ 366/QĐ-BHXH · tin cậy Thấp</span>
      <hrm-select class="m03-dv" [(ngModel)]="donViModel" [options]="donViOptions" size="sm" [allowClear]="false" [showSearch]="false" />
      @if (kyLocked()) {
        <span class="m03-locked"><tabler-icon [icon]="icLock" [size]="13" /> Kỳ đã khóa — chỉ đọc</span>
      }
    </hrm-page-header>

    <!-- ═════ WORKSPACE lập tờ khai (tự mở modal chooser lô + tự điều hướng m03b) ═════ -->
    <div class="m03-body">
      <ins-m03-workspace />
    </div>
  `,
  host: { class: 'ins-m03-page' },
  styles: [`
    :host { display: flex; flex-direction: column; flex: 1 1 auto; min-height: 0; padding: 0 20px; }
    .m03-dv { display: inline-block; width: 240px; }
    .m03-a07 { font-size: var(--fs-11); font-weight: 500; color: var(--warning-text); background: var(--warning-bg);
      border: 1px dashed var(--warning-base, var(--warning-text)); border-radius: var(--radius-full); padding: 1px 9px; cursor: help; white-space: nowrap; }
    .m03-locked { display: inline-flex; align-items: center; gap: 5px; font-size: var(--fs-12); font-weight: 600;
      color: var(--warning-text); background: var(--warning-bg); border-radius: var(--radius-full); padding: 2px 10px; }

    .m03-body { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; gap: 16px; padding: 12px 0 16px; overflow: auto; }
  `],
})
export class InsM03Page {
  protected readonly store = inject(InsM03Store);
  protected readonly shell = inject(InsShellStore);

  protected readonly icLock = IconLock;
  protected readonly a07Note = A07_D02LT_NOTE;

  /* ── Đơn vị (thanh mỏng — kỳ selector + loại kỳ nằm TRONG ins-m03-workspace) ── */
  protected readonly donViOptions = INS_DON_VI.map((d) => ({ value: d.id, label: d.ten }));
  protected get donViModel(): unknown { return this.store.donViId(); }
  protected set donViModel(v: unknown) {
    this.store.donViId.set((v as string) || 'dv1');
    this.shell.navCtx.update((c) => ({ ...c, donVi: this.store.donViId() }));
  }

  protected readonly kyInfo = computed(() => insKy(this.store.kyId()));
  protected readonly kyLocked = computed(() => this.store.kyLocked());
  /** Subtitle page-header: gom biến động D02-LT đã xác nhận → tờ khai theo kỳ (ngữ cảnh kỳ + hạn chốt). */
  protected readonly phSubtitle = computed(() => {
    const ky = this.kyInfo();
    return ky ? `Gom biến động đã xác nhận · ${ky.label} · Hạn chốt nội bộ ${ky.cutoffInternal}` : 'Gom biến động đã xác nhận thành tờ khai theo kỳ';
  });

  constructor() {
    // Navigation contract: {ky, donVi} — diễn giải MỘT lần; filter 'lo:' nay do m03b xử lý.
    const ctx = this.shell.navCtx();
    if (ctx.ky && insKy(ctx.ky)) this.store.kyId.set(ctx.ky);
    if (ctx.donVi && INS_DON_VI.some((d) => d.id === ctx.donVi)) this.store.donViId.set(ctx.donVi);
  }
}
