/* ═════════════════════════════ HELPERS (deterministic) ═════════════════════════════ */

/** '22.400.000' | '22400000' | '—' → number. */
export function m06ParseMoney(v: string): number {
  const n = Number(String(v).replace(/[^\d]/g, ''));
  return Number.isFinite(n) ? n : 0;
}
/** 1792000 → '1.792.000'. */
export function m06FmtMoney(n: number): string {
  if (!n) return '0';
  return Math.round(n).toLocaleString('vi-VN').replace(/,/g, '.');
}
/** 25.5 → '25,5%'. */
function pct(n: number): string {
  return (Number.isInteger(n) ? String(n) : String(n).replace('.', ',')) + '%';
}

/** Biểu suất chuẩn VN (§15). */
const RATES = [
  { type: 'BHXH', total: 25.5, emp: 8, er: 17.5 },
  { type: 'BHYT', total: 4.5, emp: 1.5, er: 3 },
  { type: 'BHTN', total: 2, emp: 1, er: 1 },
] as const;

/** Từ mức lương (chuỗi) → contrib rows + tổng dự kiến. salary '0' → khoản 0 hết. */
export function m06ComputeContrib(salary: string): { rows: M06ContribRow[]; total: string } {
  const base = m06ParseMoney(salary);
  const rows: M06ContribRow[] = RATES.map((r) => ({
    type: r.type,
    totalRate: pct(r.total),
    employeeRate: pct(r.emp),
    employerRate: pct(r.er),
    employeeAmount: m06FmtMoney((base * r.emp) / 100),
    employerAmount: m06FmtMoney((base * r.er) / 100),
  }));
  const total = m06FmtMoney(RATES.reduce((s, r) => s + (base * (r.emp + r.er)) / 100, 0));
  return { rows, total };
}

const EMP_META = (s: M06EmploymentStatus): M06StatusMeta => M06_EMP_STATUS[s];
const INS_META = (s: M06InsuranceStatus): M06StatusMeta => M06_INS_STATUS[s];

/** Trạng thái loại BH (BHXH/BHYT/BHTN) suy từ insuranceStatus tổng. */
function loaiBHMeta(ins: M06InsuranceStatus): M06StatusMeta {
  switch (ins) {
    case 'dang-tham-gia': return { label: 'Đang tham gia', tone: 'success' };
    case 'tam-giam': return { label: 'Tạm giảm', tone: 'warning' };
    case 'cho-tham-gia': return { label: 'Chờ kê khai', tone: 'info' };
    case 'da-ngung': return { label: 'Ngừng tham gia', tone: 'error' };
    default: return { label: 'Chưa tham gia', tone: 'neutral' };
  }
}

