/* ═════════════════════════════ DERIVE — NLĐ bất kỳ từ search row ═════════════════════════════ */

function deriveOwnerSla(row: M06SearchRow): string | null {
  if (row.urgentTaskCount > 0) return 'SLA còn 1 ngày 6 giờ';
  if (row.pendingTaskCount > 0) return 'SLA còn 3 ngày';
  return null;                  // §20 không active work → ẩn SLA
}

function deriveTaskHint(row: M06SearchRow): string {
  if (row.pendingTaskCount === 0) return 'Không có việc cần xử lý';
  return row.taskHint;
}

/** §26 map loại biến động (chuỗi) → icon timeline + tone. */
function movementIcon(t: string): { icon: M06TimelineIcon; tone: InsTone } {
  if (t.includes('Điều chỉnh')) return { icon: 'salary', tone: 'info' };
  if (t.includes('Tạm giảm')) return { icon: 'decrease', tone: 'warning' };
  if (t.includes('Báo giảm')) return { icon: 'decrease', tone: 'error' };
  if (t.includes('Báo tăng')) return { icon: 'new', tone: 'success' };
  return { icon: 'personal', tone: 'neutral' };
}

function derive360(row: M06SearchRow): M06Profile360 {
  const c = m06ComputeContrib(row.insuranceSalary);
  const active = row.insuranceStatus === 'dang-tham-gia';
  const hasSalary = m06ParseMoney(row.insuranceSalary) > 0;
  const insMeta = loaiBHMeta(row.insuranceStatus);
  const soBHXH = row.soBHXH && row.soBHXH !== '—' ? row.soBHXH : 'Chưa có';

  // §21 pending movement từ flag/last movement
  const pending: M06PendingMovement[] = row.hasPendingMovement
    ? [{
        id: `mv-${row.id}`, type: row.lastMovementType || 'Biến động chờ xử lý',
        summary: `${row.lastMovementType} — hiệu lực ${row.lastMovementDate || 'kỳ hiện tại'}.`,
        oldValue: '—', newValue: hasSalary ? row.insuranceSalary : '—',
        effectiveDate: row.lastMovementDate || '01/08/2026',
        aiSuggested: true, confidencePct: '92%', risk: row.hasDataException ? 'medium' : 'low',
      }]
    : [];

  // §25 timeline tối thiểu từ last movement + báo tăng gốc
  const timeline: M06TimelineEvent[] = [];
  if (row.lastMovementType && row.lastMovementType !== 'Chưa có biến động' && row.lastMovementDate) {
    const mi = movementIcon(row.lastMovementType);
    timeline.push({ id: `${row.id}-t1`, date: row.lastMovementDate, title: row.lastMovementType, valueChange: hasSalary ? row.insuranceSalary + 'đ' : null, source: 'Biến động BHXH', iconKey: mi.icon, tone: mi.tone, kind: 'source' });
  }
  timeline.push({ id: `${row.id}-t0`, date: row.employmentStatus === 'da-nghi' ? '—' : '01/01/2024', title: 'Báo tăng mới', valueChange: null, source: 'Hồ sơ nhân viên', iconKey: 'new', tone: 'success', kind: 'result', statusLabel: 'Đã giải quyết' });

  // §56,71 conflict khi hasDataException
  const conflict: M06ConflictInfo | null = row.hasDataException
    ? { message: 'Có 1 dữ liệu chưa khớp', detail: 'Mức lương giữa HĐLĐ và Payroll đang lệch — cần kiểm tra.' }
    : null;

  // §35-37 records từ flags
  const records: M06RecordRow[] = [];
  if (row.lastMovementType && row.lastMovementType !== 'Chưa có biến động') {
    records.push({ code: `HS-${row.code.replace('NV-', '')}`, category: 'DECLARATION', type: row.lastMovementType, period: '08/2026', submittedAt: row.lastMovementDate ? row.lastMovementDate.slice(0, 5) : '—', statusLabel: 'Đã gửi BHXH', statusTone: 'info', resultLabel: 'Đang xử lý', resultTone: 'warning' });
  }
  if (row.hasBenefitCase) {
    records.push({ code: `BC-${row.code.replace('NV-', '')}`, category: 'BENEFIT', type: 'Ốm đau', period: '08/2026', submittedAt: '05/08', statusLabel: 'Đã tiếp nhận', statusTone: 'info', resultLabel: 'Cần bổ sung', resultTone: 'warning' });
  }

  // §33 movements
  const movements: M06MovementRow[] = [];
  if (row.hasPendingMovement) {
    const kind = row.lastMovementType.includes('Tạm giảm') || row.lastMovementType.includes('giảm') ? 'giam' : row.lastMovementType.includes('Báo tăng') ? 'tang' : 'dieu-chinh';
    movements.push({ id: `${row.id}-m1`, kind, kindLabel: kind === 'tang' ? 'Báo tăng' : kind === 'giam' ? 'Báo giảm' : 'Điều chỉnh', reason: row.lastMovementType, effective: row.lastMovementDate || '01/08/2026', period: '08/2026', batch: '—', statusLabel: 'Chờ xác nhận', statusTone: 'warning' });
  }

  // §6 Verify — chuỗi căn cứ (đơn giản cho NLĐ derive).
  const salaryLineage: M06LineageNode[] = hasSalary ? [
    { node: 'Quyết định lương', value: row.insuranceSalary, ok: true },
    { node: 'Compensation', value: row.insuranceSalary, ok: !row.hasDataException },
    { node: 'Payroll', value: row.insuranceSalary, ok: !row.hasDataException },
    { node: 'Mức đóng BHXH', value: row.insuranceSalary, ok: true },
  ] : [];

  // §22 Verify — bảng chênh lệch nguồn khi hasDataException.
  const salaryConflict: M06SourceConflictDetail | null = row.hasDataException ? {
    rows: [
      { source: 'Compensation', value: hasSalary ? row.insuranceSalary : '—', ok: true },
      { source: 'Payroll', value: hasSalary ? row.insuranceSalary : '—', ok: true },
      { source: 'HĐLĐ', value: '—', ok: false },
    ],
    aiNote: 'Nguồn HĐLĐ và Payroll đang lệch giá trị — cần kiểm tra.',
    suggestedAction: 'Kiểm tra HĐLĐ',
  } : null;

  // §18 Audit tối thiểu.
  const auditTrail: M06AuditRow[] = row.hasPendingMovement ? [
    { time: row.lastMovementDate || '—', actor: 'Hệ thống', action: `Phát hiện ${row.lastMovementType.toLowerCase()}`, detail: 'Nguồn quyết định nhân sự', tone: 'info' },
    { time: '—', actor: 'Trần Thu Hà', action: 'Chờ xác nhận', detail: 'Chưa quyết định', tone: 'warning' },
  ] : [];

  // §30-31 Task aggregate (không trùng).
  const tasks: M06TaskRow[] = [];
  if (row.hasPendingMovement) tasks.push({ id: `${row.id}-tk-mv`, title: row.lastMovementType, due: row.hasNearDeadline ? 'Sắp đến hạn' : 'Theo hàng đợi', actionLabel: 'Xử lý', kind: 'movement', urgent: row.urgentTaskCount > 0 });
  if (row.hasNeedSupplement) tasks.push({ id: `${row.id}-tk-sup`, title: 'Bổ sung dữ liệu bảo hiểm', due: 'Cần bổ sung', actionLabel: 'Bổ sung', kind: 'exception', urgent: true });
  if (row.hasBenefitCase) tasks.push({ id: `${row.id}-tk-bn`, title: 'Hồ sơ chế độ cần xử lý', due: 'Theo hàng đợi', actionLabel: 'Xem', kind: 'benefit', urgent: false });
  if (row.hasDataException && !row.hasNeedSupplement) tasks.push({ id: `${row.id}-tk-ex`, title: 'Kiểm tra chênh lệch dữ liệu', due: 'Cần kiểm tra', actionLabel: 'Kiểm tra', kind: 'exception', urgent: false });

  return {
    identity: {
      id: row.id, code: row.code, name: row.name, avatarSeed: row.avatarSeed,
      employmentStatus: row.employmentStatus, insuranceStatus: row.insuranceStatus,
      donViLabel: row.donViLabel, jobTitle: row.jobTitle, joinDate: '01/01/2024',
      soBHXH, lastSyncTime: row.lastSyncTime, lastSyncDate: row.lastSyncDate,
    },
    summary: {
      insuranceSalary: hasSalary ? row.insuranceSalary : '0',
      salaryEffectiveFrom: row.lastMovementDate || '01/08/2026', salaryPrev: null, salaryPending: null,
      totalRatePct: active ? '32%' : '—', employeeRatePct: active ? '10,5%' : '—', employerRatePct: active ? '21,5%' : '—',
      kcbName: row.kcbName, kcbCode: row.kcbCode,
      pendingTaskCount: row.pendingTaskCount, urgentTaskCount: row.urgentTaskCount, taskHint: deriveTaskHint(row),
    },
    participation: {
      agencyName: 'BHXH TP. Thủ Đức', employerUnitCode: 'TE0179A', joinDate: '01/01/2024',
      subjectType: 'Lao động Việt Nam', currentPeriod: 'T08/2026',
      bhxh: insMeta, bhyt: insMeta, bhtn: insMeta,
    },
    contrib: c.rows, contribTotal: c.total,
    salaryComponents: hasSalary
      ? [{ name: 'Lương chức danh', amount: row.insuranceSalary, source: 'HĐLĐ', included: true }]
      : [],
    salaryLineage, salaryConflict,
    sources: [
      { name: 'Hồ sơ nhân viên', iconKey: 'employee', status: 'synced', updated: row.lastSyncTime },
      { name: 'Hợp đồng lao động', iconKey: 'contract', status: row.syncStatus === 'error' ? 'syncing' : 'synced', updated: row.lastSyncTime },
      { name: 'C&B / Payroll', iconKey: 'payroll', status: row.hasDataException ? 'conflict' : 'synced', updated: row.lastSyncTime },
      { name: 'Quyết định nhân sự', iconKey: 'decision', status: 'verified', updated: row.lastSyncDate },
    ],
    dataQuality: {
      completenessPct: row.hasDataException ? '82%' : row.syncStatus === 'error' ? '90%' : '100%',
      requiredSourceCount: 4, availableSourceCount: row.syncStatus === 'error' ? 3 : 4,
      conflictCount: row.hasDataException ? 1 : 0,
    },
    owner: { name: 'Trần Thu Hà', role: 'HR Bảo hiểm', avatarSeed: 'Trần Thu Hà', slaText: deriveOwnerSla(row) },
    pendingMovements: pending,
    timeline,
    auditTrail,
    tasks,
    conflict,
    employeeInfo: {
      dob: '01/01/1990', gender: '—', cccd: '—', nationality: 'Việt Nam',
      address: '—', phone: '—', email: '—',
      employmentLabel: EMP_META(row.employmentStatus).label,
      recentChange: row.hasNeedSupplement ? 'Thiếu mã số BHXH' : null,
    },
    contract: {
      type: 'HĐLĐ không xác định thời hạn', code: `HĐLĐ-${row.code.replace('NV-', '')}`, signDate: '01/01/2024',
      from: '01/01/2024', to: 'Không thời hạn', statusLabel: row.employmentStatus === 'da-nghi' ? 'Đã chấm dứt' : 'Đang hiệu lực',
      jobTitle: row.jobTitle, salaryBasis: hasSalary ? row.insuranceSalary : '—',
      isCurrent: row.employmentStatus !== 'da-nghi', insuranceImpact: null,
    },
    compensation: {
      components: hasSalary ? [{ name: 'Lương chức danh', amount: row.insuranceSalary, source: 'HĐLĐ', included: true }] : [],
      insuranceBase: hasSalary ? row.insuranceSalary : '—', prevBase: null,
      sourceConsistent: !row.hasDataException,
      conflictNote: row.hasDataException ? 'Mức lương HĐLĐ khác Payroll — cần kiểm tra.' : null,
    },
    absences: row.employmentStatus === 'tam-hoan'
      ? [{ period: '05/08 – 26/08', type: 'Nghỉ không lương', days: '16 ngày', impact: 'Có khả năng tạm giảm', status: 'Đã tạo biến động', impactTone: 'warning' }]
      : [],
    decisions: [
      { name: 'Quyết định nhân sự gần nhất', effective: row.lastMovementDate || '—', change: row.lastMovementType, impact: row.hasPendingMovement ? 'Có khả năng cần xử lý' : 'Không ảnh hưởng', status: 'Đã ban hành', detected: row.hasPendingMovement },
    ],
    movements,
    records,
  };
}

/* ═════════════════════════════ PUBLIC: build360(id) ═════════════════════════════ */

const SEARCH_BY_ID: ReadonlyMap<string, M06SearchRow> = new Map(M06_SEARCH_ROWS.map((r) => [r.id, r]));

/** Trả Hồ sơ 360 cho 1 NLĐ. Showcase m06x01 = verbatim screenshot; còn lại derive từ search row.
 *  Fallback (id lạ) = showcase để trang luôn render (demo an toàn). */
export function build360(id: string): M06Profile360 {
  if (id === SHOWCASE_ID) return M06_360_SHOWCASE;
  const row = SEARCH_BY_ID.get(id);
  return row ? derive360(row) : M06_360_SHOWCASE;
}

/** Nhãn tone → class helper cho status dot (tái dùng ở nhiều tab). */
export const M06_TONE_VAR: Record<InsTone, string> = {
  success: '--success-base', warning: '--warning-base', error: '--error-base',
  info: '--info-base', neutral: '--text-sub', processing: '--info-base', violet: '--data-4',
};
