  maLo: string;
  soHoSo: string;
  tenLo: string;
  ky: string;               // id InsKy (_core)
  loaiThuTuc: string;       // nhóm "Thu BHXH/BHYT/BHTN" → M03
  lan: number;
  phongBan: string;
  donViId: string;
  maBHXH: string;
  phienBanBieuMau: InsBieuMau;
  kenhNop: InsKenhNop;
  trangThai: InsLoTrangThai;
  ketQuaTongHop?: InsLoKetQua;      // chỉ khi co-ket-qua
  nguoiLap: string; thoiDiemLap: string;
  nguoiKiemTra?: string; thoiDiemKiemTra?: string;
  nguoiDuyet?: string; thoiDiemDuyet?: string;
  nguoiKy?: string; thoiDiemKy?: string;
  nguoiNop?: string; thoiDiemNop?: string;
