  maLoGoc?: string;         // lô sửa → link lô gốc
  soLanNop: number;         // idempotent maLo + lanNop
  nhomNguyenNhan?: string;  // lô sửa: nhóm nguyên nhân
  bangChung: BangChungGiaoDich[]; // append-only theo lần nộp
