/** "Hôm nay" demo — dùng chung INS_TODAY (_core, 19/08/2026). Nguồn ở _core để M03 KHÔNG import
 *  _m02-data chỉ vì ngày → cắt cạnh vòng import m02↔m03 (UX-1 cho M02 inject InsM03Store). */
export const M03_TODAY = INS_TODAY;
let clockMin = 0;
function demoNow(): string {
  clockMin += 5;
  const h = 9 + Math.floor(clockMin / 60), m = clockMin % 60;
  return `${M03_TODAY} ${String(Math.min(h, 18)).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
}

const clone = <T>(x: T): T => structuredClone(x);

/** Lô "đang mở" theo nghĩa CHƯA NỘP (được sửa/xóa/thêm item). */
const LO_CHUA_NOP = new Set<InsLoTrangThai>(['nhap', 'bi-tra-lai', 'dang-kiem-tra', 'cho-duyet', 'da-duyet', 'da-ky']);

let loSuaSeq = 0;
let lanChaySeq = 2;
/** UX-1: số lô cấp phát khi NHẬN từ M02 (khác dãy seed 08-01/02 và lô sửa 0Sx). */
let loM02Seq = 0;

/** UX-1: dữ liệu tối thiểu M02 đẩy sang để M03 dựng InsLoItem thật (M03 KHÔNG cần biết type M02). */
export interface NhanLoM02Item {
  refDong: string;          // id dòng biến động M02 (lineage)
  refSuKien: string;        // mô tả sự kiện nguồn
  nhanVienId: string;
  maTrangThaiNV: string;    // = mã phương án
  maPhuongAn?: string; tenPhuongAn?: string;
  luongCanCu: string; ngayHLLuong: string;
  correlationId: string;    // mã tương quan 2 chiều
}

@Injectable({ providedIn: 'root' })
export class InsM03Store {
  readonly currentUser = HR_1;

  /** BQA-14: đọc trạng thái kỳ SỐNG do M04 sở hữu. Inject LAZY (Injector.get) vì M04 inject ngược
   *  InsM03Store → tránh vòng DI (M03 KHÔNG gọi khi khởi tạo, chỉ khi method chạy). */
  private readonly injector = inject(Injector);
  private get m04(): InsM04Store { return this.injector.get(InsM04Store); }

  constructor() {
    // BQA-14: đăng ký reader kỳ-đã-khóa SỐNG (M04 sở hữu) cho _core → insKyDaKhoa lan runtime.
    insSetKyKhoaReader((ky) => this.m04.isKyKhoa(ky));
  }

  readonly los = signal<InsLo[]>(clone(LO_SEED));
  readonly items = signal<InsLoItem[]>(clone(ITEM_SEED));
  readonly hoiTo = signal<DongHoiTo[]>(clone(HOITO_SEED));
  readonly tamDung = signal<HoSoTamDung[]>(clone(TAMDUNG_SEED));
  readonly lanChay = signal<LanChay[]>(clone(LANCHAY_SEED));
  readonly dongLoi = signal<DongLoi[]>(clone(DONGLOI_SEED));
  /** Nhật ký append-only (bất biến #3). */
  readonly audit = signal<InsM03AuditEntry[]>([]);
  /** Đợt phân tích hiện hành — chặn chọn lùi (nguyên văn PBI khi vi phạm). */
  readonly dotHienTai = signal(3);

  /** Ngữ cảnh màn: kỳ + đơn vị đang chọn (thanh KỲ). */
  readonly kyId = signal('k08');
  readonly donViId = signal('dv1');
  /** Loại kỳ trên bộ chọn kỳ SC-B1 (mặc định "Kỳ hiện tại"). 'dieu-chinh' = Đợt điều chỉnh. */
  readonly loaiKy = signal<InsLoaiKyKeKhai>('hien-tai');

  resetDemo(): void {
    this.los.set(clone(LO_SEED)); this.items.set(clone(ITEM_SEED));
    this.hoiTo.set(clone(HOITO_SEED)); this.tamDung.set(clone(TAMDUNG_SEED));
    this.lanChay.set(clone(LANCHAY_SEED)); this.dongLoi.set(clone(DONGLOI_SEED));
    this.audit.set([]); this.dotHienTai.set(3);
    this.kyId.set('k08'); this.donViId.set('dv1'); this.loaiKy.set('hien-tai');
  }

  /* ── lookups ── */
  lo(id: string): InsLo | undefined { return this.los().find((l) => l.maLo === id); }
  item(id: string): InsLoItem | undefined { return this.items().find((i) => i.maItem === id); }
  itemsOfLo(loId: string): InsLoItem[] { return this.items().filter((i) => i.loId === loId); }

  readonly kyLocked = computed(() => insKyDaKhoa(this.kyId()));
  readonly losOfKy = computed(() => this.los().filter((l) => l.ky === this.kyId()));
  readonly itemsOfKy = computed(() => {
    const loIds = new Set(this.losOfKy().map((l) => l.maLo));
    return this.items().filter((i) => i.loId !== null && loIds.has(i.loId));
  });
  /** Ứng viên đủ điều kiện: cùng kỳ · Sẵn sàng · chưa thuộc lô đang mở. */
  readonly candidatesOfKy = computed(() =>
    this.items().filter((i) => i.loId === null && i.trangThai === 'san-sang' && i.ky === this.kyId()));
  readonly lanChayOfKy = computed(() => this.lanChay().filter((r) => r.ky === this.kyId()));
  readonly dongLoiOfKy = computed(() => this.dongLoi().filter((r) => r.ky === this.kyId()));

  /* ── Loại kỳ + 4 nhóm kê khai (SC-B1 — YC1/YC3) ── */
  /** Đổi loại kỳ trên bộ chọn kỳ (Kỳ hiện tại / Kỳ tháng tới / Đợt điều chỉnh). */
  setLoaiKy(v: InsLoaiKyKeKhai): void { this.loaiKy.set(v); }

  /** Nhóm kê khai của một dòng theo LOẠI BIẾN ĐỘNG (map từ mã phương án; CD → Đang tham gia).
   *  Dòng không map được xếp vào "Đang tham gia" (đối chiếu, KHÔNG tự kê khai). */
  nhomCuaItem(it: InsLoItem): InsNhomKeKhai {
    if (it.coKhongAnhHuong) return 'dang-tham-gia';
    const code = it.maPhuongAn ?? it.maTrangThaiNV;
    return INS_PHUONGAN_NHOM[code] ?? 'dang-tham-gia';
  }
  /** Ứng viên kỳ hiện hành gom theo 4 nhóm — dựng lưới gom nhóm SC-B1 (🟢🔴🔵⚪). */
  readonly candidatesByNhom = computed<Record<InsNhomKeKhai, InsLoItem[]>>(() => {
    const g: Record<InsNhomKeKhai, InsLoItem[]> = { 'bao-tang': [], 'bao-giam': [], 'dieu-chinh': [], 'dang-tham-gia': [] };
    for (const it of this.candidatesOfKy()) g[this.nhomCuaItem(it)].push(it);
    return g;
  });

  /** Không gian "Đợt điều chỉnh": dòng hồi tố xử lý trong kỳ hiện hành (tháng hiệu lực giữ kỳ gốc). */
  readonly hoiToOfKy = computed(() => this.hoiTo().filter((h) => h.kyXuLy === this.kyId()));

  /* ── Màn "Theo dõi hồ sơ" (m03b) — MỌI lô gom theo kỳ (KHÔNG lọc theo kỳ hiện hành) ── */
  /** MỌI lô (không lọc theo kỳ) — nguồn danh sách Màn A m03b. */
  readonly allLos = computed(() => this.los());

  /** Lô CHƯA NỘP mới nhất của kỳ hiện hành (mặc định bộ chọn lô modal "Lập tờ khai");
   *  null nếu kỳ hiện hành chưa có lô còn sửa được. */
  loHienTaiCuaKy(): InsLo | null {
    const chuaNop = this.losOfKy().filter((l) => INS_LO_TRANGTHAI_CHUA_NOP.has(l.trangThai));
    return chuaNop.length ? chuaNop[chuaNop.length - 1] : null;
  }

  /** Tổng hợp theo KỲ (mọi kỳ có lô) — nguồn cho group header Màn A m03b.
   *  key = id kỳ · soLo = số lô của kỳ · tongHoSo = tổng item trong các lô của kỳ ·
   *  soLoCoKQ = số lô trạng thái 'co-ket-qua' · trangThaiKy = nhãn trạng thái kỳ. */
  readonly kyAggregates = computed<Record<string, { soLo: number; tongHoSo: number; soLoCoKQ: number; trangThaiKy: string }>>(() => {
    const los = this.los();
    const items = this.items();
    // Đếm item theo lô một lượt (tránh O(n²) lồng filter).
    const itemCountByLo = new Map<string, number>();
    for (const it of items) if (it.loId !== null) itemCountByLo.set(it.loId, (itemCountByLo.get(it.loId) ?? 0) + 1);

    const agg: Record<string, { soLo: number; tongHoSo: number; soLoCoKQ: number; trangThaiKy: string }> = {};
    for (const lo of los) {
      const e = agg[lo.ky] ?? (agg[lo.ky] = {
        soLo: 0, tongHoSo: 0, soLoCoKQ: 0,
        trangThaiKy: INS_KY_LABEL[insKy(lo.ky)?.trangThai ?? 'mo'] ?? lo.ky,
      });
      e.soLo += 1;
      e.tongHoSo += itemCountByLo.get(lo.maLo) ?? 0;
      if (lo.trangThai === 'co-ket-qua') e.soLoCoKQ += 1;
    }
    return agg;
  });

  /* ── helpers ── */
  private patchLo(id: string, p: Partial<InsLo>): void {
    this.los.update((l) => l.map((x) => (x.maLo === id ? { ...x, ...p } : x)));
  }
  private patchItem(id: string, p: Partial<InsLoItem>): void {
    this.items.update((l) => l.map((x) => (x.maItem === id ? { ...x, ...p } : x)));
  }
  private log(e: Omit<InsM03AuditEntry, 'at' | 'nguoi'> & { nguoi?: string }): void {
    this.audit.update((l) => [...l, { at: demoNow(), nguoi: e.nguoi ?? this.currentUser, ...e }]);
  }
  private lockedReason(kyId: string): string | null {
    return insKyDaKhoa(kyId) ? `${insKy(kyId)?.label ?? kyId} đã khóa — toàn màn chỉ đọc.` : null;
  }

  /** BQA-5: mọi mutation NỘI DUNG lô (thêm/gỡ item · đổi tham số) khi lô ĐÃ DUYỆT / ĐÃ KÝ →
   *  tự HẠ về Nháp, xóa người duyệt/ký + chữ ký mất hiệu lực + log. Gọi SAU khi đã patch nội dung. */
  private haNhapSauDuyetKy(loId: string): void {
    const lo = this.lo(loId);
    if (!lo || (lo.trangThai !== 'da-duyet' && lo.trangThai !== 'da-ky')) return;
    const truoc = INS_LO_LABEL[lo.trangThai];
    this.patchLo(loId, {
      trangThai: 'nhap',
      nguoiDuyet: undefined, thoiDiemDuyet: undefined,
      nguoiKy: undefined, thoiDiemKy: undefined,
      chuKyHieuLuc: false,
    });
    this.log({ hanhDong: 'Sửa sau duyệt/ký → mất hiệu lực', doiTuong: loId, truoc, sau: INS_LO_LABEL['nhap'] });
  }

  tacDong(loId: string): InsTacDongLo | null {
    return TACDONG_SEED.find((t) => t.loId === loId) ?? null;
  }

  /* ═════════ ① TRÌNH DUYỆT — chặn khi còn item Lỗi ═════════ */
  trinhDuyetReason(loId: string): string | null {
    const lo = this.lo(loId);
    if (!lo) return 'Không tìm thấy lô.';
    const locked = this.lockedReason(lo.ky);
    if (locked) return locked;
    if (lo.trangThai !== 'nhap' && lo.trangThai !== 'bi-tra-lai' && lo.trangThai !== 'dang-kiem-tra') {
      return `Lô đang ở trạng thái ${INS_LO_LABEL[lo.trangThai]} — chỉ trình duyệt lô Nháp/Bị trả lại.`;
    }
    const its = this.itemsOfLo(loId);
    if (!its.length) return 'Lô chưa có item nào.';
    const nLoi = its.filter((i) => i.ketQuaPreCheck === 'loi').length;
    if (nLoi > 0) return `① Còn ${nLoi} item Lỗi — tách item lỗi hoặc sửa trước khi trình duyệt.`;
    const nChua = its.filter((i) => i.ketQuaPreCheck === null).length;
    if (nChua > 0) return `${nChua} item chưa chạy pre-check — chạy pre-check trước khi trình duyệt.`;
    return null;
  }
  trinhDuyet(loId: string): { ok: boolean; reason?: string } {
    const reason = this.trinhDuyetReason(loId);
    if (reason) return { ok: false, reason };
    this.patchLo(loId, { trangThai: 'cho-duyet', nguoiKiemTra: this.currentUser, thoiDiemKiemTra: demoNow() });
    this.log({ hanhDong: 'Trình duyệt lô', doiTuong: loId, truoc: 'Nháp', sau: 'Chờ duyệt' });
    return { ok: true };
  }

  /* ═════════ DUYỆT / TRẢ LẠI (maker–checker) ═════════ */
  duyetReason(loId: string): string | null {
    const lo = this.lo(loId);
    if (!lo) return 'Không tìm thấy lô.';
    const locked = this.lockedReason(lo.ky);
    if (locked) return locked;
    if (lo.trangThai !== 'cho-duyet') return `Lô đang ở trạng thái ${INS_LO_LABEL[lo.trangThai]} — chỉ duyệt lô Chờ duyệt.`;
    const canhBaoChuaChapNhan = this.itemsOfLo(loId).filter((i) => i.ketQuaPreCheck === 'canh-bao' && !i.canhBaoChapNhan).length;
    if (canhBaoChuaChapNhan > 0) return `${canhBaoChuaChapNhan} item Cảnh báo chưa được chấp nhận có lý do — duyệt khi mọi item Đạt hoặc Cảnh báo đã chấp nhận.`;
    return null;
  }
  duyet(loId: string): { ok: boolean; reason?: string } {
    const reason = this.duyetReason(loId);
    if (reason) return { ok: false, reason };
    const lo = this.lo(loId)!;
    if (lo.nguoiLap === APPROVER) return { ok: false, reason: 'Người lập không được duyệt chính lô của mình (maker–checker).' };
    this.patchLo(loId, { trangThai: 'da-duyet', nguoiDuyet: APPROVER, thoiDiemDuyet: demoNow() });
    this.log({ nguoi: APPROVER, hanhDong: 'Duyệt lô', doiTuong: loId, truoc: 'Chờ duyệt', sau: 'Đã duyệt' });
    return { ok: true };
  }
  traLai(loId: string, lyDo: string): { ok: boolean; reason?: string } {
    const lo = this.lo(loId);
    if (!lo) return { ok: false, reason: 'Không tìm thấy lô.' };
    if (!lyDo.trim()) return { ok: false, reason: 'Trả lại BẮT BUỘC có lý do.' };
    if (lo.trangThai !== 'cho-duyet' && lo.trangThai !== 'da-duyet') return { ok: false, reason: `Lô đang ở trạng thái ${INS_LO_LABEL[lo.trangThai]} — không trả lại được.` };
    this.patchLo(loId, { trangThai: 'bi-tra-lai', lyDoTraLai: lyDo.trim(), nguoiDuyet: undefined, thoiDiemDuyet: undefined });
    this.log({ nguoi: APPROVER, hanhDong: 'Trả lại lô', doiTuong: loId, truoc: INS_LO_LABEL[lo.trangThai], sau: 'Bị trả lại (→ Nháp)', lyDo: lyDo.trim() });
    return { ok: true };
  }
  /** Chấp nhận cảnh báo = OVERRIDE audit (lý do + người + trước/sau). */
  chapNhanCanhBao(itemId: string, lyDo: string): { ok: boolean; reason?: string } {
    const it = this.item(itemId);
    if (!it) return { ok: false, reason: 'Không tìm thấy item.' };
    if (!lyDo.trim()) return { ok: false, reason: 'Chấp nhận cảnh báo BẮT BUỘC có lý do (override).' };
    if (it.ketQuaPreCheck !== 'canh-bao') return { ok: false, reason: 'Item không ở trạng thái Cảnh báo.' };
    if (it.canhBaoChapNhan) return { ok: false, reason: 'Cảnh báo đã được chấp nhận trước đó.' };
    this.patchItem(itemId, { canhBaoChapNhan: { lyDo: lyDo.trim(), nguoi: APPROVER, at: demoNow() } });
    this.log({ nguoi: APPROVER, hanhDong: 'Chấp nhận cảnh báo (override)', doiTuong: itemId, truoc: 'Cảnh báo', sau: 'Cảnh báo — đã chấp nhận', lyDo: lyDo.trim() });
    return { ok: true };
  }

  /* ═════════ ② KÝ — chặn khi lô chưa duyệt ═════════ */
  kyReason(loId: string): string | null {
    const lo = this.lo(loId);
    if (!lo) return 'Không tìm thấy lô.';
    const locked = this.lockedReason(lo.ky);
    if (locked) return locked;
    if (lo.trangThai === 'da-ky') return 'Lô đã ký — nội dung ký là bản đóng băng.';
    if (lo.trangThai !== 'da-duyet') return `② Lô chưa duyệt (hiện: ${INS_LO_LABEL[lo.trangThai]}) — chỉ ký lô Đã duyệt không còn Lỗi.`;
    return null;
  }
  ky(loId: string): { ok: boolean; reason?: string } {
    const reason = this.kyReason(loId);
    if (reason) return { ok: false, reason };
    const its = this.itemsOfLo(loId);
    this.patchLo(loId, {
      trangThai: 'da-ky', nguoiKy: SIGNER, thoiDiemKy: demoNow(),
      noiDungDongBang: `sha256:${loId.slice(-2)}f${its.length}e…d2 · ${its.length} item · ${INS_BIEUMAU_LABEL[this.lo(loId)!.phienBanBieuMau]}`,
      chuKyHieuLuc: true,
    });
    this.log({ nguoi: SIGNER, hanhDong: 'Ký số lô (bản đóng băng)', doiTuong: loId, truoc: 'Đã duyệt', sau: 'Đã ký' });
    return { ok: true };
  }

  /* ═════════ ③ NỘP — chặn khi lô chưa ký; 6 dữ kiện; idempotent maLo + lanNop ═════════ */
  nopReason(loId: string): string | null {
    const lo = this.lo(loId);
    if (!lo) return 'Không tìm thấy lô.';
    const locked = this.lockedReason(lo.ky);
    if (locked) return locked;
    if (lo.trangThai === 'da-nop' || lo.trangThai === 'co-ket-qua') return `Lô đã nộp (lần ${lo.soLanNop}) — nộp lại phải qua LÔ SỬA.`;
    if (lo.trangThai !== 'da-ky') return `③ Lô chưa ký số (hiện: ${INS_LO_LABEL[lo.trangThai]}) — ký trước khi nộp.`;
    if (lo.chuKyHieuLuc === false) return 'Chữ ký đã mất hiệu lực do sửa sau ký — ký lại trước khi nộp.';
    return null;
  }
  nop(loId: string): { ok: boolean; reason?: string; maGD?: string } {
    const reason = this.nopReason(loId);
    if (reason) return { ok: false, reason };
    const lo = this.lo(loId)!;
    const lanNop = lo.soLanNop + 1;
    // Idempotent: đã có bằng chứng cho lần nộp này → không ghi đè, không nộp trùng.
    if (lo.bangChung.some((b) => b.lanNop === lanNop)) {
      return { ok: false, reason: `Đã có bằng chứng giao dịch lần nộp ${lanNop} (idempotent mã lô + lần nộp) — không nộp trùng.` };
    }
    const maGD = `GDT-2026-08-${String(1200 + lanNop)}`;
    const bc: BangChungGiaoDich = {
      maGD, payload: `${INS_BIEUMAU_LABEL[lo.phienBanBieuMau]} · ${this.itemsOfLo(loId).length} item · ${lo.noiDungDongBang ?? ''}`,
      phienBanBM: `${INS_BIEUMAU_LABEL[lo.phienBanBieuMau]} (bộ 01/2026)`,
      chuKy: `VNR-CA · serial 5A02…F9 · ký ${lo.thoiDiemKy ?? ''}`,
      phanHoi: 'Tiếp nhận chờ xử lý — cổng ' + INS_KENHNOP_LABEL[lo.kenhNop],
      thoiDiem: demoNow(), lanNop,
    };
    this.patchLo(loId, { trangThai: 'da-nop', nguoiNop: this.currentUser, thoiDiemNop: bc.thoiDiem, soLanNop: lanNop, bangChung: [...lo.bangChung, bc] });
    for (const it of this.itemsOfLo(loId)) this.patchItem(it.maItem, { trangThai: 'da-nop', coDaNop: true, ngayNop: M03_TODAY });
    this.log({ hanhDong: `Nộp lô (lần ${lanNop}) — lưu 6 dữ kiện bằng chứng`, doiTuong: loId, truoc: 'Đã ký', sau: 'Đã nộp' });
    return { ok: true, maGD };
  }

  /* ═════════ ④ TẠO LÔ SỬA — chặn khi kỳ đã khóa; chỉ item Bị từ chối; partial ═════════ */
  taoLoSuaReason(loId: string): string | null {
    const lo = this.lo(loId);
    if (!lo) return 'Không tìm thấy lô.';
    if (insKyDaKhoa(lo.ky)) return `④ ${insKy(lo.ky)?.label ?? lo.ky} đã khóa — không tạo lô sửa; chỉ còn Trả về 02 / Loại trừ có lý do.`;
    if (lo.trangThai !== 'co-ket-qua') return `Lô chưa có kết quả (hiện: ${INS_LO_LABEL[lo.trangThai]}) — chỉ tạo lô sửa từ lô Có kết quả.`;
    if (!this.itemsOfLo(loId).some((i) => i.trangThai === 'bi-tu-choi')) return 'Không còn item Bị từ chối nào chưa vào lô sửa.';
    return null;
  }
  taoLoSua(loId: string): { ok: boolean; reason?: string; maLoMoi?: string; done: number; skipped: { maItem: string; reason: string }[] } {
    const reason = this.taoLoSuaReason(loId);
    if (reason) return { ok: false, reason, done: 0, skipped: [] };
    const goc = this.lo(loId)!;
    const maLoMoi = `LO-2026-0S${String(++loSuaSeq)}`;
    const skipped: { maItem: string; reason: string }[] = [];
    let done = 0;
    for (const it of this.itemsOfLo(loId)) {
      if (it.trangThai === 'duoc-chap-nhan') { skipped.push({ maItem: it.maItem, reason: 'Item đã chấp nhận — không vào lô sửa.' }); continue; }
      if (it.trangThai === 'vao-lo-sua') { skipped.push({ maItem: it.maItem, reason: 'Đã ở trong lô sửa trước đó (idempotent).' }); continue; }
      if (it.trangThai !== 'bi-tu-choi') { skipped.push({ maItem: it.maItem, reason: `Trạng thái ${INS_LO_ITEM_LABEL[it.trangThai]} — chỉ item Bị từ chối.` }); continue; }
      done++;
      const nItem: InsLoItem = {
        ...clone(it), maItem: `${it.maItem}-s${goc.soLanNop + 1}`, loId: maLoMoi,
        trangThai: 'da-vao-lo', ketQuaPreCheck: null, truongViPham: [], canhBaoChapNhan: undefined,
        coDaNop: false, ngayNop: undefined, ketQuaCQ: null, lyDoTuChoi: undefined, phienBanKetQua: 0, lichSuKetQua: [],
        refItemGoc: it.maItem, nhanNguon: `Lô sửa từ ${goc.maLo} · lần nộp ${goc.soLanNop + 1}`,
      };
      this.items.update((l) => [...l, nItem]);
      this.patchItem(it.maItem, { trangThai: 'vao-lo-sua', phanLoaiTrangThai: 'da-dong' });
    }
    if (!done) return { ok: false, reason: 'Không có item nào đủ điều kiện vào lô sửa.', done: 0, skipped };
    const nLo: InsLo = {
      ...clone(goc), maLo: maLoMoi, soHoSo: `${goc.soHoSo}-S${loSuaSeq}`, tenLo: `Lô sửa — ${goc.tenLo}`,
      lan: goc.lan + 1, trangThai: 'nhap', maLoGoc: goc.maLo, soLanNop: goc.soLanNop,
      nhomNguyenNhan: 'Item bị cơ quan BHXH từ chối', bangChung: [],
      nguoiLap: this.currentUser, thoiDiemLap: demoNow(),
      nguoiKiemTra: undefined, thoiDiemKiemTra: undefined, nguoiDuyet: undefined, thoiDiemDuyet: undefined,
      nguoiKy: undefined, thoiDiemKy: undefined, nguoiNop: undefined, thoiDiemNop: undefined,
      noiDungDongBang: undefined, chuKyHieuLuc: undefined, ketQuaTongHop: undefined, lyDoTraLai: undefined,
    };
    this.los.update((l) => [...l, nLo]);
    this.log({ hanhDong: `Tạo lô sửa ${maLoMoi} (đi lại đủ B2+B3)`, doiTuong: loId, sau: `${done} item Bị từ chối → ${maLoMoi}` });
    return { ok: true, maLoMoi, done, skipped };
  }

  /* ═════════ UX-1 — NHẬN LÔ TỪ M02 (M02 gọi khi "Chuyển sang lô kê khai") ═════════ */
  /** Tạo InsLo THẬT (trạng thái Nháp) + InsLoItem cho từng dòng M02 chuyển sang. Trả maLo THẬT để
   *  M02 điều hướng `shell.go('m03', {filter:'lo:<maLo>', ky})`. KỲ CỦA LÔ = kỳ dòng (p.ky). */
  nhanLoTuM02(p: { ky: string; donViId: string; maBHXH: string; loaiThuTuc?: string; items: NhanLoM02Item[] }): string {
    const label = insKy(p.ky)?.label ?? p.ky;                 // "Kỳ 08/2026"
    const mm = /(\d{2})\/\d{4}/.exec(label)?.[1] ?? '08';
    const loaiThuTuc = p.loaiThuTuc ?? 'Thu BHXH/BHYT/BHTN';
    // Đợt 2 — SMART BATCHING: TÌM lô ĐANG MỞ (Nháp) do M02 tạo, cùng kỳ + đơn vị + mã BHXH + loại thủ
    // tục → APPEND vào (né lô đã ký/nộp/khóa và lô seed). Không tìm thấy → tạo mới. HR không tạo lô mỗi lần.
    const open = this.los().find((l) =>
      l.trangThai === 'nhap' && l.maLo.includes('-B') &&
      l.ky === p.ky && l.donViId === p.donViId && l.maBHXH === p.maBHXH && l.loaiThuTuc === loaiThuTuc);
    let maLo: string;
    if (open) {
      maLo = open.maLo;
    } else {
      const seq = ++loM02Seq;
      maLo = `LO-2026-${mm}-B${seq}`;
      const nLo: InsLo = {
        maLo, soHoSo: `${mm}-2026/B${String(seq).padStart(2, '0')}`, tenLo: `Lô từ biến động M02 — ${label}`,
        ky: p.ky, loaiThuTuc, lan: 1, phongBan: 'Toàn công ty',
        donViId: p.donViId, maBHXH: p.maBHXH, phienBanBieuMau: 'd02ts', kenhNop: 'ebhxh', trangThai: 'nhap',
        nguoiLap: this.currentUser, thoiDiemLap: demoNow(), soLanNop: 0, bangChung: [],
      };
      this.los.update((l) => [...l, nLo]);
    }
    // Đánh số item nối tiếp item đã có trong lô (append idempotent — không đè maItem cũ).
    let idx = this.items().filter((i) => i.loId === maLo).length;
    for (const it of p.items) {
      const nItem: InsLoItem = {
        maItem: `${maLo}-i${++idx}`, loId: maLo, ky: p.ky, refDong: it.refDong, refSuKien: it.refSuKien,
        nhanVienId: it.nhanVienId, maTrangThaiNV: it.maTrangThaiNV, maPhuongAn: it.maPhuongAn,
        tenPhuongAn: it.tenPhuongAn, phienBanPA: 'v2026.1', luongCanCu: it.luongCanCu, ngayHLLuong: it.ngayHLLuong,
        ketQuaPreCheck: null, truongViPham: [], trangThai: 'da-vao-lo', ketQuaCQ: null,
        phienBanKetQua: 0, lichSuKetQua: [], nhanNguon: `M02 · ${it.correlationId}`,
      };
      this.items.update((l) => [...l, nItem]);
    }
    this.log({ hanhDong: `Nhận lô từ M02 — ${p.items.length} item vào ${maLo} (${label})`, doiTuong: maLo, sau: `${p.items.length} item` });
    return maLo;
  }

  /* ═════════ BQA-10 — NHẬN DÒNG GỘP SỔ GIẢM TRÙNG TỪ M06 (link 2 chiều) ═════════ */
  /** M06 (chủ gộp sổ) gọi khi xác nhận khoảng trùng: tạo/ghép lô "gộp sổ" theo kỳ chứa 1 InsLoItem
   *  D02-LT giảm trùng, trạng thái chờ M03 kiểm tra/duyệt (lô Nháp → đi B2), lineage NGƯỢC `maHoSoGoc`
   *  M06 + `correlationId` 2 chiều. Trả `{maLo, maItem}` để M06 giữ và đọc trạng thái nhánh D02 sống.
   *  Idempotent theo lô kỳ: chạy lại KHÔNG sinh lô trùng (ghép vào lô gộp sổ cùng kỳ). */
  nhanDongGiamTrungTuM06(p: {
    ky: string; donViId: string; maBHXH: string; nhanVienId: string;
    khoang: { tu: string; den: string }; maHoSoGoc: string; correlationId: string;
  }): { maLo: string; maItem: string } {
    const label = insKy(p.ky)?.label ?? p.ky;
    const mm = /(\d{2})\/\d{4}/.exec(label)?.[1] ?? '08';
    const maLo = `LO-2026-${mm}-GS`;                          // lô gộp sổ giảm trùng theo kỳ
    let lo = this.los().find((l) => l.maLo === maLo);
    if (!lo) {
      lo = {
        maLo, soHoSo: `${mm}-2026/GS`, tenLo: `Lô gộp sổ giảm trùng (D02-LT) — ${label}`,
        ky: p.ky, loaiThuTuc: 'Thu BHXH/BHYT/BHTN', lan: 1, phongBan: 'Toàn công ty',
        donViId: p.donViId, maBHXH: p.maBHXH, phienBanBieuMau: 'd02ts', kenhNop: 'ebhxh', trangThai: 'nhap',
        nguoiLap: this.currentUser, thoiDiemLap: demoNow(), soLanNop: 0, bangChung: [],
      };
      this.los.update((l) => [...l, lo!]);
    }
    const stt = this.items().filter((i) => i.loId === maLo).length + 1;
    const maItem = `${maLo}-gt${stt}`;
    const nItem: InsLoItem = {
      maItem, loId: maLo, ky: p.ky, refDong: p.maHoSoGoc,
      refSuKien: `Gộp sổ giảm trùng D02-LT — khoảng ${p.khoang.tu} – ${p.khoang.den} (nguồn M06 ${p.maHoSoGoc})`,
      nhanVienId: p.nhanVienId, maTrangThaiNV: 'GT', maPhuongAn: 'GT',
      tenPhuongAn: 'Giảm trùng quá trình đóng (gộp sổ)', phienBanPA: 'v2026.1',
      luongCanCu: '—', ngayHLLuong: p.khoang.tu, thieuLuong: false,
      ketQuaPreCheck: null, truongViPham: [], trangThai: 'da-vao-lo', ketQuaCQ: null,
      phienBanKetQua: 0, lichSuKetQua: [], nhanNguon: `M06 gộp sổ · ${p.maHoSoGoc} · ${p.correlationId}`,
    };
    this.items.update((l) => [...l, nItem]);
    this.log({ hanhDong: `Nhận dòng D02-LT giảm trùng từ M06 (${p.maHoSoGoc}) vào ${maLo} — chờ kiểm tra/duyệt`, doiTuong: maLo, sau: `${maItem} · ${p.correlationId}` });
    return { maLo, maItem };
  }

  /* ═════════ ⑤ ⑦ THÊM VÀO LÔ — dry-run + bulk partial ═════════ */
  themVaoLoSkipReason(itemId: string, loId: string): string | null {
    const it = this.item(itemId);
    const lo = this.lo(loId);
    if (!it || !lo) return 'Không tìm thấy item/lô.';
    const locked = this.lockedReason(lo.ky);
    if (locked) return locked;
    if (!LO_CHUA_NOP.has(lo.trangThai)) return 'Chỉ được cập nhật dữ liệu ở trạng thái: [Chưa gửi]!';
    if (it.loId === loId) return 'Item đã nằm trong lô này (idempotent — không thêm trùng).';
    if (it.loId !== null) return `Item đang thuộc lô ${it.loId} — gỡ khỏi lô đó trước.`;
    if (it.trangThai !== 'san-sang') return `Item chưa Sẵn sàng (hiện: ${INS_LO_ITEM_LABEL[it.trangThai]}).`;
    if (it.ky !== lo.ky) return 'Item khác kỳ với lô — ứng viên phải cùng kỳ.';
    if (!it.maPhuongAn) return `⑦ ${insKy(it.ky)?.label ?? it.ky} không có mã phương án hiệu lực cho dòng — bổ sung danh mục tại M08.`;
    if (it.truyThu && !it.coD01TS) return '⑤ Dòng truy thu/thoái thu chưa có chứng từ D01-TS — bổ sung trước khi vào lô.';
    const trungNLD = this.items().some((x) =>
      x.maItem !== it.maItem && x.nhanVienId === it.nhanVienId && x.loId !== null &&
      this.lo(x.loId!)?.ky === lo.ky && LO_CHUA_NOP.has(this.lo(x.loId!)!.trangThai));
    if (trungNLD) return '1 NLĐ không được ở 2 lô chưa nộp cùng kỳ + loại thủ tục.';
    return null;
  }
  /** Dry-run cho ins-bulk-bar — KHÔNG đổi state (pure read). */
  themVaoLoPreview(itemIds: string[], loId: string): { eligible: number; blocked: { reason: string; count: number }[] } {
    const byReason = new Map<string, number>();
    let eligible = 0;
    for (const id of itemIds) {
      const r = this.themVaoLoSkipReason(id, loId);
      if (r === null) eligible++;
      else byReason.set(r, (byReason.get(r) ?? 0) + 1);
    }
    return { eligible, blocked: [...byReason].map(([reason, count]) => ({ reason, count })) };
  }
  themVaoLo(itemIds: string[], loId: string): { done: number; skipped: { id: string; reason: string }[] } {
    const skipped: { id: string; reason: string }[] = [];
    const doneIds: string[] = [];
    for (const id of itemIds) {
      const r = this.themVaoLoSkipReason(id, loId);
      if (r) { skipped.push({ id, reason: r }); continue; }
      this.patchItem(id, { loId, trangThai: 'da-vao-lo', ketQuaPreCheck: null });
      doneIds.push(id);
    }
    if (doneIds.length) {
      this.log({ hanhDong: 'Thêm item vào lô', doiTuong: loId, sau: `${doneIds.length} item: ${doneIds.join(', ')}` });
      this.haNhapSauDuyetKy(loId); // BQA-5: thêm item vào lô đã duyệt/ký → hạ Nháp + hủy hiệu lực
    }
    return { done: doneIds.length, skipped };
  }
  /** Gỡ item khỏi lô → về Sẵn sàng, DÒNG GỐC NGUYÊN (không xóa). */
  goKhoiLo(itemId: string): { ok: boolean; reason?: string } {
    const it = this.item(itemId);
    if (!it || !it.loId) return { ok: false, reason: 'Item không thuộc lô nào.' };
    const lo = this.lo(it.loId)!;
    if (!LO_CHUA_NOP.has(lo.trangThai)) return { ok: false, reason: 'Chỉ được cập nhật dữ liệu ở trạng thái: [Chưa gửi]!' };
    if (insKyDaKhoa(lo.ky)) return { ok: false, reason: this.lockedReason(lo.ky)! };
    this.patchItem(itemId, { loId: null, trangThai: 'san-sang', ketQuaPreCheck: null, truongViPham: it.truongViPham, canhBaoChapNhan: undefined });
    this.log({ hanhDong: 'Gỡ item khỏi lô (dòng gốc giữ nguyên)', doiTuong: itemId, truoc: lo.maLo, sau: 'Sẵn sàng' });
    this.haNhapSauDuyetKy(lo.maLo); // BQA-5: gỡ item khỏi lô đã duyệt/ký → hạ Nháp + hủy hiệu lực
    return { ok: true };
  }

  /** Đổi 2 THAM SỐ lô (biểu mẫu / kênh nộp) — sau nộp bị khóa (nguyên văn PBI). */
  doiThamSoLo(loId: string, p: { phienBanBieuMau?: InsBieuMau; kenhNop?: InsKenhNop }): { ok: boolean; reason?: string } {
    const lo = this.lo(loId);
    if (!lo) return { ok: false, reason: 'Không tìm thấy lô.' };
    if (!LO_CHUA_NOP.has(lo.trangThai)) return { ok: false, reason: 'Chỉ được cập nhật dữ liệu ở trạng thái: [Chưa gửi]!' };
    if (insKyDaKhoa(lo.ky)) return { ok: false, reason: this.lockedReason(lo.ky)! };
    this.patchLo(loId, { ...p });
    this.log({ hanhDong: 'Đổi tham số lô', doiTuong: loId, sau: `${p.phienBanBieuMau ? 'biểu mẫu ' + INS_BIEUMAU_LABEL[p.phienBanBieuMau] : ''} ${p.kenhNop ? 'kênh ' + INS_KENHNOP_LABEL[p.kenhNop] : ''}`.trim() });
    // BQA-5: đổi THAM SỐ lô đã Duyệt/Ký → hạ Nháp + xóa duyệt/ký + chữ ký mất hiệu lực (không chỉ da-ky→da-duyet).
    this.haNhapSauDuyetKy(loId);
    return { ok: true };
  }

  /** Tạo lô — bắt buộc 5 trường; trùng số hồ sơ cùng kỳ + đơn vị → CHẶN; lưu lô TRƯỚC khi thêm item. */
  taoLo(p: { soHoSo: string; tenLo: string; ky: string; loaiThuTuc: string; phongBan: string }): { ok: boolean; reason?: string; maLo?: string } {
    if (!p.soHoSo.trim() || !p.tenLo.trim() || !p.ky || !p.loaiThuTuc.trim() || !p.phongBan.trim()) {
      return { ok: false, reason: 'Bắt buộc đủ 5 trường: số hồ sơ · tên lô · kỳ · loại thủ tục · phòng ban.' };
    }
    const locked = this.lockedReason(p.ky);
    if (locked) return { ok: false, reason: locked };
    const donVi = this.donViId();
    if (this.los().some((l) => l.soHoSo === p.soHoSo.trim() && l.ky === p.ky && l.donViId === donVi)) {
      return { ok: false, reason: `Trùng số hồ sơ ${p.soHoSo.trim()} trong cùng kỳ + đơn vị — bị chặn.` };
    }
    const maLo = `LO-2026-08-${String(10 + this.los().length)}`;
    this.los.update((l) => [...l, {
      maLo, soHoSo: p.soHoSo.trim(), tenLo: p.tenLo.trim(), ky: p.ky, loaiThuTuc: p.loaiThuTuc.trim(),
      lan: 1, phongBan: p.phongBan.trim(), donViId: donVi, maBHXH: 'HN-070912',
      phienBanBieuMau: 'd02ts', kenhNop: 'ebhxh', trangThai: 'nhap',
      nguoiLap: this.currentUser, thoiDiemLap: demoNow(), soLanNop: 0, bangChung: [],
    }]);
    this.log({ hanhDong: 'Tạo lô kê khai', doiTuong: maLo, sau: `${p.soHoSo.trim()} · ${p.tenLo.trim()}` });
    return { ok: true, maLo };
  }

  /* ═════════ ⑥ TẠM DỪNG HT-TT — trình duyệt cần đủ 2 văn bản ═════════ */
  trinhTamDungReason(id: string): string | null {
    const hs = this.tamDung().find((h) => h.id === id);
    if (!hs) return 'Không tìm thấy hồ sơ.';
    if (hs.trangThai !== 'nhap') return `Hồ sơ đang ở trạng thái ${INS_TAMDUNG_LABEL[hs.trangThai]} — chỉ trình hồ sơ Nháp.`;
    const thieu: string[] = [];
    if (!hs.vanBanDonVi) thieu.push('văn bản đề nghị của đơn vị');
    if (!hs.vanBanCoQuan) thieu.push('văn bản chấp thuận của cơ quan có thẩm quyền');
    if (thieu.length) return `⑥ Chưa đủ 2 văn bản — thiếu ${thieu.join(' và ')}.`;
    return null;
  }
  trinhTamDung(id: string): { ok: boolean; reason?: string } {
    const reason = this.trinhTamDungReason(id);
    if (reason) return { ok: false, reason };
    this.tamDung.update((l) => l.map((h) => (h.id === id ? { ...h, trangThai: 'da-duyet-noi-bo' as const } : h)));
    this.log({ hanhDong: 'Trình duyệt hồ sơ tạm dừng HT-TT', doiTuong: id, truoc: 'Nháp', sau: 'Đã duyệt nội bộ' });
    return { ok: true };
  }
  ketThucSomTamDung(id: string, lyDo: string): { ok: boolean; reason?: string } {
    const hs = this.tamDung().find((h) => h.id === id);
    if (!hs) return { ok: false, reason: 'Không tìm thấy hồ sơ.' };
    if (!lyDo.trim()) return { ok: false, reason: 'Kết thúc sớm BẮT BUỘC có lý do (tính lại nghĩa vụ).' };
    if (hs.trangThai !== 'dang-hieu-luc') return { ok: false, reason: 'Chỉ kết thúc sớm hồ sơ Đang có hiệu lực.' };
    this.tamDung.update((l) => l.map((h) => (h.id === id ? { ...h, trangThai: 'ket-thuc-som' as const, lyDoKetThucSom: lyDo.trim() } : h)));
    this.log({ hanhDong: 'Kết thúc sớm tạm dừng — tính lại nghĩa vụ đóng bù', doiTuong: id, truoc: 'Đang có hiệu lực', sau: 'Kết thúc sớm', lyDo: lyDo.trim() });
    return { ok: true };
  }

  /* ═════════ PRE-CHECK (B2) — theo TỪNG item; chạy lại ghi đè kết quả nhưng GIỮ lịch sử ═════════ */
  chayPreCheck(loId: string): { ok: boolean; reason?: string; dat: number; canhBao: number; loi: number } {
    const lo = this.lo(loId);
    if (!lo) return { ok: false, reason: 'Không tìm thấy lô.', dat: 0, canhBao: 0, loi: 0 };
    if (insKyDaKhoa(lo.ky)) return { ok: false, reason: this.lockedReason(lo.ky)!, dat: 0, canhBao: 0, loi: 0 };
    let dat = 0, canhBao = 0, loi = 0;
    for (const it of this.itemsOfLo(loId)) {
      const kq: InsPreCheck = it.truongViPham.some((v) => v.muc === 'loi') ? 'loi'
        : it.truongViPham.some((v) => v.muc === 'canh-bao') ? 'canh-bao' : it.thieuLuong ? 'loi' : 'dat';
      if (kq === 'loi' && it.thieuLuong && !it.truongViPham.length) {
        this.patchItem(it.maItem, { ketQuaPreCheck: kq, truongViPham: [{ truong: 'luongCanCu', giaTri: '—', canCu: 'R-LUONG-001 v2 — thiếu lương căn cứ hiệu lực so ngày cuối kỳ', muc: 'loi' }] });
      } else {
        this.patchItem(it.maItem, { ketQuaPreCheck: kq });
      }
      kq === 'dat' ? dat++ : kq === 'canh-bao' ? canhBao++ : loi++;
    }
    this.log({ hanhDong: 'Chạy pre-check (ghi đè kết quả, giữ lịch sử)', doiTuong: loId, sau: `${dat} Đạt · ${canhBao} Cảnh báo · ${loi} Lỗi` });
    return { ok: true, dat, canhBao, loi };
  }
  /** Tách item Lỗi khỏi lô — KHÔNG xóa dòng gốc (về Sẵn sàng). */
  tachItemLoi(loId: string): { done: number } {
    const targets = this.itemsOfLo(loId).filter((i) => i.ketQuaPreCheck === 'loi');
    for (const it of targets) this.patchItem(it.maItem, { loId: null, trangThai: 'san-sang' });
    if (targets.length) this.log({ hanhDong: 'Tách item lỗi khỏi lô (dòng gốc giữ nguyên)', doiTuong: loId, sau: `${targets.length} item → Sẵn sàng` });
    return { done: targets.length };
  }

  /* ═════════ B4 — KẾT QUẢ theo TỪNG item; sửa = PHIÊN BẢN MỚI ═════════ */
  ghiKetQua(loId: string, rows: { itemId: string; ketQua: InsKetQuaCQ; lyDo?: string }[]): { done: number; skipped: { id: string; reason: string }[] } {
    const skipped: { id: string; reason: string }[] = [];
    let done = 0;
    for (const r of rows) {
      const it = this.item(r.itemId);
      if (!it || it.loId !== loId) { skipped.push({ id: r.itemId, reason: 'Item không thuộc lô.' }); continue; }
      if (!it.coDaNop) { skipped.push({ id: r.itemId, reason: 'Item chưa nộp — chưa có kết quả để ghi.' }); continue; }
      if (r.ketQua === 'tu-choi' && !r.lyDo) { skipped.push({ id: r.itemId, reason: 'Từ chối BẮT BUỘC lý do danh mục.' }); continue; }
      const pb = it.phienBanKetQua + 1;
      this.patchItem(r.itemId, {
        ketQuaCQ: r.ketQua, lyDoTuChoi: r.ketQua === 'tu-choi' ? r.lyDo : undefined,
        trangThai: r.ketQua === 'chap-nhan' ? 'duoc-chap-nhan' : 'bi-tu-choi',
        phienBanKetQua: pb,
        // F3 — dòng bị từ chối mới bóc tách vào vòng xử lý trả về (chấp nhận → không phân loại).
        phanLoaiTrangThai: r.ketQua === 'tu-choi' ? 'moi-boc-tach' : undefined,
        lichSuKetQua: [...it.lichSuKetQua, { phienBan: pb, ketQua: r.ketQua, lyDo: r.lyDo, nguoi: 'Cổng BHXH', at: demoNow() }],
      });
      done++;
    }
    if (done) {
      const its = this.itemsOfLo(loId);
      const coKQ = its.filter((i) => i.ketQuaCQ !== null);
      const tongHop: InsLoKetQua = coKQ.every((i) => i.ketQuaCQ === 'chap-nhan') ? 'chap-nhan-toan-bo'
        : coKQ.every((i) => i.ketQuaCQ === 'tu-choi') ? 'tu-choi-toan-bo' : 'thanh-cong-mot-phan';
      this.patchLo(loId, { trangThai: 'co-ket-qua', ketQuaTongHop: tongHop });
      this.log({ hanhDong: 'Ghi kết quả cơ quan BHXH (theo TỪNG item)', doiTuong: loId, sau: `${done} item` });
    }
    return { done, skipped };
  }
  /** Nhập tay kết quả — BẮT BUỘC số văn bản + ngày văn bản. */
  nhapTayKetQua(itemId: string, ketQua: InsKetQuaCQ, soVanBan: string, ngayVanBan: string, lyDo?: string): { ok: boolean; reason?: string } {
    const it = this.item(itemId);
    if (!it) return { ok: false, reason: 'Không tìm thấy item.' };
    if (!soVanBan.trim() || !ngayVanBan.trim()) return { ok: false, reason: 'Nhập tay BẮT BUỘC số văn bản và ngày văn bản.' };
    if (ketQua !== 'chap-nhan' && !lyDo?.trim()) return { ok: false, reason: 'Từ chối BẮT BUỘC lý do danh mục.' };
    const pb = it.phienBanKetQua + 1;
    this.patchItem(itemId, {
      ketQuaCQ: ketQua, lyDoTuChoi: ketQua === 'chap-nhan' ? undefined : lyDo?.trim(),
      trangThai: ketQua === 'chap-nhan' ? 'duoc-chap-nhan' : 'bi-tu-choi',
      phienBanKetQua: pb,
      // F3 — nhập tay ra "từ chối" cũng vào vòng xử lý trả về (mới bóc tách).
      phanLoaiTrangThai: ketQua === 'chap-nhan' ? undefined : 'moi-boc-tach',
      lichSuKetQua: [...it.lichSuKetQua, { phienBan: pb, ketQua, lyDo: lyDo?.trim(), nguoi: this.currentUser, at: demoNow(), soVanBan: soVanBan.trim(), ngayVanBan: ngayVanBan.trim() }],
    });
    this.log({ hanhDong: 'Nhập tay kết quả (kèm số văn bản + ngày)', doiTuong: itemId, sau: INS_KETQUA_CQ_LABEL[ketQua], lyDo: `${soVanBan.trim()} · ${ngayVanBan.trim()}` });
    return { ok: true };
  }
  /** Sửa kết quả = TẠO PHIÊN BẢN MỚI (bản cũ xem được) — bắt buộc lý do. */
  suaKetQua(itemId: string, ketQua: InsKetQuaCQ, lyDo: string): { ok: boolean; reason?: string } {
    const it = this.item(itemId);
    if (!it) return { ok: false, reason: 'Không tìm thấy item.' };
    if (!lyDo.trim()) return { ok: false, reason: 'Sửa kết quả BẮT BUỘC lý do — tạo phiên bản mới, không ghi đè.' };
    if (it.ketQuaCQ === null) return { ok: false, reason: 'Item chưa có kết quả để sửa.' };
    const pb = it.phienBanKetQua + 1;
    this.patchItem(itemId, {
      ketQuaCQ: ketQua, lyDoTuChoi: ketQua === 'chap-nhan' ? undefined : lyDo.trim(),
      trangThai: ketQua === 'chap-nhan' ? 'duoc-chap-nhan' : ketQua === 'tu-choi' ? 'bi-tu-choi' : it.trangThai,
      phienBanKetQua: pb,
      lichSuKetQua: [...it.lichSuKetQua, { phienBan: pb, ketQua, lyDo: lyDo.trim(), nguoi: this.currentUser, at: demoNow() }],
    });
    this.log({ hanhDong: `Sửa kết quả → phiên bản v${pb} (bản cũ xem được)`, doiTuong: itemId, truoc: `v${pb - 1}`, sau: `v${pb} · ${INS_KETQUA_CQ_LABEL[ketQua]}`, lyDo: lyDo.trim() });
    return { ok: true };
  }

  /* ═════════ F1/F2/F3 — Phân loại lỗi thuộc về ai + vòng xử lý trả về (doc §9/§10/§13) ═════════ */

  /** F1 — ĐỀ XUẤT phân loại lỗi (mock deterministic theo lyDoTuChoi; người XÁC NHẬN). Thuần — KHÔNG
   *  demoNow/random. null nếu item không bị từ chối. */
  deXuatPhanLoaiLoi(itemId: string): {
    nhan: InsPhanLoaiLoi;
    doChacChan: InsDoChacChan;
    danNguon: { truong: string; minhKhai: string; coQuanGhi: string; khop: boolean }[];
    giaiThich: string;
  } | null {
    const it = this.item(itemId);
    if (!it || it.ketQuaCQ !== 'tu-choi') return null;
    const ly = it.lyDoTuChoi ?? '';
    const pl = INS_LYDO_PHANLOAI[ly] ?? { nhan: 'co-quan' as InsPhanLoaiLoi, doChacChan: 'thap' as InsDoChacChan };
    const dn = INS_LYDO_DANNGUON[ly] ?? {
      danNguon: [] as { truong: string; minhKhai: string; coQuanGhi: string; khop: boolean }[],
      giaiThich: 'Chưa đủ căn cứ đối chiếu — đề xuất mô phỏng, người xác nhận.',
    };
    return { nhan: pl.nhan, doChacChan: pl.doChacChan, danNguon: dn.danNguon, giaiThich: dn.giaiThich };
  }

  /** F1 — XÁC NHẬN / ĐỔI nhãn phân loại lỗi. Đổi nhãn GHI VẾT (trước/sau + lý do). → 'da-phan-loai'. */
  xacNhanPhanLoai(itemId: string, nhan: InsPhanLoaiLoi, lyDo?: string): { ok: boolean; reason?: string } {
    const it = this.item(itemId);
    if (!it) return { ok: false, reason: 'Không tìm thấy item.' };
    if (it.ketQuaCQ !== 'tu-choi') return { ok: false, reason: 'Chỉ phân loại dòng bị từ chối.' };
    const truoc = it.phanLoaiLoi;
    this.patchItem(itemId, { phanLoaiLoi: nhan, phanLoaiTrangThai: 'da-phan-loai' });
    this.log({
      hanhDong: truoc && truoc !== nhan ? 'Đổi nhãn phân loại lỗi' : 'Xác nhận phân loại lỗi',
      doiTuong: itemId,
      truoc: truoc ? INS_PHANLOAI_LOI_LABEL[truoc] : undefined,
      sau: INS_PHANLOAI_LOI_LABEL[nhan],
      lyDo: lyDo?.trim() || undefined,
    });
    return { ok: true };
  }

  /** F3 — bắt đầu xử lý (khi vào sửa / giải trình). → 'dang-xu-ly'. */
  batDauXuLy(itemId: string): { ok: boolean; reason?: string } {
    const it = this.item(itemId);
    if (!it) return { ok: false, reason: 'Không tìm thấy item.' };
    this.patchItem(itemId, { phanLoaiTrangThai: 'dang-xu-ly' });
    this.log({ hanhDong: 'Bắt đầu xử lý dòng kết quả', doiTuong: itemId, sau: INS_PHANLOAI_TRANGTHAI_LABEL['dang-xu-ly'] });
    return { ok: true };
  }

  /** F2 — GIẢI TRÌNH & gửi lại tại chỗ (Lỗi cơ quan / kỹ thuật): GIỮ mốc nộp gốc, không tính trễ.
   *  Nhật ký chỉ-thêm. → 'cho-phan-hoi'. */
  giaiTrinhGuiLai(itemId: string, noiDung: string): { ok: boolean; reason?: string } {
    const it = this.item(itemId);
    if (!it) return { ok: false, reason: 'Không tìm thấy item.' };
    if (!noiDung.trim()) return { ok: false, reason: 'Giải trình BẮT BUỘC nội dung.' };
    const mocNopGoc = it.mocNopGoc ?? it.ngayNop ?? M03_TODAY;
    this.patchItem(itemId, { phanLoaiTrangThai: 'cho-phan-hoi', mocNopGoc });
    this.log({ hanhDong: 'Giải trình & gửi lại — giữ mốc nộp gốc, không tính trễ', doiTuong: itemId, truoc: mocNopGoc, sau: noiDung.trim() });
    return { ok: true };
  }

  /** F3 — ĐÓNG dòng kết quả (đã loại trừ có lý do / đã chấp nhận / đưa vào lô sửa). → 'da-dong'
   *  (kết thúc vòng 5 trạng thái; khi mọi dòng từ chối 'da-dong' → chặng ⑥ hoàn tất). Nhật ký chỉ-thêm. */
  dongPhanLoai(itemId: string, lyDo?: string): { ok: boolean; reason?: string } {
    const it = this.item(itemId);
    if (!it) return { ok: false, reason: 'Không tìm thấy item.' };
    this.patchItem(itemId, { phanLoaiTrangThai: 'da-dong' });
    this.log({ hanhDong: 'Đóng dòng kết quả (đã xử lý xong)', doiTuong: itemId, sau: INS_PHANLOAI_TRANGTHAI_LABEL['da-dong'], lyDo: lyDo?.trim() || undefined });
    return { ok: true };
  }

  /* ═════════ KẾT QUẢ XỬ LÝ LÔ — chạy nền, đợt, chạy lại phần thất bại (idempotent) ═════════ */
  /** Đợt phân tích — CHẶN CHỌN LÙI (nguyên văn PBI). */
  phanTichDot(dot: number): { ok: boolean; reason?: string } {
    const hienTai = this.dotHienTai();
    if (dot <= hienTai) return { ok: false, reason: `Đã phân tích đến [${hienTai}]. Vui lòng phân tích đợt lớn hơn!` };
    this.dotHienTai.set(dot);
    this.lanChay.update((l) => [...l, {
      ma: `LC-2026-08-${String(++lanChaySeq).padStart(2, '0')}`, ky: this.kyId(), thoiDiem: demoNow(),
      nguoi: this.currentUser, dot, tienDo: '45%', thanhCong: 0, thatBai: 0, lyDo: [], trangThai: 'dang-chay', duongVao: 'a',
    }]);
    this.log({ hanhDong: `Sinh biến động nền — đợt ${dot}`, doiTuong: this.kyId() });
    return { ok: true };
  }
  /** Chạy lại CHỈ phần thất bại — idempotent, không sinh trùng. */
  chayLaiPhanThatBai(lanChayId: string): { ok: boolean; reason?: string; done: number } {
    const lc = this.lanChay().find((r) => r.ma === lanChayId);
    if (!lc) return { ok: false, reason: 'Không tìm thấy lần chạy.', done: 0 };
    const targets = this.dongLoi().filter((d) => d.lanChayId === lanChayId && d.trangThai === 'cho-xu-ly');
    if (!targets.length) return { ok: false, reason: 'Không còn dòng thất bại chờ xử lý — chạy lại idempotent, không sinh trùng.', done: 0 };
    const ma = `LC-2026-08-${String(++lanChaySeq).padStart(2, '0')}`;
    this.lanChay.update((l) => [...l, {
      ma, ky: lc.ky, thoiDiem: demoNow(), nguoi: this.currentUser, dot: lc.dot, tienDo: '100%',
      thanhCong: targets.length, thatBai: 0, lyDo: [], trangThai: 'hoan-tat', duongVao: lc.duongVao,
    }]);
    for (const d of targets) {
      this.dongLoi.update((l) => l.map((x) => (x.id === d.id ? { ...x, trangThai: 'da-sua-chay-lai' as const, hanhDongKetThuc: 'Đưa vào lần chạy lại', lanChayLaiId: ma } : x)));
    }
    this.log({ hanhDong: `Chạy lại phần thất bại (${targets.length} dòng) → ${ma}`, doiTuong: lanChayId });
    return { ok: true, done: targets.length };
  }
  /** 3 đường ra dòng lỗi: sửa tại chỗ · trả về 02 · loại trừ có lý do. */
  dongLoiSuaTaiCho(id: string): { ok: boolean; reason?: string } {
    const d = this.dongLoi().find((x) => x.id === id);
    if (!d) return { ok: false, reason: 'Không tìm thấy dòng lỗi.' };
    if (d.trangThai !== 'cho-xu-ly') return { ok: false, reason: `Dòng đã ${INS_DONGLOI_LABEL[d.trangThai].toLowerCase()}.` };
    this.dongLoi.update((l) => l.map((x) => (x.id === id ? { ...x, trangThai: 'da-sua-chay-lai' as const, hanhDongKetThuc: 'Sửa tại chỗ' } : x)));
    this.log({ hanhDong: 'Sửa tại chỗ dòng lỗi', doiTuong: id });
    return { ok: true };
  }
  dongLoiTraVe02(id: string): { ok: boolean; reason?: string } {
    const d = this.dongLoi().find((x) => x.id === id);
    if (!d) return { ok: false, reason: 'Không tìm thấy dòng lỗi.' };
    if (d.trangThai !== 'cho-xu-ly') return { ok: false, reason: `Dòng đã ${INS_DONGLOI_LABEL[d.trangThai].toLowerCase()}.` };
    this.dongLoi.update((l) => l.map((x) => (x.id === id ? { ...x, trangThai: 'da-tra-ve-02' as const, hanhDongKetThuc: 'Trả về phân hệ 02 — Tab Dữ liệu ngoại lệ' } : x)));
    this.log({ hanhDong: 'Trả dòng lỗi về phân hệ 02 (2 chiều)', doiTuong: id });
    return { ok: true };
  }
  dongLoiLoaiTru(id: string, lyDo: string): { ok: boolean; reason?: string } {
    const d = this.dongLoi().find((x) => x.id === id);
    if (!d) return { ok: false, reason: 'Không tìm thấy dòng lỗi.' };
    if (!lyDo.trim()) return { ok: false, reason: 'Loại trừ BẮT BUỘC có lý do.' };
    if (d.trangThai !== 'cho-xu-ly') return { ok: false, reason: `Dòng đã ${INS_DONGLOI_LABEL[d.trangThai].toLowerCase()}.` };
    this.dongLoi.update((l) => l.map((x) => (x.id === id ? { ...x, trangThai: 'da-loai-tru' as const, hanhDongKetThuc: 'Loại trừ có lý do', lyDoLoaiTru: lyDo.trim() } : x)));
    this.log({ hanhDong: 'Loại trừ dòng lỗi có lý do', doiTuong: id, lyDo: lyDo.trim() });
    return { ok: true };
  }
}
