import { ChangeDetectionStrategy, Component, computed, inject } from '@angular/core';
import { HrmDescriptions, HrmTag } from 'hrm-ui';
import { InsSectionLabel } from '../_shared';
import { InsM08Store } from '../_data/_m08-data';

/** M08 — 2 TRANG GỌN (mục ít quan trọng trong 13 mục Cấu hình — descriptions + bảng đơn giản).
 *  FN-02 Cơ cấu tổ chức: cây 3 cấp pháp nhân → đơn vị → mã BHXH; 1 mã thuộc đúng 1 đơn vị tại 1
 *  thời điểm; đổi mã = bản ghi mới có ngày HL; không xóa đơn vị có kỳ — Ngưng sử dụng; địa bàn
 *  BẮT BUỘC (rule LTT vùng). FN-16 Đơn vị SDLĐ: bản ghi GỐC; Thiết lập giữ bản gốc — lập/ký/nộp
 *  TK3-TS thuộc M06 (đổi thông tin → NHẮC, không tự sinh/nộp); không ngưng khi còn kỳ chưa quyết toán. */
@Component({
  selector: 'ins-m08-cocau-page',
  imports: [HrmTag, InsSectionLabel],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <ins-section-label text="Cây 3 cấp: pháp nhân → đơn vị → mã BHXH" tone="muted" [count]="store.coCau().length" />
    @for (n of nodes(); track n.id) {
      <div class="o-node" [style.margin-left.px]="n.indent">
        <hrm-tag size="sm" [color]="n.cap === 'phap-nhan' ? 'purple' : n.cap === 'don-vi' ? 'blue' : 'teal'" variant="stroke">{{ n.capLabel }}</hrm-tag>
        <span class="o-strong">{{ n.ten }}</span>
        @if (n.diaBan) { <span class="o-muted">địa bàn: <b>{{ n.diaBan }}</b> (bắt buộc — rule LTT vùng)</span> }
        <span class="o-muted">ngày HL {{ n.ngayHL }}</span>
        @if (n.ghiChu) { <span class="o-note">{{ n.ghiChu }}</span> }
      </div>
    }
    <p class="o-note">Không xóa đơn vị đã có kỳ — chỉ "Ngưng sử dụng" · nơi làm việc + calendar gắn theo đơn vị (rút gọn demo).</p>
  `,
  host: { class: 'ins-m08-cocau-page' },
  styles: [`
    :host { display: flex; flex-direction: column; gap: 7px; }
    .o-node { display: flex; align-items: center; gap: 9px; flex-wrap: wrap; border: 1px solid var(--border-sub); border-radius: var(--radius-md); background: var(--bg-surface); padding: 6px 10px; }
    .o-strong { color: var(--text-strong); font-weight: 500; font-size: var(--fs-13); }
    .o-muted { font-size: var(--fs-12); color: var(--text-sub); }
    .o-muted b { color: var(--text-strong); }
    .o-note { margin: 0; font-size: var(--fs-11); color: var(--text-soft); }
  `],
})
export class InsM08CoCauPage {
  protected readonly store = inject(InsM08Store);
  private readonly CAP_LABEL = { 'phap-nhan': 'Pháp nhân', 'don-vi': 'Đơn vị', 'ma-bhxh': 'Mã BHXH' } as const;
  protected readonly nodes = computed(() => this.store.coCau().map((n) => ({
    ...n,
    capLabel: this.CAP_LABEL[n.cap],
    indent: n.cap === 'phap-nhan' ? 0 : n.cap === 'don-vi' ? 24 : 48,
  })));
}

@Component({
  selector: 'ins-m08-donvisdld-page',
  imports: [HrmDescriptions, InsSectionLabel],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <ins-section-label text="Bản ghi gốc đơn vị sử dụng lao động (FN-16)" tone="muted" [count]="store.donViSDLD().length" />
    <p class="v-note">Nhiều đơn vị — nhiều mã; MỌI bản ghi nghiệp vụ phải gắn đúng 1 mã đơn vị BHXH. Thiết lập giữ BẢN GỐC;
      lập/ký/nộp TK3-TS thuộc M06 — đổi thông tin tại đây chỉ NHẮC, không tự sinh/nộp hồ sơ. Đổi = bản mới có ngày HL;
      không ngưng khi còn kỳ chưa quyết toán.</p>
    @for (d of store.donViSDLD(); track d.id) {
      <div class="v-card">
        <hrm-descriptions [items]="itemsOf(d.id)" [column]="2" size="small" [bordered]="true" [title]="d.ten" />
        @if (d.ghiChu) { <p class="v-note">{{ d.ghiChu }}</p> }
      </div>
    }
  `,
  host: { class: 'ins-m08-donvisdld-page' },
  styles: [`
    :host { display: flex; flex-direction: column; gap: 10px; }
    .v-note { margin: 0; font-size: var(--fs-12); color: var(--text-sub); }
    .v-card { display: flex; flex-direction: column; gap: 5px; }
  `],
})
export class InsM08DonViSDLDPage {
  protected readonly store = inject(InsM08Store);
  protected itemsOf(id: string): { label: string; value: string }[] {
    const d = this.store.donViSDLD().find((x) => x.id === id);
    return d ? [
      { label: 'MST', value: d.mst },
      { label: 'Mã đơn vị BHXH', value: d.maDonViBHXH },
      { label: 'Cơ quan quản lý', value: d.coQuanQuanLy },
      { label: 'Phương thức đóng', value: d.phuongThucDong },
      { label: 'Địa chỉ', value: d.diaChi },
      { label: 'Người đại diện', value: d.daiDien },
      { label: 'Người phụ trách', value: d.phuTrach },
      { label: 'Ngày hiệu lực bản ghi', value: d.ngayHL },
    ] : [];
  }
}
