import { ChangeDetectionStrategy, Component, TemplateRef, computed, inject, signal, viewChild } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { IconLock, IconLockOpen, TablerIconComponent } from '@tabler/icons-angular';
import {
  HrmAlert, HrmButton, HrmMessageService, HrmModalService, HrmSelect, HrmStatusCell, HrmSteps,
  HrmTextarea,
} from 'hrm-ui';
import { InsShellStore, INS_KY, insKy } from '../_data/_core';
import {
  InsM04Store, M04_KY_LABEL, M04_KY_TONE, M04_NGUOI_DUYET,
} from '../_data/_m04-data';
import { M04TabKey, M04_TABS, M04_TAB_LABEL } from './_m04-columns';
import { InsM04TabSnapshot } from './m04-tab-snapshot';
import { InsM04TabChenhLech } from './m04-tab-chenhlech';
import { InsM04TabCompare, InsM04TabRecon } from './m04-tabs-aux';

/** ═════════ M04 — THEO DÕI ĐÓNG BHXH (màn thật, Phase D2 — archetype Variance & Closing Workspace) ═════════
 *  Nguồn: `_rebuild/01-requirements/m04.md` + ux-architecture (M04). IA_LOCK: lưới kỳ (chọn 1 kỳ)
 *  → vùng chi tiết 4 tab `T1 Snapshot · T2 Đối soát C12-D09 · T3 Chênh lệch · T4 So sánh kỳ`;
 *  KHÔNG nút Xóa cấp kỳ; mặc định T1 phiên bản snapshot mới nhất.
 *  Master 3 kỳ: trạng thái (6 tone) + phiên bản kỳ + số lần mở lại + nút Khóa/Mở lại kỳ
 *  DISABLED-CÓ-LÝ-DO (nêu điều kiện thiếu + link nhảy Tab Chênh lệch) — chọn kỳ đổi toàn workspace.
 *  Vòng khóa render như PBI: modal xác nhận có hrm-steps `Đang đối soát → Chờ duyệt khóa → Đã khóa`
 *  + checklist ✓/✗ (snapshot đã dựng · chênh ≤ ngưỡng M08 · mọi item có kết luận · maker ≠ checker).
 *  Mở lại = modal lý do + cảnh báo "sinh PHIÊN BẢN KỲ MỚI, không mở lại dây chuyền, AI không được
 *  thực hiện" (chỉ người dùng thao tác — store không có auto-reopen). Kỳ Đã khóa → banner chỉ đọc. */
@Component({
  selector: 'ins-m04-page',
  imports: [
    FormsModule, TablerIconComponent,
    HrmAlert, HrmButton, HrmSelect, HrmStatusCell, HrmSteps, HrmTextarea,
    InsM04TabSnapshot, InsM04TabRecon, InsM04TabChenhLech, InsM04TabCompare,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <header class="m04-head">
      <div class="m04-head__row">
        <h2 class="m04-head__title">Theo dõi đóng BHXH</h2>
        <span class="m04-head__sub">Lưới kỳ → chọn 1 kỳ → workspace 4 tab · KHÔNG có thao tác Xóa kỳ</span>
      </div>

      <!-- ── master lưới kỳ (gọn — 3 thẻ) ── -->
      <div class="m04-master">
        @for (k of kyCards(); track k.id) {
          <button type="button" class="m04-ky" [class.m04-ky--active]="k.id === selKy()" (click)="chonKy(k.id)">
            <span class="m04-ky__row">
              <b class="m04-ky__label">{{ k.label }}</b>
              <hrm-status-cell [status]="$any(k.tone)" [label]="k.trangThaiLabel" variant="badge" />
            </span>
            <span class="m04-ky__meta">Phiên bản kỳ v{{ k.phienBanKy }} · mở lại {{ k.soLanMoLai }} lần · snapshot {{ k.snapLabel }}</span>
            <span class="m04-ky__meta">Hạn chốt nội bộ {{ k.cutoff }}</span>
            <!-- timeline vòng đời kỳ (BQA-15) — mốc lịch sử Đang xử lý / Chờ kết quả nhìn thấy được -->
            <span class="m04-ky__life" [title]="'Lịch sử trạng thái kỳ (append-only)'">{{ k.vongDoi }}</span>

            <span class="m04-ky__acts">
              @switch (k.trangThai) {
                @case ('dang-doi-soat') {
                  <hrm-button size="sm" variant="primary" [disabled]="!k.khoaOk" (click)="openKhoa(k.id); $event.stopPropagation()">
                    <tabler-icon [icon]="icLock" [size]="14" /> Khóa kỳ
                  </hrm-button>
                }
                @case ('cho-duyet-khoa') {
                  <hrm-button size="sm" variant="primary" (click)="openDuyetKhoa(k.id); $event.stopPropagation()">Duyệt khóa</hrm-button>
                  <hrm-button size="sm" (click)="openTuChoi('khoa', k.id); $event.stopPropagation()">Từ chối</hrm-button>
                }
                @case ('da-khoa') {
                  <hrm-button size="sm" (click)="openMoLai(k.id); $event.stopPropagation()">
                    <tabler-icon [icon]="icUnlock" [size]="14" /> Mở lại kỳ
                  </hrm-button>
                }
                @case ('cho-duyet-mo-lai') {
                  <hrm-button size="sm" variant="primary" (click)="openDuyetMoLai(k.id); $event.stopPropagation()">Duyệt mở lại</hrm-button>
                  <hrm-button size="sm" (click)="openTuChoi('mo-lai', k.id); $event.stopPropagation()">Từ chối</hrm-button>
                }
                @case ('mo-lai') {
                  <!-- BQA-15: kỳ đứng ở "Mở lại" — người dùng bấm mới chuyển Đang đối soát -->
                  <hrm-button size="sm" variant="primary" (click)="tiepTucDoiSoat(k.id); $event.stopPropagation()">Tiếp tục đối soát</hrm-button>
                }
                @default {
                  <hrm-button size="sm" [disabled]="true">
                    <tabler-icon [icon]="icLock" [size]="14" /> Khóa kỳ
                  </hrm-button>
                }
              }
            </span>
            <!-- disabled-CÓ-LÝ-DO: nêu điều kiện thiếu + link nhảy Tab 3 -->
            @if (k.khoaReason) {
              <span class="m04-ky__reason">
                {{ k.khoaReason }}
                @if (k.reasonLinkTab3) {
                  <a class="m04-ky__link" (click)="jumpTab3(k.id); $event.stopPropagation()">Xem Tab Chênh lệch →</a>
                }
              </span>
            }
          </button>
        }
      </div>
    </header>

    @if (kyLockedBanner()) {
      <hrm-alert class="m04-lockbanner" type="info" [showIcon]="true"
        message="Kỳ đã khóa — snapshot Đã đóng băng, phần thuộc kỳ chuyển CHỈ ĐỌC (xem được, không sửa)." />
    }

    <!-- ── tab strip (pattern D1 — tự dựng, không cần severity) ── -->
    <nav class="m04-tabs" role="tablist">
      @for (t of tabs; track t) {
        <button type="button" class="m04-tab" role="tab" [class.m04-tab--active]="t === tab()"
          [attr.aria-selected]="t === tab()" (click)="tab.set(t)">{{ tabLabel[t] }}</button>
      }
      <span class="m04-tabs__ky">{{ selKyLabel() }}</span>
    </nav>

    <div class="m04-body">
      @switch (tab()) {
        @case ('t1') { <ins-m04-tab-snapshot [kyId]="selKy()" /> }
        @case ('t2') { <ins-m04-tab-recon [kyId]="selKy()" /> }
        @case ('t3') { <ins-m04-tab-chenhlech [kyId]="selKy()" /> }
        @case ('t4') { <ins-m04-tab-compare [kyId]="selKy()" /> }
      }
    </div>

    <!-- ═════ modal KHÓA KỲ — steps + checklist điều kiện ✓/✗ ═════ -->
    <ng-template #khoaTpl>
      <div class="m04-form">
        <hrm-steps [items]="khoaSteps" [current]="0" size="small" />
        <p class="m04-form__hint">Điều kiện khóa (BUSINESS_LOCK — đủ ✓ mới gửi duyệt được; khóa xong snapshot ĐÓNG BĂNG + số dư cuối chuyển kỳ sau):</p>
        <div class="m04-check">
          @for (c of khoaChecklist(); track c.label) {
            <div class="m04-check__row" [class.m04-check__row--fail]="!c.ok">
              <span class="m04-check__ico">{{ c.ok ? '✓' : '✗' }}</span>
              <span class="m04-check__lb">{{ c.label }}</span>
              <span class="m04-check__dt">{{ c.detail }}</span>
              @if (!c.ok && c.linkTab3) { <a class="m04-ky__link" (click)="jumpTab3(dlgKy())">Tab Chênh lệch →</a> }
            </div>
          }
        </div>
      </div>
    </ng-template>

    <!-- ═════ modal DUYỆT KHÓA / DUYỆT MỞ LẠI (maker ≠ checker) ═════ -->
    <ng-template #duyetTpl>
      <div class="m04-form">
        <hrm-steps [items]="duyetKind() === 'khoa' ? khoaSteps : moLaiSteps" [current]="1" size="small" />
        <p class="m04-form__hint">Chọn người duyệt — GUARD maker ≠ checker (người lập {{ dlgNguoiLap() }} không được tự duyệt; chọn chính người lập để thấy guard chặn).</p>
        <hrm-select [(ngModel)]="duyetNguoiModel" [options]="nguoiDuyetOptions" [allowClear]="false" [showSearch]="false" />
        @if (dlgErr()) { <span class="m04-form__err">{{ dlgErr() }}</span> }
      </div>
    </ng-template>

    <!-- ═════ modal MỞ LẠI KỲ — lý do + cảnh báo PBI ═════ -->
    <ng-template #moLaiTpl>
      <div class="m04-form">
        <hrm-steps [items]="moLaiSteps" [current]="0" size="small" />
        <hrm-alert type="warning" [showIcon]="true" message="Mở lại sinh PHIÊN BẢN KỲ MỚI"
          description="Snapshot cũ giữ NGUYÊN VẸN (tra được); KHÔNG mở lại dây chuyền các kỳ sau; quyền đặc biệt + duyệt 2 bước; AI không được thực hiện thao tác này — chỉ người dùng bấm." />
        <hrm-textarea [(ngModel)]="reasonModel" placeholder="Lý do + tài liệu đính kèm (bắt buộc)…" [minRows]="3" [status]="dlgErr() ? 'error' : ''" />
        @if (dlgErr()) { <span class="m04-form__err">{{ dlgErr() }}</span> }
      </div>
    </ng-template>

    <!-- ═════ modal TỪ CHỐI (khóa / mở lại) ═════ -->
    <ng-template #tuChoiTpl>
      <div class="m04-form">
        <p class="m04-form__hint">{{ tuChoiKind() === 'khoa' ? 'Từ chối khóa — kỳ về Đang đối soát, kèm lý do.' : 'Từ chối mở lại — kỳ giữ Đã khóa, kèm lý do.' }}</p>
        <hrm-textarea [(ngModel)]="reasonModel" placeholder="Lý do từ chối (bắt buộc)…" [minRows]="3" [status]="dlgErr() ? 'error' : ''" />
        @if (dlgErr()) { <span class="m04-form__err">{{ dlgErr() }}</span> }
      </div>
    </ng-template>
  `,
  host: { class: 'ins-m04-page' },
  styles: [`
    :host { display: flex; flex-direction: column; flex: 1 1 auto; min-height: 0; padding: 0 20px; }

    .m04-head { flex: none; }
    .m04-head__row { display: flex; align-items: baseline; gap: 10px; padding: 10px 0 8px; }
    .m04-head__title { margin: 0; font-size: var(--fs-14); font-weight: 600; color: var(--text-strong); }
    .m04-head__sub { font-size: var(--fs-12); color: var(--text-sub); }

    .m04-master { display: grid; grid-template-columns: repeat(3, minmax(240px, 1fr)); gap: 10px; }
    .m04-ky {
      display: flex; flex-direction: column; gap: 4px; text-align: left; cursor: pointer; font: inherit;
      border: 1px solid var(--border-sub); border-radius: var(--radius-lg); background: var(--bg-surface);
      padding: 10px 14px;
    }
    .m04-ky:hover { border-color: var(--primary-base); }
    .m04-ky--active { border-color: var(--primary-base); box-shadow: 0 0 0 1px var(--primary-base); }
    .m04-ky__row { display: flex; align-items: center; gap: 8px; }
    .m04-ky__label { color: var(--text-strong); font-size: var(--fs-13); }
    .m04-ky__meta { font-size: var(--fs-11); color: var(--text-soft); }
    .m04-ky__life { font-size: var(--fs-11); color: var(--text-sub); }
    .m04-ky__acts { display: flex; gap: 8px; margin-top: 4px; }
    .m04-ky__reason { font-size: var(--fs-11); color: var(--warning-text); }
    .m04-ky__link { color: var(--primary-base); font-weight: 600; cursor: pointer; }

    .m04-lockbanner { display: block; margin-top: 8px; }

    .m04-tabs { display: flex; gap: 2px; border-bottom: 1px solid var(--border-sub); margin-top: 10px; align-items: baseline; }
    .m04-tab {
      position: relative; border: 0; background: none; cursor: pointer; padding: 6px 10px 8px;
      font: inherit; font-size: var(--fs-13); color: var(--text-sub);
    }
    .m04-tab:hover { color: var(--text-strong); }
    .m04-tab--active { color: var(--primary-base); font-weight: 600; }
    .m04-tab--active::after {
      content: ''; position: absolute; left: 8px; right: 8px; bottom: -1px; height: 2px;
      background: var(--primary-base); border-radius: var(--radius-full);
    }
    .m04-tabs__ky { margin-left: auto; font-size: var(--fs-12); color: var(--text-sub); }

    .m04-body { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; }

    .m04-form { display: flex; flex-direction: column; gap: 12px; }
    .m04-form__hint { margin: 0; font-size: var(--fs-12); color: var(--text-sub); }
    .m04-form__err { font-size: var(--fs-12); color: var(--error-text); }
    .m04-check { display: flex; flex-direction: column; gap: 6px; }
    .m04-check__row { display: flex; align-items: baseline; gap: 8px; font-size: var(--fs-12); }
    .m04-check__ico { flex: none; width: 18px; text-align: center; font-weight: 700; color: var(--success-base); }
    .m04-check__row--fail .m04-check__ico { color: var(--error-base); }
    .m04-check__lb { color: var(--text-strong); font-weight: 500; }
    .m04-check__dt { color: var(--text-sub); }
    .m04-check__row--fail .m04-check__dt { color: var(--error-text); }
  `],
})
export class InsM04Page {
  protected readonly store = inject(InsM04Store);
  protected readonly shell = inject(InsShellStore);
  private readonly msg = inject(HrmMessageService);
  private readonly modal = inject(HrmModalService);

  protected readonly icLock = IconLock;
  protected readonly icUnlock = IconLockOpen;
  protected readonly tabs = M04_TABS;
  protected readonly tabLabel = M04_TAB_LABEL;
  protected readonly nguoiDuyetOptions = M04_NGUOI_DUYET.map((n) => ({ value: n, label: n }));
  protected readonly khoaSteps = [
    { title: 'Đang đối soát' }, { title: 'Chờ duyệt khóa' }, { title: 'Đã khóa', description: 'Snapshot đóng băng · số dư chuyển kỳ sau' },
  ];
  protected readonly moLaiSteps = [
    { title: 'Đã khóa' }, { title: 'Chờ duyệt mở lại' }, { title: 'Mở lại', description: 'Phiên bản kỳ mới · bấm "Tiếp tục đối soát" để về Đang đối soát' },
  ];

  /* ── chọn kỳ + tab (UX-8) — parser navCtx multi-key `k:v|k:v` (CÙNG format M02):
   *  hiểu `tab:<t1..t4>` + `ky:<id>` (tách theo `|` rồi từng cặp `key:value`); filter có `ky:` thì
   *  ưu tiên, không có thì tôn trọng ctx.ky của drill; mở trực tiếp → mặc định k07 (kỳ Đang đối
   *  soát — trung tâm workspace). Áp dụng xong CLEAR filter: `navCtx` là signal PUBLIC của
   *  InsShellStore nên set `filter: undefined` trực tiếp — KHÔNG cần sửa _core (không có
   *  clearNavFilter, và go() merge giữ filter cũ nên phải tự xóa để không rò sang parser khác). ── */
  protected readonly selKy = signal('k07');
  protected readonly tab = signal<M04TabKey>('t1');

  constructor() {
    const ctx = this.shell.navCtx();
    let ky = ctx.filter && insKy(ctx.ky ?? '') ? (ctx.ky as string) : 'k07';
    let tab: M04TabKey = 't1';
    if (ctx.filter) {
      for (const part of ctx.filter.split('|')) {
        const i = part.indexOf(':');
        if (i < 0) continue;
        const k = part.slice(0, i).trim();
        const v = part.slice(i + 1).trim();
        if (k === 'tab' && (M04_TABS as readonly string[]).includes(v)) tab = v as M04TabKey;
        else if (k === 'ky' && insKy(v)) ky = v;
      }
      // CLEAR filter sau khi dùng — mọi parser nên clear (UX-8).
      this.shell.navCtx.update((c) => ({ ...c, filter: undefined }));
    }
    this.selKy.set(ky);
    this.tab.set(tab);
  }
  protected chonKy(id: string): void {
    this.selKy.set(id);
    this.shell.navCtx.update((c) => ({ ...c, ky: id }));
  }
  protected readonly selKyLabel = computed(() => insKy(this.selKy())?.label ?? '');
  protected readonly kyLockedBanner = computed(() => this.store.isKyKhoa(this.selKy()));
  protected jumpTab3(kyId: string): void {
    this.selKy.set(kyId);
    this.tab.set('t3');
  }

  /* ── master cards ── */
  protected readonly kyCards = computed(() => INS_KY.map((k) => {
    const meta = this.store.meta(k.id);
    const trangThai = meta?.trangThai ?? 'mo';
    const snap = this.store.latestSnapshot(k.id);
    let khoaOk = false;
    let khoaReason = '';
    let reasonLinkTab3 = false;
    if (trangThai === 'dang-doi-soat') {
      const fails = this.store.khoaChecklist(k.id).filter((c) => !c.ok);
      khoaOk = fails.length === 0;
      khoaReason = fails.map((c) => c.detail ?? c.label).join(' · ');
      reasonLinkTab3 = fails.some((c) => c.linkTab3);
    } else if (trangThai === 'mo' || trangThai === 'dang-xu-ly' || trangThai === 'cho-ket-qua') {
      khoaReason = 'Kỳ chưa vào bước đối soát — chưa khóa được.';
    } else if (trangThai === 'mo-lai') {
      khoaReason = 'Kỳ vừa mở lại (phiên bản kỳ mới) — bấm "Tiếp tục đối soát" để vào bước đối soát.';
    }
    // Timeline vòng đời (BQA-15): "Mở 01/07 → Đang xử lý 25/07 → Chờ kết quả 01/08 → …"
    const vongDoi = (meta?.lichSuTrangThai ?? [])
      .map((h) => `${M04_KY_LABEL[h.trangThai]} ${h.at}`).join(' → ');
    return {
      id: k.id, label: k.label, trangThai,
      trangThaiLabel: M04_KY_LABEL[trangThai], tone: M04_KY_TONE[trangThai],
      phienBanKy: meta?.phienBanKy ?? 1, soLanMoLai: meta?.soLanMoLai ?? 0,
      snapLabel: snap ? `v${snap.phienBan}` : 'chưa dựng',
      cutoff: k.cutoffInternal, deadline: k.legalDeadline,
      vongDoi, khoaOk, khoaReason, reasonLinkTab3,
    };
  }));

  /** BQA-15 — kỳ `Mở lại` → `Đang đối soát` (hành động NGƯỜI DÙNG bấm). */
  protected tiepTucDoiSoat(kyId: string): void {
    const r = this.store.tiepTucDoiSoat(kyId);
    if (r.ok) this.msg.success('Kỳ chuyển Đang đối soát — tiếp tục vòng đối soát trên phiên bản kỳ mới.');
    else this.msg.error(r.reason ?? 'Không chuyển được.');
  }

  /* ── modal state chung ── */
  private dlg: { close: () => void } | null = null;
  protected readonly dlgKy = signal('k07');
  protected readonly dlgErr = signal('');
  private readonly reasonText = signal('');
  protected get reasonModel(): string { return this.reasonText(); }
  protected set reasonModel(v: string) { this.reasonText.set(v ?? ''); if (v?.trim()) this.dlgErr.set(''); }
  private readonly duyetNguoi = signal(M04_NGUOI_DUYET[0]);
  protected get duyetNguoiModel(): unknown { return this.duyetNguoi(); }
  protected set duyetNguoiModel(v: unknown) { this.duyetNguoi.set(String(v ?? M04_NGUOI_DUYET[0])); this.dlgErr.set(''); }

  private readonly khoaTplRef = viewChild<TemplateRef<unknown>>('khoaTpl');
  private readonly duyetTplRef = viewChild<TemplateRef<unknown>>('duyetTpl');
  private readonly moLaiTplRef = viewChild<TemplateRef<unknown>>('moLaiTpl');
  private readonly tuChoiTplRef = viewChild<TemplateRef<unknown>>('tuChoiTpl');

  protected readonly khoaChecklist = computed(() => this.store.khoaChecklist(this.dlgKy()));

  /* ── khóa kỳ ── */
  protected openKhoa(kyId: string): void {
    this.dlgKy.set(kyId); this.dlgErr.set('');
    this.dlg = this.modal.open({
      title: `Khóa kỳ — ${insKy(kyId)?.label}`, content: this.khoaTplRef()!, width: 560,
      footer: [
        { label: 'Hủy', onClick: () => this.dlg?.close() },
        { label: 'Gửi duyệt khóa (maker–checker)', type: 'primary', onClick: () => this.confirmKhoa() },
      ],
    });
  }
  private confirmKhoa(): void {
    const r = this.store.khoaKy(this.dlgKy());
    if (r.ok) { this.msg.success('Đã gửi duyệt khóa — kỳ chuyển Chờ duyệt khóa.'); this.dlg?.close(); }
    else this.msg.error(r.reason ?? 'Chưa đủ điều kiện khóa.');
  }

  /* ── duyệt khóa / duyệt mở lại ── */
  protected readonly duyetKind = signal<'khoa' | 'mo-lai'>('khoa');
  protected readonly dlgNguoiLap = computed(() => {
    const m = this.store.meta(this.dlgKy());
    return (this.duyetKind() === 'khoa' ? m?.nguoiLapKhoa : m?.nguoiLapMoLai) ?? '';
  });
  protected openDuyetKhoa(kyId: string): void { this.openDuyetModal('khoa', kyId, 'Duyệt khóa kỳ'); }
  protected openDuyetMoLai(kyId: string): void { this.openDuyetModal('mo-lai', kyId, 'Duyệt mở lại kỳ'); }
  private openDuyetModal(kind: 'khoa' | 'mo-lai', kyId: string, title: string): void {
    this.duyetKind.set(kind); this.dlgKy.set(kyId); this.dlgErr.set('');
    this.dlg = this.modal.open({
      title: `${title} — ${insKy(kyId)?.label}`, content: this.duyetTplRef()!, width: 520,
      footer: [
        { label: 'Hủy', onClick: () => this.dlg?.close() },
        { label: title, type: 'primary', onClick: () => this.confirmDuyet() },
      ],
    });
  }
  private confirmDuyet(): void {
    const kyId = this.dlgKy();
    const r = this.duyetKind() === 'khoa'
      ? this.store.duyetKhoa(kyId, this.duyetNguoi())
      : this.store.duyetMoLai(kyId, this.duyetNguoi());
    if (r.ok) {
      this.msg.success(this.duyetKind() === 'khoa'
        ? 'Đã khóa kỳ — snapshot đóng băng, số dư cuối chuyển sang kỳ sau.'
        : 'Đã duyệt mở lại — PHIÊN BẢN KỲ MỚI, kỳ ở trạng thái Mở lại; bấm "Tiếp tục đối soát" để vào bước đối soát (snapshot cũ tra được).');
      this.dlg?.close();
    } else this.dlgErr.set(r.reason ?? 'Không duyệt được.');
  }

  /* ── mở lại ── */
  protected openMoLai(kyId: string): void {
    this.dlgKy.set(kyId); this.reasonText.set(''); this.dlgErr.set('');
    this.dlg = this.modal.open({
      title: `Mở lại kỳ — ${insKy(kyId)?.label}`, content: this.moLaiTplRef()!, width: 560,
      footer: [
        { label: 'Hủy', onClick: () => this.dlg?.close() },
        { label: 'Gửi duyệt mở lại', type: 'primary', danger: true, onClick: () => this.confirmMoLai() },
      ],
    });
  }
  private confirmMoLai(): void {
    const lyDo = this.reasonText().trim();
    if (!lyDo) { this.dlgErr.set('Lý do + tài liệu là bắt buộc (quyền đặc biệt, duyệt 2 bước).'); return; }
    const r = this.store.moLaiKy(this.dlgKy(), lyDo);
    if (r.ok) { this.msg.success('Đã gửi duyệt mở lại — kỳ chuyển Chờ duyệt mở lại.'); this.dlg?.close(); }
    else this.msg.error(r.reason ?? 'Không mở lại được.');
  }

  /* ── từ chối (khóa / mở lại) ── */
  protected readonly tuChoiKind = signal<'khoa' | 'mo-lai'>('khoa');
  protected openTuChoi(kind: 'khoa' | 'mo-lai', kyId: string): void {
    this.tuChoiKind.set(kind); this.dlgKy.set(kyId); this.reasonText.set(''); this.dlgErr.set('');
    this.dlg = this.modal.open({
      title: kind === 'khoa' ? 'Từ chối khóa kỳ' : 'Từ chối mở lại kỳ',
      content: this.tuChoiTplRef()!, width: 460,
      footer: [
        { label: 'Hủy', onClick: () => this.dlg?.close() },
        { label: 'Từ chối', type: 'primary', danger: true, onClick: () => this.confirmTuChoi() },
      ],
    });
  }
  private confirmTuChoi(): void {
    const lyDo = this.reasonText().trim();
    if (!lyDo) { this.dlgErr.set('Lý do từ chối là bắt buộc.'); return; }
    const r = this.tuChoiKind() === 'khoa'
      ? this.store.tuChoiKhoa(this.dlgKy(), lyDo)
      : this.store.tuChoiMoLai(this.dlgKy(), lyDo);
    if (r.ok) { this.msg.success(this.tuChoiKind() === 'khoa' ? 'Đã từ chối — kỳ về Đang đối soát.' : 'Đã từ chối — kỳ giữ Đã khóa.'); this.dlg?.close(); }
    else this.msg.error(r.reason ?? 'Không từ chối được.');
  }
}
