import { ChangeDetectionStrategy, Component, computed, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { IconSearch } from '@tabler/icons-angular';
import { HrmInput, HrmPageHeader, HrmSelect, HrmTag } from 'hrm-ui';
import {
  InsM08MucCay, InsM08Store, M08_CAY, M08_PBI_RIENG_NOTE,
} from '../_data/_m08-data';
import { InsM08RulePage } from './m08-rule-page';
import { InsM08NguongPage } from './m08-nguong-page';
import { InsM08D02Page } from './m08-d02-page';
import { InsM08ThuTucPage } from './m08-thutuc-page';
import { InsM08DotPage } from './m08-dot-page';
import { InsM08NhacPage } from './m08-nhac-page';
import { InsM08DongBoPage } from './m08-dongbo-page';
import { InsM08TruyCapPage } from './m08-truycap-page';
import { InsM08LuuTruPage } from './m08-luutru-page';
import { InsM08DanhMucPage } from './m08-danhmuc-page';
import { InsM08CoCauPage, InsM08DonViSDLDPage } from './m08-gon-pages';

/** ═════════ M08 — THIẾT LẬP (archetype Version-aware Configuration Console, Phase D6) ═════════
 *  IA_LOCK m08.md: MỘT màn shell — cây trái 2 nhóm CỐ ĐỊNH `Cấu hình` (13) · `Danh mục` (9);
 *  nội dung đổi theo mục; không mục nào mở màn ngoài shell. Tìm nhanh trong cây (tên + từ khóa
 *  tham số). Cây lọc theo quyền: không quyền đọc = ẨN HẲN (demo: mục "Tích hợp"); không quyền
 *  ghi = chỉ báo "chỉ đọc" (demo: Nhật ký đồng bộ — FN-19 chuyên viên 02). Mục thuộc 7 trang PBI
 *  riêng → hiện MỜ + "chưa mở trong bản này" (A-05). Thanh ngữ cảnh pháp nhân/đơn vị — đổi →
 *  NẠP LẠI mục đang mở (không giữ dữ liệu đơn vị trước; thực thi bằng @for track reloadTick).
 *  ⚠️ URL đổi theo mục (deep-link sau reload) = yêu cầu đích; mini-app demo điều hướng bằng
 *  SIGNAL nội bộ (không route thật — pattern legacy insurance-page), section con giữ trong
 *  `section` signal; khi có router thật ánh xạ signal → URL con `/m08/<key>`. */
@Component({
  selector: 'ins-m08-page',
  imports: [
    FormsModule, HrmInput, HrmPageHeader, HrmSelect, HrmTag,
    InsM08RulePage, InsM08NguongPage, InsM08D02Page, InsM08ThuTucPage, InsM08DotPage,
    InsM08NhacPage, InsM08DongBoPage, InsM08TruyCapPage, InsM08LuuTruPage, InsM08DanhMucPage,
    InsM08CoCauPage, InsM08DonViSDLDPage,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <!-- Page-header (title + subtitle) — trên console cấu hình 2 cột -->
    <hrm-page-header [title]="'Thiết lập'"
      [subtitle]="'Danh mục & cấu hình BHXH · phiên bản theo ngày hiệu lực'" />

    <div class="m8">
      <!-- ═══ Cây trái 2 nhóm (13 + 9) ═══ -->
      <aside class="m8-tree">
        <hrm-input [(ngModel)]="kwModel" size="sm" [prefixIcon]="icSearch" [clearable]="true"
          placeholder="Tìm mục + từ khóa tham số…" />
        @for (g of nhoms; track g.key) {
          <div class="m8-group">
            <div class="m8-group__head">{{ g.label }} <span class="m8-group__count">{{ countOf(g.key) }}</span></div>
            @for (it of itemsOf(g.key); track it.key) {
              <button type="button" class="m8-item"
                [class.m8-item--on]="it.key === section()"
                [class.m8-item--mo]="it.kieu === 'mo'"
                [disabled]="it.kieu === 'mo'"
                (click)="chon(it)">
                <span class="m8-item__ten">{{ it.ten }}</span>
                @if (it.chiDoc) { <hrm-tag size="sm" color="gray">chỉ đọc</hrm-tag> }
                @if (it.kieu === 'mo') { <span class="m8-item__why">chưa mở trong bản này</span> }
              </button>
            }
          </div>
        }
        <p class="m8-tree__note">1 mục ẩn theo quyền đọc (demo: Tích hợp) — không quyền = ẨN HẲN, không phải mờ.</p>
        <p class="m8-tree__note">{{ pbiNote }}</p>
      </aside>

      <!-- ═══ Nội dung mục ═══ -->
      <section class="m8-work">
        <!-- Thanh ngữ cảnh pháp nhân/đơn vị — đổi → NẠP LẠI mục (destroy/recreate qua track). -->
        <div class="m8-ctx">
          <span class="m8-ctx__label">Phạm vi cấu hình</span>
          <hrm-select class="m8-ctx__sel" [(ngModel)]="phamViModel" [options]="phamViOptions" size="sm"
            [allowClear]="false" [showSearch]="false" />
          <span class="m8-ctx__note">Đổi pháp nhân/đơn vị → nạp lại mục đang mở, không giữ dữ liệu đơn vị trước.</span>
          <span class="m8-gap"></span>
          <span class="m8-ctx__sec">{{ tenMuc() }}</span>
        </div>

        @for (tick of [reloadTick()]; track tick) {
          <div class="m8-body">
            @switch (section()) {
              @case ('rule') { <ins-m08-rule-page [phamVi]="phamVi()" /> }
              @case ('nguong') { <ins-m08-nguong-page [phamVi]="phamVi()" /> }
              @case ('ma-d02') { <ins-m08-d02-page /> }
              @case ('thu-tuc') { <ins-m08-thutuc-page /> }
              @case ('dot') { <ins-m08-dot-page /> }
              @case ('nhac') { <ins-m08-nhac-page /> }
              @case ('dong-bo') { <ins-m08-dongbo-page /> }
              @case ('truy-cap') { <ins-m08-truycap-page /> }
              @case ('luu-tru') { <ins-m08-luutru-page /> }
              @case ('co-cau') { <ins-m08-cocau-page /> }
              @case ('don-vi-sdld') { <ins-m08-donvisdld-page /> }
              @default {
                @if (dmKey(); as key) { <ins-m08-danhmuc-page [dmKey]="key" /> }
              }
            }
          </div>
        }
      </section>
    </div>
  `,
  host: { class: 'ins-m08-page' },
  styles: [`
    :host { display: flex; flex-direction: column; flex: 1 1 auto; min-height: 0; }
    .m8 { flex: 1 1 auto; min-height: 0; display: flex; gap: 0; }

    .m8-tree {
      flex: none; width: 265px; overflow: auto; display: flex; flex-direction: column; gap: 10px;
      padding: 12px 10px 12px 20px; border-right: 1px solid var(--border-sub); background: var(--bg-surface);
    }
    .m8-group { display: flex; flex-direction: column; gap: 1px; }
    .m8-group__head {
      display: flex; align-items: center; gap: 6px; padding: 4px 2px;
      font-size: var(--fs-11); font-weight: 700; text-transform: uppercase; letter-spacing: .04em; color: var(--text-sub);
    }
    .m8-group__count { font-weight: 600; color: var(--text-soft); background: var(--bg-surface-subtle); border-radius: var(--radius-full); padding: 0 6px; }
    .m8-item {
      display: flex; align-items: center; gap: 6px; flex-wrap: wrap; text-align: left;
      border: 0; background: none; cursor: pointer; font: inherit; padding: 5px 8px; border-radius: var(--radius-sm);
    }
    .m8-item:hover:not(:disabled) { background: var(--bg-surface-subtle); }
    .m8-item--on { background: var(--primary-bg, var(--bg-surface-subtle)); }
    .m8-item--on .m8-item__ten { color: var(--primary-base); font-weight: 600; }
    .m8-item--mo { cursor: not-allowed; opacity: .5; }
    .m8-item__ten { font-size: var(--fs-13); color: var(--text-body); }
    .m8-item__why { font-size: var(--fs-11); color: var(--text-soft); }
    .m8-tree__note { margin: 0; font-size: var(--fs-11); color: var(--text-soft); }

    .m8-work { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; min-height: 0; }
    .m8-ctx {
      display: flex; align-items: center; gap: 10px; flex-wrap: wrap; padding: 8px 20px;
      border-bottom: 1px solid var(--border-sub); background: var(--bg-surface);
    }
    .m8-ctx__label { font-size: var(--fs-12); font-weight: 600; color: var(--text-sub); }
    .m8-ctx__sel { width: 300px; }
    .m8-ctx__note { font-size: var(--fs-11); color: var(--text-soft); }
    .m8-ctx__sec { font-size: var(--fs-12); font-weight: 600; color: var(--text-strong); }
    .m8-gap { flex: 1; }
    .m8-body { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; overflow: auto; padding: 12px 20px 20px; gap: 12px; }
  `],
})
export class InsM08Page {
  protected readonly store = inject(InsM08Store);
  protected readonly icSearch = IconSearch;
  protected readonly pbiNote = M08_PBI_RIENG_NOTE;

  protected readonly nhoms = [
    { key: 'cau-hinh' as const, label: 'Cấu hình' },
    { key: 'danh-muc' as const, label: 'Danh mục' },
  ];

  /* ── tìm nhanh trong cây (tên mục + từ khóa tham số) ── */
  private readonly kw = signal('');
  protected get kwModel(): string { return this.kw(); }
  protected set kwModel(v: string) { this.kw.set(v ?? ''); }

  /** Cây theo quyền: `an-quyen` = ẨN HẲN (không render). */
  private readonly cayHienThi = computed<InsM08MucCay[]>(() => {
    const kw = this.kw().trim().toLowerCase();
    return M08_CAY.filter((it) => it.kieu !== 'an-quyen')
      .filter((it) => !kw || it.ten.toLowerCase().includes(kw) || it.tuKhoa.some((t) => t.includes(kw)));
  });
  protected itemsOf(nhom: 'cau-hinh' | 'danh-muc'): InsM08MucCay[] {
    return this.cayHienThi().filter((it) => it.nhom === nhom);
  }
  /** Đếm mục ĐỊNH NGHĨA của nhóm (13/9) — kể cả mục ẩn theo quyền, để thấy "12 hiện / 13". */
  protected countOf(nhom: 'cau-hinh' | 'danh-muc'): string {
    const dinhNghia = M08_CAY.filter((it) => it.nhom === nhom).length;
    const hien = M08_CAY.filter((it) => it.nhom === nhom && it.kieu !== 'an-quyen').length;
    return hien === dinhNghia ? String(dinhNghia) : `${hien}/${dinhNghia}`;
  }

  /* ── section con (URL không đổi thật — xem doc-comment đầu file) ── */
  protected readonly section = signal('rule');
  protected readonly dmKey = computed(() => M08_CAY.find((it) => it.key === this.section())?.dmKey ?? null);
  protected readonly tenMuc = computed(() => M08_CAY.find((it) => it.key === this.section())?.ten ?? '');
  protected chon(it: InsM08MucCay): void {
    if (it.kieu === 'mo') return;
    this.section.set(it.key);
  }

  /* ── thanh ngữ cảnh pháp nhân/đơn vị — đổi → reloadTick++ (nạp lại mục) ── */
  protected readonly phamViOptions = [
    { value: 'phap-nhan', label: 'Toàn pháp nhân — Công ty CP Tập đoàn VNR' },
    { value: 'dv1', label: 'Đơn vị: Trụ sở Hà Nội (dv1)' },
    { value: 'dv2', label: 'Đơn vị: Chi nhánh Đà Nẵng (dv2)' },
  ];
  protected readonly phamVi = signal<'phap-nhan' | 'dv1' | 'dv2'>('phap-nhan');
  protected readonly reloadTick = signal(0);
  protected get phamViModel(): unknown { return this.phamVi(); }
  protected set phamViModel(v: unknown) {
    const moi = (v as 'phap-nhan') ?? 'phap-nhan';
    if (moi !== this.phamVi()) {
      this.phamVi.set(moi);
      this.reloadTick.update((t) => t + 1); // destroy + recreate nội dung mục
    }
  }
}
