import { ChangeDetectionStrategy, Component, computed, input } from '@angular/core';

/** ins-layer-badge — nhãn LỚP SỐ LIỆU đứng cạnh MỌI con số tiền (bất biến #1, AC-04):
 *  mỗi số mang ĐÚNG MỘT nhãn lớp, cấm trộn/cộng gộp lớp.
 *  Dùng ở: mọi màn có số tiền — M01 KPI, M02 mô phỏng, M04 đối soát, M07 ba lớp tiền chi. */
export type InsLayer = 'du-kien' | 'da-giao-dich' | 'chinh-thuc';

const LAYER_LABEL: Record<InsLayer, string> = {
  'du-kien': 'Dự kiến nội bộ',
  'da-giao-dich': 'Đã giao dịch/chấp nhận',
  'chinh-thuc': 'Chính thức/đối soát',
};

@Component({
  selector: 'ins-layer-badge',
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `{{ label() }}`,
  host: { class: 'ins-layer-badge', '[attr.data-layer]': 'layer()' },
  styles: [`
    :host {
      display: inline-flex; align-items: center; white-space: nowrap;
      font-size: var(--fs-11); line-height: 1.4; font-weight: 500;
      padding: 0 7px; border-radius: var(--radius-sm);
    }
    :host([data-layer='du-kien']) { background: var(--info-bg); color: var(--info-text); }
    :host([data-layer='da-giao-dich']) { background: var(--tag-purple-bg); color: var(--tag-purple-text); }
    :host([data-layer='chinh-thuc']) { background: var(--success-bg); color: var(--success-text); }
  `],
})
export class InsLayerBadge {
  readonly layer = input.required<InsLayer>();
  protected readonly label = computed(() => LAYER_LABEL[this.layer()]);
}
