import { ChangeDetectionStrategy, Component, computed, inject, input, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { HrmAlert, HrmMessageService, HrmSegmented, HrmTag } from 'hrm-ui';
import { InsSectionLabel } from '../_shared';
import { InsM08Muc, InsM08PhepKiemTra, InsM08Store, M08_MUC_LABEL, m08KhoangLabel } from '../_data/_m08-data';

/** M08 ② — NGƯỠNG KIỂM TRA 3 MỨC (Chặn = không cho lưu · Cảnh báo = popup OK vẫn lưu ·
 *  Không kiểm tra — nhãn hiện tại hệ thống cũ "Vui lòng chọn", OQ đổi tên chờ stakeholder).
 *  Mỗi phép: khoảng hiệu lực + LỊCH SỬ ĐỔI MỨC (phiên bản + người + lý do); phạm vi đơn vị
 *  KẾ THỪA pháp nhân (đơn vị đặt riêng = override); phép LUẬT khóa "Chặn" không mở ô chọn;
 *  chưa gán → mặc định "Không kiểm tra" + CẢNH BÁO THIẾU trên đầu tab; vượt Cảnh báo tại màn
 *  nghiệp vụ = override có lý do + người (AC-10 — thi công tại M02/M03/M05). */
@Component({
  selector: 'ins-m08-nguong-page',
  imports: [FormsModule, HrmAlert, HrmSegmented, HrmTag, InsSectionLabel],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (store.phepChuaGan().length; as n) {
      <hrm-alert type="warning" message="Cảnh báo thiếu cấu hình"
        [description]="'Còn ' + n + ' phép CHƯA GÁN mức — hệ thống áp mặc định &quot;Không kiểm tra&quot; (không im lặng bỏ qua).'" />
    }
    <div class="n-head">
      <ins-section-label text="Bảng phép kiểm tra theo phạm vi kế thừa" tone="muted" [count]="list().length" />
      <span class="n-muted">Phạm vi đang xem: <b>{{ phamViLabel() }}</b> — đơn vị kế thừa pháp nhân, đặt riêng = override.</span>
    </div>

    @for (p of list(); track p.id) {
      <div class="n-item" [class.n-item--thieu]="p.chuaGan">
        <div class="n-item__head">
          <span class="n-mono">{{ p.id }}</span>
          <span class="n-strong">{{ p.ten }}</span>
          @if (p.loaiQuyTac === 'luat') {
            <hrm-tag size="sm" color="red" variant="stroke">Luật — {{ p.soHieu }}</hrm-tag>
          } @else { <hrm-tag size="sm" color="blue" variant="stroke">Nội bộ</hrm-tag> }
          @if (p.phamVi !== 'phap-nhan') { <hrm-tag size="sm" color="purple">Override riêng {{ p.phamVi }}</hrm-tag> }
          @else if (p.keThua) { <hrm-tag size="sm" color="gray">Kế thừa pháp nhân</hrm-tag> }
          @if (p.chuaGan) { <hrm-tag size="sm" color="orange">Chưa gán — mặc định Không kiểm tra</hrm-tag> }
          <span class="n-gap"></span>
          <span class="n-muted">v{{ p.phienBan }} · hiệu lực {{ khoang(p) }}</span>
        </div>

        <div class="n-item__muc">
          @if (p.loaiQuyTac === 'luat') {
            <span class="n-lock">Mức: <b>Chặn</b> — khóa theo luật, không mở ô chọn</span>
          } @else {
            <hrm-segmented [ngModel]="p.muc" (ngModelChange)="doiMuc(p, $event)" [options]="mucOptions" size="sm" />
            <span class="n-muted n-oq">nhãn cũ mức 3: "Vui lòng chọn" → "Không kiểm tra" (OQ chờ stakeholder)</span>
          }
        </div>

        @if (p.lichSuDoiMuc.length) {
          <div class="n-his">
            <span class="n-his__head">Lịch sử đổi mức (phiên bản + người + lý do)</span>
            @for (h of p.lichSuDoiMuc; track h.at) {
              <span class="n-his__row">{{ h.at }} · v{{ h.phienBan }} · {{ mucLabel(h.tuMuc) }} → <b>{{ mucLabel(h.denMuc) }}</b> · {{ h.nguoi }} — {{ h.lyDo }}</span>
            }
          </div>
        }
      </div>
    }

    <p class="n-note">Chặn = không cho lưu (nhiều dòng → trang chi tiết + trước/sau tại màn nghiệp vụ) · Cảnh báo = popup OK
      vẫn lưu, vượt = override có lý do + người (AC-10) · Không kiểm tra = bỏ qua phép.</p>
  `,
  host: { class: 'ins-m08-nguong-page' },
  styles: [`
    :host { display: flex; flex-direction: column; gap: 10px; }
    .n-head { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
    .n-muted { font-size: var(--fs-12); color: var(--text-sub); }
    .n-muted b, .n-lock b { color: var(--text-strong); }
    .n-item { border: 1px solid var(--border-sub); border-radius: var(--radius-md); background: var(--bg-surface); padding: 9px 12px; display: flex; flex-direction: column; gap: 7px; }
    .n-item--thieu { border-color: var(--warning-base, var(--warning-text)); background: var(--warning-bg); }
    .n-item__head { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
    .n-gap { flex: 1; }
    .n-mono { font-family: var(--font-mono, monospace); font-size: var(--fs-12); font-weight: 600; color: var(--text-strong); }
    .n-strong { color: var(--text-strong); font-weight: 500; }
    .n-item__muc { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
    .n-lock { font-size: var(--fs-12); color: var(--error-text); }
    .n-oq { font-size: var(--fs-11); }
    .n-his { display: flex; flex-direction: column; gap: 3px; border-left: 3px solid var(--border-sub); padding-left: 10px; }
    .n-his__head { font-size: var(--fs-11); font-weight: 700; text-transform: uppercase; letter-spacing: .04em; color: var(--text-sub); }
    .n-his__row { font-size: var(--fs-12); color: var(--text-body); }
    .n-his__row b { color: var(--text-strong); }
    .n-note { margin: 0; font-size: var(--fs-11); color: var(--text-soft); }
  `],
})
export class InsM08NguongPage {
  protected readonly store = inject(InsM08Store);
  private readonly msg = inject(HrmMessageService);

  readonly phamVi = input<'phap-nhan' | 'dv1' | 'dv2'>('phap-nhan');

  protected readonly phamViLabel = computed(() =>
    this.phamVi() === 'phap-nhan' ? 'Toàn pháp nhân' : this.phamVi() === 'dv1' ? 'Trụ sở HN (dv1)' : 'CN Đà Nẵng (dv2)');

  /** Phạm vi kế thừa: đơn vị thấy phép pháp nhân + override riêng của mình. */
  protected readonly list = computed(() => {
    const pv = this.phamVi();
    return this.store.pheps().filter((p) => pv === 'phap-nhan' ? true : p.phamVi === 'phap-nhan' || p.phamVi === pv);
  });

  protected readonly mucOptions = [
    { label: M08_MUC_LABEL['chan'], value: 'chan' },
    { label: M08_MUC_LABEL['canh-bao'], value: 'canh-bao' },
    { label: M08_MUC_LABEL['khong-kiem-tra'], value: 'khong-kiem-tra' },
  ];

  protected khoang(p: InsM08PhepKiemTra): string { return m08KhoangLabel(p.khoangHL); }
  protected mucLabel(m: InsM08Muc): string { return M08_MUC_LABEL[m]; }
  /** Bộ đếm signal ép segmented re-render khi store từ chối đổi (giữ giá trị cũ). */
  private readonly bump = signal(0);

  protected doiMuc(p: InsM08PhepKiemTra, v: string | number): void {
    const denMuc = String(v) as InsM08Muc;
    if (denMuc === p.muc) return;
    const r = this.store.doiMucPhep(p.id, denMuc, `Đổi mức thao tác demo (${this.store.currentUser})`);
    if (r.ok) this.msg.success(`Đã đổi mức ${p.id} → ${M08_MUC_LABEL[denMuc]} — sinh PHIÊN BẢN MỚI + 1 dòng lịch sử.`);
    else { this.msg.error(r.reason ?? ''); this.bump.update((x) => x + 1); }
  }
}
