let clockMin = 0;
function demoNow(): string {
  clockMin += 6;
  const h = 9 + Math.floor(clockMin / 60), m = clockMin % 60;
  return `${M05_TODAY} ${String(Math.min(h, 18)).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
}

const clone = <T>(x: T): T => structuredClone(x);

/** dd/mm/yyyy → Date (chỉ gọi trong handler — zoneless, không Date.now khi render). */
function m05Date(s: string): Date | null {
  const [d, m, y] = (s ?? '').split('/').map(Number);
  return d && m && y ? new Date(y, m - 1, d) : null;
}
