@Injectable({ providedIn: 'root' })
export class InsM05Store {
  /** Người dùng demo hiện tại — chuyên viên C&B (quyền: gửi yêu cầu, tính lại, kết xuất). */
  readonly currentUser = HR_1;
  readonly quanLyHR = HR_2;
  readonly keToan = KT_1;

  /** BQA-16 (Phase E): M05 GỌI API công khai của M02 khi thu hồi đề xuất (chỉ gọi — không sửa M02). */
  private readonly m02 = inject(InsM02Store);

  readonly cases = signal<InsCase[]>(clone(CASE_SEED));
  readonly dongRa = signal<InsDongRa[]>(clone(RA_SEED));
  readonly deXuat = signal<InsDeXuatBienDong[]>(clone(DEXUAT_SEED));
  /** Nhật ký append-only (bất biến #3). */
  readonly audit = signal<InsM05AuditEntry[]>([]);
  /** Lần bulk gần nhất — retry idempotent CHỈ phần lỗi. */
  readonly lastBulk = signal<{ action: M05BulkAction; skipped: { id: string; reason: string }[] } | null>(null);

  /* ── UI state hàng đợi giữ trong store (back từ Màn B GIỮ tab/filter — drawer contract) ── */
  readonly queueTab = signal<'tat-ca' | InsCaseNhom>('tat-ca');
  readonly queueKw = signal('');
  readonly queueState = signal<string | null>(null);
  readonly queueHan = signal('');
  readonly queueThieuCT = signal(false);
  /** Filter "Tháng/Lần đề nghị" (PBI-05.01.3 — theo dõi lô ở Màn A). '' = tất cả. */
  readonly queueThangLan = signal('');

  resetDemo(): void {
    this.cases.set(clone(CASE_SEED));
    this.dongRa.set(clone(RA_SEED));
    this.deXuat.set(clone(DEXUAT_SEED));
    this.audit.set([]);
    this.lastBulk.set(null);
    this.queueTab.set('tat-ca'); this.queueKw.set(''); this.queueState.set(null);
    this.queueHan.set(''); this.queueThieuCT.set(false); this.queueThangLan.set('');
  }

  caseOf(id: string): InsCase | undefined { return this.cases().find((c) => c.maCase === id); }

  /* ── computed đếm ── */

  /** Case trên lưới chính — `Chưa tiếp nhận` ở SECTION RIÊNG (đúng 2 lối ra), không vào lưới. */
  readonly gridCases = computed(() => this.cases().filter((c) => c.trangThai !== 'chua-tiep-nhan'));
  readonly chuaTiepNhan = computed(() => this.cases().filter((c) => c.trangThai === 'chua-tiep-nhan'));
  readonly dongRaMo = computed(() => this.dongRa().filter((r) => r.trangThai === 'cho-ra' || r.trangThai === 'dang-ra'));

  /** Đếm 4 tab + severity quá hạn (tab count "12 · 3 quá hạn"). */
  readonly tabCounts = computed(() => {
    const list = this.gridCases();
    const cnt = (nhom?: InsCaseNhom) => {
      const sub = nhom ? list.filter((c) => c.nhom === nhom) : list;
      return { count: sub.length, quaHan: sub.filter((c) => c.coHan === 'qua-han').length };
    };
    return { tatCa: cnt(), omDau: cnt('om-dau'), thaiSan: cnt('thai-san'), duongSuc: cnt('duong-suc') };
  });

  /** Case có ≥1 mục checklist BẮT BUỘC thiếu (bộ lọc "Thiếu chứng từ" + cột hạn bổ sung SLA M08). */
  readonly thieuChungTuCases = computed(() =>
    this.gridCases().filter((c) => c.checklist.some((k) => k.batBuoc && k.trangThai === 'thieu')));

  /** Tổng chi dự kiến của lưới — LUÔN nhãn `Dự kiến nội bộ` (bất biến #1). */
  readonly tongDuKien = computed(() =>
    insFormatVnd(this.gridCases().reduce((s, c) => s + insParseVnd(c.soTienDuKien), 0)));

  /** Bộ lọc trạng thái CHỈ nạp trạng thái "Có sử dụng" (đang có case — LOCK m05.md). */
  readonly statesInUse = computed(() => {
    const used = new Set(this.gridCases().map((c) => c.trangThai));
    return [...used].map((s) => ({ value: s, label: INS_CASE_STATE_LABEL[s] }));
  });

  /** Giá trị "Tháng/Lần đề nghị" đang có trong dữ liệu lô (filter PBI-05.01.3 — BQA-7). */
  readonly thangLanInUse = computed(() => {
    const used = new Set<string>();
    for (const c of this.gridCases()) if (c.loB4) used.add(c.loB4.thangLan);
    return [...used].map((v) => ({ value: v, label: v }));
  });

  /* ── helpers ── */

  private patch(id: string, p: Partial<InsCase>): void {
    this.cases.update((list) => list.map((c) => (c.maCase === id ? { ...c, ...p } : c)));
  }
  private log(entry: Omit<InsM05AuditEntry, 'at'>): void {
    this.audit.update((l) => [...l, { at: demoNow(), ...entry }]);
  }

  /* ── GUARD-PAIR (`*Reason(id)` trả string|null + transition cùng tên) ── */

  /** `Chưa tiếp nhận` → Tiếp nhận lại (B1, dữ liệu gốc) — 1 trong đúng 2 lối ra. */
  tiepNhanReason(id: string): string | null {
    const c = this.caseOf(id);
    if (!c) return 'Không tìm thấy case.';
    if (c.trangThai !== 'chua-tiep-nhan') return `Chỉ tiếp nhận lại case ở trạng thái Chưa tiếp nhận (hiện: ${INS_CASE_STATE_LABEL[c.trangThai]}).`;
    return null;
  }
  tiepNhan(id: string): { ok: boolean; reason?: string } {
    const reason = this.tiepNhanReason(id);
    if (reason) return { ok: false, reason };
    this.patch(id, { trangThai: 'tiep-nhan' });
    this.log({ nguoi: this.currentUser, hanhDong: 'Tiếp nhận lại case Chưa tiếp nhận — mở B1 với dữ liệu gốc', caseIds: [id] });
    return { ok: true };
  }

  /** Guard sang B4: thiếu chứng từ bắt buộc / exception dữ liệu đóng MỞ → không kê khai & nộp. */
  sangB4Reason(id: string): string | null {
    const c = this.caseOf(id);
    if (!c) return 'Không tìm thấy case.';
    const thieu = c.checklist.filter((k) => k.batBuoc && (k.trangThai === 'thieu' || k.trangThai === 'cho-xac-minh'));
    if (thieu.length) return `Còn ${thieu.length} mục checklist bắt buộc thiếu/chờ xác minh — hoàn tất B2 trước khi kê khai.`;
    if (c.exceptionDong && (c.exceptionDong.trangThai === 'moi' || c.exceptionDong.trangThai === 'dang-xu-ly')) {
      return `Exception dữ liệu đóng ${c.exceptionDong.id} đang mở (hạn ${c.exceptionDong.han}) — đóng exception thì case tự chạy lại kiểm tra (AC-08).`;
    }
    const chan = c.viPham.find((v) => v.mucDo === 'chan' && !v.daOverride);
    if (chan) return `Vi phạm mức CHẶN ${chan.maQuyTac} chưa xử lý — không sang B4.`;
    if (m05StepOfState(c.trangThai) < 3) return `Chưa có kết quả tính (hiện: ${INS_CASE_STATE_LABEL[c.trangThai]}) — hoàn tất B3 trước.`;
    return null;
  }

  /** Guard override: đã nộp → không override (phải qua chu trình sửa/nộp lại). */
  overrideReason(id: string): string | null {
    const c = this.caseOf(id);
    if (!c) return 'Không tìm thấy case.';
    if (!PRE_SUBMIT.has(c.trangThai)) return `Case đã ${INS_CASE_STATE_LABEL[c.trangThai].toLowerCase()} — đã nộp thì không override (sửa = chu trình Cần bổ sung → nộp lại).`;
    if (!c.ketQuaTinh) return 'Chưa có kết quả tính của hệ thống — không có số để override.';
    return null;
  }

  /** Guard tính lại: đã công bố → loại khỏi tính lại (phải xóa công bố trước); đã thanh toán → không xử lý lại. */
  tinhLaiReason(id: string): string | null {
    const c = this.caseOf(id);
    if (!c) return 'Không tìm thấy case.';
    if (c.daCongBo) return 'Đã công bố — loại khỏi tính lại (phải xóa công bố trước).';
    if (c.thanhToan === 'da') return 'Đã thanh toán — không xử lý lại.';
    if (c.trangThai === 'dong') return 'Case đã đóng — sửa = tạo case/phiên bản mới link ngược.';
    if (m05StepOfState(c.trangThai) < 3 && c.trangThai !== 'san-sang-tinh') {
      return `Chưa sẵn sàng tính (hiện: ${INS_CASE_STATE_LABEL[c.trangThai]}).`;
    }
    return null;
  }
  tinhLai(id: string): { ok: boolean; reason?: string } {
    const reason = this.tinhLaiReason(id);
    if (reason) return { ok: false, reason };
    const c = this.caseOf(id)!;
    if (PRE_SUBMIT.has(c.trangThai)) this.patch(id, { trangThai: c.ketQuaTinh ? 'da-tinh' : c.trangThai });
    this.log({ nguoi: this.currentUser, hanhDong: `Tính lại mức hưởng (rule ${c.ketQuaTinh?.ruleVersion ?? 'RS-CD-2026.08'} — sổ phân tích: xóa dòng cũ cùng chứng từ, ghi mới)`, caseIds: [id] });
    return { ok: true };
  }

  /** Guard công bố: kết quả `Đã/Không thanh toán` + CHƯA công bố + phải chọn kiểu Tháng/Lần. */
  congBoReason(id: string): string | null {
    const c = this.caseOf(id);
    if (!c) return 'Không tìm thấy case.';
    if (c.daCongBo) return 'Đã công bố rồi — không công bố trùng (idempotent).';
    if (!c.thanhToan) return 'Chưa có kết quả Đã/Không thanh toán — chưa đủ điều kiện công bố.';
    return null;
  }
  congBo(id: string, kieu: 'Tháng' | 'Lần'): { ok: boolean; reason?: string } {
    const reason = this.congBoReason(id);
    if (reason) return { ok: false, reason };
    this.patch(id, { daCongBo: true, congBoKieu: kieu, trangThai: 'da-cong-bo' });
    this.log({ nguoi: this.keToan, hanhDong: `Công bố theo ${kieu} + gửi mail 2 mẫu; thông báo portal gom <Số lượng> + <Nghiệp vụ> + <Trạng thái>`, caseIds: [id] });
    return { ok: true };
  }

  /** Guard đóng case: chỉ sau khi M07 trả trạng thái chi CUỐI (hoặc nhánh đóng sớm có lý do danh mục). */
  dongCaseReason(id: string): string | null {
    const c = this.caseOf(id);
    if (!c) return 'Không tìm thấy case.';
    if (c.trangThai === 'dong') return 'Case đã đóng.';
    const nhanhSom = new Set<InsCaseState>(['bi-tu-choi', 'thieu-chung-tu-qua-han', 'chua-tiep-nhan', 'tiep-nhan']);
    if (nhanhSom.has(c.trangThai)) return null; // đóng sớm với lý do danh mục
    if (c.banGiaoChi && !c.trangThaiChiM07) return 'Đã bàn giao chi — chờ M07 trả trạng thái chi cuối (Đã chi trả/Không chi trả) mới được đóng.';
    if (!c.trangThaiChiM07 && !nhanhSom.has(c.trangThai)) {
      return 'Chưa có trạng thái chi cuối từ M07 — chỉ đóng sớm được case Bị từ chối / Thiếu chứng từ quá hạn / tạo nhầm.';
    }
    return null;
  }
  dongCase(id: string, lyDo: InsLyDoDong, ghiChu: string): { ok: boolean; reason?: string } {
    const reason = this.dongCaseReason(id);
    if (reason) return { ok: false, reason };
    this.patch(id, { trangThai: 'dong', dongInfo: { lyDo, ghiChu, nguoi: this.currentUser, at: demoNow() } });
    // case hủy/từ chối toàn phần → thu hồi đề xuất biến động CHƯA NỘP (quy tắc 14 ngày) + đồng bộ M02
    if (lyDo === 'tu-choi-khong-nop-lai' || lyDo === 'tao-nham-trung') this.thuHoiDeXuat(id, lyDo);
    this.log({ nguoi: this.currentUser, hanhDong: `Đóng case — lý do danh mục "${INS_LYDO_DONG_LABEL[lyDo]}" + thông báo NLĐ`, caseIds: [id], lyDo: ghiChu || INS_LYDO_DONG_LABEL[lyDo] });
    return { ok: true };
  }

  /** BQA-16 (Phase E): thu hồi đề xuất biến động của case hủy/từ chối toàn phần — cập nhật hàng đợi
   *  nội bộ VÀ gọi `tryLoaiTru` (API công khai M02) trên dòng đề xuất tương ứng, tìm qua
   *  correlationId. Thay quyết định 1 phía cũ (chỉ ghi `da-thu-hoi` nội bộ M05). */
  private thuHoiDeXuat(caseId: string, lyDoDong: InsLyDoDong): void {
    const cuaCase = this.deXuat().filter((d) =>
      d.maCase === caseId && (d.trangThai === 'moi' || d.trangThai === 'da-tiep-nhan-hang-doi-02'));
    if (!cuaCase.length) return;
    this.deXuat.update((list) => list.map((d) =>
      cuaCase.some((x) => x.id === d.id) ? { ...d, trangThai: 'da-thu-hoi' as InsDeXuatTrangThai } : d));
    for (const d of cuaCase) {
      const dongM02 = this.m02.changes().find((ch) => ch.correlationId === d.correlationId);
      if (!dongM02) {
        this.log({ nguoi: this.currentUser, hanhDong: `Thu hồi đề xuất ${d.id} — không tìm thấy dòng M02 theo ${d.correlationId} (chưa tiếp nhận)`, caseIds: [caseId] });
        continue;
      }
      const r = this.m02.tryLoaiTru(dongM02.id, `Nguồn thu hồi — case ${caseId} đóng (${INS_LYDO_DONG_LABEL[lyDoDong]})`);
      this.log({ nguoi: this.currentUser, hanhDong: r.ok
        ? `Thu hồi đề xuất ${d.id} — đã loại trừ dòng M02 ${dongM02.id} (${d.correlationId})`
        : `Thu hồi đề xuất ${d.id} — M02 từ chối loại trừ dòng ${dongM02.id}: ${r.reason}`, caseIds: [caseId] });
    }
  }

  /** UX-3 (quyết định Phase E — thay tiền lệ A-M05): M07 GHI NGƯỢC trạng thái chi cuối vào case.
   *  Chấp nhận ghi-xuyên CHO RIÊNG trường `trangThaiChiM07` (+ ghi chú `ketQuaChiTiet`) — có audit.
   *  Case đang ở nhánh sau bàn giao đồng bộ luôn trạng thái case + kết quả thanh toán; case đã
   *  Đóng/Đã công bố chỉ nhận ghi chú (không đè trạng thái). */
  nhanKetQuaChi(caseId: string, trangThai: 'da-chi-tra' | 'khong-chi-tra', ghiChu?: string): { ok: boolean; reason?: string } {
    const c = this.caseOf(caseId);
    if (!c) return { ok: false, reason: `Không tìm thấy case ${caseId}.` };
    const p: Partial<InsCase> = { trangThaiChiM07: trangThai };
    if (ghiChu?.trim()) p.ketQuaChiTiet = ghiChu.trim();
    if (c.trangThai === 'da-ban-giao-chi' || c.trangThai === 'da-chi-tra' || c.trangThai === 'khong-chi-tra') {
      p.trangThai = trangThai;
      p.thanhToan = trangThai === 'da-chi-tra' ? 'da' : 'khong';
    }
    this.patch(caseId, p);
    this.log({ nguoi: this.keToan, hanhDong: `Nhận kết quả chi từ M07: ${INS_CASE_STATE_LABEL[trangThai]}${ghiChu ? ` — ${ghiChu}` : ''} (ghi-xuyên Phase E)`, caseIds: [caseId] });
    return { ok: true };
  }

  /* ── B2: chứng từ quá hạn — 2 lối ra · xem tài liệu ghi log · override cảnh báo ── */

  giaHanChungTu(id: string, hanMoi: string, nguoiDuyet: string): { ok: boolean; reason?: string } {
    const c = this.caseOf(id);
    if (!c) return { ok: false, reason: 'Không tìm thấy case.' };
    if (c.trangThai !== 'thieu-chung-tu-qua-han') return { ok: false, reason: 'Chỉ gia hạn case Thiếu chứng từ quá hạn.' };
    this.patch(id, {
      trangThai: 'cho-chung-tu',
      checklist: c.checklist.map((k) => (k.trangThai === 'thieu' ? { ...k, hanBoSung: hanMoi } : k)),
      viPham: c.viPham.filter((v) => v.maQuyTac !== 'R-CD-011'),
      coHan: 'sap-den-han',
      ngayHanXuLy: hanMoi,
    });
    this.log({ nguoi: this.currentUser, hanhDong: `Gia hạn bổ sung chứng từ đến ${hanMoi} (duyệt bởi QL HR: ${nguoiDuyet})`, caseIds: [id] });
    return { ok: true };
  }

  /** UX (Phase E): "Đánh dấu đã nhận" chứng từ thiếu/chờ xác minh → mục sang `đủ`; đủ toàn bộ mục
   *  bắt buộc → case TỰ sang Sẵn sàng tính (cùng cơ chế exception đóng tự chạy lại kiểm tra AC-08). */
  danhDauDaNhan(caseId: string, itemId: string): { ok: boolean; reason?: string; sanSang?: boolean } {
    const c = this.caseOf(caseId);
    if (!c) return { ok: false, reason: 'Không tìm thấy case.' };
    const item = c.checklist.find((k) => k.id === itemId);
    if (!item) return { ok: false, reason: 'Không tìm thấy mục checklist.' };
    if (item.trangThai === 'du') return { ok: false, reason: 'Mục đã ở trạng thái đủ.' };
    const checklist = c.checklist.map((k) =>
      k.id === itemId ? { ...k, trangThai: 'du' as InsChecklistTrangThai, hanBoSung: undefined } : k);
    const conThieu = checklist.some((k) => k.batBuoc && (k.trangThai === 'thieu' || k.trangThai === 'cho-xac-minh'));
    const p: Partial<InsCase> = { checklist };
    // hết mục `thiếu` bắt buộc → gỡ vi phạm chặn "chứng từ thiếu quá hạn" (R-CD-011, như gia hạn)
    if (!checklist.some((k) => k.batBuoc && k.trangThai === 'thieu')) {
      p.viPham = c.viPham.filter((v) => v.maQuyTac !== 'R-CD-011');
    }
    const oB12 = c.trangThai === 'tiep-nhan' || c.trangThai === 'cho-chung-tu' || c.trangThai === 'thieu-chung-tu-qua-han';
    const sanSang = !conThieu && oB12;
    if (sanSang) p.trangThai = 'san-sang-tinh';
    this.patch(caseId, p);
    this.log({ nguoi: this.currentUser, hanhDong: `Đánh dấu đã nhận "${item.muc}" — mục sang đủ${sanSang ? '; đủ điều kiện — case TỰ sang Sẵn sàng tính' : ''}`, caseIds: [caseId] });
    return { ok: true, sanSang };
  }

  /** Mọi lượt xem tài liệu y tế nhạy cảm GHI LOG (PBI-05.02.4). */
  xemTaiLieu(caseId: string, taiLieuId: string): void {
    const at = demoNow();
    this.cases.update((list) => list.map((c) => c.maCase === caseId
      ? { ...c, taiLieu: c.taiLieu.map((t) => t.id === taiLieuId
          ? { ...t, log: [...t.log, { at, nguoi: this.currentUser, hanhDong: t.nhayCam ? 'Xem tài liệu (y tế nhạy cảm — ghi log)' : 'Xem tài liệu' }] } : t) }
      : c));
    this.log({ nguoi: this.currentUser, hanhDong: `Xem tài liệu ${taiLieuId} (ghi log mọi lượt xem)`, caseIds: [caseId] });
  }

  /** Bỏ qua cảnh báo eligibility = override (lý do + người) — giữ vết trên vi phạm. */
  overrideCanhBao(caseId: string, maQuyTac: string, lyDo: string): { ok: boolean; reason?: string } {
    if (!lyDo.trim()) return { ok: false, reason: 'Bỏ qua cảnh báo = override — lý do BẮT BUỘC.' };
    const c = this.caseOf(caseId);
    if (!c) return { ok: false, reason: 'Không tìm thấy case.' };
    const at = demoNow();
    this.patch(caseId, {
      viPham: c.viPham.map((v) => (v.maQuyTac === maQuyTac ? { ...v, daOverride: { lyDo: lyDo.trim(), nguoi: this.currentUser, at } } : v)),
    });
    this.log({ nguoi: this.currentUser, hanhDong: `Tiếp tục (override) cảnh báo ${maQuyTac}`, caseIds: [caseId], lyDo: lyDo.trim() });
    return { ok: true };
  }

  /* ── B3: tính số ngày / mức hưởng · override maker-checker ── */

  /** UX (Phase E): case chưa có seed tính → TÍNH THẬT công thức đơn giản từ field case
   *  (số ngày lịch − CN; CHƯA trừ lễ — bản đầy đủ kèm lễ ở CS-2026-0103). */
  private tinhDonGian(c: InsCase): InsKetQuaTinh | null {
    const tu = m05Date(c.tuNgay), den = m05Date(c.denNgay);
    if (!tu || !den || den < tu) return null;
    const bangNgay: InsNgayGiaiThich[] = [];
    let soNgayTho = 0, soNgay = 0;
    for (const d = new Date(tu); d <= den; d.setDate(d.getDate() + 1)) {
      soNgayTho++;
      const cn = d.getDay() === 0;
      if (!cn) soNgay++;
      bangNgay.push({
        ngay: `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}`,
        thu: M05_THU[d.getDay()], tinh: !cn,
        lyDo: cn ? 'Chủ nhật — không tính (công thức nhóm 2 trừ CN)' : 'Ngày làm việc — tính hưởng',
      });
    }
    const luong = insParseVnd(insNhanVien(c.nhanVienId)?.salary ?? '');
    if (!luong && c.nhom !== 'duong-suc') return null;
    const rule = c.nhom === 'thai-san' ? RULE_THAI_SAN : c.nhom === 'duong-suc' ? RULE_DUONG_SUC : RULE_OM_DAU;
    let soTien: number, congThucTien: string;
    if (c.nhom === 'duong-suc') { soTien = 702_000 * soNgay; congThucTien = 'Dưỡng sức = 30% lương cơ sở (702.000/ngày) × số ngày'; }
    else if (c.nhom === 'thai-san') { soTien = Math.round((luong / 24) * soNgay / 1000) * 1000; congThucTien = 'Thai sản = (Lương BHXH ÷ 24) × số ngày × 100%'; }
    else { soTien = Math.round((luong / 24) * soNgay * 0.75 / 1000) * 1000; congThucTien = 'Ốm đau = (Lương BHXH ÷ 24) × số ngày × 75%'; }
    return {
      soNgayTho, soNgay, bangNgay,
      congThucNgay: `${soNgayTho} ngày lịch − ${soNgayTho - soNgay} CN = ${soNgay} ngày (tính nhanh demo — CHƯA trừ lễ; bản đầy đủ: CS-2026-0103)`,
      luongCanCu: insFormatVnd(luong || 2_340_000), chuKy: '16/07 – 15/08/2026 (cấu hình M08)',
      congThucTien, soTien: insFormatVnd(soTien),
      ...rule, ngayHieuLucRule: rule.ngayHieuLuc,
      dongSoPhanTich: `PT-${c.maCase.slice(3)}-v1 (dòng mới — tính nhanh demo)`,
    };
  }

  tinhSoNgay(id: string): { ok: boolean; reason?: string } {
    const c = this.caseOf(id);
    if (!c) return { ok: false, reason: 'Không tìm thấy case.' };
    if (!c.ketQuaTinh) {
      const guard = this.tinhLaiReason(id);
      if (guard) return { ok: false, reason: guard };
      const kq = this.tinhDonGian(c);
      if (!kq) return { ok: false, reason: 'Chưa đủ dữ liệu chấm công/khoảng nghỉ để tính (demo đầy đủ ở CS-2026-0103).' };
      this.patch(id, {
        ketQuaTinh: kq, soNgay: kq.soNgay, soTienDuKien: kq.soTien,
        ...(PRE_SUBMIT.has(c.trangThai) ? { trangThai: 'da-tinh' as InsCaseState } : {}),
      });
      this.log({ nguoi: this.currentUser, hanhDong: `Tính số ngày + mức hưởng (tính nhanh demo): ${kq.congThucNgay} = ${kq.soTien}`, caseIds: [id] });
      return { ok: true };
    }
    this.log({ nguoi: this.currentUser, hanhDong: `Tính số ngày: ${c.ketQuaTinh.congThucNgay} (bảng giải thích từng ngày bị trừ)`, caseIds: [id] });
    return { ok: true };
  }
  tinhMucHuong(id: string): { ok: boolean; reason?: string } {
    const c = this.caseOf(id);
    if (!c?.ketQuaTinh) return { ok: false, reason: 'Chưa có kết quả tính số ngày.' };
    if (PRE_SUBMIT.has(c.trangThai) && c.trangThai !== 'cho-duyet-override') this.patch(id, { trangThai: 'da-tinh' });
    this.log({ nguoi: this.currentUser, hanhDong: `Tính mức hưởng: ${c.ketQuaTinh.congThucTien} = ${c.ketQuaTinh.soTien} (rule ${c.ketQuaTinh.ruleVersion})`, caseIds: [id] });
    return { ok: true };
  }

  /** Lưu override — không lý do KHÔNG lưu; giữ song song giá trị hệ thống; case → Chờ duyệt override. */
  luuOverride(id: string, sau: string, lyDo: string): { ok: boolean; reason?: string } {
    if (!lyDo.trim()) return { ok: false, reason: 'Override không lý do KHÔNG lưu (BUSINESS_LOCK B3).' };
    const reason = this.overrideReason(id);
    if (reason) return { ok: false, reason };
    const c = this.caseOf(id)!;
    this.patch(id, {
      trangThai: 'cho-duyet-override',
      override: { truoc: c.ketQuaTinh!.soTien, sau, lyDo: lyDo.trim(), nguoiDeXuat: this.currentUser, trangThai: 'cho-duyet', at: demoNow() },
    });
    this.log({ nguoi: this.currentUser, hanhDong: `Đề xuất override ${c.ketQuaTinh!.soTien} → ${sau} (giữ song song giá trị hệ thống)`, caseIds: [id], lyDo: lyDo.trim() });
    return { ok: true };
  }

  /** Duyệt/từ chối override — NGƯỜI LẬP ≠ NGƯỜI DUYỆT (maker-checker, ngưỡng theo tiền + loại M08). */
  duyetOverride(id: string, chapNhan: boolean): { ok: boolean; reason?: string } {
    const c = this.caseOf(id);
    if (!c?.override) return { ok: false, reason: 'Case không có override chờ duyệt.' };
    if (c.override.trangThai !== 'cho-duyet') return { ok: false, reason: 'Override không ở trạng thái Chờ duyệt.' };
    if (c.override.nguoiDeXuat === this.currentUser) {
      return { ok: false, reason: `Người lập (${c.override.nguoiDeXuat}) không được tự duyệt — maker ≠ checker.` };
    }
    this.patch(id, {
      override: { ...c.override, trangThai: chapNhan ? 'da-duyet' : 'bi-tu-choi', nguoiDuyet: this.currentUser },
      trangThai: 'da-tinh',
      soTienDuKien: chapNhan ? c.override.sau : c.override.truoc,
    });
    this.log({ nguoi: this.currentUser, hanhDong: chapNhan
      ? `Duyệt override ${c.override.truoc} → ${c.override.sau} (giá trị hệ thống giữ song song)`
      : `Từ chối override — dùng lại giá trị hệ thống ${c.override.truoc}`, caseIds: [id] });
    return { ok: true };
  }

  /* ── B4: lập/ghép lô + tiến chuỗi nộp bằng tay (UX-5 Phase E) · xử lý yêu cầu sửa từ M07 · nộp lại ── */

  /** UX-5: đưa case Đã tính vào lô kê khai B4 (tạo lô nội bộ M05, pre-check = `sangB4Reason`). */
  lapLoB4(id: string): { ok: boolean; reason?: string; maLo?: string } {
    const c = this.caseOf(id);
    if (!c) return { ok: false, reason: 'Không tìm thấy case.' };
    if (c.loB4) return { ok: false, reason: `Case đã thuộc lô ${c.loB4.maLo}.` };
    if (c.trangThai !== 'da-tinh') return { ok: false, reason: `Chỉ đưa case Đã tính vào lô (hiện: ${INS_CASE_STATE_LABEL[c.trangThai]}).` };
    const preCheck = this.sangB4Reason(id);
    if (preCheck) return { ok: false, reason: preCheck };
    const maLo = `LO-CD-2026-08-${String(10 + this.cases().filter((x) => x.loB4).length)}`;
    const template = c.nhom === 'duong-suc' ? '630b — Dưỡng sức, phục hồi sức khỏe' : '630a — Chế độ thai sản';
    this.patch(id, {
      trangThai: 'cho-kiem-tra',
      loB4: { maLo, thangLan: 'Tháng 08/2026', template,
        vai: { lap: this.currentUser, kiemTra: HR_2, duyet: KT_1, ky: GD_1, nop: this.currentUser }, lanNop: [] },
    });
    this.log({ nguoi: this.currentUser, hanhDong: `Đưa vào lô kê khai ${maLo} (template bắt buộc ${template}) — case sang Chờ kiểm tra (chuỗi 5 vai)`, caseIds: [id] });
    return { ok: true, maLo };
  }

  /** Nhãn bước kế tiếp của chuỗi nộp B4 — null = không có bước tay. */
  tienB4Label(id: string): string | null {
    switch (this.caseOf(id)?.trangThai) {
      case 'cho-kiem-tra': return 'Kiểm tra xong → Chờ duyệt';
      case 'cho-duyet': return 'Duyệt lô → Chờ ký';
      case 'cho-ky': return 'Ký & nộp cơ quan → Đã nộp';
      default: return null;
    }
  }

  /** UX-5: tiến 1 bước chuỗi nộp B4 bằng tay (Chờ kiểm tra → Chờ duyệt → Chờ ký → Đã nộp);
   *  bước cuối (ký & nộp) sinh LẦN NỘP mới — user đi tiếp được tới `da-nop` không cần seed. */
  tienB4(id: string): { ok: boolean; reason?: string } {
    const c = this.caseOf(id);
    if (!c?.loB4) return { ok: false, reason: 'Case chưa vào lô kê khai — dùng "Đưa vào lô kê khai" trước.' };
    const next: Partial<Record<InsCaseState, InsCaseState>> = {
      'cho-kiem-tra': 'cho-duyet', 'cho-duyet': 'cho-ky', 'cho-ky': 'da-nop',
    };
    const den = next[c.trangThai];
    if (!den) return { ok: false, reason: `Không có bước kế tiếp từ ${INS_CASE_STATE_LABEL[c.trangThai]}.` };
    if (den === 'da-nop') {
      const lan = c.loB4.lanNop.length + 1;
      const lanMoi: InsLanNop = {
        lan, ngayNop: demoNow(), payload: `FP-CD-${c.maCase.slice(-4)}`,
        phienBanBM: `${c.loB4.template.slice(0, 4)} v2026.1`, chuKy: `USB token — GĐ ${GD_1}`,
        maGD: `GD-2026-${String(82000 + lan)}`, phanHoi: 'Đã tiếp nhận — chờ xử lý',
        linkLanTruoc: lan > 1 ? lan - 1 : undefined,
      };
      this.patch(id, { trangThai: 'da-nop', loB4: { ...c.loB4, lanNop: [...c.loB4.lanNop, lanMoi] } });
    } else this.patch(id, { trangThai: den });
    this.log({ nguoi: this.currentUser, hanhDong: `B4: ${INS_CASE_STATE_LABEL[c.trangThai]} → ${INS_CASE_STATE_LABEL[den]}${den === 'da-nop' ? ' (ký & nộp — sinh lần nộp mới)' : ''}`, caseIds: [id] });
    return { ok: true };
  }

  nopLai(id: string): { ok: boolean; reason?: string } {
    const c = this.caseOf(id);
    if (!c?.loB4) return { ok: false, reason: 'Case chưa có lô kê khai.' };
    if (c.trangThai !== 'can-bo-sung' && c.trangThai !== 'bi-tu-choi') {
      return { ok: false, reason: `Chỉ nộp lại từ Cần bổ sung / Bị từ chối (hiện: ${INS_CASE_STATE_LABEL[c.trangThai]}).` };
    }
    const lanTruoc = c.loB4.lanNop.length;
    const lanMoi: InsLanNop = {
      lan: lanTruoc + 1, ngayNop: demoNow(), payload: `FP-CD-${c.maCase.slice(-4)}-r${lanTruoc + 1}`,
      phienBanBM: c.loB4.lanNop[lanTruoc - 1]?.phienBanBM ?? '630a v2026.1',
      chuKy: 'USB token — GĐ Trần Quốc Bảo', maGD: `GD-2026-${String(81900 + lanTruoc)}`,
      phanHoi: 'Đã tiếp nhận — chờ xử lý', linkLanTruoc: lanTruoc || undefined,
    };
    this.patch(id, { trangThai: 'da-nop', loB4: { ...c.loB4, lanNop: [...c.loB4.lanNop, lanMoi] } });
    this.log({ nguoi: this.currentUser, hanhDong: `Nộp lại lần ${lanMoi.lan} — giữ link lần trước (#${lanTruoc})`, caseIds: [id] });
    return { ok: true };
  }

  /* ── B5: bàn giao chi (idempotent) ── */

  banGiaoChi(id: string): { ok: boolean; reason?: string; correlationId?: string } {
    const c = this.caseOf(id);
    if (!c) return { ok: false, reason: 'Không tìm thấy case.' };
    if (c.banGiaoChi) return { ok: false, reason: `1 case 1 bản ghi — đã bàn giao (${c.banGiaoChi.correlationId}), chạy lại không sinh trùng.` };
    if (c.trangThai !== 'duoc-chap-nhan' && c.trangThai !== 'chap-nhan-mot-phan') {
      return { ok: false, reason: `Chỉ bàn giao case Được chấp nhận / Chấp nhận một phần (hiện: ${INS_CASE_STATE_LABEL[c.trangThai]}).` };
    }
    const correlationId = insNextCorrelationId(); // cấp phát tập trung (bất biến #5) — M07 derive dòng theo COR này (UX-2)
    this.patch(id, {
      trangThai: 'da-ban-giao-chi',
      banGiaoChi: { maCase: c.maCase, maHoSo: `HS-CD-2026-${c.maCase.slice(-3)}`, nhanVienId: c.nhanVienId,
        soNgay: c.soNgay ?? 0, soTienDeNghi: c.soTienDuKien, soTienDuyet: c.soTienDuKien,
        thangLan: 'Tháng 08/2026', ngayNop: M05_TODAY, correlationId },
    });
    this.log({ nguoi: this.currentUser, hanhDong: `Bàn giao chi trả sang M07 (${correlationId} — ghi chú 2 chiều)`, caseIds: [id] });
    return { ok: true, correlationId };
  }

  /* ── Dòng rà chênh lệch kỳ (M04-FN-15) — bắt buộc 1/2 đường ra, cả 2 phản hồi ngược M04 ── */

  batDauRa(raId: string): void {
    this.dongRa.update((list) => list.map((r) => (r.id === raId && r.trangThai === 'cho-ra' ? { ...r, trangThai: 'dang-ra' } : r)));
    this.log({ nguoi: this.currentUser, hanhDong: `Bắt đầu rà dòng chênh lệch ${raId}`, caseIds: [] });
  }
  daDieuChinh(raId: string): { ok: boolean; reason?: string } {
    const r = this.dongRa().find((x) => x.id === raId);
    if (!r) return { ok: false, reason: 'Không tìm thấy dòng rà.' };
    this.dongRa.update((list) => list.map((x) => (x.id === raId
      ? { ...x, trangThai: 'da-dieu-chinh', phanHoiM04: `Đã điều chỉnh hồ sơ chế độ — phản hồi ngược M04 item ${x.m04ItemId} (${x.maTuongQuan})` } : x)));
    this.log({ nguoi: this.currentUser, hanhDong: `Đã điều chỉnh hồ sơ chế độ — phản hồi ngược M04 (${r.maTuongQuan})`, caseIds: [] });
    return { ok: true };
  }
  traLoiKhongThuoc(raId: string, lyDo: string): { ok: boolean; reason?: string } {
    if (!lyDo.trim()) return { ok: false, reason: 'Trả lời "không thuộc chế độ" bắt buộc có lý do.' };
    const r = this.dongRa().find((x) => x.id === raId);
    if (!r) return { ok: false, reason: 'Không tìm thấy dòng rà.' };
    this.dongRa.update((list) => list.map((x) => (x.id === raId
      ? { ...x, trangThai: 'da-tra-loi-khong-thuoc', phanHoiM04: `Không thuộc chế độ: ${lyDo.trim()} — phản hồi ngược M04 (${x.maTuongQuan})` } : x)));
    this.log({ nguoi: this.currentUser, hanhDong: `Trả lời "không thuộc chế độ" — phản hồi ngược M04 (${r.maTuongQuan})`, caseIds: [], lyDo: lyDo.trim() });
    return { ok: true };
  }

  /* ── BULK 9 hành động (partial {done, skipped} + retry idempotent — bất biến #4) ── */

  /** Quyền theo hành động (permission m05.md — hiển thị ở modal xác nhận). */
  bulkPermission(action: M05BulkAction): string {
    switch (action) {
      case 'cap-nhat': case 'phan-cong': case 'chuyen-dot': return 'Quyền: quản lý HR';
      case 'thanh-toan': case 'cong-bo': return 'Quyền: kế toán/duyệt';
      case 'xoa': return 'Khóa quyền cao';
      default: return 'Quyền: chuyên viên';
    }
  }

  /** Lý do skip 1 case cho từng hành động — null = đủ điều kiện (dry-run + chạy thật dùng chung). */
  private bulkSkipReason(action: M05BulkAction, c: InsCase): string | null {
    switch (action) {
      case 'yeu-cau': {
        if (c.trangThai === 'dong') return 'Case đã đóng — không gửi yêu cầu bổ sung.';
        return c.checklist.some((k) => k.batBuoc && k.trangThai === 'thieu')
          ? null : 'Không có mục chứng từ bắt buộc thiếu — không gửi yêu cầu.';
      }
      case 'cap-nhat':
        if (c.daCongBo) return 'Đã công bố — chặn sửa/cập nhật trạng thái.';
        if (c.trangThai === 'dong') return 'Case đã đóng — chỉ đọc.';
        return null;
      case 'tinh-lai': return this.tinhLaiReason(c.maCase);
      case 'chuyen-dot':
        if (c.daCongBo) return 'Đã công bố — chặn chuyển đợt.';
        if (!c.loB4) return 'Chưa thuộc lô kê khai nào — không có đợt để chuyển.';
        return null;
      case 'thanh-toan':
        if (c.daCongBo) return 'Đã công bố — chặn thanh toán.';
        if (c.thanhToan) return `Đã có kết quả thanh toán (${c.thanhToan === 'da' ? 'Đã' : 'Không'} thanh toán) — retry không sinh trùng.`;
        if (!c.banGiaoChi) return 'Chưa bàn giao chi trả — thanh toán thực hiện sau bàn giao (M07).';
        return null;
      case 'cong-bo': return this.congBoReason(c.maCase);
      case 'phan-cong':
        return c.trangThai === 'dong' ? 'Case đã đóng — không phân công.' : null;
      case 'ket-xuat': return null;
      case 'xoa': return 'Xóa case = khóa quyền cao — tài khoản demo không có quyền.';
    }
  }

  /** Dry-run cho ins-bulk-bar — KHÔNG đổi state (pure read). */
  bulkPreview(action: M05BulkAction, ids: string[]): { eligible: number; blocked: { reason: string; count: number }[] } {
    const byReason = new Map<string, number>();
    let eligible = 0;
    for (const id of ids) {
      const c = this.caseOf(id);
      const reason = c ? this.bulkSkipReason(action, c) : 'Không tìm thấy case.';
      if (reason === null) eligible++;
      else byReason.set(reason, (byReason.get(reason) ?? 0) + 1);
    }
    return { eligible, blocked: [...byReason].map(([reason, count]) => ({ reason, count })) };
  }

  /** Chạy bulk — thành công một phần; dòng không thỏa bị loại, còn lại chạy; ghi lastBulk cho retry. */
  bulkRun(action: M05BulkAction, ids: string[], opts?: { owner?: string; trangThai?: InsCaseState; congBoKieu?: 'Tháng' | 'Lần'; lyDo?: string })
    : { done: number; skipped: { id: string; reason: string }[] } {
    const skipped: { id: string; reason: string }[] = [];
    const doneIds: string[] = [];
    for (const id of ids) {
      const c = this.caseOf(id);
      if (!c) { skipped.push({ id, reason: 'Không tìm thấy case.' }); continue; }
      const reason = this.bulkSkipReason(action, c);
      if (reason !== null) { skipped.push({ id, reason }); continue; }
      // BQA-8: bulk `cap-nhat` chỉ cho chuyển hợp lệ theo vòng đời (whitelist from → to[]); đích `dong` cấm
      if (action === 'cap-nhat' && opts?.trangThai) {
        const rWl = m05CapNhatReason(c.trangThai, opts.trangThai);
        if (rWl !== null) { skipped.push({ id, reason: rWl }); continue; }
      }
      switch (action) {
        case 'yeu-cau': break; // gửi mail theo 4 mẫu (gốc/đính kèm × hợp lệ/không) CC người yêu cầu — chỉ log
        case 'cap-nhat': if (opts?.trangThai) this.patch(id, { trangThai: opts.trangThai }); break;
        case 'tinh-lai': this.tinhLai(id); break;
        case 'chuyen-dot': this.patch(id, { loB4: c.loB4 ? { ...c.loB4, thangLan: 'Lần — đợt bổ sung 08/2026' } : c.loB4 }); break;
        case 'thanh-toan': this.patch(id, { thanhToan: 'da' }); break;
        case 'cong-bo': this.patch(id, { daCongBo: true, congBoKieu: opts?.congBoKieu ?? 'Tháng', trangThai: 'da-cong-bo' }); break;
        case 'phan-cong': if (opts?.owner) this.patch(id, { owner: opts.owner }); break;
        case 'ket-xuat': break;
        case 'xoa': break;
      }
      doneIds.push(id);
    }
    if (doneIds.length) {
      this.log({
        nguoi: this.currentUser,
        hanhDong: `${M05_BULK_LABEL[action]} ${doneIds.length}/${ids.length} case${opts?.owner ? ` cho ${opts.owner}` : ''}${opts?.congBoKieu ? ` (theo ${opts.congBoKieu})` : ''}${skipped.length ? ` · ${skipped.length} bị loại` : ''}`,
        caseIds: doneIds, lyDo: opts?.lyDo,
      });
    }
    this.lastBulk.set({ action, skipped });
    return { done: doneIds.length, skipped };
  }

  /* ── step-rail B1–B5 của 1 case (status + count + blocker + lockReason — pattern D2) ── */

  buocViewsOf(id: string): InsM05BuocView[] {
    const c = this.caseOf(id);
    if (!c) return [];
    const cur = m05StepOfState(c.trangThai);
    const closed = c.trangThai === 'dong';
    const ckDu = c.checklist.filter((k) => k.trangThai === 'du').length;
    const ckThieu = c.checklist.filter((k) => k.batBuoc && k.trangThai === 'thieu').length;
    const chan = c.viPham.filter((v) => v.mucDo === 'chan' && !v.daOverride).length;

    const b1: InsM05BuocView = {
      key: 1, label: 'B1 · Tiếp nhận',
      status: c.trangThai === 'chua-tiep-nhan' ? 'chua-bat-dau' : cur > 1 ? 'hoan-tat' : 'dang-xu-ly',
      count: `${INS_CASE_NGUON_LABEL[c.nguon]} · ${c.ngayPhatSinh}`,
      blocker: c.trangThai === 'chua-tiep-nhan' ? 'Blocked: case Chưa tiếp nhận — Tiếp nhận lại hoặc Đóng' : null,
      lockReason: null,
    };
    const b2: InsM05BuocView = {
      key: 2, label: 'B2 · Điều kiện & chứng từ',
      status: chan > 0 || ckThieu > 0 ? 'co-loi' : cur > 2 ? 'hoan-tat' : cur === 2 ? 'dang-xu-ly' : 'chua-bat-dau',
      count: `${ckDu}/${c.checklist.length} mục đủ · ${c.taiLieu.length} tài liệu`,
      blocker: ckThieu > 0 ? `Blocked: ${ckThieu} chứng từ bắt buộc thiếu` : chan > 0 ? `Blocked: ${chan} vi phạm mức chặn` : null,
      lockReason: null,
    };
    const b3: InsM05BuocView = {
      key: 3, label: 'B3 · Tính & giải thích',
      status: c.trangThai === 'cho-duyet-override' ? 'dang-xu-ly'
        : c.ketQuaTinh || c.soTienDuKien ? (cur > 3 ? 'hoan-tat' : 'dang-xu-ly') : cur === 3 ? 'dang-xu-ly' : 'chua-bat-dau',
      count: c.soTienDuKien ? `${c.soNgay ?? '—'} ngày · ${c.soTienDuKien}` : 'chưa có kết quả',
      blocker: c.trangThai === 'cho-du-lieu-dong' ? 'Blocked: chờ dữ liệu đóng (exception AC-08)'
        : c.trangThai === 'cho-duyet-override' ? 'Override chờ duyệt (maker ≠ checker)' : null,
      lockReason: cur < 3 && !closed ? `Hoàn tất B2 trước — ${ckThieu > 0 ? `còn ${ckThieu} chứng từ bắt buộc thiếu` : 'điều kiện/chứng từ chưa xong'}.` : null,
    };
    const sangB4 = this.sangB4Reason(id);
    const b4: InsM05BuocView = {
      key: 4, label: 'B4 · Kê khai & nộp',
      status: c.trangThai === 'can-bo-sung' || c.trangThai === 'bi-tu-choi' ? 'co-loi'
        : cur > 4 ? 'hoan-tat' : cur === 4 ? 'dang-xu-ly' : 'chua-bat-dau',
      count: c.loB4 ? `${c.loB4.maLo} · ${c.loB4.lanNop.length} lần nộp` : 'chưa vào lô',
      blocker: c.yeuCauSuaTuM07 ? 'Blocked: M07 yêu cầu sửa/nộp lại' : null,
      // UX-5: fallback phản ánh ĐIỀU KIỆN THẬT — "chưa tính xong" CHỈ khi chưa `da-tinh`;
      // case Đã tính + guard sạch → B4 MỞ (hành động "Đưa vào lô kê khai").
      lockReason: cur < 4 && !closed
        ? (sangB4 ?? (c.trangThai !== 'da-tinh'
            ? `Case chưa tính xong (hiện: ${INS_CASE_STATE_LABEL[c.trangThai]}) — hoàn tất B3 (Tính & giải thích) trước.`
            : null))
        : null,
    };
    const b5: InsM05BuocView = {
      key: 5, label: 'B5 · Kết quả & bàn giao chi',
      status: closed ? 'hoan-tat' : cur === 5 ? 'dang-xu-ly' : 'chua-bat-dau',
      count: c.ketQuaCoQuan ? `${INS_KETQUA_LO_LABEL[c.ketQuaCoQuan]}${c.banGiaoChi ? ' · đã bàn giao chi' : ''}` : 'chưa có kết quả cơ quan',
      blocker: c.banGiaoChi && !c.trangThaiChiM07 ? 'Chờ chi cuối từ M07' : null,
      lockReason: cur < 5 && !closed ? 'Chưa có kết quả từ cơ quan BHXH — hoàn tất nộp hồ sơ (B4) trước.' : null,
    };
    // Case đóng = CHỈ ĐỌC mọi bước nhưng XEM lại tự do
    if (closed) for (const b of [b1, b2, b3, b4, b5]) b.lockReason = null;
    return [b1, b2, b3, b4, b5];
  }
}
