/* ═════════ T1 — Tài liệu ═════════ */

export interface M06RowTaiLieu {
  id: string; ten: string; tep: string; kichThuoc: string; loai: string; doiTuong: string;
  phienBanN: number; hash: string; hashKhop: boolean; nhayCam: boolean; quaHan: boolean; hetHan: string;
  trangThaiLabel: string; trangThaiTone: string; nguon: string; logN: number; tuChoiN: number;
}

export function buildRowTaiLieu(t: InsM06TaiLieu): M06RowTaiLieu {
  const pb = t.phienBan[t.phienBan.length - 1];
  const nv = t.nhanVienId ? insNhanVien(t.nhanVienId) : undefined;
  return {
    id: t.id, ten: t.ten, tep: pb.tep, kichThuoc: pb.kichThuoc, loai: t.loai,
    doiTuong: nv ? `${nv.name} (${nv.code})` : '— chung —',
    phienBanN: t.phienBan.length, hash: pb.hash, hashKhop: pb.hashKhop,
    nhayCam: !!t.nhayCam, quaHan: !!t.quaHan, hetHan: t.hetHan ?? '',
    trangThaiLabel: M06_TAILIEU_LABEL[t.trangThai], trangThaiTone: M06_TAILIEU_TONE[t.trangThai],
    nguon: t.nguon, logN: t.log.length, tuChoiN: t.log.filter((l) => l.biTuChoi).length,
  };
}

