/* ═════════ T2 — Người tham gia ═════════ */

export interface M06RowNguoiTG {
  id: string; nhanVienId: string; ten: string; sub: string; soSo: string; soThe: string; ngayCapThe: string;
  loaiBH: string; nguon: string; trangThaiLabel: string; trangThaiTone: string;
  ngungLyDo: string; dangBiSuaBoi: string;
}

export function buildRowNguoiTG(n: InsM06NguoiThamGia): M06RowNguoiTG {
  const nv = insNhanVien(n.nhanVienId);
  return {
    id: n.id, nhanVienId: n.nhanVienId, ten: nv?.name ?? n.nhanVienId,
    sub: `${nv?.code ?? ''} · ${nv?.dept ?? ''}`, soSo: n.soSo, soThe: n.soThe, ngayCapThe: n.ngayCapThe,
    loaiBH: M06_LOAIBH_LABEL[n.loaiBH], nguon: M06_NGUON_VAO_LABEL[n.nguon],
    trangThaiLabel: n.trangThai === 'hieu-luc' ? 'Hiệu lực' : 'Ngừng hiệu lực',
    trangThaiTone: n.trangThai === 'hieu-luc' ? 'success' : 'neutral',
    ngungLyDo: n.ngungInfo?.lyDo ?? '', dangBiSuaBoi: n.dangBiSuaBoi ?? '',
  };
}

