/* ═════════ T3 — Bộ hồ sơ ═════════ */

export interface M06RowBoHoSo {
  id: string; soHoSo: string; ten: string; thangNam: string; loaiHS: string; phongBan: string;
  thuTuc: string; keKhaiN: number; loiN: number; trangThaiLabel: string; trangThaiTone: string;
  maGD: string; lienThongM05: boolean; gopSo: boolean; ngayMoKe: string;
}

export function buildRowBoHoSo(h: InsM06BoHoSo): M06RowBoHoSo {
  return {
    id: h.id, soHoSo: h.soHoSo, ten: h.ten, thangNam: h.thangNam, loaiHS: h.loaiHS, phongBan: h.phongBan,
    thuTuc: `${h.loaiThuTuc} · ${h.phienBanThuTuc} (tại ngày lập ${h.ngayLap})`,
    keKhaiN: h.nguoiKeKhai.length, loiN: h.nguoiKeKhai.filter((k) => k.ghiChuLoi).length,
    trangThaiLabel: M06_BOHOSO_LABEL[h.trangThai], trangThaiTone: M06_BOHOSO_TONE[h.trangThai],
    maGD: h.maGD ?? '', lienThongM05: !!h.coLienThongM05, gopSo: !!h.gopSoId, ngayMoKe: h.ngayMoCuaSoKe ?? '',
  };
}

