/* ═════════ T4 — Hồ sơ bị từ chối (2 nguồn chung 1 lưới) ═════════ */

export interface M06RowTuChoi {
  id: string; nguon: 'cong-gd' | 'exception-m04'; nguonLabel: string; moTa: string;
  maCell: string; maLoi: string; nhomNguyenNhan: string; chuaPhanLoai: boolean;
  slaLabel: string; slaTone: InsSlaTone; trangThaiLabel: string; trangThaiTone: string;
  owner: string; lichSuN: number; maTuongQuan: string;
}

export function buildRowTuChoi(r: InsM06TuChoi): M06RowTuChoi {
  const sla = r.nguon === 'cong-gd'
    ? insSlaView({ coHan: r.coHan ?? null, ngayHanXuLy: r.hanNopLai ?? '' })
    : { label: 'theo luồng M04', tone: 'muted' as InsSlaTone };
  return {
    id: r.id, nguon: r.nguon, nguonLabel: M06_TUCHOI_NGUON_LABEL[r.nguon], moTa: r.moTa,
    maCell: r.nguon === 'cong-gd' ? `${r.maGD} · lần nộp ${r.lanNop}` : r.maTuongQuan ?? '',
    maLoi: r.maLoi ?? '', nhomNguyenNhan: r.nhomNguyenNhan ?? '',
    chuaPhanLoai: r.nhomNguyenNhan === 'Chưa phân loại',
    slaLabel: sla.label, slaTone: sla.tone,
    trangThaiLabel: M06_TUCHOI_LABEL[r.trangThai], trangThaiTone: M06_TUCHOI_TONE[r.trangThai],
    owner: r.owner ?? '— chưa phân công —', lichSuN: r.lichSu?.length ?? 0, maTuongQuan: r.maTuongQuan ?? '',
  };
}

