import { ChangeDetectionStrategy, Component, input, model } from '@angular/core';
import { InsLayer, InsLayerBadge } from './ins-layer-badge';

/** ins-queue-page — primitive KHUNG MÀN QUEUE dùng chung M02 / M05-A / M06-A(T4) / M07-A.
 *  API chốt tại Phase D1 (M02 là màn chuẩn archetype "Impact-aware Work Queue").
 *
 *  Cấu trúc (flex column, min-height 0 — vùng content tự quản scroll):
 *    header gọn (title row nhỏ — KHÔNG lặp hrm-page-header của shell)
 *    + tab strip (count sống "Báo tăng (12)" + severity phụ "· 3 quá hạn" màu error)
 *    + thanh tổng hợp `summary` (mỗi số tiền kèm ins-layer-badge — bất biến #1)
 *    + slot [qpFilters] (filter strip)  + default content (vùng grid)  + slot [qpBulk] (bulk bar).
 *
 *  Tab strip tự dựng (token-only) thay vì hrm-tabs: hrm-tab chỉ nhận title string nên
 *  không thể hiện severity count màu error trong nhãn tab (yêu cầu IA M02/M05-A).
 *  Zoneless: tabs/summary là array ổn định từ computed phía màn hình. */
export interface InsQueueTab {
  key: string;
  label: string;
  /** Count sống — hiện "(n)"; undefined/null = không hiện. */
  count?: number | null;
  /** Số dòng mức nặng (VD quá hạn) — >0 mới hiện, màu error. */
  severityCount?: number;
  /** Nhãn severity — mặc định 'quá hạn'. */
  severityLabel?: string;
}

export interface InsQueueSummary {
  label: string;
  value: string;
  /** Số tiền → BẮT BUỘC kèm nhãn lớp số liệu (bất biến #1). */
  layer?: InsLayer;
  /** Tô màu số cho chip readiness (P5 — tách happy/exception ngay từ cái nhìn đầu). */
  tone?: 'success' | 'warning' | 'danger';
}

@Component({
  selector: 'ins-queue-page',
  imports: [InsLayerBadge],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <header class="qp__head">
      <div class="qp__titlerow">
        <h2 class="qp__title">{{ title() }}</h2>
        @if (subtitle()) { <span class="qp__subtitle">{{ subtitle() }}</span> }
      </div>
      <nav class="qp__tabs" role="tablist">
        @for (t of tabs(); track t.key) {
          <button type="button" class="qp__tab" role="tab"
            [class.qp__tab--active]="t.key === activeTab()"
            [attr.aria-selected]="t.key === activeTab()"
            (click)="activeTab.set(t.key)">
            <span class="qp__tab-label">{{ t.label }}</span>
            @if (t.count !== undefined && t.count !== null) { <span class="qp__tab-count">({{ t.count }})</span> }
            @if (t.severityCount) { <span class="qp__tab-sev">· {{ t.severityCount }} {{ t.severityLabel || 'quá hạn' }}</span> }
          </button>
        }
      </nav>
    </header>

    @if (summary().length) {
      <div class="qp__summary">
        @for (s of summary(); track s.label; let last = $last) {
          <span class="qp__sum-item">
            <span class="qp__sum-label">{{ s.label }}</span>
            <span class="qp__sum-value" [attr.data-tone]="s.tone || null">{{ s.value }}</span>
            @if (s.layer) { <ins-layer-badge [layer]="s.layer" /> }
          </span>
          @if (!last) { <span class="qp__sum-sep" aria-hidden="true"></span> }
        }
      </div>
    }

    @if (banner()) {
      <div class="qp__banner"><span class="qp__banner-dot" aria-hidden="true"></span><span>{{ banner() }}</span></div>
    }

    <div class="qp__filters"><ng-content select="[qpFilters]" /></div>
    <div class="qp__body"><ng-content /></div>
    <div class="qp__bulk"><ng-content select="[qpBulk]" /></div>
  `,
  host: { class: 'ins-queue-page' },
  styles: [`
    :host { display: flex; flex-direction: column; flex: 1 1 auto; min-height: 0; padding: 0 20px; }

    .qp__head { flex: none; }
    .qp__titlerow { display: flex; align-items: baseline; gap: 10px; padding: 10px 0 6px; min-width: 0; }
    .qp__title { margin: 0; font-size: var(--fs-14); font-weight: 600; color: var(--text-strong); white-space: nowrap; }
    .qp__subtitle { font-size: var(--fs-12); color: var(--text-sub); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

    .qp__tabs { display: flex; gap: 2px; border-bottom: 1px solid var(--border-sub); overflow-x: auto; }
    .qp__tab {
      position: relative; display: inline-flex; align-items: baseline; gap: 5px; flex: none;
      border: 0; background: none; cursor: pointer; padding: 6px 10px 8px;
      font: inherit; font-size: var(--fs-13); color: var(--text-sub);
    }
    .qp__tab:hover { color: var(--text-strong); }
    .qp__tab--active { color: var(--primary-base); font-weight: 600; }
    .qp__tab--active::after {
      content: ''; position: absolute; left: 8px; right: 8px; bottom: -1px; height: 2px;
      background: var(--primary-base); border-radius: var(--radius-full);
    }
    .qp__tab-count { font-size: var(--fs-12); color: var(--text-soft); }
    .qp__tab--active .qp__tab-count { color: var(--primary-base); }
    .qp__tab-sev { font-size: var(--fs-12); font-weight: 600; color: var(--error-base); }

    .qp__summary { flex: none; display: flex; align-items: center; flex-wrap: wrap; gap: 12px; padding: 8px 2px 0; }
    .qp__sum-item { display: inline-flex; align-items: center; gap: 6px; font-size: var(--fs-12); color: var(--text-sub); }
    .qp__sum-value { font-size: var(--fs-13); font-weight: 600; color: var(--text-strong); }
    .qp__sum-value[data-tone="success"] { color: var(--success-base); }
    .qp__sum-value[data-tone="warning"] { color: var(--warning-text); }
    .qp__sum-value[data-tone="danger"] { color: var(--error-base); }
    .qp__sum-sep { width: 1px; height: 14px; background: var(--border-sub); }

    .qp__banner {
      flex: none; display: flex; align-items: center; gap: 8px; margin-top: 8px;
      padding: 7px 12px; background: var(--primary-bg-subtle); border: 1px solid var(--border-sub);
      border-radius: var(--radius-md); font-size: var(--fs-12); color: var(--text-body);
    }
    .qp__banner-dot { flex: none; width: 7px; height: 7px; border-radius: var(--radius-full); background: var(--primary-base); }

    .qp__filters { flex: none; padding: 8px 0 10px; }
    .qp__filters:not(:has(*)) { display: none; }
    .qp__body { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; }
    .qp__bulk { flex: none; padding: 8px 0 10px; }
    .qp__bulk:not(:has(*)) { display: none; }
  `],
})
export class InsQueuePage {
  readonly title = input.required<string>();
  readonly subtitle = input('');
  /** Banner "Hệ thống đã phát hiện N…" (P1 System-detects) — chuỗi sẵn, ẩn khi rỗng. */
  readonly banner = input('');
  readonly tabs = input<InsQueueTab[]>([]);
  /** Tab đang mở — two-way (key của InsQueueTab). */
  readonly activeTab = model<string>('');
  readonly summary = input<InsQueueSummary[]>([]);
}
