import { ChangeDetectionStrategy, Component, TemplateRef, computed, inject, signal, viewChild } from '@angular/core';
import { FormsModule } from '@angular/forms';
import {
  HrmColumnDef, HrmDataWorkspace, HrmMessageService, HrmModalService, HrmRowGroupLevel,
  HrmStatusCell, HrmTag, HrmTextarea, HrmWorkspaceQuickFilter,
} from 'hrm-ui';
import { InsShellStore, insKy } from '../_data/_core';
import {
  INS_LO_KETQUA_LABEL, INS_LO_LABEL, INS_PHANLOAI_LOI_LABEL, InsLoKetQua, InsLoTrangThai,
  InsM03Store, InsPhanLoaiLoi,
} from '../_data/_m03-data';
import { LoRow, buildLoRow } from '../m03-filing/_m03-columns';
import { InsM03LoDetail } from '../m03-filing/m03-lo-detail';
import { InsM03D02Viewer } from '../m03-filing/m03-d02-viewer';

/** Dòng danh sách Màn A = LoRow (buildLoRow) + trường phục vụ nhóm/lọc theo kỳ (KHÔNG format lại trong template). */
type M03bRow = LoRow & {
  ky: string;               // group key (mỗi row PHẢI mang ky để group)
  kyLabel: string;          // "Kỳ 08/2026"
  trangThaiRaw: InsLoTrangThai; // giá trị thô cho quick-filter "Trạng thái lô"
  ketQuaRaw: string;        // '' | InsLoKetQua cho quick-filter "Kết quả tổng hợp"
};

/** Yêu cầu mở modal LÝ DO do child gửi lên host (contract `(reason)=EventEmitter<{mode,id}>`).
 *  6 mode child ins-m03-lo-detail (+ panel/run-zone bên trong) emit: `tra-lai` · `canh-bao` ·
 *  `ket-thuc-som` · `ketqua-loai-tru` · `dongloi-loai-tru` · `doi-nhan-loi` (F1 — đổi nhãn phân loại lỗi).
 *  Host là NƠI DUY NHẤT sở hữu modal lý do.
 *  ⚠️ Với `doi-nhan-loi`, `id` mang NHÃN MỚI ghép: `${itemId}|${nhanMoi}` — host tách để gọi store. */
interface ReasonReq { mode: string; id: string; }

/** ═════════ M03B · HOST — THEO DÕI HỒ SƠ (2-VIEW · danh sách kỳ ⇄ lô) ═════════
 *  Menu MỚI 'm03b' (KHÁC m04 "Theo dõi đóng"). Toàn bộ soát → duyệt → ký → nộp sống ở đây.
 *   • VIEW 'list' (Màn A) = <hrm-data-workspace> liệt kê MỌI lô (store.allLos), gom theo KỲ. Group header
 *     giàu tra từ store.kyAggregates(). 2 quick-filter (Trạng thái lô · Kết quả tổng hợp) + tìm.
 *   • VIEW 'lo' (Màn B) = TÁI DÙNG <ins-m03-lo-detail> toàn trang (KHÔNG viết lại soát/duyệt/ký/nộp).
 *  Host sở hữu: modal LÝ DO dùng chung (6 mode child emit) + <ins-m03-d02-viewer> ("Xem tờ khai").
 *
 *  Navigation contract: constructor đọc `shell.navCtx()` — `filter='lo:<maLo>'` (do modal "Lập tờ khai" ở
 *  m03 đẩy sang) → mở thẳng Màn B của lô đó, đưa ngữ cảnh về kỳ của lô, clear filter.
 *  ⚠️ Zoneless + OnPush + standalone: mọi binding qua computed(); KHÔNG Date.now()/Math.random() ở render. */
@Component({
  selector: 'ins-m03b-page',
  imports: [
    FormsModule,
    HrmDataWorkspace, HrmStatusCell, HrmTag, HrmTextarea,
    InsM03LoDetail, InsM03D02Viewer,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @switch (mode()) {
      @case ('list') {
        <div class="m03b-list">
          <hrm-data-workspace
            [title]="'Theo dõi hồ sơ'" [subtitle]="subtitle()"
            [columns]="cols" [cellTemplates]="$any(cellByKey())"
            [data]="filteredRows()" rowKey="id" tableMinWidth="1120px" [size]="'small'"
            [modes]="['table']"
            [searchPlaceholder]="'Tìm mã lô · tên lô · người lập…'" [search]="kw()" (searchChange)="kw.set($event)"
            [quickFilters]="quickFilters" [quickFilterValues]="qfValues()" (quickFilterValuesChange)="qfValues.set($event)"
            [groupable]="true" [rowGroups]="rowGroups()" (rowGroupsChange)="rowGroups.set($event)"
            [groupLabelFormatter]="groupLabel"
            (rowClick)="openLo($any($event)['id'])" />
          <!-- Footer đếm bản ghi — Màn A GOM THEO KỲ nên KHÔNG dùng pager cắt trang (vỡ group);
               chỉ hiển thị tổng số lô + số kỳ (thay thanh phân trang của template). -->
          <div class="m03b-foot"><b>{{ filteredRows().length }}</b> lô · <b>{{ soKy() }}</b> kỳ</div>
        </div>
      }
      @case ('lo') {
        <ins-m03-lo-detail [loId]="activeLoId()!" (reason)="onReason($event)"
          (openD02)="onOpenD02($event)" (back)="mode.set('list')" (gotoM04)="shell.go('m04')" />
      }
    }

    <!-- ═════ D02-TS viewer (mở từ lo-detail "Xem tờ khai") ═════ -->
    <ins-m03-d02-viewer [open]="d02Open()" (openChange)="d02Open.set($event)" [loId]="d02LoId()" />

    <!-- ═════ Cell templates lưới LÔ ═════ -->
    <ng-template #maLoCell let-row>
      <div class="m03b-stack"><span class="m03b-mono">{{ $any(row).maLo }}</span><span class="m03b-muted">{{ $any(row).soHoSo }}</span></div>
    </ng-template>
    <ng-template #tenLoCell let-row>
      <div class="m03b-stack">
        <span class="m03b-strong">{{ $any(row).tenLo }}</span>
        <span class="m03b-muted">{{ $any(row).phongBan }} · {{ $any(row).maBHXH }}@if ($any(row).loSua) { · <hrm-tag color="purple" size="sm" variant="lighter">Lô sửa · gốc {{ $any(row).maLoGoc }} · lần nộp {{ $any(row).soLanNop }}</hrm-tag>}</span>
      </div>
    </ng-template>
    <ng-template #soItemCell let-row>
      <span class="m03b-strong">{{ $any(row).soItem }}</span>
      @if ($any(row).soLoi) { <span class="m03b-loi"> · {{ $any(row).soLoi }} lỗi</span> }
    </ng-template>
    <ng-template #trangThaiCell let-row>
      <div class="m03b-stack">
        <hrm-status-cell [status]="$any(row).trangThaiTone" [label]="$any(row).trangThaiLabel" variant="badge" />
        @if ($any(row).lyDoTraLai) { <span class="m03b-loi">Bị trả lại: {{ $any(row).lyDoTraLai }}</span> }
      </div>
    </ng-template>
    <ng-template #ketQuaCell let-row>
      @if ($any(row).ketQuaLabel) { <hrm-tag color="orange" size="sm" variant="lighter">{{ $any(row).ketQuaLabel }}</hrm-tag> }
      @else { <span class="m03b-muted">—</span> }
    </ng-template>

    <!-- ═════ Modal LÝ DO dùng chung — mọi hành động bắt buộc-lý-do của child gom về đây ═════ -->
    <ng-template #reasonTpl>
      <div class="m03b-form">
        <p class="m03b-muted">{{ reasonMeta().hint }}</p>
        <hrm-textarea [(ngModel)]="reasonTextModel" placeholder="Nhập lý do (bắt buộc)…" [minRows]="3" [status]="reasonError() ? 'error' : ''" />
        @if (reasonError()) { <span class="m03b-err">{{ reasonError() }}</span> }
      </div>
    </ng-template>
  `,
  host: { class: 'ins-m03b-page' },
  styles: [`
    /* Full-bleed: shell (.ins-body) không padding, và list-page tự lo gutter (.lp-split margin 16px +
       .lp-head full-bleed) → :host KHÔNG thêm gutter (nếu không → double-gutter, header mất full-bleed). */
    :host { display: flex; flex-direction: column; flex: 1 1 auto; min-height: 0; padding: 0; }

    .m03b-list { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; padding: 0; }
    .m03b-list hrm-data-workspace { flex: 1 1 auto; min-height: 0; }
    /* Footer đếm (thay thanh phân trang) — canh mép panel (.lp-split margin 16px), border-top nhẹ. */
    .m03b-foot { flex: none; margin: 0 var(--space-4) var(--space-4); padding: var(--space-2) var(--space-1);
      border-top: 1px solid var(--border-soft); font-size: var(--fs-12); color: var(--text-sub); text-align: right; }
    .m03b-foot b { color: var(--text-strong); font-weight: 600; font-variant-numeric: tabular-nums; }
    /* Màn B (lo-detail) KHÔNG dùng list-page → tự cấp gutter ngang (trước đây do :host 0 20px lo). */
    ins-m03-lo-detail { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; padding: var(--space-3) var(--space-5) var(--space-4); overflow: auto; }

    /* Cell lưới LÔ */
    .m03b-stack { display: flex; flex-direction: column; gap: var(--space-0-5); min-width: 0; align-items: flex-start; }
    :host ::ng-deep .m03b-stack .ant-tag { margin: 0; }
    .m03b-mono { font-family: var(--font-mono, monospace); font-size: var(--fs-12); font-weight: 600; color: var(--text-strong); }
    .m03b-strong { color: var(--text-strong); font-weight: 500; }
    .m03b-muted { font-size: var(--fs-12); color: var(--text-sub); }
    .m03b-loi { font-size: var(--fs-12); font-weight: 600; color: var(--error-text); }

    /* Modal form */
    .m03b-form { display: flex; flex-direction: column; gap: var(--space-2); }
    .m03b-err { font-size: var(--fs-12); color: var(--error-text); }
  `],
})
export class InsM03bPage {
  protected readonly store = inject(InsM03Store);
  protected readonly shell = inject(InsShellStore);
  private readonly msg = inject(HrmMessageService);
  private readonly modal = inject(HrmModalService);

  /* ── 2 VIEW: danh sách kỳ ⇄ lô ── */
  protected readonly mode = signal<'list' | 'lo'>('list');
  protected readonly activeLoId = signal<string | null>(null);

  /* ── Màn A: dòng danh sách (MỌI lô, gom theo kỳ) ── */
  protected readonly rows = computed<M03bRow[]>(() => {
    const items = this.store.items();
    return this.store.allLos().map((lo) => ({
      ...buildLoRow(lo, items),
      ky: lo.ky,
      kyLabel: insKy(lo.ky)?.label ?? lo.ky,
      trangThaiRaw: lo.trangThai,
      ketQuaRaw: lo.ketQuaTongHop ?? '',
    }));
  });

  /** Lọc theo tìm kiếm + 2 quick-filter (Trạng thái lô · Kết quả tổng hợp). */
  protected readonly filteredRows = computed<M03bRow[]>(() => {
    const kw = this.kw().trim().toLowerCase();
    const qf = this.qfValues();
    const tt = qf['trangThai'] ?? [];
    const kq = qf['ketQua'] ?? [];
    return this.rows().filter((r) => {
      if (kw && !`${r.maLo} ${r.tenLo} ${r.nguoiLap} ${r.soHoSo}`.toLowerCase().includes(kw)) return false;
      if (tt.length && !tt.includes(r.trangThaiRaw)) return false;
      if (kq.length && !kq.includes(r.ketQuaRaw)) return false;
      return true;
    });
  });

  /** Subtitle tĩnh — số lô đã hiển thị ở group-header + footer đếm; "gom theo kỳ" hiển nhiên qua group. */
  protected readonly subtitle = signal('Soát – duyệt – ký – nộp hồ sơ theo kỳ');

  /** Số kỳ distinct trong danh sách đã lọc (đếm cho footer — KHÔNG cắt trang). */
  protected readonly soKy = computed(() => new Set(this.filteredRows().map((r) => r.ky)).size);

  /* ── Tìm + 2 quick-filter (state riêng — workspace không tự lọc data) ── */
  protected readonly kw = signal('');
  protected readonly qfValues = signal<Record<string, string[]>>({});
  protected readonly quickFilters: HrmWorkspaceQuickFilter[] = [
    {
      key: 'trangThai', label: 'Trạng thái lô', unit: 'trạng thái',
      options: (Object.keys(INS_LO_LABEL) as InsLoTrangThai[]).map((k) => ({ value: k, label: INS_LO_LABEL[k] })),
    },
    {
      key: 'ketQua', label: 'Kết quả tổng hợp', unit: 'kết quả',
      options: (Object.keys(INS_LO_KETQUA_LABEL) as InsLoKetQua[]).map((k) => ({ value: k, label: INS_LO_KETQUA_LABEL[k] })),
    },
  ];

  /* ── Nhóm dữ liệu: gom theo KỲ (mới nhất trước) ── */
  protected readonly rowGroups = signal<HrmRowGroupLevel[]>([{ key: 'ky', dir: 'desc' }]);

  /** Group header giàu — formatter chỉ nhận (key, value=<kyId>) → TRA store.kyAggregates()[value]. */
  protected readonly groupLabel = (key: string, value: unknown): string => {
    const v = String(value ?? '');
    if (key !== 'ky' || !v) return v || '—';
    const label = insKy(v)?.label ?? v;
    const agg = this.store.kyAggregates()[v];
    if (!agg) return label;
    return `${label} · ${agg.trangThaiKy} · ${agg.soLo} lô · ${agg.tongHoSo} hồ sơ · ${agg.soLoCoKQ} lô có KQ`;
  };

  /* ── Cột (7) + cell templates ── */
  protected readonly cols: HrmColumnDef[] = [
    { key: 'maLo', title: 'Mã lô · số hồ sơ', type: 'text', width: '170px', hideable: false },
    { key: 'tenLo', title: 'Tên lô', type: 'text', width: '260px' },
    { key: 'thamSo', title: 'Biểu mẫu · kênh', type: 'text', width: '160px' },
    { key: 'soItem', title: 'Item', type: 'number', align: 'center', width: '96px' },
    { key: 'trangThai', title: 'Trạng thái lô', type: 'status', width: '190px' },
    { key: 'nguoiLap', title: 'Người lập', type: 'text', width: '150px' },
    { key: 'ketQua', title: 'Kết quả tổng hợp', type: 'text', width: '180px' },
  ];
  private readonly maLoTpl = viewChild.required<TemplateRef<unknown>>('maLoCell');
  private readonly tenLoTpl = viewChild.required<TemplateRef<unknown>>('tenLoCell');
  private readonly soItemTpl = viewChild.required<TemplateRef<unknown>>('soItemCell');
  private readonly trangThaiTpl = viewChild.required<TemplateRef<unknown>>('trangThaiCell');
  private readonly ketQuaTpl = viewChild.required<TemplateRef<unknown>>('ketQuaCell');
  protected readonly cellByKey = computed<Record<string, TemplateRef<unknown>>>(() => ({
    maLo: this.maLoTpl(), tenLo: this.tenLoTpl(), soItem: this.soItemTpl(),
    trangThai: this.trangThaiTpl(), ketQua: this.ketQuaTpl(),
  }));

  constructor() {
    // Navigation contract: {ky, donVi, filter} — diễn giải MỘT lần; filter='lo:<maLo>' → mở thẳng Màn B.
    const ctx = this.shell.navCtx();
    if (ctx.ky && insKy(ctx.ky)) this.store.kyId.set(ctx.ky);
    const f = ctx.filter;
    if (f?.startsWith('lo:')) {
      const loId = f.slice(3);
      if (this.store.lo(loId)) this.openLo(loId);   // đưa ngữ cảnh về kỳ của lô + mở view 'lo'
      this.shell.navCtx.update((c) => ({ ...c, filter: undefined }));
    }
  }

  /* ── Điều hướng 2 view ── */
  /** Mở 1 lô ở view 'lo' (Màn B) — đưa ngữ cảnh toàn màn về kỳ của lô. */
  protected openLo(maLo: string): void {
    const lo = this.store.lo(maLo);
    if (lo && lo.ky !== this.store.kyId()) {
      this.store.kyId.set(lo.ky);
      this.shell.navCtx.update((c) => ({ ...c, ky: lo.ky }));
    }
    this.activeLoId.set(maLo);
    this.mode.set('lo');
  }

  /** lo-detail "Xem tờ khai" → mở D02-TS viewer cho lô đó. */
  protected onOpenD02(loId: string): void { this.d02LoId.set(loId); this.d02Open.set(true); }

  /* ── D02-TS viewer (open + loId — host sở hữu) ── */
  protected readonly d02Open = signal(false);
  protected readonly d02LoId = signal('');

  /* ── Modal LÝ DO dùng chung — host là NƠI DUY NHẤT sở hữu; child chỉ emit (reason)={mode,id} ── */
  private dlg: { close: () => void } | null = null;
  private readonly reasonMode = signal<string>('tra-lai');
  private readonly reasonTarget = signal<string | null>(null);
  private readonly reasonText = signal('');
  protected get reasonTextModel(): unknown { return this.reasonText(); }
  protected set reasonTextModel(v: unknown) { this.reasonText.set(String(v ?? '')); if (String(v ?? '').trim()) this.reasonError.set(''); }
  protected readonly reasonError = signal('');
  private readonly reasonTplRef = viewChild<TemplateRef<unknown>>('reasonTpl');

  /** Metadata theo mode: tiêu đề · gợi ý · nhãn nút xác nhận (khớp child ins-m03-lo-detail đã build). */
  protected readonly reasonMeta = computed<{ title: string; hint: string; ok: string }>(() => {
    switch (this.reasonMode()) {
      case 'tra-lai': return { title: 'Trả lại lô về Nháp', hint: 'Trả lại BẮT BUỘC có lý do — lô về "Bị trả lại (→ Nháp)", người lập sửa lại.', ok: 'Trả lại' };
      case 'canh-bao': return { title: 'Chấp nhận cảnh báo (override)', hint: 'Chấp nhận cảnh báo là override CÓ AUDIT — BẮT BUỘC lý do (ghi người + trước/sau).', ok: 'Chấp nhận' };
      case 'ket-thuc-som': return { title: 'Kết thúc sớm tạm dừng HT-TT', hint: 'Kết thúc sớm — tính lại nghĩa vụ đóng bù toàn khoảng, lý do BẮT BUỘC.', ok: 'Kết thúc sớm' };
      case 'dongloi-loai-tru': return { title: 'Loại trừ dòng lỗi có lý do', hint: 'Loại trừ dòng lỗi lần chạy nền — BẮT BUỘC lý do (ghi nhật ký).', ok: 'Loại trừ' };
      case 'ketqua-loai-tru': return { title: 'Loại trừ dòng kết quả bị từ chối', hint: 'Loại trừ dòng bị cơ quan từ chối khỏi kỳ — BẮT BUỘC lý do.', ok: 'Loại trừ' };
      case 'doi-nhan-loi': return { title: 'Đổi nhãn phân loại lỗi', hint: this.reasonDoiNhanHint(), ok: 'Đổi nhãn' };
      default: return { title: 'Nhập lý do', hint: 'Hành động này bắt buộc có lý do.', ok: 'Xác nhận' };
    }
  });

  /** Tách id ghép của mode 'doi-nhan-loi' → { itemId, nhan }. id = `${itemId}|${nhan}`. */
  private parseDoiNhan(id: string): { itemId: string; nhan: InsPhanLoaiLoi } {
    const sep = id.lastIndexOf('|');
    const itemId = sep >= 0 ? id.slice(0, sep) : id;
    const nhan = (sep >= 0 ? id.slice(sep + 1) : '') as InsPhanLoaiLoi;
    return { itemId, nhan };
  }

  /** Hint mode 'doi-nhan-loi' — kèm nhãn MỚI sắp đổi (tách từ reasonTarget). Pure, an toàn trong computed. */
  private reasonDoiNhanHint(): string {
    const id = this.reasonTarget();
    const nhan = id ? this.parseDoiNhan(id).nhan : undefined;
    const label = nhan && INS_PHANLOAI_LOI_LABEL[nhan] ? INS_PHANLOAI_LOI_LABEL[nhan] : 'nhãn khác';
    return `Đổi sang "${label}" — BẮT BUỘC lý do (ghi người + nhãn trước/sau vào nhật ký).`;
  }

  /** Điểm vào DUY NHẤT cho mọi (reason) của child (lo-detail / panel / run-zone). */
  protected onReason(req: ReasonReq): void {
    this.reasonMode.set(req.mode);
    this.reasonTarget.set(req.id);
    this.reasonText.set(''); this.reasonError.set('');
    const meta = this.reasonMeta();
    this.dlg = this.modal.open({
      title: meta.title, content: this.reasonTplRef()!, width: 460,
      footer: [
        { label: 'Hủy', onClick: () => this.dlg?.close() },
        { label: meta.ok, type: 'primary', onClick: () => this.confirmReason() },
      ],
    });
  }

  private confirmReason(): void {
    const mode = this.reasonMode();
    const id = this.reasonTarget();
    if (!id) { this.dlg?.close(); return; }
    const lyDo = this.reasonText().trim();
    if (!lyDo) { this.reasonError.set('Lý do là bắt buộc.'); return; }

    switch (mode) {
      case 'tra-lai': { const r = this.store.traLai(id, lyDo); this.finishReason(r.ok, r.reason, 'Đã trả lại lô — Bị trả lại (→ Nháp), giữ lý do.'); break; }
      case 'canh-bao': { const r = this.store.chapNhanCanhBao(id, lyDo); this.finishReason(r.ok, r.reason, 'Đã chấp nhận cảnh báo (override có audit).'); break; }
      case 'ket-thuc-som': { const r = this.store.ketThucSomTamDung(id, lyDo); this.finishReason(r.ok, r.reason, 'Đã kết thúc sớm — tính lại nghĩa vụ đóng bù.'); break; }
      case 'dongloi-loai-tru': { const r = this.store.dongLoiLoaiTru(id, lyDo); this.finishReason(r.ok, r.reason, 'Đã loại trừ dòng lỗi có lý do — ghi nhật ký.'); break; }
      // 'ketqua-loai-tru' (dòng kết quả bị từ chối): loại trừ có lý do → ĐÓNG dòng (→ 'da-dong'),
      // kết thúc vòng 5 trạng thái (chặng ⑥ hoàn tất khi mọi dòng từ chối đã đóng).
      case 'ketqua-loai-tru': { const r = this.store.dongPhanLoai(id, lyDo); this.finishReason(r.ok, r.reason, 'Đã loại trừ có lý do — đóng dòng kết quả (ghi nhật ký).'); break; }
      // F1 — đổi nhãn phân loại lỗi: id ghép `${itemId}|${nhan}`, ghi vết (người + nhãn trước/sau + lý do).
      case 'doi-nhan-loi': { const { itemId, nhan } = this.parseDoiNhan(id); const r = this.store.xacNhanPhanLoai(itemId, nhan, lyDo); this.finishReason(r.ok, r.reason, `Đã đổi nhãn phân loại → "${INS_PHANLOAI_LOI_LABEL[nhan]}" (ghi vết người + trước/sau).`); break; }
      default: { this.msg.info('Đã ghi nhận lý do.'); this.dlg?.close(); }
    }
  }
  private finishReason(ok: boolean, reason: string | undefined, okMsg: string): void {
    if (ok) { this.msg.success(okMsg); this.dlg?.close(); }
    else this.msg.error(reason ?? 'Không thực hiện được.');
  }
}
