import { ChangeDetectionStrategy, Component, TemplateRef, computed, inject, signal, viewChild } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { IconSearch } from '@tabler/icons-angular';
import { HrmButton, HrmGrid, HrmGridColumn, HrmInput, HrmMessageService, HrmSelect, HrmTag } from 'hrm-ui';
import { InsSectionLabel } from '../_shared';
import { InsM08Store, M08_TRUYCAP_LOAI_LABEL } from '../_data/_m08-data';

/** M08 ⑧ — NHẬT KÝ TRUY CẬP (FN-17): CHỈ-THÊM; 3 nhóm bắt buộc (xem dữ liệu cá nhân · xuất/tải ·
 *  danh mục + tài liệu y tế); ghi CẢ LẦN BỊ TỪ CHỐI (tag đỏ); ghi phạm vi thấy TẠI THỜI ĐIỂM;
 *  KHÔNG ghi giá trị nhạy cảm (chỉ định danh); lọc theo MỘT TÀI LIỆU (từ M06 sang → filter điền
 *  sẵn); XUẤT NHẬT KÝ CŨNG TỰ GHI 1 dòng; ghi log thất bại → nghiệp vụ vẫn xong + cảnh báo vận
 *  hành; retention theo FN-20. */
@Component({
  selector: 'ins-m08-truycap-page',
  imports: [FormsModule, HrmButton, HrmGrid, HrmInput, HrmSelect, HrmTag, InsSectionLabel],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="a-head">
      <ins-section-label text="Lưới append-only — có cả lần BỊ TỪ CHỐI" tone="muted" [count]="rows().length" />
      <hrm-input class="a-kw" [(ngModel)]="kwModel" size="sm" [prefixIcon]="icSearch" [clearable]="true"
        placeholder="Lọc theo MỘT tài liệu / đối tượng…" />
      <hrm-select class="a-loai" [(ngModel)]="loaiModel" [options]="loaiOptions" size="sm" placeholder="Nhóm hành động" />
      <span class="a-gap"></span>
      <hrm-button size="sm" (click)="xuat()">Xuất nhật ký (tự ghi 1 dòng)</hrm-button>
    </div>
    <p class="a-note">Không ghi GIÁ TRỊ nhạy cảm — chỉ định danh tài liệu/đối tượng · phạm vi = phạm vi thấy TẠI THỜI ĐIỂM
      · trước khi bật tính năng → "không có dữ liệu lịch sử" (không suy diễn ngược).</p>

    <hrm-grid [columns]="cols()" [data]="rows()" rowKey="id" density="compact" minWidth="1080px" [pageSize]="12" />

    <ng-template #ketQuaTpl let-row>
      @if ($any(row).biTuChoi) { <hrm-tag size="sm" color="red">Bị từ chối</hrm-tag> }
      @else { <hrm-tag size="sm" color="green">Thành công</hrm-tag> }
    </ng-template>
  `,
  host: { class: 'ins-m08-truycap-page' },
  styles: [`
    :host { display: flex; flex-direction: column; gap: 10px; }
    .a-head { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
    .a-kw { display: inline-block; width: 280px; }
    .a-loai { display: inline-block; width: 240px; }
    .a-gap { flex: 1; }
    .a-note { margin: 0; font-size: var(--fs-11); color: var(--text-soft); }
  `],
})
export class InsM08TruyCapPage {
  protected readonly store = inject(InsM08Store);
  private readonly msg = inject(HrmMessageService);
  protected readonly icSearch = IconSearch;

  private readonly kw = signal('');
  protected get kwModel(): string { return this.kw(); }
  protected set kwModel(v: string) { this.kw.set(v ?? ''); }
  private readonly loai = signal<string | null>(null);
  protected get loaiModel(): unknown { return this.loai(); }
  protected set loaiModel(v: unknown) { this.loai.set((v as string) || null); }

  protected readonly loaiOptions = (Object.keys(M08_TRUYCAP_LOAI_LABEL) as (keyof typeof M08_TRUYCAP_LOAI_LABEL)[])
    .map((k) => ({ value: k, label: M08_TRUYCAP_LOAI_LABEL[k] }));

  protected readonly rows = computed(() => {
    const kw = this.kw().trim().toLowerCase();
    const loai = this.loai();
    return this.store.nhatKyTruyCap()
      .filter((r) => (!loai || r.loaiHanhDong === loai) && (!kw || `${r.doiTuong} ${r.nguoi}`.toLowerCase().includes(kw)))
      .map((r) => ({
        id: r.id, nguoi: r.nguoi, thoiDiem: r.thoiDiem, phanHe: r.phanHe,
        loai: M08_TRUYCAP_LOAI_LABEL[r.loaiHanhDong], doiTuong: r.doiTuong,
        phamVi: r.phamVi, biTuChoi: r.ketQua === 'bi-tu-choi',
      }));
  });

  private readonly ketQuaTpl = viewChild.required<TemplateRef<unknown>>('ketQuaTpl');
  protected readonly cols = computed<HrmGridColumn[]>(() => [
    { key: 'thoiDiem', title: 'Thời điểm', width: '135px' },
    { key: 'nguoi', title: 'Người', width: '160px' },
    { key: 'phanHe', title: 'Phân hệ', width: '80px' },
    { key: 'loai', title: 'Nhóm hành động', width: '190px' },
    { key: 'doiTuong', title: 'Đối tượng (chỉ định danh — không giá trị nhạy cảm)', width: '330px' },
    { key: 'phamVi', title: 'Phạm vi tại thời điểm', width: '190px' },
    { key: 'ketQua', title: 'Kết quả', width: '110px', cell: this.ketQuaTpl() as HrmGridColumn['cell'] },
  ]);

  protected xuat(): void {
    this.msg.success('Đã xuất nhật ký truy cập — thao tác xuất TỰ GHI thêm 1 dòng append-only (xem dòng AC-02 mẫu).');
  }
}
