import { ChangeDetectionStrategy, Component, inject } from '@angular/core';
import { HrmButton, HrmMessageService, HrmStatusCell, HrmTag } from 'hrm-ui';
import { InsSectionLabel } from '../_shared';
import { InsShellStore, InsModuleKey, InsTone } from '../_data/_core';
import {
  InsM08LanNhac, InsM08Store, M08_LANNHAC_LABEL, M08_LANNHAC_TONE, M08_NHAC_LABEL, M08_NHAC_TONE,
} from '../_data/_m08-data';

/** M08 ⑥ — CẢNH BÁO & NHẮC VIỆC (FN-18): quy tắc ĐỦ 4 THÀNH PHẦN (đối tượng · kênh · lịch ·
 *  người nhận theo vai trò/đích danh); điều kiện trạng thái trống = mọi bản ghi TRỪ Hủy + Từ chối;
 *  gộp dòng cùng người 1 thư + CC; MỖI LẦN GỬI 1 dòng lịch sử (kết quả + lý do); thất bại → retry
 *  theo lịch, KHÔNG im lặng; quá ngưỡng → LEO THANG có log; deep-link đúng dòng việc (thiếu quyền
 *  → về danh sách trong phạm vi); không vượt khóa phân quyền. */
@Component({
  selector: 'ins-m08-nhac-page',
  imports: [HrmButton, HrmStatusCell, HrmTag, InsSectionLabel],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <ins-section-label text="Quy tắc nhắc — đủ 4 thành phần" tone="muted" [count]="store.quyTacNhac().length" />
    @for (q of store.quyTacNhac(); track q.id) {
      <div class="w-rule">
        <div class="w-rule__head">
          <span class="w-mono">{{ q.id }}</span>
          <hrm-status-cell [status]="tone(q.trangThai)" [label]="label(q.trangThai)" variant="badge" />
          @if (q.gopThu) { <hrm-tag size="sm" color="teal">Gộp 1 thư + CC theo người nhận</hrm-tag> }
        </div>
        <div class="w-4tp">
          <span><b>① Đối tượng:</b> {{ q.doiTuong }}</span>
          <span><b>② Kênh:</b> {{ q.kenh }}</span>
          <span><b>③ Lịch:</b> {{ q.lich }}</span>
          <span><b>④ Người nhận:</b> {{ q.nguoiNhan }}</span>
        </div>
        <p class="w-muted">Điều kiện trạng thái: {{ q.dieuKienTrangThai || 'TRỐNG = mọi bản ghi TRỪ Hủy + Từ chối' }}
          · Leo thang: {{ q.nguongLeoThang }}</p>
      </div>
    }

    <ins-section-label text="Lịch sử gửi — mỗi lần gửi 1 dòng (kết quả + lý do)" tone="attention" [count]="store.lanNhac().length" />
    @for (l of store.lanNhac(); track l.id) {
      <div class="w-lan">
        <span class="w-mono">{{ l.id }}</span>
        <span class="w-muted">{{ l.at }} · {{ l.quyTacId }} · gửi {{ l.nguoiNhan }}</span>
        <hrm-status-cell [status]="lanTone(l)" [label]="lanLabel(l)" variant="badge" />
        @if (l.lyDo) { <span class="w-muted">{{ l.lyDo }}</span> }
        <span class="w-gap"></span>
        <hrm-button size="sm" (click)="moDeepLink(l)">Deep-link: {{ l.deepLink.nhan }}</hrm-button>
      </div>
    }
    <p class="w-note">Gửi thất bại → retry theo lịch (không im lặng) · quá ngưỡng không phản hồi → leo thang CÓ LOG ·
      deep-link thiếu quyền → đưa về danh sách trong phạm vi, có thông báo.</p>
  `,
  host: { class: 'ins-m08-nhac-page' },
  styles: [`
    :host { display: flex; flex-direction: column; gap: 10px; }
    .w-rule { border: 1px solid var(--border-sub); border-radius: var(--radius-md); background: var(--bg-surface); padding: 9px 12px; display: flex; flex-direction: column; gap: 6px; }
    .w-rule__head { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
    .w-4tp { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 4px 16px; font-size: var(--fs-12); color: var(--text-body); }
    .w-4tp b { color: var(--text-strong); }
    .w-mono { font-family: var(--font-mono, monospace); font-size: var(--fs-12); font-weight: 700; color: var(--text-strong); }
    .w-muted { font-size: var(--fs-12); color: var(--text-sub); margin: 0; }
    .w-lan { display: flex; align-items: center; gap: 9px; flex-wrap: wrap; border: 1px solid var(--border-sub); border-radius: var(--radius-md); padding: 6px 10px; }
    .w-gap { flex: 1; }
    .w-note { margin: 0; font-size: var(--fs-11); color: var(--text-soft); }
  `],
})
export class InsM08NhacPage {
  protected readonly store = inject(InsM08Store);
  private readonly shell = inject(InsShellStore);
  private readonly msg = inject(HrmMessageService);

  protected label(s: keyof typeof M08_NHAC_LABEL): string { return M08_NHAC_LABEL[s]; }
  protected tone(s: keyof typeof M08_NHAC_TONE): InsTone { return M08_NHAC_TONE[s]; }
  protected lanLabel(l: InsM08LanNhac): string { return M08_LANNHAC_LABEL[l.ketQua]; }
  protected lanTone(l: InsM08LanNhac): InsTone { return M08_LANNHAC_TONE[l.ketQua]; }

  /** Deep-link đúng dòng việc — điều hướng chéo module mang {ky, donVi, filter} (navigation contract). */
  protected moDeepLink(l: InsM08LanNhac): void {
    this.shell.go(l.deepLink.module as InsModuleKey, l.deepLink.filter ? { filter: l.deepLink.filter } : undefined);
    this.msg.info(`Deep-link ${l.deepLink.nhan} — thiếu quyền sẽ về danh sách trong phạm vi (demo đủ quyền).`);
  }
}
