import { ChangeDetectionStrategy, Component, TemplateRef, computed, inject, signal, viewChild } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { IconAlertTriangle, IconChevronDown, IconChevronRight, IconChevronUp, IconFilePlus, IconRefresh } from '@tabler/icons-angular';
import { TablerIconComponent } from '@tabler/icons-angular';
import { HrmButton, HrmCheckbox, HrmGrid, HrmGridColumn, HrmMessageService, HrmModalService, HrmOption, HrmRadioGroup, HrmSegmented, HrmSelect } from 'hrm-ui';
import { InsDiff, InsLayerBadge } from '../_shared';
import { INS_KY, InsShellStore, insKy, insNhanVien } from '../_data/_core';
import {
  INS_LO_LABEL, INS_LOAI_KY_LABEL, INS_NHOM_LABEL, INS_NHOM_THUTUC, INS_NHOM_TONE, InsLoaiKyKeKhai,
  InsLoItem, InsM03Store, InsNhomKeKhai,
} from '../_data/_m03-data';
import { A07_D02LT_NOTE, M03_WORKSPACE_COLS, M03_WORKSPACE_MIN_WIDTH, WsRow, buildWsRow } from './_m03-columns';

/* ─── Guard text (mirror _m03-columns GUARD5/GUARD7 — dry-run "Lập tờ khai" đồng bộ với store) ─── */
const GUARD5 = 'Dòng truy thu/thoái thu thiếu D01-TS — bị chặn khỏi lô (điểm dừng ⑤).';
const GUARD7 = 'Thiếu mã phương án hiệu lực theo kỳ — bị chặn khỏi lô (điểm dừng ⑦).';
const TRUNG_NLD = 'Một NLĐ không ở hai lô chưa nộp cùng kỳ + loại thủ tục.';
/** Lô "chưa nộp" (còn sửa được) — mirror LO_CHUA_NOP store (không export) cho check trùng NLĐ. */
const LO_CHUA_NOP = new Set<string>(['nhap', 'bi-tra-lai', 'dang-kiem-tra', 'cho-duyet', 'da-duyet', 'da-ky']);
/** Thứ tự nhóm cố định (layoutCues): 3 nhóm kê khai trước, ⚪ Đang tham gia (đối chiếu) cuối. */
const NHOM_ORDER: InsNhomKeKhai[] = ['bao-tang', 'bao-giam', 'dieu-chinh', 'dang-tham-gia'];

/* ── tiền VN: chuỗi "26.000.000" ⇄ number (thuần, deterministic — dùng trong computed). ── */
function parseMoney(s: string): number {
  const n = Number((s ?? '').replace(/[^\d-]/g, ''));
  return Number.isFinite(n) ? n : 0;
}
function fmtMoney(n: number): string {
  return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
}
/** Format Date → 'dd/MM HH:mm' — CHỈ gọi trong click handler (zoneless: không dùng trong computed). */
function stampNow(): string {
  const d = new Date();
  const p = (x: number) => String(x).padStart(2, '0');
  return `${p(d.getDate())}/${p(d.getMonth() + 1)} ${p(d.getHours())}:${p(d.getMinutes())}`;
}

/** Row VM mở rộng cho workspace: WsRow + mức đóng cũ→mới (InsDiff cho điều chỉnh) + skip filing (store-accurate). */
interface WsRowExt extends WsRow {
  nhanVienId: string;
  mucMoi: string;               // lương căn cứ mới | 'không tính được'
  mucCu: string;                // lương đang đóng (nv.salary) — chỉ nhóm điều chỉnh, để dựng cũ→mới
  canhBao: boolean;             // dòng còn cảnh báo (thiếu PA/D01-TS/mã BHXH/lương)
  skipFiling: string;           // lý do bị bỏ qua khi "Lập tờ khai" ('' = lập được) — mirror store guards
}

interface WsGroup {
  nhom: InsNhomKeKhai;
  label: string;
  tone: string;
  thuTuc: string;
  keKhai: boolean;              // 3 nhóm kê khai có ô chọn + cộng tổng; ⚪ Đang tham gia = false
  rows: WsRowExt[];
  count: number;
  tongLuong: string;            // tổng lương căn cứ nhóm (chuỗi) — '' cho ⚪
}

/** ═════════ M03 · SC-B1 — WORKSPACE LẬP TỜ KHAI (component sở hữu TRỌN header SC-B1) ═════════
 *  Nguồn: JOB B `SC-B1-workspace-lap-to-khai.md` (jobb_b1) + `_m03-data` store (frozen).
 *  Header (component tự dựng — host KHÔNG còn thanh Kỳ/tóm tắt):
 *   ① Kỳ selector (hrm-select · store.kyId) + 'Cập nhật lúc dd/mm hh:mm' + nút '↻ Cập nhật mức đóng'.
 *   ② Sub-tabs LOẠI KỲ = segmented (Kỳ hiện tại / Kỳ tháng tới / Đợt điều chỉnh · store.loaiKy) +
 *      '⚠ N dòng còn cảnh báo'. ③ TÓM TẮT 1 dòng: 'Quỹ lương X · Số phải đóng dự kiến Chờ tính' (du-kien).
 *  Lưới GOM 4 NHÓM ứng viên (store.candidatesByNhom) COLLAPSIBLE, 6 cột cố định (Chọn · NLĐ+mã BHXH ·
 *  Mã phương án · Mức đóng[cũ→mới điều chỉnh] · Quỹ · Số phải đóng); ⚪ Đang tham gia = đối chiếu (thu
 *  gọn mặc định, KHÔNG tick/KHÔNG cộng). Thanh đáy: đếm + dry-run 'N vào · M bỏ qua vì…' + 'Lập tờ khai
 *  (tự lên 600/600a/600b)' → MỞ MODAL chooser lô (lô chưa nộp gần nhất / lô mới) + 2 nút Lưu nháp/Nộp
 *  hồ sơ; sau khi thêm dòng vào lô → tự điều hướng m03b "Theo dõi hồ sơ". Ranh giới: "Số phải đóng" = 4 tầng KHÔNG lưu trên
 *  dòng (Q38) → 'Chờ tính' (KHÔNG bịa số); A-07 (tin cậy Thấp) D02-LT chờ QĐ 366/QĐ-BHXH. */
@Component({
  selector: 'ins-m03-workspace',
  imports: [FormsModule, TablerIconComponent, HrmButton, HrmCheckbox, HrmGrid, HrmRadioGroup, HrmSegmented, HrmSelect, InsDiff, InsLayerBadge],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <!-- ═════ A-07 (chặn pháp lý, tin cậy Thấp) — chip nhỏ, đầu màn ═════ -->
    <div class="ws-a07row">
      <span class="ws-a07" [title]="a07Note"><tabler-icon [icon]="icWarn" [size]="12" /> A-07 · Cột D02-LT: chờ đối chiếu QĐ 366/QĐ-BHXH</span>
    </div>

    <!-- ═════ Header ① — Kê khai BHXH · Kỳ selector | Cập nhật lúc + nút Cập nhật mức đóng ═════ -->
    <div class="ws-hdr">
      <div class="ws-hdr__left">
        <label class="ws-hdr__ky">Kỳ
          <hrm-select class="ws-hdr__kysel" [ngModel]="selectedKy()" [options]="kyOptions" size="sm"
            [allowClear]="false" [showSearch]="false" (ngModelChange)="onKyChange($event)" />
        </label>
      </div>
      <div class="ws-hdr__right">
        <span class="ws-hdr__at">Cập nhật lúc <b>{{ capNhatLuc() }}</b></span>
        <hrm-button size="sm" variant="secondary" [disabled]="locked()" (click)="capNhatMucDong()">
          <tabler-icon [icon]="icRefresh" [size]="15" /> Cập nhật mức đóng</hrm-button>
      </div>
    </div>

    <!-- ═════ Header ② — Loại kỳ (segmented) | ⚠ N dòng còn cảnh báo ═════ -->
    <div class="ws-subtabs">
      <hrm-segmented [ngModel]="loaiKy()" [options]="loaiKyOptions" size="sm" (ngModelChange)="onLoaiKyChange($event)" />
      <span class="ws-gap"></span>
      @if (soCanhBao() > 0) {
        <span class="ws-warnpill"><tabler-icon [icon]="icWarn" [size]="13" /> {{ soCanhBao() }} dòng còn cảnh báo</span>
      } @else {
        <span class="ws-okpill">Không còn dòng cảnh báo trong kỳ.</span>
      }
    </div>

    <!-- ═════ Header ③ — TÓM TẮT 1 dòng (dự kiến; số phải đóng giữ 'Chờ tính', không bịa) ═════ -->
    <div class="ws-tomtat">
      <span class="ws-tomtat__lb">Tóm tắt</span>
      <span class="ws-tomtat__body">Quỹ lương <b>{{ tongQuyLuong() }}</b>
        <span class="ws-sep">·</span> Số phải đóng dự kiến <b class="ws-pending2">Chờ tính</b>
        <ins-layer-badge layer="du-kien" /></span>
      <span class="ws-tomtat__note">Số 4 tầng (Q38 tham số mẫu) — chốt khi lập tờ khai.</span>
    </div>

    <!-- ═════ Chọn tất cả (chỉ 3 nhóm kê khai) — ngay trên lưới ═════ -->
    <div class="ws-selall">
      <hrm-checkbox [ngModel]="allChecked()" [indeterminate]="someChecked()"
        [disabled]="locked() || selectableIds().length === 0" (ngModelChange)="toggleAll($event)">Chọn tất cả</hrm-checkbox>
      <span class="ws-muted">{{ selectableIds().length }} dòng kê khai · ⚪ đối chiếu không tính</span>
    </div>

    <!-- ═════ Lưới gom 4 nhóm — 1 vùng cuộn ngang chung, mỗi nhóm THU/MỞ ═════ -->
    <div class="ws-scroll">
      <div class="ws-groups" [style.minWidth]="wsMinWidth">
        @for (g of groups(); track g.nhom) {
          <section class="ws-grp">
            <button type="button" class="ws-grp__head" (click)="toggleGroup(g.nhom)">
              <tabler-icon class="ws-grp__chev" [icon]="isOpen(g.nhom) ? icDown : icRight" [size]="16" />
              <span class="ws-dot" [attr.data-tone]="g.tone"></span>
              <span class="ws-grp__name">{{ g.label }}</span>
              <span class="ws-grp__count">({{ g.count }})</span>
              @if (g.keKhai) { <span class="ws-grp__ma">thủ tục {{ g.thuTuc }}</span> }
              @else { <span class="ws-grp__ref">— tham chiếu, không kê khai</span> }
              @if (g.keKhai && g.tongLuong) {
                <span class="ws-grp__sum">Quỹ lương {{ g.tongLuong }} <span class="ws-muted">· Số phải đóng: Chờ tính</span></span>
              }
            </button>
            @if (isOpen(g.nhom)) {
              @if (g.rows.length) {
                <hrm-grid [columns]="cols()" [data]="g.rows" rowKey="id" density="compact"
                  [showPagination]="false" dividers="rows" />
              } @else {
                <p class="ws-empty">Không có dòng trong nhóm này ở kỳ đang chọn.</p>
              }
            }
          </section>
        }
      </div>
    </div>

    <!-- ═════ Thanh đáy — Đã chọn N + dry-run + Lập tờ khai (tự lên 600/600a/600b) ═════ -->
    <div class="ws-bottom">
      <span class="ws-bottom__count">Đã chọn <b>{{ selectedCount() }}</b> / {{ selectableIds().length }} dòng</span>
      @if (selectedCount() > 0) {
        <span class="ws-bottom__dry"><b class="ws-ok">{{ dryRun().eligible }}</b> vào
          @if (dryRun().blockedTotal > 0) { <span class="ws-sep">·</span> <b class="ws-bad">{{ dryRun().blockedTotal }}</b> bỏ qua }
          @if (dryRun().blocked.length > 0) {
            <button type="button" class="ws-why-btn" (click)="toggleWhy()">{{ whyOpen() ? 'Ẩn lý do' : 'Xem lý do' }}
              <tabler-icon [icon]="whyOpen() ? icUp : icDown" [size]="12" /></button>
          }
        </span>
      }
      <span class="ws-gap"></span>
      <div class="ws-lap">
        @if (lapReason(); as r) { <span class="ws-lap__reason">{{ r }}</span> }
        @else { <span class="ws-lap__hint">{{ dryRun().eligible }} dòng vào tờ khai · {{ dryRun().blockedTotal }} bỏ qua → SC-B2</span> }
        <hrm-button variant="primary" [disabled]="!!lapReason()" (click)="lapToKhai()">
          <tabler-icon [icon]="icFile" [size]="16" /> Lập tờ khai (tự lên 600/600a/600b)</hrm-button>
      </div>
    </div>
    @if (whyOpen() && dryRun().blocked.length > 0) {
      <div class="ws-why">
        @for (b of dryRun().blocked; track b.reason) {
          <div class="ws-why__row"><span class="ws-why__n">{{ b.count }}</span><span>{{ b.reason }}</span></div>
        }
      </div>
    }

    <!-- ═════ Modal LẬP TỜ KHAI — chooser lô (lô chưa nộp gần nhất / lô mới) + tóm tắt dòng ═════ -->
    <ng-template #lapTpl>
      <div class="ws-lapm">
        <p class="ws-lapm__q">Đưa <b class="ws-ok">{{ dryRun().eligible }}</b> dòng đã chọn vào tờ khai của lô nào?</p>
        <hrm-radio-group [ngModel]="loChon()" [options]="loChonOptions()" (ngModelChange)="onLoChonChange($event)" />
        <div class="ws-lapm__sum">
          <b class="ws-ok">{{ dryRun().eligible }}</b> dòng vào tờ khai
          @if (dryRun().blockedTotal > 0) { <span class="ws-sep">·</span> <b class="ws-bad">{{ dryRun().blockedTotal }}</b> bỏ qua }
        </div>
        <p class="ws-lapm__note">Lưu nháp = lô ở trạng thái Nháp. Nộp hồ sơ = trình duyệt (Chờ duyệt); nếu còn dòng chưa hợp lệ, lô giữ Nháp và báo lý do.</p>
      </div>
    </ng-template>

    <!-- ═════ Cell templates (6 cột SC-B1) ═════ -->
    <ng-template #chonCell let-row>
      @if ($any(row).selectable) {
        <hrm-checkbox [ngModel]="isSel($any(row).id)" [disabled]="locked()" (ngModelChange)="toggle($any(row).id)" />
      }
    </ng-template>

    <ng-template #nldCell let-row>
      <div class="ws-nld" [title]="$any(row).suKien">
        <span class="ws-nld__name">{{ $any(row).ten }}</span>
        <span class="ws-muted">{{ $any(row).sub }}</span>
        @if ($any(row).thieuMaBHXH) {
          <span class="ws-warn" [title]="$any(row).thieuMaBHXHNote"><tabler-icon [icon]="icWarn" [size]="12" /> Thiếu mã số BHXH — cần TK1-TS</span>
        } @else {
          <span class="ws-muted">Mã số BHXH {{ $any(row).insCode }}</span>
        }
      </div>
    </ng-template>

    <ng-template #paCell let-row>
      @if ($any(row).paText) {
        <div class="ws-nld">
          <span>{{ $any(row).paText }}</span>
          @if ($any(row).cd) { <span class="ws-cd">không ảnh hưởng số đóng</span> }
        </div>
      } @else {
        <span class="ws-warn" [title]="$any(row).paMissingNote"><tabler-icon [icon]="icWarn" [size]="12" /> Thiếu mã phương án (⑦)</span>
      }
    </ng-template>

    <ng-template #mucCell let-row>
      @if ($any(row).thieuLuong) { <span class="ws-warn">không tính được</span> }
      @else if ($any(row).mucCu && $any(row).mucCu !== $any(row).mucMoi) {
        <ins-diff [before]="$any(row).mucCu" [after]="$any(row).mucMoi" />
      } @else { <span class="ws-num">{{ $any(row).mucMoi }}</span> }
    </ng-template>

    <ng-template #quyCell let-row>
      @if ($any(row).cd) { <span class="ws-muted">không cộng</span> }
      @else if ($any(row).quy) {
        <span class="ws-quy">{{ $any(row).quy }} @if ($any(row).quyMau) { <span class="ws-quy__mau" title="Tổ hợp quỹ theo 6 tổ hợp mẫu D02-TS — chuẩn cứng cơ quan">mẫu D02-TS</span> }</span>
      } @else { <span class="ws-muted">—</span> }
    </ng-template>

    <ng-template #spdCell let-row>
      <div class="ws-nld ws-nld--right">
        @if ($any(row).thieuLuong) { <span class="ws-warn">không tính được</span> }
        @else { <span class="ws-pending">{{ $any(row).soPhaiDong }}</span> }
        @if ($any(row).truyThuLabel) { <span class="ws-muted">{{ $any(row).truyThuLabel }}</span> }
        @if ($any(row).thieuD01TS) {
          <span class="ws-warn" [title]="$any(row).d01tsNote"><tabler-icon [icon]="icWarn" [size]="12" /> Thiếu D01-TS (⑤)</span>
        }
      </div>
    </ng-template>
  `,
  host: { class: 'ins-m03-workspace' },
  styles: [`
    :host { display: flex; flex-direction: column; gap: 10px; min-width: 0; }
    tabler-icon { display: inline-flex; align-items: center; flex: none; }
    .ws-gap { flex: 1; }
    .ws-sep { color: var(--text-soft); }
    .ws-muted { font-size: var(--fs-12); color: var(--text-sub); }
    .ws-num { font-variant-numeric: tabular-nums; font-weight: 600; color: var(--text-strong); }

    /* A-07 chip (nhỏ, đầu màn) */
    .ws-a07row { display: flex; }
    .ws-a07 { display: inline-flex; align-items: center; gap: 5px; font-size: var(--fs-11); font-weight: 500;
      color: var(--warning-text); background: var(--warning-bg); border: 1px dashed var(--warning-base, var(--warning-text));
      border-radius: var(--radius-full); padding: 1px 9px; cursor: help; }

    /* Header ① — tiêu đề + Kỳ selector | cập nhật lúc + nút */
    .ws-hdr { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
    .ws-hdr__left { display: flex; align-items: center; gap: 12px; min-width: 0; }
    .ws-hdr__title { font-size: var(--fs-16); font-weight: 700; color: var(--text-strong); }
    .ws-hdr__ky { display: inline-flex; align-items: center; gap: 6px; font-size: var(--fs-13); color: var(--text-sub); }
    .ws-hdr__kysel { width: 148px; }
    .ws-hdr__right { display: flex; align-items: center; gap: 10px; margin-left: auto; }
    .ws-hdr__at { font-size: var(--fs-12); color: var(--text-sub); }
    .ws-hdr__at b { color: var(--text-body); font-variant-numeric: tabular-nums; }

    /* Header ② — segmented loại kỳ + cảnh báo */
    .ws-subtabs { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
    .ws-warnpill { display: inline-flex; align-items: center; gap: 4px; font-size: var(--fs-12); font-weight: 600;
      color: var(--warning-text); background: var(--warning-bg); border-radius: var(--radius-full); padding: 1px 10px; }
    .ws-okpill { font-size: var(--fs-12); color: var(--success-text); }

    /* Header ③ — TÓM TẮT 1 dòng */
    .ws-tomtat { display: flex; align-items: center; gap: 10px; flex-wrap: wrap;
      border: 1px solid var(--border-soft); border-radius: var(--radius-md); background: var(--bg-surface-subtle); padding: 8px 12px; }
    .ws-tomtat__lb { font-size: var(--fs-11); font-weight: 700; text-transform: uppercase; letter-spacing: .04em; color: var(--text-soft); }
    .ws-tomtat__body { display: inline-flex; align-items: center; gap: 6px; font-size: var(--fs-13); color: var(--text-body); }
    .ws-tomtat__body b { color: var(--text-strong); font-variant-numeric: tabular-nums; }
    .ws-pending2 { color: var(--text-sub) !important; font-style: italic; font-weight: 500 !important; }
    .ws-tomtat__note { font-size: var(--fs-11); color: var(--text-soft); margin-left: auto; }

    /* Chọn tất cả */
    .ws-selall { display: flex; align-items: center; gap: 10px; padding: 2px 2px 0; }

    /* Lưới gom nhóm — 1 vùng cuộn ngang chung */
    .ws-scroll { overflow-x: auto; }
    .ws-groups { display: flex; flex-direction: column; gap: 12px; }
    /* Vùng cuộn chung: TẮT cuộn ngang nội bộ mỗi hrm-grid → 6 cột thẳng hàng giữa các nhóm. */
    .ws-scroll ::ng-deep .ant-table-content, .ws-scroll ::ng-deep .ant-table-body { overflow-x: visible !important; }

    .ws-grp { display: flex; flex-direction: column; gap: 6px; }
    .ws-grp__head { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; width: 100%; text-align: left;
      border: 0; background: none; font: inherit; cursor: pointer; padding: 3px 2px 6px; border-bottom: 1px solid var(--border-soft); }
    .ws-grp__chev { color: var(--text-soft); }
    .ws-dot { flex: none; width: 10px; height: 10px; border-radius: var(--radius-full); background: var(--text-soft); }
    .ws-dot[data-tone='success'] { background: var(--success-base); }
    .ws-dot[data-tone='error'] { background: var(--error-base); }
    .ws-dot[data-tone='info'] { background: var(--info-text, var(--primary-base)); }
    .ws-dot[data-tone='neutral'] { background: var(--text-soft); }
    .ws-grp__name { font-size: var(--fs-13); font-weight: 700; text-transform: uppercase; letter-spacing: .02em; color: var(--text-strong); }
    .ws-grp__count { font-size: var(--fs-12); color: var(--text-sub); font-variant-numeric: tabular-nums; }
    .ws-grp__ma { font-size: var(--fs-12); font-weight: 700; color: var(--primary-base); background: var(--primary-bg-subtle); border-radius: var(--radius-sm); padding: 0 7px; }
    .ws-grp__ref { font-size: var(--fs-11); color: var(--text-soft); }
    .ws-grp__sum { font-size: var(--fs-12); color: var(--text-body); font-weight: 500; margin-left: auto; }
    .ws-empty { margin: 6px 0; font-size: var(--fs-12); color: var(--text-soft); }

    /* Cell nội dung */
    .ws-nld { display: flex; flex-direction: column; gap: 1px; min-width: 0; align-items: flex-start; }
    .ws-nld--right { align-items: flex-end; }
    .ws-nld__name { color: var(--text-strong); font-weight: 500; }
    .ws-warn { display: inline-flex; align-items: center; gap: 3px; font-size: var(--fs-11); color: var(--warning-text); font-weight: 500; }
    .ws-cd { font-size: var(--fs-11); color: var(--text-soft); background: var(--bg-surface-subtle); border-radius: var(--radius-sm); padding: 0 6px; }
    .ws-quy { font-size: var(--fs-12); color: var(--text-body); }
    .ws-quy__mau { font-size: var(--fs-10); color: var(--info-text); background: var(--info-bg); border-radius: var(--radius-sm); padding: 0 5px; }
    .ws-pending { font-size: var(--fs-12); color: var(--text-sub); font-style: italic; }

    /* Thanh đáy + dry-run */
    .ws-bottom { position: sticky; bottom: 0; z-index: 4; display: flex; align-items: center; gap: 14px; flex-wrap: wrap;
      border: 1px solid var(--border-sub); border-radius: var(--radius-lg); background: var(--bg-surface);
      box-shadow: var(--shadow-regular-sm); padding: 10px 14px; }
    .ws-bottom__count { font-size: var(--fs-13); color: var(--text-sub); }
    .ws-bottom__count b { color: var(--text-strong); font-weight: 600; }
    .ws-bottom__dry { font-size: var(--fs-13); color: var(--text-sub); display: inline-flex; align-items: center; gap: 4px; }
    .ws-ok { color: var(--success-base); }
    .ws-bad { color: var(--error-base); }
    .ws-why-btn { display: inline-flex; align-items: center; gap: 3px; border: 0; background: none; padding: 0 0 0 4px; cursor: pointer; font: inherit;
      font-size: var(--fs-12); font-weight: 600; color: var(--primary-base); }
    .ws-lap { display: flex; align-items: center; gap: 10px; }
    .ws-lap__reason { font-size: var(--fs-12); color: var(--warning-text); max-width: 320px; }
    .ws-lap__hint { font-size: var(--fs-12); color: var(--text-sub); }
    .ws-why { display: flex; flex-direction: column; gap: 6px; border: 1px solid var(--border-soft); border-radius: var(--radius-md);
      background: var(--bg-surface-subtle); padding: 10px 12px; }
    .ws-why__row { display: flex; align-items: baseline; gap: 8px; font-size: var(--fs-12); color: var(--text-sub); }
    .ws-why__n { flex: none; min-width: 20px; text-align: center; font-weight: 600; color: var(--error-text);
      background: var(--error-bg); border-radius: var(--radius-full); padding: 0 6px; }

    /* Modal Lập tờ khai — chooser lô + tóm tắt */
    .ws-lapm { display: flex; flex-direction: column; gap: 12px; }
    .ws-lapm__q { margin: 0; font-size: var(--fs-13); color: var(--text-body); }
    .ws-lapm__q b { font-variant-numeric: tabular-nums; }
    .ws-lapm__sum { font-size: var(--fs-13); color: var(--text-sub); display: inline-flex; align-items: center; gap: 6px;
      border: 1px solid var(--border-soft); border-radius: var(--radius-md); background: var(--bg-surface-subtle); padding: 8px 12px; }
    .ws-lapm__note { margin: 0; font-size: var(--fs-11); color: var(--text-soft); }
  `],
})
export class InsM03Workspace {
  private readonly store = inject(InsM03Store);
  private readonly shell = inject(InsShellStore);
  private readonly msg = inject(HrmMessageService);
  private readonly modal = inject(HrmModalService);


  protected readonly icWarn = IconAlertTriangle;
  protected readonly icRefresh = IconRefresh;
  protected readonly icFile = IconFilePlus;
  protected readonly icDown = IconChevronDown;
  protected readonly icRight = IconChevronRight;
  protected readonly icUp = IconChevronUp;
  protected readonly a07Note = A07_D02LT_NOTE;
  protected readonly wsMinWidth = M03_WORKSPACE_MIN_WIDTH;

  protected readonly locked = computed(() => this.store.kyLocked());

  /* ── Header ① Kỳ selector (store.kyId) — đổi kỳ = đổi ứng viên, reset chọn/lý do ── */
  protected readonly kyOptions = INS_KY.map((k) => ({ value: k.id, label: k.label }));
  protected readonly selectedKy = computed(() => this.store.kyId());
  protected onKyChange(v: string): void {
    this.store.kyId.set(v);
    this.selected.set(new Set());
    this.whyOpen.set(false);
  }

  /* ── Header ② Loại kỳ (segmented · store.loaiKy) — ngữ cảnh màn (YC1) ── */
  protected readonly loaiKyOptions = (Object.keys(INS_LOAI_KY_LABEL) as InsLoaiKyKeKhai[])
    .map((v) => ({ value: v, label: INS_LOAI_KY_LABEL[v] }));
  protected readonly loaiKy = computed(() => this.store.loaiKy());
  protected onLoaiKyChange(v: string | number): void {
    this.store.setLoaiKy(v as InsLoaiKyKeKhai);
    this.selected.set(new Set());
    this.whyOpen.set(false);
  }

  /* ── selection (component-managed; ⚪ Đang tham gia KHÔNG chọn được) ── */
  private readonly selected = signal<ReadonlySet<string>>(new Set());
  protected isSel(id: string): boolean { return this.selected().has(id); }
  protected toggle(id: string): void {
    const next = new Set(this.selected());
    next.has(id) ? next.delete(id) : next.add(id);
    this.selected.set(next);
  }
  protected toggleAll(on: boolean): void {
    this.selected.set(on ? new Set(this.selectableIds()) : new Set());
  }

  /* ── thu/mở nhóm — ⚪ Đang tham gia thu gọn mặc định (đối chiếu) ── */
  private readonly collapsed = signal<ReadonlySet<InsNhomKeKhai>>(new Set<InsNhomKeKhai>(['dang-tham-gia']));
  protected isOpen(n: InsNhomKeKhai): boolean { return !this.collapsed().has(n); }
  protected toggleGroup(n: InsNhomKeKhai): void {
    const next = new Set(this.collapsed());
    next.has(n) ? next.delete(n) : next.add(n);
    this.collapsed.set(next);
  }

  /* ── Cập nhật mức đóng — nút DUY NHẤT chạy lại số 4 tầng (Q38 mẫu → hiện 'Chờ tính'). ── */
  protected readonly capNhatLuc = signal('25/08 09:12');
  protected capNhatMucDong(): void {
    if (this.locked()) return;
    this.capNhatLuc.set(stampNow());
    this.msg.success('Đã chạy tính lại mức đóng 4 tầng (Q38 tham số mẫu — dự kiến). Số phải đóng chốt khi lập tờ khai.');
  }

  /* ── nguồn dữ liệu: ứng viên kỳ gom 4 nhóm (store.candidatesByNhom) ── */
  private readonly allRows = computed<WsRowExt[]>(() => {
    const byNhom = this.store.candidatesByNhom();
    const out: WsRowExt[] = [];
    for (const nhom of NHOM_ORDER) {
      for (const it of byNhom[nhom]) out.push(this.extRow(it, nhom));
    }
    return out;
  });
  private readonly rowById = computed<Map<string, WsRowExt>>(() => new Map(this.allRows().map((r) => [r.id, r])));

  protected readonly groups = computed<WsGroup[]>(() => {
    const rows = this.allRows();
    return NHOM_ORDER.map((nhom) => {
      const gr = rows.filter((r) => r.nhom === nhom);
      const keKhai = nhom !== 'dang-tham-gia';
      const tong = keKhai
        ? gr.filter((r) => !r.thieuLuong).reduce((s, r) => s + parseMoney(r.mucMoi), 0)
        : 0;
      return {
        nhom, label: INS_NHOM_LABEL[nhom], tone: INS_NHOM_TONE[nhom], thuTuc: INS_NHOM_THUTUC[nhom],
        keKhai, rows: gr, count: gr.length, tongLuong: keKhai && tong ? fmtMoney(tong) : '',
      };
    });
  });

  /** Ứng viên chọn được = 3 nhóm kê khai (⚪ Đang tham gia không tick). */
  protected readonly selectableIds = computed(() => this.allRows().filter((r) => r.selectable).map((r) => r.id));
  protected readonly selectedCount = computed(() => this.selected().size);
  protected readonly allChecked = computed(() => {
    const ids = this.selectableIds();
    return ids.length > 0 && ids.every((id) => this.selected().has(id));
  });
  protected readonly someChecked = computed(() => this.selectedCount() > 0 && !this.allChecked());

  /** Tổng quỹ lương đóng (dự kiến) = tổng lương căn cứ 3 nhóm kê khai (dataFields SC-B1). */
  protected readonly tongQuyLuong = computed(() => {
    const t = this.allRows()
      .filter((r) => r.selectable && !r.thieuLuong)
      .reduce((s, r) => s + parseMoney(r.mucMoi), 0);
    return fmtMoney(t);
  });
  /** '⚠ N dòng còn cảnh báo' — thiếu PA (⑦) / D01-TS (⑤) / mã số BHXH / lương. */
  protected readonly soCanhBao = computed(() => this.allRows().filter((r) => r.selectable && r.canhBao).length);

  /* ── dry-run "Lập tờ khai": N vào · M bỏ qua kèm lý do (mirror store guards; chạy thử, không đổi state) ── */
  protected readonly dryRun = computed<{ eligible: number; blockedTotal: number; eligibleIds: string[]; blocked: { reason: string; count: number }[] }>(() => {
    const map = this.rowById();
    const eligibleIds: string[] = [];
    const byReason = new Map<string, number>();
    for (const id of this.selected()) {
      const r = map.get(id);
      if (!r) continue;
      if (r.skipFiling === '') eligibleIds.push(id);
      else byReason.set(r.skipFiling, (byReason.get(r.skipFiling) ?? 0) + 1);
    }
    const blocked = [...byReason].map(([reason, count]) => ({ reason, count }));
    return { eligible: eligibleIds.length, blockedTotal: blocked.reduce((s, b) => s + b.count, 0), eligibleIds, blocked };
  });

  /** Lý do khóa nút Lập tờ khai (điểm dừng — disabled-có-lý-do, không khóa câm). */
  protected readonly lapReason = computed<string | null>(() => {
    if (this.locked()) return `${insKy(this.store.kyId())?.label ?? 'Kỳ'} đã khóa — không lập tờ khai.`;
    if (this.selectedCount() === 0) return 'Chọn ít nhất 1 dòng trong 3 nhóm kê khai.';
    if (this.dryRun().eligible === 0) return 'Mọi dòng đã chọn đều bị bỏ qua — gỡ vướng (mã phương án · D01-TS · trùng NLĐ) rồi lập lại.';
    return null;
  });

  protected readonly whyOpen = signal(false);
  protected toggleWhy(): void { this.whyOpen.update((v) => !v); }

  /* ── Modal LẬP TỜ KHAI — chooser lô (lô chưa nộp gần nhất / lô mới) + 2 nút Lưu nháp/Nộp hồ sơ ── */
  /** Lô CHƯA NỘP mới nhất của kỳ (mặc định chọn); null = chưa có → chỉ còn 'lập lô mới'. */
  protected readonly loHienTai = computed(() => this.store.loHienTaiCuaKy());
  /** Options chooser: [lô hiện tại nếu có] + lập lô mới. */
  protected readonly loChonOptions = computed<HrmOption[]>(() => {
    const opts: HrmOption[] = [];
    const cur = this.loHienTai();
    if (cur) {
      const n = this.store.itemsOfLo(cur.maLo).length;
      opts.push({ value: 'hien-tai', label: `Lô hiện tại ${cur.maLo} · ${INS_LO_LABEL[cur.trangThai]} · ${n} dòng` });
    }
    opts.push({ value: 'moi', label: 'Lập lô mới cho kỳ' });
    return opts;
  });
  private readonly loChonSig = signal<'hien-tai' | 'moi'>('moi');
  protected loChon(): 'hien-tai' | 'moi' { return this.loChonSig(); }
  protected onLoChonChange(v: unknown): void { this.loChonSig.set(v === 'hien-tai' ? 'hien-tai' : 'moi'); }
  private dlg: { close: () => void } | null = null;
  private readonly lapTplRef = viewChild.required<TemplateRef<unknown>>('lapTpl');

  /** "Lập tờ khai" = MỞ MODAL chooser lô (KHÔNG điều hướng ngay). */
  protected lapToKhai(): void {
    if (this.lapReason()) return;
    this.loChonSig.set(this.loHienTai() ? 'hien-tai' : 'moi');
    this.dlg = this.modal.open({
      title: 'Lập tờ khai (tự lên 600/600a/600b)', content: this.lapTplRef(), width: 480,
      footer: [
        { label: 'Lưu nháp', onClick: () => this.confirmLap(false) },
        { label: 'Nộp hồ sơ', type: 'primary', onClick: () => this.confirmLap(true) },
      ],
    });
  }

  /** Xác nhận: giải maLo (lô hiện tại đã chọn / lập lô mới) → themVaoLo → (Nộp?→trinhDuyet) → điều hướng m03b. */
  private confirmLap(nop: boolean): void {
    const ids = this.dryRun().eligibleIds;
    let maLo: string | null = null;
    if (this.loChonSig() === 'hien-tai' && this.loHienTai()) {
      maLo = this.loHienTai()!.maLo;
    } else {
      maLo = this.taoLoMoi();
      if (!maLo) return;                                   // lỗi tạo lô đã báo — giữ modal mở
    }
    const add = this.store.themVaoLo(ids, maLo);
    const boQua = add.skipped.length;
    if (nop) {
      const tr = this.store.trinhDuyet(maLo);
      if (!tr.ok) this.msg.warning(tr.reason ?? 'Chưa nộp được — lô giữ Nháp.');
      else this.msg.success(`Đã nộp hồ sơ lô ${maLo} — ${add.done} dòng vào · chuyển Chờ duyệt.`);
    } else {
      this.msg.success(`Đã lưu nháp lô ${maLo} — ${add.done} dòng vào${boQua ? ` · ${boQua} bỏ qua` : ''} (tự lên 600/600a/600b).`);
    }
    this.selected.set(new Set());
    this.whyOpen.set(false);
    this.dlg?.close();
    this.shell.go('m03b', { filter: 'lo:' + maLo, ky: this.store.kyId(), donVi: this.store.donViId() });
  }

  /** Lập lô mới cho kỳ hiện hành (số hồ sơ tự sinh) — trả maLo hoặc null nếu lỗi (đã báo). */
  private taoLoMoi(): string | null {
    const kyId = this.store.kyId();
    const label = insKy(kyId)?.label ?? kyId;
    const mm = /(\d{2})\/(\d{4})/.exec(label);
    const soLo = this.store.losOfKy().length + 1;
    const soHoSo = mm ? `${mm[1]}-${mm[2]}/TK${soLo}` : `TK${soLo}`;
    const created = this.store.taoLo({
      soHoSo, tenLo: `Tờ khai lập từ workspace — ${label}`, ky: kyId,
      loaiThuTuc: 'Thu BHXH/BHYT/BHTN', phongBan: 'Toàn công ty',
    });
    if (!created.ok || !created.maLo) { this.msg.error(created.reason ?? 'Không tạo được lô.'); return null; }
    return created.maLo;
  }

  /* ── cột lưới (6 cột SC-B1) — gắn cell TemplateRef theo key ── */
  private readonly chonTpl = viewChild.required<TemplateRef<unknown>>('chonCell');
  private readonly nldTpl = viewChild.required<TemplateRef<unknown>>('nldCell');
  private readonly paTpl = viewChild.required<TemplateRef<unknown>>('paCell');
  private readonly mucTpl = viewChild.required<TemplateRef<unknown>>('mucCell');
  private readonly quyTpl = viewChild.required<TemplateRef<unknown>>('quyCell');
  private readonly spdTpl = viewChild.required<TemplateRef<unknown>>('spdCell');
  protected readonly cols = computed<HrmGridColumn[]>(() => {
    const tpl: Record<string, TemplateRef<unknown> | undefined> = {
      chon: this.chonTpl(), nld: this.nldTpl(), phuongAn: this.paTpl(),
      mucDong: this.mucTpl(), quy: this.quyTpl(), soPhaiDong: this.spdTpl(),
    };
    return M03_WORKSPACE_COLS.map((d) => ({ ...d, cell: tpl[d.key] as HrmGridColumn['cell'] }));
  });

  /* ── helpers ── */
  /** WsRow + mức đóng cũ→mới (điều chỉnh: cũ = lương đang đóng nv.salary) + skip filing store-accurate. */
  private extRow(it: InsLoItem, nhom: InsNhomKeKhai): WsRowExt {
    const base = buildWsRow(it);
    const nv = insNhanVien(it.nhanVienId);
    const mucMoi = it.thieuLuong ? 'không tính được' : it.luongCanCu;
    const mucCu = nhom === 'dieu-chinh' && !it.thieuLuong ? (nv?.salary ?? '') : '';
    return {
      ...base,
      nhanVienId: it.nhanVienId,
      mucMoi, mucCu,
      canhBao: base.paMissing || base.thieuD01TS || base.thieuMaBHXH || !!it.thieuLuong,
      skipFiling: this.candidateSkip(it),
    };
  }
  /** Lý do 1 ứng viên bị bỏ qua khi vào tờ khai — mirror store.themVaoLoSkipReason (ứng viên: ⑦ ⑤ trùng NLĐ). */
  private candidateSkip(it: InsLoItem): string {
    if (this.store.kyLocked()) return 'Kỳ đã khóa — không lập tờ khai.';
    if (!it.maPhuongAn) return GUARD7;                       // ⑦
    if (it.truyThu && !it.coD01TS) return GUARD5;            // ⑤
    const trung = this.store.items().some((x) => {
      if (x.maItem === it.maItem || x.nhanVienId !== it.nhanVienId || x.loId === null) return false;
      const lo = this.store.lo(x.loId);
      return !!lo && lo.ky === it.ky && LO_CHUA_NOP.has(lo.trangThai);
    });
    return trung ? TRUNG_NLD : '';
  }
}
