import { ChangeDetectionStrategy, Component, TemplateRef, computed, inject, input, signal, viewChild } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { HrmAlert, HrmButton, HrmInput, HrmMessageService, HrmModalService, HrmTag, HrmTextarea } from 'hrm-ui';
import { InsSectionLabel, InsSlaChip } from '../../_shared';
import {
  INS_CHECKLIST_LABEL, INS_TAILIEU_LABEL, INS_TAILIEU_TONE, InsChecklistItem, InsM05Store, InsViPham,
} from '../../_data/_m05-data';

/** M05-B · B2 Điều kiện & chứng từ — 2 checklist (điều kiện hưởng + chứng từ) 4 trạng thái mục
 *  ✓/!/×/⏳; tài liệu 4 trạng thái + tag nhạy cảm + "mọi lượt xem ghi log"; hạn bổ sung + 2 lối ra
 *  khi quá hạn (gia hạn — duyệt QL HR / đóng — lý do, xử lý ở B5-modal cha); vi phạm eligibility
 *  3 mức: chặn = alert error · cảnh báo = alert warning + nút "Tiếp tục (override)" modal lý do ·
 *  kèm rule version + nguồn pháp lý.
 *  ⚠️ Checklist TỰ DỰNG token-only: `hrm-setup-guide` là accordion done/undone nhị phân + form field
 *  (Shopify onboarding) — không thể hiện 4 trạng thái mục / trạng thái chỉ đọc / hạn bổ sung SLA. */
@Component({
  selector: 'ins-m05-b2',
  imports: [FormsModule, HrmAlert, HrmButton, HrmInput, HrmTag, HrmTextarea, InsSectionLabel, InsSlaChip],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (c(); as c) {
      <div class="b2">
        <!-- Quá hạn bổ sung → 2 lối ra -->
        @if (c.trangThai === 'thieu-chung-tu-qua-han') {
          <hrm-alert type="error" message="Thiếu chứng từ QUÁ HẠN bổ sung — đúng 2 lối ra"
            description="① Gia hạn (cần quản lý HR duyệt) — case về Chờ chứng từ với hạn mới · ② Đóng case với lý do danh mục 'thiếu chứng từ quá hạn' (thực hiện ở B5)."
            [action]="quaHanActions" />
        }

        <div class="b2__cols">
          <!-- Checklist ĐIỀU KIỆN HƯỞNG -->
          <section class="b2__sec">
            <ins-section-label text="Điều kiện hưởng" tone="muted" [count]="dieuKien().length" />
            <div class="b2__list">
              @for (k of dieuKien(); track k.id) {
                <div class="b2__item" [attr.data-st]="k.trangThai">
                  <span class="b2__tick" [attr.data-st]="k.trangThai">{{ tick(k) }}</span>
                  <span class="b2__item-body">
                    <span class="b2__item-name">{{ k.muc }}@if (k.batBuoc) { <b class="b2__req">*</b> }</span>
                    <span class="b2__item-st">{{ stLabel(k) }}@if (k.hanBoSung) { · hạn bổ sung <b>{{ k.hanBoSung }}</b>}</span>
                  </span>
                </div>
              } @empty { <p class="b2__muted">Chưa sinh checklist điều kiện cho loại chế độ này.</p> }
            </div>
          </section>

          <!-- Checklist CHỨNG TỪ -->
          <section class="b2__sec">
            <ins-section-label text="Chứng từ" tone="{{ thieuCount() ? 'attention' : 'muted' }}" [count]="chungTu().length" />
            <div class="b2__list">
              @for (k of chungTu(); track k.id) {
                <div class="b2__item" [attr.data-st]="k.trangThai">
                  <span class="b2__tick" [attr.data-st]="k.trangThai">{{ tick(k) }}</span>
                  <span class="b2__item-body">
                    <span class="b2__item-name">{{ k.muc }}@if (k.batBuoc) { <b class="b2__req">*</b> }</span>
                    <span class="b2__item-st">{{ stLabel(k) }}@if (k.hanBoSung) { · hạn bổ sung <b>{{ k.hanBoSung }}</b>}</span>
                  </span>
                  @if (k.trangThai === 'thieu' && k.hanBoSung) {
                    <ins-sla-chip [label]="'hạn ' + k.hanBoSung" [tone]="c.trangThai === 'thieu-chung-tu-qua-han' ? 'danger' : 'warn'" />
                  }
                </div>
              } @empty { <p class="b2__muted">Không yêu cầu chứng từ bổ sung.</p> }
            </div>
            <p class="b2__muted">Đổi loại chế độ → checklist sinh lại, GIỮ mục còn hiệu lực (LOCK B2 m05.md).</p>
          </section>
        </div>

        <!-- Tài liệu 4 trạng thái + nhạy cảm + log -->
        <section class="b2__sec">
          <ins-section-label text="Tài liệu đính kèm" tone="muted" [count]="c.taiLieu.length" />
          @for (t of c.taiLieu; track t.id) {
            <div class="b2__doc">
              <div class="b2__doc-main">
                <span class="b2__doc-name">{{ t.ten }} <span class="b2__muted">{{ t.phienBan }} · {{ t.phanLoai }} · {{ t.nguon }}</span></span>
                <div class="b2__doc-tags">
                  <hrm-tag size="sm" [color]="docHue(t.trangThai)">{{ docLabel(t.trangThai) }}</hrm-tag>
                  @if (t.nhayCam) { <hrm-tag color="red" size="sm" variant="lighter">Y tế nhạy cảm — mọi lượt xem ghi log</hrm-tag> }
                </div>
              </div>
              <hrm-button size="sm" (click)="xem(t.id)">Xem (ghi log)</hrm-button>
              @if (t.log.length) {
                <span class="b2__muted">{{ t.log.length }} lượt xem · gần nhất: {{ t.log[t.log.length - 1].at }} — {{ t.log[t.log.length - 1].nguoi }}</span>
              }
            </div>
          } @empty { <p class="b2__muted">Chưa có tài liệu đính kèm.</p> }
        </section>

        <!-- Vi phạm eligibility 3 mức -->
        <section class="b2__sec">
          <ins-section-label text="Kiểm tra điều kiện (eligibility) — 3 mức theo cấu hình M08" tone="muted" [count]="c.viPham.length" />
          @for (v of c.viPham; track v.maQuyTac) {
            @if (v.mucDo === 'chan') {
              <hrm-alert type="error" [message]="'CHẶN — ' + v.thongDiep" [description]="ruleMeta(v)" />
            } @else if (v.mucDo === 'canh-bao') {
              @if (v.daOverride; as ov) {
                <hrm-alert type="info" [message]="'Cảnh báo ĐÃ OVERRIDE — ' + v.thongDiep"
                  [description]="ruleMeta(v) + ' · override bởi ' + ov.nguoi + ' (' + ov.at + '): ' + ov.lyDo" />
              } @else {
                <div class="b2__warnrow">
                  <hrm-alert class="b2__warnalert" type="warning" [message]="v.thongDiep" [description]="ruleMeta(v)" />
                  <hrm-button size="sm" (click)="openOverride(v.maQuyTac)">Tiếp tục (override)</hrm-button>
                </div>
              }
            } @else {
              <hrm-alert type="info" [message]="v.thongDiep" [description]="ruleMeta(v)" />
            }
          } @empty { <p class="b2__muted">Không có vi phạm eligibility.</p> }
        </section>

        @if (c.exceptionDong; as ex) {
          <section class="b2__sec">
            <ins-section-label text="Exception dữ liệu đóng (AC-08 — chỉ đọc dữ liệu đóng)" tone="critical" />
            <hrm-alert type="warning" [message]="ex.id + ' · ' + ex.moTa"
              [description]="'Owner: ' + ex.owner + ' · hạn ' + ex.han + ' · link 2 chiều ' + ex.maTuongQuan + ' (kỳ ' + ex.kyDong + ') — exception đóng thì case TỰ chạy lại kiểm tra.'" />
          </section>
        }
      </div>

      <!-- action alert quá hạn: gia hạn -->
      <ng-template #quaHanActions>
        <hrm-button size="sm" variant="primary" (click)="openGiaHan()">Gia hạn (duyệt QL HR)</hrm-button>
      </ng-template>

      <!-- Modal gia hạn -->
      <ng-template #giaHanTpl>
        <div class="b2__form">
          <p class="b2__muted">Gia hạn bổ sung chứng từ — cần <b>quản lý HR ({{ store.quanLyHR }})</b> duyệt; case quay về Chờ chứng từ với hạn mới.</p>
          <hrm-input [(ngModel)]="hanMoiModel" placeholder="Hạn mới (dd/mm/yyyy)" size="sm" />
          @if (formError()) { <span class="b2__err">{{ formError() }}</span> }
        </div>
      </ng-template>

      <!-- Modal override cảnh báo (lý do bắt buộc) -->
      <ng-template #overrideTpl>
        <div class="b2__form">
          <p class="b2__muted">Bỏ qua cảnh báo = OVERRIDE — lưu lý do + người (audit). Ngưỡng duyệt override theo tiền + loại (M08) — <b>Cần stakeholder xác nhận</b>.</p>
          <hrm-textarea [(ngModel)]="lyDoModel" placeholder="Nhập lý do (bắt buộc)…" [minRows]="3" [status]="formError() ? 'error' : ''" />
          @if (formError()) { <span class="b2__err">{{ formError() }}</span> }
        </div>
      </ng-template>
    }
  `,
  host: { class: 'ins-m05-b2' },
  styles: [`
    :host { display: block; }
    .b2 { display: flex; flex-direction: column; gap: 16px; max-width: 1080px; }
    .b2__cols { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; align-items: start; }
    .b2__sec { display: flex; flex-direction: column; gap: 8px; min-width: 0; }
    .b2__list { display: flex; flex-direction: column; border: 1px solid var(--border-sub); border-radius: var(--radius-md); overflow: hidden; }
    .b2__item { display: flex; align-items: center; gap: 10px; padding: 8px 12px; border-bottom: 1px solid var(--border-soft); background: var(--bg-surface); }
    .b2__item:last-child { border-bottom: 0; }
    .b2__item[data-st='thieu'] { background: color-mix(in srgb, var(--error-bg) 40%, var(--bg-surface)); }
    .b2__tick {
      flex: none; width: 22px; height: 22px; display: grid; place-items: center;
      border-radius: var(--radius-full); font-size: var(--fs-12); font-weight: 700;
      background: var(--bg-surface-subtle); color: var(--text-sub);
    }
    .b2__tick[data-st='du'] { background: var(--success-bg); color: var(--success-text); }
    .b2__tick[data-st='thieu'] { background: var(--error-bg); color: var(--error-text); }
    .b2__tick[data-st='cho-xac-minh'] { background: var(--warning-bg); color: var(--warning-text); }
    .b2__item-body { display: flex; flex-direction: column; gap: 1px; min-width: 0; flex: 1; }
    .b2__item-name { font-size: var(--fs-13); font-weight: 500; color: var(--text-strong); }
    .b2__req { color: var(--error-base); }
    .b2__item-st { font-size: var(--fs-12); color: var(--text-sub); }
    .b2__item-st b { color: var(--warning-text); }
    .b2__muted { margin: 0; font-size: var(--fs-12); color: var(--text-sub); }
    .b2__muted b, .b2__form b { color: var(--text-strong); }
    .b2__err { font-size: var(--fs-12); color: var(--error-text); }
    .b2__doc { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; border: 1px solid var(--border-sub); border-radius: var(--radius-md); background: var(--bg-surface); padding: 8px 12px; }
    .b2__doc-main { display: flex; flex-direction: column; gap: 4px; flex: 1; min-width: 240px; }
    .b2__doc-name { font-size: var(--fs-13); font-weight: 500; color: var(--text-strong); }
    .b2__doc-tags { display: flex; gap: 4px; flex-wrap: wrap; }
    :host ::ng-deep .b2__doc-tags .ant-tag { margin: 0; }
    .b2__warnrow { display: flex; align-items: flex-start; gap: 10px; }
    .b2__warnalert { flex: 1; display: block; }
    .b2__form { display: flex; flex-direction: column; gap: 8px; }
  `],
})
export class InsM05B2 {
  protected readonly store = inject(InsM05Store);
  private readonly msg = inject(HrmMessageService);
  private readonly modal = inject(HrmModalService);

  readonly caseId = input.required<string>();
  protected readonly c = computed(() => this.store.caseOf(this.caseId()));

  protected readonly dieuKien = computed(() => this.c()?.checklist.filter((k) => k.loai === 'dieu-kien') ?? []);
  protected readonly chungTu = computed(() => this.c()?.checklist.filter((k) => k.loai === 'chung-tu') ?? []);
  protected readonly thieuCount = computed(() => this.chungTu().filter((k) => k.trangThai === 'thieu').length);

  protected tick(k: InsChecklistItem): string {
    switch (k.trangThai) {
      case 'du': return '✓';
      case 'thieu': return '✕';
      case 'cho-xac-minh': return '!';
      case 'khong-ap-dung': return '—';
    }
  }
  protected stLabel(k: InsChecklistItem): string { return INS_CHECKLIST_LABEL[k.trangThai]; }
  protected docLabel(s: keyof typeof INS_TAILIEU_LABEL): string { return INS_TAILIEU_LABEL[s]; }
  protected docHue(s: keyof typeof INS_TAILIEU_TONE): string {
    const t = INS_TAILIEU_TONE[s];
    return t === 'success' ? 'green' : t === 'error' ? 'red' : 'blue';
  }
  protected ruleMeta(v: InsViPham): string {
    return `${v.maQuyTac} · ${v.ruleVersion} · ${v.nguonPhapLy} · hiệu lực ${v.ngayHieuLuc}`;
  }

  protected xem(taiLieuId: string): void {
    this.store.xemTaiLieu(this.caseId(), taiLieuId);
    this.msg.info('Đã mở tài liệu — lượt xem được ghi log (tài liệu y tế nhạy cảm).');
  }

  /* ── modal gia hạn / override ── */
  private dlg: { close: () => void } | null = null;
  protected readonly formError = signal('');
  private readonly hanMoi = signal('29/08/2026');
  protected get hanMoiModel(): string { return this.hanMoi(); }
  protected set hanMoiModel(v: string) { this.hanMoi.set(v ?? ''); if (v?.trim()) this.formError.set(''); }
  private readonly lyDo = signal('');
  protected get lyDoModel(): string { return this.lyDo(); }
  protected set lyDoModel(v: string) { this.lyDo.set(v ?? ''); if (v?.trim()) this.formError.set(''); }
  private readonly overrideRule = signal('');
  private readonly giaHanTplRef = viewChild<TemplateRef<unknown>>('giaHanTpl');
  private readonly overrideTplRef = viewChild<TemplateRef<unknown>>('overrideTpl');

  protected openGiaHan(): void {
    this.formError.set('');
    this.dlg = this.modal.open({
      title: 'Gia hạn bổ sung chứng từ (duyệt QL HR)', content: this.giaHanTplRef()!, width: 440,
      footer: [
        { label: 'Hủy', onClick: () => this.dlg?.close() },
        { label: 'Gia hạn', type: 'primary', onClick: () => {
          const han = this.hanMoi().trim();
          if (!han) { this.formError.set('Hạn mới là bắt buộc.'); return; }
          const r = this.store.giaHanChungTu(this.caseId(), han, this.store.quanLyHR);
          r.ok ? this.msg.success(`Đã gia hạn đến ${han} — case về Chờ chứng từ (duyệt: ${this.store.quanLyHR}).`) : this.msg.error(r.reason ?? 'Không gia hạn được.');
          this.dlg?.close();
        } },
      ],
    });
  }

  protected openOverride(maQuyTac: string): void {
    this.overrideRule.set(maQuyTac); this.lyDo.set(''); this.formError.set('');
    this.dlg = this.modal.open({
      title: `Tiếp tục (override) cảnh báo ${maQuyTac}`, content: this.overrideTplRef()!, width: 460,
      footer: [
        { label: 'Thoát', onClick: () => this.dlg?.close() },
        { label: 'Tiếp tục (override)', type: 'primary', onClick: () => {
          const r = this.store.overrideCanhBao(this.caseId(), this.overrideRule(), this.lyDo());
          if (!r.ok) { this.formError.set(r.reason ?? 'Không override được.'); return; }
          this.msg.success('Đã override cảnh báo — lưu lý do + người (audit).');
          this.dlg?.close();
        } },
      ],
    });
  }
}
