/* ═══════════════════════════ STORE ═══════════════════════════ */

export type M06TabKey = 't1' | 't2' | 't3' | 't4';
export const M06_TAB_LABEL: Record<M06TabKey, string> = {
  t1: 'Tài liệu', t2: 'Hồ sơ người tham gia', t3: 'Thủ tục hồ sơ', t4: 'Hồ sơ bị từ chối',
};

/** 7 tiêu chí tìm kiếm toàn cục — chip GIỮ khi chuyển tab, gỡ từng chip. */
export type M06FilterKey = 'nguoi' | 'ma-bhxh' | 'don-vi' | 'ky' | 'loai-thu-tuc' | 'trang-thai' | 'ma-gd';
export const M06_FILTER_LABEL: Record<M06FilterKey, string> = {
  nguoi: 'Người', 'ma-bhxh': 'Mã BHXH', 'don-vi': 'Đơn vị', ky: 'Kỳ',
  'loai-thu-tuc': 'Loại thủ tục', 'trang-thai': 'Trạng thái', 'ma-gd': 'Mã GD',
};

export interface M06BulkResult { done: number; skipped: { id: string; reason: string }[] }

@Injectable({ providedIn: 'root' })
export class InsM06Store {
  readonly currentUser = HR_1;
  readonly quanLyHR = HR_2;

  /** BQA-13/10: đọc danh mục thủ tục (M08) + đẩy dòng gộp sổ (M03). Inject LAZY (Injector.get) —
   *  M06 KHÔNG chạm store khác lúc khởi tạo; M08/M03 KHÔNG import ngược M06 nên không có vòng.
   *  (M06→M08 đọc · M06→M03 gọi; M08 chạm M02_TODAY top-level nhưng M02 không import M06/M08 → an toàn.) */
  private readonly injector = inject(Injector);
  private get m08(): InsM08Store { return this.injector.get(InsM08Store); }
  private get m03(): InsM03Store { return this.injector.get(InsM03Store); }

  readonly taiLieu = signal<InsM06TaiLieu[]>(clone(TAILIEU_SEED));
  readonly nguoiThamGia = signal<InsM06NguoiThamGia[]>(clone(NGUOITHAMGIA_SEED));
  readonly lanNhap = signal<InsM06LanNhap>(clone(LANNHAP_SEED));
  readonly lanDongBo = signal<InsM06LanDongBo>(clone(DONGBO_SEED));
  readonly boHoSo = signal<InsM06BoHoSo[]>(clone(BOHOSO_SEED));
  /** BQA-13: danh mục thủ tục = VIEW đọc từ danh mục M08 (nguồn duy nhất), map sang shape M06. */
  readonly thuTuc = computed<InsM06ThuTuc[]>(() => this.m08.thuTuc().map((t) => this.adaptThuTuc(t)));
  readonly gopSo = signal<InsM06GopSo>(clone(GOPSO_SEED));
  readonly tuChoi = signal<InsM06TuChoi[]>(clone(TUCHOI_SEED));
  readonly quaTrinh = signal<InsM06DongQuaTrinh[]>(clone(QUATRINH_SEED));
  readonly mucLuong = signal<InsM06MucLuong[]>(clone(MUCLUONG_SEED));
  readonly bienDongLocal = signal<InsM06BienDongLocal[]>(clone(BIENDONG_LOCAL_SEED));

  /** Nhật ký append-only — GỒM lượt bị từ chối. */
  readonly audit = signal<InsM06AuditEntry[]>([]);
  /** Mô phỏng "không ghi được nhật ký" → MỌI thao tác ghi bị chặn (LOCK audit). */
  readonly auditOffline = signal(false);
  readonly lastBulk = signal<{ action: string; skipped: { id: string; reason: string }[] } | null>(null);

  /* ── UI state sống trong store: tab + 7 tiêu chí (chip GIỮ khi chuyển tab) ── */
  readonly centerTab = signal<M06TabKey>('t2'); // tab mặc định T2 (OQ m06.md)
  readonly kw = signal('');
  readonly filters = signal<Partial<Record<M06FilterKey, string>>>({});
  /** T2: mặc định ẨN ngừng hiệu lực (toggle). */
  readonly hienNgung = signal(false);
  /** T4: lọc theo nguồn ('' = cả 2 nguồn chung 1 lưới). */
  readonly tuChoiNguon = signal<'' | InsM06TuChoiNguon>('');

  readonly chips = computed(() => {
    const f = this.filters();
    return (Object.keys(f) as M06FilterKey[]).filter((k) => f[k]).map((k) => ({ key: k, label: `${M06_FILTER_LABEL[k]}: ${f[k]}` }));
  });

  resetDemo(): void {
    this.taiLieu.set(clone(TAILIEU_SEED)); this.nguoiThamGia.set(clone(NGUOITHAMGIA_SEED));
    this.lanNhap.set(clone(LANNHAP_SEED)); this.lanDongBo.set(clone(DONGBO_SEED));
    this.boHoSo.set(clone(BOHOSO_SEED)); // thuTuc là computed đọc từ M08 — không reset ở M06
    this.gopSo.set(clone(GOPSO_SEED)); this.tuChoi.set(clone(TUCHOI_SEED));
    this.quaTrinh.set(clone(QUATRINH_SEED)); this.mucLuong.set(clone(MUCLUONG_SEED));
    this.audit.set([]); this.auditOffline.set(false); this.lastBulk.set(null);
    this.centerTab.set('t2'); this.kw.set(''); this.filters.set({}); this.hienNgung.set(false); this.tuChoiNguon.set('');
  }

  /* ── audit là ĐIỀU KIỆN TIÊN QUYẾT: ghi() fail → transition trả {ok:false} ── */
  private ghi(entry: Omit<InsM06AuditEntry, 'at'>): boolean {
    if (this.auditOffline()) return false;
    this.audit.update((l) => [...l, { at: demoNow(), ...entry }]);
    return true;
  }
  private chan(): { ok: false; reason: string } { return { ok: false, reason: M06_AUDIT_CHAN }; }

  /** Mỗi lần tìm kiếm = 1 dòng audit (LOCK tìm kiếm 7 tiêu chí). Lượt tìm không bị chặn ghi —
   *  nhưng nếu audit offline thì cũng không ghi được (đọc vẫn cho phép, chỉ ghi log best-effort). */
  timKiem(moTa: string): void { this.ghi({ nguoi: this.currentUser, hanhDong: `Tìm kiếm: ${moTa}` }); }
  datFilter(key: M06FilterKey, value: string | null): void {
    this.filters.update((f) => { const n = { ...f }; if (value) n[key] = value; else delete n[key]; return n; });
    if (value) this.timKiem(`${M06_FILTER_LABEL[key]} = "${value}"`);
  }

  /* ── match 7 tiêu chí dùng chung 4 tab (tiêu chí không áp dụng cho tab → bỏ qua) ── */
  matchNLD(nhanVienId?: string): boolean {
    const f = this.filters();
    const nv = nhanVienId ? insNhanVien(nhanVienId) : undefined;
    if (f['nguoi'] && !(nv && `${nv.name} ${nv.code}`.toLowerCase().includes(f['nguoi'].toLowerCase()))) return false;
    if (f['ma-bhxh'] && !(nv && (nv.insCode.includes(f['ma-bhxh']) || nv.maBHXH.includes(f['ma-bhxh'])))) return false;
    if (f['don-vi'] && !(nv && nv.donViId === f['don-vi'])) return false;
    return true;
  }
  private matchKw(text: string): boolean {
    const kw = this.kw().trim().toLowerCase();
    return !kw || text.toLowerCase().includes(kw);
  }

  readonly taiLieuLoc = computed(() => this.taiLieu().filter((t) => {
    const f = this.filters();
    if (f['ky'] && t.ky !== f['ky']) return false;
    if (f['trang-thai'] && t.trangThai !== f['trang-thai']) return false;
    if (!this.matchNLD(t.nhanVienId)) return false;
    const nv = t.nhanVienId ? insNhanVien(t.nhanVienId) : undefined;
    return this.matchKw(`${t.ten} ${t.loai} ${t.nguon} ${nv?.name ?? ''}`);
  }));

  readonly nguoiThamGiaLoc = computed(() => this.nguoiThamGia().filter((n) => {
    if (!this.hienNgung() && n.trangThai === 'ngung') return false;
    const f = this.filters();
    if (f['ky'] && n.ky !== f['ky']) return false;
    if (f['trang-thai'] && n.trangThai !== f['trang-thai']) return false;
    if (!this.matchNLD(n.nhanVienId)) return false;
    const nv = insNhanVien(n.nhanVienId);
    return this.matchKw(`${nv?.name ?? ''} ${nv?.code ?? ''} ${n.soSo} ${n.soThe}`);
  }));

  readonly boHoSoLoc = computed(() => this.boHoSo().filter((h) => {
    const f = this.filters();
    if (f['loai-thu-tuc'] && h.loaiThuTuc !== f['loai-thu-tuc']) return false;
    if (f['trang-thai'] && h.trangThai !== f['trang-thai']) return false;
    if (f['ma-gd'] && h.maGD !== f['ma-gd']) return false;
    if (!this.matchNLD(h.nguoiKeKhai[0]?.nhanVienId)) return false;
    return this.matchKw(`${h.soHoSo} ${h.ten} ${h.loaiThuTuc} ${h.maGD ?? ''}`);
  }));

  readonly tuChoiLoc = computed(() => this.tuChoi().filter((r) => {
    if (this.tuChoiNguon() && r.nguon !== this.tuChoiNguon()) return false;
    const f = this.filters();
    if (f['ma-gd'] && r.maGD !== f['ma-gd']) return false;
    if (f['trang-thai'] && r.trangThai !== f['trang-thai']) return false;
    if (!this.matchNLD(r.nhanVienNghiId)) return false;
    return this.matchKw(`${r.moTa} ${r.maGD ?? ''} ${r.maLoi ?? ''} ${r.maTuongQuan ?? ''}`);
  }));

  /** Count sống 4 tab (severity: T1 quá hạn · T3 bị từ chối · T4 quá SLA). */
  readonly tabCounts = computed(() => ({
    t1: { count: this.taiLieu().length, sev: this.taiLieu().filter((t) => t.quaHan).length },
    t2: { count: this.nguoiThamGia().filter((n) => n.trangThai === 'hieu-luc').length, sev: this.lanDongBo().trangThai === 'cho-xac-nhan' ? this.lanDongBo().nhomXungDot.filter((x) => !x.ketQua).length : 0 },
    t3: { count: this.boHoSo().length, sev: this.boHoSo().filter((h) => h.trangThai === 'bi-tu-choi').length },
    t4: { count: this.tuChoi().filter((r) => r.trangThai !== 'dong').length, sev: this.tuChoi().filter((r) => r.coHan === 'qua-han').length },
  }));

  taiLieuOf(id: string): InsM06TaiLieu | undefined { return this.taiLieu().find((t) => t.id === id); }
  boHoSoOf(id: string): InsM06BoHoSo | undefined { return this.boHoSo().find((h) => h.id === id); }
  tuChoiOf(id: string): InsM06TuChoi | undefined { return this.tuChoi().find((r) => r.id === id); }
  thuTucOf(ma: string): InsM06ThuTuc | undefined { return this.thuTuc().find((t) => t.maThuTuc === ma); }

  /** BQA-13: map 1 dòng danh mục M08 (InsM08LoaiThuTuc) → shape M06 (InsM06ThuTuc). Ánh xạ mã cũ↔mới
   *  lấy từ M08.anhXa(); độ tin cậy 'cao-nn' của M08 gộp về 'cao' của M06; 600/600a (D02-LT) mang cờ
   *  `thuocM03` (chỉ nhãn — M06 KHÔNG lập bộ hồ sơ sự vụ bằng thủ tục thuộc M03). */
  private adaptThuTuc(t: InsM08LoaiThuTuc): InsM06ThuTuc {
    const ax = this.m08.anhXa().find((a) => a.maMoi === t.maThuTuc || a.maCu === t.maThuTuc);
    const doTinCay: InsM06DoTinCay = t.doTinCay === 'cao-nn' ? 'cao' : t.doTinCay;
    return {
      maThuTuc: t.maThuTuc, maPhieu: t.maPhieu, ten: t.ten, bieuMauChinh: t.bieuMauChinh,
      hieuLucTu: t.khoangHL.tu, hieuLucDen: t.khoangHL.den, trangThai: t.trangThai,
      phienBan: t.trangThai === 'het-hieu-luc' ? 'v1' : 'v2',
      nhanNguon: t.nguon, doTinCay, laiGopSo: t.coLai600o,
      ngoaiPhamVi: t.ngoaiPhamVi, lyDoNgoaiPhamVi: t.lyDoNgoaiPhamVi,
      thuocM03: t.phanHeChu === 'm03',
      anhXa: ax ? { maCu: ax.maCu, maMoi: ax.maMoi, ghiChu: ax.ghiChu } : undefined,
    };
  }

  /* ═════════ T1 — tài liệu: guard-pair tải xuống (hash lệch CHẶN) + log kể cả bị từ chối ═════════ */

  taiXuongReason(id: string): string | null {
    const t = this.taiLieuOf(id);
    if (!t) return 'Không tìm thấy tài liệu.';
    const pb = t.phienBan[t.phienBan.length - 1];
    if (!pb.hashKhop) return `Hash toàn vẹn LỆCH bản lưu (${pb.hash}) — hệ thống chặn tải, cần kiểm tra nguồn tệp.`;
    if (t.nhayCam) return null; // nhạy cảm: demo currentUser là C&B có quyền — người khác bị từ chối (seed log)
    return null;
  }
  taiXuong(id: string): { ok: boolean; reason?: string } {
    const t = this.taiLieuOf(id);
    if (!t) return { ok: false, reason: 'Không tìm thấy tài liệu.' };
    const reason = this.taiXuongReason(id);
    // Lượt tải BỊ TỪ CHỐI vẫn phải ghi log — audit offline thì chặn cả hành động
    if (!this.ghi({ nguoi: this.currentUser, hanhDong: reason ? `Tải "${t.ten}" — BỊ TỪ CHỐI: ${reason}` : `Tải xuống "${t.ten}" (phiên bản ${t.phienBan.length})`, nhanVienId: t.nhanVienId, biTuChoi: !!reason })) return this.chan();
    if (reason) {
      this.taiLieu.update((l) => l.map((x) => x.id === id ? { ...x, log: [...x.log, { at: demoNow(), nguoi: this.currentUser, hanhDong: `Tải xuống — BỊ TỪ CHỐI (${reason})`, biTuChoi: true }] } : x));
      return { ok: false, reason };
    }
    this.taiLieu.update((l) => l.map((x) => x.id === id ? { ...x, log: [...x.log, { at: demoNow(), nguoi: this.currentUser, hanhDong: 'Tải xuống' }] } : x));
    return { ok: true };
  }
  xemTaiLieu(id: string): { ok: boolean; reason?: string } {
    const t = this.taiLieuOf(id);
    if (!t) return { ok: false, reason: 'Không tìm thấy tài liệu.' };
    if (!this.ghi({ nguoi: this.currentUser, hanhDong: `Xem tài liệu "${t.ten}"${t.nhayCam ? ' (nhạy cảm y tế — ghi log)' : ''}`, nhanVienId: t.nhanVienId })) return this.chan();
    this.taiLieu.update((l) => l.map((x) => x.id === id ? { ...x, log: [...x.log, { at: demoNow(), nguoi: this.currentUser, hanhDong: 'Xem tài liệu' }] } : x));
    return { ok: true };
  }

  /* ═════════ T2 — ngừng hiệu lực bulk (thành công một phần + retry idempotent) ═════════ */

  private ngungSkipReason(n: InsM06NguoiThamGia): string | null {
    if (n.trangThai === 'ngung') return 'Đã ngừng hiệu lực từ trước — chạy lại không sinh trùng.';
    if (n.dangBiSuaBoi) return `Đang bị ${n.dangBiSuaBoi} sửa — chặn thao tác ghi.`;
    return null;
  }
  ngungPreview(ids: string[]): { eligible: number; blocked: { reason: string; count: number }[] } {
    const map = new Map<string, number>();
    let eligible = 0;
    for (const id of ids) {
      const n = this.nguoiThamGia().find((x) => x.id === id);
      const reason = n ? this.ngungSkipReason(n) : 'Không tìm thấy bản ghi.';
      if (reason) map.set(reason, (map.get(reason) ?? 0) + 1); else eligible++;
    }
    return { eligible, blocked: [...map].map(([reason, count]) => ({ reason, count })) };
  }
  ngungHieuLuc(ids: string[], lyDo: string): M06BulkResult | { ok: false; reason: string } {
    if (!this.ghi({ nguoi: this.currentUser, hanhDong: `Ngừng hiệu lực ${ids.length} người tham gia (xóa = ngừng có lý do)`, lyDo })) return this.chan();
    const skipped: { id: string; reason: string }[] = [];
    let done = 0;
    const at = demoNow();
    this.nguoiThamGia.update((l) => l.map((n) => {
      if (!ids.includes(n.id)) return n;
      const reason = this.ngungSkipReason(n);
      if (reason) { skipped.push({ id: n.id, reason }); return n; }
      done++;
      return { ...n, trangThai: 'ngung' as const, ngungInfo: { lyDo, nguoi: this.currentUser, at } };
    }));
    this.lastBulk.set({ action: 'ngung-hieu-luc', skipped });
    return { done, skipped };
  }

  /** Chạy lại lần nhập — idempotent theo mã lần nhập; chỉ nhóm sai chạy lại, lỗi tạm thời tự qua. */
  chayLaiLanNhap(): { ok: boolean; reason?: string; daSua?: number; conLoi?: number } {
    const ln = this.lanNhap();
    if (!this.ghi({ nguoi: this.currentUser, hanhDong: `Chạy lại lần nhập ${ln.ma} (idempotent — chỉ nhóm sai, không sinh trùng)` })) return this.chan();
    const qua = ln.nhomSai.filter((d) => d.tamThoi);
    const conLoi = ln.nhomSai.filter((d) => !d.tamThoi);
    this.lanNhap.set({
      ...ln, soLanChay: ln.soLanChay + 1,
      nhomDung: [...ln.nhomDung, ...qua.map((d) => ({ dong: d.dong, noiDung: `${d.noiDung} (qua ở lần chạy ${ln.soLanChay + 1})` }))],
      nhomSai: conLoi,
      trangThai: conLoi.length ? 'ghi-nhan-mot-phan' : 'ghi-nhan-toan-bo',
    });
    return { ok: true, daSua: qua.length, conLoi: conLoi.length };
  }

  /** Ghi sau bấm lưu (nhóm đúng) — tách nhóm đúng/sai, CHỈ ghi khi người dùng bấm. */
  ghiNhanLanNhap(): { ok: boolean; reason?: string } {
    const ln = this.lanNhap();
    if (ln.trangThai !== 'da-kiem-tra' && ln.trangThai !== 'ghi-nhan-mot-phan') return { ok: false, reason: 'Lần nhập không ở trạng thái ghi được.' };
    if (!this.ghi({ nguoi: this.currentUser, hanhDong: `Ghi nhận nhóm đúng lần nhập ${ln.ma}: ${ln.nhomDung.length} nhóm dòng` })) return this.chan();
    this.lanNhap.set({ ...ln, trangThai: ln.nhomSai.length ? 'ghi-nhan-mot-phan' : 'ghi-nhan-toan-bo' });
    return { ok: true };
  }

  /* ═════════ T2 — đồng bộ: xử lý TỪNG xung đột (chọn giữ bên nào) rồi mới ghi nhận ═════════ */

  chonXungDot(xdId: string, ketQua: 'giu-hr' | 'giu-bh'): { ok: boolean; reason?: string } {
    const db = this.lanDongBo();
    const xd = db.nhomXungDot.find((x) => x.id === xdId);
    if (!xd) return { ok: false, reason: 'Không tìm thấy xung đột.' };
    if (!this.ghi({ nguoi: this.currentUser, hanhDong: `Xung đột ${xd.truong} (${insNhanVien(xd.nhanVienId)?.name}): chọn GIỮ ${ketQua === 'giu-hr' ? 'bên HR' : 'bên danh sách BH'}`, nhanVienId: xd.nhanVienId })) return this.chan();
    this.lanDongBo.set({ ...db, nhomXungDot: db.nhomXungDot.map((x) => x.id === xdId ? { ...x, ketQua } : x) });
    return { ok: true };
  }
  ghiNhanDongBoReason(): string | null {
    const db = this.lanDongBo();
    if (db.trangThai !== 'cho-xac-nhan') return 'Lần đồng bộ không ở trạng thái Chờ xác nhận.';
    const treo = db.nhomXungDot.filter((x) => !x.ketQua).length;
    if (treo) return `Còn ${treo} xung đột chưa chọn kết quả — hệ thống KHÔNG tự giải, phải xử lý từng dòng.`;
    return null;
  }
  ghiNhanDongBo(): { ok: boolean; reason?: string } {
    const reason = this.ghiNhanDongBoReason();
    if (reason) return { ok: false, reason };
    const db = this.lanDongBo();
    if (!this.ghi({ nguoi: this.currentUser, hanhDong: `Ghi nhận lần đồng bộ ${db.ma}: thêm ${db.nhomThem.length} · cập nhật ${db.nhomCapNhat.length} · xung đột đã xử ${db.nhomXungDot.length}` })) return this.chan();
    // áp kết quả xung đột được chọn vào danh sách (chỉ trường cấu hình bị ghi đè)
    this.nguoiThamGia.update((l) => l.map((n) => {
      const xd = db.nhomXungDot.find((x) => x.nhanVienId === n.nhanVienId && x.ketQua);
      if (!xd) return n;
      if (xd.truong === 'Số thẻ BHYT' && xd.ketQua === 'giu-hr') return { ...n, soThe: xd.benHR.split(' ')[0] };
      return n;
    }));
    this.lanDongBo.set({ ...db, trangThai: 'da-ghi-nhan' });
    return { ok: true };
  }

  /* ═════════ T3 — bộ hồ sơ: nộp guard + maker-checker + gộp sổ ═════════ */

  nopBoHoSoReason(id: string): string | null {
    const h = this.boHoSoOf(id);
    if (!h) return 'Không tìm thấy bộ hồ sơ.';
    if (h.trangThai === 'cho-mo-cua-so-nop') return `Ngoài cửa sổ nộp theo quý — chờ mở cửa sổ kế: ${h.ngayMoCuaSoKe}.`;
    if (h.trangThai !== 'chua-gui') return `Chỉ nộp được bộ hồ sơ Chưa gửi — hiện là "${M06_BOHOSO_LABEL[h.trangThai]}".`;
    const loi = h.nguoiKeKhai.filter((k) => k.ghiChuLoi).length;
    if (loi) return `Còn ${loi} người kê khai mang ghi chú lỗi — còn lỗi CHẶN NỘP.`;
    if (h.gopSoId) {
      const gs = this.gopSo();
      if (gs.id === h.gopSoId && gs.khoangTrung.some((k) => !k.daXacNhan)) {
        return 'Gộp sổ còn khoảng trùng CHƯA được người dùng xác nhận — xác nhận trước khi nộp.';
      }
    }
    return null;
  }
  nopBoHoSo(id: string): { ok: boolean; reason?: string } {
    const reason = this.nopBoHoSoReason(id);
    if (reason) return { ok: false, reason };
    const h = this.boHoSoOf(id)!;
    if (!this.ghi({ nguoi: this.currentUser, hanhDong: `Gửi duyệt bộ hồ sơ ${h.soHoSo} (maker: ${this.currentUser} — checker phải KHÁC maker)` })) return this.chan();
    this.boHoSo.update((l) => l.map((x) => x.id === id ? { ...x, trangThai: 'cho-duyet' as const } : x));
    return { ok: true };
  }
  duyetBoHoSo(id: string, nguoiDuyet: string): { ok: boolean; reason?: string } {
    const h = this.boHoSoOf(id);
    if (!h || h.trangThai !== 'cho-duyet') return { ok: false, reason: 'Bộ hồ sơ không ở trạng thái Chờ duyệt.' };
    if (nguoiDuyet === h.nguoiLap) return { ok: false, reason: 'Maker-checker: người duyệt phải KHÁC người lập.' };
    if (!this.ghi({ nguoi: nguoiDuyet, hanhDong: `Duyệt bộ hồ sơ ${h.soHoSo} (checker ≠ maker)` })) return this.chan();
    this.boHoSo.update((l) => l.map((x) => x.id === id ? { ...x, trangThai: 'da-duyet' as const, nguoiDuyet } : x));
    return { ok: true };
  }

  /** Danh mục: bị tham chiếu → CHỈ `Ngừng sử dụng` (guard-pair xóa). */
  xoaDanhMucReason(ma: string): string | null {
    const dung = this.boHoSo().filter((h) => h.loaiThuTuc === ma).length;
    if (dung) return `Mã ${ma} đang được ${dung} bộ hồ sơ tham chiếu — không xóa được, chỉ "Ngừng sử dụng".`;
    return null;
  }
  /** BQA-13: M06 KHÔNG tự quyết danh mục — chuyển ghi sang M08 (nguồn duy nhất); M06 vẫn ghi audit lượt yêu cầu. */
  ngungSuDungDanhMuc(ma: string): { ok: boolean; reason?: string } {
    const t = this.thuTucOf(ma);
    if (!t) return { ok: false, reason: 'Không tìm thấy mã thủ tục trong danh mục (M08).' };
    if (!this.ghi({ nguoi: this.currentUser, hanhDong: `Yêu cầu ngừng sử dụng thủ tục ${ma} → chuyển M08 (danh mục nguồn duy nhất)` })) return this.chan();
    return this.m08.ngungThuTuc(ma);
  }

  /* ── GỘP SỔ (lai duy nhất): xác nhận khoảng trùng → sinh D02-LT giảm trùng sang M03 ── */

  xacNhanKhoangTrung(ktId: string): { ok: boolean; reason?: string; d02?: { ma: string; correlationId: string } } {
    const gs = this.gopSo();
    const kt = gs.khoangTrung.find((k) => k.id === ktId);
    if (!kt) return { ok: false, reason: 'Không tìm thấy khoảng trùng.' };
    if (kt.daXacNhan) return { ok: false, reason: 'Khoảng trùng đã xác nhận — chạy lại KHÔNG sinh dòng trùng.' };
    if (!this.ghi({ nguoi: this.currentUser, hanhDong: `Xác nhận khoảng trùng ${kt.tu} – ${kt.den} (gộp sổ ${gs.id}) → sinh dòng D02-LT giảm trùng sang M03`, nhanVienId: gs.nhanVienId })) return this.chan();
    const at = demoNow();
    // BQA-10: idempotent — chỉ ĐẨY sang M03 khi CHƯA có dòng D02-LT (tái dùng nếu đã có, không sinh trùng).
    let d02 = gs.dongD02LT;
    if (!d02) {
      const correlationId = insNextCorrelationId();
      const h = this.boHoSoOf(gs.boHoSoId);
      const nv = insNhanVien(gs.nhanVienId);
      const ky = h?.thangNam === '07/2026' ? 'k07' : h?.thangNam === '06/2026' ? 'k06' : 'k08';
      const res = this.m03.nhanDongGiamTrungTuM06({
        ky, donViId: 'dv1', maBHXH: nv?.maBHXH ?? 'HN-070913', nhanVienId: gs.nhanVienId,
        khoang: { tu: kt.tu, den: kt.den }, maHoSoGoc: h?.soHoSo ?? gs.boHoSoId, correlationId,
      });
      d02 = { ma: res.maItem, correlationId, ghiChu: '', at, loM03: res.maLo };
    }
    this.gopSo.set({
      ...gs,
      khoangTrung: gs.khoangTrung.map((k) => k.id === ktId ? { ...k, daXacNhan: true, nguoiXacNhan: this.currentUser, at } : k),
      dongD02LT: { ...d02, ghiChu: `Giảm trùng ${kt.tu} – ${kt.den} — đã đẩy sang M03 (item ${d02.ma}, lô ${d02.loM03}) chờ kiểm tra/duyệt; link 2 chiều`, at },
      nhanhD02: 'cho-m03-duyet',
    });
    return { ok: true, d02: { ma: d02.ma, correlationId: d02.correlationId } };
  }

  /** BQA-10: trạng thái nhánh D02-LT giảm trùng đọc SỐNG từ M03 qua maItem (link 2 chiều). */
  nhanhD02Song(): InsM06NhanhTrangThai {
    const gs = this.gopSo();
    if (!gs.dongD02LT) return gs.nhanhD02;
    const it = this.m03.item(gs.dongD02LT.ma);
    if (!it) return 'cho-m03-duyet';
    if (it.ketQuaCQ !== null || it.trangThai === 'duoc-chap-nhan' || it.trangThai === 'bi-tu-choi') return 'co-ket-qua';
    return 'cho-m03-duyet';
  }

  /** Guard-pair đóng bộ hồ sơ gộp sổ: CẢ 2 nhánh phải có kết quả. */
  dongBoHoSoGopSoReason(boHoSoId: string): string | null {
    const gs = this.gopSo();
    if (gs.boHoSoId !== boHoSoId) return 'Bộ hồ sơ không gắn gộp sổ.';
    const thieu: string[] = [];
    if (gs.nhanhTK1 !== 'co-ket-qua') thieu.push(`nhánh TK1-TS: ${M06_NHANH_LABEL[gs.nhanhTK1]}`);
    // BQA-10: nhánh D02-LT đọc trạng thái SỐNG bên M03 (qua correlation/maItem), không dùng cờ tĩnh M06.
    const d02 = this.nhanhD02Song();
    if (d02 !== 'co-ket-qua' && d02 !== 'khong-can') thieu.push(`nhánh D02-LT giảm trùng (M03): ${M06_NHANH_LABEL[d02]}`);
    if (thieu.length) return `Bộ hồ sơ gộp sổ chỉ đóng khi CẢ 2 nhánh có kết quả — ${thieu.join(' · ')}.`;
    return null;
  }
  dongBoHoSoGopSo(boHoSoId: string): { ok: boolean; reason?: string } {
    const reason = this.dongBoHoSoGopSoReason(boHoSoId);
    if (reason) return { ok: false, reason };
    if (!this.ghi({ nguoi: this.currentUser, hanhDong: `Đóng bộ hồ sơ gộp sổ ${boHoSoId} (2 nhánh đều có kết quả)` })) return this.chan();
    this.boHoSo.update((l) => l.map((x) => x.id === boHoSoId ? { ...x, trangThai: 'dong' as const } : x));
    return { ok: true };
  }

  /* ═════════ T4 — hàng đợi từ chối ═════════ */

  /** Cổng GD: "Tạo lô sửa và nộp lại" → ghi chú chuyển ngữ cảnh M03, GIỮ link. */
  taoLoSuaNopLai(id: string): { ok: boolean; reason?: string; loSua?: string } {
    const r = this.tuChoiOf(id);
    if (!r || r.nguon !== 'cong-gd') return { ok: false, reason: 'Chỉ áp dụng dòng nguồn cổng giao dịch.' };
    if (r.trangThai === 'da-tao-lo-nop-lai' || r.trangThai === 'da-nop-lai') return { ok: false, reason: 'Đã tạo lô sửa — chạy lại không sinh trùng (chống trùng mã GD + lần nộp).' };
    const loSua = `LO-SUA-2026-08-${r.maGD?.slice(-2) ?? '00'}`;
    if (!this.ghi({ nguoi: this.currentUser, hanhDong: `Tạo lô sửa và nộp lại cho ${r.maGD} (lần nộp ${(r.lanNop ?? 1) + 1}) → chuyển ngữ cảnh M03, giữ link ${loSua}` })) return this.chan();
    this.tuChoi.update((l) => l.map((x) => x.id === id ? { ...x, trangThai: 'da-tao-lo-nop-lai' as const, loSuaM03: loSua } : x));
    return { ok: true, loSua };
  }

  /** BQA-23: cổng GD "Đã tạo lô nộp lại" → NỘP LẠI (cổng ghi nhận) → `Đã nộp lại` → cho Đóng.
   *  Thêm bước hoàn tất còn thiếu (trước đây kẹt ở "Đã tạo lô nộp lại", không đạt da-nop-lai). */
  nopLaiTuChoi(id: string): { ok: boolean; reason?: string } {
    const r = this.tuChoiOf(id);
    if (!r || r.nguon !== 'cong-gd') return { ok: false, reason: 'Chỉ áp dụng dòng nguồn cổng giao dịch.' };
    if (r.trangThai !== 'da-tao-lo-nop-lai') return { ok: false, reason: 'Chỉ nộp lại khi đã tạo lô nộp lại.' };
    const lan = (r.lanNop ?? 1) + 1;
    if (!this.ghi({ nguoi: this.currentUser, hanhDong: `Nộp lại ${r.maGD} (lần nộp ${lan}, lô ${r.loSuaM03}) — cổng ghi nhận → Đã nộp lại` })) return this.chan();
    this.tuChoi.update((l) => l.map((x) => x.id === id ? {
      ...x, trangThai: 'da-nop-lai' as const, lanNop: lan,
      lichSu: [...(x.lichSu ?? []), { lan, at: demoNow(), ketQua: `Đã nộp lại (lô ${x.loSuaM03}) — cổng đã ghi nhận, chờ kết quả` }],
    } : x));
    return { ok: true };
  }

  /** Exception M04 — 3 đường ra chọn 1; (c) lý do BẮT BUỘC + phản hồi M04 theo mã tương quan. */
  chonDuongRaException(id: string, duongRa: 'a' | 'b' | 'c', lyDo?: string): { ok: boolean; reason?: string } {
    const r = this.tuChoiOf(id);
    if (!r || r.nguon !== 'exception-m04') return { ok: false, reason: 'Chỉ áp dụng dòng exception M04.' };
    if (r.trangThai === 'da-phan-hoi-ket-qua' || r.trangThai === 'dong') return { ok: false, reason: 'Exception đã phản hồi kết quả.' };
    if (duongRa === 'c' && !lyDo?.trim()) return { ok: false, reason: 'Đường ra (c) "không thuộc hồ sơ" — lý do là BẮT BUỘC.' };
    const nhan = M06_DUONG_RA.find((d) => d.key === duongRa)!.label;
    if (!this.ghi({ nguoi: this.currentUser, hanhDong: `Exception ${r.maTuongQuan}: chọn ${nhan}${duongRa === 'c' ? ' — phản hồi M04 qua luồng chuẩn' : ''}`, lyDo: lyDo?.trim(), nhanVienId: r.nhanVienNghiId })) return this.chan();
    this.tuChoi.update((l) => l.map((x) => x.id === id ? {
      ...x, duongRa, owner: this.currentUser,
      trangThai: duongRa === 'c' ? 'da-phan-hoi-ket-qua' as const : 'dang-xu-ly' as const,
      lyDoKhongThuoc: duongRa === 'c' ? lyDo?.trim() : x.lyDoKhongThuoc,
      phanHoiM04: duongRa === 'c' ? `Không thuộc hồ sơ — ${lyDo?.trim()} (phản hồi ${x.maTuongQuan} về M04)` : x.phanHoiM04,
    } : x));
    return { ok: true };
  }

  /** BQA-23: đường ra (a)/(b) đang "Đang xử lý" → HOÀN TẤT: bộ hồ sơ/360 có kết quả thì phản hồi
   *  M04 theo mã tương quan → `Đã phản hồi kết quả` → cho Đóng (trước đây kẹt "Đang xử lý"). */
  hoanTatXuLyException(id: string, ketQua: string): { ok: boolean; reason?: string } {
    const r = this.tuChoiOf(id);
    if (!r || r.nguon !== 'exception-m04') return { ok: false, reason: 'Chỉ áp dụng dòng exception M04.' };
    if (r.trangThai !== 'dang-xu-ly') return { ok: false, reason: 'Chỉ hoàn tất khi đang xử lý (đã chọn đường ra a/b).' };
    if (!ketQua.trim()) return { ok: false, reason: 'Kết quả xử lý bắt buộc để phản hồi M04.' };
    const nhan = r.duongRa === 'a' ? 'bộ hồ sơ sự vụ' : 'hồ sơ 360 (audit)';
    if (!this.ghi({ nguoi: this.currentUser, hanhDong: `Hoàn tất xử lý exception ${r.maTuongQuan} qua ${nhan} → phản hồi M04`, lyDo: ketQua.trim(), nhanVienId: r.nhanVienNghiId })) return this.chan();
    this.tuChoi.update((l) => l.map((x) => x.id === id ? {
      ...x, trangThai: 'da-phan-hoi-ket-qua' as const,
      phanHoiM04: `${ketQua.trim()} (phản hồi ${x.maTuongQuan} về M04 qua ${nhan})`,
    } : x));
    return { ok: true };
  }

  /** `Đóng` chỉ sau khi phản hồi được ghi nhận. */
  dongTuChoiReason(id: string): string | null {
    const r = this.tuChoiOf(id);
    if (!r) return 'Không tìm thấy dòng.';
    if (r.nguon === 'exception-m04' && r.trangThai !== 'da-phan-hoi-ket-qua') return 'Chỉ đóng sau khi phản hồi kết quả về M04 được ghi nhận.';
    if (r.nguon === 'cong-gd' && r.trangThai !== 'da-nop-lai') return 'Chỉ đóng sau khi đã nộp lại và cổng ghi nhận.';
    return null;
  }
  dongTuChoi(id: string): { ok: boolean; reason?: string } {
    const reason = this.dongTuChoiReason(id);
    if (reason) return { ok: false, reason };
    if (!this.ghi({ nguoi: this.currentUser, hanhDong: `Đóng dòng từ chối ${id}` })) return this.chan();
    this.tuChoi.update((l) => l.map((x) => x.id === id ? { ...x, trangThai: 'dong' as const } : x));
    return { ok: true };
  }

  /* ═════════ Kết xuất 4 tab — 4 thông báo chặn + số bản ghi khớp + log ═════════ */

  ketXuat(tab: M06TabKey): { ok: boolean; reason?: string; soBanGhi?: number } {
    const chanMap: Record<M06TabKey, boolean> = {
      t1: this.taiLieuLoc().some((t) => t.nhayCam),
      t2: this.lanDongBo().trangThai === 'cho-xac-nhan',
      t3: this.boHoSo().some((h) => h.nguoiKeKhai.some((k) => k.ghiChuLoi)),
      t4: this.tuChoi().some((r) => r.nhomNguyenNhan === 'Chưa phân loại' && r.trangThai !== 'dong'),
    };
    const soBanGhi = { t1: this.taiLieuLoc().length, t2: this.nguoiThamGiaLoc().length, t3: this.boHoSoLoc().length, t4: this.tuChoiLoc().length }[tab];
    if (chanMap[tab]) {
      const reason = M06_KET_XUAT_CHAN[tab];
      if (!this.ghi({ nguoi: this.currentUser, hanhDong: `Kết xuất ${M06_TAB_LABEL[tab]} — BỊ CHẶN: ${reason}`, biTuChoi: true })) return this.chan();
      return { ok: false, reason };
    }
    if (!this.ghi({ nguoi: this.currentUser, hanhDong: `Kết xuất ${M06_TAB_LABEL[tab]}: ${soBanGhi} bản ghi (khớp số dòng lưới đang lọc)` })) return this.chan();
    return { ok: true, soBanGhi };
  }

  /* ═════════ B — Định danh · Quá trình · Audit ═════════ */

  nguoiThamGiaCua(nhanVienId: string): InsM06NguoiThamGia | undefined {
    return this.nguoiThamGia().find((n) => n.nhanVienId === nhanVienId);
  }

  /** Sửa định danh: số sổ trùng người khác → CHẶN + CHỈ NGƯỜI ĐANG GIỮ; audit before/after; lý do bắt buộc. */
  suaDinhDanh(nhanVienId: string, thayDoi: { soSo?: string; soThe?: string; ngayCapThe?: string }, lyDo: string): { ok: boolean; reason?: string } {
    const n = this.nguoiThamGiaCua(nhanVienId);
    if (!n) return { ok: false, reason: 'NLĐ chưa có trong danh sách người tham gia.' };
    if (!lyDo.trim()) return { ok: false, reason: 'Sửa định danh bắt buộc có lý do (audit before/after).' };
    if (thayDoi.soThe && !thayDoi.ngayCapThe && !n.ngayCapThe) return { ok: false, reason: 'Số thẻ BHYT bắt buộc trước — sau đó kiểm Ngày cấp (đúng thứ tự thông báo).' };
    if (thayDoi.soSo && thayDoi.soSo !== n.soSo) {
      const giu = this.nguoiThamGia().find((x) => x.soSo === thayDoi.soSo && x.nhanVienId !== nhanVienId);
      if (giu) return { ok: false, reason: `Số sổ ${thayDoi.soSo} đang thuộc ${insNhanVien(giu.nhanVienId)?.name} (${insNhanVien(giu.nhanVienId)?.code}) — CHẶN, chỉ người đang giữ.` };
    }
    const truoc = `soSo=${n.soSo} · soThe=${n.soThe} · ngayCap=${n.ngayCapThe}`;
    const sau = `soSo=${thayDoi.soSo ?? n.soSo} · soThe=${thayDoi.soThe ?? n.soThe} · ngayCap=${thayDoi.ngayCapThe ?? n.ngayCapThe}`;
    if (!this.ghi({ nguoi: this.currentUser, hanhDong: 'Sửa định danh (tab không tự đổi trạng thái tham gia)', nhanVienId, truoc, sau, lyDo: lyDo.trim() })) return this.chan();
    this.nguoiThamGia.update((l) => l.map((x) => x.nhanVienId === nhanVienId ? { ...x, ...thayDoi } : x));
    return { ok: true };
  }

  quaTrinhCua(nhanVienId: string): InsM06DongQuaTrinh[] {
    const rows = this.quaTrinh().filter((q) => q.nhanVienId === nhanVienId);
    if (rows.length) return rows;
    // fallback tổng hợp ổn định cho NLĐ chưa seed chi tiết (derive từ _core — không bịa random)
    const nv = insNhanVien(nhanVienId);
    if (!nv) return [];
    return [{
      id: `qt-syn-${nhanVienId}`, nhanVienId, tuThang: '01/2025', denThang: '', donVi: nv.dept + ' — ' + nv.maBHXH,
      maBHXHDonVi: nv.maBHXH, phanDoan: 'bat-buoc', ngayPhatSinh: '02/01/2025', ngayHieuLuc: '01/01/2025',
      ngayHanXuLy: '31/01/2025', trangThai: 'mo', phienBan: 1,
    }];
  }
  mucLuongCua(nhanVienId: string): InsM06MucLuong[] {
    const rows = this.mucLuong().filter((m) => m.nhanVienId === nhanVienId);
    if (rows.length) return rows;
    const nv = insNhanVien(nhanVienId);
    if (!nv) return [];
    return [{ id: `ml-syn-${nhanVienId}`, nhanVienId, tu: '01/2025', den: '', mucLuong: nv.salary, cauPhan: 'Lương cơ bản', nguon: 'Payroll', suKienNguon: 'HĐLĐ hiện hành', ruleVersion: 'RS-LUONG-2025.01' }];
  }

  /** Khóa dòng quá trình (bulk) — ghi lý do; không ghi đè dòng đã khóa. */
  khoaDong(ids: string[], lyDo: string): M06BulkResult | { ok: false; reason: string } {
    if (!this.ghi({ nguoi: this.currentUser, hanhDong: `Khóa ${ids.length} dòng quá trình`, lyDo })) return this.chan();
    const skipped: { id: string; reason: string }[] = [];
    let done = 0;
    const luc = demoNow();
    this.quaTrinh.update((l) => l.map((q) => {
      if (!ids.includes(q.id)) return q;
      if (q.trangThai === 'khoa') { skipped.push({ id: q.id, reason: 'Dòng đã khóa — không ghi đè dòng khóa.' }); return q; }
      done++;
      return { ...q, trangThai: 'khoa' as const, coKhoa: { nguoi: this.currentUser, luc, lyDo } };
    }));
    this.lastBulk.set({ action: 'khoa-dong', skipped });
    return { done, skipped };
  }

  /** Mở khóa (bulk) — maker-checker (người duyệt ≠ người mở) + SINH PHIÊN BẢN MỚI, giữ chuỗi. */
  moKhoaDong(ids: string[], lyDo: string, nguoiDuyet: string): M06BulkResult | { ok: false; reason: string } {
    if (nguoiDuyet === this.currentUser) return { ok: false, reason: 'Maker-checker: người duyệt mở khóa phải KHÁC người thao tác.' };
    if (!this.ghi({ nguoi: this.currentUser, hanhDong: `Mở khóa ${ids.length} dòng quá trình (duyệt: ${nguoiDuyet}) — SINH PHIÊN BẢN MỚI`, lyDo })) return this.chan();
    const skipped: { id: string; reason: string }[] = [];
    let done = 0;
    const at = demoNow();
    this.quaTrinh.update((l) => l.map((q) => {
      if (!ids.includes(q.id)) return q;
      if (q.trangThai !== 'khoa') { skipped.push({ id: q.id, reason: 'Dòng không ở trạng thái Khóa.' }); return q; }
      done++;
      const pbMoi = q.phienBan + 1;
      return {
        ...q, trangThai: 'mo-lai' as const, phienBan: pbMoi, coKhoa: undefined,
        lichSuPhienBan: [
          ...(q.lichSuPhienBan ?? [{ phienBan: q.phienBan, nguoi: q.coKhoa?.nguoi ?? this.currentUser, at: q.coKhoa?.luc ?? at, lyDo: q.coKhoa?.lyDo ?? 'Khóa' }]),
          { phienBan: pbMoi, nguoi: this.currentUser, at, lyDo, nguoiDuyet },
        ],
      };
    }));
    this.lastBulk.set({ action: 'mo-khoa-dong', skipped });
    return { done, skipped };
  }

  /** Chế độ (T5): lượt xem chứng từ y tế bị từ chối theo quyền — VẪN ghi log. */
  xemChungTuYTeBiTuChoi(nhanVienId: string): { ok: boolean; reason: string } {
    const reason = 'Chứng từ y tế che theo quyền — tài khoản demo không có quyền tài liệu y tế của case chế độ.';
    if (!this.ghi({ nguoi: this.currentUser, hanhDong: `Xem chứng từ y tế (case chế độ) — BỊ TỪ CHỐI theo quyền`, nhanVienId, biTuChoi: true })) return { ok: false, reason: M06_AUDIT_CHAN };
    return { ok: false, reason };
  }

  /** Xuất nhật ký — bản thân lượt xuất tự ghi 1 dòng. */
  xuatNhatKy(phamVi: string): { ok: boolean; reason?: string; soDong?: number } {
    const soDong = this.audit().length;
    if (!this.ghi({ nguoi: this.currentUser, hanhDong: `Xuất nhật ký (${phamVi}) — ${soDong} dòng; lượt xuất tự ghi 1 dòng` })) return this.chan();
    return { ok: true, soDong };
  }
}
