import { ChangeDetectionStrategy, Component, TemplateRef, computed, inject, input, signal, viewChild } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { HrmAlert, HrmButton, HrmInput, HrmMessageService, HrmModalService, HrmTag, HrmTextarea } from 'hrm-ui';
import { InsLayerBadge, InsSectionLabel } from '../../_shared';
import { InsM05Store } from '../../_data/_m05-data';

/** M05-B · B3 Tính & giải thích — SIGNATURE "Calculation Explain" (ux-architecture M05-B):
 *  layout DỌC 4 khối: ① INPUT (lương căn cứ + chu kỳ đề nghị + số ngày thô) → ② RULE (công thức
 *  chữ + rule version + nguồn pháp lý + ngày hiệu lực — chip trust-style) → ③ BẢNG NGÀY BỊ TRỪ
 *  (từng ngày + lý do; footer "8 − 2 = 6 ngày") → ④ KẾT QUẢ (số tiền to + ins-layer-badge
 *  "Dự kiến nội bộ"). OVERRIDE đặt CẠNH kết quả hệ thống (2 cột song song — bất biến #3 giữ
 *  giá trị hệ thống nhìn thấy được) + duyệt/từ chối maker ≠ checker.
 *  Nút "Tính số ngày"/"Tính mức hưởng" chạy store (guard-pair `tinhLaiReason`). */
@Component({
  selector: 'ins-m05-b3',
  imports: [FormsModule, HrmAlert, HrmButton, HrmInput, HrmTag, HrmTextarea, InsLayerBadge, InsSectionLabel],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (c(); as c) {
      <div class="b3">
        <div class="b3__toolbar">
          <hrm-button size="sm" [disabled]="!!tinhReason()" (click)="tinhNgay()">Tính số ngày</hrm-button>
          <hrm-button size="sm" variant="primary" [disabled]="!!tinhReason()" (click)="tinhTien()">Tính mức hưởng</hrm-button>
          @if (tinhReason(); as r) { <span class="b3__muted">{{ r }}</span> }
          <span class="b3__gap"></span>
          <span class="b3__trust" title="OPEN_QUESTION m05.md: chính sách làm tròn + nguồn TiLeC70A — Cần stakeholder xác nhận">
            Làm tròn & TiLeC70A: Cần stakeholder xác nhận</span>
        </div>

        @if (c.trangThai === 'cho-du-lieu-dong') {
          <hrm-alert type="warning" message="Chờ dữ liệu đóng — chưa tính được"
            [description]="'Exception ' + (c.exceptionDong?.id ?? '') + ' đang mở (AC-08 — M05 CHỈ ĐỌC dữ liệu đóng). Exception đóng → case tự chạy lại kiểm tra rồi mới tính.'" />
        }

        @if (c.ketQuaTinh; as kq) {
          <!-- ① INPUT -->
          <section class="b3__block">
            <div class="b3__blockhead"><span class="b3__no">①</span><ins-section-label text="Input" tone="muted" /></div>
            <div class="b3__inputgrid">
              <span class="b3__k">Lương căn cứ (mức BHXH gần nhất so với ngày cuối chu kỳ đề nghị)</span>
              <span class="b3__v">{{ kq.luongCanCu }}</span>
              <span class="b3__k">Chu kỳ đề nghị (16–15 cấu hình M08)</span>
              <span class="b3__v">{{ kq.chuKy }}</span>
              <span class="b3__k">Khoảng nghỉ đề nghị · số ngày thô (ngày lịch)</span>
              <span class="b3__v">{{ c.tuNgay }} – {{ c.denNgay }} · <b>{{ kq.soNgayTho }} ngày</b></span>
            </div>
          </section>

          <!-- ② RULE -->
          <section class="b3__block">
            <div class="b3__blockhead"><span class="b3__no">②</span><ins-section-label text="Rule áp dụng" tone="muted" /></div>
            <p class="b3__formula">{{ kq.congThucTien }}</p>
            <p class="b3__formula b3__formula--sub">Số ngày (nhóm 2 — ngoài [INS009-019]): KT − BĐ − lễ − CN → {{ kq.congThucNgay }}</p>
            <div class="b3__ruletags">
              <hrm-tag color="blue" size="sm">{{ kq.ruleVersion }}</hrm-tag>
              <hrm-tag color="purple" size="sm" variant="lighter">{{ kq.nguonPhapLy }}</hrm-tag>
              <hrm-tag color="green" size="sm" variant="lighter">hiệu lực {{ kq.ngayHieuLucRule }}</hrm-tag>
              <span class="b3__muted">Rule version + nguồn từ M08 — không hardcode.</span>
            </div>
          </section>

          <!-- ③ BẢNG NGÀY BỊ TRỪ -->
          <section class="b3__block">
            <div class="b3__blockhead"><span class="b3__no">③</span><ins-section-label text="Bảng giải thích từng ngày" tone="muted" [count]="kq.bangNgay.length" /></div>
            <table class="b3__table">
              <thead><tr><th>Ngày</th><th>Thứ</th><th>Tính hưởng?</th><th>Lý do</th></tr></thead>
              <tbody>
                @for (d of kq.bangNgay; track d.ngay) {
                  <tr [class.b3__row--cut]="!d.tinh">
                    <td class="b3__mono">{{ d.ngay }}</td>
                    <td>{{ d.thu }}</td>
                    <td>@if (d.tinh) { <span class="b3__yes">✓ Tính</span> } @else { <span class="b3__no-cell">✕ Bị trừ</span> }</td>
                    <td class="b3__td-reason">{{ d.lyDo }}</td>
                  </tr>
                }
              </tbody>
              <tfoot><tr><td colspan="4">{{ kq.soNgayTho }} ngày lịch − {{ kq.soNgayTho - kq.soNgay }} ngày bị trừ = <b>{{ kq.soNgay }} ngày tính hưởng</b></td></tr></tfoot>
            </table>
          </section>

          <!-- ④ KẾT QUẢ + OVERRIDE cạnh nhau -->
          <section class="b3__block">
            <div class="b3__blockhead"><span class="b3__no">④</span><ins-section-label text="Kết quả" tone="muted" /></div>
            <div class="b3__result">
              <div class="b3__rescol">
                <span class="b3__reslb">Hệ thống tính</span>
                <span class="b3__resnum">{{ kq.soTien }}</span>
                <ins-layer-badge layer="du-kien" />
                <span class="b3__muted">{{ kq.luongCanCu }} ÷ 24 × {{ kq.soNgay }} ngày × 75%</span>
                <span class="b3__muted">Sổ phân tích: {{ kq.dongSoPhanTich }}</span>
              </div>
              <div class="b3__rescol" [class.b3__rescol--override]="c.override">
                @if (c.override; as ov) {
                  <span class="b3__reslb">Override <hrm-tag size="sm" [color]="ov.trangThai === 'cho-duyet' ? 'orange' : ov.trangThai === 'da-duyet' ? 'green' : 'red'">{{
                    ov.trangThai === 'cho-duyet' ? 'Chờ duyệt' : ov.trangThai === 'da-duyet' ? 'Đã duyệt' : 'Bị từ chối' }}</hrm-tag></span>
                  <span class="b3__resnum">{{ ov.sau }}</span>
                  <span class="b3__muted">Lý do: {{ ov.lyDo }}</span>
                  <span class="b3__muted">Người lập: {{ ov.nguoiDeXuat }}@if (ov.nguoiDuyet) { · người duyệt: {{ ov.nguoiDuyet }}} · {{ ov.at }}</span>
                  @if (ov.trangThai === 'cho-duyet') {
                    <div class="b3__ovactions">
                      <hrm-button size="sm" variant="primary" (click)="duyet(true)">Duyệt override</hrm-button>
                      <hrm-button size="sm" [danger]="true" (click)="duyet(false)">Từ chối</hrm-button>
                      <span class="b3__muted">Người lập ≠ người duyệt (maker–checker); ngưỡng duyệt theo tiền + loại (M08).</span>
                    </div>
                  }
                } @else {
                  <span class="b3__reslb">Override</span>
                  <span class="b3__muted">Chưa có override — hệ thống giữ SONG SONG giá trị gốc khi override.</span>
                  <hrm-button size="sm" [disabled]="!!ovReason()" (click)="openOverride()">Đề xuất override</hrm-button>
                  @if (ovReason(); as r) { <span class="b3__muted">{{ r }}</span> }
                }
              </div>
            </div>
          </section>
        } @else {
          <hrm-alert type="info" message="Chưa có kết quả tính cho case này"
            description="Case demo tính đầy đủ (bảng ngày bị trừ + override): CS-2026-0103 — Lý Gia Hân, ốm đau 05–12/08/2026. Số ngày ≤ 0 → chặn; thiếu ca làm việc → cảnh báo (LOCK m05.md)." />
        }
      </div>

      <!-- Modal đề xuất override -->
      <ng-template #ovTpl>
        <div class="b3__form">
          <p class="b3__muted">Override GIỮ SONG SONG giá trị hệ thống; không lý do KHÔNG lưu; case → Chờ duyệt override (người lập ≠ người duyệt).</p>
          <hrm-input [(ngModel)]="ovSauModel" placeholder="Số tiền override (VD 2.400.000)" size="sm" />
          <hrm-textarea [(ngModel)]="ovLyDoModel" placeholder="Lý do (bắt buộc)…" [minRows]="3" [status]="formError() ? 'error' : ''" />
          @if (formError()) { <span class="b3__err">{{ formError() }}</span> }
        </div>
      </ng-template>
    }
  `,
  host: { class: 'ins-m05-b3' },
  styles: [`
    :host { display: block; }
    .b3 { display: flex; flex-direction: column; gap: 14px; max-width: 920px; }
    .b3__toolbar { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
    .b3__gap { flex: 1; }
    .b3__trust { font-size: var(--fs-11); font-weight: 500; color: var(--warning-text); background: var(--warning-bg);
      border: 1px dashed var(--warning-base, var(--warning-text)); border-radius: var(--radius-full); padding: 1px 9px; cursor: help; }

    .b3__block { display: flex; flex-direction: column; gap: 8px; border: 1px solid var(--border-sub);
      border-radius: var(--radius-lg); background: var(--bg-surface); padding: 12px 14px; }
    .b3__blockhead { display: flex; align-items: center; gap: 8px; }
    .b3__no { font-size: var(--fs-14); font-weight: 700; color: var(--primary-base); }

    .b3__inputgrid { display: grid; grid-template-columns: minmax(280px, 1.4fr) 1fr; gap: 6px 14px; align-items: baseline; }
    .b3__k { font-size: var(--fs-12); color: var(--text-sub); }
    .b3__v { font-size: var(--fs-13); font-weight: 600; color: var(--text-strong); font-variant-numeric: tabular-nums; }
    .b3__v b { font-weight: 700; }

    .b3__formula { margin: 0; font-size: var(--fs-14); font-weight: 600; color: var(--text-strong); }
    .b3__formula--sub { font-size: var(--fs-12); font-weight: 500; color: var(--text-sub); }
    .b3__ruletags { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
    :host ::ng-deep .b3__ruletags .ant-tag { margin: 0; }

    .b3__table { width: 100%; border-collapse: collapse; font-size: var(--fs-12); }
    .b3__table th { text-align: left; padding: 5px 10px; color: var(--text-sub); font-weight: 600;
      background: var(--bg-surface-subtle); border-bottom: 1px solid var(--border-sub); }
    .b3__table td { padding: 5px 10px; border-bottom: 1px solid var(--border-soft); color: var(--text-body); }
    .b3__row--cut td { background: color-mix(in srgb, var(--error-bg) 42%, var(--bg-surface)); }
    .b3__mono { font-family: var(--font-mono, monospace); font-weight: 600; color: var(--text-strong); }
    .b3__yes { color: var(--success-text); font-weight: 600; }
    .b3__no-cell { color: var(--error-text); font-weight: 700; }
    .b3__td-reason { color: var(--text-sub); }
    .b3__table tfoot td { padding-top: 8px; border-bottom: 0; font-size: var(--fs-13); color: var(--text-sub); }
    .b3__table tfoot b { color: var(--text-strong); font-size: var(--fs-13); }

    .b3__result { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; align-items: stretch; }
    .b3__rescol { display: flex; flex-direction: column; align-items: flex-start; gap: 5px;
      border: 1px solid var(--border-soft); border-radius: var(--radius-md); padding: 12px 14px; }
    .b3__rescol--override { border-color: var(--warning-base, var(--warning-text)); background: color-mix(in srgb, var(--warning-bg) 35%, var(--bg-surface)); }
    .b3__reslb { display: inline-flex; align-items: center; gap: 6px; font-size: var(--fs-12); font-weight: 600; color: var(--text-sub); text-transform: uppercase; letter-spacing: .04em; }
    :host ::ng-deep .b3__reslb .ant-tag { margin: 0; text-transform: none; letter-spacing: 0; }
    .b3__resnum { font-size: var(--fs-24, 24px); font-weight: 700; color: var(--text-strong); font-variant-numeric: tabular-nums; line-height: 1.2; }
    .b3__ovactions { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin-top: 4px; }

    .b3__muted { margin: 0; font-size: var(--fs-12); color: var(--text-sub); }
    .b3__err { font-size: var(--fs-12); color: var(--error-text); }
    .b3__form { display: flex; flex-direction: column; gap: 8px; }
  `],
})
export class InsM05B3 {
  private readonly store = inject(InsM05Store);
  private readonly msg = inject(HrmMessageService);
  private readonly modal = inject(HrmModalService);

  readonly caseId = input.required<string>();
  protected readonly c = computed(() => this.store.caseOf(this.caseId()));
  protected readonly tinhReason = computed(() => this.store.tinhLaiReason(this.caseId()));
  protected readonly ovReason = computed(() => this.store.overrideReason(this.caseId()));

  protected tinhNgay(): void {
    const r = this.store.tinhSoNgay(this.caseId());
    r.ok ? this.msg.success(`Đã tính số ngày: ${this.c()?.ketQuaTinh?.congThucNgay}.`) : this.msg.error(r.reason ?? 'Không tính được.');
  }
  protected tinhTien(): void {
    const r = this.store.tinhMucHuong(this.caseId());
    r.ok ? this.msg.success(`Đã tính mức hưởng: ${this.c()?.ketQuaTinh?.soTien} (Dự kiến nội bộ) — sổ phân tích ghi dòng mới.`) : this.msg.error(r.reason ?? 'Không tính được.');
  }

  protected duyet(chapNhan: boolean): void {
    const r = this.store.duyetOverride(this.caseId(), chapNhan);
    if (!r.ok) { this.msg.error(r.reason ?? 'Không duyệt được.'); return; }
    this.msg.success(chapNhan ? 'Đã duyệt override — số hiện hành đổi, giá trị hệ thống giữ song song.' : 'Đã từ chối override — dùng lại giá trị hệ thống.');
  }

  /* modal đề xuất override */
  private dlg: { close: () => void } | null = null;
  protected readonly formError = signal('');
  private readonly ovSau = signal('');
  protected get ovSauModel(): string { return this.ovSau(); }
  protected set ovSauModel(v: string) { this.ovSau.set(v ?? ''); }
  private readonly ovLyDo = signal('');
  protected get ovLyDoModel(): string { return this.ovLyDo(); }
  protected set ovLyDoModel(v: string) { this.ovLyDo.set(v ?? ''); if (v?.trim()) this.formError.set(''); }
  private readonly ovTplRef = viewChild<TemplateRef<unknown>>('ovTpl');

  protected openOverride(): void {
    this.ovSau.set(''); this.ovLyDo.set(''); this.formError.set('');
    this.dlg = this.modal.open({
      title: 'Đề xuất override mức hưởng', content: this.ovTplRef()!, width: 460,
      footer: [
        { label: 'Hủy', onClick: () => this.dlg?.close() },
        { label: 'Lưu override', type: 'primary', onClick: () => {
          const sau = this.ovSau().trim();
          if (!sau) { this.formError.set('Nhập số tiền override.'); return; }
          const r = this.store.luuOverride(this.caseId(), sau, this.ovLyDo());
          if (!r.ok) { this.formError.set(r.reason ?? 'Không lưu được.'); return; }
          this.msg.success('Đã lưu override — case chuyển Chờ duyệt override (maker ≠ checker).');
          this.dlg?.close();
        } },
      ],
    });
  }
}
