  /** Nút hành động theo dòng: "Xác nhận" (san-sang → vào lô ngay, ở lại lưới) / "Bổ sung" (mở panel). */
  protected onPrimary(row: M02Row, e?: Event): void {
    e?.stopPropagation();
    if (row.primaryKind === 'confirm') {
      const r = this.store.bulkChuyenLo([row.id]);
      if (r.done && r.loBatchId) {
        // P6: hệ thống tự xếp đợt — HR ở lại lưới; toast nêu NƠI phân bổ (Kỳ + mã đợt rút gọn).
        const kyLabel = insKy(r.ky ?? '')?.label ?? '';
        this.msg.success(`✓ Đã xác nhận ${row.ten}${kyLabel ? ' · ' + kyLabel : ''} · Đợt #${r.loBatchId.slice(8)}`);
      } else if (r.daXacNhan) {
        // T5: đã xác nhận nhưng chưa xếp được đợt — dòng chuyển "Đã xác nhận", không mất tích.
        const c = this.store.change(row.id);
        this.msg.warning(`✓ Đã xác nhận · ⚠ chưa xếp đợt: ${c?.lyDoChuaXepDuoc ?? 'xem chi tiết'}`);
        this.openById(row.id);
      } else {
        const p = this.store.chuyenLoPreview([row.id]);
        this.msg.warning(p.blocked[0]?.reason ?? 'Chưa đủ điều kiện xác nhận — mở chi tiết để xem.');
        this.openById(row.id);
      }
    } else if (row.primaryKind === 'supplement' || row.primaryKind === 'review') {
      // Bổ sung / Đối chiếu / Xem xét — mở panel chi tiết để HR xử lý (không xác nhận thẳng).
      this.openById(row.id);
    }
  }

