  /** AI card "Kê khai N biến động" — sang tab Sẵn sàng + chọn hết dòng san-sang để bấm Xác nhận (bulk). */
  protected keKhaiSanSang(): void {
    const ids = this.baseChanges().filter((c) => insClassify(c) === 'san-sang').map((c) => c.id);
    if (!ids.length) { this.msg.warning('Không có biến động sẵn sàng để kê khai.'); return; }
    this.advConds.set([{ key: 'phanLoai', operator: 'in', value: ['san-sang'] }]);
    this.selKeys.set([...ids]);
    this.msg.success(`Đã chọn ${ids.length} biến động sẵn sàng — bấm "Xác nhận" trên thanh thao tác để kê khai.`);
  }

  /** Deep-link cột "Đợt kê khai" → mở đúng lô bên M03 (navigation contract mang {ky, donVi, filter}). */
  protected goLo(row: M02Row, e?: Event): void {
    e?.stopPropagation();
    const c = this.store.change(row.id);
    if (c?.loBatchId) this.shell.go('m03', { ky: c.kyTacDong, donVi: c.donViId, filter: `lo:${c.loBatchId}` });
  }

  /** Panel emit yêu cầu lý do: 'loai-tru' → popover compact mới; còn lại → prompt textarea cũ. */
  protected onRequestReason(e: { mode: 'loai-tru' | 'hoan-tac' | 'phan-loai-d02'; id: string }): void {
    if (e.mode === 'loai-tru') this.openLoaiTru([e.id]);
    else this.openReason(e.mode, [e.id]);
  }

