  /* ── prompt LÝ DO (bắt buộc — xóa KHÔNG tồn tại, chỉ loại trừ/hoàn tác có lý do) ── */
  private dlg: { close: () => void } | null = null;
  private readonly reasonMode = signal<'loai-tru' | 'hoan-tac' | 'phan-loai-d02'>('loai-tru');
  private readonly reasonIds = signal<string[]>([]);
  private readonly reasonText = signal('');
  protected get reasonModel(): string { return this.reasonText(); }
  protected set reasonModel(v: string) { this.reasonText.set(v ?? ''); if (v?.trim()) this.reasonError.set(''); }
  protected readonly reasonError = signal('');
  protected readonly reasonHint = computed(() => {
    const n = this.reasonIds().length;
    switch (this.reasonMode()) {
      case 'loai-tru': return `Loại trừ ${n} dòng đã chọn — thay cho "xóa" (không tồn tại). Vượt ngưỡng cần người thứ 2 duyệt (maker–checker).`;
      case 'hoan-tac': return 'Hoàn tác loại trừ — dòng quay về "Cần bổ sung", tạo phiên bản mới (không ghi đè lịch sử).';
      case 'phan-loai-d02': return 'Gán nhãn "Kê khai theo kỳ (D02-LT)" — KHÔNG mặc định, phân loại tường minh có audit.';
    }
  });
  private readonly reasonTplRef = viewChild<TemplateRef<unknown>>('reasonTpl');
  private readonly simTplRef = viewChild<TemplateRef<unknown>>('simTpl');
  private readonly riskTplRef = viewChild<TemplateRef<unknown>>('riskTpl');
  private readonly loaiTruTplRef = viewChild<TemplateRef<unknown>>('loaiTruTpl');
  private readonly historyTplRef = viewChild<TemplateRef<unknown>>('historyTpl');

  protected openReason(mode: 'loai-tru' | 'hoan-tac' | 'phan-loai-d02', ids: string[]): void {
    if (!ids.length) { this.msg.warning('Chưa chọn dòng nào.'); return; }
    this.reasonMode.set(mode); this.reasonIds.set(ids); this.reasonText.set(''); this.reasonError.set('');
    const title = mode === 'loai-tru' ? 'Bỏ khỏi kỳ (có lý do)' : mode === 'hoan-tac' ? 'Hoàn tác loại trừ' : 'Gán nhãn luồng D02-LT';
    this.dlg = this.modal.open({
      title, content: this.reasonTplRef()!, width: 460,
      footer: [
        { label: 'Hủy', onClick: () => this.dlg?.close() },
        { label: title, type: 'primary', danger: mode === 'loai-tru', onClick: () => this.confirmReason() },
      ],
    });
  }

  private confirmReason(): void {
    const lyDo = this.reasonText().trim();
    if (!lyDo) { this.reasonError.set('Lý do là bắt buộc — nhật ký append-only ghi trước/sau + lý do + người.'); return; }
    const ids = this.reasonIds();
    const mode = this.reasonMode();
    if (mode === 'loai-tru') {
      let done = 0; const blocked: string[] = [];
      for (const id of ids) {
        const r = this.store.tryLoaiTru(id, lyDo);
        r.ok ? done++ : blocked.push(r.reason ?? id);
      }
      if (done && blocked.length) this.msg.warning(`Đã loại trừ ${done}/${ids.length} dòng · ${blocked.length} bị chặn.`);
      else if (done) this.msg.success(`Đã loại trừ ${done}/${ids.length} dòng (hoàn tác được, kèm lý do).`);
      else this.msg.error(blocked[0] ?? 'Không loại trừ được dòng nào.');
    } else if (mode === 'hoan-tac') {
      const r = this.store.hoanTacLoaiTru(ids[0], lyDo);
      r.ok ? this.msg.success('Đã hoàn tác loại trừ — dòng về "Cần bổ sung" (phiên bản mới).') : this.msg.error(r.reason ?? 'Không hoàn tác được.');
    } else {
      const r = this.store.phanLoaiLuong(ids[0], 'd02-lt', lyDo);
      r.ok ? this.msg.success('Đã gán nhãn Kê khai theo kỳ (D02-LT) — có audit.') : this.msg.error(r.reason ?? 'Không gán được nhãn.');
    }
    this.dlg?.close();
  }

  /* ── LOẠI TRỪ — popover compact + lý do hệ thống đề xuất (B3/B4/D) ── */
  protected readonly ltIds = signal<string[]>([]);
  protected readonly ltSuggest = signal<InsSuggestLoaiTru | null>(null);
  protected readonly ltBulkBreakdown = signal<{ label: string; count: number }[]>([]);
  protected readonly ltReasonMa = signal<string | null>(null);
  private readonly ltNote = signal('');
  protected readonly ltShowNote = signal(false);
  protected readonly ltError = signal('');
  protected readonly ltGroups = M02_LOAI_TRU_GROUPS;
  protected readonly ltIsBulk = computed(() => this.ltIds().length > 1);
  protected readonly ltIsKhac = computed(() => this.ltReasonMa() === INS_LOAI_TRU_MA_KHAC);
  protected readonly ltDiffContext = computed(() => this.ltBulkBreakdown().filter((b) => b.label !== 'Chưa có đề xuất').length > 1);
  protected readonly ltSuggestLabel = computed(() => {
    const s = this.ltSuggest();
    return s ? (INS_LOAI_TRU_REASON_LABEL[s.ma] ?? s.ma) : '';
  });
  protected get ltReasonModel(): unknown { return this.ltReasonMa(); }
  protected set ltReasonModel(v: unknown) { this.ltReasonMa.set((v as string) || null); this.ltShowNote.set(false); this.ltNote.set(''); if (v) this.ltError.set(''); }
  protected get ltNoteModel(): string { return this.ltNote(); }
  protected set ltNoteModel(v: string) { this.ltNote.set(v ?? ''); if (v?.trim()) this.ltError.set(''); }

  /** B3 — mở popover loại trừ (1 dòng: có đề xuất; N dòng: breakdown theo đề xuất — điểm 12). */
  protected openLoaiTru(ids: string[]): void {
    if (!ids.length) { this.msg.warning('Chưa chọn dòng nào.'); return; }
    this.ltIds.set(ids); this.ltReasonMa.set(null); this.ltNote.set(''); this.ltShowNote.set(false); this.ltError.set('');
    if (ids.length === 1) {
      const c = this.store.change(ids[0]);
      this.ltSuggest.set(c ? insSuggestLoaiTru(c) : null);
      this.ltBulkBreakdown.set([]);
    } else {
      this.ltSuggest.set(null);
      const counts = new Map<string, number>();
      for (const id of ids) {
        const c = this.store.change(id);
        const s = c ? insSuggestLoaiTru(c) : null;
        const label = s ? (INS_LOAI_TRU_REASON_LABEL[s.ma] ?? s.ma) : 'Chưa có đề xuất';
        counts.set(label, (counts.get(label) ?? 0) + 1);
      }
      this.ltBulkBreakdown.set([...counts].map(([label, count]) => ({ label, count })).sort((a, b) => b.count - a.count));
    }
    const n = ids.length;
    this.dlg = this.modal.open({
      title: n > 1 ? `Bỏ khỏi kỳ ${n} biến động` : 'Lý do bỏ khỏi kỳ', content: this.loaiTruTplRef()!, width: 480,
      footer: [
        { label: 'Hủy', onClick: () => this.dlg?.close() },
        { label: n > 1 ? `Bỏ khỏi kỳ (${n})` : 'Xác nhận bỏ khỏi kỳ', type: 'primary', danger: true, onClick: () => this.confirmLoaiTru() },
      ],
    });
  }

  /** Đồng ý đề xuất của hệ thống (2 click: Loại trừ → Xác nhận loại trừ). */
  protected confirmSuggested(): void {
    const s = this.ltSuggest();
    if (s) this.confirmLoaiTru(s.ma);
  }

  /** B4 — thực thi loại trừ (single/bulk) + audit chuẩn hoá; F — toast nêu nhãn lý do, row rời view mặc định. */
  private confirmLoaiTru(maOverride?: string): void {
    const ma = maOverride ?? this.ltReasonMa();
    if (!ma) { this.ltError.set('Hãy chọn lý do loại trừ.'); return; }
    const isKhac = ma === INS_LOAI_TRU_MA_KHAC;
    const note = this.ltNote().trim();
    if (isKhac && !note) { this.ltError.set('Lý do khác — hãy mô tả ngắn lý do loại trừ.'); return; }
    const lyDoNhan = INS_LOAI_TRU_REASON_LABEL[ma] ?? ma;
    const lyDoText = isKhac ? note : lyDoNhan;              // 'khac' → dùng chính nội dung mô tả làm lý do
    const ids = this.ltIds();
    let done = 0; const blocked: string[] = [];
    for (const id of ids) {
      const c = this.store.change(id);
      const suggestMa = c ? insSuggestLoaiTru(c)?.ma : undefined;
      const r = this.store.tryLoaiTru(id, lyDoText, { lyDoMa: ma, ghiChu: isKhac ? undefined : (note || undefined), suggestMa });
      r.ok ? done++ : blocked.push(r.reason ?? id);
    }
    this.dlg?.close();
    if (done && blocked.length) this.msg.warning(`✓ Đã loại trừ ${done}/${ids.length} · Lý do: ${lyDoNhan} · ${blocked.length} bị chặn.`);
    else if (done && ids.length === 1) this.msg.success(`✓ Đã loại trừ · Lý do: ${lyDoNhan}`);
    else if (done) this.msg.success(`✓ Đã loại trừ ${done} biến động · Lý do: ${lyDoNhan}`);
    else this.msg.error(blocked[0] ?? 'Không loại trừ được dòng nào.');
  }

