  protected bulkChuyenLo(): void {
    const ids = this.sel();
    if (!ids.length) return;
    const r = this.store.bulkChuyenLo(ids);
    if (r.done && r.loBatchId) {
      this.msg.success(`✓ ${r.done} đã xác nhận · tự xếp Đợt ${r.loBatchId}${r.daXacNhan ? ` · ${r.daXacNhan} chưa xếp được đợt (giữ trong hàng đợi)` : ''}${r.skipped.length ? ` · ${r.skipped.length} bỏ qua` : ''}.`);
      // UX-1: mở đúng lô THẬT vừa xếp bên M03 (kỳ = kỳ của lô, không phải navCtx cũ).
      this.shell.go('m03', { ky: r.ky, filter: `lo:${r.loBatchId}` });
    } else if (r.daXacNhan) {
      // T5: không dòng nào xếp được đợt nhưng đã xác nhận — giữ trong hàng đợi, HR xem cột "Đợt kê khai".
      this.msg.warning(`✓ ${r.daXacNhan} đã xác nhận nhưng chưa xếp được đợt — giữ trong hàng đợi, xem cột "Đợt kê khai" để biết lý do.`);
    } else {
      this.msg.warning(`0/${ids.length} dòng đủ điều kiện xác nhận — bấm "Xem lý do" trên thanh bulk.`);
    }
  }

