  protected readonly histActiveRow = signal<M02HistRow | null>(null);
  protected histActionCat(s: InsChangeState): 'excluded' | 'confirmed' | 'default' {
    if (s === 'da-loai-tru') return 'excluded';
    if (s === 'da-xac-nhan' || s === 'da-vao-lo' || s === 'da-nop' || s === 'duoc-chap-nhan') return 'confirmed';
    return 'default';
  }
  /** Khôi phục dòng đã loại trừ → store thật (hoanTacLoaiTru) → về "Cần bổ sung"; toast + đóng modal. */
