  /* ── AI5 risk scan: mở drawer gom rủi ro; mỗi nhóm → lọc thẳng tới đúng record (bộ filter mới) ── */
  protected openRiskScan(): void {
    this.dlg = this.modal.open({
      title: 'Quét rủi ro trước đóng kỳ', content: this.riskTplRef()!, width: 480,
      footer: [{ label: 'Đóng', onClick: () => this.dlg?.close() }],
    });
  }
  protected goRisk(r: InsRiskGroup): void {
    this.clearFilters(); // list chính vốn chỉ hiện việc chờ xử lý — mọi nhóm rủi ro đều nằm ở đây
    switch (r.key) {
      case 'qua-han': this.hanFilter.set(['qua-han']); break;
      case 'can-bo-sung': break;
      case 'kha-nang-trung':
        this.advConds.set([{ key: 'nhom', operator: 'in', value: ['trung-du-lieu'] }]);
        break;
      case 'nguy-co-sot': this.chongSot.set(true); break;
    }
    this.dlg?.close();
  }
