import { ChangeDetectionStrategy, Component, TemplateRef, computed, inject, input, signal, viewChild } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { IconSearch } from '@tabler/icons-angular';
import {
  HrmButton, HrmDetailPeek, HrmEmpty, HrmGrid, HrmGridColumn, HrmInput, HrmMessageService,
  HrmModalService, HrmPeekMode, HrmSelect, HrmTag,
} from 'hrm-ui';
import { InsM08BanGhiDanhMuc, InsM08Store } from '../_data/_m08-data';
import { InsM06Store } from '../_data/_m06-data';
import { InsM07Store, M07_BIEU_MAU, M07_PHAM_VI } from '../_data/_m07-data';
import { INS_LYDO_TUCHOI } from '../_data/_m03-data';
import { M07_LYDO_TUCHOI, M07_LYDO_KHONG_THU } from '../m07-payment/tracking/_m07-columns';

/** M08 ⑩ — KHUNG CRUD DÙNG CHUNG 9 DANH MỤC (IA_LOCK): bộ lọc trên → lưới giữa → thanh hành động
 *  → panel trượt phải; CHỈ KHÁC bộ trường + chống trùng. Chuẩn m08.md: tìm 3 kiểu (từ khóa · trường
 *  khóa · trạng thái); xóa n dòng xác nhận ĐÚNG n ("Bạn có chắc chắn muốn xóa n dòng dữ liệu đã
 *  chọn?"); chưa chọn → "Vui lòng chọn dữ liệu để xóa"; xuất Excel 2 chế độ (+ "Bạn chắc chắn muốn
 *  xuất tất cả dữ liệu không?" — chạy nền); 3 nút lưu Lưu / Lưu và đóng / Lưu và tạo mới; bản ghi
 *  MỚI có khoảng hiệu lực + `Ngưng sử dụng`; xóa cứng CHỈ khi chưa tham chiếu (đang → chặn + liệt
 *  kê nơi dùng + gợi ý Ngưng sử dụng); audit trước/sau; thông báo giữ văn phong cũ
 *  ("[Mã KCB] đã tồn tại trong hệ thống"); ô "Chưa thấy testcase" GIỮ NGUYÊN NHÃN (chip).
 *  Cuối trang: ỨNG VIÊN cấu hình gom từ module (móc nối D4/D5 — đọc SỐNG M06/M07, không refactor). */
@Component({
  selector: 'ins-m08-danhmuc-page',
  imports: [FormsModule, HrmButton, HrmDetailPeek, HrmEmpty, HrmGrid, HrmInput, HrmSelect, HrmTag],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (def(); as d) {
      <!-- Bộ lọc trên (tìm 3 kiểu) -->
      <div class="c-filters">
        <hrm-input class="c-kw" [(ngModel)]="kwModel" size="sm" [prefixIcon]="icSearch" [clearable]="true"
          [placeholder]="'Tìm từ khóa trong ' + d.ten + '…'" />
        <hrm-input class="c-khoa" [(ngModel)]="khoaModel" size="sm" [clearable]="true"
          [placeholder]="'Theo trường khóa: ' + khoaLabel()" />
        <hrm-select class="c-tt" [(ngModel)]="ttModel" [options]="ttOptions" size="sm" placeholder="Trạng thái" />
        <span class="c-note">Khóa chống trùng: {{ d.khoaNote }}</span>
        @if (d.khoaChuaThayTestcase) { <hrm-tag size="sm" color="orange" variant="stroke">Chưa thấy testcase — cần xác minh</hrm-tag> }
      </div>

      <!-- Thanh hành động -->
      <div class="c-actions">
        <hrm-button size="sm" variant="primary" (click)="moThem()">Thêm mới</hrm-button>
        <hrm-button size="sm" [danger]="true" (click)="xoaNhieu()">Xóa dòng đã chọn</hrm-button>
        <hrm-button size="sm" (click)="xuat('chon')">Xuất Excel (dòng chọn)</hrm-button>
        <hrm-button size="sm" (click)="xuat('tat-ca')">Xuất Excel (tất cả — chạy nền)</hrm-button>
        @if (d.actionNen; as an) { <hrm-button size="sm" (click)="chayNen()">{{ an }} (nền)</hrm-button> }
        <span class="c-gap"></span>
        <span class="c-note">Đã chọn {{ selected().length }}</span>
      </div>

      <!-- Lưới giữa -->
      @if (rows().length) {
        <hrm-grid [columns]="cols()" [data]="rows()" rowKey="id" density="compact" [pageSize]="10"
          [selectable]="true" [(selectedKeys)]="selectedModel" minWidth="900px" (rowClick)="moSua($event)" />
      } @else {
        <div class="c-empty"><hrm-empty preset="no-results" description="Không có bản ghi nào khớp bộ lọc." /></div>
      }

      <ng-template #ttTpl let-row>
        @if ($any(row).ngung) { <hrm-tag size="sm" color="gray">Ngưng sử dụng</hrm-tag> }
        @else { <hrm-tag size="sm" color="green">Đang sử dụng</hrm-tag> }
      </ng-template>
      <ng-template #refTpl let-row>
        @if ($any(row).refs.length) {
          <span class="c-refs">{{ $any(row).refs.join(' · ') }}</span>
        } @else { <span class="c-note">chưa tham chiếu</span> }
      </ng-template>

      <!-- Panel trượt phải: form bộ trường + 3 nút lưu -->
      <hrm-detail-peek [(open)]="peekOpenModel" [modes]="peekModes" [expandable]="false"
        [title]="peekTitle()" [content]="formTpl" [width]="460"
        switchLabel="Đổi cách hiển thị" closeLabel="Đóng" resizeLabel="Kéo đổi độ rộng" />
      <ng-template #formTpl>
        <div class="c-form">
          @for (f of d.fields; track f.key) {
            <label class="c-field">
              <span class="c-field__label">{{ f.label }}
                @if (d.khoa.includes(f.key)) { <hrm-tag size="sm" color="blue" variant="stroke">khóa</hrm-tag> }
                @if (f.chuaThayTestcase) { <hrm-tag size="sm" color="orange" variant="stroke">Chưa thấy testcase</hrm-tag> }
              </span>
              <hrm-input [ngModel]="form()[f.key] ?? ''" (ngModelChange)="setField(f.key, $event)" size="sm"
                [readonly]="!!(editId() && d.khoaCaSua && d.khoa.includes(f.key))" />
              @if (editId() && d.khoaCaSua && d.khoa.includes(f.key)) {
                <span class="c-err">{{ d.khoaNote }} — khóa cả khi SỬA.</span>
              }
            </label>
          }
          @if (trungReason(); as reason) { <p class="c-err">{{ reason }}</p> }
          <div class="c-form__acts">
            <hrm-button size="sm" variant="primary" (click)="luu('luu')">Lưu</hrm-button>
            <hrm-button size="sm" (click)="luu('dong')">Lưu và đóng</hrm-button>
            <hrm-button size="sm" (click)="luu('tao-moi')">Lưu và tạo mới</hrm-button>
          </div>
          @if (editId(); as id) {
            <div class="c-form__acts">
              @if (xoaReason(id); as reason) {
                <hrm-button size="sm" [danger]="true" [disabled]="true">Xóa</hrm-button>
                <hrm-button size="sm" (click)="ngung(id)">Ngưng sử dụng</hrm-button>
                <span class="c-err">{{ reason }}</span>
              } @else {
                <hrm-button size="sm" [danger]="true" (click)="xoaMot(id)">Xóa</hrm-button>
                <hrm-button size="sm" (click)="ngung(id)">Ngưng sử dụng</hrm-button>
              }
            </div>
          }
          <p class="c-note">Bản ghi mới nhận khoảng hiệu lực từ hôm nay; mọi thao tác ghi audit trước/sau (bất biến #3).</p>
        </div>
      </ng-template>

      <!-- Ứng viên cấu hình gom từ module (D4/D5 → D6) — đọc SỐNG, chưa thành danh mục chính thức -->
      <details class="c-ungvien">
        <summary>Ứng viên danh mục/tham số gom từ module (móc nối D4–D5) — {{ ungVien().length }} nhóm · hiển thị, không refactor module cũ</summary>
        @for (u of ungVien(); track u.ten) {
          <div class="c-uv">
            <span class="c-uv__ten">{{ u.ten }}</span>
            <hrm-tag size="sm" color="purple" variant="stroke">{{ u.nguon }}</hrm-tag>
            <span class="c-note">{{ u.giaTri }}</span>
          </div>
        }
      </details>
    }
  `,
  host: { class: 'ins-m08-danhmuc-page' },
  styles: [`
    :host { display: flex; flex-direction: column; gap: 10px; }
    .c-filters, .c-actions { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
    .c-kw { display: inline-block; width: 250px; }
    .c-khoa { display: inline-block; width: 220px; }
    .c-tt { display: inline-block; width: 170px; }
    .c-gap { flex: 1; }
    .c-note { font-size: var(--fs-11); color: var(--text-soft); }
    .c-err { font-size: var(--fs-12); color: var(--error-text); font-weight: 500; margin: 0; }
    .c-refs { font-size: var(--fs-12); color: var(--warning-text); }
    .c-empty { padding: 36px 0; display: flex; justify-content: center; }
    .c-form { display: flex; flex-direction: column; gap: 10px; }
    .c-field { display: flex; flex-direction: column; gap: 3px; }
    .c-field__label { display: flex; align-items: center; gap: 6px; font-size: var(--fs-12); font-weight: 600; color: var(--text-sub); }
    .c-form__acts { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
    .c-ungvien summary { font-size: var(--fs-12); color: var(--text-sub); cursor: pointer; font-weight: 600; }
    .c-uv { display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; padding: 5px 0 0 14px; }
    .c-uv__ten { font-size: var(--fs-13); font-weight: 500; color: var(--text-strong); }
  `],
})
export class InsM08DanhMucPage {
  protected readonly store = inject(InsM08Store);
  private readonly m06 = inject(InsM06Store);
  private readonly m07 = inject(InsM07Store);
  private readonly msg = inject(HrmMessageService);
  private readonly modal = inject(HrmModalService);

  protected readonly icSearch = IconSearch;

  readonly dmKey = input.required<string>();
  protected readonly def = computed(() => this.store.dmDef(this.dmKey()));

  /* ── tìm 3 kiểu ── */
  private readonly kw = signal('');
  protected get kwModel(): string { return this.kw(); }
  protected set kwModel(v: string) { this.kw.set(v ?? ''); }
  private readonly khoaF = signal('');
  protected get khoaModel(): string { return this.khoaF(); }
  protected set khoaModel(v: string) { this.khoaF.set(v ?? ''); }
  private readonly tt = signal<string | null>(null);
  protected get ttModel(): unknown { return this.tt(); }
  protected set ttModel(v: unknown) { this.tt.set((v as string) || null); }
  protected readonly ttOptions = [
    { value: 'dang-su-dung', label: 'Đang sử dụng' },
    { value: 'ngung-su-dung', label: 'Ngưng sử dụng' },
  ];
  protected readonly khoaLabel = computed(() => {
    const d = this.def();
    return d ? d.khoa.map((k) => d.fields.find((f) => f.key === k)?.label ?? k).join(' + ') : '';
  });

  private readonly list = computed<InsM08BanGhiDanhMuc[]>(() => {
    const d = this.def();
    if (!d) return [];
    const kw = this.kw().trim().toLowerCase();
    const khoa = this.khoaF().trim().toLowerCase();
    const tt = this.tt();
    return this.store.dmRecordsOf(d.key).filter((r) => {
      if (tt && r.trangThai !== tt) return false;
      if (khoa && !d.khoa.some((k) => (r.values[k] ?? '').toLowerCase().includes(khoa))) return false;
      if (kw && !Object.values(r.values).join(' ').toLowerCase().includes(kw)) return false;
      return true;
    });
  });

  protected readonly rows = computed(() => {
    const d = this.def();
    return this.list().map((r) => ({
      id: r.id,
      ...Object.fromEntries((d?.fields ?? []).map((f) => [f.key, r.values[f.key] ?? ''])),
      khoang: `${r.khoangHL.tu} → ${r.khoangHL.den ?? 'mở'}`,
      ngung: r.trangThai === 'ngung-su-dung',
      refs: r.noiThamChieu,
    }));
  });

  private readonly ttTpl = viewChild.required<TemplateRef<unknown>>('ttTpl');
  private readonly refTpl = viewChild.required<TemplateRef<unknown>>('refTpl');
  protected readonly cols = computed<HrmGridColumn[]>(() => {
    const d = this.def();
    if (!d) return [];
    return [
      ...d.fields.map((f) => ({ key: f.key, title: f.chuaThayTestcase ? `${f.label} (Chưa thấy testcase)` : f.label, width: '160px' })),
      { key: 'khoang', title: 'Khoảng hiệu lực', width: '150px' },
      { key: 'tt', title: 'Trạng thái', width: '120px', cell: this.ttTpl() as HrmGridColumn['cell'] },
      { key: 'refs', title: 'Nơi tham chiếu', width: '230px', cell: this.refTpl() as HrmGridColumn['cell'] },
    ];
  });

  /* ── selection + bulk xóa/xuất ── */
  protected readonly selected = signal<unknown[]>([]);
  protected get selectedModel(): unknown[] { return this.selected(); }
  protected set selectedModel(v: unknown[]) { this.selected.set(v ?? []); }

  protected xoaNhieu(): void {
    const ids = this.selected().map(String);
    if (!ids.length) { this.msg.warning('Vui lòng chọn dữ liệu để xóa'); return; }
    const preview = this.store.dmXoaPreview(ids);
    this.modal.confirm({
      title: `Bạn có chắc chắn muốn xóa ${ids.length} dòng dữ liệu đã chọn?`,
      content: preview.blocked.length
        ? `${preview.eligible} dòng xóa được · ${preview.blocked.map((b) => `${b.count} dòng bị chặn: ${b.reason}`).join(' — ')}`
        : `${preview.eligible}/${ids.length} dòng đủ điều kiện xóa cứng (chưa tham chiếu).`,
      okText: 'Xóa', cancelText: 'Huỷ', danger: true,
      onOk: () => {
        const r = this.store.dmXoa(ids);
        this.selected.set([]);
        r.skipped.length
          ? this.msg.warning(`Đã xóa ${r.done}/${ids.length}; ${r.skipped.length} dòng bị chặn (đang tham chiếu) — gợi ý Ngưng sử dụng.`)
          : this.msg.success(`Đã xóa ${r.done} dòng.`);
      },
    });
  }

  protected xuat(cheDo: 'chon' | 'tat-ca'): void {
    const d = this.def();
    if (!d) return;
    if (cheDo === 'chon') {
      const n = this.selected().length;
      if (!n) { this.msg.warning('Vui lòng chọn dữ liệu để xuất.'); return; }
      this.store.dmKetXuat(d.key, 'chon', n);
      this.msg.success(`Đã xuất ${n} dòng đã chọn — nhật ký xuất tự ghi.`);
      return;
    }
    this.modal.confirm({
      title: 'Bạn chắc chắn muốn xuất tất cả dữ liệu không?',
      content: `Xuất tất cả ${this.list().length} dòng — chạy NỀN, xong sẽ báo.`,
      okText: 'Xuất tất cả', cancelText: 'Huỷ',
      onOk: () => {
        this.store.dmKetXuat(d.key, 'tat-ca', this.list().length);
        this.msg.info('Lần xuất tất cả đang chạy nền — nhật ký xuất tự ghi.');
      },
    });
  }

  protected chayNen(): void {
    this.store.capNhatPhanTu();
    this.msg.info('Đã xếp hàng "Cập nhật lại các phần tử" chạy NỀN — không khóa màn hình.');
  }

  /* ── panel form (3 nút lưu) ── */
  protected readonly peekModes: HrmPeekMode[] = ['side'];
  private readonly peekOpen = signal(false);
  protected get peekOpenModel(): boolean { return this.peekOpen(); }
  protected set peekOpenModel(v: boolean) { this.peekOpen.set(v); }
  protected readonly editId = signal<string | null>(null);
  protected readonly form = signal<Record<string, string>>({});
  protected readonly peekTitle = computed(() => {
    const d = this.def();
    return this.editId() ? `Sửa bản ghi · ${d?.ten}` : `Thêm mới · ${d?.ten}`;
  });
  protected setField(key: string, v: string): void { this.form.update((f) => ({ ...f, [key]: v })); }

  protected moThem(): void {
    this.editId.set(null);
    this.form.set({});
    this.peekOpen.set(true);
  }
  protected moSua(row: Record<string, unknown>): void {
    const id = String(row['id']);
    const r = this.store.dmRecords().find((x) => x.id === id);
    if (!r) return;
    this.editId.set(id);
    this.form.set({ ...r.values });
    this.peekOpen.set(true);
  }

  protected trungReason(): string | null {
    const d = this.def();
    if (!d) return null;
    const f = this.form();
    if (!d.khoa.some((k) => f[k]?.trim())) return null; // chưa nhập khóa — chưa cần báo
    return this.store.dmTrungReason(d.key, f, this.editId() ?? undefined);
  }

  protected luu(mode: 'luu' | 'dong' | 'tao-moi'): void {
    const d = this.def();
    if (!d) return;
    const r = this.store.dmLuu(d.key, this.form(), this.editId() ?? undefined);
    if (!r.ok) { this.msg.error(r.reason ?? ''); return; }
    this.msg.success(this.editId() ? 'Đã lưu (audit trước/sau).' : `Đã thêm ${r.id} (khoảng hiệu lực từ hôm nay).`);
    if (mode === 'dong') this.peekOpen.set(false);
    else if (mode === 'tao-moi') { this.editId.set(null); this.form.set({}); }
    else if (!this.editId() && r.id) this.editId.set(r.id);
  }

  protected xoaReason(id: string): string | null { return this.store.dmXoaReason(id); }
  protected xoaMot(id: string): void {
    this.modal.confirm({
      title: 'Bạn có chắc chắn muốn xóa 1 dòng dữ liệu đã chọn?',
      okText: 'Xóa', cancelText: 'Huỷ', danger: true,
      onOk: () => {
        const r = this.store.dmXoa([id]);
        r.done ? this.msg.success('Đã xóa 1 dòng.') : this.msg.error(r.skipped[0]?.reason ?? '');
        this.peekOpen.set(false);
      },
    });
  }
  protected ngung(id: string): void {
    this.store.dmNgung([id]);
    this.msg.success('Đã Ngưng sử dụng — thay cho xóa khi đang/từng tham chiếu (bất biến #3).');
  }

  /* ── ứng viên gom từ module — ĐỌC SỐNG M06/M07 + const module (không refactor) ── */
  protected readonly ungVien = computed(() => [
    { ten: 'Lý do từ chối chi', nguon: 'M07', giaTri: M07_LYDO_TUCHOI.join(' · ') },
    { ten: 'Lý do không thu hồi được', nguon: 'M07', giaTri: M07_LYDO_KHONG_THU.join(' · ') },
    { ten: 'Lý do từ chối lô kê khai', nguon: 'M03', giaTri: INS_LYDO_TUCHOI.join(' · ') },
    { ten: 'Ngưỡng N chi hỏng', nguon: 'M07', giaTri: `N = ${this.m07.chiHong()[0]?.nguongN ?? 3} (đủ N lần TỰ chuyển hàng đợi) — đã versioned thành tham số NGUONG-N-CHI-HONG` },
    { ten: 'Bộ 66 chỉ tiêu kiểm tra theo kỳ lương', nguon: 'M07-B', giaTri: `${this.m07.ktPhienBan()[0]?.chiTieu.length ?? 0}/66 chỉ tiêu seed · ${this.m07.ktPhienBan().length} phiên bản kết quả (đọc sống InsM07Store)` },
    { ten: 'Biểu mẫu xuất versioned', nguon: 'M07-B', giaTri: M07_BIEU_MAU.map((b) => b.label).join(' · ') },
    { ten: 'Phạm vi hợp nhất theo quyền', nguon: 'M07-B', giaTri: M07_PHAM_VI.map((p) => p.label).join(' · ') },
    { ten: 'Cửa sổ nộp theo quý (đổi thẻ BHYT)', nguon: 'M06', giaTri: `Ngày mở kế: ${this.m06.boHoSo().find((h) => h.ngayMoCuaSoKe)?.ngayMoCuaSoKe ?? '01/10/2026'} (đọc sống InsM06Store)` },
    { ten: 'Danh mục thủ tục versioned (M06 đọc từ M08 — nguồn duy nhất)', nguon: 'M06', giaTri: `${this.m06.thuTuc().length} dòng M06 đọc SỐNG từ danh mục M08 (BQA-13 — hết seed trùng)` },
  ]);
}
