/** ═════════ M05-A — CONFIG THUẦN (tab · 13 cột chuẩn + cột đặc thù theo tab · row-VM) ═════════
 *  Nguồn: `_rebuild/01-requirements/m05.md` IA_LOCK — 13 cột chuẩn: mã case, NLĐ, mã BHXH, đơn vị,
 *  loại chế độ, ngày sự kiện, số ngày, số tiền dự kiến, trạng thái, hạn xử lý, cảnh báo,
 *  chứng từ thiếu, người phụ trách. Cột đặc thù: Ốm đau (tuổi con + lũy kế năm) · Thai sản
 *  (ngày sinh con + số con) · Dưỡng sức (căn cứ chế độ gốc) — seed có gì hiện nấy.
 *  Mọi chuỗi format 1 LẦN tại đây (row-VM) — template chỉ bind chuỗi sẵn (pattern D1). */

export type M05TabKey = 'tat-ca' | InsCaseNhom;

export const M05_TAB_LABEL: Record<M05TabKey, string> = {
  'tat-ca': 'Tất cả', 'om-dau': 'Ốm đau', 'thai-san': 'Thai sản', 'duong-suc': 'Dưỡng sức',
};

export interface M05ColDef {
  key: string;
  title: string;
  width?: string;
  align?: 'left' | 'center' | 'right';
  sortable?: boolean;
  fixed?: 'left' | 'right';
}

const COL: Record<string, M05ColDef> = {
  maCase: { key: 'maCaseCell', title: 'Mã case', width: '128px', sortable: true },
  nhanVien: { key: 'ten', title: 'Người lao động', width: '200px', sortable: true },
  maBHXH: { key: 'maSoBHXH', title: 'Mã BHXH', width: '116px' },
  donVi: { key: 'donViShort', title: 'Đơn vị', width: '120px' },
  loaiCheDo: { key: 'loaiCheDoCell', title: 'Loại chế độ', width: '150px' },
  ngaySuKien: { key: 'ngaySuKien', title: 'Ngày sự kiện', width: '110px', sortable: true },
  soNgay: { key: 'soNgayLabel', title: 'Số ngày', width: '82px', align: 'right' },
  soTien: { key: 'soTienCell', title: 'Số tiền dự kiến', width: '138px', align: 'right' },
  trangThai: { key: 'trangThai', title: 'Trạng thái', width: '170px' },
  hanXuLy: { key: 'hanXuLy', title: 'Hạn xử lý', width: '150px' },
  canhBao: { key: 'canhBao', title: 'Cảnh báo', width: '160px' },
  chungTuThieu: { key: 'chungTuThieu', title: 'Chứng từ thiếu', width: '160px' },
  owner: { key: 'owner', title: 'Người phụ trách', width: '150px' },
  /* cột đặc thù */
  conOm: { key: 'conOm', title: 'Tuổi con · lũy kế năm', width: '150px' },
  sinhCon: { key: 'sinhCon', title: 'Ngày sinh con · số con', width: '150px' },
  canCuGoc: { key: 'canCuGoc', title: 'Căn cứ chế độ gốc', width: '230px' },
  act: { key: 'act', title: '', width: '92px', align: 'right', fixed: 'right' },
};

const CHUAN: M05ColDef[] = [
  COL['maCase'], COL['nhanVien'], COL['maBHXH'], COL['donVi'], COL['loaiCheDo'], COL['ngaySuKien'],
  COL['soNgay'], COL['soTien'], COL['trangThai'], COL['hanXuLy'], COL['canhBao'], COL['chungTuThieu'], COL['owner'],
];

/** Tab chỉ khác filter mặc định + CỘT ĐẶC THÙ (IA_LOCK) — chèn cột đặc thù sau "Ngày sự kiện". */
function withExtra(extra?: M05ColDef): M05ColDef[] {
  const cols = [...CHUAN];
  if (extra) cols.splice(6, 0, extra);
  return [...cols, COL['act']];
}

export const M05_COLS: Record<M05TabKey, M05ColDef[]> = {
  'tat-ca': withExtra(),
  'om-dau': withExtra(COL['conOm']),
  'thai-san': withExtra(COL['sinhCon']),
  'duong-suc': withExtra(COL['canCuGoc']),
};

export const M05_GRID_MIN_WIDTH: Record<M05TabKey, string> = {
  'tat-ca': '1820px', 'om-dau': '1970px', 'thai-san': '1970px', 'duong-suc': '2050px',
};

/* ─────────────────────────── Row VM ─────────────────────────── */

export interface M05Row extends Record<string, unknown> {
  id: string;
  maCase: string;
  nhomLabel: string;
  ten: string;
  sub: string;
  maSoBHXH: string;
  donViShort: string;
  loaiCheDo: string;
  ngaySuKien: string;
  soNgayLabel: string;
  soTien: string;           // '' → 'chưa có kết quả'
  trangThaiLabel: string;
  trangThaiTone: string;
  hanNgay: string;
  slaLabel: string;
  slaTone: 'ok' | 'warn' | 'danger' | 'muted';
  /** Cảnh báo: chip chặn/cảnh báo/exception — chuỗi sẵn, '' = không có. */
  canhBaoChan: number;
  canhBaoWarn: number;
  coException: boolean;
  /** Chứng từ thiếu: 'n mục · hạn dd/mm' — '' = đủ. */
  chungTuThieu: string;
  conOm: string;
  sinhCon: string;
  canCuGoc: string;
  owner: string;
  buoc: number;             // bước B đúng trạng thái — "Đi sâu xử lý" mở đúng bước
  actions: HrmActionItem[];
}

export function buildM05Row(c: InsCase): M05Row {
  const nv = insNhanVien(c.nhanVienId);
  const dv = insDonVi(c.donViId);
  const sla = insSlaView(c);
  const thieu = c.checklist.filter((k) => k.batBuoc && k.trangThai === 'thieu');
  const hanBoSung = thieu.find((k) => k.hanBoSung)?.hanBoSung;
  return {
    id: c.maCase,
    maCase: c.maCase,
    nhomLabel: INS_CASE_NHOM_LABEL[c.nhom],
    ten: nv?.name ?? '—',
    sub: `${nv?.code ?? '—'} · ${nv?.dept ?? ''}`,
    maSoBHXH: nv?.insCode ?? '—',
    donViShort: dv?.id === 'dv2' ? 'VNR Đà Nẵng' : 'VNR Hà Nội',
    loaiCheDo: c.loaiCheDo,
    ngaySuKien: c.ngaySuKien,
    soNgayLabel: c.soNgay != null ? `${c.soNgay}` : '—',
    soTien: c.soTienDuKien,
    trangThaiLabel: INS_CASE_STATE_LABEL[c.trangThai],
    trangThaiTone: INS_CASE_STATE_TONE[c.trangThai],
    hanNgay: c.ngayHanXuLy || '—',
    slaLabel: sla.label,
    slaTone: sla.tone,
    canhBaoChan: c.viPham.filter((v) => v.mucDo === 'chan' && !v.daOverride).length,
    canhBaoWarn: c.viPham.filter((v) => v.mucDo === 'canh-bao' && !v.daOverride).length,
    coException: !!c.exceptionDong && (c.exceptionDong.trangThai === 'moi' || c.exceptionDong.trangThai === 'dang-xu-ly'),
    chungTuThieu: thieu.length ? `${thieu.length} mục${hanBoSung ? ` · hạn ${hanBoSung}` : ''}` : '',
    conOm: c.khoiCon ? `${c.khoiCon.tuoiCon} tuổi · ${c.khoiCon.luyKeNam}/${c.khoiCon.tranNam} ngày` : '—',
    sinhCon: c.khoiThaiSan ? `${c.khoiThaiSan.ngaySinhCon ?? `dự sinh ${c.khoiThaiSan.ngayDuSinh}`} · ${c.khoiThaiSan.soCon} con` : '—',
    canCuGoc: c.canCuGoc ?? '—',
    owner: c.owner,
    buoc: m05StepOfState(c.trangThai),
    actions: [
      { key: 'view', icon: IconEye, label: 'Xem tóm tắt' },
      { key: 'deep', icon: IconArrowRight, label: 'Đi sâu xử lý' },
    ],
  };
}

