import { ChangeDetectionStrategy, Component, TemplateRef, computed, inject, output, signal, viewChild } from '@angular/core';
import { HrmButton, HrmDetailPeek, HrmEmpty, HrmFileCell, HrmGrid, HrmGridColumn, HrmMessageService, HrmPeekMode, HrmStatusCell, HrmTag } from 'hrm-ui';
import { InsSectionLabel } from '../../_shared';
import { InsM06Store } from '../../_data/_m06-data';
import { M06RowTaiLieu, M06_COLS_T1, buildRowTaiLieu } from './_m06-columns';

/** M06-A T1 — KHO TÀI LIỆU: phiên bản mới không ghi đè · hash toàn vẹn (lệch CHẶN tải + log) ·
 *  log mọi xem/tải KỂ CẢ bị từ chối · quá hạn đánh dấu + lọc, không tự xóa · nhạy cảm y tế tag.
 *  Panel trượt: chuỗi phiên bản + log truy cập (gồm lượt BỊ TỪ CHỐI). */
@Component({
  selector: 'ins-m06-tab-tailieu',
  imports: [HrmButton, HrmDetailPeek, HrmEmpty, HrmFileCell, HrmGrid, HrmStatusCell, HrmTag, InsSectionLabel],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="t1-split">
      <div class="t1-main">
        @if (rows().length) {
          <hrm-grid [columns]="cols()" [data]="rows()" rowKey="id" density="compact"
            minWidth="1120px" [pageSize]="10" (rowClick)="onRowClick($event)" />
        } @else {
          <div class="t1-empty"><hrm-empty preset="no-results" description="Không có tài liệu nào khớp bộ lọc hiện tại." /></div>
        }
      </div>

      <hrm-detail-peek [(open)]="peekOpenModel" [modes]="peekModes" [expandable]="false"
        [title]="peekTitle()" [content]="panelTpl" [width]="440"
        switchLabel="Đổi cách hiển thị" closeLabel="Đóng" resizeLabel="Kéo đổi độ rộng" />
    </div>

    <!-- ═════ Cell templates ═════ -->
    <ng-template #tepTpl let-row>
      <div class="t1-tep">
        <hrm-file-cell [name]="$any(row).tep" [size]="$any(row).kichThuoc" />
        <div class="t1-tep__tags">
          @if ($any(row).nhayCam) { <hrm-tag color="purple" size="sm">Nhạy cảm y tế</hrm-tag> }
          @if ($any(row).quaHan) { <hrm-tag color="red" size="sm">Quá hạn — không tự xóa</hrm-tag> }
        </div>
      </div>
    </ng-template>
    <ng-template #pbTpl let-row>
      <div class="t1-stack">
        <span class="t1-strong">v{{ $any(row).phienBanN }}</span>
        <span class="t1-hash" [class.t1-hash--bad]="!$any(row).hashKhop">{{ $any(row).hash }} {{ $any(row).hashKhop ? '✓' : '✗ lệch' }}</span>
      </div>
    </ng-template>
    <ng-template #hanTpl let-row>
      @if ($any(row).hetHan) { <span [class.t1-warn]="$any(row).quaHan">{{ $any(row).hetHan }}</span> }
      @else { <span class="t1-muted">—</span> }
    </ng-template>
    <ng-template #statusTpl let-row>
      <hrm-status-cell [status]="$any(row).trangThaiTone" [label]="$any(row).trangThaiLabel" variant="badge" />
    </ng-template>
    <ng-template #actTpl let-row>
      <hrm-button size="sm" (click)="taiXuong($any(row).id); $event.stopPropagation()">Tải</hrm-button>
    </ng-template>

    <!-- ═════ Panel: chuỗi phiên bản + log truy cập (gồm lượt BỊ TỪ CHỐI) ═════ -->
    <ng-template #panelTpl>
      @if (sel(); as t) {
        <div class="t1-pk">
          <p class="t1-pk__name">{{ t.ten }}</p>
          <p class="t1-muted">{{ t.loai }} · nguồn {{ t.nguon }}@if (t.hetHan) { · hết hạn {{ t.hetHan }}}</p>

          <ins-section-label text="Chuỗi phiên bản (tải mới không ghi đè)" tone="muted" [count]="t.phienBan.length" />
          @for (pb of chuoiPB(); track pb.so) {
            <div class="t1-pb" [class.t1-pb--bad]="!pb.hashKhop">
              <span class="t1-pb__so">v{{ pb.so }}</span>
              <div class="t1-pb__body">
                <span class="t1-strong">{{ pb.tep }} · {{ pb.kichThuoc }}</span>
                <span class="t1-muted">{{ pb.nguoiTai }} · {{ pb.at }} · hash {{ pb.hash }} {{ pb.hashKhop ? '✓' : '✗ LỆCH — chặn tải' }}</span>
                @if (pb.ghiChu) { <span class="t1-muted">{{ pb.ghiChu }}</span> }
              </div>
            </div>
          }

          <div class="t1-pk__row">
            <hrm-button size="sm" variant="primary" (click)="taiXuong(t.id)">Tải xuống (kiểm hash)</hrm-button>
            <hrm-button size="sm" (click)="xem(t.id)">Xem (ghi log)</hrm-button>
          </div>

          <ins-section-label text="Log truy cập — gồm lượt BỊ TỪ CHỐI" tone="muted" [count]="t.log.length" />
          @for (l of logDao(); track $index) {
            <div class="t1-log" [class.t1-log--denied]="l.biTuChoi">
              <span class="t1-muted">{{ l.at }}</span>
              <span>{{ l.nguoi }} — {{ l.hanhDong }}</span>
              @if (l.biTuChoi) { <hrm-tag color="red" size="sm">bị từ chối</hrm-tag> }
            </div>
          }
        </div>
      }
    </ng-template>
  `,
  host: { class: 'ins-m06-tab-tailieu' },
  styles: [`
    :host { display: flex; flex-direction: column; flex: 1 1 auto; min-height: 0; }
    .t1-split { flex: 1 1 auto; min-height: 480px; display: flex; gap: 12px; align-items: stretch; }
    .t1-main { flex: 1 1 auto; min-width: 0; overflow: auto; }
    .t1-empty { padding: 40px 0; display: flex; justify-content: center; }
    .t1-tep { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
    .t1-tep__tags { display: flex; gap: 4px; }
    .t1-stack { display: flex; flex-direction: column; gap: 2px; }
    .t1-strong { color: var(--text-strong); font-weight: 500; }
    .t1-muted { font-size: var(--fs-12); color: var(--text-sub); }
    .t1-warn { color: var(--error-text); font-weight: 600; }
    .t1-hash { font-family: var(--font-mono, monospace); font-size: var(--fs-12); color: var(--success-text); }
    .t1-hash--bad { color: var(--error-text); font-weight: 700; }
    .t1-pk { display: flex; flex-direction: column; gap: 10px; font-size: var(--fs-13); }
    .t1-pk__name { margin: 0; font-weight: 600; color: var(--text-strong); }
    .t1-pk__row { display: flex; gap: 8px; }
    .t1-pb { display: flex; gap: 10px; border: 1px solid var(--border-sub); border-radius: var(--radius-md); padding: 7px 10px; }
    .t1-pb--bad { border-color: var(--error-base); background: var(--error-bg); }
    .t1-pb__so { font-family: var(--font-mono, monospace); font-weight: 700; color: var(--primary-base); }
    .t1-pb__body { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
    .t1-log { display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; font-size: var(--fs-12); color: var(--text-body); padding: 3px 0; border-bottom: 1px dashed var(--border-soft); }
    .t1-log--denied { color: var(--error-text); }
  `],
})
export class InsM06TabTaiLieu {
  protected readonly store = inject(InsM06Store);
  private readonly msg = inject(HrmMessageService);

  readonly open360 = output<string>();

  protected readonly rows = computed<M06RowTaiLieu[]>(() => this.store.taiLieuLoc().map(buildRowTaiLieu));

  private readonly tepTpl = viewChild.required<TemplateRef<unknown>>('tepTpl');
  private readonly pbTpl = viewChild.required<TemplateRef<unknown>>('pbTpl');
  private readonly hanTpl = viewChild.required<TemplateRef<unknown>>('hanTpl');
  private readonly statusTpl = viewChild.required<TemplateRef<unknown>>('statusTpl');
  private readonly actTpl = viewChild.required<TemplateRef<unknown>>('actTpl');

  protected readonly cols = computed<HrmGridColumn[]>(() => {
    const tpl: Record<string, TemplateRef<unknown> | undefined> = {
      tepCell: this.tepTpl(), pbCell: this.pbTpl(), hanCell: this.hanTpl(), trangThai: this.statusTpl(), act: this.actTpl(),
    };
    return M06_COLS_T1.map((d) => ({ ...d, cell: tpl[d.key] as HrmGridColumn['cell'] }));
  });

  /* ── peek (đóng giữ vị trí + selection — drawer contract) ── */
  protected readonly peekModes: HrmPeekMode[] = ['side'];
  private readonly peekOpen = signal(false);
  protected get peekOpenModel(): boolean { return this.peekOpen(); }
  protected set peekOpenModel(v: boolean) { this.peekOpen.set(v); }
  private readonly selId = signal<string | null>(null);
  protected readonly sel = computed(() => { const id = this.selId(); return id ? this.store.taiLieuOf(id) ?? null : null; });
  protected readonly peekTitle = computed(() => this.sel()?.ten ?? '');
  /** Chuỗi phiên bản mới → cũ. */
  protected readonly chuoiPB = computed(() => [...(this.sel()?.phienBan ?? [])].reverse());
  protected readonly logDao = computed(() => [...(this.sel()?.log ?? [])].reverse());

  protected onRowClick(row: Record<string, unknown>): void { this.selId.set(String(row['id'])); this.peekOpen.set(true); }

  protected taiXuong(id: string): void {
    const r = this.store.taiXuong(id);
    r.ok
      ? this.msg.success('Đã tải xuống — hash toàn vẹn khớp; lượt tải ghi log.')
      : this.msg.error(r.reason ?? 'Tải bị chặn.');
  }
  protected xem(id: string): void {
    const r = this.store.xemTaiLieu(id);
    r.ok ? this.msg.success('Đã mở xem — mọi lượt xem đều ghi log.') : this.msg.error(r.reason ?? 'Không xem được.');
  }
}
