import { ChangeDetectionStrategy, Component, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { HrmPageHeader, HrmSegmented } from 'hrm-ui';
import { InsM07Reports } from './reports/m07-reports';
import { InsM06TabTaiLieu } from '../m06-records/center/m06-tab-tailieu';

/** ═════════ M07 — BÁO CÁO VÀ TÀI LIỆU ═════════
 *  KHÔI PHỤC "Trung tâm báo cáo" (Report Explorer 9 nhóm — ins-m07-reports) đặt cạnh kho "Tài liệu"
 *  (ins-m06-tab-tailieu, dùng chung Hồ sơ M06). Segmented 2 view — mặc định Báo cáo.
 *  (Đã bỏ hẳn màn "Theo dõi chi" — chỉ giữ Báo cáo + Tài liệu.) */
@Component({
  selector: 'ins-m07-page',
  imports: [FormsModule, HrmPageHeader, HrmSegmented, InsM07Reports, InsM06TabTaiLieu],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <hrm-page-header class="m07-ph" [title]="'Báo cáo và Tài liệu'"
      [subtitle]="'Trung tâm báo cáo BHXH (tham số → kết quả → xuất tệp) và kho tài liệu hồ sơ (dùng chung Hồ sơ).'" />

    <div class="m07-bar">
      <hrm-segmented [ngModel]="view()" (ngModelChange)="view.set($event)" [options]="views" size="sm" />
    </div>

    <div class="m07-body">
      @switch (view()) {
        @case ('baocao') { <ins-m07-reports /> }
        @case ('tailieu') { <ins-m06-tab-tailieu /> }
      }
    </div>
  `,
  styles: [`
    :host { display: flex; flex-direction: column; flex: 1 1 auto; min-height: 0; }
    /* ds-demo global zero padding-ngang nz-page-header → set lại chuẩn đối xứng (giống M01/M02). */
    :host ::ng-deep .m07-ph .ant-page-header { padding: 16px 24px; }
    .m07-bar { flex: none; padding: 0 24px 12px; }
    .m07-body { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; padding: 0 24px 16px; overflow: auto; }
  `],
})
export class InsM07Page {
  /** View đang mở — mặc định Báo cáo (khôi phục theo yêu cầu). */
  protected readonly view = signal<'baocao' | 'tailieu'>('baocao');
  protected readonly views = [
    { label: 'Trung tâm báo cáo', value: 'baocao' },
    { label: 'Tài liệu', value: 'tailieu' },
  ];
}
