import { ChangeDetectionStrategy, Component, computed, inject, input, signal } from '@angular/core';
import { HrmMessageService, HrmStatusCell, HrmTag } from 'hrm-ui';
import { InsSectionLabel } from '../../../_shared';
import type { M06MovementRow, M06Profile360 } from '../_m06-360-data';

/** M06 · HỒ SƠ 360° — 2 tab lịch sử/kết quả (§33-37). Đọc thuần từ `profile()` (deterministic,
 *  zoneless-safe: mọi ngày/tiền là chuỗi format sẵn trong data). Mọi CTA prototype → msg.info(demo). */

type M06HistKind = 'all' | 'tang' | 'giam' | 'dieu-chinh';

/* ═════════════════════════ §33-34 — LỊCH SỬ BIẾN ĐỘNG ═════════════════════════ */

@Component({
  selector: 'ins-m06-360-history',
  imports: [HrmTag, HrmStatusCell],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="hx-card">
      <!-- Bộ lọc nhanh client-side: Tất cả | Tăng | Giảm | Điều chỉnh (active = primary). -->
      <div class="hx-chips">
        @for (f of filters; track f.key) {
          <button type="button" class="hx-chip" [class.hx-chip--on]="filterKind() === f.key"
            (click)="filterKind.set(f.key)">{{ f.label }}</button>
        }
      </div>

      <div class="hx-scroll">
        <div class="hx-tbl">
          <div class="hx-head">
            <span class="hx-th">Biến động</span>
            <span class="hx-th">Lý do</span>
            <span class="hx-th">Hiệu lực</span>
            <span class="hx-th">Kỳ</span>
            <span class="hx-th">Đợt kê khai</span>
            <span class="hx-th">Trạng thái</span>
          </div>

          @for (m of rows(); track m.id) {
            <div class="hx-row" role="button" tabindex="0"
              (click)="openMovement()" (keydown.enter)="openMovement()">
              <span class="hx-cell">
                <hrm-tag size="sm" [color]="kindColor(m.kind)">{{ m.kindLabel }}</hrm-tag>
              </span>
              <span class="hx-cell hx-strong">{{ m.reason }}</span>
              <span class="hx-cell hx-nums">{{ m.effective }}</span>
              <span class="hx-cell hx-nums">{{ m.period }}</span>
              <span class="hx-cell">{{ m.batch }}</span>
              <span class="hx-cell">
                <hrm-status-cell [status]="m.statusTone" [label]="m.statusLabel" variant="badge" />
              </span>
            </div>
          }

          @if (!rows().length) {
            <div class="hx-empty">Không có biến động khớp bộ lọc.</div>
          }
        </div>
      </div>
    </div>
  `,
  host: { class: 'ins-m06-360-history' },
  styles: [`
    :host { display: block; }
    .hx-card { background: var(--bg-surface); border: 1px solid var(--border-sub); border-radius: 12px; padding: 16px; }

    /* Bộ lọc chip — active = viền + nền primary nhạt + text primary. */
    .hx-chips { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; margin-bottom: 12px; }
    .hx-chip {
      cursor: pointer; font: inherit; font-size: var(--fs-13); font-weight: 500; color: var(--text-body);
      background: var(--bg-surface); border: 1px solid var(--border-sub); border-radius: var(--radius-full);
      padding: 4px 14px; height: 30px; white-space: nowrap;
    }
    .hx-chip:hover { border-color: var(--primary-base); color: var(--primary-base); }
    .hx-chip--on { color: var(--primary-base); background: var(--primary-bg-subtle); border-color: var(--primary-base); }

    /* Bảng custom (grid) — header + rows, border-bottom mảnh. */
    .hx-scroll { overflow-x: auto; }
    .hx-tbl { min-width: 760px; }
    .hx-head, .hx-row {
      display: grid; grid-template-columns: 120px minmax(0, 1fr) 110px 90px 120px 130px;
      gap: 12px; align-items: center;
    }
    .hx-head { padding: 0 10px 8px; border-bottom: 1px solid var(--border-sub); }
    .hx-th { font-size: var(--fs-12); font-weight: 600; color: var(--text-sub); }
    .hx-row {
      padding: 10px; border-bottom: 1px solid var(--border-soft, var(--border-sub));
      font-size: var(--fs-13); color: var(--text-body); cursor: pointer;
    }
    .hx-row:last-child { border-bottom: 0; }
    .hx-row:hover { background: var(--bg-surface-subtle); }
    .hx-cell { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    .hx-strong { color: var(--text-strong); font-weight: 500; }
    .hx-nums { font-variant-numeric: tabular-nums; }
    .hx-empty { padding: 16px 10px; font-size: var(--fs-13); color: var(--text-sub); }
  `],
})
export class InsM06Tab360History {
  private readonly msg = inject(HrmMessageService);
  readonly profile = input.required<M06Profile360>();

  /** Bộ lọc nhanh (§33). */
  protected readonly filterKind = signal<M06HistKind>('all');
  protected readonly filters: readonly { key: M06HistKind; label: string }[] = [
    { key: 'all', label: 'Tất cả' },
    { key: 'tang', label: 'Tăng' },
    { key: 'giam', label: 'Giảm' },
    { key: 'dieu-chinh', label: 'Điều chỉnh' },
  ];

  protected readonly rows = computed<M06MovementRow[]>(() => {
    const k = this.filterKind();
    const all = this.profile().movements;
    return k === 'all' ? all : all.filter((m) => m.kind === k);
  });

  protected kindColor(kind: M06MovementRow['kind']): string {
    return kind === 'tang' ? 'green' : kind === 'giam' ? 'red' : 'blue';
  }

  protected openMovement(): void { this.msg.info('Mở biến động (demo)'); }
}

/* ═════════════════════════ §35-37 — HỒ SƠ & KẾT QUẢ ═════════════════════════ */

@Component({
  selector: 'ins-m06-360-records',
  imports: [HrmStatusCell, InsSectionLabel],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <!-- A · Hồ sơ kê khai bảo hiểm (DECLARATION). -->
    <div class="rc-card">
      <ins-section-label text="Hồ sơ kê khai bảo hiểm" tone="muted" [count]="declRows().length" />
      <div class="rc-scroll">
        <div class="rc-tbl">
          <div class="rc-head">
            <span class="rc-th">Hồ sơ</span>
            <span class="rc-th">Loại</span>
            <span class="rc-th">Kỳ / thời gian</span>
            <span class="rc-th">Ngày gửi</span>
            <span class="rc-th">Trạng thái</span>
            <span class="rc-th">Kết quả</span>
          </div>

          @for (r of declRows(); track r.code) {
            <div class="rc-row" role="button" tabindex="0"
              (click)="openDecl()" (keydown.enter)="openDecl()">
              <span class="rc-cell rc-mono">{{ r.code }}</span>
              <span class="rc-cell rc-strong">{{ r.type }}</span>
              <span class="rc-cell rc-nums">{{ r.period }}</span>
              <span class="rc-cell rc-nums">{{ r.submittedAt }}</span>
              <span class="rc-cell">
                <hrm-status-cell [status]="r.statusTone" [label]="r.statusLabel" variant="badge" />
              </span>
              <span class="rc-cell">
                <hrm-status-cell [status]="r.resultTone" [label]="r.resultLabel" variant="badge" />
              </span>
            </div>
          }

          @if (!declRows().length) {
            <div class="rc-empty">Chưa có hồ sơ kê khai.</div>
          }
        </div>
      </div>
    </div>

    <!-- B · Hồ sơ chế độ BHXH (BENEFIT). -->
    <div class="rc-card">
      <ins-section-label text="Hồ sơ chế độ BHXH" tone="muted" [count]="benefitRows().length" />
      <div class="rc-scroll">
        <div class="rc-tbl">
          <div class="rc-head">
            <span class="rc-th">Hồ sơ</span>
            <span class="rc-th">Loại</span>
            <span class="rc-th">Kỳ / thời gian</span>
            <span class="rc-th">Ngày gửi</span>
            <span class="rc-th">Trạng thái</span>
            <span class="rc-th">Kết quả</span>
          </div>

          @for (r of benefitRows(); track r.code) {
            <div class="rc-row" role="button" tabindex="0"
              (click)="openBenefit()" (keydown.enter)="openBenefit()">
              <span class="rc-cell rc-mono">{{ r.code }}</span>
              <span class="rc-cell rc-strong">{{ r.type }}</span>
              <span class="rc-cell rc-nums">{{ r.period }}</span>
              <span class="rc-cell rc-nums">{{ r.submittedAt }}</span>
              <span class="rc-cell">
                <hrm-status-cell [status]="r.statusTone" [label]="r.statusLabel" variant="badge" />
              </span>
              <span class="rc-cell">
                <hrm-status-cell [status]="r.resultTone" [label]="r.resultLabel" variant="badge" />
              </span>
            </div>
          }

          @if (!benefitRows().length) {
            <div class="rc-empty">Chưa có hồ sơ chế độ.</div>
          }
        </div>
      </div>
    </div>
  `,
  host: { class: 'ins-m06-360-records' },
  styles: [`
    :host { display: flex; flex-direction: column; gap: 12px; }
    .rc-card {
      display: flex; flex-direction: column; gap: 12px;
      background: var(--bg-surface); border: 1px solid var(--border-sub); border-radius: 12px; padding: 16px;
    }

    /* Bảng custom (grid) — header + rows, border-bottom mảnh. */
    .rc-scroll { overflow-x: auto; }
    .rc-tbl { min-width: 780px; }
    .rc-head, .rc-row {
      display: grid; grid-template-columns: 140px minmax(0, 1fr) 130px 100px 130px 130px;
      gap: 12px; align-items: center;
    }
    .rc-head { padding: 0 10px 8px; border-bottom: 1px solid var(--border-sub); }
    .rc-th { font-size: var(--fs-12); font-weight: 600; color: var(--text-sub); }
    .rc-row {
      padding: 10px; border-bottom: 1px solid var(--border-soft, var(--border-sub));
      font-size: var(--fs-13); color: var(--text-body); cursor: pointer;
    }
    .rc-row:last-child { border-bottom: 0; }
    .rc-row:hover { background: var(--bg-surface-subtle); }
    .rc-cell { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    .rc-mono { font-family: var(--font-mono, monospace); font-weight: 700; color: var(--text-strong); }
    .rc-strong { color: var(--text-strong); font-weight: 500; }
    .rc-nums { font-variant-numeric: tabular-nums; }
    .rc-empty { padding: 14px 10px; font-size: var(--fs-13); color: var(--text-sub); }
  `],
})
export class InsM06Tab360Records {
  private readonly msg = inject(HrmMessageService);
  readonly profile = input.required<M06Profile360>();

  protected readonly declRows = computed(() =>
    this.profile().records.filter((r) => r.category === 'DECLARATION'));
  protected readonly benefitRows = computed(() =>
    this.profile().records.filter((r) => r.category === 'BENEFIT'));

  protected openDecl(): void { this.msg.info('Mở đợt kê khai (demo)'); }
  protected openBenefit(): void { this.msg.info('Mở hồ sơ chế độ (demo)'); }
}
