const PRE_BATCH_STATES: ReadonlySet<InsChangeState> = new Set(['phat-hien', 'can-bo-sung', 'san-sang', 'da-xac-nhan']);

/** Trạng thái dòng ĐÃ thuộc về 1 lô kê khai → cột "Đợt kê khai" hiện deep-link #NN. */
const BATCH_STATES: ReadonlySet<InsChangeState> = new Set(['da-vao-lo', 'da-nop', 'duoc-chap-nhan', 'bi-tu-choi', 'da-cap-nhat-ky', 'da-doi-soat', 'dong']);

/** Nhãn ngắn tên trường lỗi (truongLoi) → câu "Thiếu <trường>" đọc-hiểu-ngay trên lưới. */
const INS_FIELD_LABEL: Record<string, string> = {
  insCode: 'mã số BHXH', noiKCB: 'nơi đăng ký KCB', giayRaVien: 'giấy ra viện', ngayHieuLuc: 'ngày hiệu lực',
};

/** Nhãn mức tin cậy (hậu tố cột "Tình trạng & việc cần làm") — cao/trung-binh/thap → Cao/Trung bình/Thấp. */
const INS_CONF_LEVEL_LABEL: Record<InsConfidenceLevel, string> = { cao: 'Cao', 'trung-binh': 'Trung bình', thap: 'Thấp' };

/** ✨ "Vì sao cần xử lý" — ưu tiên thông điệp rule mức chặn/cảnh báo (AI1 Explain); nếu không có
 *  rule thì tóm tắt sự kiện (moTa). Đưa suy luận hệ thống thẳng lên lưới, khỏi mở panel. */
function buildViSao(c: InsChange): string {
  const chan = c.ketQuaRule.find((r) => r.muc === 'chan');
  const rule0 = chan ?? c.ketQuaRule[0];
  if (rule0) return rule0.thongDiep;
  return c.moTa;
}

/** Cột Trạng thái "nói thiếu gì" cho dòng can-bo-sung (DoD#5): trường lỗi đầu tiên hoặc nhóm ngoại lệ. */
function buildThieu(c: InsChange): string {
  if (c.trangThai !== 'can-bo-sung') return '';
  // Dòng nghi bỏ sót: viSao đã nói "Nghi thiếu — …" → status chỉ cần cue ngắn, tránh lặp.
  if (c.nguon === INS_NGUON_CHONG_SOT) return 'Chưa đối chiếu dữ liệu nguồn';
  const r = c.ketQuaRule.find((x) => x.muc === 'chan') ?? c.ketQuaRule[0];
  if (r?.truongLoi && INS_FIELD_LABEL[r.truongLoi]) return `Thiếu ${INS_FIELD_LABEL[r.truongLoi]}`;
  if (c.nhomNgoaiLe.length) return INS_EXCEPTION_LABEL[c.nhomNgoaiLe[0]];
  if (r) return r.thongDiep;
  return 'Cần bổ sung dữ liệu';
}

/** Cột "Hệ thống xử lý" — gộp Kỳ + Đợt: đã vào lô → "Kỳ 08/2026 · Đợt #08-01" (deep-link M03);
 *  da-xac-nhan → badge "chưa xếp" + lý do (T5); san-sang D02-LT → preview "Kỳ 08/2026 · sẽ xếp"
 *  (P6 hệ thống tự xếp); can-bo-sung/còn ngoại lệ → 'blocked' ("Chưa xếp"); còn lại → '—'. */
function buildDot(c: InsChange): { label: string; state: M02Row['dotState']; lo: string; reason: string } {
  const kyShort = insKy(c.kyTacDong)?.label.replace('Kỳ ', '') ?? '';
  const kyPrefix = kyShort ? `Kỳ ${kyShort} · ` : '';
  if (c.loBatchId && BATCH_STATES.has(c.trangThai)) return { label: `${kyPrefix}Đợt #${c.loBatchId.slice(8)}`, state: 'batch', lo: c.loBatchId, reason: '' };
  if (c.trangThai === 'da-xac-nhan') return { label: 'Đã xác nhận · chưa xếp', state: 'confirmed', lo: '', reason: c.lyDoChuaXepDuoc ?? 'Chưa xếp được đợt' };
  if (c.trangThai === 'san-sang') {
    if (c.nhanLuong === 'd02-lt') {
      return { label: kyShort ? `${kyPrefix}sẽ xếp` : 'sẽ xếp đợt', state: 'ready', lo: '', reason: '' };
    }
    return { label: '—', state: 'ready', lo: '', reason: '' };
  }
  if (c.trangThai === 'can-bo-sung' || c.nhomNgoaiLe.length > 0) return { label: '', state: 'blocked', lo: '', reason: '' };
  return { label: '—', state: 'none', lo: '', reason: '' };
}

export function buildM02Row(c: InsChange): M02Row {
  const nv = insNhanVien(c.nhanVienId);
  const ky = insKy(c.kyTacDong);
  const readonly = !!c.doiTuongKhoa || insKyDaKhoa(c.kyTacDong);
  const preBatch = PRE_BATCH_STATES.has(c.trangThai);
  const sla = insSlaView(c);
  const dot = buildDot(c);
  const nghiTrung = c.nhomNgoaiLe.includes('trung-du-lieu') || !!c.dongXungDot;
  const conf = insConfidence(c);
  const confLevel = insConfidenceLevel(conf);

  // Nút chính theo trạng thái + mức tin cậy (điểm 4/40):
  //  · san-sang tin cậy Cao/TB → "Xác nhận" (vào lô ngay); san-sang tin cậy Thấp → xem xét, KHÔNG xác nhận thẳng.
  //  · can-bo-sung có xung đột → "Đối chiếu"; thiếu dữ liệu → "Bổ sung".
  let primaryKind: M02Row['primaryKind'] = null;
  let primaryLabel = '';
  if (c.trangThai === 'san-sang') {
    if (confLevel === 'thap') { primaryKind = 'review'; primaryLabel = nghiTrung ? 'Đối chiếu' : 'Xem kỹ trước khi xác nhận'; }
    else { primaryKind = 'confirm'; primaryLabel = 'Xác nhận'; }
  } else if (c.trangThai === 'can-bo-sung') {
    if (nghiTrung) { primaryKind = 'review'; primaryLabel = 'Đối chiếu'; }
    else { primaryKind = 'supplement'; primaryLabel = 'Bổ sung'; }
  }

  // Nút phụ (thay menu ⋯): Loại trừ (mọi dòng còn xử lý được) / Hoàn tác (dòng đã loại trừ).
  const excludeKind: M02Row['excludeKind'] = c.trangThai === 'da-loai-tru' ? 'undo' : 'exclude';
  const excludeDisabled = excludeKind === 'exclude' && (readonly || !preBatch);

  // Lớp phân loại 6 nhóm (restructure §5/§11) — helpers thuần, deterministic.
  const phanLoai = insClassify(c);
  const hieuLuc = insHieuLucLabel(c);
  const huong = insHuongXuLy(c);

  // §4/§5/§6 redesign — cột gộp "Tình trạng", cột "Kỳ xử lý" (chỉ kỳ), điều kiện bật nút ✓ Xác nhận.
  const tinhTrangSuffix =
    phanLoai === 'san-sang' ? `· Tin cậy ${INS_CONF_LEVEL_LABEL[confLevel]}`
    : phanLoai === 'can-xu-ly' ? `· ${INS_KET_LUAN_LABEL[insKetLuan(c)]}`
    : '';
  let kyXuLyMain: string;
  let kyXuLySub = '';
  if (phanLoai === 'lien-ky') { kyXuLyMain = 'Liên kỳ'; kyXuLySub = '2 biến động liên kết'; }
  else if (c.nhomNgoaiLe.includes('chua-xac-dinh-luong') || !c.nhanLuong) { kyXuLyMain = 'Chưa xác định'; }
  else { kyXuLyMain = ky?.label ?? '—'; }
  const xacNhanEnabled = phanLoai === 'san-sang' && confLevel !== 'thap' && insDoiSoatPass(c);

  // NV1 — nút hành động CHÍNH: icon+tooltip theo trạng thái (deterministic). xacNhanEnabled đã gói
  // đúng điều kiện "san-sang · tin cậy ≠ thấp · đối soát pass"; else san-sang tin cậy thấp → "Xem kỹ";
  // còn lại (Cần xử lý...) → theo insKetLuan. actReady=true CHỈ với 'xac-nhan' (xác nhận inline).
  let actKind: M02Row['actKind'];
  let actTip: string;
  if (xacNhanEnabled) {
    actKind = 'xac-nhan'; actTip = 'Xác nhận';
  } else if (phanLoai === 'san-sang' && confLevel === 'thap') {
    actKind = 'xem-ky'; actTip = 'Xem kỹ trước khi xác nhận';
  } else {
    switch (insKetLuan(c)) {
      case 'cho-bo-sung': actKind = 'bo-sung'; actTip = 'Bổ sung'; break;
      case 'can-xac-minh': actKind = 'doi-chieu'; actTip = 'Đối chiếu'; break;
      case 'dieu-chinh-ky-truoc': actKind = 'ky-truoc'; actTip = 'Chuyển bù kỳ trước'; break;
      case 'tra-nguon-sua': actKind = 'tra-nguon'; actTip = 'Trả nguồn / chọn giá trị'; break;
      default: actKind = 'doi-chieu'; actTip = 'Xem chi tiết'; break;
    }
  }
  const actReady = actKind === 'xac-nhan';

  return {
    id: c.id,
    ten: nv?.name ?? '—',
    sub: `${nv?.code ?? '—'} · ${nv?.dept ?? ''}`,
    loaiLabel: INS_CHANGE_KIND_LABEL[c.loaiBienDong],
    loaiHue: c.loaiBienDong === 'tang' ? 'green' : c.loaiBienDong === 'giam' ? 'red' : 'blue',
    moTa: c.moTa,
    truoc: c.truoc ?? '',
    sau: c.sau ?? '',
    isDiff: c.loaiBienDong === 'dieu-chinh',
    viSao: buildViSao(c),
    viSaoNguon: c.nguon,
    isChongSot: c.nguon === INS_NGUON_CHONG_SOT,
    nghiTrung,
    confidence: conf,
    confidenceLabel: `${conf}%`,
    confidenceLevel: confLevel,
    thieu: buildThieu(c),
    dotLabel: dot.label,
    dotState: dot.state,
    dotReason: dot.reason,
    loBatchId: dot.lo,
    primaryKind,
    primaryLabel,
    excludeKind,
    excludeDisabled,
    chenhLech: c.chenhLechDuKien ?? '',
    cd: !!c.coKhongAnhHuong,
    slaLabel: sla.label,
    slaTone: sla.tone,
    ngayHieuLuc: c.ngayHieuLuc || '—',
    hanNgay: c.ngayHanXuLy || '—',
    luongDong: nv?.salary ?? '—',
    kyLabel: ky?.label.replace('Kỳ ', '') ?? '—',
    kyLocked: insKyDaKhoa(c.kyTacDong),
    trangThaiLabel: INS_CHANGE_STATE_LABEL[c.trangThai],
    trangThaiTone: INS_CHANGE_STATE_TONE[c.trangThai],
    flowShort: c.nhanLuong === 'd02-lt' ? 'D02-LT' : c.nhanLuong === 'su-vu' ? 'Hồ sơ sự vụ' : 'Chưa rõ cách nộp',
    flowHue: c.nhanLuong === 'd02-lt' ? 'blue' : c.nhanLuong === 'su-vu' ? 'purple' : 'orange',
    isCase: !!c.maCaseNguon,
    paCode: c.maPhuongAn ?? '',
    paName: c.tenPhuongAn ?? '',
    nhanChinh: insNhanPhuongAn(c).full,
    tooltipYc1: insTooltipYC1(c),
    paMissing: c.nhomNgoaiLe.includes('thieu-ma-phuong-an'),
    excLabels: c.nhomNgoaiLe.map((g) => INS_EXCEPTION_LABEL[g]),
    owner: c.owner,
    groupKey: c.trangThai,
    phanLoai,
    hieuLucNgay: hieuLuc.ngay,
    hieuLucThang: hieuLuc.thang,
    huongMain: huong.main,
    huongSub: huong.sub,
    huongKind: huong.kind,
    huongClickable: huong.clickable,
    nguyenNhan: insNguyenNhanNgan(c),
    classLabel: INS_CLASS_STATUS_LABEL[phanLoai],
    classTone: INS_CLASS_TONE[phanLoai],
    tinhTrangSuffix,
    kyXuLyMain,
    kyXuLySub,
    xacNhanEnabled,
    actKind,
    actTip,
    actReady,
    lienKet: c.lienKet,
  };
}

