/** Quỹ lương kỳ = Σ lương dòng KHÔNG tính `Đã loại khỏi kỳ`. */
function quyLuongOf(dong: InsDongLaoDongKy[]): number {
  return dong.filter((x) => x.trangThai !== 'da-loai-khoi-ky').reduce((s, x) => s + x.luongDong, 0);
}
/** Phải đóng theo quỹ = quỹ lương × tỷ lệ (mọi lương là bội 100.000 ⇒ số nguyên chính xác). */
function phaiDongOf(quyLuong: number): Record<InsQuy, number> {
  return {
    BHXH: quyLuong * M04_TY_LE.BHXH, BHYT: quyLuong * M04_TY_LE.BHYT,
    BHTN: quyLuong * M04_TY_LE.BHTN, TNLD: quyLuong * M04_TY_LE.TNLD,
  };
}

function buildSnapshot(id: string, kyId: string, phienBan: number, trangThai: InsSnapshotTrangThai,
  taiThoiDiem: string, dong: InsDongLaoDongKy[], daDong: Record<InsQuy, number>, ghiChu?: string): InsKySnapshot {
  const quyLuong = quyLuongOf(dong);
  const phaiDong = phaiDongOf(quyLuong);
  return {
    id, kyId, phienBan, trangThai, taiThoiDiem, quyLuong,
    funds: {
      BHXH: { phaiDong: phaiDong.BHXH, daDong: daDong.BHXH },
      BHYT: { phaiDong: phaiDong.BHYT, daDong: daDong.BHYT },
      BHTN: { phaiDong: phaiDong.BHTN, daDong: daDong.BHTN },
      TNLD: { phaiDong: phaiDong.TNLD, daDong: daDong.TNLD },
    },
    dong: structuredClone(dong), ghiChu,
  };
}

