const clone = <T>(x: T): T => structuredClone(x);

let snapSeq = 2;   // seed đã dùng snap-k07-v2
let btSeq = 5;     // seed đã dùng BT-05
let dnSeq = 72;    // seed đã dùng DN-072

export interface InsM04Guard { ok: boolean; reason?: string; }
export interface InsM04BulkResult { done: number; skipped: { id: string; reason: string }[]; }
export interface InsM04ChecklistItem { label: string; ok: boolean; detail?: string; linkTab3?: boolean; }

@Injectable({ providedIn: 'root' })
export class InsM04Store {
  /** Người dùng demo (maker). Duyệt = chọn người khác trong M04_NGUOI_DUYET (maker ≠ checker). */
  readonly currentUser = HR_1;

  /** Nguồn ② "Hồ sơ đã chấp nhận" đọc SỐNG từ M03 (BQA-4). KHÔNG tạo vòng import:
   *  _m03-data chỉ import _core/_m02 (không được import ngược _m04-data). */
  private readonly m03 = inject(InsM03Store);

  readonly kyMeta = signal<Record<string, InsM04KyMeta>>(clone(KY_META_SEED));
  readonly snapshots = signal<InsKySnapshot[]>(clone(SNAPSHOT_SEED));
  /** Dòng lao động ĐANG LÀM VIỆC theo kỳ (khác bản chụp trong snapshot — sửa xong phải DỰNG LẠI). */
  readonly dongLaoDong = signal<Record<string, InsDongLaoDongKy[]>>({ k06: clone(K06_DONG), k07: clone(K07_DONG) });
  readonly chungTu = signal<InsChungTuNop[]>(clone(CHUNGTU_SEED));
  readonly butToan = signal<InsButToan[]>(clone(BUTTOAN_SEED));
  readonly c12 = signal<InsBanGhiC12[]>(clone(C12_SEED));
  readonly items = signal<InsItemChenhLech[]>(clone(ITEM_SEED));
  readonly deNghi = signal<InsDeNghiThanhToan[]>(clone(DENGHI_SEED));
  /** Nhật ký append-only (bất biến #3). */
  readonly auditLog = signal<InsM04AuditEntry[]>([]);
  /** Ghi chú tương quan gửi sang M03 (kết luận a — M04 chỉ theo dõi, M03 xử lý). */
  readonly ghiChuM03 = signal<{ maTuongQuan: string; itemId: string; noiDung: string }[]>([]);

  resetDemo(): void {
    this.kyMeta.set(clone(KY_META_SEED));
    this.snapshots.set(clone(SNAPSHOT_SEED));
    this.dongLaoDong.set({ k06: clone(K06_DONG), k07: clone(K07_DONG) });
    this.chungTu.set(clone(CHUNGTU_SEED));
    this.butToan.set(clone(BUTTOAN_SEED));
    this.c12.set(clone(C12_SEED));
    this.items.set(clone(ITEM_SEED));
    this.deNghi.set(clone(DENGHI_SEED));
    this.auditLog.set([]);
    this.ghiChuM03.set([]);
  }

  /* ── đọc ── */

  meta(kyId: string): InsM04KyMeta | undefined { return this.kyMeta()[kyId]; }
  isKyKhoa(kyId: string): boolean {
    const t = this.meta(kyId)?.trangThai;
    return t === 'da-khoa' || t === 'cho-duyet-mo-lai';
  }
  snapshotsOf(kyId: string): InsKySnapshot[] {
    return this.snapshots().filter((s) => s.kyId === kyId).sort((a, b) => b.phienBan - a.phienBan);
  }
  latestSnapshot(kyId: string): InsKySnapshot | undefined { return this.snapshotsOf(kyId)[0]; }
  itemsOf(kyId: string): InsItemChenhLech[] { return this.items().filter((i) => i.kyId === kyId); }
  item(id: string): InsItemChenhLech | undefined { return this.items().find((i) => i.id === id); }

  /* ── ĐỐI SOÁT 4 NGUỒN (BQA-4 — PBI-04.01.9): ①②③④, null = "chưa có" (không số 0 giả) ── */

  /** Nguồn ① "Dự kiến nội bộ" = Σ phải đóng 4 quỹ snapshot mới nhất (null = chưa dựng snapshot).
   *  k07 v2 = 66.816.000 · k06 = 66.048.000 · k08 = null. */
  duKienNoiBo(kyId: string): number | null {
    const s = this.latestSnapshot(kyId);
    return s ? M04_QUYS.reduce((x, q) => x + s.funds[q].phaiDong, 0) : null;
  }

  /** Nguồn ② "Hồ sơ đã chấp nhận" — phải đóng theo hồ sơ kê khai cơ quan ĐÃ CHẤP NHẬN, derive
   *  SỐNG từ InsM03Store (ghiKetQua chấp nhận thêm item → số này tự cập nhật):
   *  = dự kiến nội bộ ① + 32% × lương căn cứ item TĂNG `Được chấp nhận` có NLĐ CHƯA trong dòng
   *    lao động kỳ (hồ sơ đi trước nội bộ) − 32% × lương item GIẢM (GH) `Được chấp nhận` có NLĐ
   *    CÒN trong dòng lao động kỳ. Chỉ tính lô CÙNG MÃ BHXH đang đối soát (C12 kỳ 06/07 đều của
   *    HN-070912 — tepGoc `*_HN070912`; lô HN-070913 thuộc mã khác, ngoài phạm vi).
   *  k07 = 66.816.000 + 32% × 15.000.000 (i21 M03 — e16 Dương Thùy Linh, tăng mới đã chấp nhận,
   *        chưa vào snapshot) = 66.816.000 + 4.800.000 = 71.616.000.
   *  k06 = 66.048.000 + 0 (i28/i29 M03 thuộc lô HN-070913 — không tính) ⇒ khớp C12, chênh 0. */
  hoSoDaChapNhan(kyId: string): number | null {
    const base = this.duKienNoiBo(kyId);
    if (base === null) return null;
    const MA_DOI_SOAT = 'HN-070912';
    const tyLeTong = M04_QUYS.reduce((s, q) => s + M04_TY_LE[q], 0); // 32%
    const roster = new Set(
      (this.dongLaoDong()[kyId] ?? []).filter((d) => d.trangThai !== 'da-loai-khoi-ky').map((d) => d.nhanVienId));
    let delta = 0;
    for (const it of this.m03.items()) {
      if (it.ky !== kyId || it.trangThai !== 'duoc-chap-nhan') continue;
      const lo = this.m03.los().find((l) => l.maLo === it.loId);
      if (lo?.maBHXH !== MA_DOI_SOAT) continue;
      const luong = insParseVnd(it.luongCanCu);
      if (luong <= 0) continue;
      if (it.maPhuongAn === 'GH') { if (roster.has(it.nhanVienId)) delta -= luong * tyLeTong; }
      else if (!roster.has(it.nhanVienId)) delta += luong * tyLeTong;
    }
    return Math.round(base + delta);
  }

  /** Nguồn ④ "Thanh toán & phân bổ" = Σ chứng từ nộp ĐÃ khớp nghĩa vụ / đã phân bổ của kỳ.
   *  k07 = CT-071 55.000.000 + CT-072 6.916.000 = 61.916.000 (CT-073 2.000.000 `Đã ghi nhận`
   *  chưa khớp → item i11 nhánh 7). Kỳ không có chứng từ seed (k06 đã khóa) → fallback Σ đã đóng
   *  snapshot (66.048.000 — khớp phần D C12, chênh 0). null = chưa có cả hai (k08). */
  thanhToanPhanBo(kyId: string): number | null {
    const ct = this.chungTu().filter((c) => c.kyId === kyId);
    if (ct.length) return ct.filter((c) => c.trangThai !== 'da-ghi-nhan').reduce((s, c) => s + c.soTien, 0);
    const snap = this.latestSnapshot(kyId);
    return snap ? M04_QUYS.reduce((s, q) => s + snap.funds[q].daDong, 0) : null;
  }

  /** Chênh chưa giải thích = Σ|giá trị| item trạng thái ∉ {Đã giải trình, Đã đóng}. */
  readonly unexplainedByKy = computed(() => {
    const out: Record<string, number> = {};
    for (const i of this.items()) {
      if (i.trangThai === 'da-giai-trinh' || i.trangThai === 'da-dong') continue;
      out[i.kyId] = (out[i.kyId] ?? 0) + Math.abs(i.giaTri);
    }
    return out;
  });
  /** Số item chưa có kết luận theo kỳ. */
  readonly chuaKetLuanByKy = computed(() => {
    const out: Record<string, number> = {};
    for (const i of this.items()) {
      if (i.trangThai === 'da-giai-trinh' || i.trangThai === 'da-dong') continue;
      out[i.kyId] = (out[i.kyId] ?? 0) + 1;
    }
    return out;
  });
  /** Tổng đã chấp nhận / kỳ (guard ngưỡng chấp nhận M08). */
  tongChapNhan(kyId: string): number {
    return this.itemsOf(kyId).filter((i) => i.ketLuan?.loai === 'chap-nhan')
      .reduce((s, i) => s + Math.abs(i.giaTri), 0);
  }

  /** Checklist điều kiện khóa kỳ (render ✓/✗ trong modal + lý do disabled trên master). */
  khoaChecklist(kyId: string): InsM04ChecklistItem[] {
    const snap = this.latestSnapshot(kyId);
    const unexplained = this.unexplainedByKy()[kyId] ?? 0;
    const chuaKetLuan = this.chuaKetLuanByKy()[kyId] ?? 0;
    return [
      { label: 'Snapshot đã dựng', ok: !!snap && snap.trangThai !== 'dang-dung',
        detail: snap ? `Phiên bản v${snap.phienBan} — ${M04_SNAPSHOT_LABEL[snap.trangThai]}` : 'Chưa có số liệu cho kỳ này' },
      { label: `Chênh chưa giải thích ≤ ngưỡng ${insFormatVnd(M04_NGUONG_KHOA)}`, ok: unexplained <= M04_NGUONG_KHOA,
        detail: `Hiện ${insFormatVnd(unexplained)}${unexplained > M04_NGUONG_KHOA ? ` > ngưỡng ${insFormatVnd(M04_NGUONG_KHOA)}` : ''}`, linkTab3: unexplained > 0 },
      { label: 'Mọi item chênh lệch đã có kết luận', ok: chuaKetLuan === 0,
        detail: chuaKetLuan ? `Còn ${chuaKetLuan} item chưa kết luận` : 'Đủ kết luận', linkTab3: chuaKetLuan > 0 },
      { label: 'Người duyệt ≠ người lập (maker–checker)', ok: true, detail: 'Kiểm tra tại bước duyệt khóa' },
    ];
  }

  /* ── helpers ghi ── */

  private log(entry: Omit<InsM04AuditEntry, 'at'>): void {
    this.auditLog.update((l) => [...l, { at: demoNow(), ...entry }]);
  }
  private patchMeta(kyId: string, p: Partial<InsM04KyMeta>): void {
    this.kyMeta.update((m) => ({ ...m, [kyId]: { ...m[kyId], ...p } }));
  }
  /** Đổi trạng thái kỳ + APPEND lịch sử (timeline vòng đời trên thẻ kỳ — BQA-15). */
  private chuyenTrangThaiKy(kyId: string, trangThai: InsM04KyTrangThai, p?: Partial<InsM04KyMeta>): void {
    const at = demoNow().slice(0, 5); // dd/MM
    this.kyMeta.update((m) => ({
      ...m,
      [kyId]: {
        ...m[kyId], ...p, trangThai,
        lichSuTrangThai: [...(m[kyId]?.lichSuTrangThai ?? []), { trangThai, at }],
      },
    }));
  }
  private patchItem(id: string, p: Partial<InsItemChenhLech>): void {
    this.items.update((list) => list.map((i) => (i.id === id ? { ...i, ...p } : i)));
  }

  /* ── snapshot ── */

  /** Dựng snapshot = PHIÊN BẢN MỚI từ dòng lao động hiện hành (bản cũ tra được, không ghi đè). */
  dungSnapshot(kyId: string): InsM04Guard {
    if (this.isKyKhoa(kyId)) return { ok: false, reason: 'Kỳ đã khóa — snapshot đã đóng băng, không dựng lại.' };
    const dong = this.dongLaoDong()[kyId];
    if (!dong?.length) return { ok: false, reason: 'Chưa có số liệu cho kỳ này — biến động kỳ chưa xử lý xong (M02).' };
    if (this.snapshotsOf(kyId).some((s) => s.trangThai === 'dang-dung')) {
      return { ok: false, reason: 'Đang có lượt dựng chạy — không chạy song song cùng kỳ.' };
    }
    const latest = this.latestSnapshot(kyId);
    const daDong = latest
      ? { BHXH: latest.funds.BHXH.daDong, BHYT: latest.funds.BHYT.daDong, BHTN: latest.funds.BHTN.daDong, TNLD: latest.funds.TNLD.daDong }
      : { BHXH: 0, BHYT: 0, BHTN: 0, TNLD: 0 };
    const phienBan = (latest?.phienBan ?? 0) + 1;
    const snap = buildSnapshot(`snap-${kyId}-v${++snapSeq}`, kyId, phienBan, 'da-dung', demoNow(), dong, daDong,
      'Dựng lại từ dòng lao động hiện hành');
    this.snapshots.update((l) => [...l, snap]);
    this.log({ nguoi: this.currentUser, hanhDong: `Dựng snapshot ${kyId} phiên bản v${phienBan} (bản cũ tra được)`, refs: [snap.id] });
    return { ok: true };
  }

  /* ── dòng lao động (sửa/loại — lý do bắt buộc; vượt trần/sàn → cảnh báo + tự đặt lại) ── */

  suaDongLaoDong(kyId: string, dongId: string, luongMoi: number, lyDo: string): InsM04Guard & { adjusted?: string } {
    if (this.isKyKhoa(kyId)) return { ok: false, reason: 'Kỳ đã khóa — phần thuộc kỳ chỉ đọc.' };
    if (!lyDo.trim()) return { ok: false, reason: 'Sửa tay bắt buộc có lý do (audit).' };
    const dong = this.dongLaoDong()[kyId]?.find((x) => x.id === dongId);
    if (!dong) return { ok: false, reason: 'Không tìm thấy dòng lao động.' };
    if (dong.trangThai === 'da-loai-khoi-ky') return { ok: false, reason: 'Dòng đã loại khỏi kỳ — không sửa.' };
    if (dong.trangThai === 'da-dong-bang') return { ok: false, reason: 'Dòng đã đóng băng theo kỳ khóa.' };
    let adjusted: string | undefined;
    let luong = luongMoi;
    if (luong > M04_TRAN_LUONG_DONG) { luong = M04_TRAN_LUONG_DONG; adjusted = `vượt trần — tự đặt lại ${insFormatVnd(M04_TRAN_LUONG_DONG)}`; }
    if (luong < M04_SAN_LUONG_DONG) { luong = M04_SAN_LUONG_DONG; adjusted = `dưới sàn — tự đặt lại ${insFormatVnd(M04_SAN_LUONG_DONG)}`; }
    this.dongLaoDong.update((m) => ({
      ...m,
      [kyId]: m[kyId].map((x) => x.id === dongId
        ? { ...x, luongDong: luong, trangThai: 'da-sua-tay' as const, lyDo: lyDo.trim(),
            ghiChu: `Sửa tay ${insFormatVnd(dong.luongDong)} → ${insFormatVnd(luong)}${adjusted ? ` (${adjusted})` : ''} — dựng lại snapshot để cập nhật bảng` }
        : x),
    }));
    this.log({ nguoi: this.currentUser, hanhDong: `Sửa tay lương đóng ${dongId}: ${insFormatVnd(dong.luongDong)} → ${insFormatVnd(luong)}${adjusted ? ` (${adjusted})` : ''}`, refs: [dongId], lyDo: lyDo.trim() });
    return { ok: true, adjusted };
  }

  loaiDongLaoDong(kyId: string, dongId: string, lyDo: string): InsM04Guard {
    if (this.isKyKhoa(kyId)) return { ok: false, reason: 'Kỳ đã khóa — phần thuộc kỳ chỉ đọc.' };
    if (!lyDo.trim()) return { ok: false, reason: 'Loại khỏi kỳ bắt buộc có lý do — không xóa vật lý.' };
    const dong = this.dongLaoDong()[kyId]?.find((x) => x.id === dongId);
    if (!dong) return { ok: false, reason: 'Không tìm thấy dòng lao động.' };
    if (dong.trangThai === 'da-loai-khoi-ky') return { ok: false, reason: 'Dòng đã ở trạng thái Đã loại khỏi kỳ.' };
    this.dongLaoDong.update((m) => ({
      ...m,
      [kyId]: m[kyId].map((x) => x.id === dongId ? { ...x, trangThai: 'da-loai-khoi-ky' as const, lyDo: lyDo.trim() } : x),
    }));
    this.log({ nguoi: this.currentUser, hanhDong: `Loại khỏi kỳ dòng ${dongId} (không xóa vật lý — dựng lại snapshot để cập nhật)`, refs: [dongId], lyDo: lyDo.trim() });
    return { ok: true };
  }

  /* ── bút toán (append-only — KHÔNG xóa; lập ≠ duyệt; đảo đưa tổng về 0) ── */

  lapButToan(kyId: string, loai: InsButToanLoai, giaTri: number, lyDo: string): InsM04Guard {
    if (!lyDo.trim()) return { ok: false, reason: 'Lập bút toán bắt buộc có lý do.' };
    if (this.isKyKhoa(kyId)) return { ok: false, reason: 'Kỳ bị tác động đã khóa — cần mở lại kỳ trước.' };
    if (!giaTri) return { ok: false, reason: 'Giá trị bút toán phải khác 0.' };
    const id = `BT-${String(++btSeq).padStart(2, '0')}`;
    this.butToan.update((l) => [...l, {
      id, kyPhatSinh: kyId, kyBiTacDong: kyId, loai, giaTri, lyDo: lyDo.trim(),
      nguoiLap: this.currentUser, trangThai: 'cho-duyet', ngay: M04_TODAY,
    }]);
    this.log({ nguoi: this.currentUser, hanhDong: `Lập bút toán ${id} (${M04_BT_LOAI_LABEL[loai]} ${insFormatVnd(giaTri, true)}) — chờ duyệt`, refs: [id], lyDo: lyDo.trim() });
    return { ok: true };
  }

  guiDuyetButToan(id: string): InsM04Guard {
    const bt = this.butToan().find((b) => b.id === id);
    if (!bt) return { ok: false, reason: 'Không tìm thấy bút toán.' };
    if (bt.trangThai !== 'nhap') return { ok: false, reason: `Chỉ gửi duyệt được bút toán Nháp (hiện: ${M04_BT_LABEL[bt.trangThai]}).` };
    this.butToan.update((l) => l.map((b) => (b.id === id ? { ...b, trangThai: 'cho-duyet' as const } : b)));
    this.log({ nguoi: this.currentUser, hanhDong: `Gửi duyệt bút toán ${id}`, refs: [id] });
    return { ok: true };
  }

  /** Duyệt bút toán — GUARD maker ≠ checker. */
  duyetButToan(id: string, nguoiDuyet: string): InsM04Guard {
    const bt = this.butToan().find((b) => b.id === id);
    if (!bt) return { ok: false, reason: 'Không tìm thấy bút toán.' };
    if (bt.trangThai !== 'cho-duyet') return { ok: false, reason: `Chỉ duyệt được bút toán Chờ duyệt (hiện: ${M04_BT_LABEL[bt.trangThai]}).` };
    if (nguoiDuyet === bt.nguoiLap) return { ok: false, reason: `Người lập (${bt.nguoiLap}) không được tự duyệt — maker ≠ checker.` };
    this.butToan.update((l) => l.map((b) => (b.id === id ? { ...b, trangThai: 'da-duyet' as const, nguoiDuyet } : b)));
    this.log({ nguoi: nguoiDuyet, hanhDong: `Duyệt bút toán ${id} (người lập ${bt.nguoiLap})`, refs: [id] });
    return { ok: true };
  }

  /** Đảo bút toán — sinh bút toán MỚI giá trị đối, link 2 chiều; bản gốc → Đã đảo (không xóa). */
  daoButToan(id: string, lyDo: string): InsM04Guard {
    const bt = this.butToan().find((b) => b.id === id);
    if (!bt) return { ok: false, reason: 'Không tìm thấy bút toán.' };
    if (!lyDo.trim()) return { ok: false, reason: 'Đảo bút toán bắt buộc có lý do.' };
    if (bt.trangThai !== 'da-duyet') return { ok: false, reason: `Chỉ đảo được bút toán Đã duyệt (hiện: ${M04_BT_LABEL[bt.trangThai]}).` };
    if (bt.loai === 'dao') return { ok: false, reason: 'Đây đã là bút toán đảo — không đảo tiếp.' };
    if (this.isKyKhoa(bt.kyBiTacDong)) return { ok: false, reason: 'Kỳ bị tác động đã khóa — cần mở lại kỳ trước.' };
    const daoId = `BT-${String(++btSeq).padStart(2, '0')}`;
    this.butToan.update((l) => [
      ...l.map((b) => (b.id === id ? { ...b, trangThai: 'da-dao' as const, refDao: daoId } : b)),
      { id: daoId, kyPhatSinh: bt.kyPhatSinh, kyBiTacDong: bt.kyBiTacDong, loai: 'dao' as const,
        giaTri: -bt.giaTri, lyDo: `Bút toán đảo ${id} — ${lyDo.trim()}`, nguoiLap: this.currentUser,
        trangThai: 'da-duyet' as const, refDao: id, ngay: M04_TODAY },
    ]);
    this.log({ nguoi: this.currentUser, hanhDong: `Đảo bút toán ${id} → ${daoId} (tổng cặp = 0, append-only)`, refs: [id, daoId], lyDo: lyDo.trim() });
    return { ok: true };
  }

  /* ── C12: nhập tay + tải tệp gốc ── */

  nhapTayC12(id: string, lyDo: string): InsM04Guard {
    const rec = this.c12().find((r) => r.id === id);
    if (!rec) return { ok: false, reason: 'Không tìm thấy bản ghi C12.' };
    if (rec.trangThai !== 'boc-tach-loi') return { ok: false, reason: 'Chỉ nhập tay khi bản ghi ở trạng thái Bóc tách lỗi.' };
    if (!lyDo.trim()) return { ok: false, reason: 'Nhập tay bắt buộc có lý do (đánh dấu nguồn nhập tay).' };
    this.c12.update((l) => l.map((r) => r.id === id
      ? { ...r, nguonGiaTri: 'nhap-tay' as const, lyDoNhapTay: lyDo.trim(),
          phan: { a: 'Lao động: 12 người (nhập tay theo bản giấy)', b: 'Quỹ lương làm căn cứ: 235.536.000',
            c: 'Phải đóng điều chỉnh: 0 (đợt điều chỉnh không phát sinh)', d: 'Đã nộp ghi nhận: —', dd: 'Chênh lệch/kết dư: 0' } }
      : r));
    this.log({ nguoi: this.currentUser, hanhDong: `Nhập tay giá trị bản ghi ${id} (giữ tệp gốc bất biến, nguồn = nhập tay)`, refs: [id], lyDo: lyDo.trim() });
    return { ok: true };
  }

  /** Tải tệp gốc — tệp bất biến, MỖI lượt tải ghi log. */
  taiTepGoc(id: string): InsM04Guard {
    const rec = this.c12().find((r) => r.id === id);
    if (!rec || rec.trangThai === 'chua-nhan') return { ok: false, reason: 'Bản ghi chưa nhận — không có tệp gốc.' };
    this.log({ nguoi: this.currentUser, hanhDong: `Tải tệp gốc ${rec.tepGoc} (bản ghi ${id})`, refs: [id] });
    return { ok: true };
  }

  /* ── item chênh lệch: gán nguyên nhân + 3 kết luận + hủy (đều bulk, dry-run được) ── */

  private itemSkipReason(i: InsItemChenhLech, forKetLuan: boolean): string | null {
    if (this.isKyKhoa(i.kyId)) return 'Kỳ đã khóa — item chỉ đọc.';
    if (i.trangThai === 'da-dong') return 'Item Đã đóng — chỉ đọc.';
    if (forKetLuan && i.trangThai === 'da-giai-trinh') return 'Item đã có kết luận — hủy kết luận trước khi kết luận lại.';
    return null;
  }

  /** Dry-run gán nguyên nhân/kết luận — map thẳng vào `ins-bulk-bar.blocked[]`. */
  itemPreview(ids: string[], forKetLuan: boolean): { eligible: number; blocked: { reason: string; count: number }[] } {
    const byReason = new Map<string, number>();
    let eligible = 0;
    for (const id of ids) {
      const i = this.item(id);
      const reason = i ? this.itemSkipReason(i, forKetLuan) : 'Không tìm thấy item.';
      if (reason === null) eligible++;
      else byReason.set(reason, (byReason.get(reason) ?? 0) + 1);
    }
    return { eligible, blocked: [...byReason].map(([reason, count]) => ({ reason, count })) };
  }

  /** Gán nhánh nguyên nhân + reason code + owner (bulk — thành công một phần). */
  ganNguyenNhan(ids: string[], nhanh: number, owner: string): InsM04BulkResult {
    const skipped: { id: string; reason: string }[] = [];
    const doneIds: string[] = [];
    for (const id of ids) {
      const i = this.item(id);
      if (!i) { skipped.push({ id, reason: 'Không tìm thấy item.' }); continue; }
      const reason = this.itemSkipReason(i, false);
      if (reason) { skipped.push({ id, reason }); continue; }
      this.patchItem(id, {
        nhanh, reasonCode: `RC-${String(nhanh).padStart(2, '0')}`, owner,
        ...(i.trangThai === 'moi-phat-hien' ? { trangThai: 'da-gan-nguyen-nhan' as const } : {}),
      });
      doneIds.push(id);
    }
    if (doneIds.length) {
      this.log({ nguoi: this.currentUser, hanhDong: `Gán nguyên nhân nhánh ${nhanh} (${M04_NHANH_LABEL[nhanh]}) + owner ${owner} cho ${doneIds.length} item`, refs: doneIds });
    }
    return { done: doneIds.length, skipped };
  }

  /** 3 loại kết luận (bulk). (a) sinh yêu cầu → mã tương quan + ghi chú M03;
   *  (b) chấp nhận → GUARD tổng chấp nhận/kỳ ≤ ngưỡng M08 + chờ duyệt;
   *  (c) chuyển exception → M05/M06 + mã tương quan. */
  ketLuan(ids: string[], loai: InsKetLuanLoai, lyDo: string, phanHe?: 'm05' | 'm06')
    : InsM04BulkResult & { maTuongQuan: string[] } {
    const skipped: { id: string; reason: string }[] = [];
    const maTuongQuan: string[] = [];
    if (!lyDo.trim()) {
      return { done: 0, maTuongQuan, skipped: ids.map((id) => ({ id, reason: 'Kết luận bắt buộc có lý do.' })) };
    }
    const eligible: InsItemChenhLech[] = [];
    for (const id of ids) {
      const i = this.item(id);
      if (!i) { skipped.push({ id, reason: 'Không tìm thấy item.' }); continue; }
      const reason = this.itemSkipReason(i, true);
      if (reason) { skipped.push({ id, reason }); continue; }
      eligible.push(i);
    }
    if (loai === 'chap-nhan' && eligible.length) {
      // GUARD ngưỡng M08: tổng đã chấp nhận + phần chọn ≤ ngưỡng — vượt thì chặn TOÀN BỘ lượt.
      const kyId = eligible[0].kyId;
      const tongMoi = this.tongChapNhan(kyId) + eligible.reduce((s, i) => s + Math.abs(i.giaTri), 0);
      if (tongMoi > M04_NGUONG_CHAP_NHAN) {
        return {
          done: 0, maTuongQuan,
          skipped: [...skipped, ...eligible.map((i) => ({
            id: i.id,
            reason: `Tổng chấp nhận/kỳ ${insFormatVnd(tongMoi)} > ngưỡng ${insFormatVnd(M04_NGUONG_CHAP_NHAN)} (M08) — thu hẹp phạm vi hoặc sinh yêu cầu điều chỉnh.`,
          }))],
        };
      }
    }
    const doneIds: string[] = [];
    for (const i of eligible) {
      const info: InsKetLuanInfo = { loai, lyDo: lyDo.trim(), nguoi: this.currentUser, at: demoNow(),
        trangThai: loai === 'sinh-yeu-cau' ? 'da-sinh-yeu-cau' : loai === 'chap-nhan' ? 'cho-duyet-chap-nhan' : 'da-chuyen' };
      if (loai === 'sinh-yeu-cau') {
        info.maTuongQuan = insNextCorrelationId();
        info.phanHeNhan = 'm03';
        maTuongQuan.push(info.maTuongQuan);
        this.ghiChuM03.update((l) => [...l, {
          maTuongQuan: info.maTuongQuan!, itemId: i.id,
          noiDung: `Yêu cầu điều chỉnh từ đối soát kỳ 07: ${i.moTa} (${insFormatVnd(i.giaTri, true)}) — gắn kỳ hiện hành, đi D02-LT`,
        }]);
      } else if (loai === 'chuyen-exception') {
        info.maTuongQuan = insNextCorrelationId();
        info.phanHeNhan = phanHe ?? 'm06';
        maTuongQuan.push(info.maTuongQuan);
      }
      this.patchItem(i.id, { trangThai: 'da-giai-trinh', ketLuan: info });
      doneIds.push(i.id);
    }
    if (doneIds.length) {
      this.log({
        nguoi: this.currentUser, refs: doneIds, lyDo: lyDo.trim(),
        hanhDong: `Kết luận "${M04_KETLUAN_LABEL[loai]}" ${doneIds.length} item${maTuongQuan.length ? ` — mã tương quan ${maTuongQuan.join(', ')}` : ''}`,
      });
    }
    return { done: doneIds.length, skipped, maTuongQuan };
  }

  /** Hủy kết luận — kỳ chưa khóa; item về "chưa kết luận" (Đã gán nguyên nhân); KHÔNG xóa lịch sử. */
  huyKetLuan(ids: string[], lyDo: string): InsM04BulkResult {
    const skipped: { id: string; reason: string }[] = [];
    const doneIds: string[] = [];
    if (!lyDo.trim()) return { done: 0, skipped: ids.map((id) => ({ id, reason: 'Hủy kết luận bắt buộc có lý do.' })) };
    for (const id of ids) {
      const i = this.item(id);
      if (!i) { skipped.push({ id, reason: 'Không tìm thấy item.' }); continue; }
      if (this.isKyKhoa(i.kyId)) { skipped.push({ id, reason: 'Kỳ đã khóa — không hủy kết luận.' }); continue; }
      if (i.trangThai === 'da-dong') { skipped.push({ id, reason: 'Item Đã đóng — kết luận đã duyệt, không hủy.' }); continue; }
      if (!i.ketLuan) { skipped.push({ id, reason: 'Item chưa có kết luận.' }); continue; }
      this.patchItem(id, {
        trangThai: 'da-gan-nguyen-nhan', ketLuan: undefined,
        lichSuKetLuan: [...(i.lichSuKetLuan ?? []), i.ketLuan],
      });
      doneIds.push(id);
    }
    if (doneIds.length) this.log({ nguoi: this.currentUser, hanhDong: `Hủy kết luận ${doneIds.length} item (lịch sử giữ nguyên)`, refs: doneIds, lyDo: lyDo.trim() });
    return { done: doneIds.length, skipped };
  }

  /** BQA-17 — Duyệt kết luận CHẤP NHẬN (PBI-04.01.10 §4.3.8 nhánh b): `Chờ duyệt chấp nhận →
   *  Đã chấp nhận` (kết thúc — item Đã đóng, đóng CHỈ qua kết luận). GUARD maker ≠ checker:
   *  người duyệt ≠ người lập kết luận (AC: "người lập trùng người duyệt bị chặn"). Bulk. */
  duyetChapNhan(ids: string[], nguoiDuyet: string): InsM04BulkResult {
    const skipped: { id: string; reason: string }[] = [];
    const doneIds: string[] = [];
    for (const id of ids) {
      const i = this.item(id);
      if (!i) { skipped.push({ id, reason: 'Không tìm thấy item.' }); continue; }
      if (this.isKyKhoa(i.kyId)) { skipped.push({ id, reason: 'Kỳ đã khóa — item chỉ đọc.' }); continue; }
      const kl = i.ketLuan;
      if (!kl || kl.loai !== 'chap-nhan' || kl.trangThai !== 'cho-duyet-chap-nhan') {
        skipped.push({ id, reason: 'Item không ở trạng thái Chờ duyệt chấp nhận.' }); continue;
      }
      if (nguoiDuyet === kl.nguoi) {
        skipped.push({ id, reason: `Người lập (${kl.nguoi}) không được tự duyệt — maker ≠ checker.` }); continue;
      }
      this.patchItem(id, { trangThai: 'da-dong', ketLuan: { ...kl, trangThai: 'da-chap-nhan', nguoiDuyet } });
      doneIds.push(id);
    }
    if (doneIds.length) {
      this.log({ nguoi: nguoiDuyet, hanhDong: `Duyệt chấp nhận ${doneIds.length} item — Chờ duyệt chấp nhận → Đã chấp nhận (item Đã đóng)`, refs: doneIds });
    }
    return { done: doneIds.length, skipped };
  }

  /* ── vòng khóa / mở lại kỳ (maker–checker, render như PBI) ── */

  khoaKy(kyId: string): InsM04Guard {
    const meta = this.meta(kyId);
    if (!meta) return { ok: false, reason: 'Không tìm thấy kỳ.' };
    if (meta.trangThai !== 'dang-doi-soat') return { ok: false, reason: `Chỉ khóa được kỳ Đang đối soát (hiện: ${M04_KY_LABEL[meta.trangThai]}).` };
    const fail = this.khoaChecklist(kyId).filter((c) => !c.ok);
    if (fail.length) return { ok: false, reason: fail.map((c) => c.detail ?? c.label).join(' · ') };
    this.chuyenTrangThaiKy(kyId, 'cho-duyet-khoa', { nguoiLapKhoa: this.currentUser });
    this.log({ nguoi: this.currentUser, hanhDong: `Đề nghị khóa kỳ ${kyId} — chuyển Chờ duyệt khóa`, refs: [kyId] });
    return { ok: true };
  }

  /** Duyệt khóa — GUARD người duyệt ≠ người lập; khóa xong: snapshot đóng băng + chuyển số dư kỳ sau. */
  duyetKhoa(kyId: string, nguoiDuyet: string): InsM04Guard {
    const meta = this.meta(kyId);
    if (!meta || meta.trangThai !== 'cho-duyet-khoa') return { ok: false, reason: 'Kỳ không ở trạng thái Chờ duyệt khóa.' };
    if (nguoiDuyet === meta.nguoiLapKhoa) return { ok: false, reason: `Người lập (${meta.nguoiLapKhoa}) không được tự duyệt — maker ≠ checker.` };
    this.chuyenTrangThaiKy(kyId, 'da-khoa');
    // Snapshot mới nhất → Đã đóng băng; dòng lao động tham gia → Đã đóng băng.
    const latest = this.latestSnapshot(kyId);
    if (latest) this.snapshots.update((l) => l.map((s) => (s.id === latest.id ? { ...s, trangThai: 'da-dong-bang' as const } : s)));
    this.dongLaoDong.update((m) => ({
      ...m,
      [kyId]: (m[kyId] ?? []).map((x) => (x.trangThai === 'da-loai-khoi-ky' ? x : { ...x, trangThai: 'da-dong-bang' as const })),
    }));
    // Số dư cuối kỳ (Σ còn thiếu 4 quỹ) → số dư đầu KỲ KẾ TIẾP.
    const soDu = latest ? M04_QUYS.reduce((s, q) => s + (latest.funds[q].phaiDong - latest.funds[q].daDong), 0) : 0;
    const nextKy = kyId === 'k06' ? 'k07' : kyId === 'k07' ? 'k08' : null;
    if (nextKy) this.patchMeta(nextKy, { soDuDauKy: soDu });
    this.log({ nguoi: nguoiDuyet, hanhDong: `Duyệt khóa kỳ ${kyId} — snapshot đóng băng, số dư cuối ${insFormatVnd(soDu)} chuyển sang kỳ sau`, refs: [kyId] });
    return { ok: true };
  }

  tuChoiKhoa(kyId: string, lyDo: string): InsM04Guard {
    const meta = this.meta(kyId);
    if (!meta || meta.trangThai !== 'cho-duyet-khoa') return { ok: false, reason: 'Kỳ không ở trạng thái Chờ duyệt khóa.' };
    if (!lyDo.trim()) return { ok: false, reason: 'Từ chối khóa bắt buộc có lý do.' };
    this.chuyenTrangThaiKy(kyId, 'dang-doi-soat', { nguoiLapKhoa: undefined });
    this.log({ nguoi: this.currentUser, hanhDong: `Từ chối khóa kỳ ${kyId} — về Đang đối soát`, refs: [kyId], lyDo: lyDo.trim() });
    return { ok: true };
  }

  /** Mở lại kỳ — quyền đặc biệt + lý do; KHÔNG mở dây chuyền; AI cấm thực hiện (chỉ người dùng bấm). */
  moLaiKy(kyId: string, lyDo: string): InsM04Guard {
    const meta = this.meta(kyId);
    if (!meta) return { ok: false, reason: 'Không tìm thấy kỳ.' };
    if (meta.trangThai !== 'da-khoa') return { ok: false, reason: `Chỉ mở lại được kỳ Đã khóa (hiện: ${M04_KY_LABEL[meta.trangThai]}).` };
    if (!lyDo.trim()) return { ok: false, reason: 'Mở lại kỳ bắt buộc có lý do + tài liệu.' };
    this.chuyenTrangThaiKy(kyId, 'cho-duyet-mo-lai', { nguoiLapMoLai: this.currentUser });
    this.log({ nguoi: this.currentUser, hanhDong: `Đề nghị mở lại kỳ ${kyId} — chuyển Chờ duyệt mở lại`, refs: [kyId], lyDo: lyDo.trim() });
    return { ok: true };
  }

  /** Duyệt mở lại → PHIÊN BẢN KỲ MỚI (snapshot cũ nguyên vẹn), kỳ đứng ở `Mở lại` (BQA-15 — nhãn
   *  nhìn thấy được; KHÔNG nhảy thẳng Đang đối soát); người dùng bấm "Tiếp tục đối soát" mới chuyển. */
  duyetMoLai(kyId: string, nguoiDuyet: string): InsM04Guard {
    const meta = this.meta(kyId);
    if (!meta || meta.trangThai !== 'cho-duyet-mo-lai') return { ok: false, reason: 'Kỳ không ở trạng thái Chờ duyệt mở lại.' };
    if (nguoiDuyet === meta.nguoiLapMoLai) return { ok: false, reason: `Người lập (${meta.nguoiLapMoLai}) không được tự duyệt — maker ≠ checker.` };
    this.chuyenTrangThaiKy(kyId, 'mo-lai', {
      phienBanKy: meta.phienBanKy + 1, soLanMoLai: meta.soLanMoLai + 1, nguoiLapMoLai: undefined,
    });
    // Dòng lao động rã đông (snapshot đóng băng GIỮ NGUYÊN — phiên bản kỳ mới dựng snapshot mới).
    this.dongLaoDong.update((m) => ({
      ...m,
      [kyId]: (m[kyId] ?? []).map((x) => (x.trangThai === 'da-dong-bang' ? { ...x, trangThai: 'da-xac-nhan' as const } : x)),
    }));
    this.log({ nguoi: nguoiDuyet, hanhDong: `Duyệt mở lại kỳ ${kyId} — PHIÊN BẢN KỲ v${meta.phienBanKy + 1}, kỳ ở trạng thái Mở lại (bấm "Tiếp tục đối soát" để vào bước đối soát); snapshot cũ nguyên; KHÔNG mở dây chuyền`, refs: [kyId] });
    return { ok: true };
  }

  /** Kỳ `Mở lại` → `Đang đối soát` — bước tiếp theo do NGƯỜI DÙNG bấm (BQA-15). */
  tiepTucDoiSoat(kyId: string): InsM04Guard {
    const meta = this.meta(kyId);
    if (!meta || meta.trangThai !== 'mo-lai') return { ok: false, reason: `Chỉ tiếp tục đối soát được kỳ Mở lại (hiện: ${meta ? M04_KY_LABEL[meta.trangThai] : '—'}).` };
    this.chuyenTrangThaiKy(kyId, 'dang-doi-soat');
    this.log({ nguoi: this.currentUser, hanhDong: `Tiếp tục đối soát kỳ ${kyId} — Mở lại → Đang đối soát`, refs: [kyId] });
    return { ok: true };
  }

  tuChoiMoLai(kyId: string, lyDo: string): InsM04Guard {
    const meta = this.meta(kyId);
    if (!meta || meta.trangThai !== 'cho-duyet-mo-lai') return { ok: false, reason: 'Kỳ không ở trạng thái Chờ duyệt mở lại.' };
    if (!lyDo.trim()) return { ok: false, reason: 'Từ chối mở lại bắt buộc có lý do.' };
    this.chuyenTrangThaiKy(kyId, 'da-khoa', { nguoiLapMoLai: undefined });
    this.log({ nguoi: this.currentUser, hanhDong: `Từ chối mở lại kỳ ${kyId} — giữ Đã khóa`, refs: [kyId], lyDo: lyDo.trim() });
    return { ok: true };
  }

  /* ── đề nghị thanh toán (6+1; chưa duyệt không gửi; thu hồi giữ bản cũ) ── */

  lapDeNghi(kyId: string): InsM04Guard {
    if (this.isKyKhoa(kyId)) return { ok: false, reason: 'Kỳ đã khóa — phần thuộc kỳ chỉ đọc.' };
    const snap = this.latestSnapshot(kyId);
    if (!snap) return { ok: false, reason: 'Chưa có số liệu cho kỳ này — dựng snapshot trước.' };
    const soTheoQuy: Partial<Record<InsQuy, number>> = {};
    let tong = 0;
    for (const q of M04_QUYS) {
      const thieu = snap.funds[q].phaiDong - snap.funds[q].daDong;
      if (thieu > 0) { soTheoQuy[q] = thieu; tong += thieu; }
    }
    if (!tong) return { ok: false, reason: 'Không còn quỹ nào thiếu — không có gì để đề nghị.' };
    const id = `DN-${String(++dnSeq).padStart(3, '0')}`;
    this.deNghi.update((l) => [...l, {
      id, kyId, soTheoQuy, tong, hanNop: '25/08/2026', trangThai: 'nhap', nguoiLap: this.currentUser,
      ghiChu: `Lập từ còn thiếu snapshot v${snap.phienBan} (tách theo quỹ)`,
    }]);
    this.log({ nguoi: this.currentUser, hanhDong: `Lập đề nghị thanh toán ${id} (${insFormatVnd(tong)})`, refs: [id] });
    return { ok: true };
  }

  guiDuyetDeNghi(id: string): InsM04Guard {
    const dn = this.deNghi().find((x) => x.id === id);
    if (!dn) return { ok: false, reason: 'Không tìm thấy đề nghị.' };
    if (dn.trangThai !== 'nhap') return { ok: false, reason: `Chỉ gửi duyệt được đề nghị Nháp (hiện: ${M04_DENGHI_LABEL[dn.trangThai]}).` };
    this.deNghi.update((l) => l.map((x) => (x.id === id ? { ...x, trangThai: 'cho-duyet' as const } : x)));
    this.log({ nguoi: this.currentUser, hanhDong: `Gửi duyệt đề nghị ${id}`, refs: [id] });
    return { ok: true };
  }

  duyetDeNghi(id: string, nguoiDuyet: string): InsM04Guard {
    const dn = this.deNghi().find((x) => x.id === id);
    if (!dn) return { ok: false, reason: 'Không tìm thấy đề nghị.' };
    if (dn.trangThai !== 'cho-duyet') return { ok: false, reason: `Chỉ duyệt được đề nghị Chờ duyệt (hiện: ${M04_DENGHI_LABEL[dn.trangThai]}).` };
    if (nguoiDuyet === dn.nguoiLap) return { ok: false, reason: `Người lập (${dn.nguoiLap}) không được tự duyệt — maker ≠ checker.` };
    this.deNghi.update((l) => l.map((x) => (x.id === id ? { ...x, trangThai: 'da-duyet' as const, nguoiDuyet } : x)));
    this.log({ nguoi: nguoiDuyet, hanhDong: `Duyệt đề nghị ${id}`, refs: [id] });
    return { ok: true };
  }

  guiKeToanDeNghi(id: string): InsM04Guard {
    const dn = this.deNghi().find((x) => x.id === id);
    if (!dn) return { ok: false, reason: 'Không tìm thấy đề nghị.' };
    if (dn.trangThai !== 'da-duyet') return { ok: false, reason: 'Chưa duyệt — không gửi kế toán (BUSINESS_LOCK).' };
    this.deNghi.update((l) => l.map((x) => (x.id === id ? { ...x, trangThai: 'da-gui-ke-toan' as const } : x)));
    this.log({ nguoi: this.currentUser, hanhDong: `Gửi kế toán đề nghị ${id}`, refs: [id] });
    return { ok: true };
  }

  thuHoiDeNghi(id: string, lyDo: string): InsM04Guard {
    const dn = this.deNghi().find((x) => x.id === id);
    if (!dn) return { ok: false, reason: 'Không tìm thấy đề nghị.' };
    if (!lyDo.trim()) return { ok: false, reason: 'Thu hồi bắt buộc có lý do.' };
    if (dn.trangThai === 'da-khop' || dn.trangThai === 'da-thu-hoi') {
      return { ok: false, reason: `Đề nghị đã ${M04_DENGHI_LABEL[dn.trangThai].toLowerCase()} — không thu hồi.` };
    }
    this.deNghi.update((l) => l.map((x) => (x.id === id ? { ...x, trangThai: 'da-thu-hoi' as const, lyDoThuHoi: lyDo.trim() } : x)));
    this.log({ nguoi: this.currentUser, hanhDong: `Thu hồi đề nghị ${id} (bản cũ tra được)`, refs: [id], lyDo: lyDo.trim() });
    return { ok: true };
  }
}
