import { ChangeDetectionStrategy, Component, TemplateRef, computed, inject, input, signal, viewChild } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { HrmAlert, HrmButton, HrmDetailPeek, HrmGrid, HrmGridColumn, HrmMessageService, HrmPeekMode, HrmSelect, HrmStatusCell, HrmTag } from 'hrm-ui';
import { InsSectionLabel } from '../_shared';
import {
  InsM08RuleTyLe, InsM08Store, M08_DUYET_LABEL, M08_DUYET_TONE, M08_MUC_LABEL, m08KhoangLabel,
} from '../_data/_m08-data';

/** M08 ① — RULE TỶ LỆ / TRẦN–SÀN (trục nghiệp vụ — mọi con số màn khác lần ngược về đây).
 *  LOCK m08.md: mỗi bản ghi hiện ĐỦ số phiên bản + nguồn pháp lý (số hiệu + ngày + link) + khoảng
 *  hiệu lực + trạng thái duyệt + loại quy tắc. Bắt buộc theo LUẬT = khóa mức Chặn, KHÔNG mở ô chọn.
 *  Thiếu 1/3 thuộc tính → KHÔNG gửi duyệt (guard-pair). Chồng khoảng cùng loại+phạm vi → chặn +
 *  CHỈ BẢN XUNG ĐỘT. Sửa đang hiệu lực = PHIÊN BẢN MỚI. Hệ số trần ×20 = THAM SỐ (HS-TRAN),
 *  không cố định trong mã. Maker-checker: gửi duyệt → maker mất quyền sửa; duyệt chọn người ≠ maker. */
@Component({
  selector: 'ins-m08-rule-page',
  imports: [FormsModule, HrmAlert, HrmButton, HrmDetailPeek, HrmGrid, HrmSelect, HrmStatusCell, HrmTag, InsSectionLabel],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="r-head">
      <ins-section-label text="Rule versioned — bảng đủ 3 thuộc tính bắt buộc" tone="muted" [count]="rows().length" />
      <span class="r-muted">Hệ số trần = <b>N × {{ heSo()?.giaTri }}</b> — {{ heSo()?.ghiChu }} (tham số <span class="r-mono">HS-TRAN</span> {{ heSo()?.phienBan }}).</span>
    </div>

    <hrm-grid [columns]="cols()" [data]="rows()" rowKey="id" density="compact" minWidth="1240px"
      [pageSize]="10" (rowClick)="onRow($event)" />

    <ng-template #tenTpl let-row>
      <div class="r-stack">
        <span class="r-strong">{{ $any(row).ten }}</span>
        <span class="r-muted">{{ $any(row).id }} · {{ $any(row).loaiCanCu }} · tháng áp dụng {{ $any(row).thangApDung }} · phạm vi {{ $any(row).phamViLabel }}</span>
      </div>
    </ng-template>
    <ng-template #loaiTpl let-row>
      @if ($any(row).luat) {
        <div class="r-stack">
          <hrm-tag size="sm" color="red" variant="stroke">Bắt buộc theo luật</hrm-tag>
          <span class="r-muted">mức KHÓA "Chặn" — không mở ô chọn</span>
        </div>
      } @else { <hrm-tag size="sm" color="blue" variant="stroke">Chính sách nội bộ</hrm-tag> }
    </ng-template>
    <ng-template #nguonTpl let-row>
      @if ($any(row).nguonOk) {
        <div class="r-stack">
          <span class="r-strong">{{ $any(row).soHieu }}</span>
          <span class="r-muted">ban hành {{ $any(row).ngayBanHanh }} · <span class="r-link">{{ $any(row).link }}</span></span>
        </div>
      } @else { <span class="r-err">Thiếu nguồn pháp lý ({{ $any(row).nguonThieu }})</span> }
    </ng-template>
    <ng-template #ttTpl let-row>
      <hrm-status-cell [status]="$any(row).tone" [label]="$any(row).trangThaiLabel" variant="badge" />
    </ng-template>
    <ng-template #actTpl let-row>
      <hrm-button size="sm" (click)="onRow($any(row)); $event.stopPropagation()">Mở</hrm-button>
    </ng-template>

    <hrm-detail-peek [(open)]="peekOpenModel" [modes]="peekModes" [expandable]="false"
      [title]="peekTitle()" [content]="panelTpl" [width]="520"
      switchLabel="Đổi cách hiển thị" closeLabel="Đóng" resizeLabel="Kéo đổi độ rộng" />

    <ng-template #panelTpl>
      @if (sel(); as r) {
        <div class="r-pk">
          <!-- 3 thuộc tính bắt buộc -->
          <ins-section-label text="3 thuộc tính bắt buộc (thiếu 1 → không gửi duyệt)" tone="attention" />
          <div class="r-kv"><span>Số phiên bản</span><b>{{ r.soPhienBan }}</b></div>
          <div class="r-kv"><span>Nguồn pháp lý</span>
            @if (r.nguonPhapLy?.soHieu && r.nguonPhapLy?.ngayBanHanh && r.nguonPhapLy?.link) {
              <b>{{ r.nguonPhapLy?.soHieu }} · {{ r.nguonPhapLy?.ngayBanHanh }} · {{ r.nguonPhapLy?.link }}</b>
            } @else { <b class="r-err">Chưa đủ (số hiệu + ngày ban hành + link)</b> }
          </div>
          <div class="r-kv"><span>Khoảng hiệu lực</span><b>{{ khoang(r) }}</b></div>
          <div class="r-kv"><span>Trạng thái duyệt</span><b>{{ duyetLabel(r) }}</b>
            @if (r.nguoiDuyet) { <span class="r-muted">duyệt bởi {{ r.nguoiDuyet }} (≠ maker {{ r.nguoiLap }})</span> }
          </div>
          @if (r.dotMa) { <div class="r-kv"><span>Đợt phát hành</span><b>{{ r.dotMa }}</b></div> }

          <!-- 6 tỷ lệ quỹ + cấu phần BHXH NSDLĐ tự tính -->
          <ins-section-label text="6 tỷ lệ quỹ (BHXH/BHYT/BHTN × NSDLĐ/NLĐ)" tone="muted" />
          <table class="r-tyle">
            <thead><tr><th>Quỹ</th><th>NSDLĐ</th><th>NLĐ</th></tr></thead>
            <tbody>
              @for (t of r.tyLe; track t.quy) { <tr><td>{{ t.quy }}</td><td>{{ t.nsdld }}</td><td>{{ t.nld }}</td></tr> }
            </tbody>
          </table>
          <p class="r-muted">BHXH NSDLĐ <b>{{ r.bhxhNsdldTuTinh }}</b> TỰ TÍNH = {{ cauPhan(r) }} (nhập đè được — cờ lưu vết).</p>
          @if (r.mucTran) {
            <p class="r-muted">Trần: <b>{{ r.mucTran }}</b> = N × hệ số <b>{{ heSo()?.giaTri }}</b> (THAM SỐ <span class="r-mono">{{ r.heSoThamSo }}</span> — không cố định trong mã).</p>
          }
          @if (r.ghiChu) { <p class="r-note">{{ r.ghiChu }}</p> }

          <!-- Chồng khoảng: chỉ bản xung đột -->
          @if (luuReason(r); as reason) { <hrm-alert type="error" [message]="'Chồng khoảng hiệu lực'" [description]="reason" /> }

          <!-- Hành động guard-pair -->
          <ins-section-label text="Hành động (maker-checker)" tone="muted" />
          <div class="r-acts">
            @if (suaReason(r.id); as reason) {
              <hrm-button size="sm" [disabled]="true">Sửa</hrm-button>
              <span class="r-err">{{ reason }}</span>
            } @else { <hrm-button size="sm" (click)="suaDemo()">Sửa (bản nháp)</hrm-button> }
          </div>
          <div class="r-acts">
            @if (guiDuyetReason(r.id); as reason) {
              <hrm-button size="sm" variant="primary" [disabled]="true">Gửi duyệt</hrm-button>
              <span class="r-err">{{ reason }}</span>
            } @else if (r.trangThai === 'nhap' || r.trangThai === 'tra-lai') {
              <hrm-button size="sm" variant="primary" (click)="guiDuyet(r.id)">Gửi duyệt (mất quyền sửa)</hrm-button>
            }
          </div>
          @if (r.trangThai === 'cho-duyet') {
            <div class="r-acts">
              <hrm-select class="r-sel" [(ngModel)]="checkerModel" [options]="checkerOptions" size="sm"
                [allowClear]="false" [showSearch]="false" placeholder="Chọn người duyệt (pháp chế/BA)" />
              <hrm-button size="sm" variant="primary" (click)="duyet(r.id)">Duyệt</hrm-button>
              <hrm-button size="sm" (click)="traLai(r.id)">Trả lại (kèm lý do)</hrm-button>
            </div>
          }
          @if (r.trangThai === 'hieu-luc') {
            <div class="r-acts">
              <hrm-button size="sm" variant="primary" (click)="taoPhienBan(r.id)">Tạo phiên bản mới từ bản hiệu lực</hrm-button>
              <span class="r-muted">Bị kỳ tham chiếu → không xóa cứng, chỉ hết hiệu lực.</span>
            </div>
          }
        </div>
      }
    </ng-template>
  `,
  host: { class: 'ins-m08-rule-page' },
  styles: [`
    :host { display: flex; flex-direction: column; gap: 10px; }
    .r-head { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
    .r-muted { font-size: var(--fs-12); color: var(--text-sub); }
    .r-muted b, .r-kv b { color: var(--text-strong); }
    .r-note { margin: 0; font-size: var(--fs-12); color: var(--warning-text); }
    .r-err { font-size: var(--fs-12); color: var(--error-text); font-weight: 500; }
    .r-strong { color: var(--text-strong); font-weight: 500; }
    .r-mono { font-family: var(--font-mono, monospace); font-weight: 600; }
    .r-link { text-decoration: underline; }
    .r-stack { display: flex; flex-direction: column; gap: 2px; align-items: flex-start; }
    .r-pk { display: flex; flex-direction: column; gap: 9px; font-size: var(--fs-13); }
    .r-kv { display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; font-size: var(--fs-12); }
    .r-kv span:first-child { color: var(--text-sub); min-width: 120px; }
    .r-tyle { border-collapse: collapse; font-size: var(--fs-12); }
    .r-tyle th, .r-tyle td { border: 1px solid var(--border-sub); padding: 3px 12px; text-align: left; }
    .r-tyle th { background: var(--bg-surface-subtle); color: var(--text-sub); font-weight: 600; }
    .r-acts { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
    .r-sel { width: 260px; }
  `],
})
export class InsM08RulePage {
  protected readonly store = inject(InsM08Store);
  private readonly msg = inject(HrmMessageService);

  /** Phạm vi từ thanh ngữ cảnh shell — đơn vị kế thừa pháp nhân. */
  readonly phamVi = input<'phap-nhan' | 'dv1' | 'dv2'>('phap-nhan');

  protected readonly heSo = computed(() => this.store.thamSoOf('HS-TRAN'));

  private readonly PHAMVI_LABEL: Record<string, string> = { 'phap-nhan': 'Pháp nhân', dv1: 'Trụ sở HN (dv1)', dv2: 'CN Đà Nẵng (dv2)' };

  private readonly list = computed(() => {
    const pv = this.phamVi();
    return this.store.rules().filter((r) => pv === 'phap-nhan' || r.phamVi === 'phap-nhan' || r.phamVi === pv);
  });

  protected readonly rows = computed(() => this.list().map((r) => ({
    id: r.id, ten: r.ten, loaiCanCu: r.loaiCanCu, thangApDung: r.thangApDung,
    phamViLabel: this.PHAMVI_LABEL[r.phamVi] ?? r.phamVi,
    luat: r.loaiQuyTac === 'luat',
    soPhienBan: r.soPhienBan,
    nguonOk: !!(r.nguonPhapLy?.soHieu && r.nguonPhapLy?.ngayBanHanh && r.nguonPhapLy?.link),
    nguonThieu: [!r.nguonPhapLy?.soHieu ? 'số hiệu' : '', !r.nguonPhapLy?.ngayBanHanh ? 'ngày ban hành' : '', !r.nguonPhapLy?.link ? 'link' : ''].filter(Boolean).join(' + '),
    soHieu: r.nguonPhapLy?.soHieu ?? '', ngayBanHanh: r.nguonPhapLy?.ngayBanHanh ?? '', link: r.nguonPhapLy?.link ?? '',
    khoang: m08KhoangLabel(r.khoangHL),
    muc: M08_MUC_LABEL[r.muc],
    trangThaiLabel: M08_DUYET_LABEL[r.trangThai], tone: M08_DUYET_TONE[r.trangThai],
  })));

  private readonly tenTpl = viewChild.required<TemplateRef<unknown>>('tenTpl');
  private readonly loaiTpl = viewChild.required<TemplateRef<unknown>>('loaiTpl');
  private readonly nguonTpl = viewChild.required<TemplateRef<unknown>>('nguonTpl');
  private readonly ttTpl = viewChild.required<TemplateRef<unknown>>('ttTpl');
  private readonly actTpl = viewChild.required<TemplateRef<unknown>>('actTpl');

  protected readonly cols = computed<HrmGridColumn[]>(() => [
    { key: 'ten', title: 'Quy tắc', width: '300px', cell: this.tenTpl() as HrmGridColumn['cell'] },
    { key: 'loai', title: 'Loại quy tắc', width: '170px', cell: this.loaiTpl() as HrmGridColumn['cell'] },
    { key: 'soPhienBan', title: 'Phiên bản', width: '90px' },
    { key: 'nguon', title: 'Nguồn pháp lý (số hiệu + ngày + link)', width: '260px', cell: this.nguonTpl() as HrmGridColumn['cell'] },
    { key: 'khoang', title: 'Khoảng hiệu lực', width: '160px' },
    { key: 'muc', title: 'Mức', width: '90px' },
    { key: 'trangThai', title: 'Trạng thái duyệt', width: '140px', cell: this.ttTpl() as HrmGridColumn['cell'] },
    { key: 'act', title: '', width: '80px', fixed: 'right', align: 'right', cell: this.actTpl() as HrmGridColumn['cell'] },
  ]);

  /* ── panel ── */
  protected readonly peekModes: HrmPeekMode[] = ['side'];
  private readonly peekOpen = signal(false);
  protected get peekOpenModel(): boolean { return this.peekOpen(); }
  protected set peekOpenModel(v: boolean) { this.peekOpen.set(v); }
  private readonly selId = signal<string | null>(null);
  protected readonly sel = computed(() => { const id = this.selId(); return id ? this.store.ruleOf(id) ?? null : null; });
  protected readonly peekTitle = computed(() => { const r = this.sel(); return r ? `${r.id} · ${r.soPhienBan}` : ''; });
  protected onRow(row: Record<string, unknown>): void { this.selId.set(String(row['id'])); this.peekOpen.set(true); }

  protected khoang(r: InsM08RuleTyLe): string { return m08KhoangLabel(r.khoangHL); }
  protected duyetLabel(r: InsM08RuleTyLe): string { return M08_DUYET_LABEL[r.trangThai]; }
  protected cauPhan(r: InsM08RuleTyLe): string { return r.cauPhan.map((c) => `${c.ten} ${c.phanTram}`).join(' + '); }
  protected luuReason(r: InsM08RuleTyLe): string | null {
    if (r.trangThai !== 'nhap') return null;
    return this.store.luuReason(r.nhomId, r.phamVi, r.khoangHL, r.id);
  }
  protected suaReason(id: string): string | null { return this.store.suaRuleReason(id); }
  protected guiDuyetReason(id: string): string | null {
    const r = this.store.ruleOf(id);
    if (!r || (r.trangThai !== 'nhap' && r.trangThai !== 'tra-lai')) return null;
    return this.store.guiDuyetReason(id);
  }

  protected readonly checkerOptions = this.store.nguoiDuyetOptions.map((o) => ({ value: o, label: o }));
  private readonly checker = signal(this.store.nguoiDuyetOptions[0]);
  protected get checkerModel(): unknown { return this.checker(); }
  protected set checkerModel(v: unknown) { this.checker.set(String(v ?? '')); }

  protected suaDemo(): void { this.msg.info('Mở form sửa bản nháp (demo) — lưu sẽ chạy guard chồng khoảng (chỉ bản xung đột).'); }
  protected guiDuyet(id: string): void {
    const r = this.store.guiDuyet(id);
    r.ok ? this.msg.success('Đã gửi duyệt — maker MẤT quyền sửa; pháp chế/BA duyệt.') : this.msg.error(r.reason ?? '');
  }
  protected duyet(id: string): void {
    const r = this.store.duyetRule(id, this.checker());
    r.ok ? this.msg.success(`Đã duyệt bởi ${this.checker()} — hiệu lực CHỈ sau Đã duyệt.`) : this.msg.error(r.reason ?? '');
  }
  protected traLai(id: string): void {
    const r = this.store.traLaiRule(id, 'Thiếu căn cứ cấu phần — bổ sung phụ lục');
    r.ok ? this.msg.success('Đã trả lại — maker được sửa tiếp.') : this.msg.error(r.reason ?? '');
  }
  protected taoPhienBan(id: string): void {
    const r = this.store.taoPhienBanMoi(id);
    r.ok ? this.msg.success(`Đã tạo PHIÊN BẢN MỚI ${r.idMoi} từ bản hiệu lực (bản gốc giữ nguyên).`) : this.msg.error(r.reason ?? '');
  }
}
