import { ChangeDetectionStrategy, Component, inject } from '@angular/core';
import { HrmAlert, HrmButton, HrmMessageService, HrmStatusCell, HrmTag } from 'hrm-ui';
import { InsSectionLabel } from '../_shared';
import { InsTone } from '../_data/_core';
import {
  InsM08LanDongBo, InsM08Store, M08_DONGBO_LABEL, M08_DONGBO_TONE, M08_LOIDB_LABEL, M08_LOIDB_TONE, M08_LYDO_LOI_LABEL,
} from '../_data/_m08-data';

/** M08 ⑦ — NHẬT KÝ ĐỒNG BỘ (FN-19): BẤT BIẾN 3 CON SỐ KHỚP — đọc = thành dòng + lỗi + loại
 *  (loại có lý do, không phải lỗi). Đẳng thức render trực tiếp trên từng lần chạy. Sự kiện lỗi
 *  3 lý do đọc được (thiếu ánh xạ → LINK tab mapping · thiếu dữ liệu · lỗi kết nối); chạy lại
 *  CHỈ sự kiện lỗi, idempotent; vẫn thiếu → `Vẫn lỗi` KHÔNG báo giả; nguồn Tạm dừng → khóa nút.
 *  Mục này gắn chỉ báo "chỉ đọc" trên cây (chuyên viên 02 xem chỉ đọc — demo quyền ghi hạn chế). */
@Component({
  selector: 'ins-m08-dongbo-page',
  imports: [HrmAlert, HrmButton, HrmStatusCell, HrmTag, InsSectionLabel],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <hrm-alert type="info" [showIcon]="true" message="Mục chỉ đọc theo quyền"
      description="Chuyên viên 02 xem CHỈ ĐỌC (FN-19) — demo: chạy lại chỉ-lỗi vẫn mở cho vai trò quản trị." />
    <ins-section-label text="Lần chạy đồng bộ — 3 con số khớp" tone="muted" [count]="store.lanDongBo().length" />

    @for (lan of store.lanDongBo(); track lan.id) {
      <div class="s-lan">
        <div class="s-lan__head">
          <span class="s-mono">{{ lan.id }}</span>
          <span class="s-muted">{{ lan.thoiDiem }} · nguồn: {{ lan.nguon }}</span>
          <hrm-status-cell [status]="tone(lan)" [label]="label(lan)" variant="badge" />
          @if (lan.nguonTamDung) { <hrm-tag size="sm" color="orange">Nguồn Tạm dừng — khóa nút chạy lại</hrm-tag> }
        </div>

        <!-- Đẳng thức 3-số: đọc = thành dòng + lỗi + loại -->
        <div class="s-eq" [attr.data-ok]="lan.soDoc === lan.soThanhDong + lan.soLoi + lan.soLoai">
          <span class="s-eq__n">đọc <b>{{ lan.soDoc }}</b></span>
          <span class="s-eq__op">=</span>
          <span class="s-eq__n"><b>{{ lan.soThanhDong }}</b> thành dòng</span>
          <span class="s-eq__op">+</span>
          <span class="s-eq__n"><b>{{ lan.soLoi }}</b> lỗi</span>
          <span class="s-eq__op">+</span>
          <span class="s-eq__n"><b>{{ lan.soLoai }}</b> loại</span>
          <span class="s-eq__check">{{ lan.soDoc === lan.soThanhDong + lan.soLoi + lan.soLoai ? '✓ khớp' : '✗ LỆCH' }}</span>
        </div>
        @if (lan.lyDoLoai) { <p class="s-muted">{{ lan.lyDoLoai }}</p> }

        <!-- Sự kiện lỗi + chạy lại chỉ-lỗi -->
        @for (e of store.loiCuaLan(lan.id); track e.id) {
          <div class="s-loi">
            <span class="s-mono">{{ e.id }}</span>
            <hrm-tag size="sm" [color]="e.lyDo === 'loi-ket-noi' ? 'purple' : e.lyDo === 'thieu-du-lieu' ? 'blue' : 'orange'">{{ lyDoLabel(e.lyDo) }}</hrm-tag>
            <span class="s-muted">{{ e.moTa }}</span>
            <hrm-status-cell [status]="loiTone(e.trangThai)" [label]="loiLabel(e.trangThai)" variant="badge" />
            @if (e.linkMapping) { <span class="s-link">→ mở mục "Loại thủ tục hồ sơ & ánh xạ" (tab mapping)</span> }
            @for (v of e.vetChayLai; track v) { <span class="s-vet">{{ v }}</span> }
          </div>
        }

        @if (chayLaiReason(lan.id); as reason) {
          <div class="s-acts">
            <hrm-button size="sm" [disabled]="true">Chạy lại (chỉ sự kiện lỗi)</hrm-button>
            <span class="s-err">{{ reason }}</span>
          </div>
        } @else {
          <div class="s-acts">
            <hrm-button size="sm" variant="primary" (click)="chayLai(lan.id)">Chạy lại — CHỈ sự kiện lỗi (idempotent)</hrm-button>
          </div>
        }
      </div>
    }
  `,
  host: { class: 'ins-m08-dongbo-page' },
  styles: [`
    :host { display: flex; flex-direction: column; gap: 10px; }
    .s-lan { border: 1px solid var(--border-sub); border-radius: var(--radius-lg); background: var(--bg-surface); padding: 10px 13px; display: flex; flex-direction: column; gap: 7px; }
    .s-lan__head { display: flex; align-items: center; gap: 9px; flex-wrap: wrap; }
    .s-mono { font-family: var(--font-mono, monospace); font-size: var(--fs-12); font-weight: 700; color: var(--text-strong); }
    .s-muted { margin: 0; font-size: var(--fs-12); color: var(--text-sub); }
    .s-eq { display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; font-size: var(--fs-13);
      border: 1px dashed var(--border-sub); border-radius: var(--radius-md); padding: 7px 12px; font-variant-numeric: tabular-nums; }
    .s-eq[data-ok='true'] { border-color: var(--success-base, var(--success-text)); background: var(--success-bg); }
    .s-eq[data-ok='false'] { border-color: var(--error-base); background: var(--error-bg); }
    .s-eq__n { color: var(--text-body); }
    .s-eq__n b { font-size: var(--fs-16); color: var(--text-strong); }
    .s-eq__op { color: var(--text-soft); font-weight: 700; }
    .s-eq__check { margin-left: 8px; font-weight: 700; color: var(--success-text); }
    .s-eq[data-ok='false'] .s-eq__check { color: var(--error-text); }
    .s-loi { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; border-left: 3px solid var(--border-sub); padding: 4px 10px; }
    .s-link { font-size: var(--fs-12); color: var(--primary-base); font-weight: 500; }
    .s-vet { font-size: var(--fs-11); color: var(--text-soft); width: 100%; }
    .s-acts { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
    .s-err { font-size: var(--fs-12); color: var(--error-text); }
  `],
})
export class InsM08DongBoPage {
  protected readonly store = inject(InsM08Store);
  private readonly msg = inject(HrmMessageService);

  protected label(l: InsM08LanDongBo): string { return M08_DONGBO_LABEL[l.trangThai]; }
  protected tone(l: InsM08LanDongBo): InsTone { return M08_DONGBO_TONE[l.trangThai]; }
  protected loiLabel(s: keyof typeof M08_LOIDB_LABEL): string { return M08_LOIDB_LABEL[s]; }
  protected loiTone(s: keyof typeof M08_LOIDB_TONE): InsTone { return M08_LOIDB_TONE[s]; }
  protected lyDoLabel(s: keyof typeof M08_LYDO_LOI_LABEL): string { return M08_LYDO_LOI_LABEL[s]; }
  protected chayLaiReason(lanId: string): string | null { return this.store.chayLaiDongBoReason(lanId); }

  protected chayLai(lanId: string): void {
    const r = this.store.chayLaiDongBo(lanId);
    r.ok
      ? this.msg.success(`Chạy lại CHỈ phần lỗi: ${r.daSua} sửa xong · ${r.vanLoi} VẪN LỖI (không báo giả).`)
      : this.msg.error(r.reason ?? '');
  }
}
