export interface InsSuggestLoaiTru { ma: string; giaiThichNgan: string; }
/** B2 — heuristic chọn lý do loại trừ phù hợp nhất theo context (advisory · 0 LLM). Trả null → HR tự
 *  chọn. Gọi TRONG event handler (mở popover), KHÔNG trong binding (tạo object mới mỗi lần — zoneless). */
export function insSuggestLoaiTru(c: InsChange): InsSuggestLoaiTru | null {
  if (c.dongXungDot || c.nhomNgoaiLe.includes('trung-du-lieu')) {
    return { ma: 'trung-lap', giaiThichNgan: `Đã có ${INS_CHANGE_KIND_LABEL[c.loaiBienDong]} cùng NLĐ, cùng ${insKy(c.kyTacDong)?.label ?? 'kỳ'} — nghi trùng.` };
  }
  if (c.coKhongAnhHuong) {
    return { ma: 'ko-anh-huong-muc-dong', giaiThichNgan: 'Thay đổi không làm thay đổi mức đóng BHXH.' };
  }
  if (c.nguon === INS_NGUON_CHONG_SOT) {
    return { ma: 'da-co-bien-dong', giaiThichNgan: 'Có thể đã có biến động tương ứng ở nguồn khác — đối chiếu trước khi bỏ khỏi kỳ.' };
  }
  return null;
}

