/** Parse chuỗi tiền định dạng sẵn ('+9.200.000' / '−13.500.000') → số. Hỗ trợ cả '−' (U+2212). */
export function insParseVnd(s?: string | null): number {
  if (!s) return 0;
  const neg = s.includes('−') || s.trim().startsWith('-');
  const n = Number(s.replace(/[^\d]/g, '') || '0');
  return neg ? -n : n;
}

/** Format số → chuỗi tiền chấm ngăn cách; `sign` = luôn kèm dấu (+/−). */
export function insFormatVnd(n: number, sign = false): string {
  const abs = Math.abs(n).toLocaleString('vi-VN');
  if (n < 0) return `−${abs}`;
  return sign && n > 0 ? `+${abs}` : abs;
}

function insDayNum(d: string): number {
  const [dd, mm, yy] = d.split('/').map(Number);
  return Date.UTC(yy, mm - 1, dd) / 86400000;
}

/** Nhãn + tone SLA của 1 dòng — format sẵn cho `ins-sla-chip` (tone theo INS_COHAN_CHIP_TONE):
 *  "còn N ngày" / "quá hạn N ngày" / "chưa xác định hạn". */
export interface InsSlaView { label: string; tone: 'ok' | 'warn' | 'danger' | 'muted'; }
export function insSlaView(c: Pick<InsChange, 'coHan' | 'ngayHanXuLy'>): InsSlaView {
  if (!c.coHan || !c.ngayHanXuLy) return { label: 'chưa xác định hạn', tone: 'muted' };
  const d = insDayNum(c.ngayHanXuLy) - insDayNum(M02_TODAY);
  const tone = INS_COHAN_CHIP_TONE[c.coHan];
  if (c.coHan === 'qua-han') return { label: d < 0 ? `quá hạn ${-d} ngày` : 'quá hạn', tone };
  if (d <= 0) return { label: 'đến hạn hôm nay', tone };
  return { label: `còn ${d} ngày`, tone };
}

/* ─────────────────────────── ĐỘ TIN CẬY (confidence) — DETERMINISTIC, không random ───────────────────────────
 *  Điểm tin cậy suy ra 1 LẦN từ tín hiệu SẴN CÓ của dòng (rule/ngoại lệ/xung đột/hạn/nguồn) — cùng input
 *  luôn ra cùng số (zoneless-safe, KHÔNG Math.random/Date.now). Dùng cho cột "Tin cậy" (lưới) + panel (đợt B).
 *  ≥90 Cao · 70–89 Trung bình · <70 Thấp. */
export type InsConfidenceLevel = 'cao' | 'trung-binh' | 'thap';

/** Tính điểm tin cậy (20–99) cho 1 dòng biến động — thuần, xác định. */
export function insConfidence(c: InsChange): number {
  const sach = c.ketQuaRule.length === 0 && c.nhomNgoaiLe.length === 0 && !c.dongXungDot;
  let n: number;
  if (c.trangThai === 'san-sang' && sach) {
    // Dòng sẵn sàng, sạch → tin cậy cao theo độ chắc của nguồn phát sinh.
    n = c.nguon === 'Hợp đồng lao động' || c.nguon === 'Quyết định nhân sự' ? 98
      : c.nguon === 'Chấm công' ? 92 : 96;
  } else {
    n = 100;
    if (c.ketQuaRule.some((r) => r.muc === 'chan')) n = 55;            // có rule chặn → tối đa 55
    n -= c.ketQuaRule.filter((r) => r.muc === 'canh-bao').length * 12; // mỗi cảnh báo −12
    n -= c.nhomNgoaiLe.length * 10;                                    // mỗi nhóm ngoại lệ −10
    if (c.coHan === 'qua-han') n -= 8;                                 // quá hạn −8
    if (c.ngayHieuLuc === '') n -= 15;                                 // thiếu ngày hiệu lực −15
    if (c.nguon === INS_NGUON_CHONG_SOT) n = 60;                       // suy luận chống sót → chưa chắc
    if (c.dongXungDot) n = 64;                                         // xung đột/trùng → cần đối chiếu
  }
  return Math.max(20, Math.min(99, n));
}

/** Mức tin cậy từ điểm số (≥90 cao · 70–89 trung bình · <70 thấp). */
export function insConfidenceLevel(n: number): InsConfidenceLevel {
  return n >= 90 ? 'cao' : n >= 70 ? 'trung-binh' : 'thap';
}

