import { ChangeDetectionStrategy, Component, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { HrmButton, HrmMessageService, HrmSelect, HrmStatusCell, HrmTag } from 'hrm-ui';
import { InsSectionLabel } from '../_shared';
import { InsM08Store, M08_HANHVI_LABEL, M08_LUUTRU_LABEL } from '../_data/_m08-data';

/** M08 ⑨ — LƯU TRỮ (FN-20): thời hạn theo LOẠI tài liệu; chưa xác nhận = GIỮ NGUYÊN; hủy LUÔN
 *  QUA DUYỆT (hủy/gia hạn/khóa chỉ đọc); tài liệu y tế phân loại riêng; đang tham chiếu → TỰ GIA
 *  HẠN + lý do; kết quả đợt chỉ-thêm, xuất được; NGƯỜI LẬP ≠ NGƯỜI DUYỆT; thi hành lỗi → dừng giữ
 *  nguyên; tra tài liệu đã hủy → "đã hủy theo chính sách, đợt nào, ai duyệt". */
@Component({
  selector: 'ins-m08-luutru-page',
  imports: [FormsModule, HrmButton, HrmSelect, HrmStatusCell, HrmTag, InsSectionLabel],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <ins-section-label text="Chính sách lưu trữ theo loại tài liệu" tone="muted" [count]="store.chinhSachLuuTru().length" />
    <div class="l-policies">
      @for (p of store.chinhSachLuuTru(); track p.id) {
        <div class="l-policy">
          <span class="l-mono">{{ p.id }}</span>
          <span class="l-strong">{{ p.loaiTaiLieu }}</span>
          @if (p.yTe) { <hrm-tag size="sm" color="pink">Y tế — phân loại riêng</hrm-tag> }
          <span class="l-muted">Thời hạn: <b>{{ p.thoiHan }}</b> · hết hạn → {{ hanhVi(p.hanhViHetHan) }}</span>
          <hrm-status-cell [status]="p.trangThai === 'hieu-luc' ? 'success' : p.trangThai === 'cho-duyet' ? 'processing' : 'neutral'"
            [label]="trangThai(p.trangThai)" variant="badge" />
          @if (p.nguoiDuyet) { <span class="l-muted">duyệt: {{ p.nguoiDuyet }}</span> }
        </div>
      }
    </div>

    @for (d of store.dotXuLy(); track d.id) {
      <div class="l-dot">
        <div class="l-dot__head">
          <ins-section-label text="Đợt xử lý hết hạn — duyệt từng dòng" tone="attention" [count]="d.dong.length" />
          <span class="l-mono">{{ d.id }}</span>
          <hrm-status-cell [status]="d.trangThai === 'da-duyet' ? 'success' : d.trangThai === 'tra-lai' ? 'error' : 'processing'"
            [label]="d.trangThai === 'da-duyet' ? 'Đã duyệt (thi hành)' : d.trangThai === 'tra-lai' ? 'Trả lại' : 'Chờ duyệt'" variant="badge" />
          <span class="l-muted">lập {{ d.at }} bởi {{ d.nguoiLap }}@if (d.nguoiDuyet) { · duyệt {{ d.nguoiDuyet }}}</span>
        </div>
        @for (row of d.dong; track row.taiLieu) {
          <div class="l-row" [class.l-row--gh]="row.dangThamChieu">
            <span class="l-strong">{{ row.taiLieu }}</span>
            <hrm-tag size="sm" [color]="row.quyetDinh === 'huy' ? 'red' : row.quyetDinh === 'khoa' ? 'gray' : 'teal'">
              {{ row.quyetDinh === 'huy' ? 'Hủy (qua duyệt)' : row.quyetDinh === 'khoa' ? 'Khóa chỉ đọc' : 'Gia hạn' }}</hrm-tag>
            @if (row.dangThamChieu) { <span class="l-warn">{{ row.dangThamChieu }} → TỰ GIA HẠN</span> }
            @if (row.lyDo) { <span class="l-muted">{{ row.lyDo }}</span> }
          </div>
        }
        @if (d.trangThai === 'cho-duyet') {
          <div class="l-acts">
            <hrm-select class="l-sel" [(ngModel)]="checkerModel" [options]="checkerOptions" size="sm" [allowClear]="false" [showSearch]="false" />
            <hrm-button size="sm" variant="primary" (click)="duyet(d.id)">Duyệt đợt (người lập ≠ người duyệt)</hrm-button>
          </div>
        }
        <p class="l-note">Hủy LUÔN qua duyệt — chưa xác nhận = GIỮ NGUYÊN · kết quả đợt chỉ-thêm, xuất được · thi hành lỗi
          → DỪNG, giữ nguyên tài liệu · tra tài liệu đã hủy → "đã hủy theo chính sách, đợt {{ d.id }}, ai duyệt".</p>
      </div>
    }
  `,
  host: { class: 'ins-m08-luutru-page' },
  styles: [`
    :host { display: flex; flex-direction: column; gap: 10px; }
    .l-policies { display: flex; flex-direction: column; gap: 5px; }
    .l-policy { display: flex; align-items: center; gap: 9px; flex-wrap: wrap; border: 1px solid var(--border-sub); border-radius: var(--radius-md); background: var(--bg-surface); padding: 6px 10px; }
    .l-mono { font-family: var(--font-mono, monospace); font-size: var(--fs-12); font-weight: 700; color: var(--text-strong); }
    .l-strong { color: var(--text-strong); font-weight: 500; font-size: var(--fs-13); }
    .l-muted { font-size: var(--fs-12); color: var(--text-sub); }
    .l-muted b { color: var(--text-strong); }
    .l-warn { font-size: var(--fs-12); color: var(--warning-text); font-weight: 600; }
    .l-dot { border: 1px solid var(--border-sub); border-radius: var(--radius-lg); background: var(--bg-surface); padding: 10px 13px; display: flex; flex-direction: column; gap: 7px; }
    .l-dot__head { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
    .l-row { display: flex; align-items: center; gap: 9px; flex-wrap: wrap; border-left: 3px solid var(--border-sub); padding: 4px 10px; }
    .l-row--gh { border-left-color: var(--warning-base, var(--warning-text)); background: var(--warning-bg); border-radius: var(--radius-sm); }
    .l-acts { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
    .l-sel { width: 230px; }
    .l-note { margin: 0; font-size: var(--fs-11); color: var(--text-soft); }
  `],
})
export class InsM08LuuTruPage {
  protected readonly store = inject(InsM08Store);
  private readonly msg = inject(HrmMessageService);

  protected hanhVi(k: keyof typeof M08_HANHVI_LABEL): string { return M08_HANHVI_LABEL[k]; }
  protected trangThai(k: keyof typeof M08_LUUTRU_LABEL): string { return M08_LUUTRU_LABEL[k]; }

  protected readonly checkerOptions = this.store.nguoiDuyetOptions.map((o) => ({ value: o, label: o }));
  private readonly checker = signal(this.store.nguoiDuyetOptions[0]);
  protected get checkerModel(): unknown { return this.checker(); }
  protected set checkerModel(v: unknown) { this.checker.set(String(v ?? '')); }

  protected duyet(id: string): void {
    const r = this.store.duyetDotHuy(id, this.checker());
    r.ok ? this.msg.success(`Đợt ${id} được duyệt (thi hành) bởi ${this.checker()} — dòng đang-tham-chiếu TỰ GIA HẠN.`)
      : this.msg.error(r.reason ?? '');
  }
}
