import { ChangeDetectionStrategy, Component, computed, inject, input } from '@angular/core';
import { IconCheck, IconSparkles, TablerIconComponent } from '@tabler/icons-angular';
import { HrmAlert, HrmMessageService, HrmStatusCell, HrmTag } from 'hrm-ui';
import { InsDiff, InsSectionLabel } from '../../../_shared';
import type { InsTone } from '../../../_data/_core';
import { M06_TONE_VAR, type M06Profile360, type M06Tab360 } from '../_m06-360-data';

/** M06 · HỒ SƠ 360° — GỘP 5 TAB NGỮ CẢNH (§11,28-32) trong 1 component @switch.
 *  Nguyên tắc: CHỈ hiển thị dữ liệu CÓ THỂ ẢNH HƯỞNG BHXH — không copy toàn module HR.
 *  Mỗi tab mở đầu bằng banner "Dữ liệu ngữ cảnh" rồi tới card nội dung.
 *
 *  ZONELESS (Angular 21): standalone + OnPush; mọi binding tham chiếu ổn định (input/computed);
 *  ngày & tiền = chuỗi định dạng sẵn từ data; @for luôn có track. KHÔNG Math.random()/Date.now().
 *  Mọi method dùng trong template là THUẦN (deterministic). */
@Component({
  selector: 'ins-m06-360-context',
  imports: [TablerIconComponent, HrmAlert, HrmStatusCell, HrmTag, InsDiff, InsSectionLabel],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <hrm-alert type="info" [banner]="true"
      message="Dữ liệu ngữ cảnh — chỉ các trường ảnh hưởng đến bảo hiểm." />

    @switch (which()) {
      <!-- ═════════ §28 HỒ SƠ NHÂN VIÊN ═════════ -->
      @case ('hoso-nv') {
        <div class="ctx-card">
          <div class="ctx-card__title">Hồ sơ nhân viên</div>
          <div class="dg">
            <div class="dg-item"><span class="dg-lb">Họ tên</span><span class="dg-val">{{ profile().identity.name }}</span></div>
            <div class="dg-item"><span class="dg-lb">Ngày sinh</span><span class="dg-val">{{ profile().employeeInfo.dob }}</span></div>
            <div class="dg-item"><span class="dg-lb">Giới tính</span><span class="dg-val">{{ profile().employeeInfo.gender }}</span></div>
            <div class="dg-item"><span class="dg-lb">CCCD</span><span class="dg-val dg-val--mono">{{ profile().employeeInfo.cccd }}</span></div>
            <div class="dg-item"><span class="dg-lb">Quốc tịch</span><span class="dg-val">{{ profile().employeeInfo.nationality }}</span></div>
            <div class="dg-item"><span class="dg-lb">Địa chỉ</span><span class="dg-val">{{ profile().employeeInfo.address }}</span></div>
            <div class="dg-item"><span class="dg-lb">Điện thoại</span><span class="dg-val">{{ profile().employeeInfo.phone }}</span></div>
            <div class="dg-item"><span class="dg-lb">Email</span><span class="dg-val">{{ profile().employeeInfo.email }}</span></div>
            <div class="dg-item"><span class="dg-lb">Trạng thái</span><span class="dg-val">{{ profile().employeeInfo.employmentLabel }}</span></div>
          </div>
          @if (profile().employeeInfo.recentChange; as rc) {
            <div class="ctx-flag ctx-flag--warn">
              <tabler-icon [icon]="icSparkles" [size]="14" />
              <span>{{ rc }} — có thể ảnh hưởng hồ sơ BHXH</span>
            </div>
          }
        </div>
      }

      <!-- ═════════ §29 HỢP ĐỒNG LAO ĐỘNG ═════════ -->
      @case ('hdld') {
        <div class="ctx-card">
          <div class="ctx-card__title">
            Hợp đồng lao động
            @if (profile().contract.isCurrent) { <hrm-tag size="sm" color="green">HĐLĐ hiện hành</hrm-tag> }
          </div>
          <div class="dg">
            <div class="dg-item"><span class="dg-lb">Loại HĐLĐ</span><span class="dg-val">{{ profile().contract.type }}</span></div>
            <div class="dg-item"><span class="dg-lb">Số hợp đồng</span><span class="dg-val dg-val--mono">{{ profile().contract.code }}</span></div>
            <div class="dg-item"><span class="dg-lb">Ngày ký</span><span class="dg-val">{{ profile().contract.signDate }}</span></div>
            <div class="dg-item"><span class="dg-lb">Hiệu lực từ</span><span class="dg-val">{{ profile().contract.from }}</span></div>
            <div class="dg-item"><span class="dg-lb">Hiệu lực đến</span><span class="dg-val">{{ profile().contract.to }}</span></div>
            <div class="dg-item"><span class="dg-lb">Trạng thái</span><span class="dg-val">
              <hrm-status-cell [status]="contractStatus()" [label]="profile().contract.statusLabel" variant="badge" />
            </span></div>
            <div class="dg-item"><span class="dg-lb">Chức danh</span><span class="dg-val">{{ profile().contract.jobTitle }}</span></div>
            <div class="dg-item"><span class="dg-lb">Mức lương căn cứ</span><span class="dg-val">{{ dvnd(profile().contract.salaryBasis) }}</span></div>
          </div>
          @if (profile().contract.insuranceImpact; as imp) {
            <p class="ctx-note"><b>Ảnh hưởng BHXH:</b> {{ imp }}</p>
          }
        </div>
      }

      <!-- ═════════ §30 LƯƠNG & PHỤ CẤP ═════════ -->
      @case ('luong') {
        <div class="ctx-card">
          <div class="ctx-card__title">Lương &amp; phụ cấp</div>

          <ins-section-label text="Cấu phần lương" tone="muted" [count]="profile().compensation.components.length" />
          <div class="cmp-list">
            @for (c of profile().compensation.components; track c.name) {
              <div class="cmp-row">
                <span class="cmp-name">{{ c.name }}</span>
                <span class="cmp-amt">{{ c.amount }} đ</span>
                <span class="cmp-chip" [class.cmp-chip--off]="!c.included">{{ c.included ? 'Tính đóng' : 'Không tính đóng' }}</span>
                <span class="cmp-src">Nguồn: {{ c.source }}</span>
              </div>
            }
            @if (!profile().compensation.components.length) {
              <p class="ctx-muted">Chưa có cấu phần lương ghi nhận.</p>
            }
          </div>

          <div class="cmp-base">
            <span class="cmp-base__lb">Mức căn cứ đóng:</span>
            <span class="cmp-base__val">{{ dvnd(profile().compensation.insuranceBase) }}</span>
          </div>
          @if (profile().compensation.prevBase; as pb) {
            <ins-diff [before]="pb + ' đ'" [after]="profile().compensation.insuranceBase + ' đ'" label="Thay đổi mức đóng" />
          }

          <ins-section-label text="Đối chiếu nguồn" tone="muted" />
          @if (profile().compensation.sourceConsistent) {
            <div class="rec-ok">
              <span class="rec-ok__item"><tabler-icon [icon]="icCheck" [size]="14" /> Compensation</span>
              <span class="rec-ok__item"><tabler-icon [icon]="icCheck" [size]="14" /> HĐLĐ</span>
              <span class="rec-ok__item"><tabler-icon [icon]="icCheck" [size]="14" /> Payroll</span>
            </div>
          } @else {
            <hrm-alert type="warning" message="Cần kiểm tra"
              [description]="profile().compensation.conflictNote || 'Nguồn dữ liệu đang lệch — cần đối chiếu Compensation / HĐLĐ / Payroll.'" />
          }
        </div>
      }

      <!-- ═════════ §31 CHẤM CÔNG – NGHỈ PHÉP ═════════ -->
      @case ('chamcong') {
        <div class="ctx-card">
          <div class="ctx-card__title">Chấm công – nghỉ phép</div>
          @if (profile().absences.length) {
            <div class="tbl-scroll">
              <div class="tbl tbl--cc">
                <div class="tbl-head">
                  <span>Khoảng thời gian</span><span>Loại nghỉ</span><span>Số ngày</span><span>Ảnh hưởng BHXH</span><span>Trạng thái</span>
                </div>
                @for (a of profile().absences; track a.period) {
                  <div class="tbl-row">
                    <span class="tbl-strong">{{ a.period }}</span>
                    <span>{{ a.type }}</span>
                    <span>{{ a.days }}</span>
                    <span class="tbl-impact">
                      <span class="dot" [style.background]="'var(' + toneVar(a.impactTone) + ')'"></span>
                      <span [style.color]="'var(' + toneVar(a.impactTone) + ')'">{{ a.impact }}</span>
                    </span>
                    <span>{{ a.status }}</span>
                  </div>
                }
              </div>
            </div>
          } @else {
            <p class="ctx-muted">Không có kỳ nghỉ ảnh hưởng bảo hiểm.</p>
          }
        </div>
      }

      <!-- ═════════ §32 QUYẾT ĐỊNH NHÂN SỰ ═════════ -->
      @case ('quyetdinh') {
        <div class="ctx-card">
          <div class="ctx-card__title">Quyết định nhân sự</div>
          @if (profile().decisions.length) {
            <div class="tbl-scroll">
              <div class="tbl tbl--qd">
                <div class="tbl-head">
                  <span>Quyết định</span><span>Hiệu lực</span><span>Thay đổi</span><span>Ảnh hưởng BHXH</span><span>Trạng thái</span>
                </div>
                @for (d of profile().decisions; track d.name) {
                  <div class="tbl-row tbl-row--click" (click)="openDecision()">
                    <span class="tbl-strong">{{ d.name }}</span>
                    <span>{{ d.effective }}</span>
                    <span>{{ d.change }}</span>
                    <span>{{ d.impact }}</span>
                    <span class="qd-status">
                      <span class="qd-status__lb">{{ d.status }}</span>
                      @if (d.detected) {
                        <hrm-tag size="sm" color="green">✓ Đã phát hiện</hrm-tag>
                      } @else {
                        <hrm-tag size="sm" color="orange">⚠ Có khả năng cần xử lý</hrm-tag>
                      }
                    </span>
                  </div>
                }
              </div>
            </div>
          } @else {
            <p class="ctx-muted">Chưa có quyết định nhân sự ảnh hưởng bảo hiểm.</p>
          }
        </div>
      }
    }
  `,
  host: { class: 'ins-m06-360-context' },
  styles: [`
    :host { display: flex; flex-direction: column; gap: 12px; max-width: 960px; }

    /* ── Card ── */
    .ctx-card {
      display: flex; flex-direction: column; gap: 12px;
      background: var(--bg-surface); border: 1px solid var(--border-sub);
      border-radius: 12px; padding: 16px;
    }
    .ctx-card__title {
      display: inline-flex; align-items: center; gap: 8px; flex-wrap: wrap;
      font-size: var(--fs-14); font-weight: 600; color: var(--text-strong);
    }

    /* ── Description grid 2 cột ── */
    .dg { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px 28px; }
    .dg-item { display: grid; grid-template-columns: 118px 1fr; gap: 10px; align-items: baseline; font-size: var(--fs-13); }
    .dg-lb { color: var(--text-sub); }
    .dg-val { color: var(--text-strong); font-weight: 500; min-width: 0; overflow-wrap: anywhere; }
    .dg-val--mono { font-family: var(--font-mono, monospace); }

    /* ── Flag / note / empty ── */
    .ctx-flag {
      align-self: flex-start; display: inline-flex; align-items: center; gap: 6px;
      font-size: var(--fs-12); font-weight: 500; padding: 6px 10px; border-radius: var(--radius-md);
    }
    .ctx-flag--warn { background: var(--warning-bg); color: var(--warning-text); }
    .ctx-note { margin: 0; font-size: var(--fs-12); color: var(--text-sub); }
    .ctx-note b { color: var(--text-strong); }
    .ctx-muted { margin: 0; font-size: var(--fs-13); color: var(--text-sub); }

    /* ── Lương: cấu phần + căn cứ + đối chiếu ── */
    .cmp-list { display: flex; flex-direction: column; gap: 6px; }
    .cmp-row {
      display: flex; align-items: center; gap: 10px; flex-wrap: wrap; font-size: var(--fs-13);
      padding: 7px 11px; border: 1px solid var(--border-sub); border-radius: var(--radius-md);
    }
    .cmp-name { color: var(--text-strong); font-weight: 500; min-width: 150px; }
    .cmp-amt { color: var(--text-strong); font-weight: 700; font-variant-numeric: tabular-nums; }
    .cmp-chip {
      font-size: var(--fs-11); font-weight: 500; line-height: 1.5;
      padding: 1px 9px; border-radius: var(--radius-full);
      background: var(--success-bg); color: var(--success-text);
    }
    .cmp-chip--off { background: var(--bg-surface-subtle); color: var(--text-sub); }
    .cmp-src { margin-left: auto; font-size: var(--fs-12); color: var(--text-sub); }
    .cmp-base { display: flex; align-items: baseline; gap: 8px; padding-top: 2px; }
    .cmp-base__lb { font-size: var(--fs-13); font-weight: 600; color: var(--text-strong); }
    .cmp-base__val { font-size: var(--fs-15, 15px); font-weight: 700; color: var(--text-strong); font-variant-numeric: tabular-nums; }
    .rec-ok { display: flex; gap: 18px; flex-wrap: wrap; }
    .rec-ok__item { display: inline-flex; align-items: center; gap: 5px; font-size: var(--fs-13); font-weight: 500; color: var(--success-text); }

    /* ── Bảng custom (grid header + rows) ── */
    .tbl-scroll { overflow-x: auto; }
    .tbl { display: flex; flex-direction: column; min-width: 700px; }
    .tbl-head, .tbl-row { display: grid; align-items: center; gap: 12px; padding: 8px 10px; }
    .tbl-head {
      font-size: var(--fs-12); font-weight: 600; color: var(--text-sub);
      border-bottom: 1px solid var(--border-sub);
    }
    .tbl-row {
      font-size: var(--fs-13); color: var(--text-strong);
      border-bottom: 1px solid var(--border-soft, var(--border-sub));
    }
    .tbl-row:last-child { border-bottom: 0; }
    .tbl-strong { color: var(--text-strong); font-weight: 500; }
    .tbl--cc .tbl-head, .tbl--cc .tbl-row { grid-template-columns: 1.4fr 1.1fr .7fr 1.5fr 1fr; }
    .tbl--qd .tbl-head, .tbl--qd .tbl-row { grid-template-columns: 1.6fr .9fr 1.4fr 1.3fr 1.4fr; }
    .tbl-impact { display: inline-flex; align-items: center; gap: 6px; min-width: 0; }
    .tbl-impact .dot { flex: none; width: 8px; height: 8px; border-radius: 50%; }
    .tbl-row--click { cursor: pointer; }
    .tbl-row--click:hover { background: var(--bg-surface-subtle); }
    .qd-status { display: inline-flex; flex-direction: column; align-items: flex-start; gap: 3px; }
    .qd-status__lb { font-size: var(--fs-12); color: var(--text-sub); }

    @media (max-width: 640px) { .dg { grid-template-columns: 1fr; } }
  `],
})
export class InsM06Tab360Context {
  private readonly msg = inject(HrmMessageService);

  readonly profile = input.required<M06Profile360>();
  readonly which = input.required<M06Tab360>();

  protected readonly icSparkles = IconSparkles;
  protected readonly icCheck = IconCheck;

  /** §29 status-cell tone: 'Đã chấm dứt' = neutral, còn lại (Đang hiệu lực) = success. */
  protected readonly contractStatus = computed<'success' | 'neutral'>(() =>
    this.profile().contract.statusLabel === 'Đã chấm dứt' ? 'neutral' : 'success');

  /** InsTone → cvar cho status dot / màu chữ ảnh hưởng (thuần). */
  protected toneVar(t: InsTone): string { return M06_TONE_VAR[t]; }

  /** Ghép ' đ' vào chuỗi tiền đã format; giữ nguyên '—'/rỗng (thuần). */
  protected dvnd(v: string): string { return !v || v === '—' ? (v || '—') : v + ' đ'; }

  /** Deep-link (prototype): click dòng quyết định → thông báo demo, không nav chéo module. */
  protected openDecision(): void { this.msg.info('Mở chi tiết quyết định nhân sự (demo)'); }
}
