import { ChangeDetectionStrategy, Component, computed, inject, input } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { HrmAlert, HrmDescItem, HrmDescriptions, HrmInput, HrmTag } from 'hrm-ui';
import { InsSectionLabel } from '../../_shared';
import { insDonVi, insNhanVien } from '../../_data/_core';
import { INS_CASE_NGUON_LABEL, INS_CASE_NHOM_LABEL, InsM05Store } from '../../_data/_m05-data';

/** M05-B · B1 Tiếp nhận — form HIỂN THỊ (descriptions + vài field sửa được khi trạng thái cho phép:
 *  Tiếp nhận/Chờ chứng từ) + nguồn case + khối con/quá trình thai sản khi loại = thai sản +
 *  validate logic thai sản hiển thị dạng alert (BĐ≥sinh · BĐ−sinh+1≤30 · đi làm lại≤BĐ ·
 *  trước sinh ≤60 ngày · 6/12 tháng đóng trước sinh — m05.md LOCK eligibility). */
@Component({
  selector: 'ins-m05-b1',
  imports: [FormsModule, HrmAlert, HrmDescriptions, HrmInput, HrmTag, InsSectionLabel],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (c(); as c) {
      <div class="b1">
        <section class="b1__sec">
          <div class="b1__sechead">
            <ins-section-label text="Thông tin tiếp nhận" tone="muted" />
            <hrm-tag color="blue" size="sm">Nguồn: {{ nguonLabel() }}</hrm-tag>
            @if (c.tuNgayDuyetTruoc) { <hrm-tag color="purple" size="sm">Giữ dữ liệu duyệt trước: {{ c.tuNgayDuyetTruoc }}</hrm-tag> }
          </div>
          <hrm-descriptions [items]="descItems()" [column]="3" size="small" />
        </section>

        <section class="b1__sec">
          <ins-section-label text="Khoảng nghỉ đề nghị" tone="muted" />
          @if (editable()) {
            <div class="b1__editrow">
              <label class="b1__lb">Từ ngày</label>
              <hrm-input class="b1__in" [(ngModel)]="tuNgayModel" size="sm" />
              <label class="b1__lb">Đến ngày</label>
              <hrm-input class="b1__in" [(ngModel)]="denNgayModel" size="sm" />
              <label class="b1__lb">Đi làm lại</label>
              <hrm-input class="b1__in" [(ngModel)]="diLamLaiModel" size="sm" />
            </div>
          } @else {
            <!-- Đóng băng = render text (hrm-control không có input disabled — lưu ý D2) -->
            <div class="b1__editrow">
              <span class="b1__frozen">Từ ngày <b>{{ c.tuNgay }}</b></span>
              <span class="b1__frozen">Đến ngày <b>{{ c.denNgay }}</b></span>
              <span class="b1__frozen">Đi làm lại <b>{{ c.ngayDiLamLai || '—' }}</b></span>
              <span class="b1__muted">Chỉ sửa được khi case ở Tiếp nhận / Chờ chứng từ — sau đó sửa qua chu trình Cần bổ sung.</span>
            </div>
          }
        </section>

        @if (c.khoiThaiSan; as ts) {
          <section class="b1__sec">
            <ins-section-label text="Quá trình thai sản" tone="muted" />
            <hrm-descriptions [items]="thaiSanItems()" [column]="3" size="small" />
            <p class="b1__muted">Kiểm tra logic thai sản (rule M08, hiển thị — không chặn nhập): BĐ ≥ ngày sinh · BĐ − sinh + 1 ≤ 30 ·
              đi làm lại ≤ BĐ chu kỳ sau · nghỉ trước sinh ≤ 60 ngày · đóng đủ 6/12 tháng trước sinh.</p>
          </section>
        }
        @if (c.khoiCon; as con) {
          <section class="b1__sec">
            <ins-section-label text="Khối con (con ốm)" tone="muted" />
            <hrm-descriptions [items]="conItems()" [column]="3" size="small" />
          </section>
        }
        @if (c.canCuGoc) {
          <section class="b1__sec">
            <ins-section-label text="Căn cứ chế độ gốc (dưỡng sức)" tone="muted" />
            <p class="b1__strong">{{ c.canCuGoc }}</p>
          </section>
        }

        @if (c.viPham.length) {
          <section class="b1__sec">
            <ins-section-label text="Kết quả kiểm tra khi tiếp nhận" tone="attention" [count]="c.viPham.length" />
            @for (v of c.viPham; track v.maQuyTac) {
              <hrm-alert [type]="v.mucDo === 'chan' ? 'error' : v.mucDo === 'canh-bao' ? 'warning' : 'info'"
                [message]="v.thongDiep"
                [description]="v.maQuyTac + ' · ' + v.ruleVersion + ' · ' + v.nguonPhapLy + ' · hiệu lực ' + v.ngayHieuLuc" />
            }
          </section>
        }
      </div>
    }
  `,
  host: { class: 'ins-m05-b1' },
  styles: [`
    :host { display: block; }
    .b1 { display: flex; flex-direction: column; gap: 16px; max-width: 980px; }
    .b1__sec { display: flex; flex-direction: column; gap: 8px; }
    .b1__sechead { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
    .b1__editrow { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
    .b1__lb { font-size: var(--fs-12); color: var(--text-sub); }
    .b1__in { display: inline-block; width: 130px; }
    .b1__frozen { font-size: var(--fs-12); color: var(--text-sub); background: var(--bg-surface-subtle); border-radius: var(--radius-sm); padding: 3px 9px; }
    .b1__frozen b { color: var(--text-strong); font-weight: 600; }
    .b1__muted { margin: 0; font-size: var(--fs-12); color: var(--text-sub); }
    .b1__strong { margin: 0; font-size: var(--fs-13); font-weight: 600; color: var(--text-strong); }
  `],
})
export class InsM05B1 {
  private readonly store = inject(InsM05Store);
  readonly caseId = input.required<string>();

  protected readonly c = computed(() => this.store.caseOf(this.caseId()));
  protected readonly nguonLabel = computed(() => {
    const c = this.c();
    return c ? INS_CASE_NGUON_LABEL[c.nguon] : '';
  });
  /** Field chỉ sửa được khi trạng thái cho phép (Tiếp nhận / Chờ chứng từ). */
  protected readonly editable = computed(() => {
    const s = this.c()?.trangThai;
    return s === 'tiep-nhan' || s === 'cho-chung-tu';
  });

  protected readonly descItems = computed<HrmDescItem[]>(() => {
    const c = this.c();
    if (!c) return [];
    const nv = insNhanVien(c.nhanVienId);
    const dv = insDonVi(c.donViId);
    return [
      { label: 'Người lao động', value: nv ? `${nv.name} (${nv.code})` : '—' },
      { label: 'Mã số BHXH', value: nv?.insCode ?? '—' },
      { label: 'Đơn vị · mã BHXH', value: `${dv?.ten ?? '—'} · ${c.maBHXH}` },
      { label: 'Nhóm chế độ', value: `${INS_CASE_NHOM_LABEL[c.nhom]} — ${c.loaiCheDo}` },
      { label: 'Ngày sự kiện', value: c.ngaySuKien },
      { label: 'Người phụ trách', value: c.owner },
      { label: 'Mã tương quan', value: c.correlationId },
      { label: 'Lương đóng hiện tại', value: nv?.salary ?? '—' },
      { label: 'Số ngày đề nghị', value: c.soNgay != null ? `${c.soNgay} ngày` : 'chưa tính' },
    ];
  });

  protected readonly thaiSanItems = computed<HrmDescItem[]>(() => {
    const ts = this.c()?.khoiThaiSan;
    if (!ts) return [];
    return [
      { label: 'Ngày dự sinh', value: ts.ngayDuSinh },
      { label: 'Ngày sinh con', value: ts.ngaySinhCon ?? 'chưa sinh' },
      { label: 'Số con', value: String(ts.soCon) },
      { label: 'Lần khám thai trong chu kỳ', value: ts.lanKhamThai != null ? `${ts.lanKhamThai}/5` : '—' },
    ];
  });

  protected readonly conItems = computed<HrmDescItem[]>(() => {
    const con = this.c()?.khoiCon;
    if (!con) return [];
    return [
      { label: 'Tên con', value: con.tenCon },
      { label: 'Tuổi con', value: `${con.tuoiCon} tuổi` },
      { label: 'Lũy kế năm / trần', value: `${con.luyKeNam}/${con.tranNam} ngày (trần theo tuổi con — M08)` },
    ];
  });

  /* editable fields — [(ngModel)] getter/setter bọc store patch (chỉ khi editable) */
  protected get tuNgayModel(): string { return this.c()?.tuNgay ?? ''; }
  protected set tuNgayModel(v: string) { this.patchIfEditable('tuNgay', v); }
  protected get denNgayModel(): string { return this.c()?.denNgay ?? ''; }
  protected set denNgayModel(v: string) { this.patchIfEditable('denNgay', v); }
  protected get diLamLaiModel(): string { return this.c()?.ngayDiLamLai ?? ''; }
  protected set diLamLaiModel(v: string) { this.patchIfEditable('ngayDiLamLai', v); }

  private patchIfEditable(key: 'tuNgay' | 'denNgay' | 'ngayDiLamLai', v: string): void {
    if (!this.editable()) return;
    const id = this.caseId();
    this.store.cases.update((list) => list.map((c) => (c.maCase === id ? { ...c, [key]: v } : c)));
  }
}
