import { ChangeDetectionStrategy, Component, TemplateRef, computed, inject, input, signal, viewChild } from '@angular/core';
import { FormsModule } from '@angular/forms';
import {
  HrmButton, HrmEmpty, HrmGrid, HrmGridColumn, HrmMessageService, HrmModalService, HrmSegmented,
  HrmSelect, HrmStatusCell, HrmTag, HrmTextarea,
} from 'hrm-ui';
import { InsBulkBar, InsLayerBadge, InsVarianceCell } from '../_shared';
import { insKy, insNhanVien } from '../_data/_core';
import { insFormatVnd } from '../_data/_m02-data';
import {
  INS_QUY_LABEL, InsItemChenhLech, InsKetLuanLoai, InsM04Store, M04_C12_PHAI_DONG, M04_KETLUAN_LABEL,
  M04_NGUOI_DUYET, M04_NGUONG_CHAP_NHAN, M04_NGUONG_KHOA, M04_NHANH_IDS, M04_NHANH_LABEL, M04_QUYS,
} from '../_data/_m04-data';
import { M04_ITEM_COLS, M04ItemRow, buildItemRow } from './_m04-columns';

/** ═════════ M04 · T3 CHÊNH LỆCH (SIGNATURE) — đối soát 4 NGUỒN · cây 9 nhánh · 3 trục xem ═════════
 *  Header = chuỗi 4 LỚP (PBI-04.01.9 / BQA-4): ① Dự kiến nội bộ (snapshot) → ② Hồ sơ đã chấp nhận
 *  (derive sống từ M03) → ③ Chính thức C12/D09 → ④ Thanh toán & phân bổ (chứng từ nộp), kèm 3 CẶP
 *  so sánh (①↔② · ②↔③ · ③↔④) + chênh CHƯA giải thích. Chưa nhận C12 (k08) → fallback đối soát
 *  2 LỚP ①↔②, ghi rõ lớp ③ chưa có (không chờ C12 mới hiển thị).
 *  Cây: 9 nhánh nguyên nhân NGUYÊN VĂN → nhóm theo TRỤC đang chọn (NLĐ / quỹ / kỳ bị tác động)
 *  → item. Đổi trục = đổi nhóm cây; footer chứng minh bất biến "TỔNG 3 TRỤC BẰNG NHAU". Cây TỰ DỰNG
 *  (hrm-tree-list bọc nz-tree chỉ nhận title string — không render được variance cell trong node).
 *  Bảng item (5 trạng thái) + bulk dry-run (ins-bulk-bar): Gán nguyên nhân + owner ·
 *  3 kết luận (sinh yêu cầu → mã tương quan + ghi chú M03 · chấp nhận → ngưỡng M08 + chờ duyệt ·
 *  chuyển exception → M05/M06) · Duyệt chấp nhận (BQA-17 — maker ≠ checker) · Hủy kết luận.
 *  Item `Đã đóng` chỉ đọc. */
@Component({
  selector: 'ins-m04-tab-chenhlech',
  imports: [
    FormsModule, HrmButton, HrmEmpty, HrmGrid, HrmSegmented, HrmSelect, HrmStatusCell, HrmTag,
    HrmTextarea, InsBulkBar, InsLayerBadge, InsVarianceCell,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <!-- ── header ĐỐI SOÁT 4 NGUỒN (PBI-04.01.9 / BQA-4) — hiện CẢ khi chưa có item (fallback 2 lớp) ── -->
    <div class="t3-head">
      <div class="t3-chain" role="list">
        @for (l of layers(); track l.key; let last = $last) {
          <div class="t3-layer" [class.t3-layer--miss]="l.missing" role="listitem">
            <span class="t3-layer__lb">{{ l.nhan }}</span>
            <b class="t3-layer__num">{{ l.giaTri }}</b>
            <ins-layer-badge [layer]="$any(l.badge)" />
          </div>
          @if (!last) { <span class="t3-chain__sep" aria-hidden="true">→</span> }
        }
      </div>
      <div class="t3-pairs">
        @for (p of pairs(); track p.nhan) {
          <span class="t3-pair">
            <span class="t3-pair__lb">{{ p.nhan }}</span>
            @if (p.diff !== null) { <ins-variance-cell [diff]="p.diff!" [tone]="p.tone" /> }
            @else { <span class="t3-pair__na">{{ p.na }}</span> }
          </span>
        }
        <div class="t3-head__unex">
          <span class="t3-head__unex-lb">Chênh CHƯA giải thích</span>
          <span class="t3-head__unex-num" [class.t3-head__unex-num--over]="unexplainedOver()">{{ unexplainedLabel() }}</span>
          <span class="t3-head__unex-sub">ngưỡng khóa {{ nguongLabel }} (M08){{ unexplainedOver() ? ' — VƯỢT NGƯỠNG' : '' }}</span>
        </div>
      </div>
      @if (!coC12()) {
        <p class="t3-fallback">Chưa nhận C12-TS — đối soát 2 LỚP (Dự kiến nội bộ ↔ Hồ sơ đã chấp nhận);
          lớp Chính thức C12/D09 CHƯA CÓ — không chờ C12 mới hiển thị (PBI-04.01.9).</p>
      }
    </div>

    @if (hasData()) {
      <!-- ── 3 trục xem ── -->
      <div class="t3-axis">
        <span class="t3-axis__lb">Trục xem</span>
        <hrm-segmented [(ngModel)]="axisModel" [options]="axisOptions" size="sm" />
        <span class="t3-axis__note">Đổi trục đổi cách NHÓM cây — tổng không đổi (bất biến 3 trục).</span>
      </div>

      <!-- ── variance tree 9 nhánh (tự dựng) ── -->
      <div class="t3-tree" role="tree">
        @for (n of treeRows(); track n.key) {
          <div class="t3-node" [class.t3-node--leaf]="n.leaf" [class.t3-node--empty]="n.empty"
            [style.padding-left.px]="10 + n.level * 26" role="treeitem" [attr.aria-expanded]="n.leaf ? null : n.expanded">
            @if (!n.leaf) {
              <button type="button" class="t3-node__toggle" (click)="toggle(n.key)">{{ n.expanded ? '−' : '+' }}</button>
            } @else { <span class="t3-node__dot" aria-hidden="true"></span> }
            <span class="t3-node__label" [title]="n.label">{{ n.label }}</span>
            @if (n.count !== null) { <span class="t3-node__count">{{ n.count }} item</span> }
            @if (n.status) { <hrm-status-cell [status]="$any(n.statusTone)" [label]="n.status" variant="badge" /> }
            <span class="t3-node__amount" [attr.data-tone]="n.tone">{{ n.amount }}</span>
          </div>
        }
        <div class="t3-tree__footer">
          Tổng 3 trục khớp: <b>{{ axisTotals().nld }}</b> (NLĐ) = <b>{{ axisTotals().quy }}</b> (quỹ)
          = <b>{{ axisTotals().ky }}</b> (kỳ) <span class="t3-tree__ok">✓</span>
        </div>
      </div>

      <!-- ── bảng item + bulk ── -->
      <section class="t3-sec">
        <h3 class="t3-sec__title">Item chênh lệch ({{ itemRows().length }})
          <span class="t3-sec__hint">Đã đóng = chỉ đọc · kết luận sai → Hủy kết luận (kỳ chưa khóa, lịch sử giữ nguyên)</span>
        </h3>
        <hrm-grid [columns]="itemCols()" [data]="itemRows()" rowKey="id" [selectable]="true"
          [(selectedKeys)]="selModel" density="compact" minWidth="1600px" [pageSize]="10" />
      </section>

      <ins-bulk-bar [selected]="sel().length" [eligible]="bulkPreview().eligible" [blocked]="bulkPreview().blocked">
        <hrm-button size="sm" (click)="openGan()">Gán nguyên nhân + owner</hrm-button>
        <hrm-button size="sm" variant="primary" (click)="openKetLuan('sinh-yeu-cau')">Sinh yêu cầu điều chỉnh</hrm-button>
        <hrm-button size="sm" (click)="openKetLuan('chap-nhan')">Chấp nhận chênh lệch</hrm-button>
        <hrm-button size="sm" (click)="openKetLuan('chuyen-exception')">Chuyển exception</hrm-button>
        <hrm-button size="sm" (click)="openDuyetChapNhan()">Duyệt chấp nhận</hrm-button>
        <hrm-button size="sm" [danger]="true" (click)="openHuy()">Hủy kết luận</hrm-button>
      </ins-bulk-bar>
    } @else {
      <div class="t3-empty">
        <hrm-empty preset="no-data" [description]="emptyLabel()" />
      </div>
    }

    <!-- ═════ cell templates ═════ -->
    <ng-template #moTaCell let-row>
      <div class="t3-mota">
        <span class="t3-mota__tx" [title]="$any(row).moTa">{{ $any(row).moTa }}</span>
        @if ($any(row).nopThua) { <hrm-tag color="teal" size="sm" variant="lighter">nộp thừa</hrm-tag> }
      </div>
    </ng-template>
    <ng-template #nhanhCell let-row><span class="t3-nhanh">{{ $any(row).nhanhLabel }}</span></ng-template>
    <ng-template #giaTriCell let-row>
      <span class="t3-money" [class.t3-money--neg]="$any(row).giaTriAm">{{ $any(row).giaTri }}</span>
    </ng-template>
    <ng-template #trucCell let-row><span class="t3-truc">{{ $any(row).trucLabel }}</span></ng-template>
    <ng-template #statusCellT let-row>
      <hrm-status-cell [status]="$any(row).trangThaiTone" [label]="$any(row).trangThaiLabel" variant="badge" />
    </ng-template>
    <ng-template #ketLuanCell let-row>
      @if ($any(row).ketLuan) {
        <div class="t3-kl">
          <span class="t3-kl__tx">{{ $any(row).ketLuan }}</span>
          @if ($any(row).maTuongQuan) { <hrm-tag color="blue" size="sm" variant="lighter">{{ $any(row).maTuongQuan }}</hrm-tag> }
        </div>
      } @else { <span class="t3-muted">chưa kết luận</span> }
    </ng-template>

    <!-- ═════ modal gán nguyên nhân ═════ -->
    <ng-template #ganTpl>
      <div class="t3-form">
        <p class="t3-form__hint">Gán nhánh nguyên nhân (reason code theo nhánh) + owner cho {{ selCount() }} item — bulk thành công một phần, item Đã đóng/đã kết luận bị bỏ qua kèm lý do.</p>
        <hrm-select [(ngModel)]="ganNhanhModel" [options]="nhanhOptions" [allowClear]="false" placeholder="Nhánh nguyên nhân" />
        <hrm-select [(ngModel)]="ganOwnerModel" [options]="ownerOptions" [allowClear]="false" [showSearch]="false" placeholder="Owner" />
      </div>
    </ng-template>

    <!-- ═════ modal kết luận (3 loại) ═════ -->
    <ng-template #klTpl>
      <div class="t3-form">
        @switch (klLoai()) {
          @case ('sinh-yeu-cau') {
            <p class="t3-form__hint">Sinh YÊU CẦU ĐIỀU CHỈNH cho {{ selCount() }} item: mỗi item nhận MÃ TƯƠNG QUAN 2 chiều,
              gắn KỲ HIỆN HÀNH, đi D02-LT — ghi chú tự động sang M03 (M04 chỉ theo dõi, không kê khai hộ).</p>
          }
          @case ('chap-nhan') {
            <p class="t3-form__hint">CHẤP NHẬN chênh lệch → chuyển Chờ duyệt chấp nhận. GUARD ngưỡng M08:
              tổng chấp nhận/kỳ sau lượt này = <b>{{ chapNhanPreview().tongMoi }}</b> / ngưỡng <b>{{ nguongChapNhanLabel }}</b>
              — vượt ngưỡng thì TOÀN BỘ lượt bị chặn.</p>
          }
          @case ('chuyen-exception') {
            <p class="t3-form__hint">Chuyển EXCEPTION kèm mã tương quan 2 chiều: sự vụ/định danh → M06 · chế độ → M05. Item khép tại M04 khi phân hệ nhận xử lý xong.</p>
            <hrm-select [(ngModel)]="klPhanHeModel" [options]="phanHeOptions" [allowClear]="false" [showSearch]="false" />
          }
        }
        <hrm-textarea [(ngModel)]="reasonModel" placeholder="Lý do kết luận (bắt buộc)…" [minRows]="3" [status]="reasonErr() ? 'error' : ''" />
        @if (reasonErr()) { <span class="t3-form__err">{{ reasonErr() }}</span> }
      </div>
    </ng-template>

    <!-- ═════ modal DUYỆT CHẤP NHẬN (BQA-17 — maker ≠ checker) ═════ -->
    <ng-template #duyetCnTpl>
      <div class="t3-form">
        <p class="t3-form__hint">Duyệt kết luận CHẤP NHẬN cho {{ selCount() }} item — chỉ item đang
          <b>Chờ duyệt chấp nhận</b>; người duyệt BẮT BUỘC ≠ người lập kết luận (maker–checker — chọn
          đúng người lập để thấy guard chặn). Duyệt xong: kết luận → Đã chấp nhận, item → Đã đóng.</p>
        <hrm-select [(ngModel)]="duyetCnNguoiModel" [options]="ownerOptions" [allowClear]="false" [showSearch]="false" />
        @if (reasonErr()) { <span class="t3-form__err">{{ reasonErr() }}</span> }
      </div>
    </ng-template>

    <!-- ═════ modal hủy kết luận ═════ -->
    <ng-template #huyTpl>
      <div class="t3-form">
        <p class="t3-form__hint">Hủy kết luận {{ selCount() }} item — kỳ chưa khóa; item về "chưa kết luận" (Đã gán nguyên nhân); lịch sử kết luận GIỮ NGUYÊN.</p>
        <hrm-textarea [(ngModel)]="reasonModel" placeholder="Lý do hủy (bắt buộc)…" [minRows]="3" [status]="reasonErr() ? 'error' : ''" />
        @if (reasonErr()) { <span class="t3-form__err">{{ reasonErr() }}</span> }
      </div>
    </ng-template>
  `,
  host: { class: 'ins-m04-tab-chenhlech' },
  styles: [`
    :host { display: flex; flex-direction: column; gap: 14px; min-height: 0; overflow: auto; padding: 12px 2px 24px; }

    .t3-head { display: flex; flex-direction: column; gap: 8px; }
    .t3-chain { display: flex; align-items: stretch; gap: 6px; flex-wrap: wrap; }
    .t3-layer {
      display: flex; flex-direction: column; align-items: flex-start; gap: 2px;
      border: 1px solid var(--border-sub); border-radius: var(--radius-md);
      background: var(--bg-surface); padding: 6px 10px; min-width: 0;
    }
    .t3-layer--miss { border-style: dashed; }
    .t3-layer--miss .t3-layer__num { color: var(--text-sub); font-weight: 500; font-size: var(--fs-12); }
    .t3-layer__lb { font-size: var(--fs-11); font-weight: 600; text-transform: uppercase; letter-spacing: .03em; color: var(--text-sub); }
    .t3-layer__num { font-size: var(--fs-14); font-weight: 700; font-variant-numeric: tabular-nums; color: var(--text-strong); }
    .t3-chain__sep { align-self: center; color: var(--text-soft); font-weight: 700; }
    .t3-pairs { display: flex; align-items: baseline; gap: 18px; flex-wrap: wrap; }
    .t3-pair { display: inline-flex; align-items: baseline; gap: 8px; }
    .t3-pair__lb { font-size: var(--fs-12); color: var(--text-sub); }
    .t3-pair__na { font-size: var(--fs-12); font-weight: 600; color: var(--text-soft); }
    .t3-fallback { margin: 0; font-size: var(--fs-12); color: var(--warning-text); }
    .t3-head__unex { margin-left: auto; display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; }
    .t3-head__unex-lb { font-size: var(--fs-12); font-weight: 600; color: var(--text-sub); text-transform: uppercase; letter-spacing: .04em; }
    .t3-head__unex-num { font-size: var(--fs-24, 24px); font-weight: 700; font-variant-numeric: tabular-nums; color: var(--text-strong); }
    .t3-head__unex-num--over { color: var(--error-base); }
    .t3-head__unex-sub { font-size: var(--fs-11); color: var(--text-soft); }

    .t3-axis { display: flex; align-items: center; gap: 10px; }
    .t3-axis__lb { font-size: var(--fs-12); color: var(--text-sub); }
    .t3-axis__note { font-size: var(--fs-11); color: var(--text-soft); }

    .t3-tree { border: 1px solid var(--border-sub); border-radius: var(--radius-md); overflow: hidden; }
    .t3-node { display: flex; align-items: center; gap: 8px; padding: 5px 12px; border-bottom: 1px solid var(--border-sub); min-width: 0; }
    .t3-node:hover { background: var(--bg-surface-subtle); }
    .t3-node--empty { opacity: .55; }
    .t3-node__toggle {
      flex: none; width: 18px; height: 18px; line-height: 1; border: 1px solid var(--border-sub);
      border-radius: var(--radius-sm); background: var(--bg-surface); cursor: pointer;
      font: inherit; font-size: var(--fs-12); color: var(--text-sub); display: inline-flex; align-items: center; justify-content: center;
    }
    .t3-node__dot { flex: none; width: 5px; height: 5px; border-radius: 50%; background: var(--text-soft); margin: 0 6px; }
    .t3-node__label { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: var(--fs-13); color: var(--text-body); }
    .t3-node:not(.t3-node--leaf) .t3-node__label { font-weight: 600; color: var(--text-strong); }
    .t3-node__count { flex: none; font-size: var(--fs-11); color: var(--text-sub); background: var(--bg-surface-subtle); border-radius: var(--radius-full); padding: 0 7px; }
    .t3-node__amount { margin-left: auto; flex: none; font-variant-numeric: tabular-nums; font-weight: 600; font-size: var(--fs-13); }
    .t3-node__amount[data-tone='up'] { color: var(--error-base); }
    .t3-node__amount[data-tone='down'] { color: var(--success-base); }
    .t3-node__amount[data-tone='zero'] { color: var(--text-soft); }
    .t3-tree__footer { padding: 8px 12px; font-size: var(--fs-12); color: var(--text-sub); background: var(--bg-surface-subtle); }
    .t3-tree__footer b { color: var(--text-strong); font-variant-numeric: tabular-nums; }
    .t3-tree__ok { color: var(--success-base); font-weight: 700; }

    .t3-sec { display: flex; flex-direction: column; gap: 8px; }
    .t3-sec__title { margin: 0; font-size: var(--fs-13); font-weight: 600; color: var(--text-strong); display: flex; gap: 10px; align-items: center; flex-wrap: wrap; }
    .t3-sec__hint { font-size: var(--fs-11); font-weight: 400; color: var(--text-soft); }

    .t3-mota { display: flex; align-items: center; gap: 6px; min-width: 0; }
    .t3-mota__tx { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--text-strong); }
    .t3-nhanh, .t3-truc { font-size: var(--fs-12); color: var(--text-sub); }
    .t3-money { font-variant-numeric: tabular-nums; font-weight: 600; color: var(--error-base); }
    .t3-money--neg { color: var(--success-base); }
    .t3-kl { display: flex; align-items: center; gap: 6px; min-width: 0; }
    .t3-kl__tx { font-size: var(--fs-12); color: var(--text-body); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    .t3-muted { color: var(--text-soft); font-size: var(--fs-12); }

    .t3-empty { padding: 56px 0; display: flex; justify-content: center; }
    .t3-form { display: flex; flex-direction: column; gap: 8px; }
    .t3-form__hint { margin: 0; font-size: var(--fs-12); color: var(--text-sub); }
    .t3-form__hint b { color: var(--text-strong); }
    .t3-form__err { font-size: var(--fs-12); color: var(--error-text); }
  `],
})
export class InsM04TabChenhLech {
  protected readonly store = inject(InsM04Store);
  private readonly msg = inject(HrmMessageService);
  private readonly modal = inject(HrmModalService);

  readonly kyId = input.required<string>();

  protected readonly nguongLabel = insFormatVnd(M04_NGUONG_KHOA);
  protected readonly nguongChapNhanLabel = insFormatVnd(M04_NGUONG_CHAP_NHAN);
  protected readonly ownerOptions = M04_NGUOI_DUYET.map((n) => ({ value: n, label: n }));
  protected readonly nhanhOptions = M04_NHANH_IDS.map((n) => ({ value: n, label: `${n} · ${M04_NHANH_LABEL[n]}` }));
  protected readonly phanHeOptions = [
    { value: 'm06', label: 'M06 — Hồ sơ sự vụ / định danh' },
    { value: 'm05', label: 'M05 — Chế độ BHXH' },
  ];
  protected readonly axisOptions = [
    { label: 'Theo NLĐ', value: 'nld' },
    { label: 'Theo quỹ', value: 'quy' },
    { label: 'Theo kỳ', value: 'ky' },
  ];

  protected readonly kyItems = computed<InsItemChenhLech[]>(() => this.store.itemsOf(this.kyId()));
  protected readonly hasData = computed(() => this.kyItems().length > 0);
  protected readonly emptyLabel = computed(() => {
    // k08: chưa nhận C12 → chưa có gì để đối soát; nhãn ĐÚNG chữ PBI.
    const c12 = this.store.c12().some((r) => r.kyId === this.kyId() && r.trangThai !== 'chua-nhan');
    return c12 ? 'Chưa có số liệu cho kỳ này' : 'Chưa nhận C12-TS';
  });
  protected readonly kyLocked = computed(() => this.store.isKyKhoa(this.kyId()));

  /* ── header ĐỐI SOÁT 4 NGUỒN (BQA-4): ① nội bộ · ② hồ sơ (sống từ M03) · ③ C12 · ④ thanh toán ── */
  protected readonly coC12 = computed(() => M04_C12_PHAI_DONG[this.kyId()] !== undefined);
  private readonly nguon = computed(() => {
    const ky = this.kyId();
    return {
      noiBo: this.store.duKienNoiBo(ky),
      hoSo: this.store.hoSoDaChapNhan(ky),
      c12: this.coC12() ? M04_C12_PHAI_DONG[ky] : null,
      thanhToan: this.store.thanhToanPhanBo(ky),
    };
  });
  protected readonly layers = computed(() => {
    const n = this.nguon();
    const v = (x: number | null, miss: string) => (x === null ? miss : insFormatVnd(x));
    return [
      { key: 'noi-bo', nhan: '① Dự kiến nội bộ', giaTri: v(n.noiBo, 'Chưa dựng snapshot'), missing: n.noiBo === null, badge: 'du-kien' },
      { key: 'ho-so', nhan: '② Hồ sơ đã chấp nhận', giaTri: v(n.hoSo, 'Chưa có số liệu cho kỳ này'), missing: n.hoSo === null, badge: 'da-giao-dich' },
      { key: 'c12', nhan: '③ Chính thức C12/D09', giaTri: v(n.c12, 'Chưa nhận C12-TS'), missing: n.c12 === null, badge: 'chinh-thuc' },
      { key: 'thanh-toan', nhan: '④ Thanh toán & phân bổ', giaTri: v(n.thanhToan, 'Chưa có chứng từ nộp'), missing: n.thanhToan === null, badge: 'da-giao-dich' },
    ];
  });
  /** 3 cặp so sánh ①↔② · ②↔③ · ③↔④ — thiếu lớp nào cặp đó "Chưa đối soát được" (không số 0 giả). */
  protected readonly pairs = computed(() => {
    const n = this.nguon();
    const cap = (nhan: string, a: number | null, b: number | null, na: string) => {
      if (a === null || b === null) return { nhan, diff: null as string | null, tone: 'zero' as const, na };
      const d = b - a;
      return { nhan, diff: d === 0 ? '0' : insFormatVnd(d, true), tone: (d > 0 ? 'up' : d < 0 ? 'down' : 'zero') as 'up' | 'down' | 'zero', na };
    };
    return [
      cap('Nội bộ ↔ hồ sơ', n.noiBo, n.hoSo, 'Chưa có số liệu cho kỳ này'),
      cap('Hồ sơ ↔ C12', n.hoSo, n.c12, 'Chưa đối soát được'),
      cap('C12 ↔ thanh toán', n.c12, n.thanhToan, 'Chưa đối soát được'),
    ];
  });
  protected readonly unexplained = computed(() => this.store.unexplainedByKy()[this.kyId()] ?? 0);
  protected readonly unexplainedLabel = computed(() => insFormatVnd(this.unexplained()));
  protected readonly unexplainedOver = computed(() => this.unexplained() > M04_NGUONG_KHOA);

  /* ── 3 trục ── */
  private readonly axis = signal<'nld' | 'quy' | 'ky'>('nld');
  protected get axisModel(): string | number { return this.axis(); }
  protected set axisModel(v: string | number) { this.axis.set(String(v) as 'nld' | 'quy' | 'ky'); }

  private axisKey(i: InsItemChenhLech): string {
    const a = this.axis();
    if (a === 'quy') return INS_QUY_LABEL[i.trucQuy];
    if (a === 'ky') return insKy(i.trucKyBiTacDong)?.label ?? i.trucKyBiTacDong;
    return i.trucNhanVienId ? (insNhanVien(i.trucNhanVienId)?.name ?? i.trucNhanVienId) : 'Chưa gắn NLĐ';
  }

  /** Tổng theo từng trục — chứng minh bất biến "3 trục bằng nhau" bằng cách CỘNG THẬT 3 lần. */
  protected readonly axisTotals = computed(() => {
    const items = this.kyItems();
    const nld = items.reduce((s, i) => s + i.giaTri, 0);
    const quy = M04_QUYS.reduce((s, q) => s + items.filter((i) => i.trucQuy === q).reduce((x, i) => x + i.giaTri, 0), 0);
    const kys = [...new Set(items.map((i) => i.trucKyBiTacDong))];
    const ky = kys.reduce((s, k) => s + items.filter((i) => i.trucKyBiTacDong === k).reduce((x, i) => x + i.giaTri, 0), 0);
    return { nld: insFormatVnd(nld, true), quy: insFormatVnd(quy, true), ky: insFormatVnd(ky, true) };
  });

  /* ── cây tự dựng: nhánh (9) → nhóm trục → item ── */
  private readonly collapsed = signal<ReadonlySet<string>>(new Set());
  protected toggle(key: string): void {
    this.collapsed.update((s) => {
      const next = new Set(s);
      next.has(key) ? next.delete(key) : next.add(key);
      return next;
    });
  }

  protected readonly treeRows = computed(() => {
    const items = this.kyItems();
    const collapsed = this.collapsed();
    const rows: {
      key: string; level: number; label: string; count: number | null; amount: string;
      tone: 'up' | 'down' | 'zero'; leaf: boolean; empty: boolean; expanded: boolean;
      status?: string; statusTone?: string;
    }[] = [];
    const tone = (v: number): 'up' | 'down' | 'zero' => (v > 0 ? 'up' : v < 0 ? 'down' : 'zero');
    for (const nhanh of M04_NHANH_IDS) {
      const nItems = items.filter((i) => i.nhanh === nhanh);
      const nSum = nItems.reduce((s, i) => s + i.giaTri, 0);
      const nKey = `n${nhanh}`;
      const nExpanded = !collapsed.has(nKey);
      rows.push({
        key: nKey, level: 0, label: `Nhánh ${nhanh} — ${M04_NHANH_LABEL[nhanh]}`,
        count: nItems.length, amount: nItems.length ? insFormatVnd(nSum, true) : 'không có chênh',
        tone: tone(nSum), leaf: false, empty: !nItems.length, expanded: nExpanded,
      });
      if (!nExpanded || !nItems.length) continue;
      const groups = new Map<string, InsItemChenhLech[]>();
      for (const i of nItems) {
        const k = this.axisKey(i);
        groups.set(k, [...(groups.get(k) ?? []), i]);
      }
      for (const [gLabel, gItems] of groups) {
        const gSum = gItems.reduce((s, i) => s + i.giaTri, 0);
        const gKey = `${nKey}:${gLabel}`;
        const gExpanded = !collapsed.has(gKey);
        rows.push({
          key: gKey, level: 1, label: gLabel, count: gItems.length,
          amount: insFormatVnd(gSum, true), tone: tone(gSum), leaf: false, empty: false, expanded: gExpanded,
        });
        if (!gExpanded) continue;
        for (const i of gItems) {
          rows.push({
            key: `${gKey}:${i.id}`, level: 2, label: `${i.id} · ${i.moTa}`, count: null,
            amount: insFormatVnd(i.giaTri, true), tone: tone(i.giaTri), leaf: true, empty: false, expanded: false,
            status: this.itemRowsById().get(i.id)?.trangThaiLabel, statusTone: this.itemRowsById().get(i.id)?.trangThaiTone,
          });
        }
      }
    }
    return rows;
  });

  /* ── bảng item ── */
  private readonly moTaTpl = viewChild.required<TemplateRef<unknown>>('moTaCell');
  private readonly nhanhTpl = viewChild.required<TemplateRef<unknown>>('nhanhCell');
  private readonly giaTriTpl = viewChild.required<TemplateRef<unknown>>('giaTriCell');
  private readonly trucTpl = viewChild.required<TemplateRef<unknown>>('trucCell');
  private readonly statusTpl = viewChild.required<TemplateRef<unknown>>('statusCellT');
  private readonly ketLuanTpl = viewChild.required<TemplateRef<unknown>>('ketLuanCell');

  protected readonly itemRows = computed<M04ItemRow[]>(() => {
    const locked = this.kyLocked();
    return this.kyItems().map((i) => buildItemRow(i, locked));
  });
  private readonly itemRowsById = computed(() => new Map(this.itemRows().map((r) => [r.id, r])));
  protected readonly itemCols = computed<HrmGridColumn[]>(() => {
    const tpl: Record<string, TemplateRef<unknown> | undefined> = {
      moTa: this.moTaTpl(), nhanh: this.nhanhTpl(), giaTri: this.giaTriTpl(), truc: this.trucTpl(),
      trangThai: this.statusTpl(), ketLuan: this.ketLuanTpl(),
    };
    return M04_ITEM_COLS.map((c) => ({ ...c, cell: tpl[c.key] as HrmGridColumn['cell'] }));
  });

  /* ── selection + bulk dry-run ── */
  private readonly selKeys = signal<unknown[]>([]);
  protected get selModel(): unknown[] { return this.selKeys(); }
  protected set selModel(v: unknown[]) { this.selKeys.set(v); }
  protected readonly sel = computed<string[]>(() => this.selKeys().map(String));
  protected readonly selCount = computed(() => this.sel().length);
  protected readonly bulkPreview = computed(() => this.store.itemPreview(this.sel(), true));

  /* ── modals ── */
  private dlg: { close: () => void } | null = null;
  private readonly reasonText = signal('');
  protected get reasonModel(): string { return this.reasonText(); }
  protected set reasonModel(v: string) { this.reasonText.set(v ?? ''); if (v?.trim()) this.reasonErr.set(''); }
  protected readonly reasonErr = signal('');

  private readonly ganTplRef = viewChild<TemplateRef<unknown>>('ganTpl');
  private readonly klTplRef = viewChild<TemplateRef<unknown>>('klTpl');
  private readonly huyTplRef = viewChild<TemplateRef<unknown>>('huyTpl');

  /* gán nguyên nhân — mặc định nhánh (1); item KHÔNG gán được giữ `Mới phát hiện` (không có nhánh
   *  "chưa xác định" — BQA-3). */
  private readonly ganNhanh = signal<number>(1);
  protected get ganNhanhModel(): unknown { return this.ganNhanh(); }
  protected set ganNhanhModel(v: unknown) { this.ganNhanh.set(Number(v) || 1); }
  private readonly ganOwner = signal(M04_NGUOI_DUYET[0]);
  protected get ganOwnerModel(): unknown { return this.ganOwner(); }
  protected set ganOwnerModel(v: unknown) { this.ganOwner.set(String(v ?? M04_NGUOI_DUYET[0])); }

  protected openGan(): void {
    if (!this.sel().length) { this.msg.warning('Chưa chọn item nào.'); return; }
    this.dlg = this.modal.open({
      title: 'Gán nguyên nhân + owner', content: this.ganTplRef()!, width: 520,
      footer: [
        { label: 'Hủy', onClick: () => this.dlg?.close() },
        { label: 'Gán', type: 'primary', onClick: () => this.confirmGan() },
      ],
    });
  }
  private confirmGan(): void {
    const r = this.store.ganNguyenNhan(this.sel(), this.ganNhanh(), this.ganOwner());
    if (r.done && r.skipped.length) this.msg.warning(`Đã gán ${r.done}/${this.sel().length} item · ${r.skipped.length} bị bỏ qua (${r.skipped[0].reason}).`);
    else if (r.done) this.msg.success(`Đã gán nguyên nhân + owner cho ${r.done}/${this.sel().length} item.`);
    else this.msg.error(r.skipped[0]?.reason ?? 'Không gán được.');
    this.dlg?.close();
  }

  /* kết luận 3 loại */
  protected readonly klLoai = signal<InsKetLuanLoai>('sinh-yeu-cau');
  private readonly klPhanHe = signal<'m05' | 'm06'>('m06');
  protected get klPhanHeModel(): unknown { return this.klPhanHe(); }
  protected set klPhanHeModel(v: unknown) { this.klPhanHe.set((v as 'm05' | 'm06') ?? 'm06'); }
  /** Preview ngưỡng chấp nhận: tổng đã chấp nhận + Σ|giá trị| item hợp lệ đang chọn. */
  protected readonly chapNhanPreview = computed(() => {
    const ids = new Set(this.sel());
    const eligible = this.kyItems().filter((i) => ids.has(i.id) && i.trangThai !== 'da-dong' && i.trangThai !== 'da-giai-trinh');
    const tongMoi = this.store.tongChapNhan(this.kyId()) + eligible.reduce((s, i) => s + Math.abs(i.giaTri), 0);
    return { tongMoi: insFormatVnd(tongMoi), over: tongMoi > M04_NGUONG_CHAP_NHAN };
  });

  protected openKetLuan(loai: InsKetLuanLoai): void {
    if (!this.sel().length) { this.msg.warning('Chưa chọn item nào.'); return; }
    this.klLoai.set(loai); this.reasonText.set(''); this.reasonErr.set('');
    this.dlg = this.modal.open({
      title: `Kết luận: ${M04_KETLUAN_LABEL[loai]}`, content: this.klTplRef()!, width: 540,
      footer: [
        { label: 'Hủy', onClick: () => this.dlg?.close() },
        { label: M04_KETLUAN_LABEL[loai], type: 'primary', onClick: () => this.confirmKetLuan() },
      ],
    });
  }
  private confirmKetLuan(): void {
    const lyDo = this.reasonText().trim();
    if (!lyDo) { this.reasonErr.set('Lý do kết luận là bắt buộc.'); return; }
    const loai = this.klLoai();
    const r = this.store.ketLuan(this.sel(), loai, lyDo, this.klPhanHe());
    if (r.done) {
      const cor = r.maTuongQuan.length ? ` Mã tương quan: ${r.maTuongQuan.join(', ')}.` : '';
      const extra = loai === 'sinh-yeu-cau' ? ' Đã ghi chú sang M03 (gắn kỳ hiện hành, đi D02-LT).'
        : loai === 'chap-nhan' ? ' Chờ duyệt chấp nhận (maker–checker).'
        : ` Đã chuyển ${this.klPhanHe().toUpperCase()}.`;
      this.msg.success(`Kết luận ${r.done}/${this.sel().length} item.${cor}${extra}${r.skipped.length ? ` ${r.skipped.length} bị bỏ qua.` : ''}`);
      this.dlg?.close();
    } else {
      this.reasonErr.set(r.skipped[0]?.reason ?? 'Không kết luận được item nào.');
    }
  }

  /* duyệt chấp nhận (BQA-17): Chờ duyệt chấp nhận → Đã chấp nhận — người duyệt ≠ người lập */
  private readonly duyetCnTplRef = viewChild<TemplateRef<unknown>>('duyetCnTpl');
  private readonly duyetCnNguoi = signal(M04_NGUOI_DUYET[0]);
  protected get duyetCnNguoiModel(): unknown { return this.duyetCnNguoi(); }
  protected set duyetCnNguoiModel(v: unknown) { this.duyetCnNguoi.set(String(v ?? M04_NGUOI_DUYET[0])); this.reasonErr.set(''); }

  protected openDuyetChapNhan(): void {
    if (!this.sel().length) { this.msg.warning('Chưa chọn item nào.'); return; }
    this.reasonErr.set('');
    this.dlg = this.modal.open({
      title: 'Duyệt chấp nhận (maker–checker)', content: this.duyetCnTplRef()!, width: 520,
      footer: [
        { label: 'Hủy', onClick: () => this.dlg?.close() },
        { label: 'Duyệt chấp nhận', type: 'primary', onClick: () => this.confirmDuyetChapNhan() },
      ],
    });
  }
  private confirmDuyetChapNhan(): void {
    const r = this.store.duyetChapNhan(this.sel(), this.duyetCnNguoi());
    if (r.done) {
      this.msg.success(`Đã duyệt chấp nhận ${r.done}/${this.sel().length} item — kết luận Đã chấp nhận, item Đã đóng.${r.skipped.length ? ` ${r.skipped.length} bị bỏ qua (${r.skipped[0].reason}).` : ''}`);
      this.dlg?.close();
    } else this.reasonErr.set(r.skipped[0]?.reason ?? 'Không duyệt được item nào.');
  }

  /* hủy kết luận */
  protected openHuy(): void {
    if (!this.sel().length) { this.msg.warning('Chưa chọn item nào.'); return; }
    this.reasonText.set(''); this.reasonErr.set('');
    this.dlg = this.modal.open({
      title: 'Hủy kết luận', content: this.huyTplRef()!, width: 460,
      footer: [
        { label: 'Đóng', onClick: () => this.dlg?.close() },
        { label: 'Hủy kết luận', type: 'primary', danger: true, onClick: () => this.confirmHuy() },
      ],
    });
  }
  private confirmHuy(): void {
    const lyDo = this.reasonText().trim();
    if (!lyDo) { this.reasonErr.set('Lý do hủy là bắt buộc.'); return; }
    const r = this.store.huyKetLuan(this.sel(), lyDo);
    if (r.done) {
      this.msg.success(`Đã hủy kết luận ${r.done}/${this.sel().length} item — lịch sử giữ nguyên.${r.skipped.length ? ` ${r.skipped.length} bị bỏ qua.` : ''}`);
      this.dlg?.close();
    } else this.reasonErr.set(r.skipped[0]?.reason ?? 'Không hủy được.');
  }
}
