import { Injectable, computed, inject, signal } from '@angular/core';
import { InsLayer } from '../_shared';
import { InsModuleKey, InsNavContext, InsShellStore, insKy, insKyDaKhoa } from '../_data/_core';
import { M02_TODAY } from '../_data/_m02-data';

/** ═════════ M01 — ngữ cảnh trang (KHÔNG providedIn root — provider cục bộ InsM01Page) ═════════
 *  M01 KHÔNG SỞ HỮU GÌ (ownership _cross-cutting.md) — service này chỉ giữ UI-state của trang:
 *  kỳ + đơn vị + đợt đang xem, 2 quyền demo, panel trượt CHỈ ĐỌC dùng chung.
 *  Mỗi Ô có ĐÚNG MỘT hành vi: mở panel (`moPeek`) HOẶC điều hướng (`go` — luôn mang {ky, donVi, filter}). */

export interface M01PeekLine { label: string; value: string; layer?: InsLayer; }
export interface M01PeekLink { label: string; module: InsModuleKey; filter?: string; }
export interface M01Peek {
  title: string;
  /** Diễn giải chỉ đọc — không trường nhập, không nút phê duyệt. */
  lines: M01PeekLine[];
  links: M01PeekLink[];
  note?: string;
}

@Injectable()
export class M01Ctx {
  private readonly shell = inject(InsShellStore);

  /** Kỳ đang xem — mặc định k07 (Đang đối soát — kỳ giàu dữ liệu nhất để demo; đổi tự do). */
  readonly ky = signal('k07');
  readonly donVi = signal('dv1');
  /** Đợt trong kỳ (đơn vị dv1 bật đợt) — mặc định đợt LỚN NHẤT đã tính; chặn chọn lùi ở UI. */
  readonly dot = signal(3);

  /** 2 quyền demo (m01.md): thiếu tiền lương → che Khối 4 + thẻ Quỹ lương/Phải đóng + tiền Khối 7
   *  (che tiền VẪN hiện số lượng); thiếu hồ sơ chế độ → đếm vào tổng, ẩn chi tiết. Mọi che → ghi log (demo: note). */
  readonly quyenTienLuong = signal(true);
  readonly quyenCheDo = signal(true);

  readonly kyObj = computed(() => insKy(this.ky()));
  readonly kyLocked = computed(() => insKyDaKhoa(this.ky()));
  /** Kỳ liền trước (so sánh kỳ trước ở KPI). */
  readonly kyTruoc = computed(() => (this.ky() === 'k08' ? 'k07' : this.ky() === 'k07' ? 'k06' : null));

  readonly capNhatLuc = `${M02_TODAY} 07:45`; // thời điểm tổng hợp gần nhất (chuỗi sẵn — zoneless)

  /** Che tiền theo quyền — '●●●' (số lượng vẫn hiện ở nơi gọi). */
  tien(s: string): string { return this.quyenTienLuong() ? s : '●●●'; }

  /* ── panel trượt CHỈ ĐỌC dùng chung ── */
  readonly peekOpen = signal(false);
  readonly peek = signal<M01Peek | null>(null);

  moPeek(p: M01Peek): void {
    this.peek.set(p);
    this.peekOpen.set(true);
  }

  /** Điều hướng chéo module — LUÔN mang {ky, donVi, filter}; đích không reset (navigation contract). */
  go(module: InsModuleKey, filter?: string): void {
    const ctx: InsNavContext = { ky: this.ky(), donVi: this.donVi() };
    if (filter) ctx.filter = filter;
    this.shell.go(module, ctx);
  }
}

/** dd/MM/yyyy → số ngày (derive cục bộ M01 — deterministic, không Date.now). */
export function m01DayNum(d: string): number {
  const [dd, mm, yy] = d.split('/').map(Number);
  return Date.UTC(yy, mm - 1, dd) / 86400000;
}
/** Tuổi (ngày) từ mốc `tu` đến hôm nay demo 19/08/2026. */
export function m01TuoiNgay(tu: string): number { return m01DayNum(M02_TODAY) - m01DayNum(tu); }
