import { ChangeDetectionStrategy, Component, computed, inject, input, signal } from '@angular/core';
import {
  IconCalendarTime, IconCircleCheck, IconClock, IconCoin, IconFileCheck, IconFileText,
  IconHeartHandshake, IconSend, IconSparkles, IconUser, TablerIconComponent,
} from '@tabler/icons-angular';
import { HrmAlert, HrmAvatar, HrmButton, HrmMessageService, HrmSteps, HrmTag, type HrmStepItem } from 'hrm-ui';
import type { InsTone } from '../../../_data/_core';
import { InsDiff, InsSlaChip } from '../../../_shared';
import {
  M06_TONE_VAR,
  type M06Profile360, type M06Risk, type M06SourceStatus,
} from '../_m06-360-data';

/* ═════════ MAP tĩnh (module-load, deterministic — zoneless-safe) ═════════ */

/** iconKey nguồn dữ liệu → Tabler icon. */
function sourceIconOf(k: M06Profile360['sources'][number]['iconKey']) {
  switch (k) {
    case 'employee': return IconUser;
    case 'contract': return IconFileText;
    case 'payroll': return IconCoin;
    case 'decision': return IconFileCheck;
    case 'attendance': return IconCalendarTime;
    case 'declaration': return IconSend;
    case 'benefit': return IconHeartHandshake;
    default: return IconFileText;
  }
}

/** Trạng thái nguồn → nhãn thân thuộc + tone (§17,44-45). */
const SOURCE_STATUS: Record<M06SourceStatus, { label: string; tone: InsTone }> = {
  synced: { label: 'Đồng bộ', tone: 'success' },
  verified: { label: 'Đã xác minh', tone: 'info' },
  syncing: { label: 'Đang đồng bộ...', tone: 'warning' },
  conflict: { label: 'Xung đột', tone: 'error' },
  missing: { label: 'Thiếu dữ liệu', tone: 'error' },
};

/** Mức rủi ro → nhãn + màu tag (§21,47). */
const RISK_META: Record<M06Risk, { label: string; color: string }> = {
  low: { label: 'Rủi ro thấp', color: 'green' },
  medium: { label: 'Rủi ro trung bình', color: 'orange' },
  high: { label: 'Rủi ro cao', color: 'red' },
};

/** Thanh màu mảnh trước tên khoản (nicety khớp ảnh). */
const CONTRIB_BAR: Record<string, string> = {
  BHXH: '--info-base', BHYT: '--success-base', BHTN: '--warning-base',
};

/** ═════════ M06 · TAB "Thông tin BHXH & KCB" (mặc định, quan trọng nhất) ═════════
 *  §12 layout 2 cột (7fr/3fr) + timeline full-width. Mental model: Current state (tham gia + cơ cấu
 *  đóng) → Việc cần xử lý (biến động chờ) → Evidence (nguồn dữ liệu, độ tin cậy) → History (timeline).
 *  Prototype: mọi CTA → HrmMessageService.info('… (demo)'); KHÔNG wire nav chéo module. */
@Component({
  selector: 'ins-m06-360-bhxh',
  imports: [TablerIconComponent, HrmAlert, HrmAvatar, HrmButton, HrmSteps, HrmTag, InsDiff, InsSlaChip],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="bh-grid">
      <!-- ═════ CỘT TRÁI (7fr) ═════ -->
      <div class="bh-col">
        <!-- A · Thông tin tham gia bảo hiểm -->
        <section class="bh-card">
          <h3 class="bh-card__title">Thông tin tham gia bảo hiểm</h3>
          <div class="bh-two">
            <div class="bh-kvs">
              @for (kv of parKv(); track kv.k) {
                <div class="bh-kv">
                  <span class="bh-kv__k">{{ kv.k }}</span>
                  <span class="bh-kv__v">{{ kv.v }}</span>
                </div>
              }
            </div>
            <div class="bh-sts">
              @for (s of loaiBH(); track s.key) {
                <div class="bh-st">
                  <span class="bh-st__k">{{ s.key }}</span>
                  <span class="bh-dot" [style.background]="s.dotVar"></span>
                  <span class="bh-st__v">{{ s.label }}</span>
                </div>
              }
            </div>
          </div>
        </section>

        <!-- B · Cơ cấu mức đóng hiện tại -->
        <section class="bh-card">
          <h3 class="bh-card__title">Cơ cấu mức đóng hiện tại</h3>
          <div class="bh-tblwrap">
            <div class="bh-tbl">
              <div class="bh-tbl__h bh-tbl__c--name">Khoản</div>
              <div class="bh-tbl__h bh-num">Tổng tỷ lệ</div>
              <div class="bh-tbl__h bh-num">NLĐ đóng</div>
              <div class="bh-tbl__h bh-num">DN đóng</div>
              <div class="bh-tbl__h bh-num">Số tiền NLĐ đóng</div>
              <div class="bh-tbl__h bh-num">Số tiền DN đóng</div>
              @for (c of cVms(); track c.type) {
                <div class="bh-tbl__c bh-tbl__c--name">
                  <span class="bh-bar" [style.background]="c.barVar"></span>{{ c.type }}
                </div>
                <div class="bh-tbl__c bh-num">{{ c.totalRate }}</div>
                <div class="bh-tbl__c bh-num">{{ c.employeeRate }}</div>
                <div class="bh-tbl__c bh-num">{{ c.employerRate }}</div>
                <div class="bh-tbl__c bh-num bh-strong">{{ c.employeeAmount }} đ</div>
                <div class="bh-tbl__c bh-num bh-strong">{{ c.employerAmount }} đ</div>
              }
            </div>
          </div>
          <div class="bh-total">
            <span class="bh-total__k">Tổng dự kiến tháng:</span>
            <span class="bh-total__v">{{ profile().contribTotal }} đ</span>
          </div>
        </section>

        <!-- C · Biến động đang chờ xử lý (§21) -->
        @if (primaryMv(); as mv) {
          <div class="bh-ai-outer">
            <section class="bh-ai">
              <img class="bh-ai__mascot" src="/assets/ins-mascot-2.png" alt="" aria-hidden="true" />
              <div class="bh-ai__head">
                <tabler-icon [icon]="icSpark" [size]="16" class="bh-ai__spark" />
                <b>Biến động đang chờ xử lý</b>
              </div>
              <div class="bh-ai__body">
                <div class="bh-ai__heading">{{ mv.type }}</div>
                <p class="bh-ai__desc">{{ mv.summary }}</p>
                <ins-diff [before]="mv.oldValue + ' đ'" [after]="mv.newValue + ' đ'" label="Lương đóng BHXH" />
                <div class="bh-ai__eff">Hiệu lực {{ mv.effectiveDate }}</div>
                <div class="bh-ai__chips">
                  @if (mv.aiSuggested) { <hrm-tag color="purple" size="sm">✨ AI đề xuất</hrm-tag> }
                  <hrm-tag color="blue" size="sm">Độ tin cậy {{ mv.confidencePct }}</hrm-tag>
                  <hrm-tag [color]="riskColor(mv.risk)" size="sm">{{ riskLabel(mv.risk) }}</hrm-tag>
                </div>
                <div class="bh-ai__cta">
                  <hrm-button size="sm" variant="primary" (click)="deep('Xem tác động biến động')">Xem tác động ›</hrm-button>
                  <button type="button" class="bh-lnk" (click)="deep('Xem bằng chứng biến động')">Xem bằng chứng</button>
                  @if (lineageVms().length) {
                    <button type="button" class="bh-lnk" (click)="showLineage.set(!showLineage())">Xem căn cứ</button>
                  }
                </div>
                <!-- §6 Verify — chuỗi căn cứ mức đóng (QĐ lương → Compensation → Payroll → Mức đóng) -->
                @if (showLineage() && lineageVms().length) {
                  <div class="bh-lineage">
                    @for (n of lineageVms(); track n.node; let last = $last) {
                      <div class="bh-lineage__node" [class.bh-lineage__node--warn]="!n.ok">
                        <div class="bh-lineage__row">
                          <span class="bh-lineage__name">{{ n.node }}</span>
                          <span class="bh-lineage__val">{{ n.value }} đ</span>
                          @if (n.ok) {
                            <span class="bh-lineage__ok" aria-hidden="true">✓</span>
                          } @else {
                            <span class="bh-lineage__warn" aria-hidden="true">⚠</span>
                          }
                        </div>
                        @if (!n.ok && n.note) {
                          <div class="bh-lineage__note">{{ n.note }}</div>
                        }
                      </div>
                      @if (!last) { <div class="bh-lineage__arrow" aria-hidden="true">↓</div> }
                    }
                  </div>
                }
                @if (extraCount() > 0) {
                  <div class="bh-ai__more">
                    và {{ extraCount() }} biến động khác
                    <button type="button" class="bh-lnk" (click)="deep('Xem cả ' + pendingCount() + ' biến động')">Xem cả {{ pendingCount() }}</button>
                  </div>
                }
              </div>
            </section>
          </div>
        } @else {
          <section class="bh-empty">
            <tabler-icon [icon]="icCheck" [size]="18" class="bh-empty__ic" />
            <span>Không có biến động chờ xử lý</span>
          </section>
        }
      </div>

      <!-- ═════ CỘT PHẢI (3fr) ═════ -->
      <div class="bh-col">
        <!-- D · Nguồn dữ liệu & độ tin cậy (§17) -->
        <section class="bh-card">
          <h3 class="bh-card__title">Nguồn dữ liệu &amp; độ tin cậy</h3>
          <div class="bh-srcs">
            @for (s of srcVms(); track s.name) {
              <div class="bh-src">
                <span class="bh-src__ic"><tabler-icon [icon]="s.icon" [size]="16" /></span>
                <div class="bh-src__main">
                  <span class="bh-src__name">{{ s.name }}</span>
                  @if (s.conflict) {
                    <button type="button" class="bh-lnk bh-lnk--sm" (click)="deep('Xem chênh lệch nguồn ' + s.name)">Xem chênh lệch</button>
                  }
                </div>
                <div class="bh-src__meta">
                  <span class="bh-src__st">
                    <span class="bh-dot" [style.background]="s.dotVar"></span>{{ s.statusLabel }}
                  </span>
                  <span class="bh-src__time">{{ s.updated }}</span>
                </div>
              </div>
            }
          </div>
          <div class="bh-src__foot">
            <div class="bh-ring" [style.background]="ringStyle()">
              <span class="bh-ring__hole">{{ profile().dataQuality.completenessPct }}</span>
            </div>
            <span class="bh-src__complete">{{ profile().dataQuality.completenessPct }} đầy đủ</span>
            <button type="button" class="bh-lnk bh-src__evidence" (click)="deep('Xem chuỗi bằng chứng')">Xem chuỗi bằng chứng ›</button>
          </div>
          <!-- §7,22 Nhất quán giá trị — chỉ số RIÊNG với "đầy đủ" (đủ nguồn) ở trên -->
          <div class="bh-consistency">
            @if (profile().salaryConflict; as cf) {
              <div class="bh-consistency__line bh-consistency__line--warn">
                <span>⚠ Nhất quán giá trị: {{ conflictMismatchCount() }} nguồn lệch</span>
                <button type="button" class="bh-lnk" (click)="showConflict.set(!showConflict())">Xem chênh lệch</button>
              </div>
              @if (showConflict()) {
                <div class="bh-cfpanel">
                  <div class="bh-cftbl">
                    <div class="bh-cftbl__h">Nguồn</div>
                    <div class="bh-cftbl__h bh-num">Giá trị</div>
                    @for (r of cf.rows; track r.source) {
                      <div class="bh-cftbl__c">{{ r.source }}</div>
                      <div class="bh-cftbl__c bh-num" [class.bh-cftbl__c--bad]="!r.ok">
                        {{ r.value }} đ {{ r.ok ? '✓' : '⚠' }}
                      </div>
                    }
                  </div>
                  <div class="bh-cfpanel__ai">✨ {{ cf.aiNote }}</div>
                  <button type="button" class="bh-cfpanel__act" (click)="deep(cf.suggestedAction)">{{ cf.suggestedAction }}</button>
                </div>
              }
            } @else {
              <div class="bh-consistency__line bh-consistency__line--ok">
                <span>✓ Các nguồn khớp giá trị</span>
              </div>
            }
          </div>
        </section>

        <!-- E · Cảnh báo dữ liệu chưa khớp (§56) -->
        @if (profile().conflict; as cf) {
          <section class="bh-conflict">
            <hrm-alert type="warning" [banner]="true" [message]="cf.message" [description]="cf.detail" />
            <button type="button" class="bh-lnk" (click)="deep('Xem chênh lệch dữ liệu')">Xem chênh lệch ›</button>
          </section>
        }

        <!-- F · Người phụ trách (§20) -->
        <section class="bh-card">
          <h3 class="bh-card__title">Người phụ trách</h3>
          <div class="bh-owner">
            <hrm-avatar [text]="profile().owner.name" [colorful]="true" [colorSeed]="profile().owner.name" size="small" />
            <div class="bh-owner__id">
              <span class="bh-owner__name">{{ profile().owner.name }}</span>
              <span class="bh-owner__role">· {{ profile().owner.role }}</span>
            </div>
          </div>
          @if (profile().owner.slaText; as sla) {
            <div class="bh-owner__sla">
              <tabler-icon [icon]="icClock" [size]="13" />
              <ins-sla-chip [label]="sla" tone="warn" />
            </div>
          }
        </section>

        <!-- G · Dòng thời gian bảo hiểm (§25) — stepper DỌC, đặt cột phải kế card Biến động -->
        <section class="bh-card bh-timeline">
          <div class="bh-timeline__head">
            <h3 class="bh-card__title bh-card__title--flush">Dòng thời gian bảo hiểm</h3>
            <div class="bh-timeline__links">
              @if (auditVms().length) {
                <button type="button" class="bh-lnk" (click)="showAudit.set(!showAudit())">Xem lịch sử xử lý</button>
              }
              <button type="button" class="bh-lnk" (click)="deep('Xem tất cả mốc bảo hiểm')">Xem tất cả ›</button>
            </div>
          </div>
          <hrm-steps class="bh-steps" [items]="stepItems()" direction="vertical" size="small"
            status="finish" [current]="stepItems().length" [dot]="true" />
          <!-- §18 Audit trail — trace Source → Detection → AI → Decision → Result -->
          @if (showAudit() && auditVms().length) {
            <div class="bh-audit">
              <div class="bh-audit__title">Lịch sử xử lý (audit)</div>
              @for (a of auditVms(); track a.action) {
                <div class="bh-audit__row">
                  <span class="bh-dot" [style.background]="a.dotVar"></span>
                  <div class="bh-audit__main">
                    <div class="bh-audit__top">
                      <span class="bh-audit__time">{{ a.time }}</span>
                      <span class="bh-audit__actor">{{ a.actor }}</span>
                      <span class="bh-audit__action">{{ a.action }}</span>
                    </div>
                    <div class="bh-audit__detail">{{ a.detail }}</div>
                  </div>
                </div>
              }
            </div>
          }
        </section>
      </div>
    </div>
  `,
  host: { class: 'ins-m06-360-bhxh' },
  styles: [`
    :host { display: block; }

    /* §12 lưới 2 cột 7fr/3fr; ≤1000px → 1 cột. Dòng thời gian = stepper dọc trong cột phải. */
    .bh-grid {
      display: grid; grid-template-columns: minmax(0, 7fr) minmax(0, 3fr); gap: 16px; align-items: start;
    }
    @media (max-width: 1000px) { .bh-grid { grid-template-columns: 1fr; } }
    .bh-col { display: flex; flex-direction: column; gap: 16px; min-width: 0; }

    /* Card trắng — convention token DS. */
    .bh-card {
      background: var(--bg-surface); border: 1px solid var(--border-sub);
      border-radius: 12px; padding: 16px; min-width: 0;
    }
    .bh-card__title {
      margin: 0 0 12px; font-size: var(--fs-14); font-weight: 600; color: var(--text-strong);
    }
    .bh-card__title--flush { margin: 0; }
    .bh-strong { color: var(--text-strong); font-weight: 600; }

    /* Link phẳng (deep-link demo). */
    .bh-lnk {
      cursor: pointer; font: inherit; font-size: var(--fs-12); font-weight: 600; color: var(--primary-base);
      background: none; border: 0; padding: 0; text-decoration: none; white-space: nowrap;
    }
    .bh-lnk:hover { text-decoration: underline; }
    .bh-lnk--sm { font-size: var(--fs-11); font-weight: 500; }

    /* Chấm tròn tone. */
    .bh-dot { width: 8px; height: 8px; border-radius: 50%; flex: none; display: inline-block; }

    /* ── A · 2 cụm ngang ── */
    .bh-two { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
    @media (max-width: 560px) { .bh-two { grid-template-columns: 1fr; } }
    .bh-kvs { display: flex; flex-direction: column; gap: 12px; min-width: 0; }
    .bh-kv { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
    .bh-kv__k { font-size: var(--fs-12); color: var(--text-sub); }
    .bh-kv__v { font-size: var(--fs-14); font-weight: 500; color: var(--text-strong); }
    .bh-sts { display: flex; flex-direction: column; gap: 12px; }
    .bh-st { display: flex; align-items: center; gap: 8px; }
    .bh-st__k { font-size: var(--fs-13); font-weight: 600; color: var(--text-strong); min-width: 48px; }
    .bh-st__v { font-size: var(--fs-13); color: var(--text-sub); }

    /* ── B · bảng cơ cấu đóng (grid 6 cột) ── */
    .bh-tblwrap { overflow-x: auto; }
    .bh-tbl {
      display: grid; grid-template-columns: 1.4fr .9fr .9fr .9fr 1.15fr 1.15fr;
      min-width: 480px; align-items: center;
    }
    .bh-tbl__h {
      font-size: var(--fs-12); color: var(--text-sub); font-weight: 500;
      padding: 0 8px 8px; border-bottom: 1px solid var(--border-sub);
    }
    .bh-tbl__c {
      font-size: var(--fs-13); color: var(--text-strong); padding: 9px 8px;
      border-bottom: 1px solid var(--border-soft);
    }
    .bh-tbl > .bh-tbl__c:nth-last-child(-n+6) { border-bottom: 0; }
    .bh-tbl__c--name { display: flex; align-items: center; gap: 8px; font-weight: 600; }
    .bh-bar { width: 3px; height: 14px; border-radius: var(--radius-full); flex: none; display: inline-block; }
    .bh-num { text-align: right; justify-self: end; font-variant-numeric: tabular-nums; }

    /* Footer bar tổng dự kiến — nền tint primary. */
    .bh-total {
      display: flex; align-items: center; justify-content: space-between; gap: 12px;
      margin-top: 12px; padding: 10px 12px; border-radius: var(--radius-md);
      background: var(--primary-bg-subtle);
    }
    .bh-total__k { font-size: var(--fs-13); color: var(--text-sub); }
    .bh-total__v { font-size: var(--fs-15, 15px); font-weight: 700; color: var(--text-strong); font-variant-numeric: tabular-nums; }

    /* ── C · card muối/gradient AI ── */
    .bh-empty {
      display: flex; align-items: center; gap: 8px; padding: 12px 16px;
      background: var(--bg-surface); border: 1px dashed var(--border-sub); border-radius: 12px;
      font-size: var(--fs-13); color: var(--text-sub);
    }
    .bh-empty__ic { color: var(--success-base); flex: none; }

    /* Wrapper nâng cụm nổi + chừa chỗ đầu mascot; card gradient AI CHE thân mascot chồng lên. */
    .bh-ai-outer { position: relative; z-index: 1; overflow: visible; }
    .bh-ai {
      position: relative; z-index: 1; overflow: visible; padding: 8px;
      /* Gradient AI brand — hex sáng cố định (ngoại lệ được phép, dùng NGUYÊN màu chatbot). */
      background: linear-gradient(180deg, #E7F0FE 0%, #EDEAFB 48%, #FCE8DC 100%);
      border: 1px solid #DBD3F5; border-radius: 12px;
    }
    .bh-ai__mascot { position: absolute; top: -12px; right: 20px; z-index: 1; width: 104px; height: auto; pointer-events: none; }
    .bh-ai__head {
      position: relative; z-index: 3; display: flex; align-items: center; gap: 7px;
      padding: 2px 2px 8px 4px; font-size: var(--fs-13); color: #1E2A5A;
    }
    .bh-ai__head b { font-weight: 700; }
    .bh-ai__spark { color: #6C4FE0; flex: none; }
    /* Hộp nền trắng bọc nội dung — token surface (đọc được cả 2 theme). */
    .bh-ai__body {
      position: relative; z-index: 3; display: flex; flex-direction: column; gap: 8px;
      background: var(--bg-surface); border-radius: 10px; padding: 12px 14px;
    }
    .bh-ai__heading { font-size: var(--fs-14); font-weight: 700; color: var(--text-strong); }
    .bh-ai__desc { margin: 0; font-size: var(--fs-13); color: var(--text-body); line-height: 1.45; }
    .bh-ai__eff { font-size: var(--fs-12); color: var(--text-sub); }
    .bh-ai__chips { display: flex; align-items: center; flex-wrap: wrap; gap: 6px; }
    .bh-ai__cta { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; margin-top: 2px; }
    .bh-ai__more { font-size: var(--fs-12); color: var(--text-sub); display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }

    /* ── D · nguồn dữ liệu ── */
    .bh-srcs { display: flex; flex-direction: column; gap: 10px; }
    .bh-src { display: flex; align-items: center; gap: 10px; min-width: 0; }
    .bh-src__ic {
      display: inline-flex; align-items: center; justify-content: center; width: 28px; height: 28px; flex: none;
      border-radius: var(--radius-md); background: var(--bg-surface-subtle); color: var(--text-sub);
    }
    .bh-src__main { display: flex; flex-direction: column; gap: 1px; min-width: 0; flex: 1 1 auto; }
    .bh-src__name { font-size: var(--fs-13); font-weight: 500; color: var(--text-strong); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    .bh-src__meta { display: flex; flex-direction: column; align-items: flex-end; gap: 1px; flex: none; }
    .bh-src__st { display: inline-flex; align-items: center; gap: 5px; font-size: var(--fs-12); color: var(--text-sub); white-space: nowrap; }
    .bh-src__time { font-size: var(--fs-11); color: var(--text-soft); }
    .bh-src__foot {
      display: flex; align-items: center; gap: 10px; flex-wrap: wrap;
      margin-top: 14px; padding-top: 14px; border-top: 1px solid var(--border-sub);
    }
    .bh-ring { width: 46px; height: 46px; border-radius: 50%; display: grid; place-items: center; flex: none; }
    .bh-ring__hole {
      width: 34px; height: 34px; border-radius: 50%; background: var(--bg-surface); display: grid; place-items: center;
      font-size: var(--fs-11); font-weight: 700; color: var(--text-strong);
    }
    .bh-src__complete { font-size: var(--fs-13); font-weight: 500; color: var(--text-strong); }
    .bh-src__evidence { margin-left: auto; }

    /* ── E · conflict ── */
    .bh-conflict { display: flex; flex-direction: column; gap: 8px; align-items: flex-start; }
    .bh-conflict hrm-alert { display: block; width: 100%; }

    /* ── F · người phụ trách ── */
    .bh-owner { display: flex; align-items: center; gap: 10px; }
    .bh-owner__id { display: flex; align-items: baseline; gap: 6px; flex-wrap: wrap; min-width: 0; }
    .bh-owner__name { font-size: var(--fs-14); font-weight: 600; color: var(--text-strong); }
    .bh-owner__role { font-size: var(--fs-13); color: var(--text-sub); }
    .bh-owner__sla { display: flex; align-items: center; gap: 6px; margin-top: 12px; color: var(--warning-text); }

    /* ── G · Dòng thời gian bảo hiểm — stepper DỌC (hrm-steps) ── */
    .bh-timeline__head { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 14px; }
    .bh-steps { display: block; }
    /* nz-steps dọc: siết cỡ chữ theo token DS — title đậm + description phụ (thay đổi · nguồn). */
    .bh-steps ::ng-deep .ant-steps-item-title { font-size: var(--fs-13); font-weight: 600; color: var(--text-strong); line-height: 1.4; }
    .bh-steps ::ng-deep .ant-steps-item-description { font-size: var(--fs-12); color: var(--text-sub); font-variant-numeric: tabular-nums; padding-bottom: 12px; }
    .bh-steps ::ng-deep .ant-steps-item:last-child .ant-steps-item-description { padding-bottom: 0; }
    .bh-steps ::ng-deep .ant-steps-item-tail::after { background: var(--border-sub); }

    /* ── §6 Verify — chuỗi căn cứ (lineage) dọc, nối mũi tên ↓ ── */
    .bh-lineage {
      display: flex; flex-direction: column; margin-top: 4px; padding: 10px 12px;
      background: var(--bg-canvas); border-radius: var(--radius-md);
    }
    .bh-lineage__node {
      padding: 6px 8px; border-radius: var(--radius-sm, 6px);
      border: 1px solid var(--border-soft); background: var(--bg-surface);
    }
    .bh-lineage__node--warn { border-color: var(--warning-base); }
    .bh-lineage__row { display: flex; align-items: center; gap: 8px; }
    .bh-lineage__name { font-size: var(--fs-13); font-weight: 600; color: var(--text-strong); flex: 1 1 auto; min-width: 0; }
    .bh-lineage__val { font-size: var(--fs-13); color: var(--text-sub); font-variant-numeric: tabular-nums; }
    .bh-lineage__ok { color: var(--success-base); font-size: var(--fs-13); flex: none; }
    .bh-lineage__warn { color: var(--warning-base); font-size: var(--fs-13); flex: none; }
    .bh-lineage__note { margin-top: 3px; font-size: var(--fs-12); color: var(--warning-text, var(--warning-base)); }
    .bh-lineage__arrow { text-align: center; font-size: var(--fs-13); color: var(--text-soft); line-height: 1.1; padding: 1px 0; }

    /* ── §7,22 Nhất quán giá trị (tách khỏi completeness) ── */
    .bh-consistency { margin-top: 10px; }
    .bh-consistency__line { display: flex; align-items: center; justify-content: space-between; gap: 10px; font-size: var(--fs-12); }
    .bh-consistency__line--warn { color: var(--warning-text, var(--warning-base)); }
    .bh-consistency__line--ok { color: var(--success-base); }
    .bh-cfpanel {
      margin-top: 8px; padding: 10px 12px; background: var(--bg-canvas);
      border-radius: var(--radius-md); display: flex; flex-direction: column; gap: 8px;
    }
    .bh-cftbl { display: grid; grid-template-columns: 1fr auto; gap: 5px 12px; align-items: center; }
    .bh-cftbl__h { font-size: var(--fs-12); color: var(--text-sub); font-weight: 500; padding-bottom: 3px; border-bottom: 1px solid var(--border-sub); }
    .bh-cftbl__c { font-size: var(--fs-13); color: var(--text-strong); }
    .bh-cftbl__c--bad { color: var(--error-base); }
    .bh-cfpanel__ai { font-size: var(--fs-12); color: var(--text-body); line-height: 1.45; }
    .bh-cfpanel__act {
      align-self: flex-start; cursor: pointer; font: inherit; font-size: var(--fs-12); font-weight: 600;
      color: var(--primary-base); background: var(--bg-surface);
      border: 1px solid var(--border-sub); border-radius: var(--radius-md); padding: 4px 10px;
    }
    .bh-cfpanel__act:hover { border-color: var(--primary-base); }

    /* ── §18 Audit trail (Xem lịch sử xử lý) ── */
    .bh-timeline__links { display: flex; align-items: center; gap: 12px; }
    .bh-audit {
      margin-top: 12px; padding: 12px; background: var(--bg-canvas);
      border-radius: var(--radius-md); display: flex; flex-direction: column; gap: 10px;
    }
    .bh-audit__title { font-size: var(--fs-12); font-weight: 600; color: var(--text-sub); }
    .bh-audit__row { display: flex; gap: 8px; align-items: flex-start; }
    .bh-audit__row .bh-dot { margin-top: 5px; }
    .bh-audit__main { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
    .bh-audit__top { display: flex; align-items: baseline; gap: 6px; flex-wrap: wrap; }
    .bh-audit__time { font-size: var(--fs-12); color: var(--text-sub); font-variant-numeric: tabular-nums; font-family: var(--font-mono, ui-monospace, monospace); }
    .bh-audit__actor { font-size: var(--fs-13); font-weight: 700; color: var(--text-strong); }
    .bh-audit__action { font-size: var(--fs-13); color: var(--text-body); }
    .bh-audit__detail { font-size: var(--fs-12); color: var(--text-sub); line-height: 1.4; }
  `],
})
export class InsM06Tab360Bhxh {
  readonly profile = input.required<M06Profile360>();

  private readonly msg = inject(HrmMessageService);

  protected readonly icSpark = IconSparkles;
  protected readonly icClock = IconClock;
  protected readonly icCheck = IconCircleCheck;

  /* ── Panel toggles (signal — zoneless, KHÔNG modal service) ── */
  protected readonly showLineage = signal(false);   // §6 Verify — chuỗi căn cứ
  protected readonly showConflict = signal(false);  // §22 Verify — chênh lệch nguồn
  protected readonly showAudit = signal(false);     // §18 Audit — lịch sử xử lý

  /* ── A · tham gia ── */
  protected readonly parKv = computed(() => {
    const p = this.profile().participation;
    return [
      { k: 'Cơ quan BHXH', v: p.agencyName },
      { k: 'Ngày tham gia tại đơn vị', v: p.joinDate },
      { k: 'Đối tượng', v: p.subjectType },
    ];
  });
  protected readonly loaiBH = computed(() => {
    const p = this.profile().participation;
    return [
      { key: 'BHXH', label: p.bhxh.label, dotVar: 'var(' + M06_TONE_VAR[p.bhxh.tone] + ')' },
      { key: 'BHYT', label: p.bhyt.label, dotVar: 'var(' + M06_TONE_VAR[p.bhyt.tone] + ')' },
      { key: 'BHTN', label: p.bhtn.label, dotVar: 'var(' + M06_TONE_VAR[p.bhtn.tone] + ')' },
    ];
  });

  /* ── B · cơ cấu đóng ── */
  protected readonly cVms = computed(() => this.profile().contrib.map((c) => ({
    ...c,
    barVar: 'var(' + (CONTRIB_BAR[c.type] ?? '--text-sub') + ')',
  })));

  /* ── C · biến động chờ ── */
  protected readonly primaryMv = computed(() => this.profile().pendingMovements[0] ?? null);
  protected readonly pendingCount = computed(() => this.profile().pendingMovements.length);
  protected readonly extraCount = computed(() => Math.max(0, this.profile().pendingMovements.length - 1));
  protected riskLabel(r: M06Risk): string { return RISK_META[r].label; }
  protected riskColor(r: M06Risk): string { return RISK_META[r].color; }

  /* ── §6 Verify — chuỗi căn cứ mức đóng (node !ok = màu warning) ── */
  protected readonly lineageVms = computed(() => this.profile().salaryLineage);

  /* ── §22 Verify — số nguồn lệch giá trị (tách khỏi "đầy đủ") ── */
  protected readonly conflictMismatchCount = computed(() => {
    const cf = this.profile().salaryConflict;
    return cf ? cf.rows.filter((r) => !r.ok).length : 0;
  });

  /* ── §18 Audit — hàng lịch sử xử lý + chấm tone ── */
  protected readonly auditVms = computed(() => this.profile().auditTrail.map((a) => ({
    ...a,
    dotVar: 'var(' + M06_TONE_VAR[a.tone] + ')',
  })));

  /* ── D · nguồn dữ liệu ── */
  protected readonly srcVms = computed(() => this.profile().sources.map((s) => {
    const m = SOURCE_STATUS[s.status];
    return {
      name: s.name,
      icon: sourceIconOf(s.iconKey),
      statusLabel: m.label,
      dotVar: 'var(' + M06_TONE_VAR[m.tone] + ')',
      updated: s.updated,
      conflict: s.status === 'conflict',
    };
  }));
  /** Vòng tròn % đầy đủ — parse số từ chuỗi (deterministic, module/computed thuần). */
  protected readonly ringStyle = computed(() => {
    const n = parseInt(this.profile().dataQuality.completenessPct, 10) || 0;
    return `conic-gradient(var(--success-base) ${n * 3.6}deg, var(--border-sub) 0deg)`;
  });

  /* ── G · timeline → HrmSteps items (stepper DỌC). title = ngày · sự kiện; description = thay đổi · nguồn. */
  protected readonly stepItems = computed<HrmStepItem[]>(() => this.profile().timeline.map((e) => ({
    title: `${e.date} · ${e.title}`,
    // §17 nối trạng thái mốc (Chờ xác nhận / Đã giải quyết) vào cuối description.
    description: [e.valueChange, `Nguồn: ${e.source}`, e.statusLabel].filter(Boolean).join(' · '),
  })));

  /** Deep-link prototype — mọi CTA chỉ toast demo, KHÔNG nav chéo module. */
  protected deep(label: string): void {
    this.msg.info(`${label} (demo)`);
  }
}
