import { ChangeDetectionStrategy, Component, TemplateRef, computed, inject, input, signal, viewChild } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { IconSearch } from '@tabler/icons-angular';
import {
  HrmButton, HrmDetailPeek, HrmEmpty, HrmGrid, HrmGridColumn, HrmInput, HrmMessageService,
  HrmPeekMode, HrmProgress, HrmSelect, HrmTag,
} from 'hrm-ui';
import { INS_DON_VI, INS_KY } from '../../_data/_core';
import { InsM02Store } from '../../_data/_m02-data';
import { InsM04Store } from '../../_data/_m04-data';
import { InsM05Store } from '../../_data/_m05-data';
import { InsM06Store } from '../../_data/_m06-data';
import { InsM08Store } from '../../_data/_m08-data';
import {
  InsM07ReportItem, InsM07Store, M07_BIEU_MAU, M07_PHAM_VI, M07_REPORT_GROUPS, M07_TEP_LABEL, M07_TEP_TONE,
} from '../../_data/_m07-data';
import { M07KetQua, m07BuildKetQua } from './_m07-report-build';
import { InsM07KiemTra } from './m07-kiemtra';
import { InsM07AuditTab } from './m07-audit-tab';

/** ═════════ M07-B — TRUNG TÂM BÁO CÁO (archetype Report Explorer, Phase D5) ═════════
 *  IA_LOCK m07.md: TRÁI = catalog ĐÚNG 9 NHÓM (search mục · lọc theo quyền — không quyền = ẨN ·
 *  mục chưa sẵn sàng = MỜ kèm lý do); PHẢI = Tham số → Kết quả → Xuất tệp; panel chi tiết dòng = CHỈ ĐỌC.
 *  KHÔNG nút nghiệp vụ nào ngoài chạy báo cáo + xuất. Báo cáo mới = mục con, không màn mới.
 *  Kỳ/đơn vị GIỮ NGỮ CẢNH giữa các mục; phạm vi hợp nhất 3 mức theo quyền; vượt ngưỡng → chạy nền
 *  có tiến độ; xuất = biểu mẫu + phiên bản theo ngày hiệu lực + 3 CHỐT CHẶN; vòng đời tệp
 *  Đang tạo → Sẵn sàng tải → Hết hạn; TẢI LẠI CŨNG GHI 1 DÒNG NHẬT KÝ. */
@Component({
  selector: 'ins-m07-reports',
  imports: [
    FormsModule,
    HrmButton, HrmDetailPeek, HrmEmpty, HrmGrid, HrmInput, HrmProgress, HrmSelect, HrmTag,
    InsM07KiemTra, InsM07AuditTab,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="rp">
      <!-- ═══ TRÁI: catalog 9 nhóm ═══ -->
      <aside class="rp-cat">
        <hrm-input [(ngModel)]="kwModel" size="sm" [prefixIcon]="icSearch" [clearable]="true" placeholder="Tìm mục báo cáo…" />
        @for (g of groups(); track g.key) {
          <div class="rp-group">
            <div class="rp-group__head">{{ g.label }} <span class="rp-group__count">{{ g.items.length }}</span></div>
            @for (it of g.items; track it.key) {
              <button type="button" class="rp-item" [class.rp-item--on]="it.key === selKey()"
                [class.rp-item--off]="!it.sanSang" [disabled]="!it.sanSang" (click)="chonMuc(it)">
                <span class="rp-item__label">{{ it.label }}</span>
                @if (!it.sanSang) { <span class="rp-item__why">chưa sẵn sàng — {{ it.lyDoChuaSanSang }}</span> }
              </button>
            }
          </div>
        }
        <p class="rp-cat__note">1 nhóm ẩn theo quyền demo (Quỹ lương) — không quyền = ẩn, không phải mờ.</p>
      </aside>

      <!-- ═══ PHẢI: Tham số → Kết quả → Xuất ═══ -->
      <section class="rp-work">
        @if (!selItem()) {
          <div class="rp-empty"><hrm-empty preset="first-use" description="Chọn 1 mục báo cáo ở catalog bên trái — khung Tham số → Kết quả → Xuất tệp dùng chung mọi mục." /></div>
        } @else if (selItem(); as it) {
          <header class="rp-work__head">
            <h3 class="rp-title">{{ it.label }}</h3>
            <span class="rp-muted">{{ it.moTa }}</span>
          </header>

          @if (it.key === 'tt-kiem-tra-66') {
            <ins-m07-kiemtra />
          } @else if (nhatKyMode()) {
            <ins-m07-audit-tab [mode]="it.key" />
          } @else {
            <!-- Tham số (kỳ + đơn vị giữ ngữ cảnh chung giữa các mục) -->
            <div class="rp-params">
              <hrm-select class="rp-params__sel" [(ngModel)]="kyModel" [options]="kyOptions" size="sm" [allowClear]="false" [showSearch]="false" />
              <hrm-select class="rp-params__sel rp-params__sel--dv" [(ngModel)]="donViModel" [options]="donViOptions" size="sm" [allowClear]="false" [showSearch]="false" />
              <hrm-select class="rp-params__sel rp-params__sel--pv" [(ngModel)]="phamViModel" [options]="phamViOptions" size="sm" [allowClear]="false" [showSearch]="false" />
              @if (it.thamSoRieng; as ts) {
                <hrm-select class="rp-params__sel" [(ngModel)]="thamSoModel" [options]="thamSoOptions()" size="sm"
                  [placeholder]="ts.label + (ts.batBuoc ? ' (bắt buộc)' : '')" [allowClear]="false" [showSearch]="false" />
              }
              <hrm-button size="sm" variant="primary" [disabled]="!!runDisabledReason() || dangChay()" (click)="chay()">
                {{ it.chayNen ? 'Chạy báo cáo (nền)' : 'Chạy báo cáo' }}</hrm-button>
              @if (runDisabledReason(); as r) { <span class="rp-guard">{{ r }}</span> }
            </div>
            @if (dangChay()) {
              <div class="rp-bg">
                <span class="rp-muted">Vượt ngưỡng (M08) → chạy nền có tiến độ…</span>
                <hrm-progress [percent]="tienDo()" [status]="tienDo() < 100 ? 'active' : 'success'" />
              </div>
            }

            <!-- Kết quả (dòng tổng theo đơn vị + toàn phạm vi; panel dòng CHỈ ĐỌC) -->
            @if (ketQua(); as kq) {
              <div class="rp-kq">
                <div class="rp-kq__meta">
                  <hrm-tag size="sm" color="green">Hoàn tất</hrm-tag>
                  <span class="rp-muted">chạy lúc {{ ranAt() }} · {{ kq.rows.length }} dòng (gồm dòng tổng) · phạm vi: {{ phamViLabel() }}</span>
                </div>
                <hrm-grid [columns]="kqCols()" [data]="kq.rows" rowKey="c1" density="compact" [pageSize]="10"
                  [minWidth]="'900px'" (rowClick)="onRowClick($event)" />
              </div>

              <!-- Xuất tệp: biểu mẫu + phiên bản theo ngày hiệu lực · 3 chốt chặn -->
              <div class="rp-export">
                <div class="rp-export__row">
                  <hrm-select class="rp-export__sel" [(ngModel)]="bieuMauModel" [options]="bieuMauOptions" size="sm" [allowClear]="false" [showSearch]="false" />
                  <hrm-button size="sm" variant="primary" [disabled]="!!exportDisabledReason()" (click)="xuat()">Xuất tệp</hrm-button>
                  @if (exportDisabledReason(); as r) { <span class="rp-guard">{{ r }}</span> }
                </div>
                <div class="rp-choke">
                  @for (c of chokes(); track c.label) {
                    <span class="rp-choke__item" [attr.data-ok]="c.ok">{{ c.ok ? '✓' : '✗' }} {{ c.label }}</span>
                  }
                </div>
              </div>
            }
          }

          <!-- Tệp đã xuất (vòng đời) — hiện ở mọi mục -->
          <div class="rp-files">
            <div class="rp-files__head">Tệp đã xuất — vòng đời Đang tạo → Sẵn sàng tải → Hết hạn</div>
            @for (t of store.tepXuat(); track t.id) {
              <div class="rp-file">
                <span class="rp-mono">{{ t.id }}</span>
                <span class="rp-file__name">{{ t.ten }}</span>
                <span class="rp-muted">{{ t.bieuMau }} · {{ t.phienBanMau }} · {{ t.phamVi }}</span>
                <hrm-tag size="sm" [color]="tepColor(t.trangThai)">{{ tepLabel(t.trangThai) }}</hrm-tag>
                <span class="rp-muted">tạo {{ t.taoLuc }} · hết hạn {{ t.hetHanLuc }} · đã tải {{ t.soLanTai }} lần</span>
                <span class="rp-gap"></span>
                <hrm-button size="sm" (click)="tai(t.id)">Tải xuống</hrm-button>
              </div>
            } @empty { <p class="rp-muted">Chưa có tệp xuất nào.</p> }
            <p class="rp-note">Tải lại tệp CŨNG ghi 1 dòng nhật ký (nhóm Nhật ký kiểm toán · mục Nhật ký xuất tệp).</p>
          </div>
        }
      </section>

      <!-- Panel dòng kết quả — CHỈ ĐỌC -->
      <hrm-detail-peek [(open)]="peekOpenModel" [peekMode]="'side'" [modes]="peekModes" [expandable]="false"
        title="Chi tiết dòng (chỉ đọc)" [content]="rowPeekTpl" [width]="380" closeLabel="Đóng" resizeLabel="Kéo đổi độ rộng" />
    </div>

    <ng-template #c1Tpl let-row>
      <span [class.rp-tong]="$any(row).tong">{{ $any(row).c1 }}</span>
    </ng-template>

    <ng-template #rowPeekTpl>
      @if (peekRow(); as row) {
        <div class="rp-peek">
          @for (c of ketQua()?.cols ?? []; track c.key) {
            <div class="rp-peek__kv"><span>{{ c.title }}</span><b>{{ row[c.key] ?? '—' }}</b></div>
          }
          <p class="rp-note">Chế độ đọc — KHÔNG nút nghiệp vụ tại Trung tâm báo cáo (chỉ chạy + xuất).</p>
        </div>
      }
    </ng-template>
  `,
  host: { class: 'ins-m07-reports' },
  styles: [`
    :host { display: flex; flex-direction: column; flex: 1 1 auto; min-height: 0; }
    .rp { flex: 1 1 auto; min-height: 0; display: flex; gap: 14px; padding: 12px 20px; }

    .rp-cat { flex: none; width: 290px; overflow: auto; display: flex; flex-direction: column; gap: 10px; }
    .rp-group { display: flex; flex-direction: column; gap: 2px; }
    .rp-group__head {
      display: flex; align-items: center; gap: 6px; padding: 4px 2px;
      font-size: var(--fs-11); font-weight: 700; text-transform: uppercase; letter-spacing: .04em; color: var(--text-sub);
    }
    .rp-group__count { font-weight: 600; color: var(--text-soft); background: var(--bg-surface-subtle); border-radius: var(--radius-full); padding: 0 6px; }
    .rp-item {
      display: flex; flex-direction: column; align-items: flex-start; gap: 2px; text-align: left;
      border: 0; background: none; cursor: pointer; font: inherit; padding: 5px 8px; border-radius: var(--radius-sm);
    }
    .rp-item:hover { background: var(--bg-surface-subtle); }
    .rp-item--on { background: var(--primary-bg, var(--bg-surface-subtle)); }
    .rp-item--on .rp-item__label { color: var(--primary-base); font-weight: 600; }
    .rp-item--off { cursor: not-allowed; opacity: .55; }
    .rp-item__label { font-size: var(--fs-13); color: var(--text-body); }
    .rp-item__why { font-size: var(--fs-11); color: var(--text-soft); }
    .rp-cat__note { margin: 0; font-size: var(--fs-11); color: var(--text-soft); }

    .rp-work { flex: 1 1 auto; min-width: 0; overflow: auto; display: flex; flex-direction: column; gap: 12px; }
    .rp-empty { padding: 60px 0; display: flex; justify-content: center; }
    .rp-work__head { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; }
    .rp-title { margin: 0; font-size: var(--fs-14); font-weight: 600; color: var(--text-strong); }
    .rp-muted { font-size: var(--fs-12); color: var(--text-sub); }
    .rp-note { margin: 0; font-size: var(--fs-11); color: var(--text-soft); }
    .rp-guard { font-size: var(--fs-12); color: var(--error-text); }

    .rp-params { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
    .rp-params__sel { width: 170px; }
    .rp-params__sel--dv { width: 280px; }
    .rp-params__sel--pv { width: 240px; }
    .rp-bg { display: flex; flex-direction: column; gap: 4px; max-width: 420px; }

    .rp-kq { display: flex; flex-direction: column; gap: 6px; }
    .rp-kq__meta { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
    .rp-tong { font-weight: 700; color: var(--text-strong); }

    .rp-export { display: flex; flex-direction: column; gap: 6px; border: 1px dashed var(--border-sub); border-radius: var(--radius-md); padding: 10px 12px; }
    .rp-export__row { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
    .rp-export__sel { width: 420px; }
    .rp-choke { display: flex; align-items: center; gap: 14px; flex-wrap: wrap; }
    .rp-choke__item { font-size: var(--fs-12); font-weight: 500; }
    .rp-choke__item[data-ok='true'] { color: var(--success-text); }
    .rp-choke__item[data-ok='false'] { color: var(--error-text); }

    .rp-files { display: flex; flex-direction: column; gap: 6px; }
    .rp-files__head { font-size: var(--fs-12); font-weight: 700; text-transform: uppercase; letter-spacing: .04em; color: var(--text-sub); }
    .rp-file { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; border: 1px solid var(--border-sub); border-radius: var(--radius-md); background: var(--bg-surface); padding: 7px 12px; font-size: var(--fs-12); }
    .rp-file__name { font-weight: 600; color: var(--text-strong); }
    .rp-mono { font-family: var(--font-mono, monospace); font-size: var(--fs-12); font-weight: 600; color: var(--text-strong); }
    .rp-gap { flex: 1; }

    .rp-peek { display: flex; flex-direction: column; gap: 8px; }
    .rp-peek__kv { display: flex; flex-direction: column; gap: 1px; font-size: var(--fs-12); }
    .rp-peek__kv span { color: var(--text-sub); }
    .rp-peek__kv b { color: var(--text-strong); font-weight: 600; }
  `],
})
export class InsM07Reports {
  protected readonly store = inject(InsM07Store);
  private readonly m02 = inject(InsM02Store);
  private readonly m04 = inject(InsM04Store);
  private readonly m05 = inject(InsM05Store);
  private readonly m06 = inject(InsM06Store);
  /** BQA-22: nguồn bảng ánh xạ mã cũ ↔ mã mới (chỉ đọc). */
  private readonly m08 = inject(InsM08Store);
  private readonly msg = inject(HrmMessageService);

  protected readonly icSearch = IconSearch;

  /** Nhóm mở sẵn theo navCtx `report-group:<key>` (VD từ trợ giúp M06: 'ho-so'). */
  readonly initialGroup = input<string>('');

  /* ── catalog: search + quyền (ẩn) + chưa sẵn sàng (mờ + lý do) ── */
  private readonly kw = signal('');
  protected get kwModel(): string { return this.kw(); }
  protected set kwModel(v: string) { this.kw.set(v ?? ''); }

  protected readonly groups = computed(() => {
    const kw = this.kw().trim().toLowerCase();
    return M07_REPORT_GROUPS
      .filter((g) => !g.anTheoQuyen) // không quyền = ẨN
      .map((g) => ({ ...g, items: kw ? g.items.filter((i) => i.label.toLowerCase().includes(kw)) : g.items }))
      .filter((g) => g.items.length > 0);
  });

  /** Mục do người dùng chọn tay — null = chưa chọn, rơi về mục đầu của nhóm navCtx. */
  private readonly manualKey = signal<string | null>(null);
  /** Mục đang chọn: chọn tay thắng; chưa chọn → mục sẵn sàng đầu tiên của nhóm `initialGroup`
   *  (navCtx `report-group:<key>` — VD 'ho-so' từ trợ giúp M06). */
  protected readonly selKey = computed(() => {
    const m = this.manualKey();
    if (m !== null) return m;
    const g = M07_REPORT_GROUPS.find((x) => x.key === this.initialGroup());
    return g?.items.find((i) => i.sanSang)?.key ?? '';
  });
  protected readonly selItem = computed<InsM07ReportItem | null>(() => {
    for (const g of M07_REPORT_GROUPS) {
      const it = g.items.find((i) => i.key === this.selKey());
      if (it) return it;
    }
    return null;
  });
  protected readonly nhatKyMode = computed(() => this.selKey().startsWith('nk-'));

  protected chonMuc(it: InsM07ReportItem): void {
    if (!it.sanSang) return;
    this.manualKey.set(it.key);
    this.ketQua.set(null); this.dangChay.set(false);
    const ts = it.thamSoRieng;
    this.thamSo.set(ts ? (ts.batBuoc ? '' : ts.options[0]) : '');
    // kỳ + đơn vị + phạm vi GIỮ NGUYÊN — ngữ cảnh chung giữa các mục
  }

  /* ── tham số dùng chung (giữ ngữ cảnh) ── */
  protected readonly kyOptions = INS_KY.map((k) => ({ value: k.id, label: k.label }));
  private readonly ky = signal('k08');
  protected get kyModel(): unknown { return this.ky(); }
  protected set kyModel(v: unknown) { this.ky.set(String(v ?? 'k08')); }
  protected readonly donViOptions = INS_DON_VI.map((d) => ({ value: d.id, label: d.ten }));
  private readonly donVi = signal('dv1');
  protected get donViModel(): unknown { return this.donVi(); }
  protected set donViModel(v: unknown) { this.donVi.set(String(v ?? 'dv1')); }
  /** Phạm vi hợp nhất 3 mức — "Toàn pháp nhân" disabled theo quyền demo (option disabled). */
  protected readonly phamViOptions = M07_PHAM_VI.map((p) => ({ value: p.value, label: p.label, disabled: p.disabled }));
  protected readonly phamVi = signal<'don-vi' | 'nhieu-don-vi' | 'phap-nhan'>('don-vi');
  protected get phamViModel(): unknown { return this.phamVi(); }
  protected set phamViModel(v: unknown) { this.phamVi.set((v as 'don-vi') ?? 'don-vi'); }
  protected readonly phamViLabel = computed(() =>
    this.phamVi() === 'don-vi' ? `1 đơn vị (${this.donVi()})` : 'nhiều đơn vị (dv1 + dv2)');

  protected readonly thamSoOptions = computed(() =>
    (this.selItem()?.thamSoRieng?.options ?? []).map((o) => ({ value: o, label: o })));
  private readonly thamSo = signal('');
  protected get thamSoModel(): unknown { return this.thamSo(); }
  protected set thamSoModel(v: unknown) { this.thamSo.set(String(v ?? '')); }

  /** Guard chạy: đủ tham số bắt buộc + điều kiện tiên quyết dữ liệu mới chạy. */
  protected readonly runDisabledReason = computed<string | null>(() => {
    const it = this.selItem();
    if (!it) return 'Chưa chọn mục.';
    const ts = it.thamSoRieng;
    if (ts?.batBuoc && !this.thamSo()) return `Thiếu tham số bắt buộc: ${ts.label}.`;
    return null;
  });

  /* ── chạy (tức thời / nền có tiến độ) ── */
  protected readonly dangChay = signal(false);
  protected readonly tienDo = signal(0);
  protected readonly ketQua = signal<M07KetQua | null>(null);
  protected readonly ranAt = signal('');

  private buildCtx() {
    return {
      kyId: this.ky(),
      donViIds: this.phamVi() === 'don-vi' ? [this.donVi()] : INS_DON_VI.map((d) => d.id),
      thamSo: this.thamSo(),
      tien: (s?: string) => this.store.tien(s),
      m02: this.m02, m04: this.m04, m05: this.m05, m06: this.m06, m07: this.store, m08: this.m08,
    };
  }

  protected chay(): void {
    const it = this.selItem();
    if (!it || this.runDisabledReason()) return;
    const finish = () => {
      const kq = m07BuildKetQua(it.key, this.buildCtx());
      if (!kq) { this.msg.error('Mục chưa có builder kết quả (demo).'); return; }
      this.ketQua.set(kq);
      this.ranAt.set('19/08/2026 (demo)');
    };
    if (it.chayNen) {
      this.dangChay.set(true); this.tienDo.set(0); this.ketQua.set(null);
      const step = (p: number) => setTimeout(() => {
        this.tienDo.set(p);
        if (p < 100) step(p + 25);
        else { this.dangChay.set(false); finish(); this.msg.success('Lần chạy nền hoàn tất.'); }
      }, 350);
      step(25);
    } else finish();
  }

  private readonly c1TplRef = viewChild.required<TemplateRef<unknown>>('c1Tpl');
  protected readonly kqCols = computed<HrmGridColumn[]>(() => {
    const kq = this.ketQua();
    if (!kq) return [];
    return kq.cols.map((c, i) => ({
      key: c.key, title: c.title, align: c.align, width: c.width,
      cell: i === 0 ? (this.c1TplRef() as HrmGridColumn['cell']) : undefined,
    }));
  });

  /* ── panel dòng chỉ đọc ── */
  protected readonly peekModes: HrmPeekMode[] = ['side'];
  private readonly peekOpen = signal(false);
  protected get peekOpenModel(): boolean { return this.peekOpen(); }
  protected set peekOpenModel(v: boolean) { this.peekOpen.set(v); }
  protected readonly peekRow = signal<Record<string, unknown> | null>(null);
  protected onRowClick(row: Record<string, unknown>): void { this.peekRow.set(row); this.peekOpen.set(true); }

  /* ── xuất: biểu mẫu versioned + 3 chốt chặn + vòng đời tệp ── */
  protected readonly bieuMauOptions = M07_BIEU_MAU.map((b) => ({ value: b.value, label: b.label }));
  private readonly bieuMau = signal('bc-chi-v20261');
  protected get bieuMauModel(): unknown { return this.bieuMau(); }
  protected set bieuMauModel(v: unknown) { this.bieuMau.set(String(v ?? '')); }

  /** 3 chốt chặn: biểu mẫu (phiên bản áp dụng) + dữ liệu (đã chạy) + quyền xuất. */
  protected readonly chokes = computed(() => {
    const bmOk = !M07_BIEU_MAU.find((b) => b.value === this.bieuMau())?.label.includes('hết hiệu lực');
    return [
      { label: bmOk ? 'Biểu mẫu có phiên bản áp dụng tại kỳ' : 'Biểu mẫu HẾT HIỆU LỰC tại kỳ — chọn phiên bản theo ngày hiệu lực', ok: bmOk },
      { label: this.ketQua() ? 'Dữ liệu kết quả đã sẵn sàng' : 'Chưa chạy báo cáo — chưa có dữ liệu', ok: !!this.ketQua() },
      { label: 'Quyền xuất nhóm báo cáo (nhạy cảm che theo quyền — số che sẽ che cả trong tệp)', ok: true },
    ];
  });
  protected readonly exportDisabledReason = computed<string | null>(() => {
    const bad = this.chokes().find((c) => !c.ok);
    return bad ? bad.label : null;
  });

  protected xuat(): void {
    const it = this.selItem();
    if (!it || this.exportDisabledReason()) return;
    const bm = M07_BIEU_MAU.find((b) => b.value === this.bieuMau())!;
    const [ten, phienBan] = bm.label.split(' · ');
    const id = this.store.taoTepXuat(`${it.key}_ky08-2026.xlsx`, ten, phienBan ?? '', `Kỳ 08/2026 · ${this.phamViLabel()}`);
    setTimeout(() => { this.store.tepSanSang(id); this.msg.success(`Tệp ${id} Sẵn sàng tải.`); }, 1200);
    this.msg.info(`Đang tạo tệp ${id} — tệp mang ngữ cảnh + phiên bản biểu mẫu; nhật ký xuất đã ghi.`);
  }

  protected tai(id: string): void {
    const r = this.store.taiTep(id);
    r.ok ? this.msg.success('Đã tải — tải lại cũng ghi 1 dòng nhật ký.') : this.msg.error(r.reason ?? '');
  }

  protected tepLabel(s: keyof typeof M07_TEP_LABEL): string { return M07_TEP_LABEL[s]; }
  protected tepColor(s: keyof typeof M07_TEP_TONE): string {
    const t = M07_TEP_TONE[s];
    return t === 'success' ? 'green' : t === 'processing' ? 'blue' : 'default';
  }
}
