import { ChangeDetectionStrategy, Component, inject } from '@angular/core';
import { HrmTag } from 'hrm-ui';
import { InsSectionLabel } from '../_shared';
import { InsM08Store, M08_TINCAY_HUE, M08_TINCAY_LABEL, m08KhoangLabel } from '../_data/_m08-data';

/** M08 ④ — LOẠI THỦ TỤC HỒ SƠ + ÁNH XẠ MÃ PHIẾU (FN-15 — nơi DUY NHẤT phân loại):
 *  D02-LT + kỳ + đổi số → M03 · TK1/TK3 sự vụ → M06 · lai duy nhất 600o (cờ riêng) ·
 *  ngoại lệ ngược CD. Dòng NGOÀI PHẠM VI (651a/b/c, 605, BHXH TN/BHYT hộ GĐ) tra cứu được
 *  nhưng KHÔNG vào ô chọn (hiện mờ + lý do). Tra theo mã phiếu TẠI THỜI ĐIỂM NỘP; hết hiệu lực →
 *  chặn + gợi ý theo bảng ánh xạ; chưa ánh xạ → báo rõ, KHÔNG đoán. 17 dòng 600→651c + 4 ánh xạ
 *  (2 cặp giữ nhãn "cần xác minh"). TOÀN danh mục: Chưa thấy testcase (OQ — giữ nguyên nhãn). */
@Component({
  selector: 'ins-m08-thutuc-page',
  imports: [HrmTag, InsSectionLabel],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="t-head">
      <ins-section-label text="Danh mục loại thủ tục (17 dòng 600 → 651c)" tone="muted" [count]="store.thuTuc().length" />
      <hrm-tag size="sm" color="orange" variant="stroke">Toàn danh mục — Chưa thấy testcase (OQ, giữ nguyên nhãn)</hrm-tag>
    </div>
    <p class="t-note">Phân loại tại đây là DUY NHẤT: D02-LT + kỳ + đổi số phải đóng → M03 · TK1/TK3 sự vụ → M06 ·
      ngoại lệ ngược CD (D02-LT nhưng không đổi số) · tra theo mã phiếu TẠI THỜI ĐIỂM NỘP — hết hiệu lực → chặn + gợi ý
      theo bảng ánh xạ; CHƯA ánh xạ → báo rõ "chưa ánh xạ được", không đoán.</p>

    <div class="t-grid2">
      <div class="t-col">
        @for (t of store.thuTuc(); track t.maThuTuc) {
          <div class="t-item" [class.t-item--mo]="t.ngoaiPhamVi" [class.t-item--het]="t.trangThai === 'het-hieu-luc'">
            <div class="t-item__head">
              <span class="t-mono">{{ t.maThuTuc }}</span>
              <span class="t-strong">{{ t.ten }}</span>
              @if (t.coLai600o) { <hrm-tag size="sm" color="teal">Lai duy nhất — gộp sổ (chủ M06, sinh D02-LT → M03)</hrm-tag> }
              <hrm-tag size="sm" [color]="t.phanHeChu === 'm03' ? 'blue' : 'purple'" variant="stroke">Chủ hồ sơ: {{ t.phanHeChu === 'm03' ? 'M03 (theo kỳ)' : 'M06 (sự vụ)' }}</hrm-tag>
            </div>
            <p class="t-muted">Mã phiếu {{ t.maPhieu }} · biểu mẫu {{ t.bieuMauChinh }} · chủ thể {{ t.chuTheNop === 'don-vi' ? 'Đơn vị' : 'NLĐ tự nộp' }}
              · hiệu lực {{ khoang(t.khoangHL) }} · nguồn {{ t.nguon }} · <hrm-tag size="sm" [color]="hue(t.doTinCay)">{{ tinCay(t.doTinCay) }}</hrm-tag></p>
            @if (t.trangThai === 'het-hieu-luc') {
              <p class="t-err">HẾT HIỆU LỰC — chọn tại thời điểm nộp bị CHẶN; gợi ý theo bảng ánh xạ (600 → 600a).</p>
            }
            @if (t.ngoaiPhamVi) { <p class="t-warn">{{ t.lyDoNgoaiPhamVi }} — tra cứu được, KHÔNG vào ô chọn.</p> }
          </div>
        }
      </div>

      <div class="t-col">
        <ins-section-label text="Bảng ánh xạ mã cũ ↔ mã mới (4 dòng)" tone="attention" [count]="store.anhXa().length" />
        @for (a of store.anhXa(); track a.maCu) {
          <div class="t-map" [class.t-map--xm]="a.nhanXacMinh">
            <span class="t-mono">{{ a.maCu }} ↔ {{ a.maMoi }}</span>
            <span class="t-muted">từ {{ a.ngayHL }} — {{ a.ghiChu }}</span>
            @if (a.nhanXacMinh) { <hrm-tag size="sm" color="red" variant="stroke">Cần xác minh</hrm-tag> }
          </div>
        }
        <p class="t-note">Chưa có trong bảng ánh xạ → hệ thống báo "chưa ánh xạ được mã phiếu", KHÔNG tự đoán mã mới.
          Sự kiện đồng bộ lỗi "thiếu ánh xạ" (Nhật ký đồng bộ) link về tab này.</p>
      </div>
    </div>
  `,
  host: { class: 'ins-m08-thutuc-page' },
  styles: [`
    :host { display: flex; flex-direction: column; gap: 10px; }
    .t-head { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
    .t-note { margin: 0; font-size: var(--fs-12); color: var(--text-sub); }
    .t-grid2 { display: grid; grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr); gap: 14px; align-items: start; }
    .t-col { display: flex; flex-direction: column; gap: 8px; min-width: 0; }
    .t-item { border: 1px solid var(--border-sub); border-radius: var(--radius-md); background: var(--bg-surface); padding: 8px 11px; display: flex; flex-direction: column; gap: 4px; }
    .t-item--mo { opacity: .55; }
    .t-item--het { border-style: dashed; }
    .t-item__head { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
    .t-mono { font-family: var(--font-mono, monospace); font-size: var(--fs-12); font-weight: 700; color: var(--text-strong); }
    .t-strong { color: var(--text-strong); font-weight: 500; }
    .t-muted { margin: 0; font-size: var(--fs-12); color: var(--text-sub); display: flex; align-items: center; gap: 5px; flex-wrap: wrap; }
    .t-warn { margin: 0; font-size: var(--fs-12); color: var(--warning-text); font-weight: 500; }
    .t-err { margin: 0; font-size: var(--fs-12); color: var(--error-text); font-weight: 500; }
    .t-map { border: 1px dashed var(--border-sub); border-radius: var(--radius-md); padding: 7px 10px; display: flex; flex-direction: column; gap: 3px; align-items: flex-start; }
    .t-map--xm { border-color: var(--error-base); background: var(--error-bg); }
  `],
})
export class InsM08ThuTucPage {
  protected readonly store = inject(InsM08Store);
  protected readonly khoang = m08KhoangLabel;
  protected tinCay(k: keyof typeof M08_TINCAY_LABEL): string { return M08_TINCAY_LABEL[k]; }
  protected hue(k: keyof typeof M08_TINCAY_HUE): string { return M08_TINCAY_HUE[k]; }
}
