import { ChangeDetectionStrategy, Component, input } from '@angular/core';

/** ins-section-label — header nhóm ưu tiên trong queue (CRITICAL / ATTENTION / ON TRACK / MUTED):
 *  chữ uppercase fs-11 màu theo tone + pill đếm.
 *  Dùng ở: các queue M02/M05-A/M07-A (nhóm dòng theo mức ưu tiên), Tab 5 M02 (nhóm ngoại lệ). */
export type InsSectionTone = 'critical' | 'attention' | 'ontrack' | 'muted';

@Component({
  selector: 'ins-section-label',
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <span class="sl-tx">{{ text() }}</span>
    @if (count() !== null) { <span class="sl-count">{{ count() }}</span> }
  `,
  host: { class: 'ins-section-label', '[attr.data-tone]': 'tone()' },
  styles: [`
    :host { display: inline-flex; align-items: center; gap: 7px; }
    .sl-tx {
      font-size: var(--fs-11); font-weight: 700; letter-spacing: .05em;
      text-transform: uppercase; line-height: 1.4;
    }
    :host([data-tone='critical']) .sl-tx { color: var(--error-base); }
    :host([data-tone='attention']) .sl-tx { color: var(--warning-base); }
    :host([data-tone='ontrack']) .sl-tx { color: var(--success-base); }
    :host([data-tone='muted']) .sl-tx { color: var(--text-sub); }
    .sl-count {
      font-size: var(--fs-11); font-weight: 600; color: var(--text-sub);
      background: var(--bg-surface-subtle); border-radius: var(--radius-full);
      padding: 0 7px; line-height: 1.6;
    }
  `],
})
export class InsSectionLabel {
  readonly text = input.required<string>();
  readonly tone = input<InsSectionTone>('muted');
  readonly count = input<number | null>(null);
}
