import { ChangeDetectionStrategy, Component, inject, signal } from '@angular/core';
import { InsShellStore } from '../_data/_core';
import { InsM05Store, m05StepOfState } from '../_data/_m05-data';
import { InsM05Queue } from './queue/m05-queue';
import { InsM05Case } from './case/m05-case-page';

/** ═════════ M05 — CHẾ ĐỘ BHXH (Phase D3): A queue 4 tab ↔ B case stepper B1–B5 ═════════
 *  Điều hướng NỘI BỘ bằng signal (không đổi URL — giữ pattern legacy/ux-architecture):
 *  A → B qua "Đi sâu xử lý" (mang caseId + bước đúng trạng thái); B → A giữ tab/filter
 *  (state hàng đợi sống trong InsM05Store). navCtx chéo module: 'case:<maCase>' (từ M02 Q78
 *  link "Case CS-… (M05)") mở thẳng Màn B đúng bước. */
@Component({
  selector: 'ins-m05-page',
  imports: [InsM05Queue, InsM05Case],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (view(); as v) {
      <ins-m05-case [caseId]="v.caseId" [initialStep]="v.step" (back)="view.set(null)" />
    } @else {
      <ins-m05-queue (openCase)="open($event)" />
    }
  `,
  styles: [`
    :host { display: flex; flex-direction: column; flex: 1 1 auto; min-height: 0; }
  `],
})
export class InsM05Page {
  private readonly shell = inject(InsShellStore);
  private readonly store = inject(InsM05Store);

  /** null = Màn A (queue); có giá trị = Màn B (case) tại bước yêu cầu. */
  protected readonly view = signal<{ caseId: string; step: number } | null>(null);

  constructor() {
    // Diễn giải navCtx MỘT lần: 'case:<maCase>' → mở thẳng Màn B đúng bước theo trạng thái.
    const f = this.shell.navCtx().filter;
    if (f?.startsWith('case:')) {
      const id = f.slice(5);
      const c = this.store.caseOf(id);
      if (c) this.view.set({ caseId: id, step: m05StepOfState(c.trangThai) });
      this.shell.navCtx.update((ctx) => ({ ...ctx, filter: undefined }));
    }
  }

  protected open(e: { caseId: string; step: number }): void { this.view.set(e); }
}
