import { ChangeDetectionStrategy, Component, TemplateRef, computed, inject, viewChild } from '@angular/core';
import { HrmAlert, HrmButton, HrmGrid, HrmGridColumn, HrmMessageService, HrmStatusCell, HrmTag } from 'hrm-ui';
import { InsSectionLabel } from '../_shared';
import {
  InsM08Store, M08_DUYET_LABEL, M08_DUYET_TONE, M08_TINCAY_HUE, M08_TINCAY_LABEL,
} from '../_data/_m08-data';

/** M08 ③ — DANH MỤC MÃ PHƯƠNG ÁN D02-LT (FN-14): KHÔNG hardcode, đọc theo kỳ; mỗi mã có hiệu lực
 *  từ (đến trống = còn), cờ "làm đổi số phải đóng" (Không: CHỈ CD), nhãn nguồn + độ tin cậy +
 *  số hiệu văn bản đối chiếu (QĐ 366 29/4/2026). `Thấp`/`Cần xác minh` → chip cảnh báo màu +
 *  KHÔNG làm default; nhóm phụ Thấp KHÔNG vào cấu hình thật trước đối chiếu; thiếu nhãn nguồn →
 *  không gửi duyệt; DL/GV_19 "Chưa thấy testcase" — GIỮ NGUYÊN NHÃN. */
@Component({
  selector: 'ins-m08-d02-page',
  imports: [HrmAlert, HrmButton, HrmGrid, HrmStatusCell, HrmTag, InsSectionLabel],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <hrm-alert type="warning" message="Cảnh báo pháp lý (4 chốt m08.md)"
      description="Rà toàn danh mục theo QĐ 366/QĐ-BHXH 29/4/2026 · không hardcode mã · bắt buộc bảng ánh xạ · không chốt sơ đồ cột D02-LT trước phụ lục." />

    <div class="d-head">
      <ins-section-label text="Bảng mã đủ nhãn tin cậy" tone="muted" [count]="rows().length" />
      <span class="d-muted">Đổi mã đang tham chiếu = phiên bản mới · kỳ khóa giữ bản đã dùng · chọn mã hết hiệu lực → CHẶN.</span>
    </div>

    <hrm-grid [columns]="cols()" [data]="rows()" rowKey="ma" density="compact" minWidth="1150px" [pageSize]="12" />

    <ng-template #maTpl let-row>
      <div class="d-stack">
        <span class="d-mono">{{ $any(row).ma }}</span>
        <span class="d-strong">{{ $any(row).ten }}</span>
        @if ($any(row).ghiChu) { <span class="d-muted">{{ $any(row).ghiChu }}</span> }
      </div>
    </ng-template>
    <ng-template #coTpl let-row>
      @if ($any(row).coDoiSo) { <hrm-tag size="sm" color="blue">Đổi số phải đóng</hrm-tag> }
      @else { <hrm-tag size="sm" color="gray" variant="stroke">KHÔNG đổi số phải đóng</hrm-tag> }
    </ng-template>
    <ng-template #tinCayTpl let-row>
      <div class="d-stack">
        <hrm-tag size="sm" [color]="$any(row).hue">{{ $any(row).tinCay }}</hrm-tag>
        @if ($any(row).canhBao) { <span class="d-warn">Cảnh báo trên ô chọn — KHÔNG làm default</span> }
        @if ($any(row).chuaThayTestcase) { <hrm-tag size="sm" color="orange" variant="stroke">Chưa thấy testcase</hrm-tag> }
      </div>
    </ng-template>
    <ng-template #ttTpl let-row>
      <div class="d-stack">
        <hrm-status-cell [status]="$any(row).tone" [label]="$any(row).trangThai" variant="badge" />
        @if ($any(row).khongVaoCauHinh) { <span class="d-warn">Không vào cấu hình thật trước đối chiếu QĐ 366</span> }
      </div>
    </ng-template>
    <ng-template #actTpl let-row>
      @if ($any(row).guiDuyetReason; as reason) {
        <div class="d-stack">
          <hrm-button size="sm" [disabled]="true">Gửi duyệt</hrm-button>
          <span class="d-err">{{ reason }}</span>
        </div>
      } @else if ($any(row).nhap) {
        <hrm-button size="sm" variant="primary" (click)="guiDuyet($any(row).ma)">Gửi duyệt</hrm-button>
      }
    </ng-template>
  `,
  host: { class: 'ins-m08-d02-page' },
  styles: [`
    :host { display: flex; flex-direction: column; gap: 10px; }
    .d-head { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
    .d-muted { font-size: var(--fs-12); color: var(--text-sub); }
    .d-warn { font-size: var(--fs-11); color: var(--warning-text); font-weight: 500; }
    .d-err { font-size: var(--fs-11); color: var(--error-text); font-weight: 500; max-width: 240px; }
    .d-mono { font-family: var(--font-mono, monospace); font-size: var(--fs-12); font-weight: 700; color: var(--text-strong); }
    .d-strong { color: var(--text-strong); font-weight: 500; }
    .d-stack { display: flex; flex-direction: column; gap: 2px; align-items: flex-start; }
  `],
})
export class InsM08D02Page {
  protected readonly store = inject(InsM08Store);
  private readonly msg = inject(HrmMessageService);

  private readonly NHOM_LABEL: Record<string, string> = { tang: 'Tăng', giam: 'Giảm', 'dieu-chinh': 'Điều chỉnh', phu: 'Nhóm phụ' };

  protected readonly rows = computed(() => this.store.maPhuongAn().map((m) => ({
    ma: m.ma, ten: m.ten, ghiChu: m.ghiChu ?? '', nhom: this.NHOM_LABEL[m.nhom],
    coDoiSo: m.coDoiSoPhaiDong,
    hieuLuc: `${m.tuNgay} → ${m.denNgay ?? 'còn hiệu lực'}`,
    nguon: m.nguon,
    tinCay: M08_TINCAY_LABEL[m.doTinCay], hue: M08_TINCAY_HUE[m.doTinCay],
    canhBao: m.doTinCay === 'thap' || m.doTinCay === 'can-xac-minh',
    chuaThayTestcase: !!m.chuaThayTestcase,
    doiChieu: m.soHieuDoiChieu,
    trangThai: M08_DUYET_LABEL[m.trangThai], tone: M08_DUYET_TONE[m.trangThai],
    khongVaoCauHinh: !!m.khongVaoCauHinh,
    nhap: m.trangThai === 'nhap',
    guiDuyetReason: m.trangThai === 'nhap' ? this.store.guiDuyetMaPAReason(m.ma) : null,
  })));

  private readonly maTpl = viewChild.required<TemplateRef<unknown>>('maTpl');
  private readonly coTpl = viewChild.required<TemplateRef<unknown>>('coTpl');
  private readonly tinCayTpl = viewChild.required<TemplateRef<unknown>>('tinCayTpl');
  private readonly ttTpl = viewChild.required<TemplateRef<unknown>>('ttTpl');
  private readonly actTpl = viewChild.required<TemplateRef<unknown>>('actTpl');

  protected readonly cols = computed<HrmGridColumn[]>(() => [
    { key: 'ma', title: 'Mã · tên', width: '280px', cell: this.maTpl() as HrmGridColumn['cell'] },
    { key: 'nhom', title: 'Nhóm', width: '95px' },
    { key: 'co', title: 'Cờ đổi số phải đóng', width: '175px', cell: this.coTpl() as HrmGridColumn['cell'] },
    { key: 'hieuLuc', title: 'Hiệu lực', width: '165px' },
    { key: 'tinCay', title: 'Nguồn · độ tin cậy', width: '210px', cell: this.tinCayTpl() as HrmGridColumn['cell'] },
    { key: 'doiChieu', title: 'Văn bản đối chiếu', width: '240px' },
    { key: 'trangThai', title: 'Trạng thái', width: '190px', cell: this.ttTpl() as HrmGridColumn['cell'] },
    { key: 'act', title: '', width: '150px', fixed: 'right', align: 'right', cell: this.actTpl() as HrmGridColumn['cell'] },
  ]);

  protected guiDuyet(ma: string): void {
    this.msg.success(`Mã ${ma} đủ nhãn nguồn — gửi duyệt (maker-checker như rule; demo không đổi trạng thái).`);
  }
}
