/** Cột + row-VM màn A (pattern D1: format 1 lần, template chỉ bind chuỗi).
 *  Dòng = 1 NLĐ trong 1 hồ sơ: NLĐ + mã hồ sơ/mã GD + loại chế độ + 3 SỐ + trạng thái
 *  + ngày + cờ quá hạn + aging + hành động. */

function dayNum(d: string): number {
  const [dd, mm, yy] = d.split('/').map(Number);
  return yy * 372 + mm * 31 + dd;
}

export interface M07Row extends Record<string, unknown> {
  id: string;
  ten: string;
  sub: string;              // mã NV · mã BHXH đơn vị
  maHoSo: string;
  maGD: string;
  loaiCheDo: string;
  deNghi: string;           // '' = thiếu số đề nghị
  duyet: string;            // '' = chưa có kết quả (KHÔNG số 0)
  tuChoi: boolean;
  daChi: string;            // '' = chưa chi
  trangThaiLabel: string;
  trangThaiTone: string;
  ngayKyNop: string;
  mocNgay: string;          // mốc phụ theo trạng thái (tiền về/hạn chi/ngày chi)
  slaLabel: string;
  slaTone: 'ok' | 'warn' | 'danger' | 'muted';
  coQuaHan: boolean;
  choVuotNguong: boolean;
  h1: string; h1Tone: string;
  h2: string; h2Tone: string;
  coChenhLech: boolean;
  soLanChiHong: number;
  phienBan: number;
  actions: HrmActionItem[];
}

/** Aging + cờ hạn — chuỗi format sẵn (zoneless). */
function slaOf(d: InsM07Dong): { label: string; tone: M07Row['slaTone'] } {
  if (d.coQuaHan && d.hanChi) return { label: `quá hạn chi ${dayNum(M07_TODAY) - dayNum(d.hanChi)} ngày`, tone: 'danger' };
  if (d.trangThai === 'cho-duyet') {
    return d.soNgayCho > 10
      ? { label: `chờ ${d.soNgayCho} ngày · vượt ngưỡng 10`, tone: 'danger' }
      : { label: `chờ kết quả ${d.soNgayCho} ngày`, tone: d.soNgayCho > 7 ? 'warn' : 'ok' };
  }
  if (d.trangThai === 'tien-da-ve' && d.hanChi) return { label: `hạn chi ${d.hanChi}`, tone: 'warn' };
  return { label: '—', tone: 'muted' };
}

export function buildM07Row(d: InsM07Dong, tien: (s?: string) => string): M07Row {
  const nv = insNhanVien(d.nhanVienId);
  const duyet = m07SoDuyet(d);
  const h1 = m07HieuSo1(d), h2 = m07HieuSo2(d);
  const sla = slaOf(d);
  const actions: M07Row['actions'] = [{ key: 'view', icon: IconEye, label: 'Chi tiết' }];
  if (d.trangThai === 'cho-duyet' && d.soDeNghi) actions.push({ key: 'ghi-kq', icon: IconPencil, label: 'Ghi kết quả' });
  if (d.trangThai === 'cho-duyet') actions.push({ key: 'huy', icon: IconBan, label: 'Hủy (thu hồi trước KQ)' });
  if (duyet !== undefined && (d.trangThai === 'da-duyet' || d.trangThai === 'tien-da-ve')) {
    actions.push({ key: 'sua-kq', icon: IconHistory, label: 'Sửa kết quả (bản ghi mới)' });
  }
  if (d.trangThai === 'tien-da-ve' || d.trangThai === 'da-de-nghi') actions.push({ key: 'xac-nhan-chi', icon: IconCash, label: 'Xác nhận chi' });
  if (d.trangThai === 'da-chi-tra') actions.push({ key: 'dong', icon: IconLock, label: 'Đóng theo dõi' });
  if (d.trangThai === 'da-xu-ly') actions.push({ key: 'mo-lai', icon: IconLockOpen, label: 'Mở lại' });
  return {
    id: d.id,
    ten: nv?.name ?? d.nhanVienId,
    sub: `${nv?.code ?? ''} · ${d.maBHXH}`,
    maHoSo: d.maHoSo, maGD: d.maGD, loaiCheDo: d.loaiCheDo,
    deNghi: d.soDeNghi ? tien(d.soDeNghi) : '',
    duyet: duyet !== undefined ? tien(duyet) : '',
    tuChoi: d.ketQuaDuyet?.ketQua === 'tu-choi',
    daChi: d.soDaChi !== undefined ? tien(d.soDaChi) : '',
    trangThaiLabel: M07_STATE_LABEL[d.trangThai] + (d.phienBan > 1 ? ` · v${d.phienBan}` : ''),
    trangThaiTone: M07_STATE_TONE[d.trangThai],
    ngayKyNop: d.ngayKyNop,
    mocNgay: d.ngayChi ? `chi ${d.ngayChi}` : d.ngayTienVe ? `tiền về ${d.ngayTienVe}` : `ký nộp ${d.ngayKyNop}`,
    slaLabel: sla.label, slaTone: sla.tone,
    coQuaHan: d.coQuaHan, choVuotNguong: d.trangThai === 'cho-duyet' && d.soNgayCho > 10,
    h1: h1.co ? h1.str : '', h1Tone: h1.tone,
    h2: h2.co && !h2.chuaChi ? h2.str : '', h2Tone: h2.tone,
    coChenhLech: !!d.giaiTrinh && d.giaiTrinh.trangThai !== 'da-duyet',
    soLanChiHong: d.soLanChiHong, phienBan: d.phienBan,
    actions,
  };
}

