/* ─────────────────────────── Hiệu số (2 HIỆU SỐ RIÊNG — CẤM cộng gộp) ─────────────────────────── */

export interface InsM07HieuSo { co: boolean; num: number; str: string; tone: 'up' | 'down' | 'zero'; }

export function m07SoDuyet(d: InsM07Dong): string | undefined {
  return d.ketQuaDuyet?.ketQua === 'duyet' ? d.ketQuaDuyet.soDuyet : undefined;
}

/** Hiệu số 1 = (đề nghị − duyệt). Chưa có duyệt → co=false ("chưa có kết quả" — KHÔNG số 0). */
export function m07HieuSo1(d: InsM07Dong): InsM07HieuSo {
  const duyet = m07SoDuyet(d);
  if (!d.soDeNghi || duyet === undefined) return { co: false, num: 0, str: '', tone: 'zero' };
  const n = insParseVnd(d.soDeNghi) - insParseVnd(duyet);
  return { co: true, num: n, str: n === 0 ? '0' : insFormatVnd(n, true), tone: n > 0 ? 'up' : n < 0 ? 'down' : 'zero' };
}

/** Hiệu số 2 = (duyệt − đã chi). Chưa chi → toàn bộ = BÌNH THƯỜNG (chuaChi=true). */
export function m07HieuSo2(d: InsM07Dong): InsM07HieuSo & { chuaChi: boolean } {
  const duyet = m07SoDuyet(d);
  if (duyet === undefined) return { co: false, num: 0, str: '', tone: 'zero', chuaChi: d.soDaChi === undefined };
  const chi = d.soDaChi !== undefined ? insParseVnd(d.soDaChi) : 0;
  const n = insParseVnd(duyet) - chi;
  return {
    co: true, num: n, str: n === 0 ? '0' : insFormatVnd(n, true),
    tone: d.soDaChi === undefined ? 'zero' : n > 0 ? 'up' : n < 0 ? 'down' : 'zero',
    chuaChi: d.soDaChi === undefined,
  };
}

/** Phần dư đợt chi = tổng đợt − tổng phân bổ (hiện rõ + owner, không tự gán). */
export function m07PhanDu(dot: InsM07DotChi): number {
  return insParseVnd(dot.tongTien) - dot.phanBo.reduce((s, p) => s + insParseVnd(p.soTien), 0);
}

