/* ── Kiểm tra dữ liệu theo kỳ lương — bộ 66 chỉ tiêu (hiện 8 tiêu biểu), 12 tháng cột động ── */

/** Cửa sổ 12 tháng động kết thúc tại kỳ 08/2026. */
export const M07_KT_THANG = ['09/25', '10/25', '11/25', '12/25', '01/26', '02/26', '03/26', '04/26', '05/26', '06/26', '07/26', '08/26'];

export interface InsM07KtChiTieu { ma: string; ten: string; thang: string[]; }
export interface InsM07KtPhienBan {
  id: string;
  chayLuc: string;
  nguoiChay: string;
  trangThai: 'hoan-tat' | 'hoan-tat-mot-phan' | 'loi';
  chiTieu: InsM07KtChiTieu[];
}

/** 8/66 chỉ tiêu tiêu biểu — giá trị chuỗi sẵn, tăng đều deterministic (không Math.random). */
function ktBase(): InsM07KtChiTieu[] {
  const mk = (ma: string, ten: string, goc: number, buoc: number, donVi = ''): InsM07KtChiTieu => ({
    ma, ten, thang: M07_KT_THANG.map((_, i) => `${(goc + buoc * i).toLocaleString('vi-VN')}${donVi}`),
  });
  return [
    mk('CT-01', 'Số lao động tham gia BHXH cuối tháng', 292, 2),
    mk('CT-05', 'Số lao động tăng mới trong tháng', 6, 0),
    mk('CT-08', 'Số lao động giảm trong tháng', 4, 0),
    mk('CT-12', 'Quỹ lương làm căn cứ đóng (triệu đồng)', 4826, 38),
    mk('CT-19', 'Số phải đóng BHXH-BHYT-BHTN (triệu đồng)', 1544, 12),
    mk('CT-27', 'Số lao động thiếu mã số BHXH', 3, 0),
    mk('CT-41', 'Hồ sơ chế độ phát sinh trong tháng', 9, 0),
    mk('CT-58', 'Số tiền chi chế độ đã quyết toán (triệu đồng)', 118, 4),
  ];
}

/** 2 phiên bản seed — v2 lệch 3 ô so với v1 (demo so sánh 2 phiên bản → diff count). */
function ktSeed(): InsM07KtPhienBan[] {
  const v1 = ktBase();
  const v2 = ktBase();
  v2[0].thang[11] = '318';        // CT-01 tháng 08/26
  v2[3].thang[11] = '5.290';      // CT-12 tháng 08/26
  v2[6].thang[10] = '12';         // CT-41 tháng 07/26
  return [
    { id: 'KT-2026-08-v1', chayLuc: '15/08/2026 09:00', nguoiChay: KT_1, trangThai: 'hoan-tat', chiTieu: v1 },
    { id: 'KT-2026-08-v2', chayLuc: '18/08/2026 16:40', nguoiChay: KT_1, trangThai: 'hoan-tat', chiTieu: v2 },
  ];
}

/** Đếm số ô khác nhau giữa 2 phiên bản (so sánh 2 phiên bản kết quả). */
export function m07KtDiff(a: InsM07KtPhienBan, b: InsM07KtPhienBan): number {
  let n = 0;
  a.chiTieu.forEach((ct, i) => ct.thang.forEach((v, j) => { if (v !== b.chiTieu[i]?.thang[j]) n++; }));
  return n;
}

/* ═════════════════ STORE ═════════════════ */

/** Bulk generic màn A (pattern D3: 1 map hành động — select + chạy + retry idempotent). */
export type M07BulkAction = 'ghi-ket-qua' | 'lap-de-nghi' | 'xac-nhan-chi' | 'dong-theo-doi' | 'ket-xuat';
export const M07_BULK_LABEL: Record<M07BulkAction, string> = {
  'ghi-ket-qua': 'Ghi kết quả duyệt (lô — độc lập từng dòng)', 'lap-de-nghi': 'Lập đề nghị thanh toán',
  'xac-nhan-chi': 'Xác nhận chi', 'dong-theo-doi': 'Đóng theo dõi', 'ket-xuat': 'Kết xuất (cơ chế M07-B)',
};

let clockMin = 0;
function demoNow(): string {
  clockMin += 7;
  const h = 9 + Math.floor(clockMin / 60), m = clockMin % 60;
  return `${M07_TODAY} ${String(Math.min(h, 18)).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
}

const clone = <T>(x: T): T => structuredClone(x);

/** Trạng thái tính vào tab "Tiền đã về chưa chi" (tab nóng). */
const TAB_TIEN_VE = new Set<InsM07LineState>(['tien-da-ve', 'da-de-nghi']);
const TAB_DA_CHI = new Set<InsM07LineState>(['da-chi-tra', 'da-xu-ly']);
/** Trạng thái thuộc tab Từ chối / Chênh lệch (nhánh từ chối). */
const TAB_TU_CHOI = new Set<InsM07LineState>(['tu-choi', 'cho-nop-lai', 'da-nop-lai', 'dong-co-ly-do']);

@Injectable({ providedIn: 'root' })
export class InsM07Store {
  /** Người dùng demo — KẾ TOÁN (quyền: xem, ghi tiền về, lập đề nghị, xác nhận chi, xuất). */
  readonly currentUser = KT_1;
  readonly nguoiNhapKQ = HR_1;
  readonly quanLy = HR_2;
  readonly giamDoc = GD_1;

  private readonly m05 = inject(InsM05Store);

  /** Patch runtime theo id dòng (UX-2) — trạng thái/kết quả đè lên dòng derive + seed. */
  private readonly dongPatch = signal<ReadonlyMap<string, Partial<InsM07Dong>>>(new Map());
  /** Dòng sinh runtime (VD nộp lại ký → dòng MỚI) — cộng vào sau dòng derive + seed. */
  private readonly dongRuntime = signal<InsM07Dong[]>([]);

  /** UX-2 (Phase E): dòng theo dõi DERIVE từ `m05.cases()` — MỌI case có `banGiaoChi` sinh dòng
   *  (bàn giao mới từ M05, COR bất kỳ, hiện NGAY); overlay `M05_OVERLAY` chỉ ENRICH (bổ field),
   *  KHÔNG lọc; + 8 dòng phủ tĩnh `DONG_EXTRA`; trạng thái runtime do `dongPatch` đè lên. */
  readonly dong = computed<InsM07Dong[]>(() => {
    const fromM05: InsM07Dong[] = [];
    for (const c of this.m05.cases()) {
      const bg = c.banGiaoChi;
      if (!bg) continue;
      const ov = M05_OVERLAY[bg.correlationId]; // enrich-only — không có overlay vẫn sinh dòng
      fromM05.push({
        id: `L-${bg.correlationId.slice(-4)}`,
        maHoSo: bg.maHoSo,
        maGD: `GD-2026-${bg.correlationId.slice(-4)}`, // A-M07-GD: mã GD demo tự đặt
        maCase: bg.maCase, nhanVienId: bg.nhanVienId, maBHXH: c.maBHXH, donViId: c.donViId,
        loaiCheDo: c.loaiCheDo,
        soDeNghi: bg.soTienDeNghi, // sao chép & KHÓA tại bàn giao — số duyệt CHỈ từ KetQuaDuyet M07
        trangThai: 'cho-duyet', ngayKyNop: bg.ngayNop, soNgayCho: 0,
        coQuaHan: false, soLanChiHong: 0, correlationId: bg.correlationId,
        phienBan: 1, nguon: 'm05-ban-giao',
        ...ov,
      } as InsM07Dong);
    }
    const patch = this.dongPatch();
    return [...fromM05, ...DONG_EXTRA, ...this.dongRuntime()]
      .map((d) => { const p = patch.get(d.id); return p ? { ...d, ...p } : d; });
  });

  readonly dotChi = signal<InsM07DotChi[]>(clone(DOT_SEED));
  readonly thuHoi = signal<InsM07KhoanThuHoi[]>(clone(THUHOI_SEED));
  readonly chiHong = signal<InsM07KhoanChiHong[]>(clone(CHIHONG_SEED));
  readonly deNghi = signal<InsM07DeNghi[]>(clone(DENGHI_SEED));
  /** Nhật ký append-only (bất biến #3) — nguồn sự kiện BẮT BUỘC của nhóm Nhật ký kiểm toán M07-B. */
  readonly audit = signal<InsM07AuditEntry[]>(clone(AUDIT_SEED));
  /** Phản hồi ngược M05 GIỮ TRONG STORE M07 (tiền lệ A-M05-COR — không ghi xuyên InsM05Store). */
  readonly phanHoiM05 = signal<{ at: string; maCase: string; noiDung: string }[]>([
    { at: '12/08/2026 16:50', maCase: 'CS-2026-0118', noiDung: 'Kết quả chi cuối: Không chi trả (đã hoàn trả cơ quan — CH-2026-02)' },
    { at: '06/08/2026 10:20', maCase: 'CS-2026-0109', noiDung: 'Yêu cầu sửa/nộp lại (M05 B4): số tài khoản không hợp lệ + thiếu giấy khai sinh con thứ 2' },
  ]);
  readonly lastBulk = signal<{ action: M07BulkAction; skipped: { id: string; reason: string }[] } | null>(null);

  /** Che số tiền nhạy cảm (quyền) — BẬT XEM sẽ ghi log truy cập. */
  readonly maskTien = signal(false);

  /* UI state màn A giữ trong store (drawer contract: back giữ tab/filter). */
  readonly tabA = signal<M07TabKey>('tat-ca');
  readonly kw = signal('');
  readonly queueLoai = signal<M07QueueLoai>('tu-choi');

  resetDemo(): void {
    this.dongPatch.set(new Map());
    this.dongRuntime.set([]);
    this.dotChi.set(clone(DOT_SEED));
    this.thuHoi.set(clone(THUHOI_SEED));
    this.chiHong.set(clone(CHIHONG_SEED));
    this.deNghi.set(clone(DENGHI_SEED));
    this.audit.set(clone(AUDIT_SEED));
    this.lastBulk.set(null);
    this.tabA.set('tat-ca'); this.kw.set(''); this.queueLoai.set('tu-choi');
    this.maskTien.set(false);
  }

  dongOf(id: string): InsM07Dong | undefined { return this.dong().find((d) => d.id === id); }

  /** Ghi patch runtime cho 1 dòng (đè lên dòng derive/seed — UX-2). */
  private patch(id: string, p: Partial<InsM07Dong>): void {
    this.dongPatch.update((m) => {
      const next = new Map(m);
      next.set(id, { ...next.get(id), ...p });
      return next;
    });
  }
  private log(e: Omit<InsM07AuditEntry, 'at'>): void {
    this.audit.update((l) => [{ at: demoNow(), ...e }, ...l]);
  }

  /** Hiển thị tiền theo quyền — bật che → '●●●' (cả lưới + panel + tệp xuất). */
  tien(s: string | undefined): string {
    if (s === undefined || s === '') return s ?? '';
    return this.maskTien() ? '●●●' : s;
  }
  /** Bật/tắt che số tiền — BẬT XEM ghi log truy cập nhạy cảm. */
  toggleMask(): void {
    const dangChe = this.maskTien();
    this.maskTien.set(!dangChe);
    if (dangChe) this.log({ nguoi: this.currentUser, hanhDong: 'Bật xem số tiền chi từng NLĐ (dữ liệu nhạy cảm) — ghi log truy cập', doiTuong: 'Màn A · lưới', loai: 'truy-cap' });
  }

  /* ── computed 5 tab + 4 loại hàng đợi ── */

  /** Khoản thu hồi còn trong hàng đợi (chưa phản hồi M05 = chưa rời). */
  readonly thuHoiMo = computed(() => this.thuHoi().filter((t) => t.phanHoiM05 === 'chua'));
  readonly chiHongMo = computed(() => this.chiHong().filter((c) => c.trangThai === 'cho-quyet-dinh'));
  /** Dòng chênh lệch (hiệu ≠ 0 chưa duyệt lý do) — BẮT BUỘC nằm tab cuối tới khi có lý do. */
  readonly dongChenhLech = computed(() => this.dong().filter((d) => {
    const g = d.giaiTrinh;
    return !!g && g.trangThai !== 'da-duyet' && (m07HieuSo1(d).num !== 0 || m07HieuSo2(d).num !== 0);
  }));
  readonly dongTuChoi = computed(() => this.dong().filter((d) => TAB_TU_CHOI.has(d.trangThai)));

  readonly queueCounts = computed<Record<M07QueueLoai, number>>(() => ({
    'tu-choi': this.dongTuChoi().length,
    'chenh-lech': this.dongChenhLech().length,
    'thu-hoi': this.thuHoiMo().length,
    'chi-hong': this.chiHongMo().length,
  }));

  readonly tabCounts = computed(() => {
    const list = this.dong();
    const quaHan = (xs: InsM07Dong[]) => xs.filter((d) => d.coQuaHan).length;
    const choDuyet = list.filter((d) => d.trangThai === 'cho-duyet' || d.trangThai === 'can-xu-ly');
    const tienVe = list.filter((d) => TAB_TIEN_VE.has(d.trangThai));
    const daChi = list.filter((d) => TAB_DA_CHI.has(d.trangThai));
    const q = this.queueCounts();
    const tabCuoi = q['tu-choi'] + q['chenh-lech'] + q['thu-hoi'] + q['chi-hong'];
    return {
      tatCa: { count: list.length, quaHan: quaHan(list) },
      choDuyet: { count: choDuyet.length, quaHan: choDuyet.filter((d) => d.soNgayCho > 10).length },
      tienVe: { count: tienVe.length, quaHan: quaHan(tienVe) },
      daChi: { count: daChi.length, quaHan: 0 },
      tuChoiCL: { count: tabCuoi, quaHan: 0 },
    };
  });

  /** Dòng thuộc tab đang chọn (tab cuối trả các dòng nhánh từ chối + chênh lệch — khoản thu hồi/chi hỏng render section riêng). */
  dongOfTab(tab: M07TabKey): InsM07Dong[] {
    const list = this.dong();
    switch (tab) {
      case 'cho-duyet': return list.filter((d) => d.trangThai === 'cho-duyet' || d.trangThai === 'can-xu-ly');
      case 'tien-ve': return list.filter((d) => TAB_TIEN_VE.has(d.trangThai));
      case 'da-chi': return list.filter((d) => TAB_DA_CHI.has(d.trangThai));
      case 'tu-choi-cl': {
        const cl = this.dongChenhLech();
        return [...this.dongTuChoi(), ...cl.filter((d) => !TAB_TU_CHOI.has(d.trangThai))];
      }
      default: return list;
    }
  }

  /** Tổng theo lớp — 3 tổng TÁCH RIÊNG (cấm cộng gộp lớp). */
  readonly tongTheoLop = computed(() => {
    const list = this.dong();
    const sum = (f: (d: InsM07Dong) => string | undefined) =>
      insFormatVnd(list.reduce((s, d) => s + insParseVnd(f(d) ?? ''), 0));
    return {
      deNghi: sum((d) => d.soDeNghi),
      duyet: sum((d) => m07SoDuyet(d)),
      daChi: sum((d) => d.soDaChi),
    };
  });

  readonly tonQuaHan = computed(() => this.dong().filter((d) => d.coQuaHan && !TAB_DA_CHI.has(d.trangThai)));

  /* ── guard-pair (pattern D2: `*Reason(id): string|null` + transition cùng tên) ── */

  /** Ghi kết quả duyệt — chặn khi thiếu số đề nghị / sai trạng thái. */
  ghiKetQuaReason(id: string): string | null {
    const d = this.dongOf(id);
    if (!d) return 'Không tìm thấy dòng.';
    if (d.trangThai !== 'cho-duyet' && d.trangThai !== 'can-xu-ly') {
      return `Chỉ ghi kết quả cho dòng Chờ duyệt (hiện: ${M07_STATE_LABEL[d.trangThai]}).`;
    }
    if (!d.soDeNghi) return 'Thiếu số đề nghị từ bàn giao — dòng được tạo nhưng CHẶN ghi kết quả (bổ sung từ M05 trước).';
    return null;
  }
  ghiKetQua(id: string, r: { soDuyet?: string; tuChoi?: boolean; lyDoTuChoi?: string; nguon: 'cong-thong-tin' | 'nhap-tay'; tep?: string }): { ok: boolean; reason?: string } {
    const reason = this.ghiKetQuaReason(id);
    if (reason) return { ok: false, reason };
    const d = this.dongOf(id)!;
    const at = demoNow();
    if (r.tuChoi) {
      if (!r.lyDoTuChoi) return { ok: false, reason: 'Từ chối = lý do theo DANH MỤC (M08) — bắt buộc.' };
      this.patch(id, { trangThai: 'tu-choi', ketQuaDuyet: { ketQua: 'tu-choi', lyDoTuChoi: r.lyDoTuChoi, ngay: at, nguon: r.nguon, nguoiNhap: this.nguoiNhapKQ, tep: r.tep, phienBan: [] } });
      this.log({ nguoi: this.nguoiNhapKQ, hanhDong: `Ghi kết quả TỪ CHỐI (lý do danh mục: ${r.lyDoTuChoi})`, doiTuong: id, loai: 'ghi' });
      return { ok: true };
    }
    const soDuyet = r.soDuyet ?? d.soDeNghi; // lô: mặc định duyệt đúng số đề nghị
    const lech = insParseVnd(soDuyet) !== insParseVnd(d.soDeNghi);
    this.patch(id, {
      trangThai: 'da-duyet',
      ketQuaDuyet: { ketQua: 'duyet', soDuyet, ngay: at, nguon: r.nguon, nguoiNhap: this.nguoiNhapKQ, tep: r.tep, phienBan: [{ phienBan: 1, soDuyet, ngay: at, nguoiNhap: this.nguoiNhapKQ, nguon: r.nguon }] },
      giaiTrinh: lech ? { trangThai: 'can-xu-ly' } : undefined,
    });
    this.log({ nguoi: this.nguoiNhapKQ, hanhDong: `Ghi kết quả duyệt${lech ? ' — KHÁC số đề nghị → vào hàng đợi Chênh lệch' : ''}`, doiTuong: id, truoc: `${d.soDeNghi} (Dự kiến nội bộ)`, sau: `${soDuyet} (Chính thức theo kết quả cơ quan)`, loai: 'ghi' });
    return { ok: true };
  }

  /** Sửa kết quả duyệt = BẢN GHI MỚI + lý do (không ghi đè — bất biến #3). */
  suaKetQua(id: string, soDuyetMoi: string, lyDo: string): { ok: boolean; reason?: string } {
    if (!lyDo.trim()) return { ok: false, reason: 'Sửa kết quả = bản ghi mới — lý do BẮT BUỘC.' };
    const d = this.dongOf(id);
    if (!d?.ketQuaDuyet || d.ketQuaDuyet.ketQua !== 'duyet') return { ok: false, reason: 'Dòng chưa có kết quả duyệt để sửa.' };
    const at = demoNow();
    const pb = d.ketQuaDuyet.phienBan;
    const lech = insParseVnd(soDuyetMoi) !== insParseVnd(d.soDeNghi);
    this.patch(id, {
      ketQuaDuyet: { ...d.ketQuaDuyet, soDuyet: soDuyetMoi, ngay: at, phienBan: [...pb, { phienBan: pb.length + 1, soDuyet: soDuyetMoi, ngay: at, nguoiNhap: this.nguoiNhapKQ, nguon: 'nhap-tay', lyDoSua: lyDo.trim() }] },
      giaiTrinh: lech ? { trangThai: 'can-xu-ly' } : (m07HieuSo2({ ...d, ketQuaDuyet: { ...d.ketQuaDuyet, soDuyet: soDuyetMoi } }).num !== 0 && d.soDaChi !== undefined ? { trangThai: 'can-xu-ly' } : undefined),
    });
    this.log({ nguoi: this.nguoiNhapKQ, hanhDong: `Sửa kết quả duyệt = bản ghi mới (phiên bản ${pb.length + 1})`, doiTuong: id, truoc: d.ketQuaDuyet.soDuyet, sau: soDuyetMoi, lyDo: lyDo.trim(), loai: 'ghi' });
    return { ok: true };
  }

  /** Ghi tiền về — chống trùng đợt `mã ĐV + ngày + tiền + số chứng từ`; ngày bắt buộc. */
  ghiTienVe(ngayVe: string, tongTien: string, chungTuNH: string): { ok: boolean; reason?: string; ma?: string } {
    if (!ngayVe.trim()) return { ok: false, reason: 'Ngày tiền về BẮT BUỘC.' };
    if (!insParseVnd(tongTien)) return { ok: false, reason: 'Tổng tiền đợt không hợp lệ.' };
    const dup = this.dotChi().find((x) => x.ngayVe === ngayVe && insParseVnd(x.tongTien) === insParseVnd(tongTien) && x.chungTuNH === chungTuNH.trim());
    if (dup) return { ok: false, reason: `Trùng đợt ${dup.ma} (ngày + tiền + số chứng từ) — chạy lại không sinh trùng.` };
    const ma = `DOT-2026-08-${String(this.dotChi().length + 1).padStart(2, '0')}`;
    this.dotChi.update((l) => [...l, { ma, ngayVe, tongTien: insFormatVnd(insParseVnd(tongTien)), chungTuNH: chungTuNH.trim() || '(chưa có chứng từ NH)', phanBo: [], ownerPhanDu: `${this.currentUser} — kế toán` }]);
    this.log({ nguoi: this.currentUser, hanhDong: `Ghi tiền về đợt ${ma} (${insFormatVnd(insParseVnd(tongTien))}) — tiền nhận hộ NLĐ, cấm trộn luồng thu`, doiTuong: ma, loai: 'ghi' });
    return { ok: true, ma };
  }

  /** Phân bổ — chỉ dòng Đã duyệt nhận; Từ chối có tiền = bất thường CHẶN; không vượt tổng đợt. */
  phanBoReason(dotMa: string, dongId: string, soTien: string): string | null {
    const dot = this.dotChi().find((x) => x.ma === dotMa);
    if (!dot) return 'Không tìm thấy đợt chi.';
    const d = this.dongOf(dongId);
    if (!d) return 'Không tìm thấy dòng.';
    if (TAB_TU_CHOI.has(d.trangThai)) return 'Dòng Từ chối có tiền về = BẤT THƯỜNG — chặn phân bổ.';
    if (d.trangThai === 'cho-duyet' || d.trangThai === 'can-xu-ly') return 'Tiền về trước kết quả — ghi đợt được nhưng CHẶN phân bổ tới khi có kết quả duyệt.';
    if (d.trangThai !== 'da-duyet') return `Chỉ dòng Đã duyệt nhận phân bổ (hiện: ${M07_STATE_LABEL[d.trangThai]}).`;
    const st = insParseVnd(soTien);
    if (!st) return 'Số tiền phân bổ không hợp lệ.';
    if (st > m07PhanDu(dot)) return `Tổng phân bổ vượt tổng đợt — phần dư còn ${insFormatVnd(m07PhanDu(dot))}.`;
    return null;
  }
  phanBo(dotMa: string, dongId: string, soTien: string): { ok: boolean; reason?: string } {
    const reason = this.phanBoReason(dotMa, dongId, soTien);
    if (reason) return { ok: false, reason };
    const dot = this.dotChi().find((x) => x.ma === dotMa)!;
    this.dotChi.update((l) => l.map((x) => (x.ma === dotMa ? { ...x, phanBo: [...x.phanBo, { dongId, soTien: insFormatVnd(insParseVnd(soTien)) }] } : x)));
    this.patch(dongId, { trangThai: 'tien-da-ve', ngayTienVe: dot.ngayVe, hanChi: '26/08/2026' /* +7 ngày M08 */ });
    this.log({ nguoi: this.currentUser, hanhDong: `Phân bổ ${insFormatVnd(insParseVnd(soTien))} từ ${dotMa} — dòng → Tiền đã về (hạn chi 26/08)`, doiTuong: dongId, loai: 'ghi' });
    return { ok: true };
  }

  /* ── hàng đợi Chênh lệch: nhập lý do (người nhập) → duyệt (người duyệt ≠ người nhập) → đúng 1/2 hướng ── */

  nhapLyDoChenh(id: string, lyDo: string): { ok: boolean; reason?: string } {
    if (!lyDo.trim()) return { ok: false, reason: 'Lý do chênh lệch BẮT BUỘC.' };
    const d = this.dongOf(id);
    if (!d?.giaiTrinh || d.giaiTrinh.trangThai === 'da-duyet') return { ok: false, reason: 'Dòng không nằm trong hàng đợi Chênh lệch.' };
    this.patch(id, { giaiTrinh: { ...d.giaiTrinh, trangThai: 'da-co-ly-do', lyDo: lyDo.trim(), nguoiNhap: this.currentUser } });
    this.log({ nguoi: this.currentUser, hanhDong: 'Nhập lý do chênh lệch (chờ người khác duyệt)', doiTuong: id, lyDo: lyDo.trim(), loai: 'ghi' });
    return { ok: true };
  }

  /** BQA-21: phân công owner xử lý dòng chênh lệch — hàng đợi sang `Đang xử lý`. */
  phanCongChenhLech(id: string, owner: string): { ok: boolean; reason?: string } {
    if (!owner.trim()) return { ok: false, reason: 'Chọn owner được phân công.' };
    const d = this.dongOf(id);
    if (!d?.giaiTrinh || d.giaiTrinh.trangThai === 'da-duyet') return { ok: false, reason: 'Dòng không nằm trong hàng đợi Chênh lệch.' };
    this.patch(id, { giaiTrinh: {
      ...d.giaiTrinh, owner: owner.trim(),
      trangThai: d.giaiTrinh.trangThai === 'can-xu-ly' ? 'dang-xu-ly' : d.giaiTrinh.trangThai,
    } });
    this.log({ nguoi: this.currentUser, hanhDong: `Phân công owner xử lý chênh lệch: ${owner.trim()} — hàng đợi sang Đang xử lý`, doiTuong: id, loai: 'ghi' });
    return { ok: true };
  }

  duyetLyDoReason(id: string, nguoiDuyet: string): string | null {
    const d = this.dongOf(id);
    if (!d?.giaiTrinh) return 'Dòng không có giải trình.';
    if (d.giaiTrinh.trangThai !== 'da-co-ly-do') return 'Chưa có lý do — nhập lý do trước khi duyệt.';
    if (nguoiDuyet === d.giaiTrinh.nguoiNhap) return `Người nhập lý do (${d.giaiTrinh.nguoiNhap}) không được tự duyệt — tách người nhập ≠ người duyệt.`;
    return null;
  }
  /** Đúng 1 trong 2 hướng: tiếp luồng tới Đã chi trả→Đã xử lý HOẶC Đóng có chênh lệch được duyệt. KHÔNG hướng 3. */
  duyetLyDo(id: string, huong: 'tiep-luong' | 'dong', nguoiDuyet: string): { ok: boolean; reason?: string } {
    const reason = this.duyetLyDoReason(id, nguoiDuyet);
    if (reason) return { ok: false, reason };
    const d = this.dongOf(id)!;
    this.patch(id, {
      giaiTrinh: { ...d.giaiTrinh!, trangThai: 'da-duyet', nguoiDuyet, huong },
      ...(huong === 'dong' ? { trangThai: 'dong-chenh-lech-duyet' as InsM07LineState } : {}),
    });
    this.log({ nguoi: nguoiDuyet, hanhDong: huong === 'dong' ? 'Duyệt lý do chênh lệch — Đóng có chênh lệch được duyệt' : 'Duyệt lý do chênh lệch — tiếp luồng tới Đã chi trả → Đã xử lý', doiTuong: id, loai: 'ghi' });
    return { ok: true };
  }

  /* ── hàng đợi Từ chối: 2 đường ra ── */

  /** (a) Sửa & nộp lại → gửi yêu cầu về M05 B4 (lý do + link lần trước) → dòng Chờ nộp lại. */
  suaNopLai(id: string, noiDungSua: string): { ok: boolean; reason?: string } {
    if (!noiDungSua.trim()) return { ok: false, reason: 'Nội dung yêu cầu sửa BẮT BUỘC (gửi về M05 B4).' };
    const d = this.dongOf(id);
    if (d?.trangThai !== 'tu-choi') return { ok: false, reason: 'Chỉ dòng Từ chối mới sửa & nộp lại.' };
    this.patch(id, { trangThai: 'cho-nop-lai', ghiChu: `Đã gửi yêu cầu sửa về M05 B4: ${noiDungSua.trim()}` });
    this.phanHoiM05.update((l) => [{ at: demoNow(), maCase: d.maCase, noiDung: `Yêu cầu sửa/nộp lại (M05 B4): ${noiDungSua.trim()} — link lần nộp trước ${d.maGD}` }, ...l]);
    this.log({ nguoi: this.currentUser, hanhDong: 'Từ chối → Sửa & nộp lại (gửi M05 B4, kèm link lần nộp trước) — dòng → Chờ nộp lại', doiTuong: id, lyDo: noiDungSua.trim(), loai: 'ghi' });
    return { ok: true };
  }

  /** Nộp lại đã ký (M05 B4) → dòng MỚI Chờ duyệt, dòng cũ Đã nộp lại — link 2 chiều, giữ dòng cũ. */
  nhanNopLai(id: string): { ok: boolean; reason?: string; dongMoi?: string } {
    const d = this.dongOf(id);
    if (d?.trangThai !== 'cho-nop-lai') return { ok: false, reason: 'Chỉ dòng Chờ nộp lại mới nhận nộp lại ký.' };
    if (d.linkDongMoi) return { ok: false, reason: `Đã nhận nộp lại (${d.linkDongMoi}) — chạy lại không sinh trùng.` };
    const idMoi = `${d.id}-R2`;
    const cor = insNextCorrelationId();
    const dongMoi: InsM07Dong = {
      ...clone(d), id: idMoi, maGD: `GD-2026-${String(81900 + this.dong().length)}`,
      trangThai: 'cho-duyet', ketQuaDuyet: undefined, giaiTrinh: undefined,
      ngayKyNop: M07_TODAY, soNgayCho: 0, correlationId: cor, phienBan: 1,
      linkDongCu: d.id, linkDongMoi: undefined, ghiChu: `Dòng mới từ nộp lại của ${d.id} (link 2 chiều)`,
    };
    this.patch(id, { trangThai: 'da-nop-lai', linkDongMoi: idMoi });
    this.dongRuntime.update((l) => [...l, dongMoi]);
    this.log({ nguoi: 'Hệ thống', hanhDong: `Nhận nộp lại ký — dòng MỚI ${idMoi} (${cor}), dòng cũ → Đã nộp lại (link 2 chiều)`, doiTuong: id, loai: 'ghi' });
    return { ok: true, dongMoi: idMoi };
  }

  /** (b) Đóng có lý do. */
  dongCoLyDo(id: string, lyDo: string): { ok: boolean; reason?: string } {
    if (!lyDo.trim()) return { ok: false, reason: 'Lý do đóng BẮT BUỘC.' };
    const d = this.dongOf(id);
    if (d?.trangThai !== 'tu-choi') return { ok: false, reason: 'Chỉ dòng Từ chối mới đóng có lý do.' };
    this.patch(id, { trangThai: 'dong-co-ly-do' });
    this.log({ nguoi: this.currentUser, hanhDong: 'Từ chối → Đóng có lý do', doiTuong: id, lyDo: lyDo.trim(), loai: 'ghi' });
    return { ok: true };
  }

  /* ── hàng đợi Thu hồi (M05-FN-14) — phản hồi case gốc; KHÔNG bù trừ vào số chi ── */

  ghiThuHoiXong(id: string, ngayThu: string, soThucThu: string, chungTu: string): { ok: boolean; reason?: string } {
    const t = this.thuHoi().find((x) => x.id === id);
    if (t?.trangThai !== 'cho-thu-hoi') return { ok: false, reason: 'Khoản không ở trạng thái Chờ thu hồi.' };
    if (!ngayThu.trim() || !insParseVnd(soThucThu)) return { ok: false, reason: 'Ngày thu + số thực thu BẮT BUỘC.' };
    this.thuHoi.update((l) => l.map((x) => (x.id === id ? { ...x, trangThai: 'da-thu-hoi', ngayThu, soThucThu: insFormatVnd(insParseVnd(soThucThu)), chungTu: chungTu.trim() || '(chưa có)', phanHoiM05: 'da' } : x)));
    this.phanHoiM05.update((l) => [{ at: demoNow(), maCase: t.caseGoc, noiDung: `Kết quả thu hồi: ĐÃ THU ${insFormatVnd(insParseVnd(soThucThu))} ngày ${ngayThu} (${id}) — KHÔNG bù trừ vào số chi` }, ...l]);
    // UX-3: ghi ngược kết quả thu hồi vào case gốc M05 (giữ trạng thái chi hiện có — chỉ bổ ghi chú)
    this.m05.nhanKetQuaChi(t.caseGoc, this.m05.caseOf(t.caseGoc)?.trangThaiChiM07 ?? 'da-chi-tra',
      `Kết quả thu hồi ${id}: đã thu ${insFormatVnd(insParseVnd(soThucThu))} ngày ${ngayThu} — không bù trừ vào số chi`);
    this.log({ nguoi: this.currentUser, hanhDong: `Ghi kết quả Đã thu hồi (${insFormatVnd(insParseVnd(soThucThu))}) — phản hồi tự động case gốc ${t.caseGoc}; KHÔNG bù trừ vào số chi`, doiTuong: id, loai: 'ghi' });
    return { ok: true };
  }

  /** Không thu hồi được = lý do DANH MỤC + duyệt (người duyệt ≠ người ghi). */
  ghiKhongThuHoi(id: string, lyDo: string, nguoiDuyet: string): { ok: boolean; reason?: string } {
    const t = this.thuHoi().find((x) => x.id === id);
    if (t?.trangThai !== 'cho-thu-hoi') return { ok: false, reason: 'Khoản không ở trạng thái Chờ thu hồi.' };
    if (!lyDo.trim()) return { ok: false, reason: 'Không thu hồi được = lý do theo DANH MỤC (M08) — bắt buộc.' };
    if (nguoiDuyet === this.currentUser) return { ok: false, reason: 'Người ghi không được tự duyệt — chọn người duyệt khác.' };
    this.thuHoi.update((l) => l.map((x) => (x.id === id ? { ...x, trangThai: 'khong-thu-hoi-duoc', lyDoKhongThu: lyDo.trim(), nguoiDuyet, phanHoiM05: 'da' } : x)));
    this.phanHoiM05.update((l) => [{ at: demoNow(), maCase: t.caseGoc, noiDung: `Kết quả thu hồi: KHÔNG THU HỒI ĐƯỢC (${lyDo.trim()}, duyệt: ${nguoiDuyet})` }, ...l]);
    // UX-3: ghi ngược kết quả thu hồi vào case gốc M05 (giữ trạng thái chi hiện có — chỉ bổ ghi chú)
    this.m05.nhanKetQuaChi(t.caseGoc, this.m05.caseOf(t.caseGoc)?.trangThaiChiM07 ?? 'da-chi-tra',
      `Kết quả thu hồi ${id}: KHÔNG thu hồi được (${lyDo.trim()}, duyệt: ${nguoiDuyet})`);
    this.log({ nguoi: nguoiDuyet, hanhDong: `Duyệt Không thu hồi được — phản hồi case gốc ${t.caseGoc}`, doiTuong: id, lyDo: lyDo.trim(), loai: 'ghi' });
    return { ok: true };
  }

  /* ── hàng đợi Chi hỏng — đủ N lần, 2 đường ra (GIỮ nhãn Q12·Q101) ── */

  chiHongDuongRaReason(id: string): string | null {
    const c = this.chiHong().find((x) => x.id === id);
    if (!c) return 'Không tìm thấy khoản chi hỏng.';
    if (c.trangThai !== 'cho-quyet-dinh') return 'Khoản đã chọn đường ra.';
    if (c.lichSuThatBai.length < c.nguongN) return `Chưa đủ N=${c.nguongN} lần thất bại (M08) — chưa vào diện quyết định.`;
    return null;
  }
  /** (a) chi phương thức khác (đã xác nhận NLĐ/ủy quyền) · (b) hoàn trả cơ quan (chứng từ + duyệt) → phản hồi M05. */
  chonDuongRaChiHong(id: string, duongRa: 'phuong-thuc-khac' | 'hoan-tra', ctx: { xacNhanNLD?: string; chungTu?: string; nguoiDuyet?: string }): { ok: boolean; reason?: string } {
    const reason = this.chiHongDuongRaReason(id);
    if (reason) return { ok: false, reason };
    const c = this.chiHong().find((x) => x.id === id)!;
    const d = this.dongOf(c.dongId);
    if (duongRa === 'phuong-thuc-khac') {
      if (!ctx.xacNhanNLD?.trim()) return { ok: false, reason: 'Đường ra (a) cần xác nhận NLĐ/ủy quyền hợp lệ.' };
      this.chiHong.update((l) => l.map((x) => (x.id === id ? { ...x, trangThai: 'da-chi-phuong-thuc-khac', duongRa, xacNhanNLD: ctx.xacNhanNLD!.trim() } : x)));
      if (d) this.patch(d.id, { soLanChiHong: 0, ghiChu: `Chi lại bằng phương thức khác (xác nhận NLĐ: ${ctx.xacNhanNLD.trim()}) — ${M07_CHIP_Q12_Q101}`, hinhThucChi: 'Phương thức khác (đã xác nhận NLĐ)' });
      this.log({ nguoi: this.currentUser, hanhDong: `Chi hỏng — đường ra (a) chi phương thức khác · ${M07_CHIP_Q12_Q101}`, doiTuong: id, loai: 'ghi' });
      return { ok: true };
    }
    if (!ctx.chungTu?.trim()) return { ok: false, reason: 'Đường ra (b) hoàn trả cơ quan cần CHỨNG TỪ hoàn trả.' };
    if (!ctx.nguoiDuyet || ctx.nguoiDuyet === this.currentUser) return { ok: false, reason: 'Hoàn trả cần người duyệt ≠ người ghi.' };
    this.chiHong.update((l) => l.map((x) => (x.id === id ? { ...x, trangThai: 'da-hoan-tra', duongRa, chungTuHoanTra: ctx.chungTu!.trim(), nguoiDuyet: ctx.nguoiDuyet, phanHoiM05: 'da' } : x)));
    if (d) {
      this.patch(d.id, { trangThai: 'da-hoan-tra-co-quan', ghiChu: `Đã hoàn trả cơ quan (${ctx.chungTu.trim()}, duyệt: ${ctx.nguoiDuyet}) — ${M07_CHIP_Q12_Q101}` });
      this.phanHoiM05.update((l) => [{ at: demoNow(), maCase: d.maCase, noiDung: `Kết quả chi cuối: Không chi trả (đã hoàn trả cơ quan — ${id})` }, ...l]);
      // UX-3: GHI NGƯỢC trạng thái chi cuối vào case M05 (ghi-xuyên Phase E)
      this.m05.nhanKetQuaChi(d.maCase, 'khong-chi-tra', `Hoàn trả cơ quan ${ctx.chungTu.trim()} (chi hỏng ${id}, duyệt: ${ctx.nguoiDuyet})`);
    }
    this.log({ nguoi: ctx.nguoiDuyet, hanhDong: `Chi hỏng — đường ra (b) hoàn trả cơ quan (${ctx.chungTu.trim()}) · ${M07_CHIP_Q12_Q101}`, doiTuong: id, loai: 'ghi' });
    return { ok: true };
  }

  /* ── Đề nghị thanh toán (maker-checker) — KHÔNG hạch toán, KHÔNG chuyển tiền ── */

  deNghiReason(dongId: string): string | null {
    const d = this.dongOf(dongId);
    if (!d) return 'Không tìm thấy dòng.';
    if (d.trangThai !== 'tien-da-ve') return `Chỉ dòng Tiền đã về được lập đề nghị (hiện: ${M07_STATE_LABEL[d.trangThai]}).`;
    if (d.deNghiMa) {
      const dn = this.deNghi().find((x) => x.ma === d.deNghiMa);
      if (dn && dn.trangThai !== 'tra-lai') return `Dòng đã nằm trong đề nghị hiệu lực ${d.deNghiMa} — 1 dòng 1 đề nghị hiệu lực.`;
    }
    if (this.chiHongMo().some((c) => c.dongId === dongId)) return 'Dòng đang trong hàng đợi Chi hỏng — chọn đường ra trước.';
    return null;
  }
  /** Số đề nghị thanh toán = ĐÚNG số duyệt (khác → lý do + duyệt — demo không mở nhánh này). */
  lapDeNghi(dongIds: string[], kyChi: string): { done: number; skipped: { id: string; reason: string }[]; ma?: string } {
    const skipped: { id: string; reason: string }[] = [];
    const ok: string[] = [];
    for (const id of dongIds) {
      const r = this.deNghiReason(id);
      r ? skipped.push({ id, reason: r }) : ok.push(id);
    }
    if (!ok.length) return { done: 0, skipped };
    const tong = insFormatVnd(ok.reduce((s, id) => s + insParseVnd(m07SoDuyet(this.dongOf(id)!) ?? ''), 0));
    const ma = `DN-2026-${String(this.deNghi().length + 1).padStart(3, '0')}`;
    this.deNghi.update((l) => [...l, { ma, hinhThuc: 'Chuyển khoản — đơn vị chi hộ', kyChi, dongIds: ok, tongTien: tong, nguoiLap: this.currentUser, trangThai: 'cho-duyet', phienBan: 1 }]);
    ok.forEach((id) => this.patch(id, { trangThai: 'da-de-nghi', deNghiMa: ma }));
    this.log({ nguoi: this.currentUser, hanhDong: `Lập đề nghị thanh toán ${ma} (${ok.length} NLĐ · ${tong}) — số đề nghị = ĐÚNG số duyệt; KHÔNG hạch toán/chuyển tiền`, doiTuong: ma, loai: 'ghi' });
    return { done: ok.length, skipped, ma };
  }

  duyetDeNghi(ma: string, nguoiDuyet: string): { ok: boolean; reason?: string } {
    const dn = this.deNghi().find((x) => x.ma === ma);
    if (dn?.trangThai !== 'cho-duyet') return { ok: false, reason: 'Đề nghị không ở trạng thái Chờ duyệt.' };
    if (nguoiDuyet === dn.nguoiLap) return { ok: false, reason: `Người lập (${dn.nguoiLap}) không được tự duyệt — maker ≠ checker.` };
    this.deNghi.update((l) => l.map((x) => (x.ma === ma ? { ...x, trangThai: 'da-duyet', nguoiDuyet } : x)));
    this.log({ nguoi: nguoiDuyet, hanhDong: `Duyệt đề nghị ${ma} — đã duyệt BẤT BIẾN, điều chỉnh = phiên bản mới`, doiTuong: ma, loai: 'ghi' });
    return { ok: true };
  }

  /** BQA-21: Kế toán trả lại MỘT PHẦN/toàn bộ → sinh đề nghị PHIÊN BẢN MỚI; bản Đã duyệt cũ GIỮ
   *  NGUYÊN trong lịch sử (bất biến — xem được, gắn `thayTheBoi`). Dòng bị trả về `Tiền đã về`;
   *  dòng còn lại đi tiếp trong phiên bản mới (Chờ duyệt lại — maker ≠ checker). */
  traLaiDeNghi(ma: string, lyDo: string, dongIdsTraLai?: string[]): { ok: boolean; reason?: string; maMoi?: string } {
    if (!lyDo.trim()) return { ok: false, reason: 'Lý do trả lại BẮT BUỘC.' };
    const dn = this.deNghi().find((x) => x.ma === ma);
    if (!dn || (dn.trangThai !== 'cho-duyet' && dn.trangThai !== 'da-duyet')) return { ok: false, reason: 'Đề nghị không trả lại được ở trạng thái hiện tại.' };
    if (dn.thayTheBoi) return { ok: false, reason: `Đề nghị đã được thay bằng ${dn.thayTheBoi} — thao tác trên phiên bản mới.` };
    const traLai = (dongIdsTraLai?.length ? dongIdsTraLai : dn.dongIds).filter((x) => dn.dongIds.includes(x));
    if (!traLai.length) return { ok: false, reason: 'Chưa chọn dòng nào để trả lại.' };
    const conLai = dn.dongIds.filter((x) => !traLai.includes(x));
    const maMoi = `${ma}-v${dn.phienBan + 1}`;
    const tongConLai = insFormatVnd(conLai.reduce((s, x) => s + insParseVnd(m07SoDuyet(this.dongOf(x)!) ?? ''), 0));
    const banMoi: InsM07DeNghi = {
      ...dn, ma: maMoi, phienBan: dn.phienBan + 1, dongIds: conLai, tongTien: tongConLai,
      trangThai: conLai.length ? 'cho-duyet' : 'tra-lai',
      nguoiDuyet: undefined, lyDoTraLai: lyDo.trim(),
      ketQuaKeToan: `Kế toán trả lại ${traLai.length}/${dn.dongIds.length} dòng: ${lyDo.trim()}`,
      phienBanCua: ma, thayTheBoi: undefined,
    };
    this.deNghi.update((l) => [
      ...l.map((x) => (x.ma === ma
        ? { ...x, thayTheBoi: maMoi, ...(x.trangThai === 'cho-duyet' ? { trangThai: 'tra-lai' as const, lyDoTraLai: lyDo.trim() } : {}) }
        : x)),
      banMoi,
    ]);
    for (const idD of traLai) {
      const d = this.dongOf(idD);
      if (d?.trangThai === 'da-de-nghi') this.patch(idD, { trangThai: 'tien-da-ve', deNghiMa: undefined });
    }
    for (const idD of conLai) this.patch(idD, { deNghiMa: maMoi });
    this.log({ nguoi: this.currentUser, hanhDong: `Kế toán trả lại ${traLai.length}/${dn.dongIds.length} dòng của ${ma} — sinh PHIÊN BẢN MỚI ${maMoi}${dn.trangThai === 'da-duyet' ? ' (bản Đã duyệt cũ giữ nguyên lịch sử, xem được)' : ''}; dòng bị trả về Tiền đã về, dòng còn lại đi tiếp`, doiTuong: ma, lyDo: lyDo.trim(), loai: 'ghi' });
    return { ok: true, maMoi };
  }

  /* ── Xác nhận chi & đóng — cấp TỪNG NLĐ ── */

  xacNhanChiReason(id: string): string | null {
    const d = this.dongOf(id);
    if (!d) return 'Không tìm thấy dòng.';
    if (d.trangThai === 'da-de-nghi') {
      const dn = this.deNghi().find((x) => x.ma === d.deNghiMa);
      if (dn?.trangThai !== 'da-duyet') return `Đề nghị ${d.deNghiMa} chưa được duyệt — chưa xác nhận chi được.`;
      return null;
    }
    if (d.trangThai === 'tien-da-ve') {
      if (this.chiHongMo().some((c) => c.dongId === id)) return 'Dòng đang trong hàng đợi Chi hỏng — chọn đường ra trước.';
      return null; // hình thức cơ quan chi thẳng NLĐ (màn rút gọn — không qua đề nghị, OQ m07.md)
    }
    return `Chỉ xác nhận chi dòng Tiền đã về / Đã đề nghị được duyệt (hiện: ${M07_STATE_LABEL[d.trangThai]}).`;
  }
  /** Ngày chi BẮT BUỘC; thông báo NLĐ mọi lần CÓ LOG; số đã chi mặc định = số duyệt. */
  xacNhanChi(id: string, ngayChi: string, hinhThuc: string, soDaChi?: string): { ok: boolean; reason?: string } {
    const reason = this.xacNhanChiReason(id);
    if (reason) return { ok: false, reason };
    if (!ngayChi.trim()) return { ok: false, reason: 'Ngày chi BẮT BUỘC.' };
    const d = this.dongOf(id)!;
    const so = soDaChi && insParseVnd(soDaChi) ? insFormatVnd(insParseVnd(soDaChi)) : m07SoDuyet(d) ?? '';
    const lech = insParseVnd(so) !== insParseVnd(m07SoDuyet(d) ?? '');
    this.patch(id, {
      trangThai: 'da-chi-tra', ngayChi, soDaChi: so,
      hinhThucChi: hinhThuc || 'Chuyển khoản — đơn vị chi hộ', chungTuChi: `UNC-2026-${ngayChi.replace(/\//g, '').slice(0, 4)}-${d.id.slice(-3)}`,
      xacNhanNLD: `Đã thông báo NLĐ ${ngayChi} (loại · tiền · ngày · kênh khiếu nại — có log)`,
      giaiTrinh: lech ? { trangThai: 'can-xu-ly' } : d.giaiTrinh,
    });
    // UX-3: GHI NGƯỢC trạng thái chi vào case M05 (ghi-xuyên Phase E — thay tiền lệ A-M05)
    this.m05.nhanKetQuaChi(d.maCase, 'da-chi-tra', `M07 xác nhận chi ${so} ngày ${ngayChi} (dòng ${d.id})`);
    this.log({ nguoi: this.currentUser, hanhDong: `Xác nhận chi từng NLĐ (${so} — Đã thực hiện) + gửi thông báo NLĐ (ghi log)${lech ? ' — lệch số duyệt → vào hàng đợi Chênh lệch' : ''}`, doiTuong: id, loai: 'ghi' });
    return { ok: true };
  }

  /** Đóng theo dõi: (duyệt − đã chi) = 0 HOẶC ≠ 0 nhưng lý do đã duyệt. Đóng = bất biến. */
  dongTheoDoiReason(id: string): string | null {
    const d = this.dongOf(id);
    if (!d) return 'Không tìm thấy dòng.';
    if (d.trangThai !== 'da-chi-tra') return `Chỉ đóng dòng Đã chi trả (hiện: ${M07_STATE_LABEL[d.trangThai]}).`;
    const h1 = m07HieuSo1(d), h2 = m07HieuSo2(d);
    if ((h1.num !== 0 || h2.num !== 0) && d.giaiTrinh?.trangThai !== 'da-duyet') {
      const phan = h1.num !== 0 ? `(đề nghị − duyệt) = ${h1.str}` : `(duyệt − đã chi) = ${h2.str}`;
      return `Hiệu số ${phan} ≠ 0 — bắt buộc lý do ĐƯỢC DUYỆT trước khi đóng.`;
    }
    return null;
  }
  dongTheoDoi(id: string): { ok: boolean; reason?: string } {
    const reason = this.dongTheoDoiReason(id);
    if (reason) return { ok: false, reason };
    const d = this.dongOf(id)!;
    this.patch(id, { trangThai: 'da-xu-ly' });
    // cả hồ sơ chi xong → trả kết quả chi cuối về M05: log phản hồi + GHI NGƯỢC case (UX-3 Phase E)
    this.phanHoiM05.update((l) => [{ at: demoNow(), maCase: d.maCase, noiDung: 'Kết quả chi cuối: Đã chi trả — đủ điều kiện đóng case M05' }, ...l]);
    this.m05.nhanKetQuaChi(d.maCase, 'da-chi-tra', `Kết quả chi cuối: Đã chi trả — dòng ${d.id} đóng theo dõi (bất biến)`);
    this.log({ nguoi: this.currentUser, hanhDong: 'Đóng theo dõi (bất biến) — trả kết quả chi cuối về M05 (ghi ngược trạng thái chi)', doiTuong: id, loai: 'ghi' });
    return { ok: true };
  }

  /** Mở lại = lý do + PHIÊN BẢN MỚI (không sửa bản đã đóng). */
  moLai(id: string, lyDo: string): { ok: boolean; reason?: string } {
    if (!lyDo.trim()) return { ok: false, reason: 'Mở lại = lý do BẮT BUỘC + phiên bản mới.' };
    const d = this.dongOf(id);
    if (d?.trangThai !== 'da-xu-ly') return { ok: false, reason: 'Chỉ mở lại dòng Đã xử lý.' };
    this.patch(id, { trangThai: 'can-xu-ly', phienBan: d.phienBan + 1 });
    this.log({ nguoi: this.currentUser, hanhDong: `Mở lại dòng — PHIÊN BẢN MỚI (v${d.phienBan + 1}); bản đã đóng giữ nguyên`, doiTuong: id, lyDo: lyDo.trim(), loai: 'ghi' });
    return { ok: true };
  }

  /** Thu hồi hồ sơ trước khi có kết quả → hủy CÓ LÝ DO, không xóa. */
  huyTruocKetQua(id: string, lyDo: string): { ok: boolean; reason?: string } {
    if (!lyDo.trim()) return { ok: false, reason: 'Hủy = lý do BẮT BUỘC (không xóa dòng).' };
    const d = this.dongOf(id);
    if (d?.trangThai !== 'cho-duyet') return { ok: false, reason: 'Chỉ hủy dòng Chờ duyệt (thu hồi trước kết quả).' };
    this.patch(id, { trangThai: 'huy' });
    this.log({ nguoi: this.currentUser, hanhDong: 'Thu hồi hồ sơ trước kết quả — hủy có lý do (không xóa)', doiTuong: id, lyDo: lyDo.trim(), loai: 'ghi' });
    return { ok: true };
  }

  /* ── Bulk generic (select hành động + chạy + retry idempotent phần lỗi) ── */

  bulkSkipReason(action: M07BulkAction, id: string): string | null {
    switch (action) {
      case 'ghi-ket-qua': return this.ghiKetQuaReason(id);
      case 'lap-de-nghi': return this.deNghiReason(id);
      case 'xac-nhan-chi': return this.xacNhanChiReason(id);
      case 'dong-theo-doi': return this.dongTheoDoiReason(id);
      case 'ket-xuat': return null; // xuất dùng cơ chế M07-B — không chặn theo dòng
    }
  }
  bulkPreview(action: M07BulkAction, ids: string[]): { eligible: number; blocked: { reason: string; count: number }[] } {
    const map = new Map<string, number>();
    let eligible = 0;
    for (const id of ids) {
      const r = this.bulkSkipReason(action, id);
      r ? map.set(r, (map.get(r) ?? 0) + 1) : eligible++;
    }
    return { eligible, blocked: [...map.entries()].map(([reason, count]) => ({ reason, count })) };
  }
  /** Partial success {done, skipped[]} — chạy lại CHỈ phần lỗi, không sinh trùng (bất biến #4). */
  bulkRun(action: M07BulkAction, ids: string[]): { done: number; skipped: { id: string; reason: string }[] } {
    if (action === 'lap-de-nghi') {
      const r = this.lapDeNghi(ids, 'Kỳ chi 08/2026 — đợt 3');
      this.lastBulk.set({ action, skipped: r.skipped });
      return { done: r.done, skipped: r.skipped };
    }
    const skipped: { id: string; reason: string }[] = [];
    let done = 0;
    for (const id of ids) {
      const reason = this.bulkSkipReason(action, id);
      if (reason) { skipped.push({ id, reason }); continue; }
      switch (action) {
        case 'ghi-ket-qua': this.ghiKetQua(id, { nguon: 'cong-thong-tin', tep: `KQ-LO-${id}.pdf` }); break;
        case 'xac-nhan-chi': this.xacNhanChi(id, M07_TODAY, 'Chuyển khoản — đơn vị chi hộ'); break;
        case 'dong-theo-doi': this.dongTheoDoi(id); break;
        case 'ket-xuat': break; // điều hướng sang B do màn hình xử lý
      }
      done++;
    }
    this.lastBulk.set({ action, skipped });
    if (action !== 'ket-xuat') this.log({ nguoi: this.currentUser, hanhDong: `Bulk ${M07_BULK_LABEL[action]}: ${done}/${ids.length} dòng (partial + retry idempotent)`, doiTuong: ids.join(', '), loai: 'ghi' });
    return { done, skipped };
  }

  /* ═════════ M07-B: lần chạy · tệp xuất · kiểm tra 66 chỉ tiêu ═════════ */

  readonly tepXuat = signal<InsM07TepXuat[]>(clone(TEP_SEED));
  readonly ktPhienBan = signal<InsM07KtPhienBan[]>(ktSeed());
  /** Đồng bộ 66 chỉ tiêu: không chạy song song cùng kỳ. */
  readonly ktDangChay = signal(false);

  /** Tạo tệp xuất: 3 chốt chặn (biểu mẫu + dữ liệu + quyền xuất) do màn hình guard; vòng đời từ Đang tạo. */
  taoTepXuat(ten: string, bieuMau: string, phienBanMau: string, phamVi: string): string {
    const id = `TEP-2026-08-${String(this.tepXuat().length + 1).padStart(2, '0')}`;
    const at = demoNow();
    this.tepXuat.update((l) => [{ id, ten, bieuMau, phienBanMau, phamVi, trangThai: 'dang-tao', taoLuc: at, hetHanLuc: '22/08/2026 (retention 3 ngày — OQ)', soLanTai: 0 }, ...l]);
    this.log({ nguoi: this.currentUser, hanhDong: `Xuất tệp "${ten}" (${bieuMau} · ${phienBanMau}) — tệp mang ngữ cảnh + phiên bản`, doiTuong: id, loai: 'xuat' });
    return id;
  }
  tepSanSang(id: string): void {
    this.tepXuat.update((l) => l.map((t) => (t.id === id && t.trangThai === 'dang-tao' ? { ...t, trangThai: 'san-sang' } : t)));
  }
  /** Tải tệp — TẢI LẠI CŨNG GHI 1 DÒNG NHẬT KÝ. */
  taiTep(id: string): { ok: boolean; reason?: string } {
    const t = this.tepXuat().find((x) => x.id === id);
    if (!t) return { ok: false, reason: 'Không tìm thấy tệp.' };
    if (t.trangThai === 'dang-tao') return { ok: false, reason: 'Tệp đang tạo — chưa tải được.' };
    if (t.trangThai === 'het-han') return { ok: false, reason: 'Tệp đã hết hạn — chạy lại báo cáo để xuất tệp mới.' };
    this.tepXuat.update((l) => l.map((x) => (x.id === id ? { ...x, soLanTai: x.soLanTai + 1 } : x)));
    this.log({ nguoi: this.currentUser, hanhDong: `Tải tệp ${t.ten} (lần ${t.soLanTai + 1}) — tải lại cũng ghi 1 dòng nhật ký`, doiTuong: id, loai: 'xuat' });
    return { ok: true };
  }

  /** Chạy kiểm tra 66 chỉ tiêu = PHIÊN BẢN KẾT QUẢ MỚI (không chạy song song cùng kỳ). */
  chayKiemTra(): { ok: boolean; reason?: string; id?: string } {
    if (this.ktDangChay()) return { ok: false, reason: 'Đang có lần chạy cùng kỳ — không chạy song song.' };
    const last = this.ktPhienBan()[this.ktPhienBan().length - 1];
    const next = clone(last);
    next.id = `KT-2026-08-v${this.ktPhienBan().length + 1}`;
    next.chayLuc = demoNow();
    next.nguoiChay = this.currentUser;
    // phiên bản mới lệch 2 ô so với bản trước (dữ liệu nguồn thay đổi trong ngày — demo deterministic)
    next.chiTieu[0].thang[11] = String(insParseVnd(next.chiTieu[0].thang[11]) + 2);
    next.chiTieu[7].thang[11] = insFormatVnd(insParseVnd(next.chiTieu[7].thang[11]) + 6);
    this.ktPhienBan.update((l) => [...l, next]);
    this.log({ nguoi: this.currentUser, hanhDong: `Chạy Kiểm tra dữ liệu theo kỳ lương — phiên bản kết quả MỚI ${next.id} (bộ 66 chỉ tiêu)`, doiTuong: next.id, loai: 'ghi' });
    return { ok: true, id: next.id };
  }
}
