import { ChangeDetectionStrategy, Component, TemplateRef, afterNextRender, computed, inject, input, linkedSignal, output, signal, viewChild } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { HrmAlert, HrmButton, HrmInput, HrmMessageService, HrmOption, HrmSelect, HrmTag, HrmTextarea, HrmTimeline, HrmTimelineItem } from 'hrm-ui';
import { InsDiff, InsLayerBadge, InsSectionLabel, InsSlaChip } from '../_shared';
import { INS_KY_LABEL, InsShellStore, insKy, insNhanVien } from '../_data/_core';
import {
  INS_BAN_GIAO_LABEL, INS_CHANGE_KIND_LABEL, INS_DATADICT, INS_DICT_NHOM_LABEL, INS_DICT_TAG_LABEL, INS_EXCEPTION_LABEL, INS_FLOW_LABEL,
  INS_KET_LUAN_DESC, INS_KET_LUAN_LABEL, INS_MOVEMENT_REASON_LABEL, INS_NGUOI_NHAN_OPTIONS, InsBanGiaoKind, InsChange, InsChangeKind, InsDictField, InsDictNhomNguon, InsDictTag,
  InsM02Store, insClassify, insDoiSoat6, insDoiSoatPass, insKetLuan, insNguyenNhanNgan, insNhanPhuongAn, insQuyAnhHuong, insSlaView,
} from '../_data/_m02-data';
import { M02Outcome, M02_EXCEPTION_OUTCOMES } from './_m02-columns';
import {
  TablerIconComponent, IconCheck, IconCircleCheck, IconAlertTriangle, IconSparkles, IconLock,
  IconArrowRight, IconChevronDown, IconChevronUp, IconExternalLink, IconArrowUp, IconArrowDown, IconMinus,
} from '@tabler/icons-angular';

/** §10 Nhãn nguồn (provenance) thuần Việt tự-diễn-giải cho panel — không lộ enum SOURCE/DERIVED. */
const INS_PROVENANCE_VN: Record<InsDictTag, string> = {
  SOURCE: 'lấy từ hồ sơ',
  DERIVED: 'hệ thống tự tính',
  AI: 'trợ lý gợi ý',
  HR_INPUT: 'do người nhập',
  SYSTEM: 'hệ thống ghi',
};

/** Options select "nơi nhận" bàn giao — nghiệp vụ/bộ phận nguồn (dùng cho Trả nguồn sửa; Yêu cầu bổ sung thêm owner của dòng). */
const INS_NGUOI_NHAN_SELECT: HrmOption[] = INS_NGUOI_NHAN_OPTIONS.map((o) => ({ label: o, value: o }));

/** M02 — panel chi tiết dòng biến động = DECISION SUPPORT PANEL (đọc ít, quyết nhanh).
 *  Cấu trúc: [Header] NLĐ · phòng ban · NHÃN CHÍNH = mã phương án dẫn dắt ("Loại — Lý do (Mã)") + quỹ
 *  ảnh hưởng + nhãn màu loại/cách nộp/hạn + link Hồ sơ 360 (M06)
 *  → ✨ AI đề xuất (đề xuất + độ tin cậy, bấm mở cách tính) → Vì sao (lý do có cấu trúc ✓/⚠) →
 *  Dữ liệu nguồn (nguồn sự kiện · thời điểm phát hiện · ngày hiệu lực + field theo loại) → Trước→Sau
 *  (số dự kiến nội bộ) → Hệ thống sẽ xử lý (kỳ · đợt) → Căn cứ pháp lý (quy tắc vẫn là căn cứ) →
 *  Lịch sử append-only. Dòng còn ngoại lệ mở thêm khối "Đường ra ngoại lệ" (7 hàng PBI-02.01.17).
 *  Kỳ khóa/đối tượng khóa → chỉ đọc + thông báo NGUYÊN VĂN "Đối tượng đã bị khóa." — hành động ghi
 *  chạy qua transition store (UI không tự suy luận). Đã BỎ block "Nguồn gốc & truy vết" (mã chống
 *  trùng/mã liên kết/3 mốc/kỳ tác động/mã phương án) — không thuộc tài liệu yêu cầu. */
@Component({
  selector: 'ins-m02-detail-panel',
  imports: [FormsModule, HrmAlert, HrmButton, HrmInput, HrmSelect, HrmTextarea, HrmTag, HrmTimeline, TablerIconComponent, InsDiff, InsLayerBadge, InsSectionLabel, InsSlaChip],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (change(); as c) {
      <!-- Khóa: đối tượng khóa tháng (nguyên văn PBI) / kỳ tác động đã khóa → chỉ đọc -->
      @if (c.doiTuongKhoa) {
        <hrm-alert class="pn__alert" type="error" message="Đối tượng đã bị khóa."
          description="Đối tượng khóa tháng — panel chỉ đọc; theo dõi mở khóa tại M04." />
      } @else if (kyLocked()) {
        <hrm-alert class="pn__alert" type="warning" [message]="kyLockedLabel()"
          description="Phần thuộc kỳ đã khóa chuyển chỉ đọc — hồi tố ghi sổ điều chỉnh bất biến." />
      }

      <!-- Header — người lao động · phòng ban + link Hồ sơ 360 (M06) · loại biến động · lý do -->
      <div class="pn__head">
        <div class="pn__head-id">
          <span class="pn__head-nv">{{ nvView() }}</span>
          @if (deptView(); as d) { <span class="pn__head-dept">{{ d }}</span> }
          <button type="button" class="pn__link" (click)="go360()">Hồ sơ 360 <tabler-icon [icon]="iExternalLink" [size]="13" /></button>
        </div>
        <!-- §6 Nhãn chính = mã phương án dẫn dắt (full = "Loại — Lý do (Mã)"); lý do làm mô tả kèm -->
        <div class="pn__head-pa">{{ paLabel().full }}</div>
        <div class="pn__head-tags">
          <hrm-tag [color]="c.loaiBienDong === 'tang' ? 'green' : c.loaiBienDong === 'giam' ? 'red' : 'blue'" size="sm">{{ kindLabel() }}</hrm-tag>
          <hrm-tag [color]="c.nhanLuong === 'su-vu' ? 'purple' : c.nhanLuong === 'd02-lt' ? 'blue' : 'orange'" size="sm" variant="lighter">{{ flowLabel() }}</hrm-tag>
          <ins-sla-chip [label]="sla().label" [tone]="sla().tone" />
        </div>
        <p class="pn__head-quy">Quỹ ảnh hưởng: <b>{{ quyAnhHuong() }}</b></p>
        <p class="pn__head-desc">{{ c.moTa }}</p>
        @if (c.truoc || c.sau) { <ins-diff [before]="c.truoc || ''" [after]="c.sau || ''" /> }
      </div>

      <!-- ĐÃ CHUYỂN XỬ LÝ — dòng đã bàn giao chéo (yêu cầu bổ sung / trả nguồn) đang chờ bên nhận phản hồi -->
      @if (c.banGiao; as bg) {
        <section class="pn__sec pn__handoff">
          <div class="pn__handoff-head">
            <span class="pn__handoff-lb">Đã chuyển xử lý</span>
            <hrm-tag color="orange" variant="lighter" size="sm">{{ banGiaoLabel(bg.kind) }}</hrm-tag>
          </div>
          <div class="pn__handoff-body">
            <div class="pn__row"><span class="pn__k">Nơi nhận</span><span class="pn__v"><b>{{ bg.nguoiNhan }}</b></span></div>
            @if (bg.hanPhanHoi) {
              <div class="pn__row"><span class="pn__k">Hạn phản hồi</span><span class="pn__v pn__handoff-han">{{ bg.hanPhanHoi }}</span></div>
            }
            @if (bg.lyDo) {
              <div class="pn__row"><span class="pn__k">Nội dung</span><span class="pn__v">{{ bg.lyDo }}</span></div>
            }
            <div class="pn__row"><span class="pn__k">Đã chuyển</span><span class="pn__v">{{ bg.at }}</span></div>
          </div>
          <div class="pn__handoff-act">
            @if (bg.hanPhanHoi && !bg.nhac) {
              <hrm-button size="sm" [disabled]="locked()" (click)="nhacBanGiao()">Nhắc bên nhận</hrm-button>
            } @else if (bg.nhac) {
              <hrm-tag color="blue" variant="lighter" size="sm">Đã nhắc</hrm-tag>
            }
            <hrm-button size="sm" [disabled]="locked()" (click)="thuHoiBanGiao()">Thu hồi bàn giao</hrm-button>
          </div>
        </section>
      }

      <!-- 【1】 VIỆC CẦN LÀM — LÊN NGAY SAU HEADER: kết luận (6) + nút chính GATED + Cách gỡ (cơ chế 7 đường ra) -->
      <section class="pn__sec pn__todo">
        <span class="pn__todo-lb">Việc cần làm</span>
        <div class="pn__kl" [attr.data-kl]="ketLuan()">
          <span class="pn__kl-chip">{{ ketLuanLabel() }}</span>
          <span class="pn__kl-desc">{{ ketLuanDesc() }}</span>
        </div>
        <!-- Cách gỡ: cơ chế thực thi (7 đường ra + 14 loại vướng) — chỉ khi dòng còn nhóm ngoại lệ mở -->
        @if (showOutcomes()) {
          <div class="pn__exc-head">
            <span class="pn__cachgo-lb">Cách gỡ</span>
            @for (g of c.nhomNgoaiLe; track g) { <hrm-tag color="orange" variant="lighter" size="sm">{{ excLabel(g) }}</hrm-tag> }
            <span class="pn__exc-han">Hạn phản hồi: <b>{{ c.ngayHanXuLy || '—' }}</b> <ins-sla-chip [label]="sla().label" [tone]="sla().tone" /></span>
          </div>
          <div class="pn__outcomes">
            @for (o of outcomes(); track o.stt) {
              <div class="pn__outcome" [class.pn__outcome--hit]="o.hit">
                <span class="pn__outcome-stt">{{ o.stt }}</span>
                <div class="pn__outcome-body">
                  <span class="pn__outcome-name">{{ o.duongRa }}</span>
                  <span class="pn__outcome-desc">{{ o.moTa }}</span>
                  @if (o.hit) {
                    <div class="pn__outcome-actions">
                      <hrm-button size="sm" [disabled]="locked() && isMutating(o.actionKey)" (click)="runOutcome(o, false)">{{ o.actionLabel }}</hrm-button>
                      @if (o.extraLabel) {
                        <hrm-button size="sm" [disabled]="locked()" (click)="runOutcome(o, true)">{{ o.extraLabel }}</hrm-button>
                      }
                    </div>
                  }
                </div>
              </div>
            }
          </div>
        }

        <!-- Bàn giao — FORM "Yêu cầu bổ sung" (đích + người nhận + hạn) mở từ đường ra 'Yêu cầu bổ sung' -->
        @if (yeuCauOpen()) {
          <div class="pn__form">
            <div class="pn__form-hd">Yêu cầu bổ sung</div>
            <label class="pn__field">
              <span class="pn__field-lb">Gửi đến</span>
              <hrm-select [(ngModel)]="yeuCauNguoiNhan" [options]="yeuCauNguoiNhanOptions()" placeholder="Chọn nơi nhận" [allowClear]="false" size="sm" />
            </label>
            <label class="pn__field">
              <span class="pn__field-lb">Hạn phản hồi (dd/MM/yyyy)</span>
              <hrm-input [(ngModel)]="yeuCauHan" placeholder="VD 25/08/2026" size="sm" />
            </label>
            <label class="pn__field">
              <span class="pn__field-lb">Nội dung yêu cầu (tùy chọn)</span>
              <hrm-textarea [(ngModel)]="yeuCauLyDo" placeholder="Nêu rõ cần bổ sung gì…" [minRows]="2" />
            </label>
            <div class="pn__form-act">
              <hrm-button size="sm" variant="primary" [disabled]="locked()" (click)="guiYeuCau()">Gửi yêu cầu</hrm-button>
              <hrm-button size="sm" (click)="huyYeuCau()">Hủy</hrm-button>
            </div>
          </div>
        }
      </section>

      <!-- 【2】 ĐỐI SOÁT NHANH VỚI CƠ QUAN BHXH — 6 điểm soát (SC-02 §12); pass → gập 1 dòng, còn vướng → tự bung (⚠ trước ✓). -->
      <section class="pn__sec">
        @if (doiSoatPass()) {
          <button type="button" class="pn__collapse-head pn__collapse-head--ok" (click)="toggleDsPass()" [attr.aria-expanded]="dsPassOpen()">
            <span class="pn__collapse-ic"><tabler-icon [icon]="iCircleCheck" [size]="16" /></span>
            <span class="pn__collapse-tt">Đã soát đủ 6/6 điểm cơ quan BHXH</span>
            <span class="pn__collapse-caret"><tabler-icon [icon]="dsPassOpen() ? iChevronUp : iChevronDown" [size]="14" /></span>
          </button>
          @if (dsPassOpen()) {
            <div class="pn__ds">
              @for (d of doiSoat(); track d.label) {
                <div class="pn__ds-row">
                  <span class="pn__ds-ic"><tabler-icon [icon]="iCircleCheck" [size]="14" /></span>
                  <div class="pn__ds-body"><span class="pn__ds-label">{{ d.label }}</span></div>
                </div>
              }
            </div>
          }
        } @else {
          <div class="pn__ds-head">
            <span class="pn__ds-head-ic"><tabler-icon [icon]="iAlert" [size]="15" /></span>
            <span class="pn__ds-head-tt">{{ soVuong() }} vướng · {{ soDat() }} đạt</span>
          </div>
          <div class="pn__ds">
            @for (d of doiSoatBad(); track d.label) {
              <div class="pn__ds-row pn__ds-row--bad">
                <span class="pn__ds-ic"><tabler-icon [icon]="iAlert" [size]="14" /></span>
                <div class="pn__ds-body">
                  <span class="pn__ds-label">{{ d.label }}</span>
                  @if (d.hint) { <span class="pn__ds-hint">{{ d.hint }}</span> }
                </div>
                @if (d.fix; as fx) {
                  <hrm-button size="sm" [disabled]="locked()" (click)="runDsFix(fx.stt)">{{ fx.label }}</hrm-button>
                }
              </div>
            }
          </div>
          @if (soDat() > 0) {
            <button type="button" class="pn__collapse-head pn__collapse-head--sub" (click)="toggleDsOk()" [attr.aria-expanded]="dsOkOpen()">
              <span class="pn__collapse-ic"><tabler-icon [icon]="iCircleCheck" [size]="16" /></span>
              <span class="pn__collapse-tt">{{ soDat() }} điểm đã đạt</span>
              <span class="pn__collapse-caret"><tabler-icon [icon]="dsOkOpen() ? iChevronUp : iChevronDown" [size]="14" /></span>
            </button>
            @if (dsOkOpen()) {
              <div class="pn__ds">
                @for (d of doiSoatOk(); track d.label) {
                  <div class="pn__ds-row">
                    <span class="pn__ds-ic"><tabler-icon [icon]="iCircleCheck" [size]="14" /></span>
                    <div class="pn__ds-body"><span class="pn__ds-label">{{ d.label }}</span></div>
                  </div>
                }
              </div>
            }
          }
        }
      </section>

      <!-- 【3】 VÌ SAO ĐỀ XUẤT (confidence 5 yếu tố) — progressive, mặc định GẬP; bung: ⚠ cần lưu ý TRƯỚC ✓ thuận. -->
      <section class="pn__sec pn__ai">
        <button type="button" class="pn__collapse-head" (click)="toggleWhy()" [attr.aria-expanded]="whyOpen()">
          <span class="pn__collapse-tt"><tabler-icon [icon]="iSparkles" [size]="15" /> Vì sao đề xuất: {{ kindLabel() }}</span>
          <span class="pn__collapse-sub" [attr.data-level]="confLevel()">Độ tin cậy {{ confidence() }}%</span>
          <span class="pn__collapse-caret"><tabler-icon [icon]="whyOpen() ? iChevronUp : iChevronDown" [size]="14" /></span>
        </button>
        @if (whyOpen()) {
          <p class="pn__ai-lead">{{ aiLead() }}</p>

          <!-- Độ tin cậy — bấm mở cách tính (5 yếu tố) -->
          <button type="button" class="pn__conf" [attr.data-level]="confLevel()" (click)="toggleBreakdown()"
            [attr.aria-expanded]="breakdownOpen()">
            <span class="pn__conf-dot"></span>
            <span class="pn__conf-num">Độ tin cậy {{ confidence() }}%</span>
            <span class="pn__conf-lv">· {{ confLevelLabel() }}</span>
            <span class="pn__conf-more">{{ breakdownOpen() ? 'Ẩn cách tính' : 'Xem cách tính' }} <tabler-icon [icon]="breakdownOpen() ? iChevronUp : iChevronDown" [size]="12" /></span>
          </button>
          @if (breakdownOpen()) {
            <div class="pn__bd">
              @for (b of breakdown().rows; track b.label) {
                <div class="pn__bd-row">
                  <span class="pn__bd-k">{{ b.label }}</span>
                  <span class="pn__bd-bar"><span class="pn__bd-fill" [attr.data-level]="b.level" [style.width.%]="b.score"></span></span>
                  <span class="pn__bd-n">{{ b.score }}</span>
                </div>
              }
              <p class="pn__bd-note"><b>Điểm cần lưu ý:</b> {{ breakdown().note }}</p>
            </div>
          }

          <!-- Vì sao — ⚠ cần lưu ý xếp TRƯỚC ✓ thuận (§3/§4 sort) rồi kết luận đề xuất -->
          <div class="pn__why">
            @for (r of aiReasonsSorted(); track $index) {
              <div class="pn__why-row" [attr.data-kind]="r.kind">
                <span class="pn__why-ic"><tabler-icon [icon]="r.kind === 'ok' ? iCheck : iAlert" [size]="14" /></span>
                <span class="pn__why-tx">{{ r.text }}</span>
              </div>
            }
            <div class="pn__why-concl" [class.pn__why-concl--block]="aiConclusion().block"><tabler-icon [icon]="iArrowRight" [size]="14" /> {{ aiConclusion().text }}</div>
          </div>

          <!-- Trước → Sau (số dự kiến nội bộ, chỉ đọc) -->
          <div class="pn__ba">
            <span class="pn__ba-lb">Thay đổi mức lương đóng (dự kiến)</span>
            @if (c.coKhongAnhHuong) {
              <p class="pn__muted-line">Dòng <b>không ảnh hưởng số phải đóng</b> — không cộng vào tổng dự kiến của kỳ.</p>
            } @else if (c.truoc || c.sau) {
              <div class="pn__ba-diff"><ins-diff [before]="c.truoc || ''" [after]="c.sau || ''" /> <ins-layer-badge layer="du-kien" /></div>
            } @else if (c.chenhLechDuKien) {
              <div class="pn__sim"><span class="pn__sim-num">{{ c.chenhLechDuKien }}</span> <ins-layer-badge layer="du-kien" /></div>
              <p class="pn__muted-line">Thay đổi <b>mức lương đóng</b> của dòng (căn cứ quỹ) — <b>chưa phải số tiền phải nộp</b>; cộng dồn vào tổng thay đổi mức đóng dự kiến của kỳ (chạy lại không nhân đôi).</p>
            } @else {
              <p class="pn__muted-line">{{ simMissingLabel() }}</p>
            }
          </div>

          <!-- Sau khi xác nhận + căn cứ pháp lý (AI đề xuất, quy tắc vẫn là căn cứ) -->
          <div class="pn__ai-foot">
            <div class="pn__row"><span class="pn__k">Sau khi xác nhận</span><span class="pn__v"><b>{{ aiAfterConfirm() }}</b></span></div>
            <p class="pn__cancu">{{ aiCanCu() }}</p>
          </div>
        }
      </section>

      <!-- 【3】 CHUỖI BIẾN ĐỘNG (§19) — progressive, mặc định GẬP (bấm bung); chỉ khi dòng thuộc chuỗi liên kỳ. -->
      @if (chuoi(); as steps) {
        <section class="pn__sec">
          <button type="button" class="pn__collapse-head" (click)="toggleChain()" [attr.aria-expanded]="chainOpen()">
            <span class="pn__collapse-tt">Chuỗi biến động</span>
            <span class="pn__collapse-sub">{{ steps.length }} mốc</span>
            <span class="pn__collapse-caret"><tabler-icon [icon]="chainOpen() ? iChevronUp : iChevronDown" [size]="14" /></span>
          </button>
          @if (chainOpen()) {
            <div class="pn__chain">
              @for (s of steps; track $index) {
                <div class="pn__chain-step" [class.pn__chain-step--self]="s.self">
                  <span class="pn__chain-ky">{{ s.ky }}</span>
                  <span class="pn__chain-dir" [attr.data-dir]="s.dir">
                    @if (s.dir === 'giam') { <tabler-icon [icon]="iArrowDown" [size]="14" /> }
                    @else if (s.dir === 'tang') { <tabler-icon [icon]="iArrowUp" [size]="14" /> }
                    @else { <tabler-icon [icon]="iMinus" [size]="14" /> }
                    {{ s.dirLabel }}
                  </span>
                  <span class="pn__chain-mo">{{ s.mo }}</span>
                </div>
                @if (!$last) { <div class="pn__chain-arrow"><tabler-icon [icon]="iArrowRight" [size]="16" /></div> }
              }
            </div>
            <p class="pn__muted-line">Hai biến động liên kết — nên xác nhận cùng nhau để không lệch số phải đóng giữa hai kỳ.</p>
            <div class="pn__chain-act">
              <hrm-button size="sm" variant="primary" [disabled]="locked() || !doiSoatPass()" (click)="xacNhanChuoi()">Xác nhận cả chuỗi</hrm-button>
            </div>
          }
        </section>
      }

      <!-- PHÁT SINH KỲ TRƯỚC (§20) — biến động hiệu lực T08 xử lý muộn trong T09; nhấn mạnh tháng
           hiệu lực BHXH giữ nguyên T08 (không tự đổi thành T09). Đặt TRÊN "Dữ liệu nguồn". -->
      @if (kyTruocInfo(); as k) {
        <section class="pn__sec">
          <ins-section-label text="Phát sinh kỳ trước" tone="critical" />
          <div class="pn__meta">
            <div class="pn__meta-row"><span class="pn__meta-k">Hiệu lực</span><span class="pn__meta-v">{{ k.hieuLuc }}</span></div>
            <div class="pn__meta-row"><span class="pn__meta-k">Hướng xử lý</span><span class="pn__meta-v">{{ k.huong }}</span></div>
            <div class="pn__meta-row"><span class="pn__meta-k">Trạng thái</span><span class="pn__meta-v">Phát sinh kỳ trước</span></div>
            <div class="pn__meta-row"><span class="pn__meta-k">Nguyên nhân</span><span class="pn__meta-v">{{ k.nguyenNhan }}</span></div>
          </div>
          <p class="pn__muted-line"><b>Đây là biến động hiệu lực T08, đang xử lý trong {{ k.kyXuLy }}.</b> Tháng hiệu lực BHXH giữ nguyên T08 — không đổi thành T09.</p>
        </section>
      }

      <!-- DỮ LIỆU NGUỒN — data dictionary theo loại biến động (progressive disclosure, mục 2C).
           Level 2: field nguồn liên quan gom theo NHÓM NGUỒN. Level 3: nguồn chung ẩn sau nút. -->
      @if (dictGroups().length) {
        <section class="pn__sec pn__src">
          <!-- 【3】 DỮ LIỆU NGUỒN — progressive, mặc định GẬP (bấm bung). -->
          <button type="button" class="pn__collapse-head" (click)="toggleSrc()" [attr.aria-expanded]="srcOpen()">
            <span class="pn__collapse-tt">Dữ liệu nguồn</span>
            <span class="pn__collapse-sub">{{ dictCount() }} field</span>
            <span class="pn__collapse-caret"><tabler-icon [icon]="srcOpen() ? iChevronUp : iChevronDown" [size]="14" /></span>
          </button>
          @if (srcOpen()) {
            <!-- Thông tin nguồn chung — nguồn sự kiện · thời điểm phát hiện · ngày hiệu lực -->
            <div class="pn__meta">
              @for (m of sourceMeta(); track m.k) {
                <div class="pn__meta-row"><span class="pn__meta-k">{{ m.k }}</span><span class="pn__meta-v" [class.pn__miss]="m.miss">{{ m.v }}</span></div>
              }
            </div>
            @for (g of dictGroups(); track g.nhom) {
              <div class="pn__src-grp">
                <div class="pn__src-gh">{{ g.nhomLabel }}</div>
                <div class="pn__src-rows">
                  @for (f of g.fields; track f.ma) {
                    <div class="pn__src-row">
                      <span class="pn__src-k">{{ f.nhan }}</span>
                      <span class="pn__src-v">
                        @if (f.truoc || f.sau) {
                          <ins-diff [before]="f.truoc || ''" [after]="f.sau || ''" />
                        } @else { {{ f.giaTri || '—' }} }
                      </span>
                      <span class="pn__tag" [attr.data-tag]="f.tag">{{ tagLabel(f.tag) }}</span>
                    </div>
                  }
                </div>
              </div>
            }

            <!-- Level 3 — nguồn chung (hồ sơ NLĐ, mốc, kỳ) ẩn mặc định để panel không dày -->
            <button type="button" class="pn__src-more" (click)="toggleFullSource()" [attr.aria-expanded]="fullSourceOpen()">
              {{ fullSourceOpen() ? 'Ẩn nguồn chung' : 'Xem đầy đủ nguồn' }} <tabler-icon [icon]="fullSourceOpen() ? iChevronUp : iChevronDown" [size]="12" />
            </button>
            @if (fullSourceOpen()) {
              <div class="pn__src-grp pn__src-grp--full">
                <div class="pn__src-gh">Thông tin chung</div>
                <div class="pn__src-rows">
                  @for (f of dictCommon(); track f.ma) {
                    <div class="pn__src-row">
                      <span class="pn__src-k">{{ f.nhan }}</span>
                      <span class="pn__src-v">{{ f.giaTri || '—' }}</span>
                      <span class="pn__tag" [attr.data-tag]="f.tag">{{ tagLabel(f.tag) }}</span>
                    </div>
                  }
                </div>
              </div>
            }
          }
        </section>
      }

      <!-- AI3 Suggested Fix — dòng xung đột giá trị lương đóng đa-nguồn -->
      @if (c.multiSourceValues?.length) {
        <section class="pn__sec">
          <ins-section-label text="Gợi ý xử lý — giá trị lệch giữa các nguồn" tone="critical" />
          <div class="pn__ms">
            @for (v of c.multiSourceValues; track v.nguon) {
              <div class="pn__ms-row" [class.pn__ms-row--sug]="v.nguon === c.suggestedNguon">
                <div class="pn__ms-info">
                  <span class="pn__ms-src">{{ v.nguon }}@if (v.nguon === c.suggestedNguon) { <span class="pn__ms-badge">đề xuất</span> }</span>
                  @if (v.ghiChu) { <span class="pn__ms-note">{{ v.ghiChu }}</span> }
                </div>
                <span class="pn__ms-val">{{ v.giaTri }}</span>
                @if (v.nguon === c.suggestedNguon) {
                  <hrm-button size="sm" variant="primary" [disabled]="locked()" (click)="apDungGiaTri(v.giaTri, v.nguon)">Dùng</hrm-button>
                } @else {
                  <hrm-button size="sm" [disabled]="locked()" (click)="apDungGiaTri(v.giaTri, v.nguon)">Dùng</hrm-button>
                }
              </div>
            }
          </div>
          @if (c.canCu) { <p class="pn__muted-line"><b>Căn cứ (gợi ý):</b> {{ c.canCu }}</p> }
        </section>
      }

      <!-- TRẢ NGUỒN SỬA — bàn giao về nghiệp vụ nguồn có thẩm quyền (HR bảo hiểm không sửa đè dữ liệu nguồn) -->
      @if (ketLuan() === 'tra-nguon-sua') {
        <section class="pn__sec">
          <ins-section-label text="Trả nguồn sửa" tone="critical" />
          <p class="pn__muted-line">HR bảo hiểm không sửa đè dữ liệu nguồn — chuyển về bộ phận có thẩm quyền sửa.</p>
          <div class="pn__form">
            <label class="pn__field">
              <span class="pn__field-lb">Trả về nghiệp vụ nguồn</span>
              <hrm-select [(ngModel)]="traNguonNguoiNhan" [options]="nguoiNhanOptions" placeholder="Chọn nghiệp vụ nguồn (Payroll / Hợp đồng / Chấm công…)" [allowClear]="false" size="sm" />
            </label>
            <label class="pn__field">
              <span class="pn__field-lb">Sai/lệch chỗ nào (bắt buộc)</span>
              <hrm-textarea [(ngModel)]="traNguonLyDo" placeholder="Mô tả dữ liệu sai/lệch để nguồn sửa…" [minRows]="2" [status]="traNguonError() ? 'error' : ''" />
            </label>
            @if (traNguonError(); as err) { <p class="pn__form-err">{{ err }}</p> }
            <div class="pn__form-act">
              <hrm-button size="sm" variant="primary" [disabled]="locked() || !traNguonNguoiNhan || !traNguonLyDo.trim()" (click)="traNguon()">Trả nguồn sửa</hrm-button>
            </div>
          </div>
        </section>
      }

      <!-- §12 Đối soát 6 điểm + §13 Kết luận nghiệp vụ + Cách gỡ (7 đường ra) ĐÃ CHUYỂN LÊN ĐẦU PANEL
           ("Việc cần làm" + "Đối soát nhanh") — reorder concept đã chốt, không lặp lại ở đây. -->

      <!-- 【3】 LỊCH SỬ — nhật ký append-only, progressive, mặc định GẬP (bấm bung). -->
      <section class="pn__sec">
        <button type="button" class="pn__collapse-head" (click)="toggleHist()" [attr.aria-expanded]="histOpen()">
          <span class="pn__collapse-tt">Lịch sử thao tác</span>
          <span class="pn__collapse-sub">{{ history().length }}</span>
          <span class="pn__collapse-caret"><tabler-icon [icon]="histOpen() ? iChevronUp : iChevronDown" [size]="14" /></span>
        </button>
        @if (histOpen()) {
          @if (history().length) {
            <hrm-timeline [items]="history()" />
          } @else {
            <p class="pn__muted-line">Chưa có thao tác trong phiên demo — nhật ký append-only ghi trước/sau + lý do + người.</p>
          }
        }
      </section>
    }

    <!-- FOOTER (DS slot) — ferry TemplateRef này lên page → hrm-detail-peek [footer] → render trong .dp-mfoot:
         GHIM đáy bằng flexbox NGOÀI vùng cuộn .dp-mbody (đúng chuẩn DS, không tự chế sticky, full-bleed).
         Khai ở top-level (viewChild luôn thấy); logic GATED giữ nguyên vì template thuộc scope panel. -->
    <ng-template #footerTpl>
      @if (change(); as c) {
        @if (canConfirm()) {
          <hrm-button variant="primary" [disabled]="locked()" (click)="xacNhan()"><tabler-icon [icon]="iCheck" [size]="16" /> Xác nhận vào kê khai</hrm-button>
        } @else {
          <hrm-button variant="primary" [disabled]="true"><tabler-icon [icon]="iLock" [size]="16" /> Xác nhận · còn {{ soCanXuLy() }} điểm cần xử lý</hrm-button>
          @if (resolveAction(); as ra) {
            <hrm-button [disabled]="locked()" (click)="runResolve()">{{ ra.label }}</hrm-button>
          }
        }
        <hrm-button [disabled]="locked()" (click)="loaiKhoiKy()">Bỏ khỏi kỳ</hrm-button>
      }
    </ng-template>
  `,
  host: { class: 'ins-m02-detail-panel' },
  styles: [`
    :host { display: flex; flex-direction: column; gap: 16px; font-size: var(--fs-13); }
    /* Icon design-system (@tabler/icons-angular) — canh giữa, không co giãn; kế thừa màu qua currentColor. */
    tabler-icon { display: inline-flex; align-items: center; flex: none; }
    .pn__alert { display: block; }

    .pn__head { display: flex; flex-direction: column; gap: 6px; }
    .pn__head-id { display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; }
    .pn__head-nv { font-size: var(--fs-14); font-weight: 700; color: var(--text-strong); }
    .pn__head-dept { font-size: var(--fs-12); color: var(--text-sub); }
    .pn__head-tags { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
    /* §6 Nhãn chính mã phương án dẫn dắt */
    .pn__head-pa { font-size: var(--fs-15); font-weight: 700; color: var(--text-strong); line-height: 1.35; }
    .pn__head-quy { margin: 0; font-size: var(--fs-12); color: var(--text-sub); }
    .pn__head-quy b { color: var(--text-body); font-weight: 600; }
    .pn__head-desc { margin: 0; font-size: var(--fs-13); font-weight: 600; color: var(--text-strong); }

    /* Dữ liệu nguồn — dải thông tin nguồn chung */
    .pn__meta { display: flex; flex-direction: column; gap: 3px; padding: 7px 10px; border: 1px solid var(--border-soft);
      border-radius: var(--radius-md); background: var(--bg-surface-subtle); }
    .pn__meta-row { display: grid; grid-template-columns: 168px 1fr; gap: 10px; align-items: baseline; }
    .pn__meta-k { font-size: var(--fs-12); color: var(--text-sub); }
    .pn__meta-v { font-size: var(--fs-13); color: var(--text-body); font-weight: 600; }

    /* Chuỗi biến động — 2 mốc giảm T08 → tăng lại T09 */
    .pn__chain { display: flex; align-items: stretch; gap: 8px; flex-wrap: wrap; }
    .pn__chain-step { display: flex; flex-direction: column; gap: 2px; flex: 1; min-width: 140px; padding: 8px 10px;
      border: 1px solid var(--border-soft); border-radius: var(--radius-md); background: var(--bg-surface-subtle); }
    .pn__chain-step--self { border-color: var(--primary-base); background: var(--primary-bg-subtle); }
    .pn__chain-ky { font-size: var(--fs-11); font-weight: 600; text-transform: uppercase; letter-spacing: .02em; color: var(--text-soft); }
    .pn__chain-dir { display: inline-flex; align-items: center; gap: 4px; font-size: var(--fs-13); font-weight: 700; color: var(--text-strong); }
    .pn__chain-dir[data-dir='giam'] { color: var(--error-text); }
    .pn__chain-dir[data-dir='tang'] { color: var(--success-text); }
    .pn__chain-mo { font-size: var(--fs-12); color: var(--text-sub); }
    .pn__chain-arrow { display: flex; align-items: center; align-self: center; color: var(--text-soft); }
    .pn__chain-act { display: flex; }

    .pn__sec { display: flex; flex-direction: column; gap: 8px; padding-top: 10px; border-top: 1px solid var(--border-soft); }
    .pn__rows { display: flex; flex-direction: column; gap: 5px; }
    .pn__row { display: flex; gap: 10px; align-items: baseline; }
    .pn__k { flex: none; width: 122px; font-size: var(--fs-12); color: var(--text-sub); }
    .pn__v { flex: 1; min-width: 0; color: var(--text-body); }
    .pn__v b { color: var(--text-strong); font-weight: 600; }
    .pn__mono { font-family: var(--font-mono, monospace); font-size: var(--fs-12); }
    .pn__mocs { display: flex; gap: 12px; flex-wrap: wrap; font-size: var(--fs-12); color: var(--text-sub); }
    .pn__miss { color: var(--warning-text); }
    .pn__muted { color: var(--text-soft); }
    .pn__cd { margin-left: 6px; font-size: var(--fs-11); color: var(--text-soft); background: var(--bg-surface-subtle); border-radius: var(--radius-sm); padding: 0 6px; }
    .pn__link { display: inline-flex; align-items: center; gap: 3px; border: 0; background: none; padding: 0; margin-left: 6px; cursor: pointer; font: inherit; font-size: var(--fs-12); font-weight: 600; color: var(--primary-base); white-space: nowrap; }
    .pn__link:hover { text-decoration: underline; }

    .pn__rule { display: flex; align-items: flex-start; gap: 8px; }
    .pn__rule-body { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
    .pn__rule-msg { color: var(--text-body); }
    .pn__rule-meta { font-size: var(--fs-12); color: var(--text-soft); }
    .pn__muted-line { margin: 0; font-size: var(--fs-12); color: var(--text-sub); }
    .pn__muted-line b { color: var(--text-strong); }

    .pn__sim { display: flex; align-items: center; gap: 8px; }
    .pn__sim-num { font-size: var(--fs-18); font-weight: 700; color: var(--text-strong); }

    /* ── ✨ AI đề xuất ── */
    .pn__ai { gap: 10px; }
    .pn__ai-head { display: flex; flex-direction: column; gap: 2px; }
    .pn__ai-title { font-size: var(--fs-14); font-weight: 700; color: var(--text-strong); }
    .pn__ai-lead { font-size: var(--fs-12); color: var(--text-sub); }

    .pn__conf { display: inline-flex; align-items: center; gap: 7px; align-self: flex-start; cursor: pointer;
      border: 1px solid var(--border-sub); border-radius: var(--radius-full); background: var(--bg-surface);
      padding: 3px 11px; font: inherit; font-size: var(--fs-12); font-weight: 600; color: var(--text-strong); }
    .pn__conf:hover { border-color: var(--primary-base); }
    .pn__conf-dot { width: 8px; height: 8px; border-radius: var(--radius-full); background: var(--text-soft); }
    .pn__conf[data-level='cao'] .pn__conf-dot { background: var(--success-base); }
    .pn__conf[data-level='trung-binh'] .pn__conf-dot { background: var(--warning-base); }
    .pn__conf[data-level='thap'] .pn__conf-dot { background: var(--error-base); }
    .pn__conf[data-level='cao'] .pn__conf-lv { color: var(--success-text); }
    .pn__conf[data-level='trung-binh'] .pn__conf-lv { color: var(--warning-text); }
    .pn__conf[data-level='thap'] .pn__conf-lv { color: var(--error-text); }
    .pn__conf-more { display: inline-flex; align-items: center; gap: 3px; font-weight: 500; color: var(--text-soft); font-size: var(--fs-11); }

    .pn__bd { display: flex; flex-direction: column; gap: 6px; padding: 10px 12px; border: 1px solid var(--border-soft);
      border-radius: var(--radius-md); background: var(--bg-surface-subtle); }
    .pn__bd-row { display: grid; grid-template-columns: 130px 1fr 28px; align-items: center; gap: 8px; }
    .pn__bd-k { font-size: var(--fs-12); color: var(--text-sub); }
    .pn__bd-bar { height: 6px; border-radius: var(--radius-full); background: var(--bg-surface); overflow: hidden; }
    .pn__bd-fill { display: block; height: 100%; border-radius: var(--radius-full); background: var(--text-soft); }
    .pn__bd-fill[data-level='cao'] { background: var(--success-base); }
    .pn__bd-fill[data-level='trung-binh'] { background: var(--warning-base); }
    .pn__bd-fill[data-level='thap'] { background: var(--error-base); }
    .pn__bd-n { font-size: var(--fs-12); font-weight: 600; color: var(--text-strong); text-align: right; font-variant-numeric: tabular-nums; }
    .pn__bd-note { margin: 2px 0 0; font-size: var(--fs-12); color: var(--text-sub); }
    .pn__bd-note b { color: var(--text-strong); }

    .pn__why { display: flex; flex-direction: column; gap: 4px; }
    .pn__why-row { display: flex; gap: 8px; align-items: center; font-size: var(--fs-13); }
    .pn__why-ic { flex: none; width: 14px; font-weight: 700; }
    .pn__why-row[data-kind='ok'] .pn__why-ic { color: var(--success-base); }
    .pn__why-row[data-kind='warn'] .pn__why-ic { color: var(--error-base); }
    .pn__why-tx { color: var(--text-body); }
    .pn__why-concl { display: inline-flex; align-items: center; gap: 4px; margin-top: 4px; font-size: var(--fs-13); font-weight: 600; color: var(--primary-base); }
    .pn__why-concl--block { color: var(--error-text); }

    .pn__ba { display: flex; flex-direction: column; gap: 5px; }
    .pn__ba-lb { font-size: var(--fs-11); font-weight: 600; text-transform: uppercase; letter-spacing: .02em; color: var(--text-soft); }
    .pn__ba-diff { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }

    .pn__ai-foot { display: flex; flex-direction: column; gap: 4px; padding-top: 8px; border-top: 1px dashed var(--border-soft); }
    .pn__cancu { margin: 0; font-size: var(--fs-11); color: var(--text-soft); }

    .pn__ms { display: flex; flex-direction: column; border: 1px solid var(--border-sub); border-radius: var(--radius-md); overflow: hidden; }
    .pn__ms-row { display: flex; align-items: center; gap: 10px; padding: 7px 10px; border-bottom: 1px solid var(--border-soft); }
    .pn__ms-row:last-child { border-bottom: 0; }
    .pn__ms-row--sug { background: var(--success-bg); }
    .pn__ms-info { display: flex; flex-direction: column; gap: 1px; flex: 1; min-width: 0; }
    .pn__ms-src { font-size: var(--fs-12); font-weight: 600; color: var(--text-strong); display: inline-flex; align-items: center; gap: 6px; }
    .pn__ms-badge { font-size: var(--fs-11); font-weight: 600; color: var(--success-text); background: var(--bg-surface); border: 1px solid var(--success-base); border-radius: var(--radius-sm); padding: 0 5px; }
    .pn__ms-note { font-size: var(--fs-11); color: var(--text-soft); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    .pn__ms-val { font-size: var(--fs-13); font-weight: 700; color: var(--text-strong); font-variant-numeric: tabular-nums; white-space: nowrap; }

    /* ── §12 Đối soát nhanh với cơ quan BHXH ── */
    .pn__ds { display: flex; flex-direction: column; gap: 4px; }
    .pn__ds-row { display: flex; gap: 8px; align-items: center; }
    .pn__ds-ic { flex: none; display: inline-flex; align-items: center; color: var(--success-base); }
    .pn__ds-row--bad .pn__ds-ic { color: var(--warning-base); }
    .pn__ds-body { display: flex; flex: 1; flex-direction: column; gap: 1px; min-width: 0; }
    .pn__ds-label { font-size: var(--fs-13); color: var(--text-body); }
    .pn__ds-row--bad .pn__ds-label { color: var(--text-strong); font-weight: 600; }
    .pn__ds-hint { font-size: var(--fs-11); color: var(--text-soft); }
    .pn__ds-warn { margin: 4px 0 0; font-size: var(--fs-12); font-weight: 600; color: var(--warning-text);
      background: var(--warning-bg); border: 1px solid var(--warning-base); border-radius: var(--radius-md); padding: 6px 10px; }
    /* Đối soát — tiêu đề khi còn vướng (⚠ N vướng · M đạt) */
    .pn__ds-head { display: flex; align-items: center; gap: 8px; }
    .pn__ds-head-ic { flex: none; font-weight: 700; color: var(--warning-base); }
    .pn__ds-head-tt { font-size: var(--fs-13); font-weight: 700; color: var(--text-strong); }

    /* ── 【1】 Việc cần làm (todo) — kết luận + gate nút chính ── */
    .pn__todo { gap: 10px; }
    .pn__todo-lb { font-size: var(--fs-11); font-weight: 700; text-transform: uppercase; letter-spacing: .02em; color: var(--text-soft); }
    .pn__todo-act { display: flex; gap: 8px; flex-wrap: wrap; }

    /* ── Collapse header dùng chung (đối soát pass · progressive: Vì sao / Nguồn / Chuỗi / Lịch sử) ── */
    .pn__collapse-head { display: flex; align-items: center; gap: 8px; width: 100%; cursor: pointer; text-align: left;
      border: 1px solid var(--border-soft); border-radius: var(--radius-md); background: var(--bg-surface-subtle);
      padding: 7px 10px; font: inherit; color: var(--text-strong); }
    .pn__collapse-head:hover { border-color: var(--primary-base); }
    .pn__collapse-head--ok { border-color: var(--success-base); background: var(--success-bg); }
    .pn__collapse-head--ok .pn__collapse-ic { color: var(--success-base); }
    .pn__collapse-head--sub { background: none; border-style: dashed; padding: 5px 10px; }
    .pn__collapse-ic { flex: none; display: inline-flex; align-items: center; color: var(--success-base); }
    .pn__collapse-tt { display: inline-flex; align-items: center; gap: 6px; flex: 1; min-width: 0; font-size: var(--fs-13); font-weight: 600; }
    .pn__collapse-sub { flex: none; font-size: var(--fs-12); font-weight: 600; color: var(--text-sub); }
    .pn__collapse-sub[data-level='cao'] { color: var(--success-text); }
    .pn__collapse-sub[data-level='trung-binh'] { color: var(--warning-text); }
    .pn__collapse-sub[data-level='thap'] { color: var(--error-text); }
    .pn__collapse-caret { flex: none; font-size: var(--fs-11); color: var(--text-soft); }

    /* ── §13 Kết luận nghiệp vụ (dải khung chính, 6 kết luận) ── */
    .pn__kl { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; padding: 9px 12px;
      border: 1px solid var(--border-soft); border-left: 3px solid var(--primary-base);
      border-radius: var(--radius-md); background: var(--bg-surface-subtle); }
    .pn__kl-chip { flex: none; font-size: var(--fs-13); font-weight: 700; color: var(--primary-base); }
    .pn__kl-desc { font-size: var(--fs-12); color: var(--text-sub); }
    .pn__kl[data-kl='xu-ly-trong-ky'] { border-left-color: var(--success-base); }
    .pn__kl[data-kl='xu-ly-trong-ky'] .pn__kl-chip { color: var(--success-text); }
    .pn__kl[data-kl='dieu-chinh-ky-truoc'] { border-left-color: var(--info-text); }
    .pn__kl[data-kl='dieu-chinh-ky-truoc'] .pn__kl-chip { color: var(--info-text); }
    .pn__kl[data-kl='cho-bo-sung'] { border-left-color: var(--warning-base); }
    .pn__kl[data-kl='cho-bo-sung'] .pn__kl-chip { color: var(--warning-text); }
    .pn__kl[data-kl='tra-nguon-sua'] { border-left-color: var(--warning-base); }
    .pn__kl[data-kl='tra-nguon-sua'] .pn__kl-chip { color: var(--warning-text); }
    .pn__kl[data-kl='khong-xu-ly'] { border-left-color: var(--text-soft); }
    .pn__kl[data-kl='khong-xu-ly'] .pn__kl-chip { color: var(--text-sub); }
    .pn__kl[data-kl='can-xac-minh'] { border-left-color: var(--error-base); }
    .pn__kl[data-kl='can-xac-minh'] .pn__kl-chip { color: var(--error-text); }
    .pn__cachgo-lb { font-size: var(--fs-11); font-weight: 700; text-transform: uppercase; letter-spacing: .02em; color: var(--text-soft); }

    .pn__exc-head { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
    .pn__exc-han { font-size: var(--fs-12); color: var(--text-sub); display: inline-flex; align-items: center; gap: 6px; }
    .pn__exc-han b { color: var(--text-strong); }
    .pn__outcomes { display: flex; flex-direction: column; border: 1px solid var(--border-sub); border-radius: var(--radius-md); overflow: hidden; }
    .pn__outcome { display: flex; gap: 10px; padding: 7px 10px; border-bottom: 1px solid var(--border-soft); }
    .pn__outcome:last-child { border-bottom: 0; }
    .pn__outcome--hit { background: var(--bg-surface-subtle); }
    .pn__outcome-stt { flex: none; width: 18px; height: 18px; display: grid; place-items: center; border-radius: var(--radius-full);
      background: var(--bg-surface-subtle); font-size: var(--fs-11); font-weight: 600; color: var(--text-sub); }
    .pn__outcome--hit .pn__outcome-stt { background: var(--primary-bg-subtle); color: var(--primary-base); }
    .pn__outcome-body { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
    .pn__outcome-name { font-size: var(--fs-12); font-weight: 600; color: var(--text-strong); }
    .pn__outcome--hit .pn__outcome-name { color: var(--primary-base); }
    .pn__outcome-desc { font-size: var(--fs-12); color: var(--text-sub); }
    .pn__outcome-actions { display: flex; gap: 6px; margin-top: 4px; flex-wrap: wrap; }

    /* ── Dữ liệu nguồn (data dictionary) ── */
    .pn__src { gap: 10px; }
    .pn__src-grp { display: flex; flex-direction: column; gap: 3px; }
    .pn__src-grp--full { padding: 8px 10px; border: 1px dashed var(--border-soft); border-radius: var(--radius-md); background: var(--bg-surface-subtle); }
    .pn__src-gh { font-size: var(--fs-11); font-weight: 700; text-transform: uppercase; letter-spacing: .02em; color: var(--text-soft); margin-bottom: 1px; }
    .pn__src-rows { display: flex; flex-direction: column; gap: 3px; }
    .pn__src-row { display: grid; grid-template-columns: 168px 1fr auto; gap: 10px; align-items: baseline; }
    .pn__src-k { font-size: var(--fs-12); color: var(--text-sub); }
    .pn__src-v { min-width: 0; color: var(--text-body); font-size: var(--fs-13); overflow-wrap: anywhere; }
    .pn__src-v b { color: var(--text-strong); font-weight: 600; }
    .pn__src-more { display: inline-flex; align-items: center; gap: 4px; align-self: flex-start; border: 0; background: none; padding: 0; cursor: pointer; font: inherit;
      font-size: var(--fs-12); font-weight: 600; color: var(--primary-base); }
    .pn__src-more:hover { text-decoration: underline; }

    .pn__tag { flex: none; align-self: center; font-size: var(--fs-11); font-weight: 600; line-height: 1.5;
      padding: 0 6px; border-radius: var(--radius-sm); white-space: nowrap;
      background: var(--bg-surface-subtle); color: var(--text-soft); }
    .pn__tag[data-tag='SOURCE'] { background: var(--bg-surface-subtle); color: var(--text-sub); }
    .pn__tag[data-tag='DERIVED'] { background: var(--info-bg); color: var(--info-text); }
    .pn__tag[data-tag='AI'] { background: var(--primary-bg-subtle); color: var(--primary-base); }
    .pn__tag[data-tag='HR_INPUT'] { background: var(--warning-bg); color: var(--warning-text); }
    .pn__tag[data-tag='SYSTEM'] { background: var(--bg-surface-subtle); color: var(--text-soft); }

    /* ── Bàn giao chéo — "Đã chuyển xử lý" + form inline (yêu cầu bổ sung / trả nguồn sửa) ── */
    .pn__handoff { gap: 8px; }
    .pn__handoff-head { display: flex; align-items: center; gap: 8px; }
    .pn__handoff-lb { font-size: var(--fs-11); font-weight: 700; text-transform: uppercase; letter-spacing: .02em; color: var(--text-soft); }
    .pn__handoff-body { display: flex; flex-direction: column; gap: 4px; padding: 8px 10px; border: 1px solid var(--border-soft);
      border-left: 3px solid var(--warning-base); border-radius: var(--radius-md); background: var(--bg-surface-subtle); }
    .pn__handoff-han { color: var(--error-text); font-weight: 600; }
    .pn__handoff-act { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }

    .pn__form { display: flex; flex-direction: column; gap: 8px; padding: 10px 12px; border: 1px solid var(--border-sub);
      border-radius: var(--radius-md); background: var(--bg-surface-subtle); }
    .pn__form-hd { font-size: var(--fs-12); font-weight: 700; color: var(--text-strong); }
    .pn__field { display: flex; flex-direction: column; gap: 3px; }
    .pn__field-lb { font-size: var(--fs-11); font-weight: 600; color: var(--text-sub); }
    .pn__form-act { display: flex; gap: 6px; flex-wrap: wrap; }
    .pn__form-err { margin: 0; font-size: var(--fs-12); font-weight: 600; color: var(--error-text);
      background: var(--error-bg); border: 1px solid var(--error-base); border-radius: var(--radius-md); padding: 6px 10px; }
  `],
})
export class InsM02DetailPanel {
  private readonly store = inject(InsM02Store);
  private readonly shell = inject(InsShellStore);
  private readonly msg = inject(HrmMessageService);

  readonly change = input.required<InsChange>();
  /** Page lọc theo loại biến động (VD đường ra "Chuyển sang Điều chỉnh"). */
  readonly switchTab = output<InsChangeKind>();
  /** Mở panel của dòng liên kết (mã tương quan 2 chiều). */
  readonly openChange = output<string>();
  /** Hành động cần LÝ DO → page mở prompt (loại trừ / hoàn tác / gán nhãn D02-LT). */
  readonly requestReason = output<{ mode: 'loai-tru' | 'hoan-tac' | 'phan-loai-d02'; id: string }>();
  /** Ferry footer template lên page → hrm-detail-peek [footer] slot (ghim NGOÀI vùng cuộn, đúng DS .dp-mfoot). */
  readonly footerReady = output<TemplateRef<unknown> | null>();
  private readonly footerTplRef = viewChild<TemplateRef<unknown>>('footerTpl');

  constructor() {
    // Emit 1 lần sau render đầu — footerTpl ổn định trong đời panel; page giữ signal + bind [footer].
    afterNextRender(() => this.footerReady.emit(this.footerTplRef() ?? null));
  }

  /* ── Icon design-system (@tabler/icons-angular) — thay toàn bộ emoji/unicode trong template ── */
  protected readonly iCheck = IconCheck;
  protected readonly iCircleCheck = IconCircleCheck;
  protected readonly iAlert = IconAlertTriangle;
  protected readonly iSparkles = IconSparkles;
  protected readonly iLock = IconLock;
  protected readonly iArrowRight = IconArrowRight;
  protected readonly iChevronDown = IconChevronDown;
  protected readonly iChevronUp = IconChevronUp;
  protected readonly iExternalLink = IconExternalLink;
  protected readonly iArrowUp = IconArrowUp;
  protected readonly iArrowDown = IconArrowDown;
  protected readonly iMinus = IconMinus;

  /** Chỉ đọc: đối tượng khóa tháng HOẶC kỳ tác động đã khóa. */
  protected readonly locked = computed(() => {
    const c = this.change();
    return !!c.doiTuongKhoa || this.store.isReadOnly(c);
  });
  protected readonly kyLocked = computed(() => this.store.isReadOnly(this.change()));
  protected readonly kyLockedLabel = computed(() => {
    const ky = insKy(this.change().kyTacDong);
    return ky ? `${ky.label} — ${INS_KY_LABEL[ky.trangThai]}.` : 'Kỳ đã khóa.';
  });
  protected readonly kindLabel = computed(() => INS_CHANGE_KIND_LABEL[this.change().loaiBienDong]);
  protected readonly flowLabel = computed(() => {
    const n = this.change().nhanLuong;
    return n ? INS_FLOW_LABEL[n] : 'Chưa xác định luồng xử lý';
  });
  protected readonly sla = computed(() => insSlaView(this.change()));
  protected readonly nvView = computed(() => {
    const nv = insNhanVien(this.change().nhanVienId);
    return nv ? `${nv.name} · ${nv.code}` : '—';
  });
  /** Header — phòng ban · chức danh của NLĐ (chuỗi sẵn từ danh mục, zoneless-safe). */
  protected readonly deptView = computed(() => {
    const nv = insNhanVien(this.change().nhanVienId);
    if (!nv) return '';
    return nv.position ? `${nv.dept} · ${nv.position}` : nv.dept;
  });
  /** Header — lý do biến động dễ hiểu (movement_reason) thay cho mã phương án kỹ thuật. */
  protected readonly reasonLabel = computed<string | null>(() => {
    const r = this.change().reason;
    return r ? INS_MOVEMENT_REASON_LABEL[r] : (this.change().tenPhuongAn ?? null);
  });
  /** §6 Nhãn chính = mã phương án dẫn dắt ({loại} — {lý do} ({mã})); wrap computed → binding ổn định. */
  protected readonly paLabel = computed(() => insNhanPhuongAn(this.change()));
  /** §6 Quỹ ảnh hưởng của dòng (BHXH + BHYT + BHTN…). */
  protected readonly quyAnhHuong = computed(() => insQuyAnhHuong(this.change()));
  /** §13 Kết luận nghiệp vụ (6 kết luận) — chip + mô tả (khung chính hiển thị trên cách gỡ). */
  protected readonly ketLuan = computed(() => insKetLuan(this.change()));
  protected readonly ketLuanLabel = computed(() => INS_KET_LUAN_LABEL[this.ketLuan()]);
  protected readonly ketLuanDesc = computed(() => INS_KET_LUAN_DESC[this.ketLuan()]);
  /** §12 Đối soát nhanh với cơ quan BHXH — 6 điểm soát; wrap computed → mảng ổn định (zoneless-safe). */
  protected readonly doiSoat = computed(() => insDoiSoat6(this.change()));
  protected readonly doiSoatPass = computed(() => insDoiSoatPass(this.change()));
  /** Dữ liệu nguồn — 3 field nguồn chung: nguồn sự kiện · thời điểm phát hiện · ngày hiệu lực. */
  protected readonly sourceMeta = computed<{ k: string; v: string; miss: boolean }[]>(() => {
    const c = this.change();
    return [
      { k: 'Nguồn sự kiện', v: c.nguon || '—', miss: false },
      { k: 'Thời điểm phát hiện', v: c.ngayPhatSinh || '—', miss: false },
      { k: 'Ngày hiệu lực', v: c.ngayHieuLuc || 'Thiếu mốc', miss: !c.ngayHieuLuc },
    ];
  });
  protected readonly simMissingLabel = computed(() => {
    const c = this.change();
    if (c.coHan === null) return 'Thiếu ngày hiệu lực — không tính được (không hiện số 0 giả).';
    if (c.nhanLuong === null) return 'Chưa xác định luồng xử lý — chưa có kết quả.';
    return 'Chưa có số dự kiến cho dòng này.';
  });

  /* ── 【1】 VIỆC CẦN LÀM — phân loại + gate nút chính (reorder concept đã chốt) ── */
  /** Nhóm phân loại 6-way (san-sang/ky-sau/lien-ky/ky-truoc/can-xu-ly/loai-tru). */
  protected readonly classify = computed(() => insClassify(this.change()));
  /** Dòng còn ở trạng thái đang xử lý → mới hiện nút hành động (đã vào lô/đã nộp… chỉ đọc). */
  protected readonly isActive = computed(() => {
    const s = this.change().trangThai;
    return s === 'phat-hien' || s === 'can-bo-sung' || s === 'san-sang' || s === 'da-xac-nhan';
  });
  /** Nút chính BẬT khi soát đủ 6/6 VÀ đã Sẵn sàng (đúng kỳ, đủ căn cứ). */
  protected readonly canConfirm = computed(() => this.isActive() && this.doiSoatPass() && this.classify() === 'san-sang');
  /** Số điểm đối soát chưa đạt / đã đạt (tiêu đề đối soát + nhãn nút khóa). */
  protected readonly soVuong = computed(() => this.doiSoat().filter((d) => !d.ok).length);
  protected readonly soDat = computed(() => this.doiSoat().filter((d) => d.ok).length);
  /** "còn N điểm cần xử lý": ưu tiên số vướng đối soát; đủ 6/6 mà chưa Sẵn sàng → còn 1 việc định tuyến. */
  protected readonly soCanXuLy = computed(() => {
    const n = this.soVuong();
    return n > 0 ? n : (this.classify() === 'san-sang' ? 0 : 1);
  });
  /** ⚠ điểm chưa đạt (kèm nút gỡ theo hint) — ⚠ luôn xếp trước ✓ (§4 sort), memoized ổn định. */
  protected readonly doiSoatBad = computed(() => {
    const c = this.change();
    return this.doiSoat().filter((d) => !d.ok).map((d) => ({ ...d, fix: this.dsFixFor(d.label, c) }));
  });
  /** ✓ điểm đã đạt (gập sau nhãn "{k} điểm đã đạt"). */
  protected readonly doiSoatOk = computed(() => this.doiSoat().filter((d) => d.ok));
  /** Nút gỡ chính cạnh nút Xác nhận khóa — theo nhóm ngoại lệ đang hit, fallback theo điểm đối soát vướng đầu. */
  protected readonly resolveAction = computed<{ label: string; stt: number } | null>(() => {
    const hit = this.outcomes().find((o) => o.hit);
    if (hit) return { label: hit.actionLabel, stt: hit.stt };
    return this.doiSoatBad()[0]?.fix ?? null;
  });
  /** Ánh xạ 1 điểm đối soát vướng → nút gỡ (nhãn + đường ra stt trong bảng 7 đường ra). */
  private dsFixFor(label: string, c: InsChange): { label: string; stt: number } | null {
    switch (label) {
      case 'Mã số BHXH': return { label: 'Yêu cầu bổ sung', stt: 1 };
      case 'Không trùng hồ sơ đang chờ': return { label: 'Đối chiếu', stt: 2 };
      case 'Đúng tháng, không rơi vào sổ đã khóa':
        return c.nhomNgoaiLe.includes('hieu-luc-hoi-to') ? { label: 'Chuyển bù kỳ trước', stt: 5 } : { label: 'Chờ mở khóa', stt: 6 };
      case 'Đủ giấy tờ kèm theo mẫu': return { label: 'Yêu cầu bổ sung', stt: 1 };
      default: return null;
    }
  }
  /** Nút chính — xác nhận vào lô kê khai (tái dùng bulkChuyenLo như lưới, giữ mọi guard nghiệp vụ). */
  protected xacNhan(): void {
    const c = this.change();
    const ten = insNhanVien(c.nhanVienId)?.name ?? '';
    const r = this.store.bulkChuyenLo([c.id]);
    if (r.done && r.loBatchId) {
      const kyLabel = insKy(r.ky ?? '')?.label ?? '';
      this.msg.success(`Đã xác nhận ${ten}${kyLabel ? ' · ' + kyLabel : ''} · Đợt #${r.loBatchId.slice(8)}`);
    } else if (r.daXacNhan) {
      this.msg.warning('Đã xác nhận · chưa xếp đợt — giữ trong hàng đợi.');
    } else {
      const p = this.store.chuyenLoPreview([c.id]);
      this.msg.warning(p.blocked[0]?.reason ?? 'Chưa đủ điều kiện xác nhận.');
    }
  }
  /** Nút phụ — Loại khỏi kỳ (loại trừ có lý do; page mở popover). */
  protected loaiKhoiKy(): void { this.requestReason.emit({ mode: 'loai-tru', id: this.change().id }); }
  /** Chạy nút gỡ chính theo resolveAction. */
  protected runResolve(): void { const ra = this.resolveAction(); if (ra) this.runDsFix(ra.stt); }
  /** Chạy 1 đường ra theo stt (tái dùng runOutcome — giữ mọi guard nghiệp vụ). */
  protected runDsFix(stt: number): void {
    const o = M02_EXCEPTION_OUTCOMES.find((x) => x.stt === stt);
    if (o) this.runOutcome({ ...o, hit: true }, false);
  }

  /* ── 【2】【3】 trạng thái đóng/mở (collapse) — signal ổn định, zoneless-safe ── */
  /** Đối soát: pass → gập chi tiết; còn vướng → gập riêng nhóm ✓ đã đạt. */
  protected readonly dsPassOpen = signal(false);
  protected toggleDsPass(): void { this.dsPassOpen.update((v) => !v); }
  protected readonly dsOkOpen = signal(false);
  protected toggleDsOk(): void { this.dsOkOpen.update((v) => !v); }
  /** Progressive — Dữ liệu nguồn / Chuỗi / Lịch sử: mặc định GẬP.
   *  RIÊNG "Vì sao" tự BUNG khi dòng đang mở có độ tin cậy THẤP (linkedSignal theo confLevel; dòng cao/vừa giữ gập);
   *  vẫn cho phép người dùng gập/mở tay trong cùng một dòng, đổi dòng thì khởi tạo lại theo mức tin cậy mới. */
  protected readonly whyOpen = linkedSignal(() => this.confLevel() === 'thap');
  protected toggleWhy(): void { this.whyOpen.update((v) => !v); }
  protected readonly srcOpen = signal(false);
  protected toggleSrc(): void { this.srcOpen.update((v) => !v); }
  protected readonly chainOpen = signal(false);
  protected toggleChain(): void { this.chainOpen.update((v) => !v); }
  protected readonly histOpen = signal(false);
  protected toggleHist(): void { this.histOpen.update((v) => !v); }
  /** Vì sao — ⚠ cần lưu ý xếp TRƯỚC ✓ thuận (§3/§4 sort), deterministic + memoized. */
  protected readonly aiReasonsSorted = computed(() => {
    const rs = this.aiReasons();
    return [...rs.filter((r) => r.kind === 'warn'), ...rs.filter((r) => r.kind === 'ok')];
  });

  /* ── CHUỖI LIÊN KỲ (§19) — dựng 2 mốc từ các mắt xích cùng chuoiId (deterministic, không random).
   *  Nếu tìm được đủ mắt xích trong store → sắp theo buoc; nếu không → chỉ dòng hiện tại. ── */
  protected readonly chuoi = computed<{ ky: string; dir: string; dirLabel: string; mo: string; self: boolean }[] | null>(() => {
    const c = this.change();
    if (!c.lienKet) return null;
    const cid = c.lienKet.chuoiId;
    const steps = this.store.changes()
      .filter((x) => x.lienKet?.chuoiId === cid)
      .sort((a, b) => (a.lienKet!.buoc - b.lienKet!.buoc));
    const src = steps.length >= 2 ? steps : [c];
    return src.map((x) => {
      const lk = x.lienKet!;
      return {
        ky: lk.kyLabel,
        dir: lk.huong,
        dirLabel: lk.huong === 'giam' ? 'Báo giảm' : lk.huong === 'tang' ? 'Báo tăng lại' : 'Điều chỉnh',
        mo: lk.moTaBuoc ?? x.moTa,
        self: x.id === c.id,
      };
    });
  });

  /** Phát sinh kỳ trước (§20) — thông tin gọn khi c.phatSinhKyTruoc: hiệu lực T08, xử lý trong kỳ khác. */
  protected readonly kyTruocInfo = computed<{ hieuLuc: string; huong: string; nguyenNhan: string; kyXuLy: string } | null>(() => {
    const c = this.change();
    if (!c.phatSinhKyTruoc) return null;
    const kyXuLy = c.kyXuLyLabel ?? 'T09/2026';
    return {
      hieuLuc: c.ngayHieuLuc || '—',
      huong: `T08 → xử lý trong ${kyXuLy}`,
      nguyenNhan: (c.nguyenNhanNgan ?? insNguyenNhanNgan(c)) || '—',
      kyXuLy,
    };
  });

  /** Xác nhận cả chuỗi liên kỳ — demo toast deterministic (chưa ghi kỳ thật). */
  protected xacNhanChuoi(): void {
    this.msg.success('Đã xác nhận cả chuỗi liên kỳ — giảm T08 và tăng lại T09 xử lý cùng nhau (demo — chưa ghi vào kỳ thật).');
  }

  /* ── ✨ AI ĐỀ XUẤT (đợt B) — gộp kết quả quy tắc + dự báo tác động, có độ tin cậy + lý do ── */

  /** Mở/đóng khối "cách tính" độ tin cậy (referentially-stable signal, zoneless-safe). */
  protected readonly breakdownOpen = signal(false);
  protected toggleBreakdown(): void { this.breakdownOpen.update((v) => !v); }

  /** Điểm tin cậy + mức — deterministic từ store (không random). */
  protected readonly confidence = computed(() => this.store.confidenceCuaDong(this.change()));
  protected readonly confLevel = computed(() => this.store.confidenceLevel(this.change()));
  protected readonly confLevelLabel = computed(() =>
    this.confLevel() === 'cao' ? 'Cao' : this.confLevel() === 'trung-binh' ? 'Trung bình' : 'Thấp');

  /** Dòng mô tả ngắn dưới tiêu đề đề xuất (VD "Nghỉ không lương · từ Kỳ 08/2026"). */
  protected readonly aiLead = computed(() => {
    const c = this.change();
    const ky = insKy(c.kyTacDong)?.label ?? '';
    const what = c.tenPhuongAn || c.moTa;
    return ky ? `${what} · từ ${ky}` : what;
  });

  /** Vì sao có cấu trúc — dòng thuận (✓) + cần lưu ý (⚠) suy ra 1 lần từ tín hiệu sẵn có. */
  protected readonly aiReasons = computed<{ kind: 'ok' | 'warn'; text: string }[]>(() => {
    const c = this.change();
    const out: { kind: 'ok' | 'warn'; text: string }[] = [];
    const hasChan = c.ketQuaRule.some((r) => r.muc === 'chan');
    // 1) Vướng mắc chặn lên trước (⚠ đỏ)
    for (const r of c.ketQuaRule) if (r.muc === 'chan') out.push({ kind: 'warn', text: r.thongDiep });
    // 2) Căn cứ nguồn (chỉ nêu điểm thuận khi không bị chặn)
    if (!hasChan) {
      if (c.nguon === 'Hợp đồng lao động') out.push({ kind: 'ok', text: 'Hợp đồng lao động còn hiệu lực' });
      else if (c.nguon === 'Quyết định nhân sự') out.push({ kind: 'ok', text: 'Có quyết định nhân sự làm căn cứ' });
      else if (c.nguon === 'Chấm công') out.push({ kind: 'ok', text: 'Dữ liệu chấm công khớp' });
      else if (c.maCaseNguon) out.push({ kind: 'ok', text: `Gắn với hồ sơ chế độ ${c.maCaseNguon}` });
      else out.push({ kind: 'ok', text: `Căn cứ nguồn: ${c.nguon}` });
    }
    // 3) Mốc hiệu lực
    if (c.ngayHieuLuc) out.push({ kind: 'ok', text: `Có ngày hiệu lực ${c.ngayHieuLuc}` });
    else out.push({ kind: 'warn', text: 'Thiếu ngày hiệu lực — cần bổ sung' });
    // 4) Không trùng hồ sơ
    if (!c.dongXungDot && !c.nhomNgoaiLe.includes('trung-du-lieu')) out.push({ kind: 'ok', text: 'Không trùng với hồ sơ khác' });
    else out.push({ kind: 'warn', text: 'Nghi trùng hồ sơ — cần đối chiếu nguồn' });
    // 5) Cảnh báo từ quy tắc
    for (const r of c.ketQuaRule) if (r.muc === 'canh-bao') out.push({ kind: 'warn', text: r.thongDiep });
    // 6) Nhóm ngoại lệ còn lại (bỏ nhóm trùng vì đã nêu ở bước 4)
    for (const g of c.nhomNgoaiLe) if (g !== 'trung-du-lieu') out.push({ kind: 'warn', text: this.excLabel(g) });
    return out;
  });

  /** Kết luận đề xuất — chốt lại hành động; nếu có quy tắc chặn thì đổi thành lời nhắc xử lý trước. */
  protected readonly aiConclusion = computed<{ text: string; block: boolean }>(() => {
    const c = this.change();
    const ky = insKy(c.kyTacDong)?.label ?? '';
    if (c.ketQuaRule.some((r) => r.muc === 'chan')) return { text: 'Cần xử lý vướng mắc trước khi kê khai', block: true };
    return { text: `Đề xuất ${this.kindLabel()}${ky ? ' — ' + ky : ''}`, block: false };
  });

  /** Sau khi xác nhận sẽ nằm ở đâu — "Kỳ 08/2026 · Đợt #08-01" hoặc "· sẽ xếp đợt tự động". */
  protected readonly aiAfterConfirm = computed(() => {
    const c = this.change();
    const ky = insKy(c.kyTacDong)?.label ?? 'Chưa rõ kỳ';
    if (c.loBatchId) return `${ky} · Đợt #${c.loBatchId.slice(8)}`;
    return `${ky} · sẽ xếp đợt tự động`;
  });

  /** Căn cứ pháp lý — AI đề xuất nhưng quy tắc vẫn là căn cứ (giữ truy vết); kèm diễn giải ngắn. */
  protected readonly aiCanCu = computed(() => {
    const r = this.change().ketQuaRule[0];
    if (r) return `Căn cứ: quy tắc ${r.rule} ${r.phienBan} — ${r.thongDiep}`;
    return 'Căn cứ: quy trình nghiệp vụ BHXH hiện hành';
  });

  /** Cách tính độ tin cậy — điểm thành phần deterministic (suy từ tín hiệu, không random) + điểm lưu ý. */
  protected readonly breakdown = computed<{ rows: { label: string; score: number; level: string }[]; note: string }>(() => {
    const c = this.change();
    const hasChan = c.ketQuaRule.some((r) => r.muc === 'chan');
    const nCanhBao = c.ketQuaRule.filter((r) => r.muc === 'canh-bao').length;
    const conflict = !!c.dongXungDot || c.nhomNgoaiLe.includes('trung-du-lieu');
    const nExc = c.nhomNgoaiLe.length;
    const chongSot = c.nguon === 'Đối soát chống sót';
    const clamp = (n: number) => Math.max(20, Math.min(99, n));
    const khopQuyTac = hasChan ? 35 : nCanhBao ? clamp(78 - nCanhBao * 8) : 98;
    const duDuLieu = clamp((c.ngayHieuLuc ? 96 : 60) - nExc * 12);
    const nguonNhatQuan = conflict ? 48 : chongSot ? 62 : 95;
    const chungCu = c.nguon === 'Chấm công' ? 90 : c.nguon === 'Hợp đồng lao động' || c.nguon === 'Quyết định nhân sự' ? 94 : 82;
    const lichSu = chongSot ? 60 : c.coHan === 'qua-han' ? 74 : 93;
    const lv = (n: number) => (n >= 90 ? 'cao' : n >= 70 ? 'trung-binh' : 'thap');
    const rows = [
      { label: 'Khớp quy tắc', score: khopQuyTac, level: lv(khopQuyTac) },
      { label: 'Đủ dữ liệu nguồn', score: duDuLieu, level: lv(duDuLieu) },
      { label: 'Nguồn nhất quán', score: nguonNhatQuan, level: lv(nguonNhatQuan) },
      { label: 'Chứng cứ hỗ trợ khớp', score: chungCu, level: lv(chungCu) },
      { label: 'Lịch sử nhất quán', score: lichSu, level: lv(lichSu) },
    ];
    let note: string;
    if (hasChan) note = `Vướng quy tắc chặn: ${c.ketQuaRule.find((r) => r.muc === 'chan')!.thongDiep}`;
    else if (conflict) note = 'Có hồ sơ nghi trùng — cần đối chiếu nguồn trước khi chốt.';
    else if (!c.ngayHieuLuc) note = 'Thiếu ngày hiệu lực — chưa tính đủ tác động.';
    else if (chongSot) note = 'Suy luận từ đối soát chống sót — chưa có chứng từ gốc.';
    else if (c.coHan === 'qua-han') note = 'Đã quá hạn xử lý — cần ưu tiên.';
    else note = 'Không có điểm bất thường nổi bật.';
    return { rows, note };
  });

  /* ── DỮ LIỆU NGUỒN (Phase 2) — data dictionary theo lý do biến động ── */

  /** Mở/đóng khối nguồn chung (Level 3) — signal ổn định, zoneless-safe. */
  protected readonly fullSourceOpen = signal(false);
  protected toggleFullSource(): void { this.fullSourceOpen.update((v) => !v); }

  /** Field nguồn của dòng theo reason (rỗng khi chưa gắn reason → không render section). */
  private readonly dictFields = computed<InsDictField[]>(() => {
    const r = this.change().reason;
    return r ? INS_DATADICT[r] ?? [] : [];
  });
  protected readonly dictCount = computed(() => this.dictFields().length);

  /** Gom field theo NHÓM NGUỒN, giữ thứ tự xuất hiện (memoized theo change → referentially-stable). */
  protected readonly dictGroups = computed<{ nhom: InsDictNhomNguon; nhomLabel: string; fields: InsDictField[] }[]>(() => {
    const order: InsDictNhomNguon[] = [];
    const map = new Map<InsDictNhomNguon, InsDictField[]>();
    for (const f of this.dictFields()) {
      if (!map.has(f.nhomNguon)) { map.set(f.nhomNguon, []); order.push(f.nhomNguon); }
      map.get(f.nhomNguon)!.push(f);
    }
    return order.map((n) => ({ nhom: n, nhomLabel: INS_DICT_NHOM_LABEL[n], fields: map.get(n)! }));
  });

  /** Nguồn CHUNG (mọi loại) — suy từ dòng, giá trị chuỗi sẵn (Level 3, ẩn mặc định). */
  protected readonly dictCommon = computed<InsDictField[]>(() => {
    const c = this.change();
    const nv = insNhanVien(c.nhanVienId);
    const ky = insKy(c.kyTacDong)?.label ?? '—';
    const exc = c.nhomNgoaiLe.length ? c.nhomNgoaiLe.map((g) => this.excLabel(g)).join(' · ') : 'Không có';
    return [
      { ma: 'employee_id', nhan: 'Mã nhân viên', tag: 'SOURCE', nhomNguon: 'HRCore', giaTri: nv?.code ?? '—' },
      { ma: 'social_insurance_no', nhan: 'Mã số BHXH', tag: 'SOURCE', nhomNguon: 'Insurance', giaTri: c.maBHXH },
      { ma: 'employment_status', nhan: 'Trạng thái làm việc', tag: 'SOURCE', nhomNguon: 'HRCore', giaTri: 'Đang làm việc' },
      { ma: 'source_event_type', nhan: 'Loại sự kiện nguồn', tag: 'SYSTEM', nhomNguon: 'System', giaTri: c.nguon },
      { ma: 'detected_at', nhan: 'Thời điểm phát hiện', tag: 'SYSTEM', nhomNguon: 'System', giaTri: c.ngayPhatSinh || '—' },
      { ma: 'effective_date', nhan: 'Ngày hiệu lực', tag: 'SOURCE', nhomNguon: 'Document', giaTri: c.ngayHieuLuc || 'Thiếu mốc' },
      { ma: 'effective_period', nhan: 'Kỳ áp dụng', tag: 'DERIVED', nhomNguon: 'System', giaTri: ky },
      { ma: 'exception_type', nhan: 'Nhóm ngoại lệ', tag: 'DERIVED', nhomNguon: 'System', giaTri: exc },
      { ma: 'target_batch_id', nhan: 'Đợt kê khai', tag: 'SYSTEM', nhomNguon: 'System', giaTri: c.loBatchId || 'Chưa xếp đợt' },
    ];
  });

  /** §10 Nhãn nguồn — nhãn thuần Việt tự-diễn-giải cho panel (đầy đủ hơn chip bảng INS_DICT_TAG_LABEL). */
  protected tagLabel(t: InsDictTag): string { return INS_PROVENANCE_VN[t] ?? INS_DICT_TAG_LABEL[t]; }

  /** Khối đường ra: dòng còn nhóm ngoại lệ MỞ (chưa vào lô/rẽ nhánh). */
  protected readonly showOutcomes = computed(() => {
    const c = this.change();
    return c.nhomNgoaiLe.length > 0 && (c.trangThai === 'phat-hien' || c.trangThai === 'can-bo-sung' || c.trangThai === 'san-sang' || c.trangThai === 'da-xac-nhan');
  });
  protected readonly outcomes = computed(() => {
    const groups = this.change().nhomNgoaiLe;
    return M02_EXCEPTION_OUTCOMES.map((o) => ({ ...o, hit: o.groups.some((g) => groups.includes(g)) }));
  });

  /** Lịch sử của dòng — audit append-only lọc theo id (chuỗi thời gian sẵn từ store). */
  protected readonly history = computed<HrmTimelineItem[]>(() => {
    const id = this.change().id;
    return this.store.auditLog()
      .filter((e) => e.dongIds.includes(id))
      .map((e) => ({
        label: `${e.at} — ${e.hanhDong} (${e.nguoi})${e.truoc && e.sau ? ` · ${e.truoc} → ${e.sau}` : ''}${e.lyDo ? ` · lý do: ${e.lyDo}` : ''}`,
        color: (e.hanhDong.includes('Loại trừ') || e.hanhDong.includes('Bỏ khỏi')) ? 'red' as const : e.hanhDong.includes('lô') ? 'green' as const : 'blue' as const,
      }));
  });

  /** AI3 — chọn 1 giá trị đa nguồn làm căn cứ chốt (apply → validate rule → Sẵn sàng). */
  protected apDungGiaTri(giaTri: string, nguon: string): void {
    const r = this.store.apDungGiaTriDeXuat(this.change().id, giaTri, nguon);
    r.ok
      ? this.msg.success(`Đã chọn căn cứ ${nguon} (${giaTri}) — dòng chuyển Sẵn sàng.`)
      : this.msg.error(r.reason ?? 'Không áp dụng được giá trị.');
  }

  protected excLabel(g: string): string { return INS_EXCEPTION_LABEL[g as keyof typeof INS_EXCEPTION_LABEL] ?? g; }
  /** Nút mutating bị khóa khi chỉ đọc; nút điều hướng luôn dùng được. */
  protected isMutating(k: M02Outcome['actionKey']): boolean {
    return k === 'yeu-cau' || k === 'chon-thang' || k === 'phan-loai' || k === 'chuyen-tab4';
  }

  /* ── BÀN GIAO CHÉO (JOB A §13) — có ĐÍCH + người nhận + hạn: yêu cầu bổ sung / trả nguồn sửa / đã chuyển ── */

  /** Nhãn loại bàn giao đã ghi trên dòng (Yêu cầu bổ sung / Trả nguồn sửa). */
  protected banGiaoLabel(k: InsBanGiaoKind): string { return INS_BAN_GIAO_LABEL[k]; }
  /** Nhắc bên nhận khi bàn giao quá hạn (escalation). */
  protected nhacBanGiao(): void { this.store.nhacBanGiao(this.change().id); this.msg.success('Đã nhắc bên nhận phản hồi việc đã bàn giao.'); }
  /** Thu hồi bàn giao — dòng quay lại hàng chờ xử lý bình thường. */
  protected thuHoiBanGiao(): void { this.store.thuHoiBanGiao(this.change().id); this.msg.success('Đã thu hồi bàn giao — dòng trở lại hàng chờ xử lý.'); }

  /* Yêu cầu bổ sung — FORM inline (đích + người nhận + hạn), state signal-backed (zoneless-safe). */
  protected readonly yeuCauOpen = signal(false);
  private readonly yeuCauNguoiNhanSig = signal('');
  private readonly yeuCauHanSig = signal('');
  private readonly yeuCauLyDoSig = signal('');
  protected get yeuCauNguoiNhan(): string { return this.yeuCauNguoiNhanSig(); }
  protected set yeuCauNguoiNhan(v: string) { this.yeuCauNguoiNhanSig.set(v ?? ''); }
  protected get yeuCauHan(): string { return this.yeuCauHanSig(); }
  protected set yeuCauHan(v: string) { this.yeuCauHanSig.set(v ?? ''); }
  protected get yeuCauLyDo(): string { return this.yeuCauLyDoSig(); }
  protected set yeuCauLyDo(v: string) { this.yeuCauLyDoSig.set(v ?? ''); }
  /** Options "Gửi đến" = owner của dòng (mặc định) + các bộ phận/nghiệp vụ nhận (per-row, memoized → stable ref). */
  protected readonly yeuCauNguoiNhanOptions = computed<HrmOption[]>(() => {
    const owner = this.change().owner;
    return INS_NGUOI_NHAN_OPTIONS.includes(owner)
      ? INS_NGUOI_NHAN_SELECT
      : [{ label: owner, value: owner }, ...INS_NGUOI_NHAN_SELECT];
  });
  /** Mở form yêu cầu bổ sung — prefill người nhận = owner, hạn = ngày hạn xử lý của dòng nếu có. */
  private moFormYeuCau(): void {
    const c = this.change();
    this.yeuCauNguoiNhanSig.set(c.owner);
    this.yeuCauHanSig.set(c.ngayHanXuLy || '');
    this.yeuCauLyDoSig.set('');
    this.yeuCauOpen.set(true);
  }
  protected huyYeuCau(): void { this.yeuCauOpen.set(false); }
  /** Gửi yêu cầu bổ sung — ghi bản ghi bàn giao (người nhận + hạn + nội dung); toast theo kết quả store. */
  protected guiYeuCau(): void {
    const c = this.change();
    const nguoiNhan = this.yeuCauNguoiNhanSig().trim() || c.owner;
    const r = this.store.yeuCauBoSung([c.id], {
      nguoiNhan,
      hanPhanHoi: this.yeuCauHanSig().trim() || undefined,
      lyDo: this.yeuCauLyDoSig().trim() || undefined,
    });
    if (r.done) {
      this.msg.success(`Đã gửi yêu cầu bổ sung tới ${nguoiNhan} — gộp ${r.nguoiNhan} người nhận.`);
      this.yeuCauOpen.set(false);
    } else {
      this.msg.error(r.skipped[0]?.reason ?? 'Không gửi được yêu cầu.');
    }
  }

  /* Trả nguồn sửa — FORM inline (đích nghiệp vụ nguồn + lý do bắt buộc); băng đỏ inline khi store từ chối. */
  protected readonly nguoiNhanOptions = INS_NGUOI_NHAN_SELECT;
  private readonly traNguonNguoiNhanSig = signal('');
  private readonly traNguonLyDoSig = signal('');
  protected readonly traNguonError = signal('');
  protected get traNguonNguoiNhan(): string { return this.traNguonNguoiNhanSig(); }
  protected set traNguonNguoiNhan(v: string) { this.traNguonNguoiNhanSig.set(v ?? ''); }
  protected get traNguonLyDo(): string { return this.traNguonLyDoSig(); }
  protected set traNguonLyDo(v: string) { this.traNguonLyDoSig.set(v ?? ''); if (v?.trim()) this.traNguonError.set(''); }
  /** Trả nguồn sửa — bàn giao về nghiệp vụ nguồn (bắt buộc người nhận + lý do); {ok:false} → băng đỏ inline reason. */
  protected traNguon(): void {
    const c = this.change();
    const nguoiNhan = this.traNguonNguoiNhanSig();
    const r = this.store.traNguon(c.id, nguoiNhan, this.traNguonLyDoSig());
    if (r.ok) {
      this.msg.success(`Đã trả nguồn sửa → ${nguoiNhan.trim()} (chờ nguồn sửa xong).`);
      this.traNguonError.set('');
      this.traNguonLyDoSig.set('');
    } else {
      this.traNguonError.set(r.reason ?? 'Không trả nguồn được.');
    }
  }

  /* ── điều hướng chéo module — LUÔN mang {ky, donVi, filter} (navigation contract) ── */
  protected go360(): void { const c = this.change(); this.shell.go('m06', { ky: c.kyTacDong, donVi: c.donViId, filter: `nv:${c.nhanVienId}` }); }

  /** Chạy đường ra — transition store thật, thông báo kết quả; lý do bắt buộc → nhờ page prompt. */
  protected runOutcome(o: M02Outcome & { hit: boolean }, extra: boolean): void {
    const c = this.change();
    switch (o.actionKey) {
      case 'yeu-cau': { this.moFormYeuCau(); return; }
      case 'chon-thang': {
        if (!c.dongXungDot) { this.msg.error('Dòng không có bản ghi xung đột liên kết 2 chiều.'); return; }
        const r = extra ? this.store.xuLyXungDot(c.dongXungDot, c.id) : this.store.xuLyXungDot(c.id, c.dongXungDot);
        r.ok
          ? this.msg.success(extra ? `Đã giữ bản liên kết ${c.dongXungDot} — dòng này Đã loại trừ (link 2 chiều).` : `Đã giữ dòng này — bản thua ${c.dongXungDot} Đã loại trừ (link 2 chiều).`)
          : this.msg.error(r.reason ?? 'Không xử lý được xung đột.');
        return;
      }
      case 'phan-loai': {
        if (extra) {
          const r = this.store.banGiaoSuVu(c.id);
          if (r.ok) {
            this.msg.success('Đã bàn giao hồ sơ sự vụ — chuyển sang M06 để xử lý tiếp (không bao giờ qua lô kê khai).');
            this.go360();
          } else {
            this.msg.error(r.reason ?? 'Không bàn giao được.');
          }
        } else {
          this.requestReason.emit({ mode: 'phan-loai-d02', id: c.id });
        }
        return;
      }
      case 'mo-m08': this.shell.go('m08', { ky: c.kyTacDong, donVi: c.donViId, filter: 'danh-muc:ma-phuong-an' }); return;
      case 'chuyen-tab4': {
        if (c.loaiBienDong !== 'dieu-chinh') {
          const r = this.store.chuyenHoiTo(c.id);
          if (!r.ok) { this.msg.error(r.reason ?? 'Không chuyển được.'); return; }
          this.msg.success('Đã chuyển xử lý hồi tố sang Tab Điều chỉnh (mã phương án kỳ gốc).');
        }
        this.switchTab.emit('dieu-chinh');
        return;
      }
      case 'mo-m04': this.shell.go('m04', { ky: c.kyTacDong, donVi: c.donViId, filter: `ky:${c.kyTacDong}` }); return;
      case 'mo-m03': this.shell.go('m03', { ky: c.kyTacDong, donVi: c.donViId, filter: c.loBatchId ? `lo:${c.loBatchId}` : 'tra-lai' }); return;
    }
  }
}
