import { ChangeDetectionStrategy, Component, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { HrmAlert, HrmButton, HrmMessageService, HrmSelect, HrmSteps, HrmTag } from 'hrm-ui';
import { InsSectionLabel } from '../_shared';
import {
  InsM08DotPhatHanh, InsM08Store, M08_DOT_LABEL, M08_DUYET_LABEL, m08KhoangLabel,
} from '../_data/_m08-data';

/** M08 ⑤ — PHIÊN BẢN & PHÁT HÀNH QUY TẮC THEO ĐỢT (FN-21): đợt CHỈ nhận bản nháp (4 loại rule);
 *  MỘT ngày hiệu lực chung — mọi bản ghi lên CÙNG THỜI ĐIỂM (all-or-nothing); xung đột tại ngày
 *  hiệu lực → CẢ ĐỢT DỪNG (không bản nào lên, chỉ bản xung đột được nêu tên); thu hồi = PHIÊN BẢN
 *  MỚI từng quy tắc (rollback không xóa vết); vết đợt CHỈ-THÊM + correlation từ kỳ ngược về đợt.
 *  Timeline: Soạn → Chờ duyệt → Đã duyệt → Chờ hiệu lực → Đã phát hành (+ Trả lại · Thu hồi). */
@Component({
  selector: 'ins-m08-dot-page',
  imports: [FormsModule, HrmAlert, HrmButton, HrmSelect, HrmSteps, HrmTag, InsSectionLabel],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <ins-section-label text="Đợt phát hành — all-or-nothing theo NGÀY HIỆU LỰC CHUNG" tone="muted" [count]="store.dots().length" />

    @for (d of store.dots(); track d.ma) {
      <div class="p-dot" [class.p-dot--soan]="d.trangThai === 'soan'">
        <div class="p-dot__head">
          <span class="p-mono">{{ d.ma }}</span>
          <hrm-tag size="sm" [color]="d.trangThai === 'da-phat-hanh' ? 'green' : d.trangThai === 'thu-hoi' ? 'purple' : d.trangThai === 'soan' ? 'gray' : 'blue'">{{ label(d) }}</hrm-tag>
          <span class="p-muted">Ngày hiệu lực chung: <b>{{ d.ngayHieuLucChung }}</b> — mọi bản ghi lên CÙNG THỜI ĐIỂM</span>
          <span class="p-gap"></span>
          <span class="p-mono p-cor">{{ d.correlationId }}</span>
        </div>

        <hrm-steps [items]="steps" [current]="stepOf(d)" size="small" [status]="d.trangThai === 'tra-lai' || d.trangThai === 'thu-hoi' ? 'error' : 'process'" />

        <!-- Bản ghi trong đợt -->
        <div class="p-bans">
          @for (id of d.banGhiIds; track id) {
            <div class="p-ban" [class.p-ban--xd]="xungDot(d.ma).includes(id)">
              <span class="p-mono">{{ id }}</span>
              <span class="p-muted">{{ ruleTen(id) }} · {{ ruleKhoang(id) }} · {{ ruleTrangThai(id) }}</span>
              @if (xungDot(d.ma).includes(id)) { <hrm-tag size="sm" color="red">Bản xung đột</hrm-tag> }
              @if (d.trangThai === 'soan') {
                <hrm-button size="sm" (click)="go(d.ma, id)">Gỡ khỏi đợt</hrm-button>
              }
            </div>
          }
        </div>

        <!-- Guard phát hành: CẢ ĐỢT DỪNG -->
        @if (d.trangThai !== 'da-phat-hanh' && d.trangThai !== 'thu-hoi') {
          @if (phatHanhReason(d.ma); as reason) {
            @if (xungDot(d.ma).length) {
              <hrm-alert type="error" message="CẢ ĐỢT DỪNG" [description]="reason" />
            }
            <div class="p-acts">
              @if (d.trangThai === 'soan') {
                @if (guiDuyetReason(d.ma); as gd) {
                  <hrm-button size="sm" variant="primary" [disabled]="true">Gửi duyệt đợt</hrm-button>
                  <span class="p-err">{{ gd }}</span>
                } @else {
                  <hrm-button size="sm" variant="primary" (click)="guiDuyet(d.ma)">Gửi duyệt đợt</hrm-button>
                }
              }
              @if (d.trangThai === 'cho-duyet') {
                <hrm-select class="p-sel" [(ngModel)]="checkerModel" [options]="checkerOptions" size="sm" [allowClear]="false" [showSearch]="false" />
                <hrm-button size="sm" variant="primary" (click)="duyet(d.ma)">Duyệt đợt (≠ người soạn)</hrm-button>
                <hrm-button size="sm" [danger]="true" (click)="traLai(d.ma)">Trả lại đợt</hrm-button>
              }
              <hrm-button size="sm" variant="primary" [disabled]="true">Phát hành</hrm-button>
              @if (!xungDot(d.ma).length) { <span class="p-err">{{ reason }}</span> }
            </div>
          } @else {
            <div class="p-acts">
              @if (d.trangThai === 'da-duyet') {
                <hrm-button size="sm" (click)="choHieuLuc(d.ma)">Chuyển chờ hiệu lực</hrm-button>
              }
              <hrm-button size="sm" variant="primary" (click)="phatHanh(d.ma)">Phát hành CÙNG THỜI ĐIỂM ({{ d.banGhiIds.length }} bản ghi)</hrm-button>
            </div>
          }
        }
        @if (d.trangThai === 'da-phat-hanh') {
          <div class="p-acts">
            <span class="p-muted">Phát hành lúc {{ d.thoiDiemPH }} · người soạn {{ d.nguoiSoan }} · người duyệt {{ d.nguoiDuyet }}</span>
            <hrm-button size="sm" [danger]="true" (click)="thuHoi(d.ma)">Thu hồi đợt (= phiên bản mới từng quy tắc)</hrm-button>
          </div>
        }

        <!-- Vết chỉ-thêm -->
        <details class="p-vet">
          <summary>Vết đợt (chỉ-thêm) — {{ d.vet.length }} dòng · correlation {{ d.correlationId }} (kỳ lần ngược về đợt)</summary>
          @for (v of d.vet; track v.at) { <p class="p-vet__row">{{ v.at }} · {{ v.nguoi }} — {{ v.noiDung }}</p> }
        </details>
      </div>
    }
  `,
  host: { class: 'ins-m08-dot-page' },
  styles: [`
    :host { display: flex; flex-direction: column; gap: 12px; }
    .p-dot { border: 1px solid var(--border-sub); border-radius: var(--radius-lg); background: var(--bg-surface); padding: 12px 14px; display: flex; flex-direction: column; gap: 10px; }
    .p-dot--soan { border-style: dashed; }
    .p-dot__head { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
    .p-gap { flex: 1; }
    .p-mono { font-family: var(--font-mono, monospace); font-size: var(--fs-12); font-weight: 700; color: var(--text-strong); }
    .p-cor { color: var(--text-sub); font-weight: 600; }
    .p-muted { font-size: var(--fs-12); color: var(--text-sub); }
    .p-muted b { color: var(--text-strong); }
    .p-err { font-size: var(--fs-12); color: var(--error-text); font-weight: 500; }
    .p-bans { display: flex; flex-direction: column; gap: 5px; }
    .p-ban { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; border: 1px solid var(--border-sub); border-radius: var(--radius-md); padding: 6px 10px; }
    .p-ban--xd { border-color: var(--error-base); background: var(--error-bg); }
    .p-acts { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
    .p-sel { width: 230px; }
    .p-vet summary { font-size: var(--fs-12); color: var(--text-sub); cursor: pointer; }
    .p-vet__row { margin: 3px 0 0 14px; font-size: var(--fs-12); color: var(--text-body); }
  `],
})
export class InsM08DotPage {
  protected readonly store = inject(InsM08Store);
  private readonly msg = inject(HrmMessageService);

  protected readonly steps = [
    { title: 'Soạn' }, { title: 'Chờ duyệt' }, { title: 'Đã duyệt' }, { title: 'Chờ hiệu lực' }, { title: 'Đã phát hành' },
  ];
  protected stepOf(d: InsM08DotPhatHanh): number {
    switch (d.trangThai) {
      case 'soan': return 0;
      case 'cho-duyet': case 'tra-lai': return 1;
      case 'da-duyet': return 2;
      case 'cho-hieu-luc': return 3;
      default: return 4;
    }
  }
  protected label(d: InsM08DotPhatHanh): string { return M08_DOT_LABEL[d.trangThai]; }
  protected xungDot(ma: string): string[] { return this.store.dotXungDot(ma); }
  protected phatHanhReason(ma: string): string | null { return this.store.phatHanhDotReason(ma); }
  protected guiDuyetReason(ma: string): string | null { return this.store.guiDuyetDotReason(ma); }
  protected ruleTen(id: string): string { return this.store.ruleOf(id)?.ten ?? id; }
  protected ruleKhoang(id: string): string { const r = this.store.ruleOf(id); return r ? m08KhoangLabel(r.khoangHL) : ''; }
  protected ruleTrangThai(id: string): string { const r = this.store.ruleOf(id); return r ? M08_DUYET_LABEL[r.trangThai] : ''; }

  protected readonly checkerOptions = this.store.nguoiDuyetOptions.map((o) => ({ value: o, label: o }));
  private readonly checker = signal(this.store.nguoiDuyetOptions[0]);
  protected get checkerModel(): unknown { return this.checker(); }
  protected set checkerModel(v: unknown) { this.checker.set(String(v ?? '')); }

  protected go(dotMa: string, ruleId: string): void {
    const r = this.store.goKhoiDot(dotMa, ruleId);
    r.ok ? this.msg.success(`Đã gỡ ${ruleId} khỏi đợt — cách thoát xung đột, bản ghi về nháp tự do.`) : this.msg.error(r.reason ?? '');
  }
  protected guiDuyet(ma: string): void {
    const r = this.store.guiDuyetDot(ma);
    r.ok ? this.msg.success('Đã gửi duyệt đợt — maker mất quyền sửa bản ghi trong đợt.') : this.msg.error(r.reason ?? '');
  }
  protected duyet(ma: string): void {
    const r = this.store.duyetDot(ma, this.checker());
    r.ok ? this.msg.success(`Đợt được duyệt bởi ${this.checker()} → Đã duyệt.`) : this.msg.error(r.reason ?? '');
  }
  protected traLai(ma: string): void {
    const r = this.store.traLaiDot(ma, 'Trả lại để chỉnh sửa (checker ≠ maker)');
    r.ok ? this.msg.success('Đã trả lại đợt về Soạn — maker chỉnh sửa rồi gửi duyệt lại.') : this.msg.error(r.reason ?? '');
  }
  protected choHieuLuc(ma: string): void {
    const r = this.store.chuyenChoHieuLuc(ma);
    r.ok ? this.msg.success('Đợt Đã duyệt → Chờ hiệu lực (khóa chờ ngày hiệu lực chung).') : this.msg.error(r.reason ?? '');
  }
  protected phatHanh(ma: string): void {
    const r = this.store.phatHanhDot(ma);
    r.ok ? this.msg.success('Đã phát hành CÙNG THỜI ĐIỂM — bản hiệu lực cũ tự hết hiệu lực (không ghi đè lịch sử).') : this.msg.error(r.reason ?? '');
  }
  protected thuHoi(ma: string): void {
    const r = this.store.thuHoiDot(ma, 'Phát hiện sai cấu phần sau phát hành');
    r.ok ? this.msg.success('Đã THU HỒI đợt — mỗi quy tắc sinh PHIÊN BẢN MỚI, vết giữ nguyên.') : this.msg.error(r.reason ?? '');
  }
}
