import { ChangeDetectionStrategy, Component, TemplateRef, computed, inject, input, signal, viewChild } from '@angular/core';
import { FormsModule } from '@angular/forms';
import {
  HrmButton, HrmDetailPeek, HrmEmpty, HrmGrid, HrmGridColumn, HrmInput, HrmMessageService,
  HrmModalService, HrmPeekMode, HrmSelect, HrmStatusCell, HrmTag, HrmTextarea,
} from 'hrm-ui';
import { InsLayerBadge } from '../_shared';
import { insNhanVien } from '../_data/_core';
import { insFormatVnd, insParseVnd } from '../_data/_m02-data';
import {
  INS_QUY_LABEL, InsKySnapshot, InsM04Store, InsQuy, M04_NGUOI_DUYET, M04_QUYS,
  M04_SAN_LUONG_DONG, M04_SNAPSHOT_LABEL, M04_SNAPSHOT_TONE, M04_TRAN_LUONG_DONG, M04_TY_LE,
} from '../_data/_m04-data';
import {
  M04_BT_COLS, M04_CT_COLS, M04_DONG_COLS, buildButToanRow, buildChungTuRow, buildDeNghiRow, buildDongRow,
} from './_m04-columns';

/** ═════════ M04 · T1 SNAPSHOT — bảng 4 quỹ × 3 chỉ tiêu (cell-drill) + bảng cấp người
 *  + khối Thanh toán (chứng từ 3 trạng thái · đề nghị 6+1) + sổ bút toán append-only ═════════
 *  Nhãn lớp (bất biến #1): phải đóng snapshot = `Dự kiến nội bộ` · đã đóng theo chứng từ =
 *  `Đã giao dịch/chấp nhận`. Còn thiếu ÂM → nhãn "nộp thừa" (không số 0 giả).
 *  Sửa/loại dòng cấp người = modal lý do BẮT BUỘC; vượt trần/sàn → cảnh báo + tự đặt lại (store).
 *  Sổ bút toán KHÔNG có nút xóa — chỉ Lập (lý do) / Gửi duyệt / Duyệt (maker ≠ checker) / Đảo. */
@Component({
  selector: 'ins-m04-tab-snapshot',
  imports: [
    FormsModule, HrmButton, HrmDetailPeek, HrmEmpty, HrmGrid, HrmInput, HrmSelect, HrmStatusCell,
    HrmTag, HrmTextarea, InsLayerBadge,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (snapshot(); as snap) {
      <!-- ── chọn phiên bản + trạng thái snapshot ── -->
      <div class="t1-head">
        <span class="t1-head__lb">Phiên bản snapshot</span>
        <hrm-select class="t1-head__ver" [(ngModel)]="verModel" [options]="verOptions()" size="sm"
          [allowClear]="false" [showSearch]="false" />
        <hrm-status-cell [status]="$any(snapTone())" [label]="snapLabel()" variant="badge" />
        <span class="t1-head__note">{{ snap.taiThoiDiem }}@if (snap.ghiChu) { · {{ snap.ghiChu }}}</span>
        <span class="t1-head__gap"></span>
        <span class="t1-head__sodu">Số dư đầu kỳ:
          @if (soDuDauKy() === null) { <b>không tính được</b> }
          @else { <b>{{ soDuDauKyLabel() }}</b> <span class="t1-muted">(kế thừa số dư cuối kỳ trước)</span> }
        </span>
        @if (!kyLocked()) {
          <hrm-button size="sm" (click)="dungSnapshot()">Dựng snapshot mới</hrm-button>
        }
      </div>

      <!-- ── bảng 4 quỹ × 3 chỉ tiêu ── -->
      <section class="t1-sec">
        <h3 class="t1-sec__title">Nghĩa vụ theo quỹ
          <span class="t1-sec__hint">Phải đóng <ins-layer-badge layer="du-kien" /> · Đã đóng <ins-layer-badge layer="da-giao-dich" /> · ô bấm được → danh sách NLĐ đóng góp</span>
        </h3>
        <table class="t1-funds">
          <thead>
            <tr><th>Quỹ</th><th class="num">Phải đóng</th><th class="num">Đã đóng</th><th class="num">Còn thiếu</th></tr>
          </thead>
          <tbody>
            @for (r of fundRows(); track r.quy) {
              <tr>
                <td>{{ r.label }}</td>
                <td class="num"><button type="button" class="t1-cell" (click)="openFundPeek(r.quy, 'phai')">{{ r.phaiDong }}</button></td>
                <td class="num"><button type="button" class="t1-cell" (click)="openFundPeek(r.quy, 'da')">{{ r.daDong }}</button></td>
                <td class="num">
                  <button type="button" class="t1-cell" [class.t1-cell--warn]="r.thieuAm" (click)="openFundPeek(r.quy, 'thieu')">{{ r.conThieu }}</button>
                </td>
              </tr>
            }
            <tr class="t1-funds__total">
              <td>Tổng</td>
              <td class="num">{{ tong().phaiDong }}</td>
              <td class="num">{{ tong().daDong }}</td>
              <td class="num">{{ tong().conThieu }}</td>
            </tr>
          </tbody>
        </table>
        <p class="t1-funds__note">
          「Đã đóng」tách 3 trạng thái chứng từ: Đã phân bổ theo C12 <b>{{ daDongTach().phanBo }}</b>
          · Đã khớp nghĩa vụ <b>{{ daDongTach().khop }}</b> · Đã ghi nhận (chưa khớp — KHÔNG tính, vào chênh lệch)
          <b>{{ daDongTach().ghiNhan }}</b>.
        </p>
      </section>

      <!-- ── bảng cấp người ── -->
      <section class="t1-sec">
        <h3 class="t1-sec__title">Dòng lao động trong kỳ ({{ dongRows().length }})
          <span class="t1-sec__hint">Sửa/loại bắt buộc lý do · vượt trần {{ tranLabel }} / sàn {{ sanLabel }} → cảnh báo + tự đặt lại · thay đổi xong cần Dựng snapshot mới</span>
        </h3>
        <hrm-grid [columns]="dongCols()" [data]="dongRows()" rowKey="id" density="compact"
          minWidth="1160px" [pageSize]="12" [showPagination]="false" />
      </section>

      <!-- ── khối thanh toán ── -->
      <section class="t1-sec">
        <h3 class="t1-sec__title">Thanh toán — chứng từ nộp ({{ ctRows().length }})</h3>
        <hrm-grid [columns]="ctCols()" [data]="ctRows()" rowKey="id" density="compact"
          minWidth="1100px" [showPagination]="false" />

        <div class="t1-dn-head">
          <h3 class="t1-sec__title">Đề nghị thanh toán ({{ dnRows().length }})</h3>
          @if (!kyLocked()) { <hrm-button size="sm" (click)="lapDeNghi()">Lập đề nghị từ còn thiếu</hrm-button> }
        </div>
        @for (r of dnRows(); track r.id) {
          <div class="t1-dn">
            <div class="t1-dn__main">
              <span class="t1-dn__id">{{ r.id }}</span>
              <hrm-status-cell [status]="$any(r.trangThaiTone)" [label]="r.trangThaiLabel" variant="badge" />
              <span class="t1-dn__quy">{{ r.theoQuy }}</span>
              <span class="t1-dn__tong">{{ r.tong }} <ins-layer-badge layer="du-kien" /></span>
            </div>
            <div class="t1-dn__sub">Hạn nộp {{ r.hanNop }} · {{ r.nguoi }}@if (r.ghiChu) { · {{ r.ghiChu }}}</div>
            <div class="t1-dn__act">
              @if (r.canGuiDuyet) { <hrm-button size="sm" (click)="dnAction('gui-duyet', r.id)">Gửi duyệt</hrm-button> }
              @if (r.canDuyet) { <hrm-button size="sm" variant="primary" (click)="openDuyet('de-nghi', r.id)">Duyệt</hrm-button> }
              @if (r.canGuiKeToan) { <hrm-button size="sm" (click)="dnAction('gui-ke-toan', r.id)">Gửi kế toán</hrm-button> }
              @if (r.canThuHoi) { <hrm-button size="sm" [danger]="true" (click)="openReason('thu-hoi-dn', r.id)">Thu hồi</hrm-button> }
            </div>
          </div>
        } @empty { <hrm-empty preset="no-data" description="Chưa có đề nghị thanh toán cho kỳ này." /> }
      </section>

      <!-- ── sổ bút toán (append-only — KHÔNG có nút Xóa) ── -->
      <section class="t1-sec">
        <div class="t1-dn-head">
          <h3 class="t1-sec__title">Sổ bút toán điều chỉnh ({{ btRows().length }})
            <span class="t1-sec__hint">Append-only — không xóa; sai thì ĐẢO (cặp gốc–đảo link nhau, tổng cặp = 0)</span>
          </h3>
          @if (!kyLocked()) { <hrm-button size="sm" (click)="openLapBT()">Lập bút toán</hrm-button> }
        </div>
        <hrm-grid [columns]="btCols()" [data]="btRows()" rowKey="id" density="compact"
          minWidth="1240px" [showPagination]="false" />
      </section>
    } @else {
      <div class="t1-empty">
        <hrm-empty preset="no-data" description="Chưa có số liệu cho kỳ này" />
        <p class="t1-empty__note">Kỳ đang Mở — biến động chưa xử lý xong (M02), chưa dựng snapshot.</p>
        <hrm-button size="sm" [disabled]="true" title="Chưa có số liệu cho kỳ này — biến động kỳ chưa xử lý xong (M02)">Dựng snapshot</hrm-button>
      </div>
    }

    <!-- ═════ cell templates ═════ -->
    <ng-template #dongUserCell let-row>
      <div class="t1-user"><span class="t1-user__name" [class.t1-user__name--dim]="$any(row).loaiKhoiKy">{{ $any(row).ten }}</span><span class="t1-user__sub">{{ $any(row).sub }}</span></div>
    </ng-template>
    <ng-template #dongStatusCell let-row>
      <hrm-status-cell [status]="$any(row).trangThaiTone" [label]="$any(row).trangThaiLabel" variant="badge" />
    </ng-template>
    <ng-template #dongActCell let-row>
      @if (!$any(row).readonly_) {
        <span class="t1-actrow">
          <button type="button" class="t1-link" (click)="openSua($any(row).id)">Sửa</button>
          <button type="button" class="t1-link t1-link--danger" (click)="openReason('loai-dong', $any(row).id)">Loại</button>
        </span>
      } @else { <span class="t1-muted">chỉ đọc</span> }
    </ng-template>

    <ng-template #ctStatusCell let-row>
      <hrm-status-cell [status]="$any(row).trangThaiTone" [label]="$any(row).trangThaiLabel" variant="badge" />
    </ng-template>

    <ng-template #btStatusCell let-row>
      <div class="t1-btst">
        <hrm-status-cell [status]="$any(row).trangThaiTone" [label]="$any(row).trangThaiLabel" variant="badge" />
        @if ($any(row).refDao) { <hrm-tag color="purple" size="sm" variant="lighter">↔ {{ $any(row).refDao }}</hrm-tag> }
      </div>
    </ng-template>
    <ng-template #btMoneyCell let-row>
      <span class="t1-money" [class.t1-money--neg]="$any(row).giaTriAm">{{ $any(row).giaTri }}</span>
    </ng-template>
    <ng-template #btActCell let-row>
      <span class="t1-actrow">
        @if ($any(row).canGuiDuyet) { <button type="button" class="t1-link" (click)="btGuiDuyet($any(row).id)">Gửi duyệt</button> }
        @if ($any(row).canDuyet) { <button type="button" class="t1-link" (click)="openDuyet('but-toan', $any(row).id)">Duyệt</button> }
        @if ($any(row).canDao) { <button type="button" class="t1-link t1-link--danger" (click)="openReason('dao-bt', $any(row).id)">Đảo</button> }
      </span>
    </ng-template>

    <!-- ═════ peek NLĐ đóng góp theo ô quỹ ═════ -->
    <hrm-detail-peek [(open)]="peekOpenModel" peekMode="side" [modes]="peekModes" [expandable]="false"
      [title]="peekTitle()" [content]="fundPeekTpl" [width]="440" closeLabel="Đóng" />
    <ng-template #fundPeekTpl>
      @if (peekCtx(); as ctx) {
        <div class="t1-peek">
          <p class="t1-peek__note">{{ ctx.note }}</p>
          @for (p of ctx.people; track p.id) {
            <div class="t1-peek__row"><span>{{ p.name }}</span><span class="t1-peek__sub">{{ p.sub }}</span><b>{{ p.amount }}</b></div>
          }
          <div class="t1-peek__total"><span>Tổng {{ ctx.chiTieuLabel }}</span><b>{{ ctx.total }}</b><ins-layer-badge [layer]="ctx.layer" /></div>
          @if (ctx.extra) { <p class="t1-peek__note">{{ ctx.extra }}</p> }
        </div>
      }
    </ng-template>

    <!-- ═════ modal lý do dùng chung ═════ -->
    <ng-template #reasonTpl>
      <div class="t1-form">
        <p class="t1-form__hint">{{ reasonHint() }}</p>
        <hrm-textarea [(ngModel)]="reasonModel" placeholder="Nhập lý do (bắt buộc)…" [minRows]="3" [status]="reasonErr() ? 'error' : ''" />
        @if (reasonErr()) { <span class="t1-form__err">{{ reasonErr() }}</span> }
      </div>
    </ng-template>

    <!-- modal sửa lương (trần/sàn) -->
    <ng-template #suaTpl>
      <div class="t1-form">
        <p class="t1-form__hint">Sửa tay lương đóng — vượt trần {{ tranLabel }} hoặc dưới sàn {{ sanLabel }} sẽ CẢNH BÁO và tự đặt lại về giới hạn. Bắt buộc lý do.</p>
        <hrm-input [(ngModel)]="suaLuongModel" placeholder="Lương đóng mới, VD 21.500.000" />
        <hrm-textarea [(ngModel)]="reasonModel" placeholder="Lý do sửa (bắt buộc)…" [minRows]="2" [status]="reasonErr() ? 'error' : ''" />
        @if (reasonErr()) { <span class="t1-form__err">{{ reasonErr() }}</span> }
      </div>
    </ng-template>

    <!-- modal duyệt (maker ≠ checker) -->
    <ng-template #duyetTpl>
      <div class="t1-form">
        <p class="t1-form__hint">Chọn người duyệt — GUARD maker ≠ checker: người lập không được tự duyệt (chọn chính mình để thấy guard chặn).</p>
        <hrm-select [(ngModel)]="duyetNguoiModel" [options]="nguoiDuyetOptions" [allowClear]="false" [showSearch]="false" />
        @if (reasonErr()) { <span class="t1-form__err">{{ reasonErr() }}</span> }
      </div>
    </ng-template>

    <!-- modal lập bút toán -->
    <ng-template #lapBtTpl>
      <div class="t1-form">
        <p class="t1-form__hint">Sổ điều chỉnh append-only — bút toán lập xong vào Chờ duyệt; KHÔNG có thao tác xóa, sai thì lập bút toán đảo.</p>
        <hrm-input [(ngModel)]="btGiaTriModel" placeholder="Giá trị (VD +300.000 hoặc −300.000)" />
        <hrm-textarea [(ngModel)]="reasonModel" placeholder="Lý do (bắt buộc)…" [minRows]="2" [status]="reasonErr() ? 'error' : ''" />
        @if (reasonErr()) { <span class="t1-form__err">{{ reasonErr() }}</span> }
      </div>
    </ng-template>
  `,
  host: { class: 'ins-m04-tab-snapshot' },
  styles: [`
    :host { display: flex; flex-direction: column; gap: 18px; min-height: 0; overflow: auto; padding: 12px 2px 24px; }

    .t1-head { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
    .t1-head__lb { font-size: var(--fs-12); color: var(--text-sub); }
    .t1-head__ver { display: inline-block; width: 210px; }
    .t1-head__note { font-size: var(--fs-12); color: var(--text-soft); }
    .t1-head__gap { flex: 1; }
    .t1-head__sodu { font-size: var(--fs-12); color: var(--text-sub); }
    .t1-head__sodu b { color: var(--text-strong); }

    .t1-sec { display: flex; flex-direction: column; gap: 8px; }
    .t1-sec__title { margin: 0; font-size: var(--fs-13); font-weight: 600; color: var(--text-strong); display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
    .t1-sec__hint { font-size: var(--fs-11); font-weight: 400; color: var(--text-soft); display: inline-flex; align-items: center; gap: 4px; }

    .t1-funds { border-collapse: collapse; width: 100%; max-width: 720px; font-size: var(--fs-13); }
    .t1-funds th, .t1-funds td { border: 1px solid var(--border-sub); padding: 7px 12px; text-align: left; }
    .t1-funds th { background: var(--bg-surface-subtle); font-weight: 600; color: var(--text-sub); font-size: var(--fs-12); }
    .t1-funds .num { text-align: right; font-variant-numeric: tabular-nums; }
    .t1-funds__total td { font-weight: 700; background: var(--bg-surface-subtle); color: var(--text-strong); }
    .t1-cell { border: 0; background: none; padding: 0; cursor: pointer; font: inherit; color: var(--primary-base); font-variant-numeric: tabular-nums; }
    .t1-cell:hover { text-decoration: underline; }
    .t1-cell--warn { color: var(--warning-text); font-weight: 600; }
    .t1-funds__note { margin: 0; font-size: var(--fs-12); color: var(--text-sub); }
    .t1-funds__note b { color: var(--text-strong); font-variant-numeric: tabular-nums; }

    .t1-user { display: flex; flex-direction: column; min-width: 0; }
    .t1-user__name { color: var(--text-strong); font-weight: 500; }
    .t1-user__name--dim { color: var(--text-soft); text-decoration: line-through; }
    .t1-user__sub { font-size: var(--fs-12); color: var(--text-sub); }
    .t1-muted { color: var(--text-soft); font-size: var(--fs-12); }
    .t1-actrow { display: inline-flex; gap: 10px; }
    .t1-link { border: 0; background: none; padding: 0; cursor: pointer; font: inherit; font-size: var(--fs-12); font-weight: 600; color: var(--primary-base); }
    .t1-link--danger { color: var(--error-base); }
    .t1-money { font-variant-numeric: tabular-nums; font-weight: 600; color: var(--text-strong); }
    .t1-money--neg { color: var(--success-base); }
    .t1-btst { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }

    .t1-dn-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
    .t1-dn { border: 1px solid var(--border-sub); border-radius: var(--radius-md); padding: 10px 14px; display: flex; flex-direction: column; gap: 4px; }
    .t1-dn__main { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
    .t1-dn__id { font-weight: 700; color: var(--text-strong); }
    .t1-dn__quy { font-size: var(--fs-12); color: var(--text-sub); font-variant-numeric: tabular-nums; }
    .t1-dn__tong { margin-left: auto; font-weight: 700; color: var(--text-strong); font-variant-numeric: tabular-nums; display: inline-flex; align-items: center; gap: 6px; }
    .t1-dn__sub { font-size: var(--fs-12); color: var(--text-soft); }
    .t1-dn__act { display: flex; gap: 8px; }

    .t1-empty { display: flex; flex-direction: column; align-items: center; gap: 8px; padding: 56px 0; }
    .t1-empty__note { margin: 0; font-size: var(--fs-12); color: var(--text-soft); }

    .t1-peek { display: flex; flex-direction: column; gap: 6px; font-size: var(--fs-13); }
    .t1-peek__note { margin: 0 0 4px; font-size: var(--fs-12); color: var(--text-sub); }
    .t1-peek__row { display: flex; align-items: baseline; gap: 8px; padding: 3px 0; border-bottom: 1px dashed var(--border-sub); }
    .t1-peek__row b { margin-left: auto; font-variant-numeric: tabular-nums; color: var(--text-strong); }
    .t1-peek__sub { font-size: var(--fs-11); color: var(--text-soft); }
    .t1-peek__total { display: flex; align-items: center; gap: 8px; padding-top: 8px; font-weight: 600; }
    .t1-peek__total b { margin-left: auto; font-variant-numeric: tabular-nums; }

    .t1-form { display: flex; flex-direction: column; gap: 8px; }
    .t1-form__hint { margin: 0; font-size: var(--fs-12); color: var(--text-sub); }
    .t1-form__err { font-size: var(--fs-12); color: var(--error-text); }
  `],
})
export class InsM04TabSnapshot {
  protected readonly store = inject(InsM04Store);
  private readonly msg = inject(HrmMessageService);
  private readonly modal = inject(HrmModalService);

  readonly kyId = input.required<string>();

  protected readonly tranLabel = insFormatVnd(M04_TRAN_LUONG_DONG);
  protected readonly sanLabel = insFormatVnd(M04_SAN_LUONG_DONG);
  protected readonly nguoiDuyetOptions = M04_NGUOI_DUYET.map((n) => ({ value: n, label: n }));

  protected readonly kyLocked = computed(() => this.store.isKyKhoa(this.kyId()));

  /* ── phiên bản snapshot ── */
  private readonly verSel = signal<string | null>(null);
  protected get verModel(): unknown { return this.snapshot()?.id ?? null; }
  protected set verModel(v: unknown) { this.verSel.set((v as string) || null); }
  protected readonly verOptions = computed(() =>
    this.store.snapshotsOf(this.kyId()).map((s) => ({ value: s.id, label: `v${s.phienBan} — ${s.taiThoiDiem}` })));
  protected readonly snapshot = computed<InsKySnapshot | undefined>(() => {
    const list = this.store.snapshotsOf(this.kyId());
    const sel = this.verSel();
    return (sel && list.find((s) => s.id === sel)) || list[0];
  });
  protected readonly snapLabel = computed(() => { const s = this.snapshot(); return s ? M04_SNAPSHOT_LABEL[s.trangThai] : ''; });
  protected readonly snapTone = computed(() => { const s = this.snapshot(); return s ? M04_SNAPSHOT_TONE[s.trangThai] : 'neutral'; });
  protected readonly soDuDauKy = computed(() => this.store.meta(this.kyId())?.soDuDauKy ?? null);
  protected readonly soDuDauKyLabel = computed(() => {
    const v = this.soDuDauKy();
    if (v === null) return '';
    if (v === 0) return '0 (kỳ trước đã đóng đủ)';
    return v < 0 ? `${insFormatVnd(v)} — nộp thừa mang sang` : `${insFormatVnd(v)} — còn thiếu mang sang`;
  });

  /* ── bảng 4 quỹ × 3 chỉ tiêu ── */
  protected readonly fundRows = computed(() => {
    const s = this.snapshot();
    if (!s) return [];
    return M04_QUYS.map((quy) => {
      const f = s.funds[quy];
      const thieu = f.phaiDong - f.daDong;
      return {
        quy, label: INS_QUY_LABEL[quy],
        phaiDong: insFormatVnd(f.phaiDong), daDong: insFormatVnd(f.daDong),
        conThieu: thieu < 0 ? `nộp thừa ${insFormatVnd(-thieu)}` : insFormatVnd(thieu),
        thieuAm: thieu < 0,
      };
    });
  });
  protected readonly tong = computed(() => {
    const s = this.snapshot();
    if (!s) return { phaiDong: '', daDong: '', conThieu: '' };
    const pd = M04_QUYS.reduce((x, q) => x + s.funds[q].phaiDong, 0);
    const dd = M04_QUYS.reduce((x, q) => x + s.funds[q].daDong, 0);
    return { phaiDong: insFormatVnd(pd), daDong: insFormatVnd(dd), conThieu: insFormatVnd(pd - dd) };
  });
  /** "Đã đóng" chú thích 3 số tách theo trạng thái chứng từ. */
  protected readonly daDongTach = computed(() => {
    const cts = this.store.chungTu().filter((c) => c.kyId === this.kyId());
    const sum = (st: string) => cts.filter((c) => c.trangThai === st).reduce((s, c) => s + c.soTien, 0);
    return {
      phanBo: insFormatVnd(sum('da-phan-bo-c12')), khop: insFormatVnd(sum('da-khop-nghia-vu')), ghiNhan: insFormatVnd(sum('da-ghi-nhan')),
    };
  });

  /* ── peek NLĐ đóng góp ── */
  protected readonly peekModes: HrmPeekMode[] = ['side'];
  private readonly peekOpen = signal(false);
  protected get peekOpenModel(): boolean { return this.peekOpen(); }
  protected set peekOpenModel(v: boolean) { this.peekOpen.set(v); }
  protected readonly peekCtx = signal<{
    note: string; chiTieuLabel: string; total: string; layer: 'du-kien' | 'da-giao-dich';
    people: { id: string; name: string; sub: string; amount: string }[]; extra?: string;
  } | null>(null);
  protected readonly peekTitle = signal('');

  protected openFundPeek(quy: InsQuy, chiTieu: 'phai' | 'da' | 'thieu'): void {
    const s = this.snapshot();
    if (!s) return;
    const f = s.funds[quy];
    const active = s.dong.filter((d) => d.trangThai !== 'da-loai-khoi-ky');
    const people = active.map((d) => {
      const nv = insNhanVien(d.nhanVienId);
      return { id: d.id, name: nv?.name ?? '—', sub: `lương ${insFormatVnd(d.luongDong)} × ${M04_TY_LE[quy] * 100}%`,
        amount: insFormatVnd(d.luongDong * M04_TY_LE[quy]) };
    });
    const thieu = f.phaiDong - f.daDong;
    const label = chiTieu === 'phai' ? 'Phải đóng' : chiTieu === 'da' ? 'Đã đóng' : 'Còn thiếu';
    this.peekTitle.set(`${INS_QUY_LABEL[quy]} — ${label}`);
    this.peekCtx.set({
      note: chiTieu === 'phai'
        ? `Nghĩa vụ ${INS_QUY_LABEL[quy]} cấp người (snapshot v${s.phienBan} — lớp Dự kiến nội bộ):`
        : chiTieu === 'da'
          ? `Đã đóng ghi theo CHỨNG TỪ (lớp Đã giao dịch) — liệt kê nghĩa vụ cấp người để đối chiếu:`
          : thieu < 0
            ? `Quỹ ${INS_QUY_LABEL[quy]} NỘP THỪA ${insFormatVnd(-thieu)} — nghĩa vụ cấp người để đối chiếu:`
            : `Còn thiếu ${insFormatVnd(thieu)} — nghĩa vụ cấp người để đối chiếu:`,
      chiTieuLabel: label.toLowerCase(),
      total: chiTieu === 'phai' ? insFormatVnd(f.phaiDong) : chiTieu === 'da' ? insFormatVnd(f.daDong)
        : thieu < 0 ? `nộp thừa ${insFormatVnd(-thieu)}` : insFormatVnd(thieu),
      layer: chiTieu === 'phai' ? 'du-kien' : 'da-giao-dich',
      people,
      extra: chiTieu === 'da' ? 'Đã đóng không tách được cấp người từ chứng từ gộp — phân bổ cấp người chờ C12 (không hiển thị số 0 giả).' : undefined,
    });
    this.peekOpen.set(true);
  }

  /* ── bảng cấp người ── */
  private readonly dongUserTpl = viewChild.required<TemplateRef<unknown>>('dongUserCell');
  private readonly dongStatusTpl = viewChild.required<TemplateRef<unknown>>('dongStatusCell');
  private readonly dongActTpl = viewChild.required<TemplateRef<unknown>>('dongActCell');
  protected readonly dongRows = computed(() => {
    const locked = this.kyLocked();
    return (this.store.dongLaoDong()[this.kyId()] ?? []).map((d) => buildDongRow(d, locked));
  });
  protected readonly dongCols = computed<HrmGridColumn[]>(() => {
    const tpl: Record<string, TemplateRef<unknown> | undefined> = {
      ten: this.dongUserTpl(), trangThai: this.dongStatusTpl(), act: this.dongActTpl(),
    };
    return M04_DONG_COLS.map((c) => ({ ...c, cell: tpl[c.key] as HrmGridColumn['cell'] }));
  });

  /* ── chứng từ + đề nghị ── */
  private readonly ctStatusTpl = viewChild.required<TemplateRef<unknown>>('ctStatusCell');
  protected readonly ctRows = computed(() =>
    this.store.chungTu().filter((c) => c.kyId === this.kyId()).map(buildChungTuRow));
  protected readonly ctCols = computed<HrmGridColumn[]>(() =>
    M04_CT_COLS.map((c) => ({ ...c, cell: (c.key === 'trangThai' ? this.ctStatusTpl() : undefined) as HrmGridColumn['cell'] })));
  protected readonly dnRows = computed(() => {
    const locked = this.kyLocked();
    return this.store.deNghi().filter((d) => d.kyId === this.kyId()).map((d) => buildDeNghiRow(d, locked));
  });

  /* ── sổ bút toán ── */
  private readonly btStatusTpl = viewChild.required<TemplateRef<unknown>>('btStatusCell');
  private readonly btMoneyTpl = viewChild.required<TemplateRef<unknown>>('btMoneyCell');
  private readonly btActTpl = viewChild.required<TemplateRef<unknown>>('btActCell');
  protected readonly btRows = computed(() => {
    const locked = this.kyLocked();
    return this.store.butToan().filter((b) => b.kyPhatSinh === this.kyId()).map((b) => buildButToanRow(b, locked));
  });
  protected readonly btCols = computed<HrmGridColumn[]>(() => {
    const tpl: Record<string, TemplateRef<unknown> | undefined> = {
      trangThai: this.btStatusTpl(), giaTri: this.btMoneyTpl(), act: this.btActTpl(),
    };
    return M04_BT_COLS.map((c) => ({ ...c, cell: tpl[c.key] as HrmGridColumn['cell'] }));
  });

  /* ── actions + modal ── */
  private dlg: { close: () => void } | null = null;
  private readonly reasonMode = signal<'loai-dong' | 'dao-bt' | 'thu-hoi-dn'>('loai-dong');
  private readonly reasonRef = signal('');
  private readonly reasonText = signal('');
  protected get reasonModel(): string { return this.reasonText(); }
  protected set reasonModel(v: string) { this.reasonText.set(v ?? ''); if (v?.trim()) this.reasonErr.set(''); }
  protected readonly reasonErr = signal('');
  protected readonly reasonHint = computed(() => {
    switch (this.reasonMode()) {
      case 'loai-dong': return 'Loại khỏi kỳ — KHÔNG xóa vật lý; dòng giữ lại với lý do. Dựng lại snapshot để cập nhật bảng quỹ.';
      case 'dao-bt': return 'Đảo bút toán — sinh bút toán MỚI giá trị đối, link 2 chiều với bản gốc; tổng cặp về 0.';
      case 'thu-hoi-dn': return 'Thu hồi đề nghị — bản cũ vẫn tra được (không xóa lịch sử).';
    }
  });
  private readonly reasonTplRef = viewChild<TemplateRef<unknown>>('reasonTpl');
  private readonly suaTplRef = viewChild<TemplateRef<unknown>>('suaTpl');
  private readonly duyetTplRef = viewChild<TemplateRef<unknown>>('duyetTpl');
  private readonly lapBtTplRef = viewChild<TemplateRef<unknown>>('lapBtTpl');

  protected openReason(mode: 'loai-dong' | 'dao-bt' | 'thu-hoi-dn', id: string): void {
    this.reasonMode.set(mode); this.reasonRef.set(id); this.reasonText.set(''); this.reasonErr.set('');
    const title = mode === 'loai-dong' ? 'Loại khỏi kỳ (lý do bắt buộc)' : mode === 'dao-bt' ? 'Đảo bút toán' : 'Thu hồi đề nghị';
    this.dlg = this.modal.open({
      title, content: this.reasonTplRef()!, width: 460,
      footer: [
        { label: 'Hủy', onClick: () => this.dlg?.close() },
        { label: title, type: 'primary', danger: true, onClick: () => this.confirmReason() },
      ],
    });
  }
  private confirmReason(): void {
    const lyDo = this.reasonText().trim();
    if (!lyDo) { this.reasonErr.set('Lý do là bắt buộc (nhật ký append-only).'); return; }
    const id = this.reasonRef();
    const mode = this.reasonMode();
    const r = mode === 'loai-dong' ? this.store.loaiDongLaoDong(this.kyId(), id, lyDo)
      : mode === 'dao-bt' ? this.store.daoButToan(id, lyDo)
      : this.store.thuHoiDeNghi(id, lyDo);
    r.ok
      ? this.msg.success(mode === 'loai-dong' ? 'Đã loại khỏi kỳ — dựng lại snapshot để cập nhật bảng quỹ.'
        : mode === 'dao-bt' ? 'Đã lập bút toán đảo (cặp gốc–đảo link nhau, tổng = 0).' : 'Đã thu hồi — bản cũ tra được.')
      : this.msg.error(r.reason ?? 'Không thực hiện được.');
    if (r.ok) this.dlg?.close();
  }

  /* sửa lương */
  private readonly suaLuong = signal('');
  protected get suaLuongModel(): string { return this.suaLuong(); }
  protected set suaLuongModel(v: string) { this.suaLuong.set(v ?? ''); }
  protected openSua(dongId: string): void {
    const d = (this.store.dongLaoDong()[this.kyId()] ?? []).find((x) => x.id === dongId);
    this.reasonRef.set(dongId); this.reasonText.set(''); this.reasonErr.set('');
    this.suaLuong.set(d ? insFormatVnd(d.luongDong) : '');
    this.dlg = this.modal.open({
      title: 'Sửa tay lương đóng', content: this.suaTplRef()!, width: 460,
      footer: [
        { label: 'Hủy', onClick: () => this.dlg?.close() },
        { label: 'Sửa (ghi audit)', type: 'primary', onClick: () => this.confirmSua() },
      ],
    });
  }
  private confirmSua(): void {
    const lyDo = this.reasonText().trim();
    if (!lyDo) { this.reasonErr.set('Lý do là bắt buộc.'); return; }
    const luong = Math.abs(insParseVnd(this.suaLuong()));
    if (!luong) { this.reasonErr.set('Nhập lương đóng hợp lệ.'); return; }
    const r = this.store.suaDongLaoDong(this.kyId(), this.reasonRef(), luong, lyDo);
    if (r.ok) {
      r.adjusted ? this.msg.warning(`Cảnh báo: ${r.adjusted}. Dựng lại snapshot để cập nhật.`)
        : this.msg.success('Đã sửa tay — dựng lại snapshot để cập nhật bảng quỹ.');
      this.dlg?.close();
    } else this.msg.error(r.reason ?? 'Không sửa được.');
  }

  /* duyệt maker ≠ checker (bút toán / đề nghị) */
  private readonly duyetKind = signal<'but-toan' | 'de-nghi'>('but-toan');
  private readonly duyetNguoi = signal(M04_NGUOI_DUYET[0]);
  protected get duyetNguoiModel(): unknown { return this.duyetNguoi(); }
  protected set duyetNguoiModel(v: unknown) { this.duyetNguoi.set(String(v ?? M04_NGUOI_DUYET[0])); this.reasonErr.set(''); }
  protected openDuyet(kind: 'but-toan' | 'de-nghi', id: string): void {
    this.duyetKind.set(kind); this.reasonRef.set(id); this.reasonErr.set('');
    this.dlg = this.modal.open({
      title: kind === 'but-toan' ? 'Duyệt bút toán' : 'Duyệt đề nghị thanh toán',
      content: this.duyetTplRef()!, width: 420,
      footer: [
        { label: 'Hủy', onClick: () => this.dlg?.close() },
        { label: 'Duyệt', type: 'primary', onClick: () => this.confirmDuyet() },
      ],
    });
  }
  private confirmDuyet(): void {
    const id = this.reasonRef();
    const r = this.duyetKind() === 'but-toan'
      ? this.store.duyetButToan(id, this.duyetNguoi())
      : this.store.duyetDeNghi(id, this.duyetNguoi());
    if (r.ok) { this.msg.success('Đã duyệt (maker ≠ checker hợp lệ).'); this.dlg?.close(); }
    else this.reasonErr.set(r.reason ?? 'Không duyệt được.');
  }

  /* lập bút toán */
  private readonly btGiaTri = signal('');
  protected get btGiaTriModel(): string { return this.btGiaTri(); }
  protected set btGiaTriModel(v: string) { this.btGiaTri.set(v ?? ''); }
  protected openLapBT(): void {
    this.reasonText.set(''); this.reasonErr.set(''); this.btGiaTri.set('');
    this.dlg = this.modal.open({
      title: 'Lập bút toán điều chỉnh', content: this.lapBtTplRef()!, width: 460,
      footer: [
        { label: 'Hủy', onClick: () => this.dlg?.close() },
        { label: 'Lập (chờ duyệt)', type: 'primary', onClick: () => this.confirmLapBT() },
      ],
    });
  }
  private confirmLapBT(): void {
    const lyDo = this.reasonText().trim();
    if (!lyDo) { this.reasonErr.set('Lý do là bắt buộc.'); return; }
    const giaTri = insParseVnd(this.btGiaTri());
    if (!giaTri) { this.reasonErr.set('Giá trị phải khác 0 (VD +300.000).'); return; }
    const r = this.store.lapButToan(this.kyId(), giaTri > 0 ? 'dieu-chinh-tang' : 'dieu-chinh-giam', giaTri, lyDo);
    if (r.ok) { this.msg.success('Đã lập bút toán — trạng thái Chờ duyệt.'); this.dlg?.close(); }
    else this.msg.error(r.reason ?? 'Không lập được.');
  }

  protected btGuiDuyet(id: string): void {
    const r = this.store.guiDuyetButToan(id);
    r.ok ? this.msg.success('Đã gửi duyệt bút toán.') : this.msg.error(r.reason ?? 'Không gửi được.');
  }

  protected dnAction(kind: 'gui-duyet' | 'gui-ke-toan', id: string): void {
    const r = kind === 'gui-duyet' ? this.store.guiDuyetDeNghi(id) : this.store.guiKeToanDeNghi(id);
    r.ok ? this.msg.success(kind === 'gui-duyet' ? 'Đã gửi duyệt đề nghị.' : 'Đã gửi kế toán.')
      : this.msg.error(r.reason ?? 'Không thực hiện được.');
  }

  protected lapDeNghi(): void {
    const r = this.store.lapDeNghi(this.kyId());
    r.ok ? this.msg.success('Đã lập đề nghị Nháp từ phần còn thiếu (tách theo quỹ).') : this.msg.warning(r.reason ?? 'Không lập được.');
  }

  protected dungSnapshot(): void {
    const r = this.store.dungSnapshot(this.kyId());
    r.ok ? this.msg.success('Đã dựng snapshot phiên bản mới (bản cũ tra được).') : this.msg.warning(r.reason ?? 'Không dựng được.');
  }
}
