import { ChangeDetectionStrategy, Component, input } from '@angular/core';

/** ins-diff — hiển thị thay đổi `before → after` (không ghi đè sự thật lịch sử — bất biến #3:
 *  giá trị cũ luôn còn nhìn thấy cạnh giá trị mới).
 *  before: --text-soft + gạch nhẹ · after: --text-strong đậm · thiếu bên nào hiện "—".
 *  Dùng ở: M02 row/panel (identity · before→after), M05-B override cạnh số hệ thống,
 *  M06-B timeline lương, M08 so sánh phiên bản rule. */
@Component({
  selector: 'ins-diff',
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (label()) { <span class="df-lb">{{ label() }}</span> }
    <span class="df-before">{{ before() || '—' }}</span>
    <span class="df-arrow" aria-hidden="true">→</span>
    <span class="df-after">{{ after() || '—' }}</span>
  `,
  host: { class: 'ins-diff' },
  styles: [`
    :host { display: inline-flex; align-items: baseline; gap: 6px; font-size: var(--fs-13); line-height: 1.4; min-width: 0; }
    .df-lb { color: var(--text-sub); font-size: var(--fs-12); flex: none; }
    .df-before {
      color: var(--text-soft);
      text-decoration: line-through; text-decoration-thickness: 1px;
      overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
    }
    .df-arrow { color: var(--text-soft); flex: none; }
    .df-after { color: var(--text-strong); font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  `],
})
export class InsDiff {
  readonly before = input<string>('');
  readonly after = input<string>('');
  readonly label = input<string>('');
}
