let clockMin = 0;
function demoNow(): string {
  clockMin += 4;
  const h = 9 + Math.floor(clockMin / 60), m = clockMin % 60;
  return `${M08_TODAY} ${String(Math.min(h, 18)).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
}

/** dd/MM/yyyy → số ngày (so sánh khoảng — pure). */
export function m08DayNum(d: string): number {
  const [dd, mm, yy] = d.split('/').map(Number);
  return Date.UTC(yy, mm - 1, dd) / 86400000;
}
/** 2 khoảng hiệu lực chồng nhau? (den trống = mở). */
export function m08KhoangChong(a: InsM08Khoang, b: InsM08Khoang): boolean {
  const aTu = m08DayNum(a.tu), bTu = m08DayNum(b.tu);
  const aDen = a.den ? m08DayNum(a.den) : Infinity, bDen = b.den ? m08DayNum(b.den) : Infinity;
  return aTu <= bDen && bTu <= aDen;
}
export function m08KhoangLabel(k: InsM08Khoang): string { return `${k.tu} → ${k.den ?? 'mở'}`; }

const clone = <T>(x: T): T => structuredClone(x);

const MAKER = 'Lê Thị Mai Hương';       // maker demo (chuyên viên C&B)
const PHAP_CHE = 'Ngô Thị Kim Chi';     // checker pháp chế
const BA = 'Đinh Thu Trang';            // checker BA

@Injectable({ providedIn: 'root' })
export class InsM08Store {
  readonly currentUser = MAKER;
  /** Người duyệt hợp lệ (pháp chế/BA) — chọn chính maker để thấy guard maker ≠ checker. */
  readonly nguoiDuyetOptions = [PHAP_CHE, BA, MAKER];

  readonly rules = signal<InsM08RuleTyLe[]>(clone(RULE_SEED));
  readonly pheps = signal<InsM08PhepKiemTra[]>(clone(PHEP_SEED));
  readonly maPhuongAn = signal<InsM08MaPhuongAn[]>(clone(MA_PA_SEED));
  readonly thuTuc = signal<InsM08LoaiThuTuc[]>(clone(THUTUC_SEED));
  readonly anhXa = signal<InsM08AnhXaMaPhieu[]>(clone(ANHXA_SEED));
  readonly dots = signal<InsM08DotPhatHanh[]>(clone(DOT_SEED));
  readonly quyTacNhac = signal<InsM08QuyTacNhac[]>(clone(NHAC_SEED));
  readonly lanNhac = signal<InsM08LanNhac[]>(clone(LANNHAC_SEED));
  readonly lanDongBo = signal<InsM08LanDongBo[]>(clone(DONGBO_SEED));
  readonly suKienLoi = signal<InsM08SuKienLoiDongBo[]>(clone(LOIDB_SEED));
  /** Append-only — có cả lần BỊ TỪ CHỐI; không giá trị nhạy cảm. */
  readonly nhatKyTruyCap = signal<InsM08NhatKyTruyCap[]>(clone(TRUYCAP_SEED));
  readonly chinhSachLuuTru = signal<InsM08ChinhSachLuuTru[]>(clone(LUUTRU_SEED));
  readonly dotXuLy = signal<InsM08DotXuLyHetHan[]>(clone(DOTXULY_SEED));
  readonly thamSo = signal<InsM08ThamSo[]>(clone(THAMSO_SEED));
  readonly dmRecords = signal<InsM08BanGhiDanhMuc[]>(clone(DM_SEED));
  readonly coCau = signal<InsM08CoCauNode[]>(clone(COCAU_SEED));
  readonly donViSDLD = signal<InsM08DonViSDLD[]>(clone(DVSDLD_SEED));
  /** Nhật ký thao tác M08 — append-only (bất biến #3), có trước/sau. */
  readonly audit = signal<InsM08AuditEntry[]>([]);

  resetDemo(): void {
    this.rules.set(clone(RULE_SEED));
    this.pheps.set(clone(PHEP_SEED));
    this.maPhuongAn.set(clone(MA_PA_SEED));
    this.thuTuc.set(clone(THUTUC_SEED));
    this.anhXa.set(clone(ANHXA_SEED));
    this.dots.set(clone(DOT_SEED));
    this.quyTacNhac.set(clone(NHAC_SEED));
    this.lanNhac.set(clone(LANNHAC_SEED));
    this.lanDongBo.set(clone(DONGBO_SEED));
    this.suKienLoi.set(clone(LOIDB_SEED));
    this.nhatKyTruyCap.set(clone(TRUYCAP_SEED));
    this.chinhSachLuuTru.set(clone(LUUTRU_SEED));
    this.dotXuLy.set(clone(DOTXULY_SEED));
    this.thamSo.set(clone(THAMSO_SEED));
    this.dmRecords.set(clone(DM_SEED));
    this.audit.set([]);
  }

  private log(e: Omit<InsM08AuditEntry, 'at'>): void {
    this.audit.update((l) => [{ at: demoNow(), ...e }, ...l]);
  }
  private patchRule(id: string, p: Partial<InsM08RuleTyLe>): void {
    this.rules.update((l) => l.map((r) => (r.id === id ? { ...r, ...p } : r)));
  }

  ruleOf(id: string): InsM08RuleTyLe | undefined { return this.rules().find((r) => r.id === id); }
  thamSoOf(ma: string): InsM08ThamSo | undefined { return this.thamSo().find((t) => t.ma === ma); }
  dmDef(key: string): InsM08DanhMucDef | undefined { return M08_DANH_MUC_DEFS.find((d) => d.key === key); }
  dmRecordsOf(key: string): InsM08BanGhiDanhMuc[] { return this.dmRecords().filter((r) => r.dmKey === key); }

  /* ── BQA-13: danh mục thủ tục là NƠI DUY NHẤT khai báo — M06/M03 đọc, M08 sở hữu ghi ── */
  thuTucOf(ma: string): InsM08LoaiThuTuc | undefined { return this.thuTuc().find((t) => t.maThuTuc === ma); }
  /** Ngừng sử dụng loại thủ tục (đổi = bản mới; bản cũ giữ nguyên hiệu lực) — chủ M08, M06 gọi đọc-quyết ở đây. */
  ngungThuTuc(ma: string): { ok: boolean; reason?: string } {
    const t = this.thuTucOf(ma);
    if (!t) return { ok: false, reason: 'Không tìm thấy loại thủ tục trong danh mục M08.' };
    if (t.trangThai === 'het-hieu-luc') return { ok: false, reason: 'Thủ tục đã hết hiệu lực từ trước.' };
    this.thuTuc.update((l) => l.map((x) => (x.maThuTuc === ma
      ? { ...x, trangThai: 'het-hieu-luc' as const, khoangHL: { ...x.khoangHL, den: M08_TODAY } } : x)));
    this.log({ nguoi: this.currentUser, hanhDong: `Ngừng sử dụng loại thủ tục ${ma} (danh mục M08 — nguồn duy nhất)`, doiTuong: ma });
    return { ok: true };
  }

  /** Phép chưa gán mức — cảnh báo thiếu trên đầu tab Ngưỡng kiểm tra. */
  readonly phepChuaGan = computed(() => this.pheps().filter((p) => p.chuaGan));

  /** Phiên bản rule tỷ lệ hiệu lực TRONG kỳ (M01 đọc sống — rule đổi giữa kỳ → CẢ HAI phiên bản).
   *  Kỳ kXX → tháng XX/2026. */
  ruleVersionsAtKy(kyId: string): { soPhienBan: string; khoang: string; soHieu: string }[] {
    const thang = Number(kyId.replace('k', ''));
    if (!thang) return [];
    const kyKhoang: InsM08Khoang = {
      tu: `01/${String(thang).padStart(2, '0')}/2026`,
      den: `${thang === 2 ? 28 : [4, 6, 9, 11].includes(thang) ? 30 : 31}/${String(thang).padStart(2, '0')}/2026`,
    };
    return this.rules()
      .filter((r) => r.nhomId === 'RS-2026' && (r.trangThai === 'hieu-luc' || r.trangThai === 'het-hieu-luc')
        && m08KhoangChong(r.khoangHL, kyKhoang))
      .sort((a, b) => m08DayNum(a.khoangHL.tu) - m08DayNum(b.khoangHL.tu))
      .map((r) => ({ soPhienBan: `RS-2026 ${r.soPhienBan}`, khoang: m08KhoangLabel(r.khoangHL), soHieu: r.nguonPhapLy?.soHieu ?? '' }));
  }

  /* ══════════ GUARD-PAIR (pattern D2: `*Reason` string|null + transition cùng tên) ══════════ */

  /** Gửi duyệt rule — thiếu 1/3 thuộc tính (số phiên bản · nguồn pháp lý đủ 3 trường · khoảng HL) → CHẶN. */
  guiDuyetReason(id: string): string | null {
    const r = this.ruleOf(id);
    if (!r) return 'Không tìm thấy bản ghi.';
    if (r.trangThai !== 'nhap' && r.trangThai !== 'tra-lai') return `Trạng thái ${M08_DUYET_LABEL[r.trangThai]} — chỉ gửi duyệt bản Nháp/Trả lại.`;
    const thieu: string[] = [];
    if (!r.soPhienBan) thieu.push('số phiên bản');
    const n = r.nguonPhapLy;
    if (!n?.soHieu || !n?.ngayBanHanh || !n?.link) thieu.push('nguồn pháp lý (số hiệu + ngày ban hành + link)');
    if (!r.khoangHL?.tu) thieu.push('khoảng hiệu lực');
    if (thieu.length) return `Thiếu ${thieu.length}/3 thuộc tính bắt buộc: ${thieu.join(' · ')} — KHÔNG gửi duyệt được.`;
    return null;
  }
  guiDuyet(id: string): { ok: boolean; reason?: string } {
    const reason = this.guiDuyetReason(id);
    if (reason) return { ok: false, reason };
    this.patchRule(id, { trangThai: 'cho-duyet', nguoiGuiDuyet: this.currentUser });
    this.log({ nguoi: this.currentUser, hanhDong: 'Gửi duyệt rule — maker MẤT quyền sửa từ đây', doiTuong: id, truoc: 'Nháp', sau: 'Chờ duyệt' });
    return { ok: true };
  }

  /** Gửi duyệt mã phương án — thiếu NHÃN NGUỒN → không gửi duyệt (FN-14). */
  guiDuyetMaPAReason(ma: string): string | null {
    const m = this.maPhuongAn().find((x) => x.ma === ma);
    if (!m) return 'Không tìm thấy mã.';
    if (m.trangThai !== 'nhap') return `Trạng thái ${M08_DUYET_LABEL[m.trangThai]} — chỉ gửi duyệt bản Nháp.`;
    if (m.khongVaoCauHinh) return 'Nhóm phụ độ tin cậy Thấp — KHÔNG vào cấu hình thật trước đối chiếu QĐ 366.';
    if (!m.nguon) return 'Thiếu nhãn nguồn — không gửi duyệt được.';
    if (m.doTinCay === 'can-xac-minh') return 'Độ tin cậy "Cần xác minh" — bổ sung văn bản đối chiếu trước khi gửi duyệt.';
    return null;
  }

  /** Maker mất quyền sửa sau gửi duyệt; hiệu lực → sửa = PHIÊN BẢN MỚI. */
  suaRuleReason(id: string): string | null {
    const r = this.ruleOf(id);
    if (!r) return 'Không tìm thấy bản ghi.';
    if (r.trangThai === 'nhap' || r.trangThai === 'tra-lai') return null;
    if (r.trangThai === 'cho-duyet') return 'Đã gửi duyệt — maker mất quyền sửa (chờ pháp chế/BA duyệt hoặc trả lại).';
    if (r.trangThai === 'hieu-luc') return 'Đang hiệu lực — sửa = TẠO PHIÊN BẢN MỚI (không ghi đè lịch sử).';
    return `Trạng thái ${M08_DUYET_LABEL[r.trangThai]} — bản ghi bất biến.`;
  }

  /** Lưu bản nháp — chồng khoảng hiệu lực cùng nhóm + phạm vi → CHẶN + CHỈ BẢN XUNG ĐỘT. */
  luuReason(nhomId: string, phamVi: string, khoang: InsM08Khoang, excludeId?: string): string | null {
    const xungDot = this.rules().filter((r) =>
      r.id !== excludeId && r.nhomId === nhomId && r.phamVi === phamVi &&
      r.trangThai !== 'het-hieu-luc' && r.trangThai !== 'thu-hoi' && r.trangThai !== 'tra-lai' &&
      m08KhoangChong(r.khoangHL, khoang));
    if (!xungDot.length) return null;
    return `Chồng khoảng hiệu lực cùng loại + phạm vi với: ${xungDot.map((r) => `${r.id} (${m08KhoangLabel(r.khoangHL)})`).join(' · ')}.`;
  }

  duyetRule(id: string, nguoiDuyet: string): { ok: boolean; reason?: string } {
    const r = this.ruleOf(id);
    if (!r || r.trangThai !== 'cho-duyet') return { ok: false, reason: 'Chỉ duyệt bản Chờ duyệt.' };
    if (nguoiDuyet === (r.nguoiGuiDuyet ?? r.nguoiLap)) return { ok: false, reason: 'Người duyệt phải KHÁC maker (maker-checker).' };
    this.patchRule(id, { trangThai: 'da-duyet', nguoiDuyet });
    this.log({ nguoi: nguoiDuyet, hanhDong: 'Duyệt rule (pháp chế/BA) — hiệu lực CHỈ sau Đã duyệt + tới ngày', doiTuong: id, truoc: 'Chờ duyệt', sau: 'Đã duyệt' });
    return { ok: true };
  }
  traLaiRule(id: string, lyDo: string): { ok: boolean; reason?: string } {
    const r = this.ruleOf(id);
    if (!r || r.trangThai !== 'cho-duyet') return { ok: false, reason: 'Chỉ trả lại bản Chờ duyệt.' };
    if (!lyDo.trim()) return { ok: false, reason: 'Lý do trả lại bắt buộc.' };
    this.patchRule(id, { trangThai: 'tra-lai' });
    this.log({ nguoi: PHAP_CHE, hanhDong: 'Trả lại rule — maker được sửa tiếp', doiTuong: id, truoc: 'Chờ duyệt', sau: 'Trả lại', lyDo });
    return { ok: true };
  }

  /** Tạo phiên bản mới từ bản hiệu lực (sửa đang hiệu lực = PHIÊN BẢN MỚI). */
  taoPhienBanMoi(id: string): { ok: boolean; reason?: string; idMoi?: string } {
    const r = this.ruleOf(id);
    if (!r) return { ok: false, reason: 'Không tìm thấy bản ghi.' };
    if (r.trangThai !== 'hieu-luc') return { ok: false, reason: 'Chỉ tạo phiên bản mới từ bản ĐANG HIỆU LỰC.' };
    const ver = Number(r.soPhienBan.replace(/\D/g, '') || '0') + 1;
    const idMoi = `${r.nhomId}-v${ver}-draft`;
    if (this.ruleOf(idMoi)) return { ok: false, reason: `Đã có bản nháp ${idMoi} — không tạo trùng.` };
    const moi: InsM08RuleTyLe = {
      ...clone(r), id: idMoi, soPhienBan: `v${ver}`, trangThai: 'nhap',
      khoangHL: { tu: '01/10/2026' }, nguoiLap: this.currentUser, nguoiGuiDuyet: undefined, nguoiDuyet: undefined,
      dotMa: undefined, ghiChu: `Tạo từ bản hiệu lực ${r.id} — bản gốc giữ nguyên`,
    };
    this.rules.update((l) => [...l, moi]);
    this.log({ nguoi: this.currentUser, hanhDong: `Tạo PHIÊN BẢN MỚI từ ${r.id}`, doiTuong: idMoi });
    return { ok: true, idMoi };
  }

  /** Đổi mức phép kiểm tra = PHIÊN BẢN MỚI + lịch sử (người + lý do); phép LUẬT khóa Chặn. */
  doiMucPhepReason(id: string): string | null {
    const p = this.pheps().find((x) => x.id === id);
    if (!p) return 'Không tìm thấy phép.';
    if (p.loaiQuyTac === 'luat') return `Bắt buộc theo luật (${p.soHieu}) — mức KHÓA "Chặn", không mở ô chọn.`;
    return null;
  }
  doiMucPhep(id: string, denMuc: InsM08Muc, lyDo: string): { ok: boolean; reason?: string } {
    const reason = this.doiMucPhepReason(id);
    if (reason) return { ok: false, reason };
    if (!lyDo.trim()) return { ok: false, reason: 'Đổi mức bắt buộc lý do (phiên bản + người + lý do).' };
    this.pheps.update((l) => l.map((p) => {
      if (p.id !== id) return p;
      const phienBan = p.phienBan + 1;
      return {
        ...p, muc: denMuc, phienBan, chuaGan: false,
        lichSuDoiMuc: [...p.lichSuDoiMuc, { at: demoNow(), tuMuc: p.muc, denMuc, nguoi: this.currentUser, lyDo, phienBan }],
      };
    }));
    const p = this.pheps().find((x) => x.id === id)!;
    this.log({ nguoi: this.currentUser, hanhDong: `Đổi mức phép kiểm tra → phiên bản v${p.phienBan}`, doiTuong: id, sau: M08_MUC_LABEL[denMuc], lyDo });
    return { ok: true };
  }

  /* ── Đợt phát hành (FN-21) ── */

  dotOf(ma: string): InsM08DotPhatHanh | undefined { return this.dots().find((d) => d.ma === ma); }

  /** Bản ghi xung đột trong đợt (chồng khoảng cùng nhóm+phạm vi giữa các bản trong đợt,
   *  hoặc với bản chờ hiệu lực ngoài đợt) — CHỈ BẢN XUNG ĐỘT. */
  dotXungDot(ma: string): string[] {
    const dot = this.dotOf(ma);
    if (!dot) return [];
    const banTrongDot = dot.banGhiIds.map((id) => this.ruleOf(id)).filter((r): r is InsM08RuleTyLe => !!r);
    const xungDot = new Set<string>();
    for (let i = 0; i < banTrongDot.length; i++) {
      for (let j = i + 1; j < banTrongDot.length; j++) {
        const a = banTrongDot[i], b = banTrongDot[j];
        if (a.nhomId === b.nhomId && a.phamVi === b.phamVi && m08KhoangChong(a.khoangHL, b.khoangHL)) {
          xungDot.add(a.id); xungDot.add(b.id);
        }
      }
    }
    return [...xungDot];
  }

  guiDuyetDotReason(ma: string): string | null {
    const dot = this.dotOf(ma);
    if (!dot) return 'Không tìm thấy đợt.';
    if (dot.trangThai !== 'soan') return `Trạng thái ${M08_DOT_LABEL[dot.trangThai]} — chỉ gửi duyệt đợt đang Soạn.`;
    const chuaDu = dot.banGhiIds.filter((id) => this.guiDuyetReason(id) !== null && this.ruleOf(id)?.trangThai === 'nhap');
    if (chuaDu.length) return `${chuaDu.length} bản ghi chưa đủ 3 thuộc tính bắt buộc: ${chuaDu.join(' · ')}.`;
    return null;
  }
  guiDuyetDot(ma: string): { ok: boolean; reason?: string } {
    const reason = this.guiDuyetDotReason(ma);
    if (reason) return { ok: false, reason };
    this.dots.update((l) => l.map((d) => (d.ma === ma
      ? { ...d, trangThai: 'cho-duyet' as const, vet: [...d.vet, { at: demoNow(), nguoi: this.currentUser, noiDung: 'Gửi duyệt đợt — maker mất quyền sửa bản ghi trong đợt' }] }
      : d)));
    return { ok: true };
  }
  /** BQA-23: duyệt đợt DỪNG ở `Đã duyệt` (không nhảy thẳng Chờ hiệu lực — trước đây làm da-duyet unreachable). */
  duyetDot(ma: string, nguoiDuyet: string): { ok: boolean; reason?: string } {
    const dot = this.dotOf(ma);
    if (!dot || dot.trangThai !== 'cho-duyet') return { ok: false, reason: 'Chỉ duyệt đợt Chờ duyệt.' };
    if (nguoiDuyet === dot.nguoiSoan) return { ok: false, reason: 'Người duyệt đợt phải KHÁC người soạn (maker-checker).' };
    this.dots.update((l) => l.map((d) => (d.ma === ma
      ? { ...d, trangThai: 'da-duyet' as const, nguoiDuyet, vet: [...d.vet, { at: demoNow(), nguoi: nguoiDuyet, noiDung: 'Duyệt đợt (pháp chế/BA) → Đã duyệt' }] }
      : d)));
    return { ok: true };
  }

  /** BQA-23: chuyển đợt Đã duyệt → Chờ hiệu lực (khóa đợt, chờ tới ngày hiệu lực chung). */
  chuyenChoHieuLuc(ma: string): { ok: boolean; reason?: string } {
    const dot = this.dotOf(ma);
    if (!dot || dot.trangThai !== 'da-duyet') return { ok: false, reason: 'Chỉ chuyển Chờ hiệu lực từ đợt Đã duyệt.' };
    this.dots.update((l) => l.map((d) => (d.ma === ma
      ? { ...d, trangThai: 'cho-hieu-luc' as const, vet: [...d.vet, { at: demoNow(), nguoi: this.currentUser, noiDung: `Khóa đợt chờ ngày hiệu lực chung ${d.ngayHieuLucChung} (Đã duyệt → Chờ hiệu lực)` }] }
      : d)));
    return { ok: true };
  }

  /** BQA-23: trả lại đợt về Soạn cho maker sửa (checker ≠ maker) — bổ sung action còn thiếu. */
  traLaiDot(ma: string, lyDo: string): { ok: boolean; reason?: string } {
    const dot = this.dotOf(ma);
    if (!dot || dot.trangThai !== 'cho-duyet') return { ok: false, reason: 'Chỉ trả lại đợt Chờ duyệt.' };
    if (!lyDo.trim()) return { ok: false, reason: 'Lý do trả lại bắt buộc.' };
    this.dots.update((l) => l.map((d) => (d.ma === ma
      ? { ...d, trangThai: 'soan' as const, nguoiDuyet: undefined, vet: [...d.vet, { at: demoNow(), nguoi: this.currentUser, noiDung: `TRẢ LẠI đợt về Soạn (maker sửa lại): ${lyDo.trim()}` }] }
      : d)));
    return { ok: true };
  }

  /** Phát hành: từ Đã duyệt/Chờ hiệu lực; xung đột tại ngày hiệu lực chung → CẢ ĐỢT DỪNG (không bản nào lên). */
  phatHanhDotReason(ma: string): string | null {
    const dot = this.dotOf(ma);
    if (!dot) return 'Không tìm thấy đợt.';
    if (dot.trangThai === 'da-phat-hanh') return 'Đợt đã phát hành.';
    if (dot.trangThai !== 'da-duyet' && dot.trangThai !== 'cho-hieu-luc') {
      return `Trạng thái ${M08_DOT_LABEL[dot.trangThai]} — phát hành cần Đã duyệt/Chờ hiệu lực (Soạn → Chờ duyệt → Đã duyệt → Chờ hiệu lực → Đã phát hành).`;
    }
    const xd = this.dotXungDot(ma);
    if (xd.length) return `CẢ ĐỢT DỪNG — xung đột khoảng hiệu lực tại ngày hiệu lực chung: ${xd.join(' ↔ ')}. Không bản ghi nào được phát hành.`;
    return null;
  }
  phatHanhDot(ma: string): { ok: boolean; reason?: string } {
    const reason = this.phatHanhDotReason(ma);
    if (reason) return { ok: false, reason };
    const dot = this.dotOf(ma)!;
    // All-or-nothing: mọi bản trong đợt lên hiệu lực CÙNG THỜI ĐIỂM; bản hiệu lực cũ cùng nhóm tự hết hiệu lực.
    this.rules.update((l) => l.map((r) => {
      if (dot.banGhiIds.includes(r.id)) return { ...r, trangThai: 'hieu-luc' as const, dotMa: ma };
      const thay = dot.banGhiIds.some((id) => { const m = this.ruleOf(id); return m && m.nhomId === r.nhomId && m.phamVi === r.phamVi; });
      if (thay && r.trangThai === 'hieu-luc') return { ...r, trangThai: 'het-hieu-luc' as const, khoangHL: { ...r.khoangHL, den: dot.ngayHieuLucChung } };
      return r;
    }));
    this.dots.update((l) => l.map((d) => (d.ma === ma
      ? { ...d, trangThai: 'da-phat-hanh' as const, thoiDiemPH: demoNow(), vet: [...d.vet, { at: demoNow(), nguoi: 'Hệ thống', noiDung: `Phát hành all-or-nothing — ${d.banGhiIds.length}/${d.banGhiIds.length} bản ghi lên CÙNG THỜI ĐIỂM ${d.ngayHieuLucChung}` }] }
      : d)));
    this.log({ nguoi: this.currentUser, hanhDong: `Phát hành đợt ${ma} (correlation ${dot.correlationId})`, doiTuong: ma });
    return { ok: true };
  }

  /** Gỡ bản ghi khỏi đợt đang soạn (cách thoát xung đột — bản ghi về nháp tự do). */
  goKhoiDot(dotMa: string, ruleId: string): { ok: boolean; reason?: string } {
    const dot = this.dotOf(dotMa);
    if (!dot || dot.trangThai !== 'soan') return { ok: false, reason: 'Chỉ gỡ bản ghi khi đợt đang Soạn.' };
    this.dots.update((l) => l.map((d) => (d.ma === dotMa
      ? { ...d, banGhiIds: d.banGhiIds.filter((id) => id !== ruleId), vet: [...d.vet, { at: demoNow(), nguoi: this.currentUser, noiDung: `Gỡ ${ruleId} khỏi đợt (thoát xung đột) — bản ghi về nháp tự do` }] }
      : d)));
    this.patchRule(ruleId, { dotMa: undefined });
    return { ok: true };
  }

  /** Thu hồi đợt = PHIÊN BẢN MỚI từng quy tắc (không xóa vết) + vết chỉ-thêm. */
  thuHoiDot(ma: string, lyDo: string): { ok: boolean; reason?: string } {
    const dot = this.dotOf(ma);
    if (!dot || dot.trangThai !== 'da-phat-hanh') return { ok: false, reason: 'Chỉ thu hồi đợt Đã phát hành.' };
    if (!lyDo.trim()) return { ok: false, reason: 'Lý do thu hồi bắt buộc.' };
    this.rules.update((l) => {
      const out = [...l];
      for (const id of dot.banGhiIds) {
        const r = out.find((x) => x.id === id);
        if (!r || r.trangThai !== 'hieu-luc') continue;
        r.trangThai = 'thu-hoi';
        const ver = Number(r.soPhienBan.replace(/\D/g, '') || '0') + 1;
        out.push({ ...clone(r), id: `${r.nhomId}-v${ver}-rb`, soPhienBan: `v${ver}`, trangThai: 'nhap',
          nguoiLap: this.currentUser, nguoiGuiDuyet: undefined, nguoiDuyet: undefined, dotMa: undefined,
          ghiChu: `Phiên bản mới sinh do THU HỒI đợt ${ma} — ${lyDo}` });
      }
      return out;
    });
    this.dots.update((l) => l.map((d) => (d.ma === ma
      ? { ...d, trangThai: 'thu-hoi' as const, vet: [...d.vet, { at: demoNow(), nguoi: this.currentUser, noiDung: `THU HỒI đợt — mỗi quy tắc sinh PHIÊN BẢN MỚI (rollback không xóa vết): ${lyDo}` }] }
      : d)));
    return { ok: true };
  }

  /* ── Nhật ký đồng bộ (FN-19) ── */

  loiCuaLan(lanId: string): InsM08SuKienLoiDongBo[] { return this.suKienLoi().filter((e) => e.lanId === lanId); }

  chayLaiDongBoReason(lanId: string): string | null {
    const lan = this.lanDongBo().find((l) => l.id === lanId);
    if (!lan) return 'Không tìm thấy lần chạy.';
    if (lan.nguonTamDung) return 'Nguồn đang TẠM DỪNG — nút chạy lại bị khóa.';
    const conLoi = this.loiCuaLan(lanId).filter((e) => e.trangThai !== 'da-chay-lai-thanh-cong');
    if (!conLoi.length) return 'Không còn sự kiện lỗi — chạy lại chỉ áp dụng cho phần lỗi (idempotent).';
    return null;
  }
  /** Chạy lại CHỈ sự kiện lỗi — idempotent: thiếu dữ liệu/kết nối → thành công; thiếu ánh xạ chưa bổ sung → VẪN LỖI. */
  chayLaiDongBo(lanId: string): { ok: boolean; reason?: string; daSua: number; vanLoi: number } {
    const reason = this.chayLaiDongBoReason(lanId);
    if (reason) return { ok: false, reason, daSua: 0, vanLoi: 0 };
    let daSua = 0, vanLoi = 0;
    this.suKienLoi.update((l) => l.map((e) => {
      if (e.lanId !== lanId || e.trangThai === 'da-chay-lai-thanh-cong') return e;
      if (e.lyDo === 'thieu-anh-xa') {
        vanLoi++;
        return { ...e, trangThai: 'van-loi' as const, vetChayLai: [...e.vetChayLai, `${demoNow()} — chạy lại: ánh xạ vẫn thiếu → VẪN LỖI (không báo giả)`] };
      }
      daSua++;
      return { ...e, trangThai: 'da-chay-lai-thanh-cong' as const, vetChayLai: [...e.vetChayLai, `${demoNow()} — chạy lại CHỈ sự kiện lỗi: thành công (không sinh trùng)`] };
    }));
    this.log({ nguoi: this.currentUser, hanhDong: `Chạy lại đồng bộ ${lanId} — chỉ phần lỗi: ${daSua} sửa xong · ${vanLoi} vẫn lỗi`, doiTuong: lanId });
    return { ok: true, daSua, vanLoi };
  }

  /* ── Lưu trữ (FN-20) ── */

  duyetDotHuy(id: string, nguoiDuyet: string): { ok: boolean; reason?: string } {
    const dot = this.dotXuLy().find((d) => d.id === id);
    if (!dot || dot.trangThai !== 'cho-duyet') return { ok: false, reason: 'Chỉ duyệt đợt Chờ duyệt.' };
    if (nguoiDuyet === dot.nguoiLap) return { ok: false, reason: 'Người duyệt phải KHÁC người lập đợt (FN-20).' };
    this.dotXuLy.update((l) => l.map((d) => (d.id === id ? { ...d, trangThai: 'da-duyet' as const, nguoiDuyet } : d)));
    this.log({ nguoi: nguoiDuyet, hanhDong: 'Duyệt đợt xử lý hết hạn (thi hành) — kết quả đợt chỉ-thêm, xuất được', doiTuong: id });
    return { ok: true };
  }

  /* ── Danh mục CRUD chung ── */

  /** Chống trùng theo khóa danh mục — thông báo GIỮ VĂN PHONG CŨ: "[X] đã tồn tại trong hệ thống". */
  dmTrungReason(dmKey: string, values: Record<string, string>, excludeId?: string): string | null {
    const def = this.dmDef(dmKey);
    if (!def) return 'Danh mục không tồn tại.';
    // BQA-18: "Chưa thấy testcase — cấm suy diễn" → KHÔNG chống trùng suy diễn (chờ xác minh testcase).
    if (def.khoaChuaThayTestcase) return null;
    for (const k of def.khoa) {
      if (!values[k]?.trim()) return `Thiếu trường khóa "${def.fields.find((f) => f.key === k)?.label ?? k}".`;
    }
    const trung = this.dmRecordsOf(dmKey).find((r) => r.id !== excludeId && def.khoa.every((k) => r.values[k] === values[k]));
    if (trung) return `[${def.khoa.map((k) => values[k]).join(' + ')}] đã tồn tại trong hệ thống`;
    return null;
  }
  dmLuu(dmKey: string, values: Record<string, string>, excludeId?: string): { ok: boolean; reason?: string; id?: string } {
    const def = this.dmDef(dmKey);
    if (!def) return { ok: false, reason: 'Danh mục không tồn tại.' };
    if (excludeId && def.khoaCaSua) {
      const cu = this.dmRecords().find((r) => r.id === excludeId);
      if (cu && def.khoa.some((k) => cu.values[k] !== values[k])) {
        return { ok: false, reason: `${def.khoaNote} — không đổi được ${def.khoa.map((k) => def.fields.find((f) => f.key === k)?.label).join(' + ')} khi sửa.` };
      }
    }
    const reason = this.dmTrungReason(dmKey, values, excludeId);
    if (reason) return { ok: false, reason };
    if (excludeId) {
      const truoc = this.dmRecords().find((r) => r.id === excludeId);
      this.dmRecords.update((l) => l.map((r) => (r.id === excludeId ? { ...r, values: { ...values } } : r)));
      this.log({ nguoi: this.currentUser, hanhDong: `Sửa bản ghi danh mục ${def.ten}`, doiTuong: excludeId,
        truoc: JSON.stringify(truoc?.values), sau: JSON.stringify(values) });
      return { ok: true, id: excludeId };
    }
    const id = `DM-${String(++dmSeq).padStart(3, '0')}`;
    this.dmRecords.update((l) => [...l, { id, dmKey, values: { ...values }, khoangHL: { tu: M08_TODAY }, trangThai: 'dang-su-dung', noiThamChieu: [] }]);
    this.log({ nguoi: this.currentUser, hanhDong: `Thêm bản ghi danh mục ${def.ten}`, doiTuong: id, sau: JSON.stringify(values) });
    return { ok: true, id };
  }
  /** Xóa cứng CHỈ khi chưa tham chiếu — đang → chặn + LIỆT KÊ nơi dùng + gợi ý Ngưng sử dụng. */
  dmXoaReason(id: string): string | null {
    const r = this.dmRecords().find((x) => x.id === id);
    if (!r) return 'Không tìm thấy bản ghi.';
    if (r.noiThamChieu.length) return `Đang được tham chiếu: ${r.noiThamChieu.join(' · ')} — không xóa cứng; dùng "Ngưng sử dụng".`;
    return null;
  }
  dmXoaPreview(ids: string[]): { eligible: number; blocked: { reason: string; count: number }[] } {
    const reasons = new Map<string, number>();
    let eligible = 0;
    for (const id of ids) {
      const reason = this.dmXoaReason(id);
      if (reason) reasons.set(reason, (reasons.get(reason) ?? 0) + 1);
      else eligible++;
    }
    return { eligible, blocked: [...reasons].map(([reason, count]) => ({ reason, count })) };
  }
  dmXoa(ids: string[]): { done: number; skipped: { id: string; reason: string }[] } {
    const skipped: { id: string; reason: string }[] = [];
    const okIds: string[] = [];
    for (const id of ids) {
      const reason = this.dmXoaReason(id);
      if (reason) skipped.push({ id, reason });
      else okIds.push(id);
    }
    this.dmRecords.update((l) => l.filter((r) => !okIds.includes(r.id)));
    if (okIds.length) this.log({ nguoi: this.currentUser, hanhDong: `Xóa ${okIds.length} dòng danh mục (chưa tham chiếu)`, doiTuong: okIds.join(', ') });
    return { done: okIds.length, skipped };
  }
  dmNgung(ids: string[]): { done: number } {
    this.dmRecords.update((l) => l.map((r) => (ids.includes(r.id) ? { ...r, trangThai: 'ngung-su-dung' as const, khoangHL: { ...r.khoangHL, den: M08_TODAY } } : r)));
    this.log({ nguoi: this.currentUser, hanhDong: `Ngưng sử dụng ${ids.length} dòng danh mục (thay xóa — bất biến #3)`, doiTuong: ids.join(', ') });
    return { done: ids.length };
  }
  /** Ghi nhật ký kết xuất (xuất tự ghi — chạy nền khi "tất cả"). */
  dmKetXuat(dmKey: string, cheDo: 'chon' | 'tat-ca', soDong: number): void {
    this.log({ nguoi: this.currentUser, hanhDong: `Xuất Excel danh mục ${this.dmDef(dmKey)?.ten} — chế độ ${cheDo === 'chon' ? 'dòng đã chọn' : 'TẤT CẢ (chạy nền)'} · ${soDong} dòng (xuất tự ghi)`, doiTuong: dmKey });
  }
  capNhatPhanTu(): void {
    this.log({ nguoi: this.currentUser, hanhDong: 'Chạy nền "Cập nhật lại các phần tử" — tính lại giá trị phần tử BH cho kỳ hiện hành', doiTuong: 'phan-tu' });
  }
}
