import { ChangeDetectionStrategy, Component, computed, inject, input, output, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { IconCircleCheck, IconLock, IconTrash, TablerIconComponent } from '@tabler/icons-angular';
import {
  HrmButton, HrmCollapse, HrmCollapsePanel, HrmDescItem, HrmDescriptions,
  HrmMessageService, HrmSelect, HrmStatusCell, HrmTag,
} from 'hrm-ui';
import { InsBulkBar, InsSectionLabel, InsVarianceCell } from '../_shared';
import { INS_KY_LABEL, insKy, insNhanVien } from '../_data/_core';
import {
  INS_BIEUMAU_LABEL, INS_KENHNOP_LABEL, INS_LO_ITEM_LABEL, INS_LO_ITEM_TONE, INS_LO_KETQUA_LABEL,
  INS_LO_LABEL, INS_LO_TONE, INS_PRECHECK_LABEL, INS_PRECHECK_TONE,
  INS_TAMDUNG_LABEL, INS_TAMDUNG_TONE, InsBieuMau, InsKenhNop, InsLo, InsM03Store,
} from '../_data/_m03-data';
import { BIEUMAU_OPTIONS, KENHNOP_OPTIONS } from './_m03-columns';

/** M03 — PANEL LÔ (nội dung hrm-detail-peek master, SC-B2 "Định danh lô" + item + 2 khối chuyên biệt).
 *  Đúng NAMING CONTRACT: input `loId`, output `reason` ({ mode:'ket-thuc-som', id }) — host mở
 *  reason-prompt rồi gọi store.ketThucSomTamDung.
 *  Khối:
 *   • Định danh lô = hrm-descriptions (mã·số hồ sơ·tên·kỳ·loại thủ tục·lần·phòng ban·mã BHXH·người lập·
 *     biểu mẫu·kênh nộp + dấu vết lập/kiểm/duyệt/ký/nộp) — KHÓA CHỈ ĐỌC sau lưu; 3 nhãn phụ bật khi có
 *     (lô sửa · kết quả tổng hợp · lý do trả lại). 2 tham số (biểu mẫu·kênh) sửa được KHI CHƯA NỘP
 *     (doiThamSoLo), sau nộp/kỳ khóa hiện nguyên văn "Chỉ được cập nhật dữ liệu ở trạng thái: [Chưa gửi]!".
 *   • Item trong lô (itemsOfLo) + Gỡ (goKhoiLo — dòng gốc giữ nguyên).
 *   • Ứng viên đủ điều kiện (candidatesOfKy) → InsBulkBar dry-run guard ⑤⑦ (themVaoLoPreview/themVaoLo).
 *   • Điều chỉnh kỳ quá khứ (hồi tố) = hoiToOfKy: chênh TÁCH THEO KỲ qua ins-variance-cell, D01-TS bắt
 *     buộc, truy/thoái thu + phía chịu; lô chứa dòng hồi tố BẮT BUỘC phê duyệt.
 *   • Tạm dừng đóng HT-TT (hrm-collapse): ≤12 tháng, 2 văn bản, đóng bù toàn khoảng hiện ở KỲ KẾT THÚC;
 *     trình duyệt guard ⑥ (trinhTamDungReason — disabled-có-lý-do), kết thúc sớm emit reason. */
@Component({
  selector: 'ins-m03-lo-panel',
  imports: [
    FormsModule, TablerIconComponent,
    HrmButton, HrmCollapse, HrmCollapsePanel, HrmDescriptions, HrmSelect, HrmStatusCell, HrmTag,
    InsBulkBar, InsSectionLabel, InsVarianceCell,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (lo(); as lo) {
      <!-- ═════ Định danh lô — 3 nhãn phụ + hrm-descriptions (chỉ đọc sau lưu) ═════ -->
      <section class="lp__head">
        <div class="lp__tags">
          <hrm-status-cell [status]="$any(trangThaiTone())" [label]="trangThaiLabel()" variant="badge" />
          @if (lo.ketQuaTongHop) { <hrm-tag color="orange" size="sm" variant="lighter">{{ ketQuaLabel() }}</hrm-tag> }
          @if (lo.maLoGoc) { <hrm-tag color="purple" size="sm" variant="lighter">Lô sửa · gốc {{ lo.maLoGoc }} · lần nộp {{ lo.soLanNop + 1 }}</hrm-tag> }
          @if (lo.lyDoTraLai) { <hrm-tag color="red" size="sm" variant="lighter">Bị trả lại: {{ lo.lyDoTraLai }}</hrm-tag> }
        </div>
        <hrm-descriptions [items]="dinhDanh()" [column]="2" size="small" [bordered]="true" />
        <p class="lp__note">Định danh lô sau lưu chỉ đọc — trùng số hồ sơ cùng kỳ + đơn vị bị chặn khi tạo lô.</p>
      </section>

      <!-- ═════ 2 tham số lô (biểu mẫu · kênh nộp) — sửa khi CHƯA NỘP, sau nộp khóa ═════ -->
      <section class="lp__sec">
        <ins-section-label text="Tham số lô — đổi khi chưa nộp" tone="muted" />
        @if (editable()) {
          <div class="lp__params">
            <hrm-select class="lp__param" [ngModel]="lo.phienBanBieuMau" (ngModelChange)="setBieuMau($event)"
              [options]="bieuMauOptions" size="sm" [allowClear]="false" [showSearch]="false" />
            <hrm-select class="lp__param" [ngModel]="lo.kenhNop" (ngModelChange)="setKenh($event)"
              [options]="kenhOptions" size="sm" [allowClear]="false" [showSearch]="false" />
          </div>
          <p class="lp__note">Đổi biểu mẫu/kênh nộp trên lô đã Duyệt/Ký sẽ tự hạ về Nháp và hủy hiệu lực chữ ký.</p>
        } @else {
          <p class="lp__warn"><tabler-icon [icon]="icLock" [size]="13" /> Chỉ được cập nhật dữ liệu ở trạng thái: [Chưa gửi]!</p>
        }
      </section>

      <!-- ═════ VÙNG 1 — Item trong lô (Gỡ = goKhoiLo, dòng gốc giữ nguyên) ═════ -->
      <section class="lp__sec">
        <ins-section-label text="Item trong lô" tone="muted" [count]="itemsInLo().length" />
        @for (r of itemsInLo(); track r.id) {
          <div class="lp__item">
            <div class="lp__item-main">
              <span class="lp__item-name">{{ r.ten }} <span class="lp__muted">{{ r.sub }}</span></span>
              <span class="lp__item-sub">{{ r.suKien }} · {{ r.pa }}</span>
              @if (r.flag) { <span class="lp__item-flag">{{ r.flag }}</span> }
            </div>
            <hrm-status-cell [status]="$any(r.preTone)" [label]="r.preLabel" variant="badge" />
            <hrm-status-cell [status]="$any(r.trangThaiTone)" [label]="r.trangThaiLabel" variant="badge" />
            <hrm-button size="sm" [danger]="true" [disabled]="!editable()" (click)="goKhoiLo(r.id)">
              <tabler-icon [icon]="icTrash" [size]="14" /> Gỡ</hrm-button>
          </div>
        } @empty { <p class="lp__muted-line">Chưa có item — thêm từ vùng ứng viên bên dưới.</p> }
      </section>

      <!-- ═════ VÙNG 2 — Ứng viên đủ điều kiện (dry-run guard ⑤⑦ → InsBulkBar) ═════ -->
      <section class="lp__sec">
        <ins-section-label text="Ứng viên đủ điều kiện (cùng kỳ · Sẵn sàng · chưa thuộc lô mở)" tone="attention" [count]="candidates().length" />
        @for (c of candidates(); track c.id) {
          <button type="button" class="lp__cand" [class.lp__cand--on]="isSel(c.id)" [disabled]="!editable()" (click)="toggle(c.id)">
            <span class="lp__cand-check" [class.lp__cand-check--on]="isSel(c.id)"></span>
            <span class="lp__item-main">
              <span class="lp__item-name">{{ c.ten }} <span class="lp__muted">{{ c.sub }}</span></span>
              <span class="lp__item-sub">{{ c.suKien }} · {{ c.pa }}</span>
            </span>
            @if (c.canhBao) { <span class="lp__cand-warn">{{ c.canhBao }}</span> }
          </button>
        } @empty { <p class="lp__muted-line">Không còn ứng viên Sẵn sàng cho kỳ này.</p> }
        <ins-bulk-bar [selected]="sel().length" [eligible]="preview().eligible" [blocked]="preview().blocked">
          <hrm-button size="sm" [disabled]="!editable()" (click)="themTatCa()">Chọn tất cả</hrm-button>
          <hrm-button size="sm" variant="primary" [disabled]="!editable()" (click)="themVaoLo()">Thêm vào lô ({{ sel().length }})</hrm-button>
        </ins-bulk-bar>
      </section>

      <!-- ═════ KHỐI 1 — Điều chỉnh kỳ quá khứ (hồi tố): chênh TÁCH THEO KỲ + D01-TS ═════ -->
      <section class="lp__sec">
        <ins-section-label text="Điều chỉnh kỳ quá khứ (hồi tố)" tone="muted" [count]="hoiTo().length" />
        @for (h of hoiTo(); track h.id) {
          <div class="lp__ht">
            <div class="lp__ht-head">
              <span class="lp__item-name">{{ h.ten }}</span>
              <hrm-tag [color]="$any(h.loaiColor)" size="sm">{{ h.loaiLabel }}</hrm-tag>
              <hrm-tag [color]="h.coD01TS ? 'green' : 'red'" size="sm" variant="lighter">{{ h.coD01TS ? 'Đủ D01-TS' : 'Thiếu D01-TS' }}</hrm-tag>
              <span class="lp__muted">{{ h.khoang }} · phía chịu: {{ h.phiaChiu }} · QĐ {{ h.ngayQuyetDinh }} · {{ h.vanBan }}</span>
            </div>
            <div class="lp__ht-rows">
              <div class="lp__ht-rowhead"><span>Kỳ gốc</span><span>Lương đã đóng → điều chỉnh · chênh lệch</span></div>
              @for (k of h.rows; track k.ky) {
                <div class="lp__ht-row">
                  <span class="lp__ht-ky">{{ k.ky }}</span>
                  <ins-variance-cell [expected]="k.cu" [actual]="k.moi" [diff]="k.diff" [tone]="$any(k.tone)" />
                </div>
              }
            </div>
            <p class="lp__note">Lô chứa dòng hồi tố BẮT BUỘC phê duyệt · tháng hiệu lực giữ ở kỳ gốc · D01-TS là căn cứ truy/thoái thu · lãi chậm đóng KHÔNG thuộc M03.</p>
          </div>
        } @empty { <p class="lp__muted-line">Lô không có dòng điều chỉnh kỳ quá khứ.</p> }
      </section>

      <!-- ═════ KHỐI 2 — Tạm dừng đóng quỹ hưu trí – tử tuất (hrm-collapse, guard ⑥) ═════ -->
      <section class="lp__sec">
        <ins-section-label text="Tạm dừng đóng quỹ hưu trí – tử tuất (HT-TT)" tone="muted" [count]="tamDung().length" />
        @if (tamDung().length) {
          <hrm-collapse class="lp__collapse">
            @for (h of tamDung(); track h.id; let first = $first) {
              <hrm-collapse-panel [header]="h.header" [active]="first">
                <div class="lp__td">
                  <div class="lp__ht-head">
                    <hrm-status-cell [status]="$any(h.tone)" [label]="h.trangThaiLabel" variant="badge" />
                    <span class="lp__muted">{{ h.khoang }} ({{ h.soThang }}) · {{ h.phamVi }}</span>
                  </div>
                  <div class="lp__rows">
                    <div class="lp__row"><span class="lp__k">2 văn bản</span>
                      <span class="lp__v">{{ h.vanBanDonVi }} · <span [class.lp__miss]="h.thieuVanBanCoQuan">{{ h.vanBanCoQuan }}</span></span></div>
                    <div class="lp__row"><span class="lp__k">Giảm theo kỳ (chỉ HT-TT)</span>
                      <span class="lp__v">@for (g of h.dongGiamTheoKy; track g.ky) { <span class="lp__kychip">{{ g.ky }}: {{ g.soTien }}</span> }</span></div>
                    <div class="lp__row"><span class="lp__k">Đóng bù toàn khoảng</span>
                      <span class="lp__v"><b>{{ h.nghiaVuDongBu }}</b> — hiển thị tại kỳ kết thúc <b>{{ h.kyHienThiDongBu }}</b></span></div>
                    @if (h.canhBaoTruocHan) { <div class="lp__row"><span class="lp__k">Cảnh báo trước hạn</span><span class="lp__v lp__warned">{{ h.canhBaoTruocHan }}</span></div> }
                    @if (h.lyDoKetThucSom) { <div class="lp__row"><span class="lp__k">Lý do kết thúc sớm</span><span class="lp__v">{{ h.lyDoKetThucSom }}</span></div> }
                  </div>
                  <div class="lp__ht-actions">
                    @if (h.trangThai === 'nhap') {
                      <hrm-button size="sm" variant="primary" [disabled]="!!h.trinhReason" (click)="trinhTamDung(h.id)">
                        <tabler-icon [icon]="icCheck" [size]="14" /> Trình duyệt hồ sơ</hrm-button>
                      @if (h.trinhReason) { <span class="lp__blockreason">{{ h.trinhReason }}</span> }
                    } @else if (h.trangThai === 'dang-hieu-luc') {
                      <hrm-button size="sm" (click)="reason.emit({ mode: 'ket-thuc-som', id: h.id })">Kết thúc sớm (lý do)…</hrm-button>
                    }
                  </div>
                </div>
              </hrm-collapse-panel>
            }
          </hrm-collapse>
          <p class="lp__note">Chỉ giảm phần HT-TT · tối đa 12 tháng · cần đủ 2 văn bản (đề nghị đơn vị + chấp thuận cơ quan) · đóng bù toàn khoảng khi hết hạn.</p>
        } @else {
          <p class="lp__muted-line">Không có hồ sơ tạm dừng HT-TT.</p>
        }
      </section>
    }
  `,
  host: { class: 'ins-m03-lo-panel' },
  styles: [`
    :host { display: flex; flex-direction: column; gap: 14px; font-size: var(--fs-13); }
    tabler-icon { display: inline-flex; align-items: center; flex: none; }

    .lp__head { display: flex; flex-direction: column; gap: 8px; }
    .lp__tags { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
    :host ::ng-deep .lp__tags .ant-tag { margin: 0; }
    .lp__note { margin: 0; font-size: var(--fs-11); color: var(--text-soft); }
    .lp__muted { color: var(--text-soft); font-size: var(--fs-12); font-weight: 400; }
    .lp__muted-line { margin: 0; font-size: var(--fs-12); color: var(--text-sub); }
    .lp__warn { margin: 0; display: inline-flex; align-items: center; gap: 5px; font-size: var(--fs-12); color: var(--warning-text); }
    .lp__warned { color: var(--warning-text); }
    .lp__miss { color: var(--warning-text); font-weight: 500; }
    .lp__blockreason { font-size: var(--fs-12); color: var(--error-text); }

    .lp__sec { display: flex; flex-direction: column; gap: 8px; padding-top: 10px; border-top: 1px solid var(--border-soft); }
    .lp__params { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
    .lp__param { display: inline-block; width: 200px; }

    .lp__rows { display: flex; flex-direction: column; gap: 4px; }
    .lp__row { display: flex; gap: 10px; align-items: baseline; }
    .lp__k { flex: none; width: 168px; font-size: var(--fs-12); color: var(--text-sub); }
    .lp__v { flex: 1; min-width: 0; color: var(--text-body); }
    .lp__v b { color: var(--text-strong); font-weight: 600; }

    /* Item / ứng viên */
    .lp__item { display: flex; align-items: center; gap: 10px; padding: 6px 8px; border: 1px solid var(--border-soft); border-radius: var(--radius-md); }
    :host ::ng-deep .lp__item .ant-tag { margin: 0; }
    .lp__item-main { display: flex; flex-direction: column; gap: 1px; min-width: 0; flex: 1; text-align: left; }
    .lp__item-name { color: var(--text-strong); font-weight: 500; font-size: var(--fs-13); }
    .lp__item-sub { font-size: var(--fs-12); color: var(--text-sub); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    .lp__item-flag { font-size: var(--fs-11); color: var(--warning-text); font-weight: 500; }

    .lp__cand { display: flex; align-items: center; gap: 10px; padding: 6px 8px; border: 1px solid var(--border-soft);
      border-radius: var(--radius-md); background: none; cursor: pointer; font: inherit; width: 100%; }
    .lp__cand:disabled { opacity: .55; cursor: not-allowed; }
    .lp__cand--on { border-color: var(--primary-base); background: var(--primary-bg-subtle); }
    .lp__cand-check { flex: none; width: 15px; height: 15px; border: 1.5px solid var(--border-input); border-radius: var(--radius-sm); }
    .lp__cand-check--on { background: var(--primary-base); border-color: var(--primary-base); }
    .lp__cand-warn { flex: none; font-size: var(--fs-11); color: var(--warning-text); max-width: 160px; text-align: right; }

    /* Hồi tố */
    .lp__ht { display: flex; flex-direction: column; gap: 8px; padding: 8px 10px; border: 1px solid var(--border-soft); border-radius: var(--radius-md); }
    .lp__ht-head { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
    :host ::ng-deep .lp__ht-head .ant-tag { margin: 0; }
    .lp__ht-actions { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
    .lp__ht-rows { display: flex; flex-direction: column; gap: 4px; }
    .lp__ht-rowhead { display: flex; gap: 12px; font-size: var(--fs-11); font-weight: 600; text-transform: uppercase; letter-spacing: .02em; color: var(--text-soft); }
    .lp__ht-rowhead span:first-child { flex: none; width: 84px; }
    .lp__ht-row { display: flex; gap: 12px; align-items: baseline; padding: 3px 0; border-top: 1px dashed var(--border-soft); }
    .lp__ht-ky { flex: none; width: 84px; font-size: var(--fs-12); font-weight: 600; color: var(--text-body); font-variant-numeric: tabular-nums; }
    .lp__kychip { display: inline-block; margin-right: 8px; font-size: var(--fs-12); color: var(--text-sub); background: var(--bg-surface-subtle); border-radius: var(--radius-sm); padding: 0 6px; }

    .lp__collapse { display: block; }
    .lp__td { display: flex; flex-direction: column; gap: 8px; }
  `],
})
export class InsM03LoPanel {
  protected readonly store = inject(InsM03Store);
  private readonly msg = inject(HrmMessageService);

  /** Lô đang mở trong panel. */
  readonly loId = input.required<string>();
  /** Hành động cần LÝ DO → host mở reason-prompt rồi gọi store (kết thúc sớm tạm dừng HT-TT). */
  readonly reason = output<{ mode: 'ket-thuc-som'; id: string }>();

  protected readonly icLock = IconLock;
  protected readonly icTrash = IconTrash;
  protected readonly icCheck = IconCircleCheck;
  protected readonly bieuMauOptions = BIEUMAU_OPTIONS;
  protected readonly kenhOptions = KENHNOP_OPTIONS;

  protected readonly lo = computed<InsLo | undefined>(() => this.store.los().find((l) => l.maLo === this.loId()));
  protected readonly trangThaiLabel = computed(() => { const l = this.lo(); return l ? INS_LO_LABEL[l.trangThai] : ''; });
  protected readonly trangThaiTone = computed(() => { const l = this.lo(); return l ? INS_LO_TONE[l.trangThai] : 'neutral'; });
  protected readonly ketQuaLabel = computed(() => { const l = this.lo(); return l?.ketQuaTongHop ? INS_LO_KETQUA_LABEL[l.ketQuaTongHop] : ''; });

  private readonly kyView = computed(() => {
    const l = this.lo(); if (!l) return '';
    const ky = insKy(l.ky);
    return ky ? `${ky.label} · ${INS_KY_LABEL[ky.trangThai]}` : l.ky;
  });

  /** Định danh lô = hrm-descriptions (chỉ đọc sau lưu). Dấu vết kiểm/duyệt/ký/nộp bật khi đã có. */
  protected readonly dinhDanh = computed<HrmDescItem[]>(() => {
    const l = this.lo();
    if (!l) return [];
    const items: HrmDescItem[] = [
      { label: 'Mã lô', value: l.maLo },
      { label: 'Số hồ sơ', value: l.soHoSo },
      { label: 'Tên lô', value: l.tenLo, span: 2 },
      { label: 'Kỳ nghiệp vụ', value: this.kyView() },
      { label: 'Loại thủ tục', value: l.loaiThuTuc },
      { label: 'Lần lập', value: `Lần ${l.lan}` },
      { label: 'Phòng ban', value: l.phongBan },
      { label: 'Mã số BHXH đơn vị', value: l.maBHXH },
      { label: 'Biểu mẫu', value: INS_BIEUMAU_LABEL[l.phienBanBieuMau] },
      { label: 'Kênh nộp', value: INS_KENHNOP_LABEL[l.kenhNop] },
      { label: 'Người lập', value: `${l.nguoiLap} · ${l.thoiDiemLap}` },
    ];
    if (l.nguoiKiemTra) items.push({ label: 'Người kiểm tra', value: `${l.nguoiKiemTra} · ${l.thoiDiemKiemTra ?? ''}` });
    if (l.nguoiDuyet) items.push({ label: 'Người duyệt', value: `${l.nguoiDuyet} · ${l.thoiDiemDuyet ?? ''}` });
    if (l.nguoiKy) items.push({ label: 'Người ký', value: `${l.nguoiKy} · ${l.thoiDiemKy ?? ''}` });
    if (l.nguoiNop) items.push({ label: 'Người nộp', value: `${l.nguoiNop} · ${l.thoiDiemNop ?? ''}` });
    return items;
  });

  /** Sau nộp / kỳ khóa → tham số + item khóa (nguyên văn PBI khi đổi). */
  protected readonly editable = computed(() => {
    const l = this.lo();
    return !!l
      && ['nhap', 'bi-tra-lai', 'dang-kiem-tra', 'cho-duyet', 'da-duyet', 'da-ky'].includes(l.trangThai)
      && !this.store.kyLocked();
  });

  /* ── VÙNG 1: item trong lô ── */
  protected readonly itemsInLo = computed(() => this.store.itemsOfLo(this.loId()).map((i) => {
    const nv = insNhanVien(i.nhanVienId);
    const flag = i.truyThu && !i.coD01TS ? '⑤ Thiếu D01-TS' : !i.maPhuongAn ? '⑦ Thiếu mã phương án' : i.thieuLuong ? 'Thiếu lương căn cứ' : '';
    return {
      id: i.maItem,
      ten: nv?.name ?? '—',
      sub: nv?.code ?? '—',
      suKien: i.refSuKien,
      pa: i.maPhuongAn ? `${i.maPhuongAn} — ${i.tenPhuongAn ?? ''}` : 'thiếu mã phương án',
      preLabel: i.ketQuaPreCheck ? INS_PRECHECK_LABEL[i.ketQuaPreCheck] : 'Chưa chạy',
      preTone: i.ketQuaPreCheck ? INS_PRECHECK_TONE[i.ketQuaPreCheck] : 'neutral',
      trangThaiLabel: INS_LO_ITEM_LABEL[i.trangThai],
      trangThaiTone: INS_LO_ITEM_TONE[i.trangThai],
      flag,
    };
  }));

  /* ── VÙNG 2: ứng viên đủ điều kiện + dry-run ⑤⑦ ── */
  protected readonly candidates = computed(() => this.store.candidatesOfKy().map((i) => {
    const nv = insNhanVien(i.nhanVienId);
    const canhBao = !i.maPhuongAn ? '⑦ thiếu mã phương án'
      : i.truyThu && !i.coD01TS ? '⑤ thiếu D01-TS'
      : i.coKhongAnhHuong ? 'CD — không ảnh hưởng' : '';
    return {
      id: i.maItem,
      ten: nv?.name ?? '—',
      sub: nv?.code ?? '—',
      suKien: i.refSuKien,
      pa: i.maPhuongAn ? `${i.maPhuongAn} — ${i.tenPhuongAn ?? ''}` : 'thiếu mã phương án',
      canhBao,
    };
  }));

  private readonly selIds = signal<string[]>([]);
  protected readonly sel = computed(() => this.selIds());
  protected isSel(id: string): boolean { return this.selIds().includes(id); }
  protected toggle(id: string): void {
    this.selIds.update((l) => (l.includes(id) ? l.filter((x) => x !== id) : [...l, id]));
  }
  /** Dry-run cho ins-bulk-bar (KHÔNG đổi state) — eligible/blocked theo guard ⑤⑦ + chống trùng. */
  protected readonly preview = computed(() => this.store.themVaoLoPreview(this.selIds(), this.loId()));

  protected themVaoLo(): void {
    const ids = this.selIds();
    if (!ids.length) { this.msg.warning('Chưa chọn ứng viên nào.'); return; }
    const r = this.store.themVaoLo(ids, this.loId());
    if (r.done && r.skipped.length) this.msg.warning(`Đã thêm ${r.done}/${ids.length} item · ${r.skipped.length} bị bỏ qua (xem lý do trên thanh bulk).`);
    else if (r.done) this.msg.success(`Đã thêm ${r.done}/${ids.length} item vào lô ${this.loId()}.`);
    else this.msg.error(r.skipped[0]?.reason ?? 'Không thêm được item nào.');
    // Giữ lại các item bị chặn để cán bộ gỡ nguyên nhân rồi thử lại.
    this.selIds.update((l) => l.filter((id) => r.skipped.some((s) => s.id === id)));
  }
  protected themTatCa(): void {
    const all = this.candidates().map((c) => c.id);
    if (!all.length) { this.msg.warning('Không còn ứng viên nào.'); return; }
    this.selIds.set(all);
    const p = this.store.themVaoLoPreview(all, this.loId());
    this.msg.info(`Đã chọn tất cả ${all.length} ứng viên — ${p.eligible} vào lô · ${all.length - p.eligible} bỏ qua vì vướng điều kiện. Bấm "Thêm vào lô" để xác nhận.`);
  }

  protected setBieuMau(v: unknown): void {
    const r = this.store.doiThamSoLo(this.loId(), { phienBanBieuMau: v as InsBieuMau });
    r.ok ? this.msg.success('Đã đổi biểu mẫu lô.') : this.msg.error(r.reason ?? 'Không đổi được.');
  }
  protected setKenh(v: unknown): void {
    const r = this.store.doiThamSoLo(this.loId(), { kenhNop: v as InsKenhNop });
    r.ok ? this.msg.success('Đã đổi kênh nộp.') : this.msg.error(r.reason ?? 'Không đổi được.');
  }

  protected goKhoiLo(itemId: string): void {
    const r = this.store.goKhoiLo(itemId);
    r.ok ? this.msg.success('Đã gỡ item khỏi lô — về Sẵn sàng, dòng gốc giữ nguyên.') : this.msg.error(r.reason ?? 'Không gỡ được.');
  }

  /* ── KHỐI 1: hồi tố (hoiToOfKy của lô này) — chênh tách theo kỳ ── */
  protected readonly hoiTo = computed(() => this.store.hoiToOfKy().filter((h) => h.loId === this.loId()).map((h) => ({
    id: h.id,
    ten: this.nvName(h.nhanVienId),
    loaiLabel: h.loai === 'truy-thu' ? 'Truy thu' : 'Thoái thu',
    loaiColor: h.loai === 'truy-thu' ? 'orange' : 'blue',
    coD01TS: h.coD01TS,
    phiaChiu: h.phiaChiu === 'cqbh' ? 'Cơ quan BHXH' : 'Người lao động',
    khoang: `${h.tuThang} → ${h.denThang}`,
    ngayQuyetDinh: h.ngayQuyetDinh,
    vanBan: h.vanBan ?? 'chưa có văn bản',
    rows: h.chenhTheoKy.map((k) => ({
      ky: k.ky, cu: k.luongDaDong, moi: k.luongDieuChinh, diff: k.chenhLech, tone: this.diffTone(k.chenhLech),
    })),
  })));

  /* ── KHỐI 2: tạm dừng HT-TT (guard ⑥) ── */
  protected readonly tamDung = computed(() => this.store.tamDung().map((h) => {
    const trinhReason = h.trangThai === 'nhap' ? this.store.trinhTamDungReason(h.id) : null;
    return {
      id: h.id,
      header: `${this.nvName(h.nhanVienId)} · ${h.khoangTu} → ${h.khoangDen} · ${INS_TAMDUNG_LABEL[h.trangThai]}`,
      trangThai: h.trangThai,
      trangThaiLabel: INS_TAMDUNG_LABEL[h.trangThai],
      tone: INS_TAMDUNG_TONE[h.trangThai],
      khoang: `${h.khoangTu} → ${h.khoangDen}`,
      soThang: `${this.soThang(h.khoangTu, h.khoangDen)} tháng`,
      phamVi: h.phamVi,
      vanBanDonVi: h.vanBanDonVi || 'Thiếu văn bản đề nghị của đơn vị',
      vanBanCoQuan: h.vanBanCoQuan || 'Thiếu văn bản chấp thuận của cơ quan',
      thieuVanBanCoQuan: !h.vanBanCoQuan,
      dongGiamTheoKy: h.dongGiamTheoKy,
      nghiaVuDongBu: h.nghiaVuDongBu,
      kyHienThiDongBu: h.kyHienThiDongBu,
      canhBaoTruocHan: h.canhBaoTruocHan ?? '',
      lyDoKetThucSom: h.lyDoKetThucSom ?? '',
      trinhReason,
    };
  }));

  protected trinhTamDung(id: string): void {
    const r = this.store.trinhTamDung(id);
    r.ok ? this.msg.success('Đã trình duyệt hồ sơ tạm dừng — đủ 2 văn bản (điểm dừng ⑥ qua).') : this.msg.error(r.reason ?? 'Không trình được.');
  }

  /* ── helpers thuần (deterministic, zoneless-safe) ── */
  private nvName(id: string): string { const nv = insNhanVien(id); return nv ? `${nv.name} · ${nv.code}` : id; }
  private diffTone(diff: string): 'up' | 'down' | 'zero' {
    const s = (diff ?? '').trim();
    if (s.startsWith('+')) return 'up';
    if (s.startsWith('−') || s.startsWith('-')) return 'down';
    return 'zero';
  }
  /** Số tháng của khoảng 'MM/yyyy' → 'MM/yyyy' (bao gồm 2 đầu) — thuần, không Date runtime. */
  private soThang(tu: string, den: string): number {
    const a = /(\d{1,2})\/(\d{4})/.exec(tu ?? '');
    const b = /(\d{1,2})\/(\d{4})/.exec(den ?? '');
    if (!a || !b) return 0;
    return (+b[2] - +a[2]) * 12 + (+b[1] - +a[1]) + 1;
  }
}
