import { ChangeDetectionStrategy, Component, inject, signal } from '@angular/core';
import { InsShellStore } from '../_data/_core';
import { InsM06Store, M06TabKey } from '../_data/_m06-data';
import { InsM06Search } from './search/m06-search';
import { InsM06Profile360 } from './profile-360/m06-360-page';
import { M06_DEFAULT_TAB_360, type M06Tab360 } from './profile-360/_m06-360-data';

/** ═════════ M06 — HỒ SƠ (Phase D4): A Trung tâm hồ sơ 4 tab ↔ B Insurance 360 6 tab ═════════
 *  Điều hướng NỘI BỘ bằng signal (không đổi URL — pattern m05-page). B vào DUY NHẤT từ A
 *  đúng tab ngữ cảnh (M06_TAB_A_TO_B). navCtx chéo module:
 *  - 'nv:<nhanVienId>' / 'nld:<nhanVienId>' (M02 "Mở hồ sơ 360") → mở thẳng Màn B tab Định danh.
 *  - 'tab:<t1|t2|t3|t4>' (VD M04 chuyển exception → tab:t4) → mở Màn A đúng tab. */
@Component({
  selector: 'ins-m06-page',
  imports: [InsM06Search, InsM06Profile360],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <!-- Tra cứu LUÔN mounted (ẩn khi mở 360) → giữ state search (keyword/filter/sort/page/scroll)
         khi back. 360 render có điều kiện theo view(). -->
    <ins-m06-search [style.display]="view() ? 'none' : 'flex'" (open360)="open360($event)" />
    @if (view(); as v) {
      <ins-m06-profile-360 [nhanVienId]="v.nhanVienId" [initialTab]="v.tab" (back)="view.set(null)" />
    }
  `,
  styles: [`
    :host { display: flex; flex-direction: column; flex: 1 1 auto; min-height: 0; }
  `],
})
export class InsM06Page {
  private readonly shell = inject(InsShellStore);
  private readonly store = inject(InsM06Store);

  /** null = Màn A (trung tâm); có giá trị = Màn B (360) đúng tab ngữ cảnh. */
  protected readonly view = signal<{ nhanVienId: string; tab: M06Tab360 } | null>(null);

  constructor() {
    // Diễn giải navCtx MỘT lần khi mở màn (drawer/navigation contract).
    const f = this.shell.navCtx().filter;
    if (f?.startsWith('nv:') || f?.startsWith('nld:')) {
      const id = f.slice(f.indexOf(':') + 1);
      this.view.set({ nhanVienId: id, tab: M06_DEFAULT_TAB_360 });
      this.shell.navCtx.update((c) => ({ ...c, filter: undefined }));
    } else if (f?.startsWith('tab:')) {
      this.store.centerTab.set(f.slice(4) as M06TabKey);
      this.shell.navCtx.update((c) => ({ ...c, filter: undefined }));
    }
  }

  /** "Mở hồ sơ 360" từ trang Tra cứu — mở Màn B mặc định tab BHXH & KCB; search vẫn mounted (giữ state). */
  protected open360(id: string): void {
    this.view.set({ nhanVienId: id, tab: M06_DEFAULT_TAB_360 });
  }
}
