/* ─────────────────────────── Data dictionary §37 — M06SearchRow ─────────────────────────── */

export interface M06SearchRow {
  id: string;
  code: string;
  name: string;
  /** = name → hrm-user-cell tô màu avatar colorful. */
  avatarSeed: string;
  /** Nhãn đơn vị/khối hiển thị ở cột "Đơn vị". */
  donViLabel: string;
  /** id đơn vị (INS_DON_VI) — dùng cho advanced filter donVi[]; không hiển thị. */
  donViId: string;
  /** = position. */
  jobTitle: string;

  employmentStatus: M06EmploymentStatus; // §20
  insuranceStatus: M06InsuranceStatus;   // §21

  /** = insCode ('—' nếu chưa có mã số BHXH). */
  soBHXH: string;
  /** Mức lương đóng — chuỗi định dạng sẵn ('22.400.000' | '0'). */
  insuranceSalary: string;

  kcbName: string;  // 'BV Nhân dân 115' | '—'
  kcbCode: string;  // '79024' | ''  ('' → cột hiển thị "Chưa đăng ký")

  pendingTaskCount: number;
  urgentTaskCount: number;
  taskPriority: M06TaskPriority;   // §24 — dẫn xuất từ urgent/pending
  taskHint: string;                // '1 sắp đến hạn' | 'Cần bổ sung' | 'Không có' …

  lastMovementType: string;        // 'Điều chỉnh lương đóng' | 'Báo tăng mới' | 'Tạm giảm' | 'Báo giảm' | 'Chưa có biến động'
  lastMovementDate: string;        // '01/08/2026' | ''

  syncStatus: M06SyncStatus;       // 'synced' | 'error'
  lastSyncTime: string;            // '09:42'
  lastSyncDate: string;            // '12/08/2026'

  // Flags cho advanced filter (nhóm C · D):
  hasPendingMovement: boolean;
  hasBenefitCase: boolean;
  hasDataException: boolean;
  hasNearDeadline: boolean;
  hasNeedSupplement: boolean;
}

/* ─────────────────────────── Builder (tái dùng INS_NHAN_VIEN base + overlay) ─────────────────────────── */

/** Phần bảo hiểm chồng lên base NLĐ. Các field base (code/name/jobTitle/soBHXH/donVi) lấy từ INS_NHAN_VIEN. */
interface M06Overlay {
  employmentStatus: M06EmploymentStatus;
  insuranceStatus: M06InsuranceStatus;
  insuranceSalary?: string; // mặc định = salary; override '0' khi tạm giảm/chưa/chờ/đã ngừng
  kcbName: string;
  kcbCode: string;
  pendingTaskCount: number;
  urgentTaskCount: number;
  taskHint: string;
  lastMovementType: string;
  lastMovementDate: string;
  syncStatus: M06SyncStatus;
  lastSyncTime: string;
  lastSyncDate: string;
  hasPendingMovement?: boolean;
  hasBenefitCase?: boolean;
  hasDataException?: boolean;
  hasNearDeadline?: boolean;
  hasNeedSupplement?: boolean;
}

function derivePriority(pending: number, urgent: number): M06TaskPriority {
  if (urgent > 0) return 'urgent';
  if (pending > 0) return 'warn';
  return 'none';
}

function fromBase(nv: InsNhanVien, o: M06Overlay): M06SearchRow {
  return {
    id: nv.id,
    code: nv.code,
    name: nv.name,
    avatarSeed: nv.name,
    donViLabel: M06_DON_VI_SHORT[nv.donViId] ?? nv.dept,
    donViId: nv.donViId,
    jobTitle: nv.position,
    employmentStatus: o.employmentStatus,
    insuranceStatus: o.insuranceStatus,
    soBHXH: nv.insCode,
    insuranceSalary: o.insuranceSalary ?? nv.salary,
    kcbName: o.kcbName,
    kcbCode: o.kcbCode,
    pendingTaskCount: o.pendingTaskCount,
    urgentTaskCount: o.urgentTaskCount,
    taskPriority: derivePriority(o.pendingTaskCount, o.urgentTaskCount),
    taskHint: o.taskHint,
    lastMovementType: o.lastMovementType,
    lastMovementDate: o.lastMovementDate,
    syncStatus: o.syncStatus,
    lastSyncTime: o.lastSyncTime,
    lastSyncDate: o.lastSyncDate,
    hasPendingMovement: o.hasPendingMovement ?? false,
    hasBenefitCase: o.hasBenefitCase ?? false,
    hasDataException: o.hasDataException ?? false,
    hasNearDeadline: o.hasNearDeadline ?? false,
    hasNeedSupplement: o.hasNeedSupplement ?? false,
  };
}

