/* ─────────────────────────── Quick filter §35,39 ─────────────────────────── */

export type M06QuickFilter = 'dang-tham-gia' | 'can-xu-ly' | 'tam-giam';

export interface M06QuickFilterDef {
  key: M06QuickFilter;
  label: string;
  /** Có hiển thị badge số NLĐ match (chỉ "Cần xử lý"). */
  showCount: boolean;
}
export const M06_QUICK_FILTERS: readonly M06QuickFilterDef[] = [
  { key: 'dang-tham-gia', label: 'Đang tham gia', showCount: false },
  { key: 'can-xu-ly', label: 'Cần xử lý', showCount: true },
  { key: 'tam-giam', label: 'Tạm giảm', showCount: false },
];

/** Vị từ quick filter (áp NGAY, không cần Apply). */
export const M06_QUICK_FILTER_PRED: Record<M06QuickFilter, (r: M06SearchRow) => boolean> = {
  'dang-tham-gia': (r) => r.insuranceStatus === 'dang-tham-gia',
  'can-xu-ly': (r) => r.pendingTaskCount > 0,
  'tam-giam': (r) => r.insuranceStatus === 'tam-giam',
};

export function m06MatchesQuickFilter(row: M06SearchRow, qf: M06QuickFilter | null): boolean {
  return qf === null ? true : M06_QUICK_FILTER_PRED[qf](row);
}

/** Đếm số NLĐ match 1 quick filter (badge "Cần xử lý · N"). */
export function m06QuickFilterCount(qf: M06QuickFilter): number {
  return M06_SEARCH_ROWS.reduce((n, r) => (M06_QUICK_FILTER_PRED[qf](r) ? n + 1 : n), 0);
}

/* ─────────────────────────── Advanced filter model §38 ─────────────────────────── */

export interface M06SearchFilter {
  donVi: string[];                       // id INS_DON_VI
  employmentStatus: M06EmploymentStatus[];
  insuranceStatus: M06InsuranceStatus[];
  kcb: string[];                         // kcbCode
  salaryFrom: number | null;
  salaryTo: number | null;
  // Nhóm C — công việc cần xử lý:
  hasPendingMovement: boolean;
  hasBenefitCase: boolean;
  hasDataException: boolean;
  hasNearDeadline: boolean;
  hasNeedSupplement: boolean;
  // Nhóm D — dữ liệu:
  syncStatus: M06SyncStatus[];
}

/** Bộ lọc rỗng (không điều kiện nào). Trả bản mới → an toàn khi mutate/patch trong signal. */
export function m06EmptyFilter(): M06SearchFilter {
  return {
    donVi: [], employmentStatus: [], insuranceStatus: [], kcb: [],
    salaryFrom: null, salaryTo: null,
    hasPendingMovement: false, hasBenefitCase: false, hasDataException: false,
    hasNearDeadline: false, hasNeedSupplement: false,
    syncStatus: [],
  };
}

/** '22.400.000' → 22400000 ; '—'/'0'/'' → 0. Dùng cho so khớp salaryFrom/To. */
export function m06Money(v: string): number {
  const n = Number(String(v).replace(/[^\d]/g, ''));
  return Number.isFinite(n) ? n : 0;
}

/** Số điều kiện advanced đang bật (cho badge "Bộ lọc (N)" — KHÔNG tính search/QF). */
export function m06AdvancedCount(f: M06SearchFilter): number {
  let n = 0;
  if (f.donVi.length) n++;
  if (f.employmentStatus.length) n++;
  if (f.insuranceStatus.length) n++;
  if (f.kcb.length) n++;
  if (f.salaryFrom !== null || f.salaryTo !== null) n++;
  if (f.hasPendingMovement) n++;
  if (f.hasBenefitCase) n++;
  if (f.hasDataException) n++;
  if (f.hasNearDeadline) n++;
  if (f.hasNeedSupplement) n++;
  if (f.syncStatus.length) n++;
  return n;
}

/** Khớp 1 dòng với advanced filter (AND giữa các nhóm, OR trong multi-select). */
export function m06MatchesFilter(row: M06SearchRow, f: M06SearchFilter): boolean {
  if (f.donVi.length && !f.donVi.includes(row.donViId)) return false;
  if (f.employmentStatus.length && !f.employmentStatus.includes(row.employmentStatus)) return false;
  if (f.insuranceStatus.length && !f.insuranceStatus.includes(row.insuranceStatus)) return false;
  if (f.kcb.length && !f.kcb.includes(row.kcbCode)) return false;
  const sal = m06Money(row.insuranceSalary);
  if (f.salaryFrom !== null && sal < f.salaryFrom) return false;
  if (f.salaryTo !== null && sal > f.salaryTo) return false;
  if (f.hasPendingMovement && !row.hasPendingMovement) return false;
  if (f.hasBenefitCase && !row.hasBenefitCase) return false;
  if (f.hasDataException && !row.hasDataException) return false;
  if (f.hasNearDeadline && !row.hasNearDeadline) return false;
  if (f.hasNeedSupplement && !row.hasNeedSupplement) return false;
  if (f.syncStatus.length && !f.syncStatus.includes(row.syncStatus)) return false;
  return true;
}

/** Khớp từ khóa: name | code | soBHXH (lowercase includes). Rỗng → true. */
export function m06MatchesKeyword(row: M06SearchRow, keyword: string): boolean {
  const k = keyword.trim().toLowerCase();
  if (!k) return true;
  return (
    row.name.toLowerCase().includes(k) ||
    row.code.toLowerCase().includes(k) ||
    row.soBHXH.toLowerCase().includes(k)
  );
}
