import { ChangeDetectionStrategy, Component, input } from '@angular/core';
import { InsLayer, InsLayerBadge } from './ins-layer-badge';

/** ins-variance-cell — cặp số kỳ vọng → thực tế + chênh lệch có tone + nhãn lớp số liệu.
 *  Dùng ở M04 (đối soát/so sánh kỳ), M07-A (3 số đề nghị→duyệt→đã chi), M01 (khối 6).
 *  Mọi chuỗi FORMAT SẴN từ store/config (zoneless: component không tự tính).
 *  Promote từ bản cục bộ `m04-contribution/m04-variance-cell.ts` (D2) — API giữ nguyên. */
@Component({
  selector: 'ins-variance-cell',
  imports: [InsLayerBadge],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (expected() || actual()) {
      <span class="vc-pair">
        <span class="vc-num">{{ expected() || '—' }}</span>
        <span class="vc-arrow" aria-hidden="true">→</span>
        <span class="vc-num vc-num--actual">{{ actual() || '—' }}</span>
      </span>
    }
    <span class="vc-diff" [attr.data-tone]="tone()">{{ diff() }}</span>
    @if (layer(); as l) { <ins-layer-badge [layer]="l" /> }
  `,
  host: { class: 'ins-variance-cell' },
  styles: [`
    :host { display: inline-flex; align-items: baseline; gap: 8px; font-variant-numeric: tabular-nums; min-width: 0; }
    .vc-pair { display: inline-flex; align-items: baseline; gap: 5px; font-size: var(--fs-12); color: var(--text-sub); }
    .vc-num { white-space: nowrap; }
    .vc-num--actual { color: var(--text-strong); font-weight: 600; }
    .vc-arrow { color: var(--text-soft); }
    .vc-diff { font-size: var(--fs-13); font-weight: 700; white-space: nowrap; }
    .vc-diff[data-tone='up'] { color: var(--error-base); }
    .vc-diff[data-tone='down'] { color: var(--success-base); }
    .vc-diff[data-tone='zero'] { color: var(--text-sub); }
  `],
})
export class InsVarianceCell {
  /** Số kỳ vọng/kỳ gốc (chuỗi sẵn) — bỏ trống để chỉ hiện diff. */
  readonly expected = input('');
  /** Số thực tế/kỳ đối chiếu (chuỗi sẵn). */
  readonly actual = input('');
  /** Chênh lệch — chuỗi format sẵn kèm dấu ('+704.000' / '−4.196.000' / '0'). */
  readonly diff = input.required<string>();
  /** up = tăng/thiếu (đỏ) · down = giảm/thừa (xanh) · zero = không chênh. */
  readonly tone = input<'up' | 'down' | 'zero'>('zero');
  /** Nhãn lớp số liệu đi kèm (bất biến #1) — null = ngữ cảnh đã có nhãn chung. */
  readonly layer = input<InsLayer | null>(null);
}
