import { ChangeDetectionStrategy, Component, input } from '@angular/core';

/** ins-sla-chip — chip hạn xử lý/SLA nhỏ, radius full.
 *  `label` là CHUỖI ĐÃ FORMAT SẴN ("còn 3 ngày" / "quá hạn 2 ngày" / "chưa xác định hạn") —
 *  zoneless: component KHÔNG tự tính ngày. Tone map gợi ý: INS_COHAN_CHIP_TONE (_m02-data).
 *  Dùng ở: M01 aging map, M02 cột hạn, M05 queue, M07 tồn đọng. */
export type InsSlaTone = 'ok' | 'warn' | 'danger' | 'muted';

@Component({
  selector: 'ins-sla-chip',
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `{{ label() }}`,
  host: { class: 'ins-sla-chip', '[attr.data-tone]': 'tone()' },
  styles: [`
    :host {
      display: inline-flex; align-items: center; white-space: nowrap;
      font-size: var(--fs-11); line-height: 1.4; font-weight: 500;
      padding: 1px 9px; border-radius: var(--radius-full);
    }
    :host([data-tone='ok']) { background: var(--success-bg); color: var(--success-text); }
    :host([data-tone='warn']) { background: var(--warning-bg); color: var(--warning-text); }
    :host([data-tone='danger']) { background: var(--error-bg); color: var(--error-text); }
    :host([data-tone='muted']) { background: var(--bg-surface-subtle); color: var(--text-sub); }
  `],
})
export class InsSlaChip {
  readonly label = input.required<string>();
  readonly tone = input<InsSlaTone>('muted');
}
