import { ChangeDetectionStrategy, Component, computed, input, output } from '@angular/core';
import { HrmStatusCell, HrmTag } from 'hrm-ui';
import { InsLayerBadge, InsSectionLabel, InsSlaChip } from '../../_shared';
import { insNhanVien } from '../../_data/_core';
import { insSlaView } from '../../_data/_m02-data';
import {
  INS_CASE_NGUON_LABEL, INS_CASE_NHOM_LABEL, INS_CASE_STATE_LABEL, INS_CASE_STATE_TONE,
  INS_CHECKLIST_LABEL, InsCase, m05StepOfState,
} from '../../_data/_m05-data';

/** M05-A — panel TÓM TẮT case (content hrm-detail-peek side, gọn): trạng thái + 3 mốc + số tiền
 *  (nhãn lớp) + chứng từ thiếu + nút "Đi sâu xử lý →" mở Màn B ĐÚNG BƯỚC theo trạng thái
 *  (tiếp nhận lại → B1; lập lại lô/nộp lại → B4 — IA_LOCK m05.md). */
@Component({
  selector: 'ins-m05-case-peek',
  imports: [HrmStatusCell, HrmTag, InsLayerBadge, InsSectionLabel, InsSlaChip],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (c(); as c) {
      <div class="pk__head">
        <div class="pk__tags">
          <hrm-tag color="teal" size="sm">{{ nhomLabel() }}</hrm-tag>
          <hrm-status-cell [status]="$any(tone())" [label]="stateLabel()" variant="badge" />
          <ins-sla-chip [label]="sla().label" [tone]="sla().tone" />
        </div>
        <p class="pk__desc">{{ c.loaiCheDo }} · {{ nvView() }}</p>
        <p class="pk__sub">{{ nguonLabel() }} · nghỉ {{ c.tuNgay }} – {{ c.denNgay }}@if (c.ngayDiLamLai) { · đi làm lại {{ c.ngayDiLamLai }}}</p>
      </div>

      <section class="pk__sec">
        <ins-section-label text="3 mốc bắt buộc" tone="muted" />
        <div class="pk__mocs">
          <span>Phát sinh <b>{{ c.ngayPhatSinh }}</b></span>
          <span>Hiệu lực <b>{{ c.ngayHieuLuc }}</b></span>
          <span>Hạn xử lý <b>{{ c.ngayHanXuLy || '—' }}</b></span>
        </div>
      </section>

      <section class="pk__sec">
        <ins-section-label text="Số tiền hiện hành" tone="muted" />
        @if (c.soTienDuKien) {
          <div class="pk__money"><span class="pk__num">{{ c.soTienDuKien }}</span><ins-layer-badge layer="du-kien" /></div>
          @if (c.override?.trangThai === 'cho-duyet') {
            <p class="pk__muted">Override {{ c.override?.sau }} đang chờ duyệt — hệ thống giữ song song {{ c.override?.truoc }}.</p>
          }
        } @else {
          <p class="pk__muted">chưa có kết quả</p>
        }
      </section>

      <section class="pk__sec">
        <ins-section-label text="Chứng từ thiếu" tone="{{ thieu().length ? 'attention' : 'muted' }}" [count]="thieu().length" />
        @if (thieu().length) {
          @for (k of thieu(); track k.id) {
            <div class="pk__ck"><span class="pk__ck-x">✕</span>
              <span>{{ k.muc }} — <b>{{ ckLabel(k.trangThai) }}</b>@if (k.hanBoSung) { · hạn bổ sung {{ k.hanBoSung }}}</span></div>
          }
        } @else {
          <p class="pk__muted">Không có mục checklist bắt buộc thiếu.</p>
        }
      </section>

      @if (c.exceptionDong; as ex) {
        <section class="pk__sec">
          <ins-section-label text="Exception dữ liệu đóng" tone="critical" />
          <p class="pk__muted">{{ ex.id }} · {{ ex.moTa }} · hạn {{ ex.han }} · {{ ex.maTuongQuan }}</p>
        </section>
      }

      <button type="button" class="pk__deep" (click)="deep.emit({ caseId: c.maCase, step: buoc() })">
        Đi sâu xử lý → <span class="pk__deep-b">B{{ buoc() }}</span>
      </button>
    }
  `,
  host: { class: 'ins-m05-case-peek' },
  styles: [`
    :host { display: flex; flex-direction: column; gap: 14px; font-size: var(--fs-13); }
    .pk__head { display: flex; flex-direction: column; gap: 5px; }
    .pk__tags { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
    .pk__desc { margin: 0; font-weight: 600; color: var(--text-strong); }
    .pk__sub { margin: 0; font-size: var(--fs-12); color: var(--text-sub); }
    .pk__sec { display: flex; flex-direction: column; gap: 6px; padding-top: 10px; border-top: 1px solid var(--border-soft); }
    .pk__mocs { display: flex; gap: 12px; flex-wrap: wrap; font-size: var(--fs-12); color: var(--text-sub); }
    .pk__mocs b { color: var(--text-strong); }
    .pk__money { display: flex; align-items: center; gap: 8px; }
    .pk__num { font-size: var(--fs-18); font-weight: 700; color: var(--text-strong); font-variant-numeric: tabular-nums; }
    .pk__muted { margin: 0; font-size: var(--fs-12); color: var(--text-sub); }
    .pk__ck { display: flex; gap: 7px; align-items: baseline; font-size: var(--fs-12); color: var(--text-body); }
    .pk__ck b { color: var(--warning-text); }
    .pk__ck-x { color: var(--error-base); font-weight: 700; }
    .pk__deep {
      margin-top: 2px; display: inline-flex; align-items: center; justify-content: center; gap: 7px;
      border: 0; border-radius: var(--radius-md); background: var(--primary-base); color: var(--static-white, #fff);
      font: inherit; font-size: var(--fs-13); font-weight: 600; padding: 8px 14px; cursor: pointer;
    }
    .pk__deep:hover { opacity: .92; }
    .pk__deep-b {
      background: color-mix(in srgb, var(--static-white, #fff) 22%, transparent);
      border-radius: var(--radius-sm); padding: 0 7px; font-size: var(--fs-12);
    }
  `],
})
export class InsM05CasePeek {
  readonly c = input.required<InsCase>();
  /** Mở Màn B đúng bước theo trạng thái. */
  readonly deep = output<{ caseId: string; step: number }>();

  protected readonly nhomLabel = computed(() => INS_CASE_NHOM_LABEL[this.c().nhom]);
  protected readonly stateLabel = computed(() => INS_CASE_STATE_LABEL[this.c().trangThai]);
  protected readonly tone = computed(() => INS_CASE_STATE_TONE[this.c().trangThai]);
  protected readonly nguonLabel = computed(() => INS_CASE_NGUON_LABEL[this.c().nguon]);
  protected readonly sla = computed(() => insSlaView(this.c()));
  protected readonly buoc = computed(() => m05StepOfState(this.c().trangThai));
  protected readonly thieu = computed(() =>
    this.c().checklist.filter((k) => k.batBuoc && (k.trangThai === 'thieu' || k.trangThai === 'cho-xac-minh')));
  protected readonly nvView = computed(() => {
    const nv = insNhanVien(this.c().nhanVienId);
    return nv ? `${nv.name} (${nv.code})` : '—';
  });
  protected ckLabel(s: 'du' | 'thieu' | 'khong-ap-dung' | 'cho-xac-minh'): string { return INS_CHECKLIST_LABEL[s]; }
}
