/** ── BQA-14: trạng thái kỳ SỐNG từ M04 ──
 *  M04 SỞ HỮU trạng thái kỳ runtime (khóa / mở lại). Để M01/M02/M03 phản ánh khóa runtime mà
 *  `_core` KHÔNG import ngược M04 (tránh vòng), InsM02Store/InsM03Store — vốn đã inject InsM04Store
 *  cho các đối soát khác — đăng ký reader `kỳ-đã-khóa` vào đây lúc khởi tạo (`insSetKyKhoaReader`).
 *  Chưa mở M02/M03 (reader null) → fallback trạng thái tĩnh INS_KY (seed trùng M04 nên nhất quán). */
let insKyKhoaReader: ((id: string) => boolean) | null = null;
export function insSetKyKhoaReader(fn: (id: string) => boolean): void { insKyKhoaReader = fn; }

export function insKyDaKhoa(id: string): boolean {
  if (insKyKhoaReader) return insKyKhoaReader(id);
  const t = insKy(id)?.trangThai;
  return t === 'da-khoa' || t === 'da-khoa-dieu-chinh';
}

