/* ─────────────────────────── Shell store (điều hướng nội bộ mini-app) ─────────────────────────── */

/** Ngữ cảnh điều hướng chéo module — LUÔN mang {ky, donVi, filter}; đích KHÔNG reset filter
 *  (navigation contract, _cross-cutting.md). */
export interface InsNavContext {
  ky?: string;      // id InsKy
  donVi?: string;   // id InsDonVi
  filter?: string;  // filter key màn đích tự diễn giải (VD 'qua-han', 'tab5:thieu-bhxh')
}

@Injectable({ providedIn: 'root' })
export class InsShellStore {
  /** Module đang mở (sidebar 8 mục). */
  readonly section = signal<InsModuleKey>('m01');
  /** Ngữ cảnh mang theo khi điều hướng chéo module — mặc định kỳ đang Mở. */
  readonly navCtx = signal<InsNavContext>({ ky: 'k08' });

  go(section: InsModuleKey, ctx?: InsNavContext): void {
    if (ctx) this.navCtx.update((c) => ({ ...c, ...ctx }));
    this.section.set(section);
  }

  resetDemo(): void {
    this.section.set('m01');
    this.navCtx.set({ ky: 'k08' });
  }
}
