import { ChangeDetectionStrategy, Component, computed, inject, input, model, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import {
  HrmAlert, HrmDescItem, HrmDescriptions, HrmDetailPeek, HrmEmpty, HrmPeekMode, HrmSegmented,
  HrmTag, HrmTagColor,
} from 'hrm-ui';
import { insKy, insNhanVien } from '../_data/_core';
import {
  INS_BIEUMAU_LABEL, INS_KENHNOP_LABEL, INS_NHOM_LABEL, INS_NHOM_THUTUC, INS_PHUONGAN_LABEL,
  InsM03Store, InsNhomKeKhai,
} from '../_data/_m03-data';
import { InsSectionLabel } from '../_shared';
import { A07_D02LT_NOTE } from './_m03-columns';

/** Màu tag 4 nhóm kê khai (🟢 tăng · 🔴 giảm · 🔵 điều chỉnh · ⚪ đang tham gia) — HrmTagHue. */
const NHOM_TAG: Record<InsNhomKeKhai, HrmTagColor> = {
  'bao-tang': 'green', 'bao-giam': 'red', 'dieu-chinh': 'blue', 'dang-tham-gia': 'default',
};

/** Một bản ghi D02-LT (1 NLĐ trong lô) — dựng SẴN chuỗi (zoneless-safe, binding ổn định). */
interface D02Record {
  id: string;
  name: string;
  sub: string;                 // "VNR-015 · Kinh doanh"
  nhomLabel: string;
  nhomTone: HrmTagColor;
  thuTuc: string;              // '600' | '600a' | '600b' | '—'
  thieuMaBHXH: boolean;        // → cần TK1-TS
  cd: boolean;                 // dòng CD — không kê khai, chỉ đối chiếu
  desc: HrmDescItem[];         // khối key/value (bản chuẩn / bản đối chiếu)
}

/** ═════════ M03 · SC-B2 — BẢN D02-TS FORM VIEWER ("Xem tờ khai") ═════════
 *  NET-NEW: mở bản tờ khai D02-TS của MỘT lô trong hrm-detail-peek chế độ CENTER (modal giữa).
 *  Render khối kê khai D02-LT theo TỪNG NLĐ dạng key/value (HrmDescriptions từ itemsOfLo(loId)):
 *  mã phương án = chỉ tiêu CT02 · mức đóng (lương căn cứ) · tổ hợp quỹ (mẫu D02-TS). Kèm khối đăng ký
 *  TK1-TS CHỈ khi có NLĐ chưa có mã số BHXH. Header = biểu mẫu (phienBanBieuMau) + "chọn bản": bản
 *  chuẩn cơ quan / bản đối chiếu nội bộ (hrm-segmented) — đổi cách hiển thị nhãn, cùng dữ liệu.
 *  A-07 (tin cậy Thấp) hiển thị NỔI ở đầu: sơ đồ cột D02-LT chờ đối chiếu QĐ 366/QĐ-BHXH — BẢN
 *  THAM CHIẾU. FIDELITY PROTOTYPE — KHÔNG bịa lược đồ cột chính thức của cơ quan.
 *  Host sở hữu open + selectedLoId; wire `<ins-m03-d02-viewer [(open)] [loId]>`. */
@Component({
  selector: 'ins-m03-d02-viewer',
  imports: [FormsModule, HrmAlert, HrmDescriptions, HrmDetailPeek, HrmEmpty, HrmSegmented, HrmTag, InsSectionLabel],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <hrm-detail-peek [(open)]="open" [peekMode]="'center'" [modes]="peekModes"
      [title]="peekTitle()" [content]="formTpl" [modalWidth]="780"
      closeLabel="Đóng" switchLabel="Đổi cách hiển thị" />

    <ng-template #formTpl>
      @if (lo(); as lo) {
        <div class="d02">
          <!-- A-07 (tin cậy Thấp) — NỔI ở đầu bước dựng tờ khai -->
          <hrm-alert class="d02__a07" type="warning" [showIcon]="true"
            message="A-07 · Bản tham chiếu — tin cậy Thấp" [description]="a07Note" />

          <!-- Header: biểu mẫu của lô + chọn bản kết xuất -->
          <div class="d02__head">
            <div class="d02__bieumau">
              <span class="d02__lbl">Biểu mẫu</span>
              <span class="d02__bieumau-v">{{ bieuMauLabel() }}</span>
              <hrm-tag color="default" size="sm" variant="lighter">Khối kê khai D02-LT</hrm-tag>
            </div>
            <div class="d02__ban">
              <span class="d02__lbl">Chọn bản</span>
              <hrm-segmented [options]="banSegs" [(ngModel)]="banModel" size="sm" />
            </div>
          </div>

          <!-- Định danh lô (chỉ đọc) -->
          <hrm-descriptions [items]="loMeta()" [column]="2" [bordered]="true" size="small" />

          <!-- Mã thủ tục hệ thống tự gắn theo loại biến động -->
          <p class="d02__thutuc"><b>Mã thủ tục tự gắn:</b> {{ thuTucSummary() }}</p>

          <!-- Khối kê khai D02-LT — 1 bản ghi / NLĐ -->
          <div class="d02__sec">
            <ins-section-label text="Khối kê khai D02-LT" tone="muted" [count]="records().length" />
            @if (records().length) {
              <div class="d02__records">
                @for (r of records(); track r.id) {
                  <div class="d02__rec" [class.d02__rec--cd]="r.cd">
                    <div class="d02__rec-head">
                      <div class="d02__rec-id">
                        <span class="d02__rec-name">{{ r.name }}</span>
                        <span class="d02__rec-sub">{{ r.sub }}</span>
                      </div>
                      <div class="d02__rec-tags">
                        <hrm-tag [color]="r.nhomTone" size="sm">{{ r.nhomLabel }}@if (r.thuTuc !== '—') { · {{ r.thuTuc }} }</hrm-tag>
                        @if (r.thieuMaBHXH) { <hrm-tag color="warning" size="sm" variant="lighter">Thiếu mã BHXH · kèm TK1-TS</hrm-tag> }
                      </div>
                    </div>
                    <hrm-descriptions [items]="r.desc" [column]="1" [bordered]="true" size="small" />
                  </div>
                }
              </div>
            } @else {
              <hrm-empty description="Lô chưa có dòng kê khai nào." />
            }
          </div>

          <!-- Khối đăng ký TK1-TS — CHỈ khi có NLĐ chưa có mã số BHXH -->
          @if (tk1Rows().length) {
            <div class="d02__sec">
              <ins-section-label text="Khối đăng ký TK1-TS" tone="attention" [count]="tk1Rows().length" />
              <hrm-alert class="d02__tk1-note" type="info" [showIcon]="true"
                message="TK1-TS chỉ bắt buộc khi NLĐ chưa có mã số BHXH"
                description="Đăng ký cấp mã số BHXH lần đầu — thiếu mã số cơ quan sẽ không tiếp nhận tờ khai." />
              <div class="d02__tk1-list">
                @for (t of tk1Rows(); track t.id) {
                  <div class="d02__tk1-row">
                    <div class="d02__rec-id">
                      <span class="d02__rec-name">{{ t.name }}</span>
                      <span class="d02__rec-sub">{{ t.sub }}</span>
                    </div>
                    <span class="d02__tk1-suk">{{ t.suKien }}</span>
                  </div>
                }
              </div>
            </div>
          }

          <p class="d02__foot">
            Bản tham chiếu (prototype) — số phải đóng chính thức do lần tính chốt kỳ sinh ra, không nằm ở đây.
            Sơ đồ cột D02-LT chờ đối chiếu nguyên văn phụ lục QĐ 366/QĐ-BHXH (A-07 · tin cậy Thấp).
          </p>
        </div>
      } @else {
        <hrm-empty description="Chưa chọn lô để xem tờ khai." />
      }
    </ng-template>
  `,
  host: { class: 'ins-m03-d02-viewer' },
  styles: [`
    .d02 { display: flex; flex-direction: column; gap: 14px; font-size: var(--fs-13); }

    .d02__a07 { display: block; }

    .d02__head { display: flex; align-items: flex-end; justify-content: space-between; gap: 14px; flex-wrap: wrap; }
    .d02__bieumau, .d02__ban { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
    .d02__lbl { font-size: var(--fs-11); font-weight: 700; text-transform: uppercase; letter-spacing: .04em; color: var(--text-soft); }
    .d02__bieumau-v { font-size: var(--fs-14); font-weight: 700; color: var(--text-strong); }

    .d02__thutuc { margin: 0; font-size: var(--fs-12); color: var(--text-sub);
      padding: 7px 10px; border: 1px solid var(--border-soft); border-radius: var(--radius-md); background: var(--bg-surface-subtle); }
    .d02__thutuc b { color: var(--text-strong); font-weight: 600; }

    .d02__sec { display: flex; flex-direction: column; gap: 8px; padding-top: 12px; border-top: 1px solid var(--border-soft); }

    .d02__records { display: flex; flex-direction: column; gap: 10px; }
    .d02__rec { display: flex; flex-direction: column; gap: 7px; padding: 10px 12px;
      border: 1px solid var(--border-soft); border-radius: var(--radius-lg); background: var(--bg-surface); }
    .d02__rec--cd { background: var(--bg-surface-subtle); border-style: dashed; }
    .d02__rec-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; flex-wrap: wrap; }
    .d02__rec-id { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
    .d02__rec-name { font-size: var(--fs-14); font-weight: 700; color: var(--text-strong); }
    .d02__rec-sub { font-size: var(--fs-12); color: var(--text-sub); }
    .d02__rec-tags { display: inline-flex; align-items: center; gap: 6px; flex-wrap: wrap; }
    :host ::ng-deep .d02__rec-tags .ant-tag { margin: 0; }

    .d02__tk1-note { display: block; }
    .d02__tk1-list { display: flex; flex-direction: column; border: 1px solid var(--border-sub); border-radius: var(--radius-md); overflow: hidden; }
    .d02__tk1-row { display: flex; align-items: center; justify-content: space-between; gap: 10px;
      padding: 8px 12px; border-bottom: 1px solid var(--border-soft); }
    .d02__tk1-row:last-child { border-bottom: 0; }
    .d02__tk1-suk { font-size: var(--fs-12); color: var(--text-sub); text-align: right; min-width: 0; overflow-wrap: anywhere; }

    .d02__foot { margin: 0; font-size: var(--fs-11); color: var(--text-soft); line-height: 1.5; }
  `],
})
export class InsM03D02Viewer {
  private readonly store = inject(InsM03Store);

  /** Lô đang xem (host bind [loId]; rỗng khi chưa chọn). */
  readonly loId = input<string>('');
  /** Mở/đóng bản tờ khai (two-way — host sở hữu d02 open state). */
  readonly open = model<boolean>(false);

  /** Peek CHỈ chế độ center (modal giữa) — bản tờ khai đọc toàn cục. */
  protected readonly peekModes: HrmPeekMode[] = ['center'];
  protected readonly a07Note = A07_D02LT_NOTE;

  /** Bộ chọn "bản kết xuất" — bản chuẩn cơ quan / bản đối chiếu nội bộ (nhãn khác, cùng dữ liệu). */
  protected readonly banSegs = [
    { label: 'Bản chuẩn cơ quan', value: 'chuan' },
    { label: 'Bản đối chiếu nội bộ', value: 'noibo' },
  ];
  /** Bản đang chọn — 'chuan' = bản chuẩn cơ quan (mặc định) · 'noibo' = bản đối chiếu nội bộ. */
  private readonly ban = signal<'chuan' | 'noibo'>('chuan');
  protected get banModel(): string { return this.ban(); }
  protected set banModel(v: string) { this.ban.set(v === 'noibo' ? 'noibo' : 'chuan'); }

  protected readonly lo = computed(() => {
    const id = this.loId();
    return id ? this.store.lo(id) ?? null : null;
  });
  private readonly items = computed(() => {
    const id = this.loId();
    return id ? this.store.itemsOfLo(id) : [];
  });

  protected readonly peekTitle = computed(() => {
    const lo = this.lo();
    return lo ? `Tờ khai D02-TS · ${lo.maLo}` : 'Tờ khai D02-TS';
  });
  protected readonly bieuMauLabel = computed(() => {
    const lo = this.lo();
    return lo ? INS_BIEUMAU_LABEL[lo.phienBanBieuMau] : '';
  });

  /** Định danh lô (chỉ đọc) — mã · kỳ · phòng ban/mã đơn vị · biểu mẫu/kênh nộp. */
  protected readonly loMeta = computed<HrmDescItem[]>(() => {
    const lo = this.lo();
    if (!lo) return [];
    return [
      { label: 'Mã lô · số hồ sơ', value: `${lo.maLo} · ${lo.soHoSo}` },
      { label: 'Kỳ · loại thủ tục', value: `${insKy(lo.ky)?.label ?? lo.ky} · ${lo.loaiThuTuc}` },
      { label: 'Phòng ban · mã đơn vị BHXH', value: `${lo.phongBan} · ${lo.maBHXH}` },
      { label: 'Biểu mẫu · kênh nộp', value: `${INS_BIEUMAU_LABEL[lo.phienBanBieuMau]} · ${INS_KENHNOP_LABEL[lo.kenhNop]}` },
    ];
  });

  /** Tổng mã thủ tục tự gắn theo nhóm (600 / 600a / 600b / đang tham gia). */
  protected readonly thuTucSummary = computed(() => {
    const g: Record<InsNhomKeKhai, number> = { 'bao-tang': 0, 'bao-giam': 0, 'dieu-chinh': 0, 'dang-tham-gia': 0 };
    for (const it of this.items()) g[this.store.nhomCuaItem(it)]++;
    const parts: string[] = [];
    if (g['bao-tang']) parts.push(`${g['bao-tang']} báo tăng (600)`);
    if (g['bao-giam']) parts.push(`${g['bao-giam']} báo giảm (600a)`);
    if (g['dieu-chinh']) parts.push(`${g['dieu-chinh']} điều chỉnh (600b)`);
    if (g['dang-tham-gia']) parts.push(`${g['dang-tham-gia']} đang tham gia (không kê khai)`);
    return parts.join(' · ') || 'Chưa có dòng kê khai';
  });

  /** Khối kê khai D02-LT — 1 bản ghi / NLĐ; nhãn key/value đổi theo "bản" đang chọn. */
  protected readonly records = computed<D02Record[]>(() => {
    const banNoiBo = this.banModel === 'noibo';
    return this.items().map((it) => {
      const nv = insNhanVien(it.nhanVienId);
      const nhom = this.store.nhomCuaItem(it);
      const laKeKhai = nhom !== 'dang-tham-gia';
      const thieuMaBHXH = !nv?.insCode || nv.insCode === '—';
      const paText = it.maPhuongAn
        ? `${it.maPhuongAn} — ${it.tenPhuongAn ?? INS_PHUONGAN_LABEL[it.maPhuongAn] ?? ''}${it.phienBanPA ? ` (${it.phienBanPA})` : ''}`
        : 'Thiếu mã phương án hiệu lực';
      const mucDong = it.coKhongAnhHuong
        ? 'Không ảnh hưởng số đóng (chỉ đối chiếu)'
        : it.thieuLuong ? 'Không tính được — thiếu lương căn cứ' : it.luongCanCu;
      const quy = laKeKhai ? 'BHXH · BHYT · BHTN · TNLĐ-BNN' : 'Không kê khai (chỉ đối chiếu)';
      const maBHXHValue = thieuMaBHXH ? 'Chưa có — kèm TK1-TS' : (nv?.insCode ?? '—');

      const desc: HrmDescItem[] = banNoiBo
        ? [
            { label: 'Người lao động', value: `${nv?.name ?? '—'} · ${nv?.code ?? ''}` },
            { label: 'Mã số BHXH', value: maBHXHValue },
            { label: 'Phương án (CT02)', value: paText },
            { label: 'Mức đóng (căn cứ)', value: mucDong },
            { label: 'Tổ hợp quỹ', value: quy },
            { label: 'Sự kiện nguồn', value: it.refSuKien },
            { label: 'Nguồn · lineage', value: it.nhanNguon ?? '—' },
          ]
        : [
            { label: 'Mã số BHXH', value: maBHXHValue },
            { label: 'Chỉ tiêu CT02 (phương án)', value: paText },
            { label: 'Mã thủ tục', value: INS_NHOM_THUTUC[nhom] === '—' ? 'Không kê khai' : INS_NHOM_THUTUC[nhom] },
            { label: 'Tiền lương làm căn cứ đóng', value: mucDong },
            { label: 'Tổ hợp quỹ đóng', value: quy },
          ];

      return {
        id: it.maItem,
        name: nv?.name ?? '—',
        sub: `${nv?.code ?? '—'}${nv?.dept ? ` · ${nv.dept}` : ''}`,
        nhomLabel: INS_NHOM_LABEL[nhom],
        nhomTone: NHOM_TAG[nhom],
        thuTuc: INS_NHOM_THUTUC[nhom],
        thieuMaBHXH,
        cd: !!it.coKhongAnhHuong,
        desc,
      };
    });
  });

  /** NLĐ chưa có mã số BHXH → khối TK1-TS (đăng ký lần đầu). */
  protected readonly tk1Rows = computed(() =>
    this.items()
      .filter((it) => { const nv = insNhanVien(it.nhanVienId); return !nv?.insCode || nv.insCode === '—'; })
      .map((it) => {
        const nv = insNhanVien(it.nhanVienId);
        return { id: it.maItem, name: nv?.name ?? '—', sub: `${nv?.code ?? '—'}${nv?.dept ? ` · ${nv.dept}` : ''}`, suKien: it.refSuKien };
      }));
}
