import { Component, inject } from '@angular/core';
import { NgTemplateOutlet } from '@angular/common';
import { ActivatedRoute } from '@angular/router';
import {
  TablerIconComponent, IconArrowsMaximize, IconBell,
  IconLayoutSidebarLeftCollapse, IconLayoutSidebarLeftExpand, IconBuilding, IconSelector, IconSettings,
} from '@tabler/icons-angular';
import {
  HrmAppShell, HrmSideNav, HrmNavSection, HrmNavItem, HrmButton,
} from 'hrm-ui';
import { SgDoc } from '../../../../doc/sg-doc';
import { SgUse, SgDo, SgDont } from '../../../../doc/sg-blocks';
import { INS_SITEMAP, InsModuleKey, InsShellStore } from './_data/_core';
import { InsM02Store } from './_data/_m02-data';
import { InsM03Store } from './_data/_m03-data';
import { InsM04Store } from './_data/_m04-data';
import { InsM05Store } from './_data/_m05-data';
import { InsM06Store } from './_data/_m06-data';
import { InsM07Store } from './_data/_m07-data';
import { InsM08Store } from './_data/_m08-data';
import { InsM01Page } from './m01-dashboard/m01-page';
import { InsM02Page } from './m02-changes/m02-page';
import { InsM03Page } from './m03-filing/m03-page';
import { InsM03bPage } from './m03b-theo-doi-ho-so/m03b-page';
import { InsM04Page } from './m04-contribution/m04-page';
import { InsM05Page } from './m05-benefits/m05-page';
import { InsM06Page } from './m06-records/m06-page';
import { InsM07Page } from './m07-payment/m07-page';
import { InsM08Page } from './m08-config/m08-page';

/** ═══════════ INS-BẢO HIỂM — REBUILD (sitemap 8 module M01–M08, 12 màn) ═══════════
 *  Shell của mini-app BHXH theo `_rebuild/02-ux-architecture/ux-architecture.md`:
 *  hrm-app-shell + hrm-side-nav 8 mục + hrm-page-header breadcrumb `Bảo hiểm ▸ <module>`.
 *  Điều hướng nội bộ bằng signal (`InsShellStore.section`) — KHÔNG đổi route; điều hướng chéo
 *  module LUÔN mang `{ky, donVi, filter}` (navigation contract).
 *  3 chế độ render giữ nguyên contract legacy: `/preview/insurance` (full màn hình, route data
 *  `preview`) · nhúng trong `<sg-doc>` (khung desktop + link "Mở toàn màn hình") · sg-doc text.
 *  Phase B: M01–M08 là placeholder (M02 build thật ở D1). Legacy 16 màn cũ còn nguyên trong
 *  thư mục (không còn trong nav) — xóa ở Phase F. */
@Component({
  selector: 'sg-feature-insurance',
  imports: [
    NgTemplateOutlet, TablerIconComponent, HrmAppShell, HrmSideNav, HrmButton,
    SgDoc, SgUse, SgDo, SgDont,
    InsM01Page, InsM02Page, InsM03Page, InsM03bPage, InsM04Page, InsM05Page, InsM06Page, InsM07Page, InsM08Page,
  ],
  template: `
    @if (preview) {
      <div class="lp-desktop lp-desktop--full"><ng-container *ngTemplateOutlet="screenTpl" /></div>
    } @else {
    <sg-doc category="Tính năng" title="INS-Bảo hiểm"
      desc="Nghiệp vụ BHXH khép kín theo 8 module M01–M08: từ biến động nhân sự đến kê khai, theo dõi đóng, chế độ, hồ sơ, theo dõi chi và thiết lập. Rebuild theo PBI INS — 3 lớp số liệu, lineage 100%, bulk thành công một phần, sổ điều chỉnh bất biến.">

      <div sgOverview>
        <div class="lp-desktop"><ng-container *ngTemplateOutlet="screenTpl" /></div>
        <div class="lp-full">
          <a class="lp-full-link" href="/preview/insurance" target="_blank" rel="noopener">
            <hrm-button variant="default"><tabler-icon [icon]="icMax" [size]="16" /> Mở toàn màn hình</hrm-button>
          </a>
        </div>
      </div>

      <div sgUsage>
        <sg-use
          purpose="Trung tâm điều hành BHXH: M02 hàng đợi biến động → M03 kê khai theo kỳ → M04 theo dõi đóng/đối soát → M05 chế độ → M06 hồ sơ → M07 theo dõi chi; M01 chỉ đọc số tổng hợp, M08 giữ mọi cấu hình versioned."
          [when]="whenList"
          behavior="Sidebar 8 module theo sitemap rebuild; điều hướng chéo module luôn mang {ky, đơn vị, filter} — số ở nguồn khớp số dòng ở đích; kỳ Đã khóa chuyển chỉ đọc; mọi số tiền mang đúng một nhãn lớp số liệu."
          avoid="Không dùng làm màn kê khai pháp lý thật — mã phương án/sơ đồ cột D02-LT chờ đối chiếu QĐ 366/QĐ-BHXH; các nhãn 'Cần stakeholder xác nhận' phải giữ nguyên khi demo." />
      </div>

      <div sgBest>
        <sg-do>Đi theo luồng chính: M02 xử lý biến động (Sẵn sàng) → chuyển lô kê khai → M03 nộp → M04 đối soát → khóa kỳ.</sg-do>
        <sg-do>Quan sát nhãn lớp số liệu (Dự kiến nội bộ / Đã giao dịch / Chính thức) cạnh mỗi con số khi demo.</sg-do>
        <sg-dont>Không kỳ vọng "xóa" dữ liệu — hệ thống chỉ có Loại trừ có lý do / sổ điều chỉnh append-only (bất biến PBI).</sg-dont>
      </div>

    </sg-doc>
    }

    <ng-template #screenTpl>
      <hrm-app-shell contentPad="none">
        <hrm-side-nav appSideNav
          [sections]="navSections"
          [selectedKey]="shell.section()"
          (itemClick)="onNav($event)"
          logoSrc="/assets/vnr-logo-full.svg" logoMarkSrc="/assets/vnr-logo-mark.svg"
          [toggleIcon]="icCollapse" [expandIcon]="icExpand"
          [(collapsed)]="collapsedModel"
          [user]="navUser" [switchIcon]="icSettings">
          <button snActions type="button" class="ins-bell" aria-label="Thông báo"><tabler-icon [icon]="icBell" [size]="18" /></button>
          <button snHead type="button" class="ins-org" [class.ins-org--min]="collapsedModel"
            aria-label="Tập đoàn VNR — Tài khoản doanh nghiệp">
            <span class="ins-org-ic"><tabler-icon [icon]="icOrg" [size]="20" [stroke]="1.7" /></span>
            @if (!collapsedModel) {
              <span class="ins-org-info">
                <span class="ins-org-name">Tập đoàn VNR</span>
                <span class="ins-org-sub">Tài khoản doanh nghiệp</span>
              </span>
              <tabler-icon class="ins-org-caret" [icon]="icCaret" [size]="16" [stroke]="1.7" />
            }
          </button>
        </hrm-side-nav>

        <!-- Không còn thanh [appTopNav]: page-header của từng module lên TRÊN CÙNG.
             Nút "Đặt lại demo" chuyển vào page-header của M02 (primary, góc phải) — vẫn reset TOÀN BỘ
             qua output (resetDemo)="resetDemo()". -->
        <div class="ins-body">
          @switch (shell.section()) {
            @case ('m01') { <ins-m01-page /> }
            @case ('m02') { <ins-m02-page (resetDemo)="resetDemo()" /> }
            @case ('m03') { <ins-m03-page /> }
            @case ('m03b') { <ins-m03b-page /> }
            @case ('m04') { <ins-m04-page /> }
            @case ('m05') { <ins-m05-page /> }
            @case ('m06') { <ins-m06-page /> }
            @case ('m07') { <ins-m07-page /> }
            @case ('m08') { <ins-m08-page /> }
          }
        </div>
      </hrm-app-shell>
    </ng-template>
  `,
  styles: [`
    :host { display: block; }
    .lp-desktop { height: 760px; border: 1px solid var(--border-sub); border-radius: var(--radius-xl); overflow: hidden; box-shadow: var(--shadow-regular-sm); }
    .lp-full { margin-top: 14px; }
    .lp-full-link { text-decoration: none; }
    .lp-desktop--full { height: 100vh; border: 0; border-radius: 0; box-shadow: none; }
    .lp-desktop ::ng-deep .shell-content { padding: 0; display: flex; flex-direction: column; min-height: 0; }

    .ins-body { display: flex; flex-direction: column; min-height: 0; flex: 1 1 auto; overflow: auto; background: var(--bg-body); }
    .ins-bell { display: grid; place-items: center; width: 30px; height: 30px; border: 0; border-radius: var(--radius-md);
      background: transparent; color: var(--text-sub); cursor: pointer; }
    .ins-bell:hover { background: var(--bg-surface-subtle); color: var(--text-strong); }

    /* Org switcher — content project vào slot snHead của hrm-side-nav (token-only). */
    .ins-org { display: flex; align-items: center; gap: 10px; width: 100%; padding: 8px 10px; cursor: pointer;
      background: var(--bg-surface); border: 1px solid var(--border-sub); border-radius: var(--radius-lg);
      font: inherit; text-align: left; }
    .ins-org:hover { border-color: var(--border-strong, var(--border-sub)); background: var(--bg-surface-subtle); }
    .ins-org-ic { display: grid; place-items: center; width: 36px; height: 36px; flex: none;
      border-radius: var(--radius-md); background: var(--primary-bg-subtle); color: var(--primary-base); }
    .ins-org-info { display: flex; flex-direction: column; gap: 1px; min-width: 0; flex: 1; }
    .ins-org-name { font-size: var(--fs-13); font-weight: 600; color: var(--text-strong); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    .ins-org-sub { font-size: var(--fs-12); color: var(--text-sub); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    .ins-org-caret { color: var(--text-soft); flex: none; }
    .ins-org--min { justify-content: center; padding: 6px; border: 0; background: transparent; }
  `],
})
export class SgFeatureInsurance {
  protected readonly preview = inject(ActivatedRoute).snapshot.data['preview'] === true;
  protected readonly shell = inject(InsShellStore);
  private readonly m02 = inject(InsM02Store);
  private readonly m03 = inject(InsM03Store);
  private readonly m04 = inject(InsM04Store);
  private readonly m05 = inject(InsM05Store);
  private readonly m06 = inject(InsM06Store);
  private readonly m07 = inject(InsM07Store);
  private readonly m08 = inject(InsM08Store);

  protected readonly icMax = IconArrowsMaximize; protected readonly icBell = IconBell;
  protected readonly icCollapse = IconLayoutSidebarLeftCollapse; protected readonly icExpand = IconLayoutSidebarLeftExpand;
  protected readonly icSettings = IconSettings; protected readonly icOrg = IconBuilding; protected readonly icCaret = IconSelector;

  protected readonly whenList = [
    'Demo nghiệp vụ BHXH end-to-end cho khách hàng/BA theo đúng PBI rebuild (8 module, 12 màn).',
    'Kiểm chứng UX + state model (vòng đời biến động 9+2, 6 điều kiện vào lô…) trước khi thiết kế API/domain thật.',
  ];

  /** Sidebar 8 mục M01–M08 dựng từ INS_SITEMAP (const — tham chiếu ổn định). */
  protected readonly navSections: HrmNavSection[] = [{
    header: 'Nghiệp vụ BHXH',
    items: INS_SITEMAP.map((m) => ({ key: m.key, label: m.label, icon: m.icon })),
  }];

  /** HrmSideNavUser chuẩn DS: name + email. */
  protected readonly navUser = { name: 'Lê Thị Mai Hương', email: 'maihuong.le@vnr.vn', initials: 'MH' };

  private collapsed = false;
  protected get collapsedModel(): boolean { return this.collapsed; }
  protected set collapsedModel(v: boolean) { this.collapsed = v; }

  protected onNav(item: HrmNavItem): void {
    this.shell.go(item.key as InsModuleKey);
  }

  /** Đặt lại demo: seed 7 store M02–M08 (M01 là computed đọc sống, không cần reset) + shell về mặc định.
   *  M07 reset SAU M05 (dòng theo dõi sinh runtime từ banGiaoChi của M05). */
  protected resetDemo(): void {
    this.m02.resetDemo();
    this.m03.resetDemo();
    this.m04.resetDemo();
    this.m05.resetDemo();
    this.m06.resetDemo();
    this.m07.resetDemo();
    this.m08.resetDemo();
    this.shell.resetDemo();
  }
}
