export interface WsRow extends Record<string, unknown> {
  id: string;
  selectable: boolean;          // nhóm kê khai (🟢🔴🔵) mới có ô chọn; ⚪ Đang tham gia = false
  /* định danh */
  ten: string;
  sub: string;                  // "VNR-015 · Kinh doanh · Giám sát bán hàng"
  insCode: string;              // mã số BHXH ('' khi thiếu → dùng thieuMaBHXH)
  thieuMaBHXH: boolean;
  thieuMaBHXHNote: string;
  suKien: string;
  nguon: string;                // nhãn nguồn (M02 · COR-… / Lô sửa từ … / …)
  trangThaiLabel: string;
  trangThaiTone: string;
  /* nhóm + mã thủ tục (header nhóm: "🟢 Báo tăng (600)") */
  nhom: InsNhomKeKhai;
  nhomLabel: string;
  nhomTone: string;
  thuTuc: string;               // '600' | '600a' | '600b' | '—'
  /* mã phương án */
  paText: string;               // "TM — Tăng mới lao động (v2026.1)" | ''
  paMissing: boolean;           // guard ⑦
  paMissingNote: string;
  /* mức đóng */
  mucDong: string;              // lương căn cứ (chuỗi) | 'không tính được'
  thieuLuong: boolean;
  ngayHLLuong: string;
  /* quỹ (tổ hợp mẫu D02-TS — tham chiếu) */
  quy: string;
  quyMau: boolean;
  cd: boolean;                  // dòng CD — không ảnh hưởng số đóng
  /* số phải đóng (chờ tính 4 tầng — không lưu trên dòng) */
  soPhaiDong: string;           // 'Chờ tính' | 'không tính được'
  soPhaiDongPending: boolean;
  /* guard ⑤ + truy thu */
  thieuD01TS: boolean;
  d01tsNote: string;
  truyThuLabel: string;         // '' | 'Truy thu (NLĐ chịu)' | 'Truy thu (cơ quan chịu)'
  /* dòng sẽ bị bỏ qua khi "Lập tờ khai" (dry-run) — lý do đầu tiên; '' = lập được */
  skipReason: string;
}

/** Nhóm kê khai của 1 dòng (mirror store.nhomCuaItem — deterministic, thuần). CD → Đang tham gia. */
function nhomCua(it: InsLoItem): InsNhomKeKhai {
  if (it.coKhongAnhHuong) return 'dang-tham-gia';
  const code = it.maPhuongAn ?? it.maTrangThaiNV;
  return INS_PHUONGAN_NHOM[code] ?? 'dang-tham-gia';
}

export function buildWsRow(it: InsLoItem): WsRow {
  const nv = insNhanVien(it.nhanVienId);
  const nhom = nhomCua(it);
  const laKeKhai = nhom !== 'dang-tham-gia';
  const thieuMaBHXH = !nv?.insCode || nv.insCode === '—';
  const paMissing = !it.maPhuongAn;                       // guard ⑦
  const thieuD01TS = !!it.truyThu && !it.coD01TS;         // guard ⑤
  const skipReason = paMissing ? GUARD7 : it.thieuLuong ? 'Thiếu lương căn cứ — không tính được số phải đóng.' : thieuD01TS ? GUARD5 : '';
  return {
    id: it.maItem,
    selectable: laKeKhai,
    ten: nv?.name ?? '—',
    sub: `${nv?.code ?? '—'} · ${nv?.dept ?? ''}${nv?.position ? ` · ${nv.position}` : ''}`,
    insCode: thieuMaBHXH ? '' : (nv?.insCode ?? ''),
    thieuMaBHXH,
    thieuMaBHXHNote: WARN_MABHXH,
    suKien: it.refSuKien,
    nguon: it.nhanNguon ?? '—',
    trangThaiLabel: INS_LO_ITEM_LABEL[it.trangThai],
    trangThaiTone: INS_LO_ITEM_TONE[it.trangThai],
    nhom,
    nhomLabel: INS_NHOM_LABEL[nhom],
    nhomTone: INS_NHOM_TONE[nhom],
    thuTuc: INS_NHOM_THUTUC[nhom],
    paText: it.maPhuongAn
      ? `${it.maPhuongAn} — ${it.tenPhuongAn ?? INS_PHUONGAN_LABEL[it.maPhuongAn] ?? ''}${it.phienBanPA ? ` (${it.phienBanPA})` : ''}`
      : '',
    paMissing,
    paMissingNote: GUARD7,
    mucDong: it.thieuLuong ? 'không tính được' : it.luongCanCu,
    thieuLuong: !!it.thieuLuong,
    ngayHLLuong: it.ngayHLLuong,
    quy: laKeKhai ? 'BHXH · BHYT · BHTN · TNLĐ-BNN' : '',
    quyMau: laKeKhai,
    cd: !!it.coKhongAnhHuong,
    soPhaiDong: it.thieuLuong ? 'không tính được' : 'Chờ tính',
    soPhaiDongPending: !it.thieuLuong,
    thieuD01TS,
    d01tsNote: thieuD01TS ? GUARD5 : '',
    truyThuLabel: it.truyThu === 'nld' ? 'Truy thu (NLĐ chịu)' : it.truyThu === 'cqbh' ? 'Truy thu (cơ quan chịu)' : '',
    skipReason,
  };
}

/* ═════════════════════════ Danh sách LÔ — row-VM (LoRow · buildLoRow) ═════════════════════════
 *  m03b-page tự khai cột lưới inline; lo-detail mở lô qua (rowClick). Chỉ giữ VM dùng chung. */

export interface LoRow extends Record<string, unknown> {
  id: string;
  maLo: string;
  soHoSo: string;
  tenLo: string;
  phongBan: string;
  maBHXH: string;
  thamSo: string;               // "D02TS · eBHXH"
  soItem: number;
  soLoi: number;
  trangThaiLabel: string;
  trangThaiTone: string;
  ketQuaLabel: string;          // '' nếu chưa co-ket-qua
  loSua: boolean;
  maLoGoc: string;
  soLanNop: number;             // lô sửa: lần nộp của lô gốc (§4.3)
  lyDoTraLai: string;
  kyLocked: boolean;
  nguoiLap: string;
}

/** `items` = tất cả item HOẶC item của riêng lô (lọc theo loId bên trong → gọi kiểu nào cũng đúng). */
export function buildLoRow(lo: InsLo, items: InsLoItem[] = []): LoRow {
  const own = items.filter((i) => i.loId === lo.maLo);
  return {
    id: lo.maLo,
    maLo: lo.maLo,
    soHoSo: lo.soHoSo,
    tenLo: lo.tenLo,
    phongBan: lo.phongBan,
    maBHXH: lo.maBHXH,
    thamSo: `${INS_BIEUMAU_LABEL[lo.phienBanBieuMau]} · ${INS_KENHNOP_LABEL[lo.kenhNop]}`,
    soItem: own.length,
    soLoi: own.filter((i) => i.ketQuaPreCheck === 'loi').length,
    trangThaiLabel: INS_LO_LABEL[lo.trangThai],
    trangThaiTone: INS_LO_TONE[lo.trangThai],
    ketQuaLabel: lo.ketQuaTongHop ? INS_LO_KETQUA_LABEL[lo.ketQuaTongHop] : '',
    loSua: !!lo.maLoGoc,
    maLoGoc: lo.maLoGoc ?? '',
    soLanNop: lo.soLanNop,
    lyDoTraLai: lo.lyDoTraLai ?? '',
    kyLocked: insKyDaKhoa(lo.ky),
    nguoiLap: lo.nguoiLap,
  };
}

