export interface ItemRow extends Record<string, unknown> {
  id: string;
  ten: string;
  sub: string;
  suKien: string;
  nguon: string;
  paText: string;               // "TM — Tăng mới tham gia (v2026.1)" | ''
  paMissing: boolean;
  cd: boolean;
  luong: string;
  thieuLuong: boolean;
  preLabel: string;             // 'Chưa chạy' khi null
  preTone: string;
  daChapNhanCanhBao: boolean;
  chapNhanBoi: string;          // "Trần Quốc Bảo — lý do…"
  viPham: string[];             // đã format "luongCanCu = 20.500.000 · R-LUONG-021 v3…"
  trangThaiLabel: string;
  trangThaiTone: string;
  canChapNhan: boolean;         // canh-bao chưa chấp nhận → nút (bắt buộc lý do)
  d01ts: string;                // 'Đủ D01-TS' | 'Thiếu D01-TS' | ''
  actions: HrmActionItem[];
}

export function buildItemRow(it: InsLoItem): ItemRow {
  const nv = insNhanVien(it.nhanVienId);
  const pre = it.ketQuaPreCheck;
  return {
    id: it.maItem,
    ten: nv?.name ?? '—',
    sub: `${nv?.code ?? '—'} · ${it.maItem}`,
    suKien: it.refSuKien,
    nguon: it.nhanNguon ?? '—',
    paText: it.maPhuongAn ? `${it.maPhuongAn} — ${it.tenPhuongAn ?? ''}${it.phienBanPA ? ` (${it.phienBanPA})` : ''}` : '',
    paMissing: !it.maPhuongAn,
    cd: !!it.coKhongAnhHuong,
    luong: it.thieuLuong ? 'không tính được' : it.luongCanCu,
    thieuLuong: !!it.thieuLuong,
    preLabel: pre ? INS_PRECHECK_LABEL[pre] : 'Chưa chạy',
    preTone: pre ? INS_PRECHECK_TONE[pre] : 'neutral',
    daChapNhanCanhBao: !!it.canhBaoChapNhan,
    chapNhanBoi: it.canhBaoChapNhan ? `${it.canhBaoChapNhan.nguoi} — ${it.canhBaoChapNhan.lyDo}` : '',
    viPham: it.truongViPham.map((v) => `${v.truong} = ${v.giaTri} · ${v.canCu}`),
    trangThaiLabel: INS_LO_ITEM_LABEL[it.trangThai],
    trangThaiTone: INS_LO_ITEM_TONE[it.trangThai],
    canChapNhan: pre === 'canh-bao' && !it.canhBaoChapNhan,
    d01ts: it.truyThu ? (it.coD01TS ? 'Đủ D01-TS' : 'Thiếu D01-TS') : '',
    actions: [],
  };
}

