import { ChangeDetectionStrategy, Component, TemplateRef, computed, inject, input, signal, viewChild } from '@angular/core';
import { FormsModule } from '@angular/forms';
import {
  HrmDescItem, HrmDescriptions, HrmEmpty, HrmGrid, HrmGridColumn, HrmMessageService,
  HrmModalService, HrmSegmented, HrmSelect, HrmStatusCell, HrmTag, HrmTextarea,
} from 'hrm-ui';
import { InsLayerBadge, InsVarianceCell } from '../_shared';
import { INS_KY, insNhanVien } from '../_data/_core';
import { insFormatVnd } from '../_data/_m02-data';
import {
  InsM04Store, M04_NHOM_THAY_DOI_LABEL, M04_QUYS, M04_SO_SANH_NHOM,
} from '../_data/_m04-data';
import { M04_C12_COLS, M04CompareRow, buildC12Row, compareRow } from './_m04-columns';

/** ═════════ M04 · T2 ĐỐI SOÁT C12-D09 — bản ghi 5 trạng thái + bóc tách A–Đ ═════════
 *  Tệp gốc BẤT BIẾN (tải = ghi audit); fingerprint chống trùng đơn vị+kỳ; bản `Bóc tách lỗi`
 *  → nút "Nhập tay" (modal lý do, đánh dấu nguồn nhập tay); k08 → empty "Chưa nhận C12-TS".
 *  Chip assumption A-07: bộ bóc tách C12 chờ đối chiếu QĐ 366/QĐ-BHXH (chặn thi công pháp lý). */
@Component({
  selector: 'ins-m04-tab-recon',
  imports: [
    FormsModule, HrmDescriptions, HrmEmpty, HrmGrid, HrmStatusCell, HrmTag, HrmTextarea,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="t2-assume">
      <hrm-tag color="orange" variant="lighter">A-07 · Bộ bóc tách C12: chờ đối chiếu QĐ 366/QĐ-BHXH — Cần stakeholder xác nhận</hrm-tag>
    </div>

    @if (rows().length) {
      <hrm-grid [columns]="cols()" [data]="rows()" rowKey="id" density="compact" minWidth="1180px"
        [showPagination]="false" (rowClick)="onRowClick($event)" />

      @if (selRec(); as r) {
        <section class="t2-detail">
          <div class="t2-detail__head">
            <h3 class="t2-detail__title">Bóc tách 5 phần A–Đ — {{ r.mau }} · {{ r.phienBan }}</h3>
            @if (r.nhapTay) { <hrm-tag color="purple" size="sm">Nguồn: nhập tay — {{ r.lyDoNhapTay }}</hrm-tag> }
            @else if (!r.chuaNhan) { <hrm-tag color="green" size="sm" variant="lighter">Nguồn: bóc tách tự động</hrm-tag> }
          </div>
          @if (descItems().length) {
            <hrm-descriptions [items]="descItems()" [column]="1" size="small" [bordered]="true" />
          } @else if (r.lyDoLoi) {
            <p class="t2-loi">{{ r.lyDoLoi }} — chưa có giá trị bóc tách. Dùng "Nhập tay" (lý do bắt buộc, giữ tệp gốc).</p>
          } @else {
            <p class="t2-loi">chưa nhận — không có dữ liệu bóc tách.</p>
          }
        </section>
      }
    } @else {
      <div class="t2-empty"><hrm-empty preset="no-data" description="Chưa nhận C12-TS" /></div>
    }

    <ng-template #stCell let-row>
      <div class="t2-st">
        <hrm-status-cell [status]="$any(row).trangThaiTone" [label]="$any(row).trangThaiLabel" variant="badge" />
        @if ($any(row).nhapTay) { <hrm-tag color="purple" size="sm" variant="lighter">nhập tay</hrm-tag> }
      </div>
    </ng-template>
    <ng-template #tepCell let-row>
      <span class="t2-tep" [class.t2-muted]="$any(row).chuaNhan">{{ $any(row).tepGoc }}</span>
    </ng-template>
    <ng-template #actCell let-row>
      <span class="t2-actrow">
        @if ($any(row).canNhapTay) { <button type="button" class="t2-link" (click)="openNhapTay($any(row).id)">Nhập tay</button> }
        @if ($any(row).canTai) { <button type="button" class="t2-link" (click)="taiTep($any(row).id)">Tải tệp gốc</button> }
      </span>
    </ng-template>

    <ng-template #nhapTayTpl>
      <div class="t2-form">
        <p class="t2-form__hint">Nhập tay giá trị khi bóc tách lỗi — tệp gốc GIỮ NGUYÊN bất biến; giá trị được ĐÁNH DẤU nguồn nhập tay. Lý do bắt buộc.</p>
        <hrm-textarea [(ngModel)]="reasonModel" placeholder="Lý do nhập tay (bắt buộc)…" [minRows]="3" [status]="reasonErr() ? 'error' : ''" />
        @if (reasonErr()) { <span class="t2-form__err">{{ reasonErr() }}</span> }
      </div>
    </ng-template>
  `,
  host: { class: 'ins-m04-tab-recon' },
  styles: [`
    :host { display: flex; flex-direction: column; gap: 12px; min-height: 0; overflow: auto; padding: 12px 2px 24px; }
    .t2-assume { display: flex; }
    .t2-st { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
    .t2-tep { font-size: var(--fs-12); color: var(--text-body); }
    .t2-muted { color: var(--text-soft); }
    .t2-actrow { display: inline-flex; gap: 10px; }
    .t2-link { border: 0; background: none; padding: 0; cursor: pointer; font: inherit; font-size: var(--fs-12); font-weight: 600; color: var(--primary-base); }
    .t2-detail { display: flex; flex-direction: column; gap: 8px; }
    .t2-detail__head { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
    .t2-detail__title { margin: 0; font-size: var(--fs-13); font-weight: 600; color: var(--text-strong); }
    .t2-loi { margin: 0; font-size: var(--fs-12); color: var(--warning-text); }
    .t2-empty { padding: 56px 0; display: flex; justify-content: center; }
    .t2-form { display: flex; flex-direction: column; gap: 8px; }
    .t2-form__hint { margin: 0; font-size: var(--fs-12); color: var(--text-sub); }
    .t2-form__err { font-size: var(--fs-12); color: var(--error-text); }
  `],
})
export class InsM04TabRecon {
  protected readonly store = inject(InsM04Store);
  private readonly msg = inject(HrmMessageService);
  private readonly modal = inject(HrmModalService);

  readonly kyId = input.required<string>();

  private readonly stTpl = viewChild.required<TemplateRef<unknown>>('stCell');
  private readonly tepTpl = viewChild.required<TemplateRef<unknown>>('tepCell');
  private readonly actTpl = viewChild.required<TemplateRef<unknown>>('actCell');
  private readonly nhapTayTplRef = viewChild<TemplateRef<unknown>>('nhapTayTpl');

  protected readonly rows = computed(() =>
    this.store.c12().filter((r) => r.kyId === this.kyId()).map(buildC12Row));
  protected readonly cols = computed<HrmGridColumn[]>(() => {
    const tpl: Record<string, TemplateRef<unknown> | undefined> = {
      trangThai: this.stTpl(), tepGoc: this.tepTpl(), act: this.actTpl(),
    };
    return M04_C12_COLS.map((c) => ({ ...c, cell: tpl[c.key] as HrmGridColumn['cell'] }));
  });

  private readonly selId = signal<string | null>(null);
  protected readonly selRec = computed(() => {
    const rows = this.rows();
    const id = this.selId();
    return (id && rows.find((r) => r.id === id)) || rows[0] || null;
  });
  protected readonly descItems = computed<HrmDescItem[]>(() => {
    const id = this.selRec()?.id;
    const rec = id ? this.store.c12().find((r) => r.id === id) : null;
    if (!rec?.phan) return [];
    return [
      { label: 'Phần A — Lao động', value: rec.phan.a },
      { label: 'Phần B — Quỹ lương', value: rec.phan.b },
      { label: 'Phần C — Phải đóng', value: rec.phan.c },
      { label: 'Phần D — Đã nộp', value: rec.phan.d },
      { label: 'Phần Đ — Chênh lệch/kết dư', value: rec.phan.dd },
    ];
  });

  protected onRowClick(row: Record<string, unknown>): void { this.selId.set(String(row['id'])); }

  protected taiTep(id: string): void {
    const r = this.store.taiTepGoc(id);
    r.ok ? this.msg.success('Đã tải tệp gốc (demo) — lượt tải ghi vào nhật ký.') : this.msg.warning(r.reason ?? '');
  }

  private dlg: { close: () => void } | null = null;
  private readonly nhapTayId = signal('');
  private readonly reasonText = signal('');
  protected get reasonModel(): string { return this.reasonText(); }
  protected set reasonModel(v: string) { this.reasonText.set(v ?? ''); if (v?.trim()) this.reasonErr.set(''); }
  protected readonly reasonErr = signal('');

  protected openNhapTay(id: string): void {
    this.nhapTayId.set(id); this.reasonText.set(''); this.reasonErr.set('');
    this.dlg = this.modal.open({
      title: 'Nhập tay giá trị C12', content: this.nhapTayTplRef()!, width: 460,
      footer: [
        { label: 'Hủy', onClick: () => this.dlg?.close() },
        { label: 'Nhập tay (ghi audit)', type: 'primary', onClick: () => this.confirmNhapTay() },
      ],
    });
  }
  private confirmNhapTay(): void {
    const lyDo = this.reasonText().trim();
    if (!lyDo) { this.reasonErr.set('Lý do là bắt buộc — giá trị sẽ đánh dấu nguồn nhập tay.'); return; }
    const r = this.store.nhapTayC12(this.nhapTayId(), lyDo);
    if (r.ok) { this.msg.success('Đã nhập tay — nguồn giá trị đánh dấu "nhập tay", tệp gốc giữ nguyên.'); this.dlg?.close(); }
    else this.msg.error(r.reason ?? 'Không nhập tay được.');
  }
}

/** ═════════ M04 · T4 SO SÁNH KỲ — 2 kỳ + phiên bản snapshot mỗi kỳ ═════════
 *  4 nhóm chỉ tiêu (lao động / quỹ lương / phải đóng / đã nộp) + 8 nhóm nguyên nhân thay đổi
 *  (bar count) + NLĐ đóng góp lớn nhất; chế độ "so đợt trong tháng" (không tách màn).
 *  Cặp kỳ thiếu snapshot → nhãn ĐÚNG chữ "không tính được" (không số 0 giả). */
@Component({
  selector: 'ins-m04-tab-compare',
  imports: [FormsModule, HrmEmpty, HrmSegmented, HrmSelect, InsLayerBadge, InsVarianceCell],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="t4-pick">
      <span class="t4-pick__lb">Kỳ gốc</span>
      <hrm-select class="t4-pick__ky" [(ngModel)]="gocModel" [options]="kyOptions" size="sm" [allowClear]="false" [showSearch]="false" />
      <hrm-select class="t4-pick__ver" [(ngModel)]="gocVerModel" [options]="gocVerOptions()" size="sm" [allowClear]="false" [showSearch]="false" placeholder="Phiên bản" />
      <span class="t4-pick__vs">so với</span>
      <span class="t4-pick__lb">Kỳ đối chiếu</span>
      <hrm-select class="t4-pick__ky" [(ngModel)]="doiModel" [options]="kyOptions" size="sm" [allowClear]="false" [showSearch]="false" />
      <hrm-select class="t4-pick__ver" [(ngModel)]="doiVerModel" [options]="doiVerOptions()" size="sm" [allowClear]="false" [showSearch]="false" placeholder="Phiên bản" />
      <span class="t4-pick__gap"></span>
      <hrm-segmented [(ngModel)]="cheDoModel" [options]="cheDoOptions" size="sm" />
    </div>

    @if (cheDo() === 'ky') {
      @if (canCompare()) {
        <section class="t4-sec">
          <h3 class="t4-sec__title">4 nhóm chỉ tiêu <ins-layer-badge layer="du-kien" /></h3>
          <table class="t4-table">
            <thead><tr><th>Chỉ tiêu</th><th class="num">{{ gocTitle() }}</th><th class="num">{{ doiTitle() }}</th><th class="num">Chênh lệch</th></tr></thead>
            <tbody>
              @for (r of chiTieuRows(); track r.chiTieu) {
                <tr>
                  <td>{{ r.chiTieu }}</td>
                  <td class="num">{{ r.kyGoc }}</td>
                  <td class="num">{{ r.kyDoiChieu }}</td>
                  <td class="num"><ins-variance-cell [diff]="r.chenh" [tone]="r.tone" /></td>
                </tr>
              }
            </tbody>
          </table>
        </section>

        <section class="t4-sec">
          <h3 class="t4-sec__title">8 nhóm nguyên nhân thay đổi
            <span class="t4-sec__hint">Σ tác động quỹ lương = {{ tongTacDong() }} — khớp chênh chỉ tiêu Quỹ lương</span>
          </h3>
          @if (nhomRows(); as rows) {
            @if (rows.length) {
              <div class="t4-nhom">
                @for (r of rows; track r.nhom) {
                  <div class="t4-nhom__row">
                    <span class="t4-nhom__label">{{ r.label }}</span>
                    <span class="t4-nhom__count" [class.t4-nhom__count--zero]="!r.count">{{ r.count }} người</span>
                    <div class="t4-nhom__barwrap"><div class="t4-nhom__bar" [style.width.%]="r.barPct" [attr.data-tone]="r.tone"></div></div>
                    <span class="t4-nhom__num" [attr.data-tone]="r.tone">{{ r.tacDong }}</span>
                  </div>
                }
              </div>
            } @else {
              <p class="t4-note">không tính được — chưa có dữ liệu phân rã nguyên nhân cho cặp kỳ này.</p>
            }
          }
        </section>

        <section class="t4-sec">
          <h3 class="t4-sec__title">NLĐ đóng góp thay đổi lớn nhất</h3>
          @for (p of topNguoi(); track p.id) {
            <div class="t4-top"><span>{{ p.name }}</span><span class="t4-top__why">{{ p.why }}</span><b [attr.data-tone]="p.tone">{{ p.amount }}</b></div>
          } @empty { <p class="t4-note">không tính được</p> }
        </section>
      } @else {
        <div class="t4-empty">
          <hrm-empty preset="no-data" description="không tính được" />
          <p class="t4-note">{{ compareBlockReason() }}</p>
        </div>
      }
    } @else {
      <!-- chế độ so ĐỢT trong tháng (không tách màn) -->
      <section class="t4-sec">
        <h3 class="t4-sec__title">So đợt trong tháng — {{ doiTitle() }} <ins-layer-badge layer="da-giao-dich" /></h3>
        @if (dotRows().length) {
          <table class="t4-table">
            <thead><tr><th>Đợt</th><th>Ngày</th><th>Trạng thái</th><th class="num">Số tiền</th></tr></thead>
            <tbody>
              @for (r of dotRows(); track r.id) {
                <tr><td>{{ r.dot }}</td><td>{{ r.ngay }}</td><td>{{ r.trangThai }}</td><td class="num">{{ r.soTien }}</td></tr>
              }
              <tr class="t4-table__total"><td colspan="3">Tổng đã nộp các đợt</td><td class="num">{{ dotTong() }}</td></tr>
            </tbody>
          </table>
        } @else { <p class="t4-note">Chưa có chứng từ nộp trong kỳ — không tính được.</p> }
      </section>
    }
  `,
  host: { class: 'ins-m04-tab-compare' },
  styles: [`
    :host { display: flex; flex-direction: column; gap: 14px; min-height: 0; overflow: auto; padding: 12px 2px 24px; }
    .t4-pick { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
    .t4-pick__lb { font-size: var(--fs-12); color: var(--text-sub); }
    .t4-pick__ky { display: inline-block; width: 140px; }
    .t4-pick__ver { display: inline-block; width: 200px; }
    .t4-pick__vs { font-size: var(--fs-12); font-weight: 600; color: var(--text-strong); }
    .t4-pick__gap { flex: 1; }

    .t4-sec { display: flex; flex-direction: column; gap: 8px; }
    .t4-sec__title { margin: 0; font-size: var(--fs-13); font-weight: 600; color: var(--text-strong); display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
    .t4-sec__hint { font-size: var(--fs-11); font-weight: 400; color: var(--text-soft); }

    .t4-table { border-collapse: collapse; width: 100%; max-width: 860px; font-size: var(--fs-13); }
    .t4-table th, .t4-table td { border: 1px solid var(--border-sub); padding: 7px 12px; text-align: left; }
    .t4-table th { background: var(--bg-surface-subtle); font-weight: 600; color: var(--text-sub); font-size: var(--fs-12); }
    .t4-table .num { text-align: right; font-variant-numeric: tabular-nums; }
    .t4-table__total td { font-weight: 700; background: var(--bg-surface-subtle); color: var(--text-strong); }

    .t4-nhom { display: flex; flex-direction: column; gap: 6px; max-width: 860px; }
    .t4-nhom__row { display: flex; align-items: center; gap: 10px; }
    .t4-nhom__label { flex: none; width: 230px; font-size: var(--fs-12); color: var(--text-body); }
    .t4-nhom__count { flex: none; width: 64px; font-size: var(--fs-11); color: var(--text-sub); }
    .t4-nhom__count--zero { color: var(--text-soft); }
    .t4-nhom__barwrap { flex: 1; height: 8px; background: var(--bg-surface-subtle); border-radius: var(--radius-full); overflow: hidden; }
    .t4-nhom__bar { height: 100%; border-radius: var(--radius-full); }
    .t4-nhom__bar[data-tone='up'] { background: var(--error-base); }
    .t4-nhom__bar[data-tone='down'] { background: var(--success-base); }
    .t4-nhom__bar[data-tone='zero'] { background: var(--border-sub); }
    .t4-nhom__num { flex: none; width: 120px; text-align: right; font-variant-numeric: tabular-nums; font-weight: 600; font-size: var(--fs-12); }
    .t4-nhom__num[data-tone='up'] { color: var(--error-base); }
    .t4-nhom__num[data-tone='down'] { color: var(--success-base); }
    .t4-nhom__num[data-tone='zero'] { color: var(--text-soft); }

    .t4-top { display: flex; align-items: baseline; gap: 10px; max-width: 640px; padding: 4px 0; border-bottom: 1px dashed var(--border-sub); font-size: var(--fs-13); }
    .t4-top__why { font-size: var(--fs-12); color: var(--text-sub); }
    .t4-top b { margin-left: auto; font-variant-numeric: tabular-nums; }
    .t4-top b[data-tone='up'] { color: var(--error-base); }
    .t4-top b[data-tone='down'] { color: var(--success-base); }

    .t4-note { margin: 0; font-size: var(--fs-12); color: var(--text-soft); }
    .t4-empty { display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 40px 0; }
  `],
})
export class InsM04TabCompare {
  protected readonly store = inject(InsM04Store);

  /** Kỳ đang chọn trên master — mặc định làm kỳ đối chiếu. */
  readonly kyId = input.required<string>();

  protected readonly kyOptions = INS_KY.map((k) => ({ value: k.id, label: k.label }));
  protected readonly cheDoOptions = [
    { label: 'Kỳ – kỳ', value: 'ky' },
    { label: 'So đợt trong tháng', value: 'dot' },
  ];

  private readonly goc = signal('k06');
  protected get gocModel(): unknown { return this.goc(); }
  protected set gocModel(v: unknown) { this.goc.set(String(v ?? 'k06')); this.gocVer.set(null); }
  private readonly doi = signal<string | null>(null);
  protected get doiModel(): unknown { return this.doi() ?? this.kyId(); }
  protected set doiModel(v: unknown) { this.doi.set(String(v ?? 'k07')); this.doiVer.set(null); }
  protected readonly doiKy = computed(() => this.doi() ?? this.kyId());

  private readonly gocVer = signal<string | null>(null);
  protected get gocVerModel(): unknown { return this.gocSnap()?.id ?? null; }
  protected set gocVerModel(v: unknown) { this.gocVer.set((v as string) || null); }
  private readonly doiVer = signal<string | null>(null);
  protected get doiVerModel(): unknown { return this.doiSnap()?.id ?? null; }
  protected set doiVerModel(v: unknown) { this.doiVer.set((v as string) || null); }

  private readonly cheDoSig = signal<'ky' | 'dot'>('ky');
  protected readonly cheDo = computed(() => this.cheDoSig());
  protected get cheDoModel(): string | number { return this.cheDoSig(); }
  protected set cheDoModel(v: string | number) { this.cheDoSig.set(String(v) as 'ky' | 'dot'); }

  protected readonly gocVerOptions = computed(() =>
    this.store.snapshotsOf(this.goc()).map((s) => ({ value: s.id, label: `v${s.phienBan} — ${s.taiThoiDiem}` })));
  protected readonly doiVerOptions = computed(() =>
    this.store.snapshotsOf(this.doiKy()).map((s) => ({ value: s.id, label: `v${s.phienBan} — ${s.taiThoiDiem}` })));

  private readonly gocSnap = computed(() => {
    const list = this.store.snapshotsOf(this.goc());
    const sel = this.gocVer();
    return (sel && list.find((s) => s.id === sel)) || list[0];
  });
  private readonly doiSnap = computed(() => {
    const list = this.store.snapshotsOf(this.doiKy());
    const sel = this.doiVer();
    return (sel && list.find((s) => s.id === sel)) || list[0];
  });

  protected readonly canCompare = computed(() =>
    !!this.gocSnap() && !!this.doiSnap() && this.goc() !== this.doiKy());
  protected readonly compareBlockReason = computed(() => {
    if (this.goc() === this.doiKy()) return 'Chọn 2 kỳ khác nhau (cùng đơn vị + mã BHXH).';
    if (!this.gocSnap()) return `Kỳ gốc: Chưa có số liệu cho kỳ này (snapshot chưa dựng).`;
    if (!this.doiSnap()) return `Kỳ đối chiếu: Chưa có số liệu cho kỳ này (snapshot chưa dựng).`;
    return '';
  });

  protected readonly gocTitle = computed(() => {
    const s = this.gocSnap();
    return s ? `${INS_KY.find((k) => k.id === this.goc())?.label} · v${s.phienBan}` : '';
  });
  protected readonly doiTitle = computed(() => {
    const s = this.doiSnap();
    return s ? `${INS_KY.find((k) => k.id === this.doiKy())?.label} · v${s.phienBan}` : INS_KY.find((k) => k.id === this.doiKy())?.label ?? '';
  });

  /** 4 nhóm chỉ tiêu: lao động tham gia · quỹ lương · phải đóng · đã nộp. */
  protected readonly chiTieuRows = computed<M04CompareRow[]>(() => {
    const g = this.gocSnap(), d = this.doiSnap();
    if (!g || !d) return [];
    const laoDong = (s: typeof g) => s.dong.filter((x) => x.trangThai !== 'da-loai-khoi-ky').length;
    const phaiDong = (s: typeof g) => M04_QUYS.reduce((x, q) => x + s.funds[q].phaiDong, 0);
    const daDong = (s: typeof g) => M04_QUYS.reduce((x, q) => x + s.funds[q].daDong, 0);
    return [
      compareRow('Lao động tham gia', laoDong(g), laoDong(d), false),
      compareRow('Quỹ lương', g.quyLuong, d.quyLuong),
      compareRow('Phải đóng', phaiDong(g), phaiDong(d)),
      compareRow('Đã nộp', daDong(g), daDong(d)),
    ];
  });

  /** 8 nhóm nguyên nhân — seed chỉ phân rã cho cặp k06→k07 (đảo chiều thì đổi dấu tác động). */
  protected readonly nhomRows = computed(() => {
    const g = this.goc(), d = this.doiKy();
    const forward = g === 'k06' && d === 'k07';
    const backward = g === 'k07' && d === 'k06';
    if (!forward && !backward) return [];
    const sign = forward ? 1 : -1;
    const max = Math.max(...M04_SO_SANH_NHOM.map((r) => Math.abs(r.tacDong)), 1);
    return M04_SO_SANH_NHOM.map((r) => {
      const v = r.tacDong * sign;
      return {
        nhom: r.nhom, label: M04_NHOM_THAY_DOI_LABEL[r.nhom], count: r.count,
        tacDong: r.count ? insFormatVnd(v, true) : '0',
        tone: v > 0 ? 'up' : v < 0 ? 'down' : 'zero',
        barPct: Math.round((Math.abs(v) / max) * 100),
      };
    });
  });
  protected readonly tongTacDong = computed(() => {
    const rows = this.nhomRows();
    if (!rows.length) return 'không tính được';
    const g = this.goc() === 'k06' ? 1 : -1;
    return insFormatVnd(M04_SO_SANH_NHOM.reduce((s, r) => s + r.tacDong, 0) * g, true);
  });

  protected readonly topNguoi = computed(() => {
    const rows = this.nhomRows();
    if (!rows.length) return [];
    const sign = this.goc() === 'k06' ? 1 : -1;
    return M04_SO_SANH_NHOM
      .filter((r) => r.nhanVienIds.length)
      .flatMap((r) => r.nhanVienIds.map((id) => ({ id, why: M04_NHOM_THAY_DOI_LABEL[r.nhom], v: r.tacDong * sign })))
      .sort((a, b) => Math.abs(b.v) - Math.abs(a.v))
      .slice(0, 5)
      .map((p) => ({
        id: p.id, name: insNhanVien(p.id)?.name ?? p.id, why: p.why,
        amount: p.v === 0 ? '±0 (loại khỏi kỳ)' : insFormatVnd(p.v, true),
        tone: p.v > 0 ? 'up' : p.v < 0 ? 'down' : 'zero',
      }));
  });

  /** Chế độ so ĐỢT: các đợt chứng từ nộp của kỳ đối chiếu. */
  protected readonly dotRows = computed(() =>
    this.store.chungTu().filter((c) => c.kyId === this.doiKy()).map((c) => ({
      id: c.id, dot: `Đợt ${c.dot} (${c.thang})`, ngay: c.ngay,
      trangThai: c.trangThai === 'da-ghi-nhan' ? 'Đã ghi nhận (chưa khớp — không cộng)' : c.trangThai === 'da-khop-nghia-vu' ? 'Đã khớp nghĩa vụ' : 'Đã phân bổ theo C12',
      soTien: insFormatVnd(c.soTien), counted: c.trangThai !== 'da-ghi-nhan',
    })));
  protected readonly dotTong = computed(() => {
    const cts = this.store.chungTu().filter((c) => c.kyId === this.doiKy() && c.trangThai !== 'da-ghi-nhan');
    return insFormatVnd(cts.reduce((s, c) => s + c.soTien, 0));
  });
}
