import { ChangeDetectionStrategy, Component, computed, input, signal } from '@angular/core';

/** ins-bulk-bar — thanh bulk action chung mọi queue (M02, M05-A, M06-A, M07-A).
 *  Thể hiện bất biến #4 "bulk = thành công một phần": luôn nói trước
 *  "Đã chọn N · X có thể xử lý · Y bị chặn" + "Xem lý do" (khối expand inline, không overlay).
 *  Nút hành động do màn hình content-project qua <ng-content/>.
 *  Sticky bottom trong container cuộn; tự ẩn khi selected = 0 (khối lý do cũng tự đóng).
 *  Zoneless: `blocked` là array ổn định từ computed phía màn hình. */
export interface InsBulkBlocked {
  reason: string;
  count: number;
}

@Component({
  selector: 'ins-bulk-bar',
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (selected() > 0) {
      <div class="bb">
        <div class="bb-row">
          <span class="bb-sum">
            Đã chọn <b>{{ selected() }}</b>
            <span class="bb-sep">·</span> <b class="bb-ok">{{ eligible() }}</b> có thể xử lý
            @if (blockedCount() > 0) {
              <span class="bb-sep">·</span> <b class="bb-bad">{{ blockedCount() }}</b> bị chặn
            }
          </span>
          @if (blocked().length > 0) {
            <button type="button" class="bb-why" (click)="toggleReasons()">
              {{ showReasons() ? 'Ẩn lý do' : 'Xem lý do' }}
            </button>
          }
          <span class="bb-gap"></span>
          <ng-content />
        </div>
        @if (showReasons() && blocked().length > 0) {
          <div class="bb-reasons">
            @for (b of blocked(); track b.reason) {
              <div class="bb-reason"><span class="bb-count">{{ b.count }}</span><span>{{ b.reason }}</span></div>
            }
          </div>
        }
      </div>
    }
  `,
  host: { class: 'ins-bulk-bar' },
  styles: [`
    :host { display: block; position: sticky; bottom: 12px; z-index: 6; }
    .bb {
      background: var(--bg-surface); border: 1px solid var(--border-sub);
      border-radius: var(--radius-lg); box-shadow: var(--shadow-regular-md, var(--shadow-regular-sm));
      padding: 10px 14px;
    }
    .bb-row { display: flex; align-items: center; gap: 12px; }
    .bb-sum { font-size: var(--fs-13); color: var(--text-sub); }
    .bb-sum b { color: var(--text-strong); font-weight: 600; }
    .bb-sep { color: var(--text-soft); margin: 0 2px; }
    .bb-ok { color: var(--success-base); }
    .bb-bad { color: var(--error-base); }
    .bb-why {
      border: 0; background: none; padding: 0; cursor: pointer;
      color: var(--primary-base); font: inherit; font-size: var(--fs-12); font-weight: 600;
    }
    .bb-gap { flex: 1; }
    .bb-reasons {
      margin-top: 10px; padding-top: 10px; border-top: 1px solid var(--border-sub);
      display: flex; flex-direction: column; gap: 6px;
    }
    .bb-reason { display: flex; align-items: baseline; gap: 8px; font-size: var(--fs-12); color: var(--text-sub); }
    .bb-count {
      flex: none; min-width: 20px; text-align: center; font-weight: 600;
      color: var(--error-text); background: var(--error-bg); border-radius: var(--radius-full); padding: 0 6px;
    }
  `],
})
export class InsBulkBar {
  readonly selected = input.required<number>();
  readonly eligible = input<number>(0);
  readonly blocked = input<InsBulkBlocked[]>([]);

  protected readonly showReasons = signal(false);
  protected readonly blockedCount = computed(() => this.blocked().reduce((s, b) => s + b.count, 0));

  protected toggleReasons(): void { this.showReasons.update((v) => !v); }
}
