/** ═════════ M04 — CONFIG THUẦN (bộ cột + row-VM: format 1 LẦN, template chỉ bind chuỗi) ═════════
 *  Pattern chuẩn D1 (#1): row-VM + cột config tách file — page/tab chỉ map key → TemplateRef. */

export interface M04ColDef {
  key: string;
  title: string;
  width?: string;
  align?: 'left' | 'center' | 'right';
  fixed?: 'left' | 'right';
}

export type M04TabKey = 't1' | 't2' | 't3' | 't4';
export const M04_TAB_LABEL: Record<M04TabKey, string> = {
  t1: 'Snapshot', t2: 'Đối soát C12-D09', t3: 'Chênh lệch', t4: 'So sánh kỳ',
};
export const M04_TABS: M04TabKey[] = ['t1', 't2', 't3', 't4'];

/* ─────────────────────────── T1 — bảng cấp người ─────────────────────────── */

export interface M04DongRow extends Record<string, unknown> {
  id: string;
  ten: string;
  sub: string;
  trangThaiLabel: string;
  trangThaiTone: string;
  luongDong: string;
  phaiDong: string;      // 32% lương (chuỗi sẵn)
  ghiChu: string;
  loaiKhoiKy: boolean;
  readonly_: boolean;    // Đã đóng băng / Đã loại khỏi kỳ → khóa action sửa/loại
}

export function buildDongRow(d: InsDongLaoDongKy, kyLocked: boolean): M04DongRow {
  const nv = insNhanVien(d.nhanVienId);
  const loai = d.trangThai === 'da-loai-khoi-ky';
  return {
    id: d.id,
    ten: nv?.name ?? '—',
    sub: `${nv?.code ?? '—'} · ${nv?.dept ?? ''}`,
    trangThaiLabel: M04_DONG_LABEL[d.trangThai],
    trangThaiTone: M04_DONG_TONE[d.trangThai],
    luongDong: insFormatVnd(d.luongDong),
    phaiDong: loai ? '—' : insFormatVnd(Math.round(d.luongDong * 0.32)),
    ghiChu: d.ghiChu ?? d.lyDo ?? '',
    loaiKhoiKy: loai,
    readonly_: kyLocked || loai || d.trangThai === 'da-dong-bang',
  };
}

export const M04_DONG_COLS: M04ColDef[] = [
  { key: 'ten', title: 'Người lao động', width: '210px' },
  { key: 'trangThai', title: 'Trạng thái dòng', width: '150px' },
  { key: 'luongDong', title: 'Lương đóng', width: '120px', align: 'right' },
  { key: 'phaiDong', title: 'Phải đóng (32%)', width: '130px', align: 'right' },
  { key: 'ghiChu', title: 'Ghi chú / lý do', width: '260px' },
  { key: 'act', title: '', width: '90px', align: 'right', fixed: 'right' },
];

/* ─────────────────────────── T1 — sổ bút toán ─────────────────────────── */

export interface M04ButToanRow extends Record<string, unknown> {
  id: string;
  ngay: string;
  loaiLabel: string;
  giaTri: string;
  giaTriAm: boolean;
  lyDo: string;
  nguoi: string;         // "Lập X · Duyệt Y"
  trangThaiLabel: string;
  trangThaiTone: string;
  refDao: string;
  canGuiDuyet: boolean;
  canDuyet: boolean;
  canDao: boolean;
}

export function buildButToanRow(b: InsButToan, kyLocked: boolean): M04ButToanRow {
  return {
    id: b.id,
    ngay: b.ngay,
    loaiLabel: M04_BT_LOAI_LABEL[b.loai],
    giaTri: insFormatVnd(b.giaTri, true),
    giaTriAm: b.giaTri < 0,
    lyDo: b.lyDo,
    nguoi: `Lập ${b.nguoiLap}${b.nguoiDuyet ? ` · Duyệt ${b.nguoiDuyet}` : ''}`,
    trangThaiLabel: M04_BT_LABEL[b.trangThai],
    trangThaiTone: M04_BT_TONE[b.trangThai],
    refDao: b.refDao ?? '',
    canGuiDuyet: !kyLocked && b.trangThai === 'nhap',
    canDuyet: !kyLocked && b.trangThai === 'cho-duyet',
    canDao: !kyLocked && b.trangThai === 'da-duyet' && b.loai !== 'dao',
  };
}

