/* ─────────────────────────── T1 — chứng từ nộp + đề nghị ─────────────────────────── */

export interface M04ChungTuRow extends Record<string, unknown> {
  id: string;
  ngay: string;
  dotLabel: string;      // "07/2026 · đợt 1 · Toàn đơn vị · BHXH Q. Đống Đa" (chống trùng)
  soTien: string;
  trangThaiLabel: string;
  trangThaiTone: string;
  phanBo: string;        // "BHXH 42.000.000 · BHYT 8.800.000 · …" hoặc "chưa khớp"
  ghiChu: string;
}

export function buildChungTuRow(c: InsChungTuNop): M04ChungTuRow {
  return {
    id: c.id,
    ngay: c.ngay,
    dotLabel: `${c.thang} · đợt ${c.dot} · ${c.phongBan} · ${c.noiDong}`,
    soTien: insFormatVnd(c.soTien),
    trangThaiLabel: M04_CHUNGTU_LABEL[c.trangThai],
    trangThaiTone: M04_CHUNGTU_TONE[c.trangThai],
    phanBo: c.phanBo
      ? M04_QUYS.filter((q) => c.phanBo![q]).map((q) => `${INS_QUY_LABEL[q]} ${insFormatVnd(c.phanBo![q])}`).join(' · ')
      : 'chưa khớp — tính vào chênh lệch',
    ghiChu: c.ghiChu ?? '',
  };
}

