export interface M04DeNghiRow extends Record<string, unknown> {
  id: string;
  tong: string;
  theoQuy: string;
  hanNop: string;
  trangThaiLabel: string;
  trangThaiTone: string;
  nguoi: string;
  ghiChu: string;
  canGuiDuyet: boolean;
  canDuyet: boolean;
  canGuiKeToan: boolean;
  canThuHoi: boolean;
}

export function buildDeNghiRow(d: InsDeNghiThanhToan, kyLocked: boolean): M04DeNghiRow {
  return {
    id: d.id,
    tong: insFormatVnd(d.tong),
    theoQuy: (Object.keys(d.soTheoQuy) as InsQuy[]).map((q) => `${INS_QUY_LABEL[q]} ${insFormatVnd(d.soTheoQuy[q]!)}`).join(' · '),
    hanNop: d.hanNop,
    trangThaiLabel: M04_DENGHI_LABEL[d.trangThai],
    trangThaiTone: M04_DENGHI_TONE[d.trangThai],
    nguoi: `Lập ${d.nguoiLap}${d.nguoiDuyet ? ` · Duyệt ${d.nguoiDuyet}` : ''}`,
    ghiChu: d.lyDoThuHoi ? `Thu hồi: ${d.lyDoThuHoi}` : (d.chungTuRef ? `Chứng từ ${d.chungTuRef}` : d.ghiChu ?? ''),
    canGuiDuyet: !kyLocked && d.trangThai === 'nhap',
    canDuyet: !kyLocked && d.trangThai === 'cho-duyet',
    canGuiKeToan: !kyLocked && d.trangThai === 'da-duyet',
    canThuHoi: !kyLocked && d.trangThai !== 'da-khop' && d.trangThai !== 'da-thu-hoi',
  };
}

/* ─────────────────────────── T2 — bản ghi C12/D09 ─────────────────────────── */

export interface M04C12Row extends Record<string, unknown> {
  id: string;
  mau: string;
  phienBan: string;      // "Lần tiếp nhận 2"
  tepGoc: string;
  fingerprint: string;
  ngayNhan: string;
  trangThaiLabel: string;
  trangThaiTone: string;
  nhapTay: boolean;      // tag nguồn nhập tay
  lyDoNhapTay: string;
  lyDoLoi: string;
  canNhapTay: boolean;
  canTai: boolean;
  chuaNhan: boolean;
}

export function buildC12Row(r: InsBanGhiC12): M04C12Row {
  return {
    id: r.id,
    mau: r.mau,
    phienBan: `Lần tiếp nhận ${r.phienBanTiepNhan}`,
    tepGoc: r.tepGoc,
    fingerprint: r.fingerprint,
    ngayNhan: r.ngayNhan ?? '—',
    trangThaiLabel: M04_C12_LABEL[r.trangThai],
    trangThaiTone: M04_C12_TONE[r.trangThai],
    nhapTay: r.nguonGiaTri === 'nhap-tay',
    lyDoNhapTay: r.lyDoNhapTay ?? '',
    lyDoLoi: r.lyDoLoi ?? '',
    canNhapTay: r.trangThai === 'boc-tach-loi' && r.nguonGiaTri !== 'nhap-tay',
    canTai: r.trangThai !== 'chua-nhan',
    chuaNhan: r.trangThai === 'chua-nhan',
  };
}

