/* ─────────────────────────── T3 — bảng item chênh lệch ─────────────────────────── */

export interface M04ItemRow extends Record<string, unknown> {
  id: string;
  moTa: string;
  nhanhLabel: string;      // "8 · C12/D09 nhận thiếu, bóc tách lỗi hoặc khác mã đơn vị/kỳ"
  giaTri: string;
  giaTriAm: boolean;
  nopThua: boolean;        // giá trị âm phía quỹ → chú thích "nộp thừa"
  trucLabel: string;       // "Trần Quốc Bảo · BHXH · Kỳ 07"
  trangThaiLabel: string;
  trangThaiTone: string;
  reasonOwner: string;     // "RC-03 · Lê Thị Mai Hương"
  ketLuan: string;         // "Sinh yêu cầu điều chỉnh — COR-2026-0051 → M03 · Chờ duyệt chấp nhận"
  maTuongQuan: string;
  /** Kết luận chấp nhận đang chờ duyệt (BQA-17) — hàng nổi bật cho nút "Duyệt chấp nhận". */
  choDuyetChapNhan: boolean;
  readonly_: boolean;      // Đã đóng → chỉ đọc
}

export function buildItemRow(i: InsItemChenhLech, kyLocked: boolean): M04ItemRow {
  const nv = i.trucNhanVienId ? insNhanVien(i.trucNhanVienId) : null;
  const kl = i.ketLuan;
  const phanHe = kl?.phanHeNhan ? kl.phanHeNhan.toUpperCase() : '';
  return {
    id: i.id,
    moTa: i.moTa,
    nhanhLabel: `${i.nhanh} · ${M04_NHANH_LABEL[i.nhanh]}`,
    giaTri: insFormatVnd(i.giaTri, true),
    giaTriAm: i.giaTri < 0,
    nopThua: i.giaTri < 0,
    trucLabel: `${nv?.name ?? 'Chưa gắn NLĐ'} · ${INS_QUY_LABEL[i.trucQuy]} · ${insKy(i.trucKyBiTacDong)?.label ?? i.trucKyBiTacDong}`,
    trangThaiLabel: M04_ITEM_LABEL[i.trangThai],
    trangThaiTone: M04_ITEM_TONE[i.trangThai],
    reasonOwner: i.reasonCode ? `${i.reasonCode}${i.owner ? ` · ${i.owner}` : ''}` : (i.owner ?? ''),
    ketLuan: kl
      ? `${M04_KETLUAN_LABEL[kl.loai]}${kl.maTuongQuan ? ` — ${kl.maTuongQuan}${phanHe ? ` → ${phanHe}` : ''}` : ''}`
        + ` · ${M04_KETLUAN_TT_LABEL[kl.trangThai]}${kl.nguoiDuyet ? ` (duyệt: ${kl.nguoiDuyet})` : ''}`
      : '',
    maTuongQuan: kl?.maTuongQuan ?? '',
    choDuyetChapNhan: kl?.trangThai === 'cho-duyet-chap-nhan',
    readonly_: kyLocked || i.trangThai === 'da-dong',
  };
}

