/* ─────────────────────────── T4 — so sánh kỳ ─────────────────────────── */

/** 1 hàng chỉ tiêu so sánh — chuỗi format sẵn cho ins-variance-cell (_shared). */
export interface M04CompareRow {
  chiTieu: string;
  kyGoc: string;
  kyDoiChieu: string;
  chenh: string;
  tone: 'up' | 'down' | 'zero';
}

export function compareRow(chiTieu: string, goc: number, doiChieu: number, isMoney = true): M04CompareRow {
  const d = doiChieu - goc;
  return {
    chiTieu,
    kyGoc: isMoney ? insFormatVnd(goc) : String(goc),
    kyDoiChieu: isMoney ? insFormatVnd(doiChieu) : String(doiChieu),
    chenh: isMoney ? insFormatVnd(d, true) : (d > 0 ? `+${d}` : String(d)),
    tone: d > 0 ? 'up' : d < 0 ? 'down' : 'zero',
  };
}
