import { ChangeDetectionStrategy, Component, TemplateRef, computed, inject, input, output, signal, viewChild } from '@angular/core';
import { FormsModule } from '@angular/forms';
import {
  HrmAlert, HrmApprovalFlow, HrmApprovalStep, HrmButton, HrmDescItem, HrmDescriptions,
  HrmMessageService, HrmModalService, HrmSegmented, HrmSelect, HrmTag, HrmTextarea, HrmTimeline, HrmTimelineItem,
} from 'hrm-ui';
import { InsLayerBadge, InsSectionLabel } from '../../_shared';
import { InsShellStore } from '../../_data/_core';
import {
  INS_DEXUAT_STATE_LABEL, INS_KETQUA_LO_LABEL, INS_LYDO_DONG_LABEL, InsLyDoDong, InsM05Store,
} from '../../_data/_m05-data';

/** M05-B · B4 Kê khai & nộp — maker-checker 5 VAI (lập → kiểm tra → duyệt → ký → nộp,
 *  hrm-approval-flow) + lô + LẦN NỘP (6 dữ kiện descriptions: payload/phiên bản BM/chữ ký/mã GD/
 *  thời điểm/phản hồi); nộp lại = lần mới GIỮ LINK lần trước; yêu cầu sửa/nộp lại từ M07 →
 *  alert + nút xử lý (case → `Cần bổ sung` → nộp lại). */
@Component({
  selector: 'ins-m05-b4',
  imports: [HrmAlert, HrmApprovalFlow, HrmButton, HrmDescriptions, HrmTag, InsSectionLabel],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (c(); as c) {
      <div class="b4">
        @if (sangB4Reason(); as r) {
          <hrm-alert type="warning" message="Bước B4 đang bị chặn (guard)" [description]="r" />
        }

        @if (c.yeuCauSuaTuM07) {
          <hrm-alert type="error" message="Yêu cầu sửa/nộp lại từ M07" [description]="c.yeuCauSuaTuM07"
            [action]="m07Actions" />
        }
        @if (c.trangThai === 'bi-tu-choi') {
          <hrm-alert type="error" message="Cơ quan BHXH từ chối hồ sơ"
            description="2 đường ra: sửa và NỘP LẠI (lần mới link lần trước; lỗi chứng từ quay về B2) — hoặc Đóng case với lý do 'từ chối — không nộp lại' (B5)."
            [action]="tuChoiActions" />
        }

        <section class="b4__sec">
          <ins-section-label text="Maker–checker 5 vai" tone="muted" />
          @if (c.loB4; as lo) {
            <hrm-approval-flow [steps]="approvalSteps()" />
            <p class="b4__muted">Lô <b>{{ lo.maLo }}</b> · {{ lo.thangLan }} · template bắt buộc: <b>{{ lo.template }}</b> ·
              snapshot chốt tại thời điểm LẬP lô — lô partial + retry.
              <span class="b4__trust" title="OPEN_QUESTION m05.md: kênh nộp + chữ ký số — Cần stakeholder xác nhận">Kênh nộp & chữ ký số: Cần stakeholder xác nhận</span></p>
          } @else {
            <p class="b4__muted">Case chưa vào lô kê khai — tạo/ghép lô khi đủ điều kiện (guard phía trên).</p>
          }
        </section>

        @if (c.loB4; as lo) {
          <section class="b4__sec">
            <ins-section-label text="Lần nộp" tone="muted" [count]="lo.lanNop.length" />
            @for (ln of lo.lanNop; track ln.lan) {
              <div class="b4__lan">
                <div class="b4__lanhead">
                  <hrm-tag color="blue" size="sm">Lần {{ ln.lan }}</hrm-tag>
                  @if (ln.linkLanTruoc) { <hrm-tag color="purple" size="sm" variant="lighter">nộp lại — link lần {{ ln.linkLanTruoc }}</hrm-tag> }
                  <span class="b4__muted">{{ ln.ngayNop }}</span>
                </div>
                <hrm-descriptions [items]="lanNopItems(ln)" [column]="3" size="small" />
              </div>
            } @empty { <p class="b4__muted">Chưa nộp lần nào.</p> }
            @if (lo.ketQuaLo; as kq) {
              <div class="b4__ketqua">
                <span class="b4__muted">Kết quả lô:</span>
                <hrm-tag size="sm" [color]="kq === 'duoc-chap-nhan' ? 'green' : kq === 'bi-tu-choi' ? 'red' : 'orange'">{{ loKetQuaLabel(kq) }}</hrm-tag>
                @for (e of lo.itemLoi ?? []; track e) { <span class="b4__muted">· item lỗi: {{ e }}</span> }
              </div>
            }
          </section>
        }
      </div>

      <ng-template #m07Actions>
        <hrm-button size="sm" variant="primary" (click)="xuLyM07()">Xử lý — sửa & nộp lại</hrm-button>
      </ng-template>
      <ng-template #tuChoiActions>
        <hrm-button size="sm" variant="primary" (click)="nopLai()">Nộp lại (lần mới)</hrm-button>
        <hrm-button size="sm" (click)="goStep.emit(2)">Lỗi chứng từ — về B2</hrm-button>
      </ng-template>
    }
  `,
  host: { class: 'ins-m05-b4' },
  styles: [`
    :host { display: block; }
    .b4 { display: flex; flex-direction: column; gap: 14px; max-width: 980px; }
    .b4__sec { display: flex; flex-direction: column; gap: 8px; border: 1px solid var(--border-sub);
      border-radius: var(--radius-lg); background: var(--bg-surface); padding: 12px 14px; }
    .b4__muted { margin: 0; font-size: var(--fs-12); color: var(--text-sub); }
    .b4__muted b { color: var(--text-strong); }
    .b4__trust { font-size: var(--fs-11); font-weight: 500; color: var(--warning-text); background: var(--warning-bg);
      border: 1px dashed var(--warning-base, var(--warning-text)); border-radius: var(--radius-full); padding: 1px 9px; cursor: help; margin-left: 6px; }
    .b4__lan { display: flex; flex-direction: column; gap: 6px; border: 1px solid var(--border-soft); border-radius: var(--radius-md); padding: 10px 12px; }
    .b4__lanhead { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
    :host ::ng-deep .b4__lanhead .ant-tag, :host ::ng-deep .b4__ketqua .ant-tag { margin: 0; }
    .b4__ketqua { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
  `],
})
export class InsM05B4 {
  private readonly store = inject(InsM05Store);
  private readonly msg = inject(HrmMessageService);

  readonly caseId = input.required<string>();
  /** Điều hướng bước trong case (VD lỗi chứng từ → B2). */
  readonly goStep = output<number>();

  protected readonly c = computed(() => this.store.caseOf(this.caseId()));
  protected readonly sangB4Reason = computed(() => this.store.sangB4Reason(this.caseId()));

  /** Map trạng thái case → 5 bước lập/kiểm tra/duyệt/ký/nộp của hrm-approval-flow. */
  protected readonly approvalSteps = computed<HrmApprovalStep[]>(() => {
    const c = this.c();
    if (!c?.loB4) return [];
    const vai = c.loB4.vai;
    const defs: { title: string; name: string; role: string }[] = [
      { title: 'Lập', name: vai.lap, role: 'Chuyên viên C&B' },
      { title: 'Kiểm tra', name: vai.kiemTra, role: 'Chuyên viên đối soát' },
      { title: 'Duyệt', name: vai.duyet, role: 'Kế toán/duyệt' },
      { title: 'Ký', name: vai.ky, role: 'Người ký số' },
      { title: 'Nộp', name: vai.nop, role: 'Nộp cơ quan BHXH' },
    ];
    // vị trí hiện tại trong chuỗi theo trạng thái case
    const idx = c.trangThai === 'cho-kiem-tra' ? 1 : c.trangThai === 'cho-duyet' ? 2 : c.trangThai === 'cho-ky' ? 3
      : c.trangThai === 'can-bo-sung' || c.trangThai === 'bi-tu-choi' ? 5
      : c.loB4.lanNop.length > 0 || c.trangThai === 'da-nop' ? 5 : 0;
    const rejected = c.trangThai === 'bi-tu-choi' || c.trangThai === 'can-bo-sung';
    return defs.map((d, i) => ({
      ...d,
      state: i < idx ? 'approved' : i === idx ? 'current' : 'waiting',
      stateLabel: i === idx ? (rejected ? 'Cần xử lý lại' : 'Đang chờ') : undefined,
      time: i < idx && c.loB4!.lanNop.length ? (i === 4 ? c.loB4!.lanNop[c.loB4!.lanNop.length - 1].ngayNop : undefined) : undefined,
    } as HrmApprovalStep));
  });

  /** 6 dữ kiện lần nộp — descriptions (payload · phiên bản BM · chữ ký · mã GD · thời điểm · phản hồi). */
  protected lanNopItems(ln: { payload: string; phienBanBM: string; chuKy: string; maGD: string; ngayNop: string; phanHoi: string }): HrmDescItem[] {
    return [
      { label: 'Payload (snapshot)', value: ln.payload },
      { label: 'Phiên bản biểu mẫu', value: ln.phienBanBM },
      { label: 'Chữ ký', value: ln.chuKy },
      { label: 'Mã giao dịch', value: ln.maGD },
      { label: 'Thời điểm nộp', value: ln.ngayNop },
      { label: 'Phản hồi cơ quan', value: ln.phanHoi },
    ];
  }
  protected loKetQuaLabel(k: 'duoc-chap-nhan' | 'bi-tu-choi' | 'chap-nhan-mot-phan'): string { return INS_KETQUA_LO_LABEL[k]; }

  protected xuLyM07(): void {
    this.msg.success('Đã tiếp nhận yêu cầu từ M07 — case ở Cần bổ sung: sửa dữ liệu/chứng từ rồi Nộp lại (lần mới link lần trước).');
  }
  protected nopLai(): void {
    const r = this.store.nopLai(this.caseId());
    r.ok ? this.msg.success('Đã nộp lại — lần mới giữ link lần trước; chờ phản hồi cơ quan.') : this.msg.error(r.reason ?? 'Không nộp lại được.');
  }
}

/** M05-B · B5 Kết quả & bàn giao chi trả — kết quả cơ quan (3 phân loại) + Thanh toán/Đồng bộ
 *  (đồng bộ CHỈ dòng Số tiền BHXH = 0) + Công bố (guard `congBoReason` + Tháng/Lần) + BÀN GIAO CHI
 *  (1 case 1 bản ghi idempotent, correlation sang M07) + trạng thái chi đọc từ M07 (seed tĩnh) +
 *  Đóng case (lý do danh mục 5 giá trị + thông báo NLĐ) + khối Đề xuất biến động (14 ngày, Q78). */
@Component({
  selector: 'ins-m05-b5',
  imports: [
    FormsModule, HrmAlert, HrmButton, HrmDescriptions, HrmSegmented, HrmSelect, HrmTag, HrmTextarea, HrmTimeline,
    InsLayerBadge, InsSectionLabel,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (c(); as c) {
      <div class="b5">
        <!-- Kết quả cơ quan -->
        <section class="b5__sec">
          <ins-section-label text="Kết quả cơ quan BHXH" tone="muted" />
          @if (c.ketQuaCoQuan; as kq) {
            <div class="b5__row">
              <hrm-tag size="sm" [color]="kq === 'duoc-chap-nhan' ? 'green' : kq === 'bi-tu-choi' ? 'red' : 'orange'">{{ kqLabel(kq) }}</hrm-tag>
              @if (c.soTienDuKien) {
                <span class="b5__num">{{ c.soTienDuKien }}</span>
                <!-- BQA-20 (Phase E): số chỉ mang nhãn "Đã giao dịch/chấp nhận" khi cơ quan CHẤP NHẬN;
                     bị từ chối/một phần → vẫn là "Dự kiến nội bộ" (không đội lốt số đã chấp nhận). -->
                <ins-layer-badge [layer]="kq === 'duoc-chap-nhan' ? 'da-giao-dich' : 'du-kien'" />
              }
            </div>
          } @else { <p class="b5__muted">chưa có kết quả</p> }
        </section>

        <!-- Thanh toán / Đồng bộ / Công bố -->
        <section class="b5__sec">
          <ins-section-label text="Thanh toán · Đồng bộ · Công bố" tone="muted" />
          <div class="b5__row">
            <span class="b5__k">Kết quả thanh toán</span>
            @if (c.thanhToan) { <hrm-tag size="sm" [color]="c.thanhToan === 'da' ? 'green' : 'red'">{{ c.thanhToan === 'da' ? 'Đã thanh toán' : 'Không thanh toán' }}</hrm-tag> }
            @else { <span class="b5__muted">chưa có kết quả</span> }
            <span class="b5__trust" title="OPEN_QUESTION m05.md: 2 cột thanh toán sau bàn giao giữ/bỏ — Cần stakeholder xác nhận">2 cột thanh toán: Cần stakeholder xác nhận</span>
          </div>
          <div class="b5__row">
            <span class="b5__k">Đồng bộ sổ phân tích</span>
            <hrm-button size="sm" [disabled]="!dongBoDuoc()" (click)="dongBo()">Đồng bộ</hrm-button>
            <span class="b5__muted">"Đồng bộ" CHỈ chạy dòng Số tiền BHXH = 0/rỗng (LOCK m05.md){{ dongBoDuoc() ? '' : ' — case này đã có số tiền, không thuộc diện.' }}</span>
          </div>
          <div class="b5__row">
            <span class="b5__k">Công bố</span>
            @if (c.daCongBo) {
              <hrm-tag color="green" size="sm">Đã công bố theo {{ c.congBoKieu }}</hrm-tag>
            } @else {
              <hrm-segmented [(ngModel)]="congBoKieuModel" [options]="congBoSegs" size="sm" />
              <hrm-button size="sm" variant="primary" [disabled]="!!congBoReason()" (click)="congBo()">Công bố</hrm-button>
              @if (congBoReason(); as r) { <span class="b5__muted">{{ r }}</span> }
            }
          </div>
        </section>

        <!-- Bàn giao chi (idempotent) + trạng thái chi từ M07 -->
        <section class="b5__sec">
          <ins-section-label text="Bàn giao chi trả (→ M07)" tone="muted" />
          @if (c.banGiaoChi; as bg) {
            <hrm-descriptions [items]="banGiaoItems()" [column]="3" size="small" />
            <p class="b5__muted">1 case 1 bản ghi — chạy lại KHÔNG sinh trùng (idempotent). Ghi chú 2 chiều sang M07 theo <b>{{ bg.correlationId }}</b>.</p>
          } @else {
            <div class="b5__row">
              <hrm-button size="sm" variant="primary" [disabled]="!banGiaoDuoc()" (click)="banGiao()">Bàn giao chi trả</hrm-button>
              <span class="b5__muted">Chỉ bàn giao case Được chấp nhận / Chấp nhận một phần — M05 KHÔNG lập đề nghị thanh toán, KHÔNG xác nhận chi (M07).</span>
            </div>
          }
          <div class="b5__row">
            <span class="b5__k">Trạng thái chi cuối (đọc từ M07)</span>
            @if (c.trangThaiChiM07; as tt) {
              <hrm-tag size="sm" [color]="tt === 'da-chi-tra' ? 'green' : 'red'">{{ tt === 'da-chi-tra' ? 'Đã chi trả' : 'Không chi trả' }}</hrm-tag>
            } @else { <span class="b5__muted">chưa có kết quả từ M07 — điều kiện đóng case</span> }
          </div>
        </section>

        <!-- Đề xuất biến động (quy tắc 14 ngày) -->
        <section class="b5__sec">
          <ins-section-label text="Đề xuất biến động (quy tắc 14 ngày — đi qua M02 Q78)" tone="muted" [count]="deXuatCua().length" />
          @for (d of deXuatCua(); track d.id) {
            <div class="b5__row">
              <hrm-tag size="sm" [color]="d.chieu === 'giam-tam' ? 'red' : 'green'">{{ d.chieu === 'giam-tam' ? 'Giảm tạm' : 'Tăng lại' }}</hrm-tag>
              <span class="b5__strong">{{ d.thangNam }}</span>
              <span class="b5__muted">{{ d.lyDo }}</span>
              <span class="b5__mono">{{ d.correlationId }}</span>
              <hrm-tag color="blue" size="sm" variant="lighter">{{ dxLabel(d.trangThai) }}</hrm-tag>
              <hrm-button size="sm" (click)="goM02(d.correlationId)">Mở hàng đợi M02 ↗</hrm-button>
            </div>
          } @empty {
            <p class="b5__muted">Không có đề xuất — quy tắc: không lương ≥ 14 NGÀY LÀM VIỆC trong tháng → giảm tạm; đi làm lại → tăng lại; xét từng tháng độc lập, mỗi tháng 1 dòng; KHÔNG vào thẳng M03.
              <span class="b5__trust" title="OPEN_QUESTION m05.md: cách đếm 14 ngày + danh sách loại nghỉ — Cần stakeholder xác nhận">Cách đếm 14 ngày: Cần stakeholder xác nhận</span></p>
          }
        </section>

        <!-- Đóng case -->
        <section class="b5__sec">
          <ins-section-label text="Đóng case" tone="muted" />
          @if (c.dongInfo; as d) {
            <p class="b5__muted">Đã đóng bởi <b>{{ d.nguoi }}</b> ({{ d.at }}) — lý do danh mục: <b>{{ dongLabel(d.lyDo) }}</b>@if (d.ghiChu) { · {{ d.ghiChu }}}.</p>
            <p class="b5__muted">Chứng từ về sau khi đóng → tạo case MỚI (không mở lại case này).</p>
          } @else {
            <div class="b5__row">
              <hrm-button size="sm" [danger]="true" [disabled]="!!dongReason()" (click)="openDong()">Đóng case</hrm-button>
              @if (dongReason(); as r) { <span class="b5__muted">{{ r }}</span> }
              @else { <span class="b5__muted">Đóng = lý do danh mục 5 giá trị + thông báo NLĐ + audit.</span> }
            </div>
          }
        </section>

        <!-- Audit của case -->
        <section class="b5__sec">
          <ins-section-label text="Lịch sử thao tác (append-only)" tone="muted" [count]="history().length" />
          @if (history().length) { <hrm-timeline [items]="history()" /> }
          @else { <p class="b5__muted">Chưa có thao tác trong phiên demo.</p> }
        </section>
      </div>

      <!-- Modal đóng case: lý do danh mục 5 giá trị -->
      <ng-template #dongTpl>
        <div class="b5__form">
          <p class="b5__muted">Lý do đóng — danh mục ĐÚNG 5 giá trị (M08); đóng xong gửi thông báo trạng thái cho NLĐ + audit.</p>
          <hrm-select [(ngModel)]="lyDoDongModel" [options]="lyDoDongOptions" placeholder="Chọn lý do danh mục" [allowClear]="false" [showSearch]="false" />
          <hrm-textarea [(ngModel)]="ghiChuModel" placeholder="Ghi chú thêm (tùy chọn)…" [minRows]="2" />
          @if (formError()) { <span class="b5__err">{{ formError() }}</span> }
        </div>
      </ng-template>
    }
  `,
  host: { class: 'ins-m05-b5' },
  styles: [`
    :host { display: block; }
    .b5 { display: flex; flex-direction: column; gap: 14px; max-width: 980px; }
    .b5__sec { display: flex; flex-direction: column; gap: 8px; border: 1px solid var(--border-sub);
      border-radius: var(--radius-lg); background: var(--bg-surface); padding: 12px 14px; }
    .b5__row { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; font-size: var(--fs-13); }
    .b5__k { flex: none; width: 200px; font-size: var(--fs-12); color: var(--text-sub); }
    .b5__num { font-size: var(--fs-16); font-weight: 700; color: var(--text-strong); font-variant-numeric: tabular-nums; }
    .b5__strong { font-weight: 600; color: var(--text-strong); }
    .b5__mono { font-family: var(--font-mono, monospace); font-size: var(--fs-12); color: var(--text-strong); }
    .b5__muted { margin: 0; font-size: var(--fs-12); color: var(--text-sub); }
    .b5__muted b { color: var(--text-strong); }
    .b5__err { font-size: var(--fs-12); color: var(--error-text); }
    .b5__trust { font-size: var(--fs-11); font-weight: 500; color: var(--warning-text); background: var(--warning-bg);
      border: 1px dashed var(--warning-base, var(--warning-text)); border-radius: var(--radius-full); padding: 1px 9px; cursor: help; }
    :host ::ng-deep .b5__row .ant-tag { margin: 0; }
    .b5__form { display: flex; flex-direction: column; gap: 8px; }
  `],
})
export class InsM05B5 {
  private readonly store = inject(InsM05Store);
  private readonly shell = inject(InsShellStore);
  private readonly msg = inject(HrmMessageService);
  private readonly modal = inject(HrmModalService);

  readonly caseId = input.required<string>();
  protected readonly c = computed(() => this.store.caseOf(this.caseId()));
  protected readonly congBoReason = computed(() => this.store.congBoReason(this.caseId()));
  protected readonly dongReason = computed(() => this.store.dongCaseReason(this.caseId()));
  protected readonly deXuatCua = computed(() => this.store.deXuat().filter((d) => d.maCase === this.caseId()));
  protected readonly banGiaoDuoc = computed(() => {
    const s = this.c()?.trangThai;
    return s === 'duoc-chap-nhan' || s === 'chap-nhan-mot-phan';
  });
  protected readonly dongBoDuoc = computed(() => !this.c()?.soTienDuKien);

  protected kqLabel(k: 'duoc-chap-nhan' | 'bi-tu-choi' | 'chap-nhan-mot-phan'): string { return INS_KETQUA_LO_LABEL[k]; }
  protected dxLabel(s: keyof typeof INS_DEXUAT_STATE_LABEL): string { return INS_DEXUAT_STATE_LABEL[s]; }
  protected dongLabel(l: InsLyDoDong): string { return INS_LYDO_DONG_LABEL[l]; }

  protected readonly banGiaoItems = computed<HrmDescItem[]>(() => {
    const bg = this.c()?.banGiaoChi;
    if (!bg) return [];
    return [
      { label: 'Mã hồ sơ', value: bg.maHoSo },
      { label: 'Số ngày', value: String(bg.soNgay) },
      { label: 'Số tiền đề nghị', value: bg.soTienDeNghi },
      { label: 'Số tiền duyệt', value: bg.soTienDuyet },
      { label: 'Tháng/Lần', value: bg.thangLan },
      { label: 'Ngày nộp', value: bg.ngayNop },
      { label: 'Mã tương quan (M07)', value: bg.correlationId },
    ];
  });

  protected readonly history = computed<HrmTimelineItem[]>(() =>
    this.store.audit()
      .filter((e) => e.caseIds.includes(this.caseId()))
      .map((e) => ({
        label: `${e.at} — ${e.hanhDong} (${e.nguoi})${e.lyDo ? ` · lý do: ${e.lyDo}` : ''}`,
        color: e.hanhDong.includes('Đóng') ? 'red' as const : e.hanhDong.includes('Công bố') || e.hanhDong.includes('Bàn giao') ? 'green' as const : 'blue' as const,
      })));

  protected dongBo(): void {
    this.msg.success('Đã đồng bộ dòng Số tiền BHXH = 0/rỗng vào sổ phân tích (idempotent).');
  }

  protected readonly congBoSegs = [{ label: 'Tháng', value: 'Tháng' }, { label: 'Lần', value: 'Lần' }];
  private readonly congBoKieu = signal<'Tháng' | 'Lần'>('Tháng');
  protected get congBoKieuModel(): string | number { return this.congBoKieu(); }
  protected set congBoKieuModel(v: string | number) { this.congBoKieu.set(v === 'Lần' ? 'Lần' : 'Tháng'); }

  protected congBo(): void {
    const r = this.store.congBo(this.caseId(), this.congBoKieu());
    r.ok
      ? this.msg.success(`Đã công bố theo ${this.congBoKieu()} — mail 2 mẫu; thông báo portal gom <Số lượng> + <Nghiệp vụ> + <Trạng thái>.`)
      : this.msg.error(r.reason ?? 'Không công bố được.');
  }

  protected banGiao(): void {
    const r = this.store.banGiaoChi(this.caseId());
    r.ok
      ? this.msg.success(`Đã bàn giao chi trả sang M07 — ${r.correlationId} (1 case 1 bản ghi, idempotent).`)
      : this.msg.error(r.reason ?? 'Không bàn giao được.');
  }

  protected goM02(cor: string): void {
    this.shell.go('m02', { filter: `cor:${cor}` });
  }

  /* modal đóng case */
  private dlg: { close: () => void } | null = null;
  protected readonly formError = signal('');
  protected readonly lyDoDongOptions = (Object.keys(INS_LYDO_DONG_LABEL) as InsLyDoDong[])
    .map((k) => ({ value: k, label: INS_LYDO_DONG_LABEL[k] }));
  private readonly lyDoDong = signal<InsLyDoDong | null>(null);
  protected get lyDoDongModel(): unknown { return this.lyDoDong(); }
  protected set lyDoDongModel(v: unknown) { this.lyDoDong.set((v as InsLyDoDong) || null); if (v) this.formError.set(''); }
  private readonly ghiChu = signal('');
  protected get ghiChuModel(): string { return this.ghiChu(); }
  protected set ghiChuModel(v: string) { this.ghiChu.set(v ?? ''); }
  private readonly dongTplRef = viewChild<TemplateRef<unknown>>('dongTpl');

  protected openDong(): void {
    this.lyDoDong.set(null); this.ghiChu.set(''); this.formError.set('');
    this.dlg = this.modal.open({
      title: 'Đóng case — lý do danh mục', content: this.dongTplRef()!, width: 460,
      footer: [
        { label: 'Hủy', onClick: () => this.dlg?.close() },
        { label: 'Đóng case', type: 'primary', danger: true, onClick: () => {
          const lyDo = this.lyDoDong();
          if (!lyDo) { this.formError.set('Chọn lý do đóng (danh mục 5 giá trị).'); return; }
          const r = this.store.dongCase(this.caseId(), lyDo, this.ghiChu().trim());
          if (!r.ok) { this.formError.set(r.reason ?? 'Không đóng được.'); return; }
          this.msg.success(`Đã đóng case (${INS_LYDO_DONG_LABEL[lyDo]}) — đã gửi thông báo trạng thái cho NLĐ.`);
          this.dlg?.close();
        } },
      ],
    });
  }
}
