import { ChangeDetectionStrategy, Component, computed, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { HrmButton, HrmMessageService, HrmSelect, HrmTag } from 'hrm-ui';
import {
  InsM07KtPhienBan, InsM07Store, M07_KT_THANG, m07KtDiff,
} from '../../_data/_m07-data';

/** Khối "Kiểm tra dữ liệu theo kỳ lương" — BỘ 66 CHỈ TIÊU (quản trị ở M08; hiện 8 tiêu biểu),
 *  cửa sổ 12 THÁNG CỘT ĐỘNG (bảng ngang); mỗi lần chạy = PHIÊN BẢN KẾT QUẢ MỚI (không chạy
 *  song song cùng kỳ); so sánh 2 phiên bản → diff count + danh sách ô lệch. */
@Component({
  selector: 'ins-m07-kiemtra',
  imports: [FormsModule, HrmButton, HrmSelect, HrmTag],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="kt">
      <div class="kt-head">
        <hrm-select class="kt-sel" [(ngModel)]="verModel" [options]="verOptions()" size="sm" [allowClear]="false" [showSearch]="false" />
        <hrm-button size="sm" variant="primary" [disabled]="store.ktDangChay()" (click)="chay()">
          {{ store.ktDangChay() ? 'Đang chạy — không chạy song song cùng kỳ' : 'Chạy kiểm tra (phiên bản mới)' }}</hrm-button>
        <span class="kt-muted">Bộ <b>66 chỉ tiêu</b> (M08) — hiển thị 8 chỉ tiêu tiêu biểu · cửa sổ 12 tháng cột động (09/2025 → 08/2026)</span>
      </div>

      @if (ver(); as v) {
        <div class="kt-meta">
          <hrm-tag size="sm" color="blue">{{ v.id }}</hrm-tag>
          <span class="kt-muted">chạy {{ v.chayLuc }} · {{ v.nguoiChay }} · {{ v.trangThai === 'hoan-tat' ? 'Hoàn tất' : v.trangThai === 'loi' ? 'Lỗi' : 'Hoàn tất một phần' }}</span>
        </div>
        <div class="kt-scroll">
          <table class="kt-table">
            <thead>
              <tr><th class="kt-th kt-th--name">Chỉ tiêu</th>
                @for (t of thang; track t) { <th class="kt-th">{{ t }}</th> }
              </tr>
            </thead>
            <tbody>
              @for (ct of v.chiTieu; track ct.ma) {
                <tr>
                  <td class="kt-td kt-td--name"><b>{{ ct.ma }}</b> {{ ct.ten }}</td>
                  @for (val of ct.thang; track $index) { <td class="kt-td kt-td--num">{{ val }}</td> }
                </tr>
              }
            </tbody>
          </table>
        </div>
        <p class="kt-muted">… 58 chỉ tiêu còn lại quản trị tại M08 (popup chi tiết chỉ tiêu theo tháng — ngoài phạm vi mock).</p>
      }

      <!-- So sánh 2 phiên bản -->
      <div class="kt-cmp">
        <span class="kt-strong">So sánh 2 phiên bản:</span>
        <hrm-select class="kt-sel" [(ngModel)]="cmpAModel" [options]="verOptions()" size="sm" [allowClear]="false" [showSearch]="false" />
        <span class="kt-muted">↔</span>
        <hrm-select class="kt-sel" [(ngModel)]="cmpBModel" [options]="verOptions()" size="sm" [allowClear]="false" [showSearch]="false" />
        @if (diff(); as d) {
          <hrm-tag size="sm" [color]="d.count ? 'orange' : 'green'">{{ d.count }} ô lệch</hrm-tag>
        }
      </div>
      @if (diff(); as d) {
        @if (d.count) {
          <div class="kt-diff">
            @for (x of d.items; track x) { <span class="kt-diff__item">{{ x }}</span> }
          </div>
        }
      }
    </div>
  `,
  host: { class: 'ins-m07-kiemtra' },
  styles: [`
    :host { display: block; }
    .kt { display: flex; flex-direction: column; gap: 10px; }
    .kt-head, .kt-meta, .kt-cmp { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
    .kt-sel { width: 220px; }
    .kt-muted { font-size: var(--fs-12); color: var(--text-sub); }
    .kt-muted b { color: var(--text-strong); }
    .kt-strong { font-size: var(--fs-13); font-weight: 600; color: var(--text-strong); }

    .kt-scroll { overflow-x: auto; border: 1px solid var(--border-sub); border-radius: var(--radius-md); }
    .kt-table { border-collapse: collapse; width: max-content; min-width: 100%; font-size: var(--fs-12); }
    .kt-th {
      position: sticky; top: 0; text-align: right; white-space: nowrap; padding: 6px 10px;
      background: var(--bg-surface-subtle); color: var(--text-sub); font-weight: 600;
      border-bottom: 1px solid var(--border-sub);
    }
    .kt-th--name { text-align: left; min-width: 260px; }
    .kt-td { padding: 5px 10px; border-bottom: 1px solid var(--border-sub); color: var(--text-body); }
    .kt-td--num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
    .kt-td--name b { color: var(--text-strong); margin-right: 4px; }
    .kt-diff { display: flex; flex-direction: column; gap: 3px; }
    .kt-diff__item { font-size: var(--fs-12); color: var(--warning-text); }
  `],
})
export class InsM07KiemTra {
  protected readonly store = inject(InsM07Store);
  private readonly msg = inject(HrmMessageService);

  protected readonly thang = M07_KT_THANG;

  protected readonly verOptions = computed(() => this.store.ktPhienBan().map((v) => ({ value: v.id, label: `${v.id} · ${v.chayLuc}` })));
  private readonly verId = signal('KT-2026-08-v2');
  protected get verModel(): unknown { return this.verId(); }
  protected set verModel(v: unknown) { this.verId.set(String(v ?? '')); }
  protected readonly ver = computed<InsM07KtPhienBan | undefined>(() =>
    this.store.ktPhienBan().find((v) => v.id === this.verId()) ?? this.store.ktPhienBan()[this.store.ktPhienBan().length - 1]);

  private readonly cmpA = signal('KT-2026-08-v1');
  private readonly cmpB = signal('KT-2026-08-v2');
  protected get cmpAModel(): unknown { return this.cmpA(); }
  protected set cmpAModel(v: unknown) { this.cmpA.set(String(v ?? '')); }
  protected get cmpBModel(): unknown { return this.cmpB(); }
  protected set cmpBModel(v: unknown) { this.cmpB.set(String(v ?? '')); }

  protected readonly diff = computed(() => {
    const a = this.store.ktPhienBan().find((v) => v.id === this.cmpA());
    const b = this.store.ktPhienBan().find((v) => v.id === this.cmpB());
    if (!a || !b || a.id === b.id) return null;
    const items: string[] = [];
    a.chiTieu.forEach((ct, i) => ct.thang.forEach((val, j) => {
      const other = b.chiTieu[i]?.thang[j];
      if (val !== other) items.push(`${ct.ma} · tháng ${M07_KT_THANG[j]}: ${val} → ${other}`);
    }));
    return { count: m07KtDiff(a, b), items };
  });

  protected chay(): void {
    const guard = this.store.ktDangChay();
    if (guard) { this.msg.warning('Đang có lần chạy cùng kỳ — không chạy song song.'); return; }
    this.store.ktDangChay.set(true);
    setTimeout(() => {
      const r = this.store.chayKiemTra();
      this.store.ktDangChay.set(false);
      if (r.ok && r.id) {
        this.verId.set(r.id);
        this.cmpA.set(this.store.ktPhienBan()[this.store.ktPhienBan().length - 2]?.id ?? 'KT-2026-08-v1');
        this.cmpB.set(r.id);
        this.msg.success(`Hoàn tất — phiên bản kết quả MỚI ${r.id} (so sánh với bản trước ngay bên dưới).`);
      } else this.msg.error(r.reason ?? 'Không chạy được.');
    }, 900);
  }
}
