import { ChangeDetectionStrategy, Component, computed, effect, inject, input, output, signal } from '@angular/core';
import { IconArrowLeft } from '@tabler/icons-angular';
import { TablerIconComponent } from '@tabler/icons-angular';
import { HrmAlert, HrmMessageService, HrmStatusCell, HrmTag } from 'hrm-ui';
import { InsLayerBadge, InsSlaChip } from '../../_shared';
import { insNhanVien } from '../../_data/_core';
import { insSlaView } from '../../_data/_m02-data';
import {
  INS_CASE_NHOM_LABEL, INS_CASE_STATE_LABEL, INS_CASE_STATE_TONE, INS_LYDO_DONG_LABEL,
  InsM05Store, M05Step, m05StepOfState,
} from '../../_data/_m05-data';
import { InsM05B1 } from './m05-b1';
import { InsM05B2 } from './m05-b2';
import { InsM05B3 } from './m05-b3';
import { InsM05B4, InsM05B5 } from './m05-b45';

/** ═════════ M05-B — CHI TIẾT CASE CHẾ ĐỘ (archetype Case Progress Workspace, Phase D3) ═════════
 *  IA_LOCK m05.md: stepper CỐ ĐỊNH B1 Tiếp nhận → B2 Điều kiện & chứng từ → B3 Tính & giải thích
 *  → B4 Kê khai & nộp → B5 Kết quả & bàn giao chi trả. Mở từ A định vị ĐÚNG BƯỚC theo trạng thái;
 *  bước trước xem lại tự do, bước sau KHÓA kèm lý do (guard-pair store). Case header THƯỜNG TRỰC
 *  (sticky): NLĐ + loại chế độ + mã case + trạng thái + SLA + số tiền hiện hành (nhãn lớp) +
 *  cảnh báo; thanh 3 mốc (phát sinh/hiệu lực/hạn xử lý). Case `Đóng` = banner CHỈ ĐỌC mọi bước;
 *  sửa = case/phiên bản mới link ngược. Step-rail giàu copy pattern `m03-page` (D2). */
@Component({
  selector: 'ins-m05-case',
  imports: [
    TablerIconComponent, HrmAlert, HrmStatusCell, HrmTag, InsLayerBadge, InsSlaChip,
    InsM05B1, InsM05B2, InsM05B3, InsM05B4, InsM05B5,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (c(); as c) {
      <!-- ═════ Case header thường trực (sticky) ═════ -->
      <div class="cs-head">
        <button type="button" class="cs-back" (click)="back.emit()" title="Về hàng đợi — giữ tab/bộ lọc">
          <tabler-icon [icon]="icBack" [size]="15" /> Hàng đợi</button>
        <div class="cs-id">
          <span class="cs-name">{{ nvView() }}</span>
          <span class="cs-meta"><span class="cs-mono">{{ c.maCase }}</span> · {{ nhomLabel() }} — {{ c.loaiCheDo }}</span>
        </div>
        <hrm-status-cell [status]="$any(tone())" [label]="stateLabel()" variant="badge" />
        <ins-sla-chip [label]="sla().label" [tone]="sla().tone" />
        @if (c.soTienDuKien) {
          <span class="cs-money">{{ c.soTienDuKien }} <ins-layer-badge layer="du-kien" /></span>
        } @else { <span class="cs-muted">chưa có kết quả</span> }
        @if (canhBao(); as w) { <hrm-tag color="orange" size="sm">{{ w }}</hrm-tag> }
        <span class="cs-gap"></span>
        <span class="cs-mocs">
          <span>Phát sinh <b>{{ c.ngayPhatSinh }}</b></span>
          <span>Hiệu lực <b>{{ c.ngayHieuLuc }}</b></span>
          <span>Hạn xử lý <b>{{ c.ngayHanXuLy || '—' }}</b></span>
        </span>
      </div>

      @if (closed()) {
        <hrm-alert class="cs-closed" type="warning" [message]="'Case đã ĐÓNG — lý do: ' + dongLabel() + '. Toàn màn CHỈ ĐỌC.'"
          description="Sửa sau đóng = tạo case/phiên bản mới link ngược case này; chứng từ về sau khi đóng → tạo case MỚI." />
      }

      <!-- ═════ Step-rail B1–B5 (status + count + blocker; bước sau khóa kèm lý do) ═════ -->
      <nav class="cs-rail" aria-label="Vòng đời case B1–B5">
        @for (b of buocViews(); track b.key; let i = $index) {
          <button type="button" class="cs-step" [class.cs-step--active]="step() === b.key"
            [class.cs-step--locked]="!!b.lockReason"
            [attr.aria-current]="step() === b.key ? 'step' : null" (click)="goStep(b)">
            <span class="cs-step__idx" [attr.data-status]="b.status">{{ b.key }}</span>
            <span class="cs-step__body">
              <span class="cs-step__label">{{ b.label }}</span>
              <span class="cs-step__status" [attr.data-status]="b.status">{{ statusLabel(b.status) }}</span>
              <span class="cs-step__count">{{ b.count }}</span>
              @if (b.blocker) { <span class="cs-step__blocker">{{ b.blocker }}</span> }
              @if (b.lockReason) { <span class="cs-step__lock">🔒 {{ b.lockReason }}</span> }
            </span>
          </button>
          @if (i < 4) { <span class="cs-rail__sep" aria-hidden="true"></span> }
        }
      </nav>

      <!-- ═════ Thân bước ═════ -->
      <div class="cs-body" [class.cs-body--readonly]="closed()">
        @switch (step()) {
          @case (1) { <ins-m05-b1 [caseId]="caseId()" /> }
          @case (2) { <ins-m05-b2 [caseId]="caseId()" /> }
          @case (3) { <ins-m05-b3 [caseId]="caseId()" /> }
          @case (4) { <ins-m05-b4 [caseId]="caseId()" (goStep)="setStep($event)" /> }
          @case (5) { <ins-m05-b5 [caseId]="caseId()" /> }
        }
      </div>
    } @else {
      <p class="cs-muted cs-nf">Không tìm thấy case.</p>
    }
  `,
  host: { class: 'ins-m05-case' },
  styles: [`
    :host { display: flex; flex-direction: column; flex: 1 1 auto; min-height: 0; padding: 0 20px; }

    .cs-head {
      position: sticky; top: 0; z-index: 7; flex: none;
      display: flex; align-items: center; gap: 10px; flex-wrap: wrap;
      background: var(--bg-body); border-bottom: 1px solid var(--border-sub); padding: 10px 0 8px;
    }
    .cs-back {
      display: inline-flex; align-items: center; gap: 5px; cursor: pointer; font: inherit;
      font-size: var(--fs-12); font-weight: 600; color: var(--primary-base);
      border: 1px solid var(--border-sub); border-radius: var(--radius-md); background: var(--bg-surface); padding: 4px 10px;
    }
    .cs-back:hover { border-color: var(--primary-base); }
    .cs-id { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
    .cs-name { font-size: var(--fs-14); font-weight: 600; color: var(--text-strong); white-space: nowrap; }
    .cs-meta { font-size: var(--fs-12); color: var(--text-sub); white-space: nowrap; }
    .cs-mono { font-family: var(--font-mono, monospace); font-weight: 600; color: var(--text-strong); }
    .cs-money { display: inline-flex; align-items: center; gap: 6px; font-size: var(--fs-14); font-weight: 700; color: var(--text-strong); font-variant-numeric: tabular-nums; }
    .cs-muted { font-size: var(--fs-12); color: var(--text-sub); }
    .cs-nf { padding: 24px 0; }
    .cs-gap { flex: 1; }
    .cs-mocs { display: flex; gap: 12px; font-size: var(--fs-12); color: var(--text-sub); white-space: nowrap; }
    .cs-mocs b { color: var(--text-strong); }
    .cs-closed { display: block; margin-top: 8px; }

    /* step-rail — copy pattern .m03-step (D2) */
    .cs-rail { flex: none; display: flex; align-items: stretch; gap: 8px; padding: 8px 0 10px; border-bottom: 1px solid var(--border-sub); overflow-x: auto; }
    .cs-step { display: flex; align-items: flex-start; gap: 9px; flex: 1 1 0; min-width: 190px; text-align: left;
      border: 1px solid var(--border-soft); border-radius: var(--radius-lg); background: var(--bg-surface);
      padding: 8px 12px; cursor: pointer; font: inherit; }
    .cs-step:hover { border-color: var(--border-input); }
    .cs-step--active { border-color: var(--primary-base); box-shadow: 0 0 0 1px var(--primary-base); }
    .cs-step--locked { opacity: .72; cursor: not-allowed; }
    .cs-step__idx { flex: none; width: 24px; height: 24px; display: grid; place-items: center; margin-top: 1px;
      border-radius: var(--radius-full); font-size: var(--fs-12); font-weight: 600;
      border: 1.5px solid var(--border-input); color: var(--text-sub); background: var(--bg-surface); }
    .cs-step__idx[data-status='dang-xu-ly'] { border-color: var(--primary-base); color: var(--primary-base); }
    .cs-step__idx[data-status='co-loi'] { border-color: var(--error-base); color: var(--error-text); background: var(--error-bg); }
    .cs-step__idx[data-status='hoan-tat'] { border-color: var(--success-base); color: var(--success-text); background: var(--success-bg); }
    .cs-step__body { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
    .cs-step__label { font-size: var(--fs-13); font-weight: 600; color: var(--text-strong); white-space: nowrap; }
    .cs-step__status { font-size: var(--fs-11); font-weight: 600; }
    .cs-step__status[data-status='chua-bat-dau'] { color: var(--text-soft); }
    .cs-step__status[data-status='dang-xu-ly'] { color: var(--primary-base); }
    .cs-step__status[data-status='co-loi'] { color: var(--error-text); }
    .cs-step__status[data-status='hoan-tat'] { color: var(--success-text); }
    .cs-step__count { font-size: var(--fs-12); color: var(--text-sub); }
    .cs-step__blocker { font-size: var(--fs-11); color: var(--error-text); }
    .cs-step__lock { font-size: var(--fs-11); color: var(--text-soft); }
    .cs-rail__sep { flex: none; width: 14px; align-self: center; height: 1.5px; background: var(--border-sub); border-radius: 1px; }

    .cs-body { flex: 1 1 auto; min-height: 0; padding: 12px 0 16px; overflow: auto; }
    /* Case Đóng → CHỈ ĐỌC mọi bước: khóa pointer vùng thân (xem/cuộn vẫn được). */
    .cs-body--readonly :is(button, input, textarea, .ant-select, .ant-segmented) { pointer-events: none; opacity: .82; }
  `],
})
export class InsM05Case {
  protected readonly store = inject(InsM05Store);
  private readonly msg = inject(HrmMessageService);

  readonly caseId = input.required<string>();
  /** Bước yêu cầu khi mở từ A ("Đi sâu" mang caseId + bước). */
  readonly initialStep = input<number>(0);
  readonly back = output<void>();

  protected readonly icBack = IconArrowLeft;

  protected readonly c = computed(() => this.store.caseOf(this.caseId()));
  protected readonly closed = computed(() => this.c()?.trangThai === 'dong');
  protected readonly buocViews = computed(() => this.store.buocViewsOf(this.caseId()));

  protected readonly step = signal<M05Step>(1);

  /** Chỉ định vị 1 LẦN khi mở (đổi caseId = định vị lại) — không reset khi store thay đổi. */
  private positionedFor: string | null = null;

  constructor() {
    // Định vị đúng bước theo trạng thái khi mở (hoặc theo bước yêu cầu từ A — "Đi sâu" mang caseId + bước).
    effect(() => {
      const c = this.c();
      if (!c || this.positionedFor === c.maCase) return;
      this.positionedFor = c.maCase;
      const req = this.initialStep();
      this.step.set((req >= 1 && req <= 5 ? req : m05StepOfState(c.trangThai)) as M05Step);
    });
  }

  protected setStep(s: number): void { this.step.set(s as M05Step); }
  protected goStep(b: { key: M05Step; lockReason: string | null }): void {
    // đi lui tự do; bước sau khóa kèm LÝ DO (guard-pair) — bấm vào hiện lý do, không nhảy.
    if (b.lockReason && b.key > this.step()) { this.msg.warning(b.lockReason); return; }
    this.step.set(b.key);
  }

  protected readonly stateLabel = computed(() => {
    const c = this.c();
    return c ? INS_CASE_STATE_LABEL[c.trangThai] : '';
  });
  protected readonly tone = computed(() => {
    const c = this.c();
    return c ? INS_CASE_STATE_TONE[c.trangThai] : 'neutral';
  });
  protected readonly nhomLabel = computed(() => {
    const c = this.c();
    return c ? INS_CASE_NHOM_LABEL[c.nhom] : '';
  });
  protected readonly sla = computed(() => insSlaView(this.c() ?? { coHan: null, ngayHanXuLy: '' }));
  protected readonly nvView = computed(() => {
    const c = this.c();
    const nv = c ? insNhanVien(c.nhanVienId) : undefined;
    return nv ? `${nv.name} (${nv.code})` : '—';
  });
  /** Cảnh báo quan trọng trên header: chặn > thiếu chứng từ > exception. */
  protected readonly canhBao = computed(() => {
    const c = this.c();
    if (!c) return '';
    const chan = c.viPham.filter((v) => v.mucDo === 'chan' && !v.daOverride).length;
    if (chan) return `${chan} vi phạm mức chặn`;
    const thieu = c.checklist.filter((k) => k.batBuoc && k.trangThai === 'thieu').length;
    if (thieu) return `${thieu} chứng từ bắt buộc thiếu`;
    if (c.exceptionDong && (c.exceptionDong.trangThai === 'moi' || c.exceptionDong.trangThai === 'dang-xu-ly')) return 'exception dữ liệu đóng mở';
    if (c.yeuCauSuaTuM07) return 'M07 yêu cầu sửa/nộp lại';
    return '';
  });
  protected readonly dongLabel = computed(() => {
    const d = this.c()?.dongInfo;
    return d ? INS_LYDO_DONG_LABEL[d.lyDo] : '';
  });

  protected statusLabel(s: 'chua-bat-dau' | 'dang-xu-ly' | 'co-loi' | 'hoan-tat'): string {
    return s === 'chua-bat-dau' ? 'Chưa bắt đầu' : s === 'dang-xu-ly' ? 'Đang xử lý' : s === 'co-loi' ? 'Có lỗi cần xử lý' : 'Đã hoàn tất';
  }
}
